def solution(A):
    n = len(A)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        if i >= 3 and A[i - 3] + A[i - 2] + A[i - 1] == 0:
            dp[i] = max(dp[i], dp[i - 3] + 1)
    return dp[n]

