def solution(events):
    coins = 0
    won = 0
    for c in events:
        if c == 'i':
            coins += 1
        elif c == 'd':
            if coins > 0:
                coins -= 1
        elif c == 'w':
            won += coins
            coins = 0
    return won

class Solution {
    public static int solution(String events) {
        int coins = 0, won = 0;
        for (char c : events.toCharArray()) {
            if (c == 'i') coins++;
            else if (c == 'd') { if (coins > 0) coins--; }
            else if (c == 'w') { won += coins; coins = 0; }
        }
        return won;
    }
}

