def solution(board):
    n = len(board)
    total = 0
    for r in range(3):
        positions = [p for p in range(r, n, 3)]
        coin = [board[p] == 'C' for p in positions]
        tokens_idx = [i for i, p in enumerate(positions) if board[p] == 'T']
        if not tokens_idx:
            continue
        k = len(tokens_idx)
        P = len(positions)
        NEG = -10 ** 9
        dp = [[NEG] * P for _ in range(k + 1)]
        for i in range(P):
            dp[0][i] = 0
        for j in range(1, k + 1):
            best_prev = NEG
            start_i = tokens_idx[j - 1]
            for i in range(P):
                if i > 0:
                    best_prev = max(best_prev, dp[j - 1][i - 1])
                if i >= start_i and best_prev != NEG:
                    dp[j][i] = best_prev + (1 if coin[i] else 0)
        best = 0
        for i in range(P):
            best = max(best, dp[k][i])
        total += best
    return total

import java.util.*;

class Solution {
    public static int solution(String board) {
        int n = board.length();
        int total = 0;
        for (int r = 0; r < 3; r++) {
            List<Integer> positions = new ArrayList<>();
            for (int p = r; p < n; p += 3) positions.add(p);
            int P = positions.size();
            boolean[] coin = new boolean[P];
            List<Integer> tokenIdx = new ArrayList<>();
            for (int i = 0; i < P; i++) {
                char c = board.charAt(positions.get(i));
                if (c == 'C') coin[i] = true;
                if (c == 'T') tokenIdx.add(i);
            }
            if (tokenIdx.isEmpty()) continue;
            int k = tokenIdx.size();
            int NEG = Integer.MIN_VALUE / 2;
            int[][] dp = new int[k + 1][P];
            for (int j = 0; j <= k; j++) Arrays.fill(dp[j], NEG);
            for (int i = 0; i < P; i++) dp[0][i] = 0;
            for (int j = 1; j <= k; j++) {
                int bestPrev = NEG;
                int startI = tokenIdx.get(j - 1);
                for (int i = 0; i < P; i++) {
                    if (i > 0) bestPrev = Math.max(bestPrev, dp[j - 1][i - 1]);
                    if (i >= startI && bestPrev != NEG) {
                        dp[j][i] = bestPrev + (coin[i] ? 1 : 0);
                    }
                }
            }
            int best = 0;
            for (int i = 0; i < P; i++) best = Math.max(best, dp[k][i]);
            total += best;
        }
        return total;
    }
}

