def solution(numbers):
    cnt = [0] * 10
    for v in numbers:
        d1, d2 = v // 10, v % 10
        if d1 == d2:
            cnt[d1] += 1
        else:
            cnt[d1] += 1
            cnt[d2] += 1
    return max(cnt)

class Solution {
    public static int solution(int[] numbers) {
        int[] cnt = new int[10];
        for (int v : numbers) {
            int d1 = v / 10, d2 = v % 10;
            if (d1 == d2) cnt[d1]++;
            else { cnt[d1]++; cnt[d2]++; }
        }
        int best = 0;
        for (int c : cnt) best = Math.max(best, c);
        return best;
    }
}

