from collections import defaultdict, deque

def divideTreeNodes(n, values, edges):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v); g[v].append(u)
    color = [-1] * (n + 1)
    color[1] = 0
    q = deque([1])
    while q:
        u = q.popleft()
        for v in g[u]:
            if color[v] == -1:
                color[v] = color[u] ^ 1
                q.append(v)
    INF = float('inf')
    mn = [INF, INF]; mx = [-INF, -INF]
    for i in range(1, n + 1):
        c = color[i]
        mn[c] = min(mn[c], values[i - 1])
        mx[c] = max(mx[c], values[i - 1])
    return (mx[0] - mn[0]) + (mx[1] - mn[1])

import java.util.*;
class Solution {
    public long divideTreeNodes(int n, int[] values, int[][] edges) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] color = new int[n + 1];
        Arrays.fill(color, -1);
        color[1] = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(1);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (color[v] == -1) { color[v] = color[u] ^ 1; q.add(v); }
        }
        long[] mn = {Long.MAX_VALUE, Long.MAX_VALUE}, mx = {Long.MIN_VALUE, Long.MIN_VALUE};
        for (int i = 1; i <= n; i++) {
            int c = color[i];
            mn[c] = Math.min(mn[c], values[i - 1]);
            mx[c] = Math.max(mx[c], values[i - 1]);
        }
        return (mx[0] - mn[0]) + (mx[1] - mn[1]);
    }
}

