import heapq

def assignLocker(clients):
    free = []
    next_id = 1
    assigned = {}
    last = -1
    for c in clients:
        if c in assigned:
            heapq.heappush(free, assigned.pop(c))
        else:
            if free:
                lid = heapq.heappop(free)
            else:
                lid = next_id; next_id += 1
            assigned[c] = lid
            last = lid
    return last

import java.util.*;
class Solution {
    public int assignLocker(String[] clients) {
        PriorityQueue<Integer> free = new PriorityQueue<>();
        Map<String, Integer> assigned = new HashMap<>();
        int next = 1, last = -1;
        for (String c : clients) {
            if (assigned.containsKey(c)) {
                free.offer(assigned.remove(c));
            } else {
                int lid = free.isEmpty() ? next++ : free.poll();
                assigned.put(c, lid);
                last = lid;
            }
        }
        return last;
    }
}

