using namespace std;
class Solution {
public:
    int assignLocker(vector<string>& clients) {
        priority_queue<int, vector<int>, greater<int>> free;
        unordered_map<string, int> assigned;
        int next = 1, last = -1;
        for (auto& c : clients) {
            auto it = assigned.find(c);
            if (it != assigned.end()) {
                free.push(it->second);
                assigned.erase(it);
            } else {
                int lid;
                if (free.empty()) lid = next++;
                else { lid = free.top(); free.pop(); }
                assigned[c] = lid;
                last = lid;
            }
        }
        return last;
    }
};

def biggestNumberFromDigits(digits):
    n = len(digits)
    best = 0
    # 选 1、2、3 位的情况都试
    for k in (1, 2, 3):
        if n < k: continue
        if k == 1:
            best = max(best, max(digits))
        elif k == 2:
            for i in range(n - 1):
                for j in range(i + 1, n):
                    v = digits[i] * 10 + digits[j]
                    if v >= 10 and v > best:
                        best = v
        else:
            for i in range(n - 2):
                for j in range(i + 1, n - 1):
                    for l in range(j + 1, n):
                        v = digits[i] * 100 + digits[j] * 10 + digits[l]
                        if v >= 100 and v > best:
                            best = v
    return best

class Solution {
    public int biggestNumberFromDigits(int[] digits) {
        int n = digits.length, best = 0;
        for (int d : digits) best = Math.max(best, d);
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n; j++) {
                int v = digits[i] * 10 + digits[j];
                if (v >= 10) best = Math.max(best, v);
            }
        for (int i = 0; i < n - 2; i++)
            for (int j = i + 1; j < n - 1; j++)
                for (int k = j + 1; k < n; k++) {
                    int v = digits[i] * 100 + digits[j] * 10 + digits[k];
                    if (v >= 100) best = Math.max(best, v);
                }
        return best;
    }
}

