def buildMaxFromSubarray(nums, k):
    n = len(nums)
    stack = []
    for i, v in enumerate(nums):
        while stack and stack[-1] < v and len(stack) - 1 + (n - i) >= k:
            stack.pop()
        if len(stack) < k:
            stack.append(v)
    return int(''.join(map(str, stack)))

class Solution {
    public long buildMaxFromSubarray(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && stack[top - 1] < nums[i] && (top - 1) + (n - i) >= k) top--;
            if (top < k) stack[top++] = nums[i];
        }
        long ans = 0;
        for (int i = 0; i < k; i++) ans = ans * 10 + stack[i];
        return ans;
    }
}

