    long long buildMaxFromSubarray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> stk;
        for (int i = 0; i < n; i++) {
            while (!stk.empty() && stk.back() < nums[i] && (int)stk.size() - 1 + (n - i) >= k) stk.pop_back();
            if ((int)stk.size() < k) stk.push_back(nums[i]);
        }
        long long ans = 0;
        for (int v : stk) ans = ans * 10 + v;
        return ans;
    }
};

def minSatellites(targetRegions, satellites):
    used = [False] * len(satellites)
    count = 0
    for ts, te in targetRegions:
        best = -1; best_end = float('inf')
        for i, (cs, ce) in enumerate(satellites):
            if not used[i] and cs <= ts and ce >= te and ce < best_end:
                best = i; best_end = ce
        if best == -1:
            return -1
        used[best] = True
        count += 1
    return count

class Solution {
    public int minSatellites(int[][] targetRegions, int[][] satellites) {
        boolean[] used = new boolean[satellites.length];
        int count = 0;
        for (int[] t : targetRegions) {
            int best = -1, bestEnd = Integer.MAX_VALUE;
            for (int i = 0; i < satellites.length; i++) {
                if (!used[i] && satellites[i][0] <= t[0] && satellites[i][1] >= t[1] && satellites[i][1] < bestEnd) {
                    best = i; bestEnd = satellites[i][1];
                }
            }
            if (best == -1) return -1;
            used[best] = true; count++;
        }
        return count;
    }
}

