def canFitWord(grid, word):
    L = len(word)
    rows = len(grid); cols = len(grid[0])

    def check_segment(cells):
        if len(cells) != L:
            return False
        for ch, (r, c) in zip(word, cells):
            g = grid[r][c]
            if g == '_' or g == ch:
                continue
            return False
        return True

    # 行向
    for r in range(rows):
        seg = []
        for c in range(cols):
            if grid[r][c] == '#':
                if check_segment(seg): return 1
                seg = []
            else:
                seg.append((r, c))
        if check_segment(seg): return 1
    # 列向
    for c in range(cols):
        seg = []
        for r in range(rows):
            if grid[r][c] == '#':
                if check_segment(seg): return 1
                seg = []
            else:
                seg.append((r, c))
        if check_segment(seg): return 1
    return 0

import java.util.*;
class Solution {
    char[][] g; String w;
    boolean check(List<int[]> seg) {
        if (seg.size() != w.length()) return false;
        for (int i = 0; i < seg.size(); i++) {
            int[] p = seg.get(i);
            char ch = g[p[0]][p[1]];
            if (ch != '_' && ch != w.charAt(i)) return false;
        }
        return true;
    }
    public int canFitWord(char[][] grid, String word) {
        g = grid; w = word;
        int R = grid.length, C = grid[0].length;
        for (int r = 0; r < R; r++) {
            List<int[]> seg = new ArrayList<>();
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == '#') { if (check(seg)) return 1; seg.clear(); }
                else seg.add(new int[]{r, c});
            }
            if (check(seg)) return 1;
        }
        for (int c = 0; c < C; c++) {
            List<int[]> seg = new ArrayList<>();
            for (int r = 0; r < R; r++) {
                if (grid[r][c] == '#') { if (check(seg)) return 1; seg.clear(); }
                else seg.add(new int[]{r, c});
            }
            if (check(seg)) return 1;
        }
        return 0;
    }
}

