def closestCost(pizzas, toppings, x):
    best = None
    def update(p):
        nonlocal best
        if best is None: best = p; return
        d1 = abs(p - x); d2 = abs(best - x)
        if d1 < d2 or (d1 == d2 and p < best):
            best = p
    m = len(toppings)
    for p in pizzas:
        update(p)
        for i in range(m):
            update(p + toppings[i])
            for j in range(i + 1, m):
                update(p + toppings[i] + toppings[j])
    return best

class Solution {
    int best = Integer.MAX_VALUE;
    int target;
    void update(int p) {
        if (best == Integer.MAX_VALUE) { best = p; return; }
        int d1 = Math.abs(p - target), d2 = Math.abs(best - target);
        if (d1 < d2 || (d1 == d2 && p < best)) best = p;
    }
    public int closestCost(int[] pizzas, int[] toppings, int x) {
        target = x; best = Integer.MAX_VALUE;
        int m = toppings.length;
        for (int p : pizzas) {
            update(p);
            for (int i = 0; i < m; i++) {
                update(p + toppings[i]);
                for (int j = i + 1; j < m; j++) update(p + toppings[i] + toppings[j]);
            }
        }
        return best;
    }
}

