        for (int p : pizzas) {
            update(p);
            for (int i = 0; i < m; i++) {
                update(p + toppings[i]);
                for (int j = i + 1; j < m; j++) update(p + toppings[i] + toppings[j]);
            }
        }
        return best;
    }
};

def countFourDigitCodes(S):
    if S < 0 or S > 36:
        return 0
    dp = [[0] * 37 for _ in range(5)]
    dp[0][0] = 1
    for i in range(1, 5):
        for s in range(37):
            for d in range(10):
                if s - d >= 0:
                    dp[i][s] += dp[i - 1][s - d]
    return dp[4][S]

class Solution {
    public int countFourDigitCodes(int S) {
        if (S < 0 || S > 36) return 0;
        int[][] dp = new int[5][37];
        dp[0][0] = 1;
        for (int i = 1; i <= 4; i++)
            for (int s = 0; s <= 36; s++)
                for (int d = 0; d <= 9; d++)
                    if (s - d >= 0) dp[i][s] += dp[i - 1][s - d];
        return dp[4][S];
    }
}

