from collections import deque

def maxDetonation(bombs):
    n = len(bombs)
    adj = [[] for _ in range(n)]
    for i in range(n):
        xi, yi, ri = bombs[i]
        r2 = ri * ri
        for j in range(n):
            if i == j: continue
            dx = bombs[j][0] - xi; dy = bombs[j][1] - yi
            if dx * dx + dy * dy <= r2:
                adj[i].append(j)
    best = 0
    for s in range(n):
        seen = {s}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v); q.append(v)
        best = max(best, len(seen))
    return best

import java.util.*;
class Solution {
    public int maxDetonation(int[][] bombs) {
        int n = bombs.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            long r2 = (long) bombs[i][2] * bombs[i][2];
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                long dx = bombs[j][0] - bombs[i][0], dy = bombs[j][1] - bombs[i][1];
                if (dx * dx + dy * dy <= r2) adj.get(i).add(j);
            }
        }
        int best = 0;
        for (int s = 0; s < n; s++) {
            boolean[] seen = new boolean[n];
            seen[s] = true; int cnt = 1;
            Deque<Integer> q = new ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; cnt++; q.add(v); }
            }
            best = Math.max(best, cnt);
        }
        return best;
    }
}

