            String op = s.substring(i, i + 3); i += 4;
            int x = parse();
            while (s.charAt(i) == ' ') i++;
            i++; // comma
            int y = parse();
            while (s.charAt(i) == ' ') i++;
            i++; // )
            return op.equals("add") ? x + y : x - y;
        }
