def fillMatrix(n):
    if n == 2:
        return None
    if n % 2 == 0:
        return None  # 题目示例不要求覆盖偶数情形
    M = [[0] * n for _ in range(n)]
    r, c = 0, n // 2
    for num in range(1, n * n + 1):
        M[r][c] = num
        nr, nc = (r - 1) % n, (c + 1) % n
        if M[nr][nc] != 0:
            r = (r + 1) % n
        else:
            r, c = nr, nc
    return M

class Solution {
    public int[][] fillMatrix(int n) {
        if (n == 2 || n % 2 == 0) return null;
        int[][] M = new int[n][n];
        int r = 0, c = n / 2;
        for (int num = 1; num <= n * n; num++) {
            M[r][c] = num;
            int nr = (r - 1 + n) % n, nc = (c + 1) % n;
            if (M[nr][nc] != 0) r = (r + 1) % n;
            else { r = nr; c = nc; }
        }
        return M;
    }
}

