from bisect import bisect_left

def findClosestStore(houses, stores):
    s = sorted(stores)
    res = []
    for h in houses:
        i = bisect_left(s, h)
        cand = []
        if i < len(s): cand.append(s[i])
        if i > 0: cand.append(s[i - 1])
        # 距离最小，距离相同取数值最小
        cand.sort(key=lambda x: (abs(x - h), x))
        res.append(cand[0])
    return res

import java.util.*;
class Solution {
    public int[] findClosestStore(int[] houses, int[] stores) {
        int[] s = stores.clone();
        Arrays.sort(s);
        int[] res = new int[houses.length];
        for (int k = 0; k < houses.length; k++) {
            int h = houses[k];
            int i = Arrays.binarySearch(s, h);
            if (i < 0) i = -i - 1;
            int best = Integer.MAX_VALUE, bestDist = Integer.MAX_VALUE;
            int[] cand = (i > 0 && i < s.length) ? new int[]{s[i - 1], s[i]} : (i == 0 ? new int[]{s[0]} : new int[]{s[s.length - 1]});
            for (int v : cand) {
                int d = Math.abs(v - h);
                if (d < bestDist || (d == bestDist && v < best)) { bestDist = d; best = v; }
            }
            res[k] = best;
        }
        return res;
    }
}

