        vector<int> s = stores;
        sort(s.begin(), s.end());
        vector<int> res;
        for (int h : houses) {
            auto it = lower_bound(s.begin(), s.end(), h);
            int best = INT_MAX, bestDist = INT_MAX;
            vector<int> cand;
            if (it != s.end()) cand.push_back(*it);
            if (it != s.begin()) cand.push_back(*prev(it));
            for (int v : cand) {
                int d = abs(v - h);
                if (d < bestDist || (d == bestDist && v < best)) { bestDist = d; best = v; }
            }
            res.push_back(best);
        }
        return res;
    }
};

import java.util.*;
class Solution {
    public int findConsistentLogs(int[] arr) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : arr) freq.merge(v, 1, Integer::sum);
        int m = Integer.MAX_VALUE;
        for (int v : freq.values()) m = Math.min(m, v);
        Map<Integer, Integer> cnt = new HashMap<>();
        int l = 0, best = 0;
        for (int r = 0; r < arr.length; r++) {
            cnt.merge(arr[r], 1, Integer::sum);
            while (cnt.get(arr[r]) > m) {
                cnt.merge(arr[l], -1, Integer::sum);
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

