def findLastCharacter(S, K):
    s = list(S * K)
    front = True
    while len(s) > 1:
        if front:
            # 删除从第 1 个开始每隔一个的字符（位置 0,2,4,...）
            s = [c for i, c in enumerate(s) if i % 2 == 1]
        else:
            # 从末尾开始每隔一个删除：保留与最后字符同奇偶距离的字符
            n = len(s)
            s = [c for i, c in enumerate(s) if (n - 1 - i) % 2 == 1]
        front = not front
    return s[0]

class Solution {
    public String findLastCharacter(String S, int K) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < K; i++) sb.append(S);
        String s = sb.toString();
        boolean front = true;
        while (s.length() > 1) {
            StringBuilder next = new StringBuilder();
            int n = s.length();
            if (front) {
                for (int i = 1; i < n; i += 2) next.append(s.charAt(i));
            } else {
                for (int i = 0; i < n; i++) if ((n - 1 - i) % 2 == 1) next.append(s.charAt(i));
            }
            s = next.toString();
            front = !front;
        }
        return s;
    }
}

