            } else {
                for (int i = 0; i < n; i++) if ((n - 1 - i) % 2 == 1) next += s[i];
            }
            s = next;
            front = !front;
        }
        return s;
    }
};

def maxHeartRateDifference(heartRate, activityLevel):
    mn = {}; mx = {}
    for hr, lvl in zip(heartRate, activityLevel):
        if lvl not in mn:
            mn[lvl] = hr; mx[lvl] = hr
        else:
            if hr < mn[lvl]: mn[lvl] = hr
            if hr > mx[lvl]: mx[lvl] = hr
    return max(mx[k] - mn[k] for k in mn)

import java.util.*;
class Solution {
    public int maxHeartRateDifference(int[] heartRate, String[] activityLevel) {
        Map<String, int[]> g = new HashMap<>();
        for (int i = 0; i < heartRate.length; i++) {
            int hr = heartRate[i];
            int[] mm = g.get(activityLevel[i]);
            if (mm == null) g.put(activityLevel[i], new int[]{hr, hr});
            else { mm[0] = Math.min(mm[0], hr); mm[1] = Math.max(mm[1], hr); }
        }
        int best = 0;
        for (int[] mm : g.values()) best = Math.max(best, mm[1] - mm[0]);
        return best;
    }
}

