def longestNonDecreasingWithOneChange(nums):
    n = len(nums)
    if n <= 2: return n
    up = [1] * n
    for i in range(1, n):
        if nums[i] >= nums[i - 1]:
            up[i] = up[i - 1] + 1
    down = [1] * n
    for i in range(n - 2, -1, -1):
        if nums[i] <= nums[i + 1]:
            down[i] = down[i + 1] + 1
    best = max(up)
    for i in range(n):
        left = up[i - 1] if i > 0 else 0
        right = down[i + 1] if i + 1 < n else 0
        if i == 0 or i + 1 == n or nums[i - 1] <= nums[i + 1] + 0:
            # 改成介于左右之间的值
            pass
        if i == 0:
            cand = 1 + right
        elif i + 1 == n:
            cand = left + 1
        else:
            cand = (left + 1 + right) if nums[i - 1] <= nums[i + 1] else max(left + 1, 1 + right)
        if cand > best:
            best = cand
    return best

class Solution {
    public int longestNonDecreasingWithOneChange(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int[] up = new int[n]; int[] down = new int[n];
        up[0] = 1;
        for (int i = 1; i < n; i++) up[i] = (nums[i] >= nums[i - 1]) ? up[i - 1] + 1 : 1;
        down[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) down[i] = (nums[i] <= nums[i + 1]) ? down[i + 1] + 1 : 1;
        int best = 0;
        for (int v : up) best = Math.max(best, v);
        for (int i = 0; i < n; i++) {
            int left = i > 0 ? up[i - 1] : 0;
            int right = i + 1 < n ? down[i + 1] : 0;
            int cand;
            if (i == 0) cand = 1 + right;
            else if (i + 1 == n) cand = left + 1;
            else cand = (nums[i - 1] <= nums[i + 1]) ? left + 1 + right : Math.max(left + 1, 1 + right);
            if (cand > best) best = cand;
        }
        return best;
    }
}

