            cur = (arr[i] >= arr[i - 1]) ? cur + 1 : 1;
            if (cur > best) best = cur;
        }
        return best;
    }
};

from collections import defaultdict, deque

def findMinDistanceToFurthestNode(n, edges):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v); g[v].append(u)
    def bfs(src):
        dist = {src: 0}
        q = deque([src])
        far = src
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    if dist[v] > dist[far]: far = v
                    q.append(v)
        return far, dist[far]
    u, _ = bfs(1)
    _, d = bfs(u)
    return (d + 1) // 2

import java.util.*;
class Solution {
    List<List<Integer>> g;
    int[] bfs(int src, int n) {
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(src);
        int far = src;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (dist[v] > dist[far]) far = v;
                q.add(v);
            }
        }
        return new int[]{far, dist[far]};
    }
    public int findMinDistanceToFurthestNode(int n, int[][] edges) {
        g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] a = bfs(1, n);
        int[] b = bfs(a[0], n);
        return (b[1] + 1) / 2;
    }
}

