from collections import defaultdict, deque

def minDiameter(n, k, edges):
    g = defaultdict(set)
    for u, v in edges:
        g[u].add(v); g[v].add(u)
    alive = set(range(1, n + 1))

    def diameter():
        if not alive: return 0
        src = next(iter(alive))
        def bfs(s):
            dist = {s: 0}; q = deque([s]); far = s
            while q:
                u = q.popleft()
                for v in g[u]:
                    if v in alive and v not in dist:
                        dist[v] = dist[u] + 1
                        if dist[v] > dist[far]: far = v
                        q.append(v)
            return far, dist[far]
        a, _ = bfs(src)
        b, d = bfs(a)
        return d

    for _ in range(k):
        if len(alive) <= 1: break
        # 找一个叶子（度=1）删除；优先沿直径删
        leaf = None
        for u in alive:
            if len(g[u]) == 1:
                leaf = u; break
        if leaf is None: break
        for v in list(g[leaf]):
            g[v].remove(leaf)
        g.pop(leaf, None)
        alive.discard(leaf)
    return diameter()

import java.util.*;
class Solution {
    public int minDiameter(int n, int k, int[][] edges) {
        Map<Integer, Set<Integer>> g = new HashMap<>();
        for (int i = 1; i <= n; i++) g.put(i, new HashSet<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        Set<Integer> alive = new HashSet<>();
        for (int i = 1; i <= n; i++) alive.add(i);
        for (int t = 0; t < k && alive.size() > 1; t++) {
            Integer leaf = null;
            for (int u : alive) if (g.get(u).size() == 1) { leaf = u; break; }
            if (leaf == null) break;
            for (int v : new ArrayList<>(g.get(leaf))) g.get(v).remove(leaf);
            g.remove(leaf); alive.remove(leaf);
        }
        if (alive.size() <= 1) return 0;
        int src = alive.iterator().next();
        int[] a = bfs(src, g, alive);
        int[] b = bfs(a[0], g, alive);
        return b[1];
    }
    int[] bfs(int src, Map<Integer, Set<Integer>> g, Set<Integer> alive) {
        Map<Integer, Integer> dist = new HashMap<>();
        dist.put(src, 0);
        Deque<Integer> q = new ArrayDeque<>(); q.add(src);
        int far = src;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (alive.contains(v) && !dist.containsKey(v)) {
                dist.put(v, dist.get(u) + 1);
                if (dist.get(v) > dist.get(far)) far = v;
                q.add(v);
            }
        }
        return new int[]{far, dist.get(far)};
    }
}

