class Solution {
public:
    int minDiameter(int n, int k, vector<vector<int>>& edges) {
        unordered_map<int, unordered_set<int>> g;
        for (int i = 1; i <= n; i++) g[i] = {};
        for (auto& e : edges) { g[e[0]].insert(e[1]); g[e[1]].insert(e[0]); }
        unordered_set<int> alive;
        for (int i = 1; i <= n; i++) alive.insert(i);
        for (int t = 0; t < k && (int)alive.size() > 1; t++) {
