            vector<int> nbrs(g[leaf].begin(), g[leaf].end());
            for (int v : nbrs) g[v].erase(leaf);
            g.erase(leaf); alive.erase(leaf);
        }
        if ((int)alive.size() <= 1) return 0;
        auto bfs = [&](int src) -> pair<int,int> {
            unordered_map<int,int> dist; dist[src] = 0;
            queue<int> q; q.push(src);
