                    if (dist[v] > dist[far]) far = v;
                    q.push(v);
                }
            }
            return {far, dist[far]};
        };
        auto a = bfs(*alive.begin());
        auto b = bfs(a.first);
        return b.second;
    }
};

def findOptimalInput(targetTime):
    def cost_seconds(v):
        digs = str(v)
        c = len(digs)
        for i in range(1, len(digs)):
            if digs[i] != digs[i - 1]:
                c += 2
        if len(digs) <= 2:
            sec = int(digs)
        else:
            minutes = int(digs[:-2])
            seconds = int(digs[-2:])
            sec = minutes * 60 + seconds
        return c, sec
    best = None
    for v in range(0, 10000):
        c, sec = cost_seconds(v)
        if abs(sec - targetTime) * 10 > targetTime:
            continue
        key = (c, abs(sec - targetTime), v)
        if best is None or key < best[0]:
            best = (key, v)
    return best[1] if best else -1

class Solution {
    public int findOptimalInput(int targetTime) {
        int bestV = -1; long[] best = null;
        for (int v = 0; v < 10000; v++) {
            String d = Integer.toString(v);
            int c = d.length();
            for (int i = 1; i < d.length(); i++) if (d.charAt(i) != d.charAt(i - 1)) c += 2;
            int sec;
            if (d.length() <= 2) sec = Integer.parseInt(d);
            else {
                int m = Integer.parseInt(d.substring(0, d.length() - 2));
                int s = Integer.parseInt(d.substring(d.length() - 2));
                sec = m * 60 + s;
            }
            if ((long) Math.abs(sec - targetTime) * 10 > targetTime) continue;
            long[] key = {c, Math.abs(sec - targetTime), v};
            if (best == null || cmp(key, best) < 0) { best = key; bestV = v; }
        }
        return bestV;
    }
    int cmp(long[] a, long[] b) {
        for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return Long.compare(a[i], b[i]);
        return 0;
    }
}

