import java.util.*;
class Solution {
    public int[] findPalindromes(int n, int[][] edges, char[] c, int[] queries) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        boolean[] visited = new boolean[n + 1];
        int[] parent = new int[n + 1];
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i <= n; i++) children.add(new ArrayList<>());
        Deque<Integer> st = new ArrayDeque<>(); st.push(1); visited[1] = true;
        List<Integer> order = new ArrayList<>();
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (int v : g.get(u)) if (!visited[v]) {
                visited[v] = true; parent[v] = u;
                children.get(u).add(v); st.push(v);
            }
        }
        for (int u = 1; u <= n; u++) Collections.sort(children.get(u));
        String[] S = new String[n + 1];
        for (int i = order.size() - 1; i >= 0; i--) {
            int u = order.get(i);
            StringBuilder sb = new StringBuilder();
            for (int v : children.get(u)) sb.append(S[v]);
            sb.append(c[u - 1]);
            S[u] = sb.toString();
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            String s = S[queries[i]];
            String r = new StringBuilder(s).reverse().toString();
            ans[i] = s.equals(r) ? 1 : 0;
        }
        return ans;
    }
}

