using namespace std;
class Solution {
public:
    vector<int> findPalindromes(int n, vector<vector<int>>& edges, vector<char>& c, vector<int>& queries) {
        vector<vector<int>> g(n + 1), children(n + 1);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<bool> visited(n + 1, false);
        vector<int> order;
        stack<int> st; st.push(1); visited[1] = true;
        while (!st.empty()) {
            int u = st.top(); st.pop(); order.push_back(u);
            for (int v : g[u]) if (!visited[v]) {
                visited[v] = true;
                children[u].push_back(v); st.push(v);
            }
        }
        for (int u = 1; u <= n; u++) sort(children[u].begin(), children[u].end());
        vector<string> S(n + 1);
        for (int i = order.size() - 1; i >= 0; i--) {
            int u = order[i];
            string s;
            for (int v : children[u]) s += S[v];
            s += c[u - 1];
            S[u] = s;
        }
        vector<int> ans;
        for (int q : queries) {
            string r = S[q]; reverse(r.begin(), r.end());
            ans.push_back(S[q] == r ? 1 : 0);
        }
        return ans;
    }
};

