def getComponentsInForest(nodes, edges):
    # 用 level-order 数组重建邻接表
    n = len(nodes)
    val = [int(x) if x != 'null' else None for x in nodes]
    adj = {v: [] for v in val if v is not None}
    # children
    idx = 1
    for i in range(n):
        if val[i] is None: continue
        for _ in range(2):
            if idx < n and val[idx] is not None:
                adj[val[i]].append(val[idx]); adj[val[idx]].append(val[i])
            idx += 1
    cut = set()
    for u, v in edges:
        cut.add((u, v)); cut.add((v, u))
    visited = set(); sizes = []
    for u in adj:
        if u in visited: continue
        s = 0; stack = [u]; visited.add(u)
        while stack:
            x = stack.pop(); s += 1
            for y in adj[x]:
                if y not in visited and (x, y) not in cut:
                    visited.add(y); stack.append(y)
        sizes.append(s)
    sizes.sort(reverse=True)
    return sizes

import java.util.*;
class Solution {
    public int[] getComponentsInForest(String[] nodes, int[][] edges) {
        int n = nodes.length;
        Integer[] val = new Integer[n];
        for (int i = 0; i < n; i++) val[i] = nodes[i].equals("null") ? null : Integer.parseInt(nodes[i]);
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (Integer v : val) if (v != null) adj.put(v, new ArrayList<>());
        int idx = 1;
        for (int i = 0; i < n; i++) {
            if (val[i] == null) continue;
            for (int t = 0; t < 2; t++) {
                if (idx < n && val[idx] != null) {
                    adj.get(val[i]).add(val[idx]); adj.get(val[idx]).add(val[i]);
                }
                idx++;
            }
        }
        Set<Long> cut = new HashSet<>();
        for (int[] e : edges) { cut.add((long) e[0] * 100000 + e[1]); cut.add((long) e[1] * 100000 + e[0]); }
        Set<Integer> visited = new HashSet<>();
        List<Integer> sizes = new ArrayList<>();
        for (int u : adj.keySet()) {
            if (visited.contains(u)) continue;
            int s = 0; Deque<Integer> stk = new ArrayDeque<>(); stk.push(u); visited.add(u);
            while (!stk.isEmpty()) {
                int x = stk.pop(); s++;
                for (int y : adj.get(x)) if (!visited.contains(y) && !cut.contains((long) x * 100000 + y)) {
                    visited.add(y); stk.push(y);
                }
            }
            sizes.add(s);
        }
        sizes.sort(Comparator.reverseOrder());
        int[] res = new int[sizes.size()];
        for (int i = 0; i < res.length; i++) res[i] = sizes.get(i);
        return res;
    }
}

