def getMeetingIntervals(meetings, dns):
    if not meetings: return []
    meetings.sort()
    merged = [meetings[0][:]]
    for s, e in meetings[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    ds, de = dns
    res = []
    for s, e in merged:
        if e <= ds or s >= de:
            res.append([s, e])
        else:
            if s < ds: res.append([s, ds])
            if e > de: res.append([de, e])
    return res

import java.util.*;
class Solution {
    public int[][] getMeetingIntervals(int[][] meetings, int[] dns) {
        if (meetings.length == 0) return new int[0][];
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        merged.add(meetings[0].clone());
        for (int i = 1; i < meetings.length; i++) {
            int[] last = merged.get(merged.size() - 1);
            if (meetings[i][0] <= last[1]) last[1] = Math.max(last[1], meetings[i][1]);
            else merged.add(meetings[i].clone());
        }
        int ds = dns[0], de = dns[1];
        List<int[]> res = new ArrayList<>();
        for (int[] m : merged) {
            int s = m[0], e = m[1];
            if (e <= ds || s >= de) res.add(new int[]{s, e});
            else {
                if (s < ds) res.add(new int[]{s, ds});
                if (e > de) res.add(new int[]{de, e});
            }
        }
        return res.toArray(new int[0][]);
    }
}

