def happyNeighborhood(N, M, house):
    left = {}; right = {}
    for day, x in enumerate(house, start=1):
        l = x; r = x
        if (x - 1) in right:
            l = left[x - 1]
        if (x + 1) in left:
            r = right[x + 1]
        left[r] = l; right[l] = r
        if r - l + 1 >= M:
            return day
    return -1

import java.util.*;
class Solution {
    public int happyNeighborhood(int N, int M, int[] house) {
        Map<Integer, Integer> left = new HashMap<>(), right = new HashMap<>();
        for (int day = 0; day < house.length; day++) {
            int x = house[day], l = x, r = x;
            if (right.containsKey(x - 1)) l = left.get(x - 1);
            if (left.containsKey(x + 1)) r = right.get(x + 1);
            left.put(r, l); right.put(l, r);
            if (r - l + 1 >= M) return day + 1;
        }
        return -1;
    }
}

