    int happyNeighborhood(int N, int M, vector<int>& house) {
        unordered_map<int, int> left, right;
        for (int day = 0; day < (int)house.size(); day++) {
            int x = house[day], l = x, r = x;
            auto itR = right.find(x - 1);
            if (itR != right.end()) l = left[x - 1];
            auto itL = left.find(x + 1);
            if (itL != left.end()) r = right[x + 1];
            left[r] = l; right[l] = r;
            if (r - l + 1 >= M) return day + 1;
        }
        return -1;
    }
};

class Solution {
    public int isBalanced(String s) {
        int open = 0, close = 0;
        for (char ch : s.toCharArray()) {
            if (ch == '(') open++;
            else if (ch == ')') close++;
            else if (Character.isDigit(ch)) {
                int d = ch - '0';
                int take = Math.min(d, close);
                close -= take; d -= take;
                take = Math.min(d, open);
                open -= take;
            }
        }
        return open == close ? 1 : 0;
    }
}

