import java.util.*;
class Solution {
    public String largestLexSubstring(String A, String B) {
        int L = A.length();
        if (B.length() < L) return "";
        int[] need = new int[26], cur = new int[26];
        for (char c : A.toCharArray()) need[c - 'a']++;
        for (int i = 0; i < L; i++) cur[B.charAt(i) - 'a']++;
        String best = "";
        if (Arrays.equals(need, cur)) best = B.substring(0, L);
        for (int i = L; i < B.length(); i++) {
            cur[B.charAt(i) - 'a']++;
            cur[B.charAt(i - L) - 'a']--;
            if (Arrays.equals(need, cur)) {
                String sub = B.substring(i - L + 1, i + 1);
                if (sub.compareTo(best) > 0) best = sub;
            }
        }
        return best;
    }
}

