            }
        }
        return best;
    }
};

def tokenize(text, dictionary):
    seen = {}
    for tok, idd in dictionary:
        if tok not in seen:
            seen[tok] = idd
    keys = sorted(seen.keys(), key=lambda x: -len(x))
    res = []; i = 0
    while i < len(text):
        matched = False
        for k in keys:
            if text.startswith(k, i):
                res.append(seen[k]); i += len(k); matched = True; break
        if not matched:
            res.append(text[i]); i += 1
    return res

import java.util.*;
class Solution {
    public List<String> tokenize(String text, String[][] dictionary) {
        Map<String, String> seen = new LinkedHashMap<>();
        for (String[] p : dictionary) if (!seen.containsKey(p[0])) seen.put(p[0], p[1]);
        List<String> keys = new ArrayList<>(seen.keySet());
        keys.sort((a, b) -> Integer.compare(b.length(), a.length()));
        List<String> res = new ArrayList<>();
        int i = 0;
        while (i < text.length()) {
            boolean matched = false;
            for (String k : keys) {
                if (text.startsWith(k, i)) { res.add(seen.get(k)); i += k.length(); matched = true; break; }
            }
            if (!matched) { res.add(String.valueOf(text.charAt(i))); i++; }
        }
        return res;
    }
}

#include <vector>
