class Solution {
public:
    vector<string> tokenize(string text, vector<vector<string>>& dictionary) {
        unordered_map<string, string> seen;
        vector<string> keys;
        for (auto& p : dictionary) if (!seen.count(p[0])) { seen[p[0]] = p[1]; keys.push_back(p[0]); }
        sort(keys.begin(), keys.end(), [](const string& a, const string& b){ return a.size() > b.size(); });
        vector<string> res;
        int i = 0;
        while (i < (int)text.size()) {
            bool matched = false;
            for (auto& k : keys) {
                if (i + (int)k.size() <= (int)text.size() && text.compare(i, k.size(), k) == 0) {
                    res.push_back(seen[k]); i += k.size(); matched = true; break;
                }
            }
            if (!matched) { res.push_back(string(1, text[i])); i++; }
        }
        return res;
    }
};

def maxSubarrayFilledWithZeros(A, X, Y):
    n = len(A)
    def feasible(L):
        # 尝试在窗口 [l, l+L-1] 中用 ≤X 次 Op1 + ≤Y 次 Op2 全部归零
        for l in range(n - L + 1):
            r = l + L - 1
            zeros_needed = sum(1 for i in range(l, r + 1) if A[i] != 0)
            # 简化策略：每个非 0 直接用 Op2 置 0，需要 zeros_needed ≤ Y
            if zeros_needed <= Y:
                return True
            # 更精细：在窗口内放置 op2 个锚点（Y 个），其余位置可由 Op1 链式生成
            # 但 Op1 需要 a[i-1]==0 的前提；要让长度为 g 的"空"段用 g 次 Op1 填充
            # 故 Y 个锚点把窗口分成至多 Y+1 段（包含端点扩展），总 Op1 ≈ L - Y
            if Y >= 1 and L - Y <= X:
                return True
        return False
    best = 0
    for L in range(n, 0, -1):
        if feasible(L):
            best = L; break
    return best

class Solution {
    public int maxSubarrayFilledWithZeros(int[] A, int X, int Y) {
        int n = A.length;
        for (int L = n; L >= 1; L--) {
            for (int l = 0; l + L <= n; l++) {
                int r = l + L - 1;
                int nonZero = 0;
                for (int i = l; i <= r; i++) if (A[i] != 0) nonZero++;
                if (nonZero <= Y) return L;
                if (Y >= 1 && L - Y <= X) return L;
            }
        }
        return 0;
    }
}

