def maxMovesSameSum(A):
    n = len(A)
    if n < 2: return 0
    def simulate(S):
        l, r = 0, n - 1; cnt = 0
        while r - l >= 1:
            if A[l] + A[l + 1] == S:
                l += 2; cnt += 1
            elif A[r] + A[r - 1] == S:
                r -= 2; cnt += 1
            elif A[l] + A[r] == S:
                l += 1; r -= 1; cnt += 1
            else:
                break
        return cnt
    cands = set()
    if n >= 2: cands.add(A[0] + A[1])
    if n >= 2: cands.add(A[-1] + A[-2])
    cands.add(A[0] + A[-1])
    return max(simulate(s) for s in cands)

import java.util.*;
class Solution {
    int[] arr; int n;
    int simulate(int S) {
        int l = 0, r = n - 1, cnt = 0;
        while (r - l >= 1) {
            if (arr[l] + arr[l + 1] == S) { l += 2; cnt++; }
            else if (arr[r] + arr[r - 1] == S) { r -= 2; cnt++; }
            else if (arr[l] + arr[r] == S) { l++; r--; cnt++; }
            else break;
        }
        return cnt;
    }
    public int maxMovesSameSum(int[] A) {
        arr = A; n = A.length;
        if (n < 2) return 0;
        Set<Integer> cands = new HashSet<>();
        cands.add(A[0] + A[1]);
        cands.add(A[n - 1] + A[n - 2]);
        cands.add(A[0] + A[n - 1]);
        int best = 0;
        for (int s : cands) best = Math.max(best, simulate(s));
        return best;
    }
}

