class Solution {
    public int minChairs(int[] S, int[] E) {
        int n = S.length;
        int[][] ev = new int[2 * n][2];
        for (int i = 0; i < n; i++) { ev[2 * i] = new int[]{S[i], 1}; ev[2 * i + 1] = new int[]{E[i], -1}; }
        Arrays.sort(ev, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
