def mergeIntervalsWithNames(intervals):
    events = []
    for name, s, e in intervals:
        events.append((int(s), 0, name))
        events.append((int(e), 1, name))
    events.sort()
    active = []  # 保持顺序
    res = []
    prev_t = None
    for t, typ, name in events:
        if prev_t is not None and t != prev_t and active:
            res.append(f"{prev_t} {t} " + ", ".join(active))
        if typ == 0: active.append(name)
        else: active.remove(name)
        prev_t = t
    return res

import java.util.*;
class Solution {
    public List<String> mergeIntervalsWithNames(String[][] intervals) {
        List<int[]> events = new ArrayList<>();
        List<String> names = new ArrayList<>();
        for (String[] it : intervals) {
            events.add(new int[]{Integer.parseInt(it[1]), 0, names.size()});
            events.add(new int[]{Integer.parseInt(it[2]), 1, names.size()});
            names.add(it[0]);
        }
        events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        List<String> active = new ArrayList<>();
        List<String> res = new ArrayList<>();
        Integer prev = null;
        for (int[] e : events) {
            if (prev != null && e[0] != prev && !active.isEmpty()) {
                res.add(prev + " " + e[0] + " " + String.join(", ", active));
            }
            if (e[1] == 0) active.add(names.get(e[2]));
            else active.remove(names.get(e[2]));
            prev = e[0];
        }
        return res;
    }
}

