            events.push_back({stoi(it[1]), 0, (int)names.size()});
            events.push_back({stoi(it[2]), 1, (int)names.size()});
            names.push_back(it[0]);
        }
        sort(events.begin(), events.end());
        vector<string> active, res;
        int prev = -1; bool hasPrev = false;
        for (auto& [t, typ, idx] : events) {
            if (hasPrev && t != prev && !active.empty()) {
                string line = to_string(prev) + " " + to_string(t) + " ";
                for (int i = 0; i < (int)active.size(); i++) { if (i) line += ", "; line += active[i]; }
                res.push_back(line);
            }
            if (typ == 0) active.push_back(names[idx]);
            else active.erase(find(active.begin(), active.end(), names[idx]));
            prev = t; hasPrev = true;
        }
        return res;
    }
};

