def minDays(roses, k, n):
    if n * k > len(roses): return -1
    def can(d):
        bouquets = run = 0
        for r in roses:
            if r <= d:
                run += 1
                if run == k:
                    bouquets += 1; run = 0
            else:
                run = 0
        return bouquets >= n
    lo, hi = min(roses), max(roses)
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid): hi = mid
        else: lo = mid + 1
    return lo

class Solution {
    public int minDays(int[] roses, int k, int n) {
        if ((long) n * k > roses.length) return -1;
        int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
        for (int r : roses) { lo = Math.min(lo, r); hi = Math.max(hi, r); }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (can(roses, k, n, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
    boolean can(int[] roses, int k, int n, int d) {
        int bouq = 0, run = 0;
        for (int r : roses) {
            if (r <= d) { run++; if (run == k) { bouq++; run = 0; } }
            else run = 0;
        }
        return bouq >= n;
    }
}

