import java.util.*;
class Solution {
    public int minFlipsGridPalindrome(int[][] grid) {
        int n = grid.length, m = grid[0].length, ans = 0;
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            int[][] cells = {{i, j}, {i, m - 1 - j}, {n - 1 - i, j}, {n - 1 - i, m - 1 - j}};
            Set<String> uniq = new TreeSet<>();
            for (int[] c : cells) uniq.add(c[0] + "," + c[1]);
            String key = String.join(";", uniq);
            if (seen.contains(key)) continue;
            seen.add(key);
            int ones = 0, total = uniq.size();
            for (String s : uniq) {
                String[] p = s.split(",");
                ones += grid[Integer.parseInt(p[0])][Integer.parseInt(p[1])];
            }
            ans += Math.min(ones, total - ones);
        }
        return ans;
    }
}

