        }
        return ans;
    }
};

def minAbsDifference(loads):
    total = sum(loads)
    target = total // 2
    dp = [False] * (target + 1); dp[0] = True
    for v in loads:
        for s in range(target, v - 1, -1):
            if dp[s - v]: dp[s] = True
    for s in range(target, -1, -1):
        if dp[s]: return total - 2 * s
    return total

class Solution {
    public int minAbsDifference(int[] loads) {
        int total = 0;
        for (int v : loads) total += v;
        int target = total / 2;
        boolean[] dp = new boolean[target + 1]; dp[0] = true;
        for (int v : loads) for (int s = target; s >= v; s--) if (dp[s - v]) dp[s] = true;
        for (int s = target; s >= 0; s--) if (dp[s]) return total - 2 * s;
        return total;
    }
}

