        return total;
    }
};

import java.util.*;
class Solution {
    public int[] minimizeTotalTime(int[] multiples, int[] prices) {
        int n = multiples.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            double ra = prices[a] / (double) Math.max(multiples[a] - 1, 1);
            double rb = prices[b] / (double) Math.max(multiples[b] - 1, 1);
            return Double.compare(ra, rb);
        });
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = idx[i];
        return res;
    }
}

