import java.util.*;
class Solution {
    public String[] assignMinimumCars(int[][] requests) {
        Integer[] idx = new Integer[requests.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> requests[a][0] != requests[b][0] ? Integer.compare(requests[a][0], requests[b][0]) : Integer.compare(requests[a][1], requests[b][1]));
        PriorityQueue<Integer> freeIds = new PriorityQueue<>();
        PriorityQueue<int[]> busy = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        int nextId = 0;
        Map<Integer, List<int[]>> assigned = new TreeMap<>();
        for (int i : idx) {
            int p = requests[i][0], r = requests[i][1];
            while (!busy.isEmpty() && busy.peek()[0] <= p) freeIds.offer(busy.poll()[1]);
            int cid;
            if (!freeIds.isEmpty()) cid = freeIds.poll();
            else { cid = nextId++; assigned.put(cid, new ArrayList<>()); }
            assigned.computeIfAbsent(cid, k -> new ArrayList<>()).add(new int[]{p, r});
            busy.offer(new int[]{r, cid});
        }
        String[] res = new String[assigned.size()];
        int k = 0;
        for (var e : assigned.entrySet()) {
            StringBuilder sb = new StringBuilder();
            sb.append(e.getKey()).append(":");
            for (int[] pr : e.getValue()) sb.append(" (").append(pr[0]).append(",").append(pr[1]).append(")");
            res[k++] = sb.toString();
        }
        return res;
    }
}

