using namespace std;
class Solution {
public:
    vector<string> assignMinimumCars(vector<vector<int>>& requests) {
        vector<int> idx(requests.size());
        for (int i = 0; i < (int)idx.size(); i++) idx[i] = i;
        sort(idx.begin(), idx.end(), [&](int a, int b){
            return requests[a][0] != requests[b][0] ? requests[a][0] < requests[b][0] : requests[a][1] < requests[b][1];
        });
        priority_queue<int, vector<int>, greater<int>> freeIds;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> busy;
        int nextId = 0;
        map<int, vector<pair<int,int>>> assigned;
        for (int i : idx) {
            int p = requests[i][0], r = requests[i][1];
            while (!busy.empty() && busy.top().first <= p) { freeIds.push(busy.top().second); busy.pop(); }
            int cid;
            if (!freeIds.empty()) { cid = freeIds.top(); freeIds.pop(); }
            else cid = nextId++;
            assigned[cid].push_back({p, r});
            busy.push({r, cid});
        }
        vector<string> res;
        for (auto& [cid, v] : assigned) {
            string s = to_string(cid) + ":";
            for (auto& [p, r] : v) s += " (" + to_string(p) + "," + to_string(r) + ")";
            res.push_back(s);
        }
        return res;
    }
};

class Solution {
    int n; String s; int k;
    int solve(int target0) {
        int[] diff = new int[n + 1];
        int flips = 0, cnt = 0;
        for (int i = 0; i < n; i++) {
            cnt = (cnt + diff[i]) % 2;
            int cur = ((s.charAt(i) - '0') + cnt) % 2;
            int expected = (target0 + i) % 2;
            if (cur != expected) {
                if (i + k > n) return -1;
                flips++;
                diff[i] ^= 1; diff[i + k] ^= 1;
                cnt ^= 1;
            }
        }
        return flips;
    }
    public int minFlipsToAlternate(String str, int kk) {
        s = str; k = kk; n = s.length();
        int a = solve(0), b = solve(1);
        int best = Integer.MAX_VALUE;
        if (a >= 0) best = Math.min(best, a);
        if (b >= 0) best = Math.min(best, b);
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

