class Solution {
    public int minSplits(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int nxt = nums[n - 1], ops = 0;
        for (int i = n - 2; i >= 0; i--) {
            int v = nums[i];
            if (v <= nxt) nxt = v;
            else { int k = (v + nxt - 1) / nxt; ops += k - 1; nxt = v / k; }
        }
        return ops;
    }
}

