def minOpsBinaryPalindromic(N):
    def is_pal(x):
        b = bin(x)[2:]; return b == b[::-1]
    d = 0
    while True:
        if N - d >= 0 and is_pal(N - d): return d
        if is_pal(N + d): return d
        d += 1

class Solution {
    boolean isPal(long x) {
        String b = Long.toBinaryString(x);
        int i = 0, j = b.length() - 1;
        while (i < j) { if (b.charAt(i++) != b.charAt(j--)) return false; }
        return true;
    }
    public long minOpsBinaryPalindromic(long N) {
        for (long d = 0; ; d++) {
            if (N - d >= 0 && isPal(N - d)) return d;
            if (isPal(N + d)) return d;
        }
    }
}

