def relativeSort(A, B):
    n = len(A)
    A = A[:]; B = B[:]
    swaps = 0
    for i in range(n - 1):
        ok = A[i] < A[i + 1] and B[i] < B[i + 1]
        swapped = A[i] < B[i + 1] and B[i] < A[i + 1]
        if ok:
            continue
        if swapped:
            A[i + 1], B[i + 1] = B[i + 1], A[i + 1]
            swaps += 1
        else:
            return -1
    return swaps

class Solution {
    public int relativeSort(int[] A, int[] B) {
        int n = A.length, swaps = 0;
        A = A.clone(); B = B.clone();
        for (int i = 0; i < n - 1; i++) {
            boolean ok = A[i] < A[i + 1] && B[i] < B[i + 1];
            boolean swapped = A[i] < B[i + 1] && B[i] < A[i + 1];
            if (ok) continue;
            if (swapped) { int t = A[i + 1]; A[i + 1] = B[i + 1]; B[i + 1] = t; swaps++; }
            else return -1;
        }
        return swaps;
    }
}

