import java.util.*;
class Solution {
    public String mostBookedHotelRoom(String[] A) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String op : A) if (op.charAt(0) == '+') cnt.merge(op.substring(1), 1, Integer::sum);
        String best = null; int bestC = -1;
        for (var e : cnt.entrySet()) {
            if (e.getValue() > bestC || (e.getValue() == bestC && e.getKey().compareTo(best) < 0)) {
                bestC = e.getValue(); best = e.getKey();
            }
        }
        return best;
    }
}

