def moveBitsToRight(s):
    n_zeros = s.count('0')
    seen_zeros = 0
    total = 0
    for ch in s:
        if ch == '0':
            seen_zeros += 1
        else:
            # 当前这个 1 要跨过其右侧的 0
            zeros_to_right = n_zeros - seen_zeros
            total += 1 + zeros_to_right
    return total

class Solution {
    public int moveBitsToRight(String s) {
        int nZeros = 0;
        for (char c : s.toCharArray()) if (c == '0') nZeros++;
        int seen = 0, total = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') seen++;
            else total += 1 + (nZeros - seen);
        }
        return total;
    }
}

