def nearestValueReplacement(A, cur, D):
    A = A[:]
    n = len(A)
    while True:
        A[cur] += 1
        v = A[cur]
        # 找距离 cur 最近且 ≤ D 的等值位置（并列取左）
        best = -1
        for d in range(1, D + 1):
            cand = []
            if cur - d >= 0 and A[cur - d] == v: cand.append(cur - d)
            if cur + d < n and A[cur + d] == v: cand.append(cur + d)
            if cand:
                best = min(cand)
                break
        if best == -1:
            break
        cur = best
    return A

class Solution {
    public int[] nearestValueReplacement(int[] A, int cur, int D) {
        int[] arr = A.clone();
        int n = arr.length;
        while (true) {
            arr[cur]++;
            int v = arr[cur];
            int best = -1;
            for (int d = 1; d <= D && best == -1; d++) {
                int l = cur - d, r = cur + d;
                int leftMatch = (l >= 0 && arr[l] == v) ? l : -1;
                int rightMatch = (r < n && arr[r] == v) ? r : -1;
                if (leftMatch != -1) best = leftMatch;
                else if (rightMatch != -1) best = rightMatch;
            }
            if (best == -1) break;
            cur = best;
        }
        return arr;
    }
}

