def numDistinctIslands(grid):
    n = len(grid); m = len(grid[0])
    visited = [[False] * m for _ in range(n)]
    shapes = set()
    def dfs(i, j, base_i, base_j, shape):
        if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] == 0 or visited[i][j]:
            return
        visited[i][j] = True
        shape.append((i - base_i, j - base_j))
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(i + di, j + dj, base_i, base_j, shape)
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                shape = []
                dfs(i, j, i, j, shape)
                shape.sort()
                shapes.add(tuple(shape))
    return len(shapes)

import java.util.*;
class Solution {
    int n, m;
    int[][] grid;
    boolean[][] visited;
    void dfs(int i, int j, int bi, int bj, List<int[]> shape) {
        if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] == 0 || visited[i][j]) return;
        visited[i][j] = true;
        shape.add(new int[]{i - bi, j - bj});
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) dfs(i + d[0], j + d[1], bi, bj, shape);
    }
    public int numDistinctIslands(int[][] g) {
        grid = g; n = g.length; m = g[0].length;
        visited = new boolean[n][m];
        Set<String> shapes = new HashSet<>();
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            if (g[i][j] == 1 && !visited[i][j]) {
                List<int[]> s = new ArrayList<>();
                dfs(i, j, i, j, s);
                s.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
                StringBuilder sb = new StringBuilder();
                for (int[] p : s) sb.append(p[0]).append(",").append(p[1]).append(";");
                shapes.add(sb.toString());
            }
        }
        return shapes.size();
    }
}

