def waysToSplit(s):
    n = len(s)
    if n < 2: return 0
    pref = [0] * n; suf = [0] * n
    seen = set()
    for i in range(n):
        seen.add(s[i]); pref[i] = len(seen)
    seen = set()
    for i in range(n - 1, -1, -1):
        seen.add(s[i]); suf[i] = len(seen)
    return sum(1 for i in range(n - 1) if pref[i] == suf[i + 1])

import java.util.*;
class Solution {
    public int waysToSplit(String s) {
        int n = s.length();
        if (n < 2) return 0;
        int[] pref = new int[n], suf = new int[n];
        Set<Character> seen = new HashSet<>();
        for (int i = 0; i < n; i++) { seen.add(s.charAt(i)); pref[i] = seen.size(); }
        seen.clear();
        for (int i = n - 1; i >= 0; i--) { seen.add(s.charAt(i)); suf[i] = seen.size(); }
        int ans = 0;
        for (int i = 0; i + 1 < n; i++) if (pref[i] == suf[i + 1]) ans++;
        return ans;
    }
}

