def pickMaxDistance(binaryStrings):
    def common_prefix(a, b):
        i = 0
        while i < len(a) and i < len(b) and a[i] == b[i]:
            i += 1
        return i
    best = 0
    for i in range(len(binaryStrings)):
        for j in range(i + 1, len(binaryStrings)):
            cp = common_prefix(binaryStrings[i], binaryStrings[j])
            d = (len(binaryStrings[i]) - cp) + (len(binaryStrings[j]) - cp)
            if d > best: best = d
    return best

class Solution {
