        int best = 0;
        for (int i = 0; i < binaryStrings.length; i++)
            for (int j = i + 1; j < binaryStrings.length; j++) {
                int cp = 0;
                while (cp < binaryStrings[i].length() && cp < binaryStrings[j].length() && binaryStrings[i].charAt(cp) == binaryStrings[j].charAt(cp)) cp++;
                int d = (binaryStrings[i].length() - cp) + (binaryStrings[j].length() - cp);
                if (d > best) best = d;
            }
        return best;
    }
}

