import java.util.*;
class Solution {
    public String reachTheEnd(String[] grid, int maxTime) {
        int R = grid.length, C = grid[0].length();
        if (grid[0].charAt(0) == '#') return "No";
        if (R == 1 && C == 1) return maxTime >= 0 ? "Yes" : "No";
        int[][] dist = new int[R][C];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[0][0] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            for (int[] d : dirs) {
                int nr = p[0] + d[0], nc = p[1] + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr].charAt(nc) == '.' && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[p[0]][p[1]] + 1;
                    if (nr == R - 1 && nc == C - 1) return dist[nr][nc] <= maxTime ? "Yes" : "No";
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return "No";
    }
}

#include <vector>
#include <string>
#include <queue>
using namespace std;
class Solution {
public:
    string reachTheEnd(vector<string>& grid, int maxTime) {
        int R = grid.size(), C = grid[0].size();
        if (grid[0][0] == '#') return "No";
        if (R == 1 && C == 1) return maxTime >= 0 ? "Yes" : "No";
        vector<vector<int>> dist(R, vector<int>(C, -1));
        dist[0][0] = 0;
        queue<pair<int,int>> q; q.push({0, 0});
        int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == '.' && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    if (nr == R - 1 && nc == C - 1) return dist[nr][nc] <= maxTime ? "Yes" : "No";
                    q.push({nr, nc});
                }
            }
        }
        return "No";
    }
};

import java.util.*;
class Solution {
    public long findMaximumBreakTime(int[] start, int[] finish, int t, int k) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(start[a], start[b]));
        int[] s = new int[n], f = new int[n];
        for (int i = 0; i < n; i++) { s[i] = start[idx[i]]; f[i] = finish[idx[i]]; }
        long[] gap = new long[n + 1];
        gap[0] = s[0];
        for (int i = 1; i < n; i++) gap[i] = s[i] - f[i - 1];
        gap[n] = t - f[n - 1];
        long[] len = new long[n];
        for (int i = 0; i < n; i++) len[i] = f[i] - s[i];
        long[] preG = new long[n + 2], preL = new long[n + 1];
        for (int i = 0; i <= n; i++) preG[i + 1] = preG[i] + gap[i];
        for (int i = 0; i < n; i++) preL[i + 1] = preL[i] + len[i];
        if (k >= n) return t;
        long best = 0;
        for (long g : gap) best = Math.max(best, g);
        for (int l = 0; l + k <= n; l++) {
            long merged = (preG[l + k + 1] - preG[l]) + (preL[l + k] - preL[l]);
            if (merged > best) best = merged;
        }
        return best;
    }
}

