def searchSuggestions(products, popularity, searchWord, k):
    pop = {name: int(score) for name, score in popularity}
    res = []
    for p in range(1, len(searchWord) + 1):
        prefix = searchWord[:p]
        cands = [name for name in products if name.startswith(prefix)]
        cands.sort(key=lambda name: (-pop.get(name, 0), name))
        res.append(cands[:k])
    return res

import java.util.*;
class Solution {
    public List<List<String>> searchSuggestions(String[] products, String[][] popularity, String searchWord, int k) {
        Map<String, Integer> pop = new HashMap<>();
        for (String[] p : popularity) pop.put(p[0], Integer.parseInt(p[1]));
        List<List<String>> res = new ArrayList<>();
        for (int len = 1; len <= searchWord.length(); len++) {
            String prefix = searchWord.substring(0, len);
            List<String> cands = new ArrayList<>();
            for (String pr : products) if (pr.startsWith(prefix)) cands.add(pr);
            cands.sort((a, b) -> {
                int pa = pop.getOrDefault(a, 0), pb = pop.getOrDefault(b, 0);
                if (pa != pb) return Integer.compare(pb, pa);
                return a.compareTo(b);
            });
            res.add(cands.subList(0, Math.min(k, cands.size())));
        }
        return res;
    }
}

