def setTotalPalindromeCost(dna):
    n = len(dna)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] ^ (1 << (ord(dna[i]) - ord('a')))
    total = 0
    for i in range(n):
        for j in range(i, n):
            mask = pref[j + 1] ^ pref[i]
            total += bin(mask).count('1') // 2
    return total

class Solution {
    public long setTotalPalindromeCost(String dna) {
        int n = dna.length();
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] ^ (1 << (dna.charAt(i) - 'a'));
        long total = 0;
        for (int i = 0; i < n; i++) for (int j = i; j < n; j++) {
            int mask = pref[j + 1] ^ pref[i];
            total += Integer.bitCount(mask) / 2;
        }
        return total;
    }
}

