    }
};

import heapq

def shortestPathWithWaypoint(n, edges, start, target, waypoint):
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w)); g[v].append((u, w))
    def dijkstra(src):
        dist = [float('inf')] * n
        dist[src] = 0
        h = [(0, src)]
        while h:
            d, u = heapq.heappop(h)
            if d > dist[u]: continue
            for v, w in g[u]:
                nd = d + w
                if nd < dist[v]: dist[v] = nd; heapq.heappush(h, (nd, v))
        return dist
    ds = dijkstra(start)
    dw = dijkstra(waypoint)
    best = ds[target] if ds[target] != float('inf') else -1
    if ds[waypoint] == float('inf') or dw[target] == float('inf'):
        via = -1
    else:
        via = ds[waypoint] + dw[target]
    return [best, via]

import java.util.*;
class Solution {
    public long[] shortestPathWithWaypoint(int n, int[][] edges, int start, int target, int waypoint) {
        List<long[]>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) { g[e[0]].add(new long[]{e[1], e[2]}); g[e[1]].add(new long[]{e[0], e[2]}); }
        long[] ds = dijkstra(g, start, n);
        long[] dw = dijkstra(g, waypoint, n);
        long INF = Long.MAX_VALUE;
        long best = ds[target] == INF ? -1 : ds[target];
        long via = (ds[waypoint] == INF || dw[target] == INF) ? -1 : ds[waypoint] + dw[target];
        return new long[]{best, via};
    }
    long[] dijkstra(List<long[]>[] g, int src, int n) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] p = pq.poll();
            long d = p[0]; int u = (int) p[1];
            if (d > dist[u]) continue;
            for (long[] e : g[u]) {
                long nd = d + e[1];
                if (nd < dist[(int) e[0]]) { dist[(int) e[0]] = nd; pq.offer(new long[]{nd, e[0]}); }
            }
        }
        return dist;
    }
}

#include <vector>
#include <queue>
#include <climits>
using namespace std;
class Solution {
    vector<long long> dijkstra(vector<vector<pair<int,long long>>>& g, int src, int n) {
        vector<long long> dist(n, LLONG_MAX);
        dist[src] = 0;
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        pq.push({0, src});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : g[u]) {
                long long nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; pq.push({nd, v}); }
            }
        }
        return dist;
    }
public:
    vector<long long> shortestPathWithWaypoint(int n, vector<vector<int>>& edges, int start, int target, int waypoint) {
        vector<vector<pair<int,long long>>> g(n);
        for (auto& e : edges) { g[e[0]].push_back({e[1], e[2]}); g[e[1]].push_back({e[0], e[2]}); }
        auto ds = dijkstra(g, start, n);
        auto dw = dijkstra(g, waypoint, n);
        long long best = ds[target] == LLONG_MAX ? -1 : ds[target];
        long long via = (ds[waypoint] == LLONG_MAX || dw[target] == LLONG_MAX) ? -1 : ds[waypoint] + dw[target];
        return {best, via};
    }
};

def calculateTime(keyboard, text):
    pos = {c: i for i, c in enumerate(keyboard)}
    prev = 0; total = 0
    for c in text:
        total += abs(pos[c] - prev)
        prev = pos[c]
    return total

class Solution {
