from collections import defaultdict

def friendRecommend(n, friendships):
    adj = defaultdict(set)
    for u, v in friendships:
        adj[u].add(v); adj[v].add(u)
    res = []
    for y in range(n):
        mutual = defaultdict(int)
        for f in adj[y]:
            for x in adj[f]:
                if x != y and x not in adj[y]:
                    mutual[x] += 1
        if not mutual:
            res.append(-1)
        else:
            best = -1; bestM = -1
            for x, c in mutual.items():
                if c > bestM or (c == bestM and x < best):
                    bestM = c; best = x
            res.append(best)
    return res

import java.util.*;
class Solution {
    public int[] friendRecommend(int n, int[][] friendships) {
        List<Set<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new HashSet<>());
        for (int[] e : friendships) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] res = new int[n];
        for (int y = 0; y < n; y++) {
            Map<Integer, Integer> mutual = new HashMap<>();
            for (int f : adj.get(y)) for (int x : adj.get(f)) {
                if (x != y && !adj.get(y).contains(x)) mutual.merge(x, 1, Integer::sum);
            }
            if (mutual.isEmpty()) { res[y] = -1; continue; }
            int best = -1, bestM = -1;
            for (var e : mutual.entrySet()) {
                int c = e.getValue(), x = e.getKey();
                if (c > bestM || (c == bestM && x < best)) { bestM = c; best = x; }
            }
            res[y] = best;
        }
        return res;
    }
}

