def splitAndSort(A):
    n = len(A)
    if n < 2: return 0
    pmax = [0] * n; smin = [0] * n
    pmax[0] = A[0]
    for i in range(1, n): pmax[i] = max(pmax[i - 1], A[i])
    smin[-1] = A[-1]
    for i in range(n - 2, -1, -1): smin[i] = min(smin[i + 1], A[i])
    return sum(1 for i in range(n - 1) if pmax[i] <= smin[i + 1])

class Solution {
    public int splitAndSort(int[] A) {
        int n = A.length;
        if (n < 2) return 0;
        int[] pm = new int[n], sm = new int[n];
        pm[0] = A[0];
        for (int i = 1; i < n; i++) pm[i] = Math.max(pm[i - 1], A[i]);
        sm[n - 1] = A[n - 1];
        for (int i = n - 2; i >= 0; i--) sm[i] = Math.min(sm[i + 1], A[i]);
        int ans = 0;
        for (int i = 0; i + 1 < n; i++) if (pm[i] <= sm[i + 1]) ans++;
        return ans;
    }
}

