from bisect import bisect_left

def minDecreasingSubsequences(nums):
    tails = []  # 每条子序列当前尾值；保持升序
    for v in nums:
        i = bisect_left(tails, v)
        if i == len(tails):
            tails.append(v)
        else:
            tails[i] = v
    return len(tails)

import java.util.*;
class Solution {
    public int minDecreasingSubsequences(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int v : nums) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails.get(mid) < v) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(v);
            else tails.set(lo, v);
        }
        return tails.size();
    }
}

