            auto it = lower_bound(tails.begin(), tails.end(), v);
            if (it == tails.end()) tails.push_back(v);
            else *it = v;
        }
        return tails.size();
    }
};

import java.util.*;
class Solution {
    public List<String> textJustification(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        int i = 0, n = words.length;
        while (i < n) {
            int j = i, lineLen = 0;
            while (j < n && lineLen + words[j].length() + (j - i) <= maxWidth) { lineLen += words[j].length(); j++; }
            int gaps = j - i - 1;
            boolean isLast = j == n;
            StringBuilder sb = new StringBuilder();
            if (gaps == 0 || isLast) {
                for (int k = i; k < j; k++) { sb.append(words[k]); if (k + 1 < j) sb.append(' '); }
                while (sb.length() < maxWidth) sb.append(' ');
            } else {
                int totalSpaces = maxWidth - lineLen;
                int base = totalSpaces / gaps, extra = totalSpaces % gaps;
                for (int k = i; k < j - 1; k++) {
                    sb.append(words[k]);
                    int sp = base + ((k - i) < extra ? 1 : 0);
                    for (int x = 0; x < sp; x++) sb.append(' ');
                }
                sb.append(words[j - 1]);
            }
            res.add(sb.toString());
            i = j;
        }
        return res;
    }
}

