def ticTacToeStatus(k, n, moves):
    board = [[0] * n for _ in range(n)]
    winner = 0; filled = 0
    res = []
    for player, r, c in moves:
        if winner != 0:
            res.append("Game Over"); continue
        if board[r][c] != 0:
            res.append("Invalid Move"); continue
        board[r][c] = player; filled += 1
        # 检查四方向
        def line(dr, dc):
            cnt = 1
            x, y = r + dr, c + dc
            while 0 <= x < n and 0 <= y < n and board[x][y] == player:
                cnt += 1; x += dr; y += dc
            x, y = r - dr, c - dc
            while 0 <= x < n and 0 <= y < n and board[x][y] == player:
                cnt += 1; x -= dr; y -= dc
            return cnt
        if max(line(0,1), line(1,0), line(1,1), line(1,-1)) >= 3:
            winner = player
            res.append(f"Player {player} won")
        elif filled == n * n:
            res.append("Draw")
        else:
            res.append("In Progress")
    return res

import java.util.*;
class Solution {
    int n; int[][] board; int player;
    int line(int r, int c, int dr, int dc) {
        int cnt = 1, x = r + dr, y = c + dc;
        while (x >= 0 && x < n && y >= 0 && y < n && board[x][y] == player) { cnt++; x += dr; y += dc; }
        x = r - dr; y = c - dc;
        while (x >= 0 && x < n && y >= 0 && y < n && board[x][y] == player) { cnt++; x -= dr; y -= dc; }
        return cnt;
    }
    public List<String> ticTacToeStatus(int k, int N, int[][] moves) {
        n = N; board = new int[n][n];
        int winner = 0, filled = 0;
        List<String> res = new ArrayList<>();
        for (int[] mv : moves) {
            int p = mv[0], r = mv[1], c = mv[2];
            player = p;
            if (winner != 0) { res.add("Game Over"); continue; }
            if (board[r][c] != 0) { res.add("Invalid Move"); continue; }
            board[r][c] = p; filled++;
            int best = Math.max(Math.max(line(r,c,0,1), line(r,c,1,0)), Math.max(line(r,c,1,1), line(r,c,1,-1)));
            if (best >= 3) { winner = p; res.add("Player " + p + " won"); }
            else if (filled == n * n) res.add("Draw");
            else res.add("In Progress");
        }
        return res;
    }
}

