from collections import deque

def transformString(str1, str2):
    if len(str1) != len(str2): return -1
    n = len(str1)
    def valid(s):
        for i in range(1, n):
            if s[i] == s[i - 1]: return False
        return True
    if str1 == str2: return 0
    seen = {str1: 0}
    q = deque([str1])
    while q:
        cur = q.popleft()
        d = seen[cur]
        if d > 30: continue
        for i in range(n):
            for ch in 'xyz':
                if ch == cur[i]: continue
                if i > 0 and cur[i - 1] == ch: continue
                if i + 1 < n and cur[i + 1] == ch: continue
                nxt = cur[:i] + ch + cur[i + 1:]
                if nxt == str2: return d + 1
                if nxt not in seen:
                    seen[nxt] = d + 1
                    q.append(nxt)
    return -1

import java.util.*;
class Solution {
    public int transformString(String str1, String str2) {
        if (str1.length() != str2.length()) return -1;
        int n = str1.length();
        if (str1.equals(str2)) return 0;
        Map<String, Integer> seen = new HashMap<>();
        seen.put(str1, 0);
        Deque<String> q = new ArrayDeque<>();
        q.add(str1);
        char[] alpha = {'x','y','z'};
        while (!q.isEmpty()) {
            String cur = q.poll();
            int d = seen.get(cur);
            if (d > 30) continue;
            char[] arr = cur.toCharArray();
            for (int i = 0; i < n; i++) {
                char orig = arr[i];
                for (char ch : alpha) {
                    if (ch == orig) continue;
                    if (i > 0 && arr[i - 1] == ch) continue;
                    if (i + 1 < n && arr[i + 1] == ch) continue;
                    arr[i] = ch;
                    String nxt = new String(arr);
                    if (nxt.equals(str2)) return d + 1;
                    if (!seen.containsKey(nxt)) { seen.put(nxt, d + 1); q.add(nxt); }
                }
                arr[i] = orig;
            }
        }
        return -1;
    }
}

