def substituteTemplates(subs, template):
    visiting = set()
    def resolve(text):
        out = []; i = 0
        while i < len(text):
            if text[i] == '%':
                j = text.find('%', i + 1)
                if j == -1:
                    out.append(text[i:]); break
                key = text[i + 1:j]
                if key in visiting:
                    raise ValueError("cycle")
                visiting.add(key)
                out.append(resolve(subs.get(key, '')))
                visiting.discard(key)
                i = j + 1
            else:
                out.append(text[i]); i += 1
        return ''.join(out)
    return resolve(template)

import java.util.*;
class Solution {
    Map<String, String> subs;
    Set<String> visiting = new HashSet<>();
    String resolve(String text) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            if (text.charAt(i) == '%') {
                int j = text.indexOf('%', i + 1);
                if (j == -1) { out.append(text.substring(i)); break; }
                String key = text.substring(i + 1, j);
                if (visiting.contains(key)) throw new RuntimeException("cycle");
                visiting.add(key);
                out.append(resolve(subs.getOrDefault(key, "")));
                visiting.remove(key);
                i = j + 1;
            } else {
                out.append(text.charAt(i)); i++;
            }
        }
        return out.toString();
    }
    public String substituteTemplates(Map<String, String> substitutions, String template) {
        subs = substitutions;
        return resolve(template);
    }
}

