using namespace std;
class Solution {
    unordered_map<string, string> subs;
    unordered_set<string> visiting;
    string resolve(const string& text) {
        string out;
        int i = 0;
        while (i < (int)text.size()) {
            if (text[i] == '%') {
                int j = text.find('%', i + 1);
                if (j == (int)string::npos) { out += text.substr(i); break; }
                string key = text.substr(i + 1, j - i - 1);
                if (visiting.count(key)) throw runtime_error("cycle");
                visiting.insert(key);
                auto it = subs.find(key);
                out += resolve(it != subs.end() ? it->second : "");
                visiting.erase(key);
                i = j + 1;
            } else {
                out += text[i]; i++;
            }
        }
        return out;
    }
public:
    string substituteTemplates(unordered_map<string, string>& substitutions, string templ) {
        subs = substitutions;
        return resolve(templ);
    }
};

def solution(board: list[list[str]]) -> int:
    rows, cols = len(board), len(board[0])
    ans = float('inf')

    for c in range(cols):
        # 找到该列最底下的 '*' 行号
        bottom_star = -1
        for r in range(rows):
            if board[r][c] == '*':
                bottom_star = r
        if bottom_star == -1:
            continue  # 这一列没有图形格子，跳过

        # 数从 bottom_star + 1 到 rows - 1 之间 '#' 的个数
        obstacles = 0
        for r in range(bottom_star + 1, rows):
            if board[r][c] == '#':
                obstacles += 1
        ans = min(ans, obstacles)

    return ans if ans != float('inf') else 0

