def solution(numbers: list[int], pattern: list[int]) -> int:
    n, m = len(numbers), len(pattern)
    count = 0

    # 枚举每个长度 m+1 的子数组起点
    for i in range(n - m):
        ok = True
        for j in range(m):
            diff = numbers[i + j + 1] - numbers[i + j]
            # diff 的正负号必须与 pattern[j] 一致
            if pattern[j] == 1 and diff <= 0:
                ok = False
                break
            if pattern[j] == 0 and diff != 0:
                ok = False
                break
            if pattern[j] == -1 and diff >= 0:
                ok = False
                break
        if ok:
            count += 1

    return count

