        int count = 0;

        // 枚举每个长度 m+1 的子数组起点
        for (int i = 0; i <= n - m - 1; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                int diff = numbers[i + j + 1] - numbers[i + j];
