def solution(schedules: list[list[int]], length: int) -> int:
    DAY = 1440
    busy = [False] * DAY                    # busy[t] = 时刻 t 被占用

    # 把所有员工的占用时段标记到时间线上（半开区间 [start, finish)）
    for sched in schedules:
        for i in range(0, len(sched), 2):
            start, finish = sched[i], sched[i + 1]
            for t in range(start, finish):
                busy[t] = True

    # 找第一个长度 length 的全空白窗口
    consecutive = 0                         # 连续空闲分钟数
    for t in range(DAY):
        if not busy[t]:
            consecutive += 1
            if consecutive >= length:
                return t - length + 1
        else:
            consecutive = 0

    return -1

class Solution {
