        final int DAY = 1440;
        boolean[] busy = new boolean[DAY];  // busy[t] = 时刻 t 被占用

        // 把所有员工的占用时段标记到时间线上（半开区间 [start, finish)）
        for (int[] sched : schedules) {
            for (int i = 0; i < sched.length; i += 2) {
                int start = sched[i], finish = sched[i + 1];
                for (int t = start; t < finish; t++) busy[t] = true;
            }
        }

        // 找第一个长度 length 的全空白窗口
        int consecutive = 0;
        for (int t = 0; t < DAY; t++) {
            if (!busy[t]) {
                consecutive++;
                if (consecutive >= length) return t - length + 1;
            } else {
                consecutive = 0;
            }
        }
        return -1;
    }
}

