import java.util.*;

class Solution {
    int solution(int[] salesData, int frequencyThreshold) {
        int n = salesData.length;
        // 记录每个值的所有出现位置
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < n; i++) {
            pos.computeIfAbsent(salesData[i], k -> new ArrayList<>()).add(i);
        }

        int ans = 0;
        for (var entry : pos.entrySet()) {
            List<Integer> positions = entry.getValue();
            int k = positions.size();
            if (k < frequencyThreshold) continue;
            // 枚举"恰好用 v 的连续 frequencyThreshold 次出现"的所有窗口
            for (int i = 0; i <= k - frequencyThreshold; i++) {
                int left = i > 0 ? positions.get(i - 1) + 1 : 0;
                int j = i + frequencyThreshold;
                int right = j < k ? positions.get(j) - 1 : n - 1;
                ans = Math.max(ans, right - left + 1);
            }
        }
        return ans;
    }
}

