import java.util.*;

class Solution {
    String solution(String message) {
        Set<Character> VOWELS = Set.of('a', 'e', 'i', 'o', 'u');
        char[] chars = message.toCharArray();

        // 收集所有元音位置
        List<Integer> pos = new ArrayList<>();
        for (int i = 0; i < chars.length; i++) {
            if (VOWELS.contains(chars[i])) pos.add(i);
        }
        if (pos.size() <= 1) return message;    // 0 或 1 个元音，无可移动

        // 循环右移：新位置 pos[i] 上的字母 = 旧位置 pos[(i-1+k)%k] 上的字母
        int k = pos.size();
        char[] vowels = new char[k];
        for (int i = 0; i < k; i++) vowels[i] = chars[pos.get(i)];

        for (int i = 0; i < k; i++) {
            int from = (i - 1 + k) % k;
            chars[pos.get(i)] = vowels[from];
        }
        return new String(chars);
    }
}

