        for (int i = 0; i < k; i++) {
            int from = (i - 1 + k) % k;
            message[pos[i]] = vowels[from];
        }
        return message;
    }
};

import java.util.*;

class Solution {
    int[] solution(int[] queries) {
        // leftEnd[x] = x 所在段的左端；rightEnd[x] = x 所在段的右端
        Map<Integer, Integer> leftEnd = new HashMap<>();
        Map<Integer, Integer> rightEnd = new HashMap<>();
        Set<Integer> built = new HashSet<>();

        int n = queries.length;
        int[] ans = new int[n];
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            int x = queries[i];
            built.add(x);

            int newLeft = x;
            if (built.contains(x - 1)) newLeft = leftEnd.get(x - 1);

            int newRight = x;
            if (built.contains(x + 1)) newRight = rightEnd.get(x + 1);

            rightEnd.put(newLeft, newRight);
            leftEnd.put(newRight, newLeft);

            maxLen = Math.max(maxLen, newRight - newLeft + 1);
            ans[i] = maxLen;
        }
        return ans;
    }
}

