#include <unordered_set>
#include <vector>
using namespace std;

class Solution {
public:
    vector<int> solution(vector<int>& queries) {
        // leftEnd[x] = x 所在段的左端；rightEnd[x] = x 所在段的右端
        unordered_map<int, int> leftEnd, rightEnd;
        unordered_set<int> built;

        int n = queries.size();
        vector<int> ans(n);
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            int x = queries[i];
            built.insert(x);

            int newLeft = x;
            if (built.count(x - 1)) newLeft = leftEnd[x - 1];

            int newRight = x;
            if (built.count(x + 1)) newRight = rightEnd[x + 1];

            rightEnd[newLeft] = newRight;
            leftEnd[newRight] = newLeft;

            maxLen = max(maxLen, newRight - newLeft + 1);
            ans[i] = maxLen;
        }
        return ans;
    }
};

def solution(matrix: list[list[int]], commands: list[str]) -> list[list[int]]:
    def swap_rows(r1: int, r2: int) -> None:
        matrix[r1], matrix[r2] = matrix[r2], matrix[r1]

    def swap_columns(c1: int, c2: int) -> None:
        for row in matrix:
            row[c1], row[c2] = row[c2], row[c1]

    def reverse_row(r: int) -> None:
        matrix[r].reverse()

    def reverse_column(c: int) -> None:
        i, j = 0, len(matrix) - 1
        while i < j:
            matrix[i][c], matrix[j][c] = matrix[j][c], matrix[i][c]
            i += 1
            j -= 1

    def rotate90_clockwise() -> None:
        n = len(matrix)
        # 转置（上三角与下三角交换）
        for i in range(n):
            for j in range(i + 1, n):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
        # 每行反转
        for row in matrix:
            row.reverse()

    for cmd in commands:
        parts = cmd.split()
        op = parts[0]
        if op == 'swapRows':
            swap_rows(int(parts[1]), int(parts[2]))
        elif op == 'swapColumns':
            swap_columns(int(parts[1]), int(parts[2]))
        elif op == 'reverseRow':
            reverse_row(int(parts[1]))
        elif op == 'reverseColumn':
            reverse_column(int(parts[1]))
        elif op == 'rotate90Clockwise':
            rotate90_clockwise()

    return matrix

class Solution {
    int[][] m;                                  // 共享矩阵指针

    int[][] solution(int[][] matrix, String[] commands) {
        m = matrix;
        for (String cmd : commands) {
            String[] parts = cmd.split(" ");
            String op = parts[0];
            switch (op) {
                case "swapRows" -> swapRows(Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
                case "swapColumns" -> swapColumns(Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
                case "reverseRow" -> reverseRow(Integer.parseInt(parts[1]));
                case "reverseColumn" -> reverseColumn(Integer.parseInt(parts[1]));
                case "rotate90Clockwise" -> rotate90Clockwise();
            }
        }
        return m;
    }

    void swapRows(int r1, int r2) {
        int[] tmp = m[r1]; m[r1] = m[r2]; m[r2] = tmp;
    }

    void swapColumns(int c1, int c2) {
        for (int[] row : m) {
            int tmp = row[c1]; row[c1] = row[c2]; row[c2] = tmp;
        }
    }

    void reverseRow(int r) {
        int i = 0, j = m[r].length - 1;
        while (i < j) {
            int tmp = m[r][i]; m[r][i] = m[r][j]; m[r][j] = tmp;
            i++; j--;
        }
    }

    void reverseColumn(int c) {
        int i = 0, j = m.length - 1;
        while (i < j) {
            int tmp = m[i][c]; m[i][c] = m[j][c]; m[j][c] = tmp;
            i++; j--;
        }
    }

    void rotate90Clockwise() {
        int n = m.length;
        // 转置（上三角与下三角交换）
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int tmp = m[i][j]; m[i][j] = m[j][i]; m[j][i] = tmp;
            }
        }
        // 每行反转
        for (int i = 0; i < n; i++) reverseRow(i);
    }
}

#include <vector>
#include <string>
#include <sstream>
using namespace std;

class Solution {
public:
    vector<vector<int>> solution(vector<vector<int>> matrix, vector<string> commands) {
        for (auto& cmd : commands) {
            istringstream iss(cmd);
            string op;
            iss >> op;
            if (op == "swapRows") {
                int r1, r2; iss >> r1 >> r2;
                swap(matrix[r1], matrix[r2]);
            } else if (op == "swapColumns") {
                int c1, c2; iss >> c1 >> c2;
                for (auto& row : matrix) swap(row[c1], row[c2]);
            } else if (op == "reverseRow") {
                int r; iss >> r;
                reverse(matrix[r].begin(), matrix[r].end());
            } else if (op == "reverseColumn") {
                int c; iss >> c;
                int i = 0, j = (int) matrix.size() - 1;
                while (i < j) { swap(matrix[i][c], matrix[j][c]); i++; j--; }
            } else if (op == "rotate90Clockwise") {
                int n = matrix.size();
                // 转置（上三角与下三角交换）
                for (int i = 0; i < n; i++) {
                    for (int j = i + 1; j < n; j++) {
                        swap(matrix[i][j], matrix[j][i]);
                    }
                }
                // 每行反转
                for (auto& row : matrix) reverse(row.begin(), row.end());
            }
        }
        return matrix;
    }
};

def solution(left: int, right: int) -> int:
