import java.util.*;

public class BankingSystem {
    private static final long MILLIS_IN_DAY = 86_400_000L;

    private final Map<String, Long> balance = new HashMap<>();          // 活账户 -> 余额
    private final Map<String, Long> outgoing = new HashMap<>();         // 活账户 -> 累计出账
    private final Map<String, String> alias = new HashMap<>();          // 旧 id -> 当前主账户
    private final Map<String, TreeMap<Long, Long>> history = new HashMap<>();
    private final Map<String, Long> mergedAt = new HashMap<>();         // 被合并的账户 -> 合并时刻
    private final Map<String, String> paymentOwner = new HashMap<>();
    private final Map<String, String> paymentStatus = new HashMap<>();

    private record Cashback(long refundTime, long seq, String ownerAtCreation, String paymentId, long refundAmt)
            implements Comparable<Cashback> {
        public int compareTo(Cashback o) {
            int c = Long.compare(refundTime, o.refundTime);
            return c != 0 ? c : Long.compare(seq, o.seq);
        }
    }

    private final PriorityQueue<Cashback> cashbackQueue = new PriorityQueue<>();
    private long cashbackSeq = 0;
    private long paymentCounter = 0;

    // ---------- 内部工具 ----------
    private Optional<String> resolve(String accountId) {
        String cur = accountId;
        while (alias.containsKey(cur)) cur = alias.get(cur);
        return balance.containsKey(cur) ? Optional.of(cur) : Optional.empty();
    }

    private void log(String accountId, long timestamp) {
        history.get(accountId).put(timestamp, balance.get(accountId));
    }

    private void flushCashback(long currentTimestamp) {
        while (!cashbackQueue.isEmpty() && cashbackQueue.peek().refundTime <= currentTimestamp) {
            Cashback cb = cashbackQueue.poll();
            Optional<String> target = resolve(cb.ownerAtCreation);
            if (target.isEmpty()) continue;
            String t = target.get();
            balance.put(t, balance.get(t) + cb.refundAmt);
            log(t, cb.refundTime);
            paymentStatus.put(cb.paymentId, "CASHBACK_RECEIVED");
        }
    }

    // ---------- Level 1 ----------
    public boolean createAccount(int timestamp, String accountId) {
        flushCashback(timestamp);
        if (balance.containsKey(accountId) || alias.containsKey(accountId)) return false;
        balance.put(accountId, 0L);
        outgoing.put(accountId, 0L);
        history.put(accountId, new TreeMap<>());
        log(accountId, timestamp);
        return true;
    }

    public Optional<Integer> deposit(int timestamp, String accountId, int amount) {
        flushCashback(timestamp);
        Optional<String> opt = resolve(accountId);
        if (opt.isEmpty()) return Optional.empty();
        String t = opt.get();
        balance.put(t, balance.get(t) + amount);
        log(t, timestamp);
        return Optional.of(balance.get(t).intValue());
    }

    public Optional<Integer> transfer(int timestamp, String sourceId, String targetId, int amount) {
        flushCashback(timestamp);
        Optional<String> srcOpt = resolve(sourceId);
        Optional<String> dstOpt = resolve(targetId);
        if (srcOpt.isEmpty() || dstOpt.isEmpty()) return Optional.empty();
        String src = srcOpt.get(), dst = dstOpt.get();
        if (src.equals(dst)) return Optional.empty();
        if (balance.get(src) < amount) return Optional.empty();
        balance.put(src, balance.get(src) - amount);
        balance.put(dst, balance.get(dst) + amount);
        outgoing.put(src, outgoing.get(src) + amount);
        log(src, timestamp);
        log(dst, timestamp);
        return Optional.of(balance.get(src).intValue());
    }

    // ---------- Level 2 ----------
    public List<String> topSpenders(int timestamp, int n) {
        flushCashback(timestamp);
        List<Map.Entry<String, Long>> items = new ArrayList<>(outgoing.entrySet());
        items.sort((a, b) -> {
            int c = Long.compare(b.getValue(), a.getValue());
            return c != 0 ? c : a.getKey().compareTo(b.getKey());
        });
        List<String> result = new ArrayList<>();
        for (int i = 0; i < Math.min(n, items.size()); i++) {
            result.add(items.get(i).getKey() + "(" + items.get(i).getValue() + ")");
        }
        return result;
    }

    // ---------- Level 3 ----------
    public Optional<String> pay(int timestamp, String accountId, int amount) {
        flushCashback(timestamp);
        Optional<String> opt = resolve(accountId);
        if (opt.isEmpty()) return Optional.empty();
        String t = opt.get();
        if (balance.get(t) < amount) return Optional.empty();
        balance.put(t, balance.get(t) - amount);
        outgoing.put(t, outgoing.get(t) + amount);
        log(t, timestamp);
        paymentCounter++;
        String paymentId = "payment" + paymentCounter;
        paymentOwner.put(paymentId, t);
        paymentStatus.put(paymentId, "IN_PROGRESS");
        long refundAmt = (long) amount * 2 / 100;
        cashbackSeq++;
        cashbackQueue.add(new Cashback(timestamp + MILLIS_IN_DAY, cashbackSeq, t, paymentId, refundAmt));
        return Optional.of(paymentId);
    }

    public Optional<String> getPaymentStatus(int timestamp, String accountId, String payment) {
        flushCashback(timestamp);
        Optional<String> opt = resolve(accountId);
        if (opt.isEmpty() || !paymentOwner.containsKey(payment)) return Optional.empty();
        Optional<String> ownerNow = resolve(paymentOwner.get(payment));
        if (ownerNow.isEmpty() || !ownerNow.get().equals(opt.get())) return Optional.empty();
        return Optional.of(paymentStatus.get(payment));
    }

    // ---------- Level 4 ----------
    public boolean mergeAccounts(int timestamp, String accountId1, String accountId2) {
        flushCashback(timestamp);
        if (accountId1.equals(accountId2)) return false;
        Optional<String> a1Opt = resolve(accountId1);
        Optional<String> a2Opt = resolve(accountId2);
        if (a1Opt.isEmpty() || a2Opt.isEmpty()) return false;
        String a1 = a1Opt.get(), a2 = a2Opt.get();
        if (a1.equals(a2)) return false;
        balance.put(a1, balance.get(a1) + balance.get(a2));
        outgoing.put(a1, outgoing.get(a1) + outgoing.get(a2));
        log(a1, timestamp);
        mergedAt.put(a2, (long) timestamp);
        alias.put(a2, a1);
        balance.remove(a2);
        outgoing.remove(a2);
        return true;
    }

    public Optional<Integer> getBalance(int timestamp, String accountId, int timeAt) {
        flushCashback(timestamp);
        if (balance.containsKey(accountId)) {
            TreeMap<Long, Long> log = history.get(accountId);
            Map.Entry<Long, Long> e = log.floorEntry((long) timeAt);
            return e == null ? Optional.empty() : Optional.of(e.getValue().intValue());
        }
        if (mergedAt.containsKey(accountId)) {
            long mergeTime = mergedAt.get(accountId);
            if (timeAt >= mergeTime) return Optional.empty();
            TreeMap<Long, Long> log = history.get(accountId);
            Map.Entry<Long, Long> e = log.floorEntry((long) timeAt);
            return e == null ? Optional.empty() : Optional.of(e.getValue().intValue());
        }
        return Optional.empty();
    }
}

#include <map>
#include <queue>
#include <string>
#include <vector>
#include <optional>
#include <unordered_map>
#include <algorithm>

class BankingSystem {
    static constexpr long long MILLIS_IN_DAY = 86'400'000LL;

    std::unordered_map<std::string, long long> balance;
    std::unordered_map<std::string, long long> outgoing;
    std::unordered_map<std::string, std::string> alias;
    std::unordered_map<std::string, std::map<long long, long long>> history;
    std::unordered_map<std::string, long long> mergedAt;
    std::unordered_map<std::string, std::string> paymentOwner;
    std::unordered_map<std::string, std::string> paymentStatus;

    struct Cashback {
        long long refundTime;
        long long seq;
        std::string ownerAtCreation;
        std::string paymentId;
        long long refundAmt;
        bool operator>(const Cashback& o) const {
            if (refundTime != o.refundTime) return refundTime > o.refundTime;
            return seq > o.seq;
        }
    };
    std::priority_queue<Cashback, std::vector<Cashback>, std::greater<Cashback>> cashbackQueue;
    long long cashbackSeq = 0;
    long long paymentCounter = 0;

    std::optional<std::string> resolve(const std::string& accountId) {
        std::string cur = accountId;
        while (alias.count(cur)) cur = alias[cur];
        if (balance.count(cur)) return cur;
        return std::nullopt;
    }

    void logBalance(const std::string& accountId, long long timestamp) {
        history[accountId][timestamp] = balance[accountId];
    }

    void flushCashback(long long currentTimestamp) {
        while (!cashbackQueue.empty() && cashbackQueue.top().refundTime <= currentTimestamp) {
            Cashback cb = cashbackQueue.top();
            cashbackQueue.pop();
            auto target = resolve(cb.ownerAtCreation);
            if (!target) continue;
            balance[*target] += cb.refundAmt;
            logBalance(*target, cb.refundTime);
            paymentStatus[cb.paymentId] = "CASHBACK_RECEIVED";
        }
    }

public:
    // ---------- Level 1 ----------
    bool createAccount(int timestamp, const std::string& accountId) {
        flushCashback(timestamp);
        if (balance.count(accountId) || alias.count(accountId)) return false;
        balance[accountId] = 0;
        outgoing[accountId] = 0;
        history[accountId] = {};
        logBalance(accountId, timestamp);
        return true;
    }

    std::optional<int> deposit(int timestamp, const std::string& accountId, int amount) {
        flushCashback(timestamp);
        auto opt = resolve(accountId);
        if (!opt) return std::nullopt;
        balance[*opt] += amount;
        logBalance(*opt, timestamp);
        return static_cast<int>(balance[*opt]);
    }

    std::optional<int> transfer(int timestamp, const std::string& sourceId,
                                const std::string& targetId, int amount) {
        flushCashback(timestamp);
        auto src = resolve(sourceId);
        auto dst = resolve(targetId);
        if (!src || !dst || *src == *dst) return std::nullopt;
        if (balance[*src] < amount) return std::nullopt;
        balance[*src] -= amount;
        balance[*dst] += amount;
        outgoing[*src] += amount;
        logBalance(*src, timestamp);
        logBalance(*dst, timestamp);
        return static_cast<int>(balance[*src]);
    }

    // ---------- Level 2 ----------
    std::vector<std::string> topSpenders(int timestamp, int n) {
        flushCashback(timestamp);
        std::vector<std::pair<std::string, long long>> items(outgoing.begin(), outgoing.end());
        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
            if (a.second != b.second) return a.second > b.second;
            return a.first < b.first;
        });
        std::vector<std::string> result;
        for (int i = 0; i < std::min<int>(n, items.size()); i++) {
            result.push_back(items[i].first + "(" + std::to_string(items[i].second) + ")");
        }
        return result;
    }

    // ---------- Level 3 ----------
    std::optional<std::string> pay(int timestamp, const std::string& accountId, int amount) {
        flushCashback(timestamp);
        auto opt = resolve(accountId);
        if (!opt) return std::nullopt;
        if (balance[*opt] < amount) return std::nullopt;
        balance[*opt] -= amount;
        outgoing[*opt] += amount;
        logBalance(*opt, timestamp);
        paymentCounter++;
        std::string paymentId = "payment" + std::to_string(paymentCounter);
        paymentOwner[paymentId] = *opt;
        paymentStatus[paymentId] = "IN_PROGRESS";
        long long refundAmt = static_cast<long long>(amount) * 2 / 100;
        cashbackSeq++;
        cashbackQueue.push({static_cast<long long>(timestamp) + MILLIS_IN_DAY, cashbackSeq, *opt, paymentId, refundAmt});
        return paymentId;
    }

    std::optional<std::string> getPaymentStatus(int timestamp, const std::string& accountId,
                                                 const std::string& payment) {
        flushCashback(timestamp);
        auto opt = resolve(accountId);
        if (!opt || !paymentOwner.count(payment)) return std::nullopt;
        auto ownerNow = resolve(paymentOwner[payment]);
        if (!ownerNow || *ownerNow != *opt) return std::nullopt;
        return paymentStatus[payment];
    }

    // ---------- Level 4 ----------
    bool mergeAccounts(int timestamp, const std::string& accountId1, const std::string& accountId2) {
        flushCashback(timestamp);
        if (accountId1 == accountId2) return false;
        auto a1 = resolve(accountId1);
        auto a2 = resolve(accountId2);
        if (!a1 || !a2 || *a1 == *a2) return false;
        balance[*a1] += balance[*a2];
        outgoing[*a1] += outgoing[*a2];
        logBalance(*a1, timestamp);
        mergedAt[*a2] = timestamp;
        alias[*a2] = *a1;
        balance.erase(*a2);
        outgoing.erase(*a2);
        return true;
    }

    std::optional<int> getBalance(int timestamp, const std::string& accountId, int timeAt) {
        flushCashback(timestamp);
        if (balance.count(accountId)) {
            auto& log = history[accountId];
            auto it = log.upper_bound(static_cast<long long>(timeAt));
            if (it == log.begin()) return std::nullopt;
            --it;
            return static_cast<int>(it->second);
        }
        if (mergedAt.count(accountId)) {
            long long mergeTime = mergedAt[accountId];
            if (timeAt >= mergeTime) return std::nullopt;
            auto& log = history[accountId];
            auto it = log.upper_bound(static_cast<long long>(timeAt));
            if (it == log.begin()) return std::nullopt;
            --it;
            return static_cast<int>(it->second);
        }
        return std::nullopt;
    }
};

from typing import List
from sortedcontainers import SortedList

def buildingBlocks(operations: List[List[int]]) -> str:
    obs = SortedList()
    out = []
    for op in operations:
        if op[0] == 1:
            obs.add(op[1])
        else:
            x, size = op[1], op[2]
            idx = obs.bisect_left(x)
            if idx == len(obs) or obs[idx] > x + size - 1:
                out.append('1')
            else:
                out.append('0')
    return ''.join(out)

class Solution {
    String buildingBlocks(int[][] operations) {
        TreeSet<Integer> obs = new TreeSet<>();
        StringBuilder out = new StringBuilder();
        for (int[] op : operations) {
            if (op[0] == 1) obs.add(op[1]);
            else {
                int x = op[1], size = op[2];
                Integer c = obs.ceiling(x);
                out.append((c == null || c > x + size - 1) ? '1' : '0');
            }
        }
        return out.toString();
    }
}

class Solution {
public:
    string buildingBlocks(vector<vector<int>>& operations) {
        set<int> obs;
        string out;
        for (auto& op : operations) {
            if (op[0] == 1) obs.insert(op[1]);
            else {
                int x = op[1], size = op[2];
                auto it = obs.lower_bound(x);
                out += (it == obs.end() || *it > x + size - 1) ? '1' : '0';
            }
        }
        return out;
    }
};

class Solution {
    int computeDifference(String text) {
        int up = 0, lo = 0;
        for (char c : text.toCharArray()) {
            if (Character.isUpperCase(c)) up++;
            else if (Character.isLowerCase(c)) lo++;
        }
        return up - lo;
    }
}

