from typing import List

def findDiagonalOrder(mat: List[List[int]]) -> List[int]:
    m, n = len(mat), len(mat[0])
    res = []
    for d in range(m + n - 1):
        if d % 2 == 0:
            i = min(d, m - 1)
            j = d - i
            while i >= 0 and j < n:
                res.append(mat[i][j])
                i -= 1
                j += 1
        else:
            j = min(d, n - 1)
            i = d - j
            while j >= 0 and i < m:
                res.append(mat[i][j])
                i += 1
                j -= 1
    return res

class Solution {
    int[] findDiagonalOrder(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[] res = new int[m * n];
        int k = 0;
        for (int d = 0; d < m + n - 1; d++) {
            if (d % 2 == 0) {
                int i = Math.min(d, m - 1), j = d - i;
                while (i >= 0 && j < n) res[k++] = mat[i--][j++];
            } else {
                int j = Math.min(d, n - 1), i = d - j;
                while (j >= 0 && i < m) res[k++] = mat[i++][j--];
            }
        }
        return res;
    }
}

class Solution {
public:
    vector<int> findDiagonalOrder(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        vector<int> res;
        for (int d = 0; d < m + n - 1; d++) {
            if (d % 2 == 0) {
                int i = min(d, m - 1), j = d - i;
                while (i >= 0 && j < n) { res.push_back(mat[i][j]); i--; j++; }
            } else {
                int j = min(d, n - 1), i = d - j;
                while (j >= 0 && i < m) { res.push_back(mat[i][j]); i++; j--; }
            }
        }
        return res;
    }
};

