            ok = True
            for di in range(-v, v + 1):
                for dj in range(-v, v + 1):
                    if di == 0 and dj == 0:
                        continue
                    if abs(di) == v and abs(dj) == v:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] >= v:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                res.append([i, j])
    return res

class Solution {
    int[][] findLocalMaximums(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        List<int[]> res = new ArrayList<>();
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            int v = matrix[i][j];
            if (v == 0) continue;
            boolean ok = true;
            outer:
            for (int di = -v; di <= v && ok; di++) {
                for (int dj = -v; dj <= v; dj++) {
                    if (di == 0 && dj == 0) continue;
                    if (Math.abs(di) == v && Math.abs(dj) == v) continue;
                    int ni = i + di, nj = j + dj;
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] >= v) {
                        ok = false;
                        break outer;
                    }
                }
            }
            if (ok) res.add(new int[]{i, j});
        }
        return res.toArray(new int[0][]);
    }
}

