class Solution {
    int[] findPairClosestToK(int[] arr, int k) {
        int l = 0, r = arr.length - 1;
        int[] best = new int[]{arr[l], arr[r]};
        long bestDist = Math.abs((long)arr[l] + arr[r] - k);
        while (l < r) {
            long s = (long)arr[l] + arr[r];
            if (Math.abs(s - k) < bestDist) { bestDist = Math.abs(s - k); best = new int[]{arr[l], arr[r]}; }
            if (s < k) l++; else if (s > k) r--; else break;
        }
        return best;
    }
}

