def longestOnes(nums: List[int], k: int) -> int:
    l = zeros = ans = 0
    for r in range(len(nums)):
        if nums[r] == 0: zeros += 1
        while zeros > k:
            if nums[l] == 0: zeros -= 1
            l += 1
        ans = max(ans, r - l + 1)
    return ans

