def mergeThreeSortedArrays(a: List[int], b: List[int], c: List[int]) -> List[int]:
    i = j = k = 0
    res = []
    while i < len(a) or j < len(b) or k < len(c):
        cands = []
        if i < len(a): cands.append((a[i], 0))
        if j < len(b): cands.append((b[j], 1))
        if k < len(c): cands.append((c[k], 2))
        v, src = min(cands)
        if not res or res[-1] != v: res.append(v)
        if src == 0: i += 1
        elif src == 1: j += 1
        else: k += 1
    return res

class Solution {
    int[] mergeThreeSortedArrays(int[] a, int[] b, int[] c) {
        int i = 0, j = 0, k = 0;
        List<Integer> res = new ArrayList<>();
        while (i < a.length || j < b.length || k < c.length) {
            int va = i < a.length ? a[i] : Integer.MAX_VALUE;
            int vb = j < b.length ? b[j] : Integer.MAX_VALUE;
            int vc = k < c.length ? c[k] : Integer.MAX_VALUE;
            int m = Math.min(va, Math.min(vb, vc));
            if (res.isEmpty() || res.get(res.size() - 1) != m) res.add(m);
            if (va == m) i++;
            else if (vb == m) j++;
            else k++;
        }
        int[] out = new int[res.size()];
        for (int x = 0; x < res.size(); x++) out[x] = res.get(x);
        return out;
    }
}

class Solution {
public:
    vector<int> mergeThreeSortedArrays(vector<int>& a, vector<int>& b, vector<int>& c) {
        size_t i = 0, j = 0, k = 0;
        vector<int> res;
        while (i < a.size() || j < b.size() || k < c.size()) {
            int va = i < a.size() ? a[i] : INT_MAX;
            int vb = j < b.size() ? b[j] : INT_MAX;
            int vc = k < c.size() ? c[k] : INT_MAX;
            int m = min({va, vb, vc});
            if (res.empty() || res.back() != m) res.push_back(m);
            if (va == m) i++;
            else if (vb == m) j++;
            else k++;
        }
        return res;
    }
};

