def depthSum(nestedList: List[Union[int, list]]) -> int:
    def dfs(lst, depth):
        s = 0
        for x in lst:
            if isinstance(x, int):
                s += x * depth
            else:
                s += dfs(x, depth + 1)
        return s
    return dfs(nestedList, 1)

