def replaceConsonant(message: str, n: int) -> str:
    consonants = "bcdfghjklmnpqrstvwxyz"
    nxt = {c: consonants[(i + 1) % len(consonants)] for i, c in enumerate(consonants)}
    res = []
    cnt = 0
    for c in message:
        low = c.lower()
        if low.isalpha() and low not in "aeiou":
            cnt += 1
            if cnt % n == 0:
                nc = nxt[low]
                res.append(nc.upper() if c.isupper() else nc)
                continue
        res.append(c)
    return ''.join(res)

class Solution {
    String replaceConsonant(String message, int n) {
        String cons = "bcdfghjklmnpqrstvwxyz";
        Map<Character, Character> nxt = new HashMap<>();
        for (int i = 0; i < cons.length(); i++) nxt.put(cons.charAt(i), cons.charAt((i + 1) % cons.length()));
        StringBuilder sb = new StringBuilder();
        int cnt = 0;
        for (char c : message.toCharArray()) {
            char low = Character.toLowerCase(c);
            if (Character.isLetter(low) && "aeiou".indexOf(low) < 0) {
                cnt++;
                if (cnt % n == 0) {
                    char nc = nxt.get(low);
                    sb.append(Character.isUpperCase(c) ? Character.toUpperCase(nc) : nc);
                    continue;
                }
            }
            sb.append(c);
        }
        return sb.toString();
    }
}

class Solution {
public:
    string replaceConsonant(string message, int n) {
        string cons = "bcdfghjklmnpqrstvwxyz";
        unordered_map<char, char> nxt;
        for (size_t i = 0; i < cons.size(); i++) nxt[cons[i]] = cons[(i + 1) % cons.size()];
        string res;
        int cnt = 0;
        for (char c : message) {
            char low = tolower(c);
            if (isalpha(low) && string("aeiou").find(low) == string::npos) {
                cnt++;
                if (cnt % n == 0) {
                    char nc = nxt[low];
                    res += isupper(c) ? toupper(nc) : nc;
                    continue;
                }
            }
            res += c;
        }
        return res;
    }
};

class Solution {
    double[] slidingWindowAverage(int[] nums, int windowSize) {
        if (windowSize > nums.length) return new double[0];
        double s = 0;
        for (int i = 0; i < windowSize; i++) s += nums[i];
        double[] res = new double[nums.length - windowSize + 1];
        res[0] = s / windowSize;
        for (int i = windowSize; i < nums.length; i++) {
            s += nums[i] - nums[i - windowSize];
            res[i - windowSize + 1] = s / windowSize;
        }
        return res;
    }
}

class Solution {
public:
    vector<double> slidingWindowAverage(vector<int>& nums, int windowSize) {
        if (windowSize > (int)nums.size()) return {};
        double s = 0;
        for (int i = 0; i < windowSize; i++) s += nums[i];
        vector<double> res;
        res.push_back(s / windowSize);
        for (int i = windowSize; i < (int)nums.size(); i++) {
            s += nums[i] - nums[i - windowSize];
            res.push_back(s / windowSize);
        }
        return res;
    }
};

