def caveAdventure(grid: List[List[str]]) -> int:
    n, m = len(grid), len(grid[0])
    NEG = -1
    f = [[NEG] * m for _ in range(n)]
    if grid[0][0] == 'x':
        return -1
    f[0][0] = 1
    # left to right
    for j in range(1, m):
        if grid[0][j] != 'x' and f[0][j - 1] != NEG:
            f[0][j] = f[0][j - 1] + 1
    for i in range(1, n):
        for j in range(m):
            if grid[i][j] != 'x' and f[i - 1][j] != NEG:
                f[i][j] = f[i - 1][j] + 1
        # left to right
        for j in range(1, m):
            if grid[i][j] != 'x' and f[i][j - 1] != NEG:
                cand = f[i][j - 1] + 1
                if cand > f[i][j]: f[i][j] = cand
        # right to left
        for j in range(m - 2, -1, -1):
            if grid[i][j] != 'x' and f[i][j + 1] != NEG:
                cand = f[i][j + 1] + 1
                if cand > f[i][j]: f[i][j] = cand
    return f[n - 1][m - 1] if f[n - 1][m - 1] != NEG else -1

class Solution {
    int caveAdventure(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] f = new int[n][m];
        for (int[] row : f) Arrays.fill(row, -1);
        if (grid[0][0] == 'x') return -1;
        f[0][0] = 1;
        for (int j = 1; j < m; j++)
            if (grid[0][j] != 'x' && f[0][j - 1] != -1) f[0][j] = f[0][j - 1] + 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++)
                if (grid[i][j] != 'x' && f[i - 1][j] != -1) f[i][j] = f[i - 1][j] + 1;
            for (int j = 1; j < m; j++)
                if (grid[i][j] != 'x' && f[i][j - 1] != -1) f[i][j] = Math.max(f[i][j], f[i][j - 1] + 1);
            for (int j = m - 2; j >= 0; j--)
                if (grid[i][j] != 'x' && f[i][j + 1] != -1) f[i][j] = Math.max(f[i][j], f[i][j + 1] + 1);
        }
        return f[n - 1][m - 1] == -1 ? -1 : f[n - 1][m - 1];
    }
}

