def closestLandMark(aNum: int) -> int:
    fibs = [0, 1]
    while fibs[-1] < aNum * 2:
        fibs.append(fibs[-1] + fibs[-2])
    return min(abs(aNum - f) for f in fibs)

class Solution {
    int closestLandMark(int aNum) {
        List<Long> fibs = new ArrayList<>(Arrays.asList(0L, 1L));
        while (fibs.get(fibs.size() - 1) < (long) aNum * 2) {
            fibs.add(fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2));
        }
        long best = Long.MAX_VALUE;
        for (long f : fibs) best = Math.min(best, Math.abs(aNum - f));
        return (int) best;
    }
}

class Solution {
public:
    int closestLandMark(int aNum) {
        vector<long long> fibs = {0, 1};
        while (fibs.back() < (long long) aNum * 2) fibs.push_back(fibs.back() + fibs[fibs.size() - 2]);
        long long best = LLONG_MAX;
        for (long long f : fibs) best = min(best, (long long) abs((long long) aNum - f));
        return (int) best;
    }
};

from typing import List

def combineTwoVectorsOfIntervals(X: List[List[int]], Y: List[List[int]]) -> List[List[int]]:
    merged = sorted(X + Y)
    res = []
    for s, e in merged:
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

class Solution {
    int[][] combineTwoVectorsOfIntervals(int[][] X, int[][] Y) {
        List<int[]> all = new ArrayList<>();
        for (int[] iv : X) all.add(iv);
        for (int[] iv : Y) all.add(iv);
        all.sort((a, b) -> a[0] - b[0]);
        List<int[]> res = new ArrayList<>();
        for (int[] iv : all) {
            if (!res.isEmpty() && iv[0] <= res.get(res.size() - 1)[1]) {
                res.get(res.size() - 1)[1] = Math.max(res.get(res.size() - 1)[1], iv[1]);
            } else res.add(iv.clone());
        }
        return res.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> combineTwoVectorsOfIntervals(vector<vector<int>>& X, vector<vector<int>>& Y) {
        vector<vector<int>> all = X;
        all.insert(all.end(), Y.begin(), Y.end());
        sort(all.begin(), all.end());
        vector<vector<int>> res;
        for (auto& iv : all) {
            if (!res.empty() && iv[0] <= res.back()[1]) res.back()[1] = max(res.back()[1], iv[1]);
            else res.push_back(iv);
        }
        return res;
    }
};

