class Solution {
    long enumeratingNarrativeSections(int[] bucket, int n) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int pairs = 0, l = 0;
        long ans = 0;
        for (int r = 0; r < bucket.length; r++) {
            int v = cnt.merge(bucket[r], 1, Integer::sum);
            if (v % 2 == 0) pairs++;
            while (pairs >= n) {
                ans += bucket.length - r;
                int u = cnt.merge(bucket[l], -1, Integer::sum);
                if (u % 2 == 1) pairs--;
                l++;
            }
        }
        return ans;
    }
}

class Solution {
public:
    long long enumeratingNarrativeSections(vector<int>& bucket, int n) {
        unordered_map<int, int> cnt;
        int pairs = 0, l = 0;
        long long ans = 0;
        for (int r = 0; r < (int)bucket.size(); r++) {
            cnt[bucket[r]]++;
            if (cnt[bucket[r]] % 2 == 0) pairs++;
            while (pairs >= n) {
                ans += (long long)(bucket.size() - r);
                cnt[bucket[l]]--;
                if (cnt[bucket[l]] % 2 == 1) pairs--;
                l++;
            }
        }
        return ans;
    }
};

