        for k in range(m):
            d = numbers[i + k + 1] - numbers[i + k]
            sign = 1 if d > 0 else -1 if d < 0 else 0
            if sign != pattern[k]:
                ok = False
                break
        if ok:
            cnt += 1
    return cnt

