from typing import List

def searchMysteriousGrid(phrases: List[str], grid: List[List[str]]) -> int:
    m, n = len(grid), len(grid[0])
    def try_match(phrase, i, j, d1, d2):
        cnt = 0
        for turn in range(len(phrase)):
            ci, cj = i, j
            ok = True
            for k in range(len(phrase)):
                if k < turn:
                    ni, nj = i + d1[0] * k, j + d1[1] * k
                else:
                    ni = i + d1[0] * (turn - 1) + d2[0] * (k - turn + 1)
                    nj = j + d1[1] * (turn - 1) + d2[1] * (k - turn + 1)
                if not (0 <= ni < m and 0 <= nj < n) or grid[ni][nj] != phrase[k]:
                    ok = False
                    break
            if ok:
                cnt += 1
        return cnt
    ans = 0
    for phrase in phrases:
        for i in range(m):
            for j in range(n):
                if grid[i][j] != phrase[0]:
                    continue
                # initial right, turn down
                ans += try_match(phrase, i, j, (0, 1), (1, 0))
                # initial down, turn right (avoid double-counting straight lines)
                ans += try_match(phrase, i, j, (1, 0), (0, 1))
    return ans

class Solution {
    int searchMysteriousGrid(String[] phrases, char[][] grid) {
        int m = grid.length, n = grid[0].length, ans = 0;
        int[][] starts = {{0, 1, 1, 0}, {1, 0, 0, 1}};
        for (String p : phrases) {
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (grid[i][j] != p.charAt(0)) continue;
                for (int[] s : starts) {
                    for (int turn = 1; turn <= p.length(); turn++) {
                        boolean ok = true;
                        for (int k = 0; k < p.length(); k++) {
                            int ni, nj;
                            if (k < turn) { ni = i + s[0] * k; nj = j + s[1] * k; }
                            else { ni = i + s[0] * (turn - 1) + s[2] * (k - turn + 1); nj = j + s[1] * (turn - 1) + s[3] * (k - turn + 1); }
                            if (ni < 0 || ni >= m || nj < 0 || nj >= n || grid[ni][nj] != p.charAt(k)) { ok = false; break; }
                        }
                        if (ok) ans++;
                    }
                }
            }
        }
        return ans;
    }
}

