def findLongestLength(fullString):
    n = len(fullString)
    last = {c: i for i, c in enumerate(fullString)}

    blocks = []
    l = 0
    r = last[fullString[0]]
    for i in range(n):
        r = max(r, last[fullString[i]])
        if i == r:
            blocks.append(r - l + 1)
            l = r + 1
            if l < n:
                r = last[fullString[l]]

    if len(blocks) < 2:
        return 0
    total = sum(blocks)
    return max(max(blocks), total - min(blocks))

