def getWinnerCount(booster_a, booster_b, booster_c):
    n = len(booster_a)
    players = [sorted([booster_a[i], booster_b[i], booster_c[i]]) for i in range(n)]

    def beats(x, y):
        return sum(1 for k in range(3) if x[k] > y[k]) >= 2

    ans = 0
    for i in range(n):
        ok = all(beats(players[i], players[j]) for j in range(n) if j != i)
        if ok:
            ans += 1
    return ans

class Solution {
    public int getWinnerCount(int[] a, int[] b, int[] c) {
        int n = a.length;
        int[][] players = new int[n][3];
        for (int i = 0; i < n; i++) {
            int[] trio = { a[i], b[i], c[i] };
            java.util.Arrays.sort(trio);
            players[i] = trio;
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (!beats(players[i], players[j])) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }

    private boolean beats(int[] x, int[] y) {
        int wins = 0;
        for (int k = 0; k < 3; k++) if (x[k] > y[k]) wins++;
        return wins >= 2;
    }
}

