from collections import Counter

def getOutlierValue(arr):
    total = sum(arr)
    cnt = Counter(arr)
    best = -1
    for s in set(arr):
        outlier = total - 2 * s
        if outlier <= 0:
            continue
        if outlier not in cnt:
            continue
        if outlier == s and cnt[s] < 2:
            continue
        if outlier > best:
            best = outlier
    return best

import java.util.*;

class Solution {
    public int getOutlierValue(int[] arr) {
        long total = 0;
        for (int x : arr) total += x;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : arr) cnt.merge(x, 1, Integer::sum);
        int best = -1;
        for (int s : cnt.keySet()) {
            long outlier = total - 2L * s;
            if (outlier <= 0 || outlier > Integer.MAX_VALUE) continue;
            int o = (int) outlier;
            if (!cnt.containsKey(o)) continue;
            if (o == s && cnt.get(s) < 2) continue;
            if (o > best) best = o;
        }
        return best;
    }
}

