def findLongestRegex(x, y, z):
    n = len(x)
    parts = []
    for i in range(n):
        need = {x[i], y[i]}
        # exclude z[i] if possible
        candidate = set(chr(c) for c in range(ord('A'), ord('Z') + 1))
        if z[i] in need:
            # cannot avoid z[i] at this position
            if x[i] == z[i] and y[i] == z[i]:
                # all of x, y, z match here; build bracketed group of all 26 letters minus none
                parts.append(z[i])
                continue
            return "-1"
        candidate.discard(z[i])
        # candidate is sorted, but we must include need
        if len(candidate) == 1:
            parts.append(next(iter(candidate)))
        else:
            parts.append("[" + "".join(sorted(candidate)) + "]")
    return "".join(parts)

import java.util.*;

class Solution {
    public String findLongestRegex(String x, String y, String z) {
        int n = x.length();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char xi = x.charAt(i), yi = y.charAt(i), zi = z.charAt(i);
            if (xi == zi && yi == zi) {
                out.append(zi);
                continue;
            }
            if (xi == zi || yi == zi) return "-1";
            StringBuilder bracket = new StringBuilder("[");
            for (char c = 'A'; c <= 'Z'; c++) if (c != zi) bracket.append(c);
            bracket.append(']');
            out.append(bracket);
        }
        return out.toString();
    }
}

