def getTotalBalanced(capacity):
    n = len(capacity)
    if n < 3:
        return 0
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + capacity[i]

    from collections import defaultdict
    by_val = defaultdict(list)
    for i, v in enumerate(capacity):
        by_val[v].append(i)

    ans = 0
    for v, idxs in by_val.items():
        m = len(idxs)
        for a in range(m):
            for b in range(a + 1, m):
                l, r = idxs[a], idxs[b]
                if r - l < 2:
                    continue
                inner = pref[r] - pref[l + 1]
                if inner == v:
                    ans += 1
    return ans

