def findSimilarities(newPasswords, oldPasswords):
    res = []
    for new, old in zip(newPasswords, oldPasswords):
        j = 0
        for c in new:
            if j == len(old):
                break
            nxt = chr((ord(c) - ord('a') + 1) % 26 + ord('a'))
