class Solution {
    public long[] getSmallerItems(int[] items, int[] start, int[] end, int[] query) {
        int n = items.length, m = start.length;
        int[] diff = new int[n + 1];
        for (int i = 0; i < m; i++) { diff[start[i]]++; diff[end[i] + 1]--; }
        long[] cov = new long[n];
        long cur = 0;
        for (int i = 0; i < n; i++) { cur += diff[i]; cov[i] = cur; }
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(items[a], items[b]));
        int[] vals = new int[n];
        long[] cums = new long[n + 1];
        for (int i = 0; i < n; i++) {
            vals[i] = items[order[i]];
            cums[i + 1] = cums[i] + cov[order[i]];
        }
        long[] res = new long[query.length];
        for (int i = 0; i < query.length; i++) {
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (vals[mid] < query[i]) lo = mid + 1;
                else hi = mid;
            }
            res[i] = cums[lo];
        }
        return res;
    }
}

