class Solution {
    public int findMaximumPackages(int[] cost) {
        int[] cnt = new int[4001];
        for (int c : cost) cnt[c]++;
        int best = 0;
        for (int T = 2; T <= 4000; T++) {
            int pkgs = cnt[T];
            int[] local = cnt.clone();
            local[T] = 0;
            for (int v = 1; v * 2 < T && v <= 2000; v++) {
                int other = T - v;
                if (other > 2000) continue;
                int pair = Math.min(local[v], local[other]);
                pkgs += pair;
                local[v] -= pair;
                local[other] -= pair;
            }
            if (T % 2 == 0) {
                int half = T / 2;
                if (half <= 2000) pkgs += local[half] / 2;
            }
            best = Math.max(best, pkgs);
        }
        return best;
    }
}

