def getMinSize(gameSize, k):
    n = len(gameSize)
    gameSize.sort()
    pairs = n - k
    cap = 0
    for i in range(pairs):
        cap = max(cap, gameSize[i] + gameSize[n - 1 - i])
    if pairs < n - pairs:
        cap = max(cap, gameSize[n - 1 - pairs])
    return cap

