def findScore(userID1, userID2, p):
    n, m = len(userID1), len(userID2)
    if m * p > n + p - 1:
        return 0
    target = [0] * 26
    for c in userID2:
        target[ord(c) - ord('a')] += 1
    ans = 0
    for r in range(p):
        chain = userID1[r::p]
        if len(chain) < m:
            continue
        win = [0] * 26
        for i in range(m):
            win[ord(chain[i]) - ord('a')] += 1
        if win == target:
            ans += 1
        for i in range(m, len(chain)):
            win[ord(chain[i]) - ord('a')] += 1
            win[ord(chain[i - m]) - ord('a')] -= 1
            if win == target:
                ans += 1
    return ans

class Solution {
    public int findScore(String userID1, String userID2, int p) {
        int n = userID1.length(), m = userID2.length();
        int[] target = new int[26];
        for (int i = 0; i < m; i++) target[userID2.charAt(i) - 'a']++;
        int ans = 0;
        for (int r = 0; r < p; r++) {
            int len = (n - r + p - 1) / p;
            if (len < m) continue;
            int[] win = new int[26];
            for (int i = 0; i < m; i++) win[userID1.charAt(r + i * p) - 'a']++;
            if (java.util.Arrays.equals(win, target)) ans++;
            for (int i = m; i < len; i++) {
                win[userID1.charAt(r + i * p) - 'a']++;
                win[userID1.charAt(r + (i - m) * p) - 'a']--;
                if (java.util.Arrays.equals(win, target)) ans++;
            }
        }
        return ans;
    }
}

