def findMaxValue(factor, data, x):
    candidates = []
    for i, row in enumerate(data):
        row_sorted = sorted(row, reverse=True)
        candidates.extend(row_sorted[:factor[i]])
    if len(candidates) < x:
        return -1
    candidates.sort(reverse=True)
    return sum(candidates[:x])

import java.util.*;

class Solution {
    public long findMaxValue(int[] factor, int[][] data, int x) {
        List<Integer> candidates = new ArrayList<>();
        for (int i = 0; i < data.length; i++) {
            Integer[] row = new Integer[data[i].length];
            for (int j = 0; j < data[i].length; j++) row[j] = data[i][j];
            Arrays.sort(row, Collections.reverseOrder());
            for (int j = 0; j < Math.min(factor[i], row.length); j++) candidates.add(row[j]);
        }
        if (candidates.size() < x) return -1;
        candidates.sort(Collections.reverseOrder());
        long ans = 0;
        for (int i = 0; i < x; i++) ans += candidates.get(i);
        return ans;
    }
}

