def findMinimumMaximum(parcels, extra_parcels):
    lo = max(parcels)
    hi = lo + extra_parcels
    def feasible(M):
        return sum(M - p for p in parcels if M > p) >= extra_parcels
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    public long findMinimumMaximum(int[] parcels, long extra) {
        long lo = 0;
        for (int p : parcels) lo = Math.max(lo, p);
        long hi = lo + extra;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long room = 0;
            for (int p : parcels) if (mid > p) room += mid - p;
            if (room >= extra) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

