class Solution {
    public int[] findOptimalPermutation(int[] data) {
        int n = data.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> data[a] != data[b] ? Integer.compare(data[a], data[b]) : Integer.compare(a, b));
        int[] p = new int[n];
        for (int pos = 0; pos < n; pos++) p[order[pos]] = pos + 1;
        return p;
    }
}

