        sort(order.begin(), order.end(), [&](int a, int b){
            if (data[a] != data[b]) return data[a] < data[b];
            return a < b;
        });
        vector<int> p(n);
        for (int pos = 0; pos < n; pos++) p[order[pos]] = pos + 1;
        return p;
    }
};

