class Solution {
    public long[] getMinConnectionCost(int[] cap, int[][] hubs) {
        int n = cap.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + cap[i];
        long[] out = new long[hubs.length];
        for (int q = 0; q < hubs.length; q++) {
            int hubA = hubs[q][0], hubB = hubs[q][1];
            long ca = cap[hubA - 1], cb = cap[hubB - 1], cn = cap[n - 1];
            long cost = ca * hubA - pref[hubA];
            cost += cb * (hubB - hubA) - (pref[hubB] - pref[hubA]);
            cost += cn * (n - hubB) - (pref[n] - pref[hubB]);
            out[q] = cost;
        }
        return out;
    }
}

