def countValidSplits(productTypes, m):
    n = len(productTypes)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] | (1 << (ord(productTypes[i]) - ord('a')))
    suf = [0] * (n + 2)
    for i in range(n - 1, -1, -1):
        suf[i] = suf[i + 1] | (1 << (ord(productTypes[i]) - ord('a')))
    ans = 0
    for i in range(1, n):
        common = pref[i] & suf[i]
        if bin(common).count('1') > m:
            ans += 1
    return ans

class Solution {
    public int countValidSplits(String s, int m) {
        int n = s.length();
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] | (1 << (s.charAt(i) - 'a'));
        int[] suf = new int[n + 2];
        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] | (1 << (s.charAt(i) - 'a'));
        int ans = 0;
        for (int i = 1; i < n; i++)
            if (Integer.bitCount(pref[i] & suf[i]) > m) ans++;
        return ans;
    }
}

