class Solution {
    public int[] findFinalCart(int[] items, int[] query) {
        LinkedList<Integer> list = new LinkedList<>();
        Map<Integer, Deque<Integer>> indices = new HashMap<>();
        for (int x : items) list.add(x);
        // For simple correctness: rebuild indices on demand. Acceptable for moderate input.
        for (int q : query) {
            if (q > 0) list.add(q);
            else {
                int target = -q;
                Iterator<Integer> it = list.iterator();
                while (it.hasNext()) {
                    if (it.next() == target) { it.remove(); break; }
                }
            }
        }
        int[] out = new int[list.size()];
        int i = 0;
        for (int v : list) out[i++] = v;
        return out;
    }
}

