from bisect import bisect_left

def getMaxPoints(domino, remove, min_order):
    n = len(domino)
    def lis_of_kept(k):
        kept = [False] * n
        for i in range(k, n):
            kept[remove[i]] = True
        tails = []
        for i in range(n):
            if not kept[i]:
                continue
            x = domino[i]
            pos = bisect_left(tails, x)
            if pos == len(tails):
                tails.append(x)
            else:
                tails[pos] = x
        return len(tails)

    lo, hi = 0, n
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if lis_of_kept(mid) >= min_order:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

import java.util.*;

class Solution {
    public int getMaxPoints(int[] domino, int[] remove, int minOrder) {
        int n = domino.length;
        int lo = 0, hi = n, ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (lisKept(domino, remove, mid) >= minOrder) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }

    private int lisKept(int[] domino, int[] remove, int k) {
        int n = domino.length;
        boolean[] kept = new boolean[n];
        for (int i = k; i < n; i++) kept[remove[i]] = true;
        List<Integer> tails = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!kept[i]) continue;
            int x = domino[i];
            int pos = Collections.binarySearch(tails, x);
            if (pos < 0) pos = -pos - 1;
            if (pos == tails.size()) tails.add(x);
            else tails.set(pos, x);
        }
        return tails.size();
    }
}

