def findMinSyncTime(total_servers, servers):
    s = sorted(servers)
    n = len(s)
    if n <= 1:
        return 0
    gaps = [s[i] - s[i - 1] for i in range(1, n)]
    gaps.append(total_servers - s[-1] + s[0])
    return total_servers - max(gaps)

