class Solution {
    public int findMinSyncTime(int totalServers, int[] servers) {
        int[] s = servers.clone();
        Arrays.sort(s);
        int n = s.length;
        if (n <= 1) return 0;
        int maxGap = 0;
        for (int i = 1; i < n; i++) maxGap = Math.max(maxGap, s[i] - s[i - 1]);
        maxGap = Math.max(maxGap, totalServers - s[n - 1] + s[0]);
        return totalServers - maxGap;
    }
}

