class Solution {
    public long calculateMaxQualityScore(int[] ratings, int impactFactor) {
        long base = kadane(ratings, 0, false);
        long mult = kadane(ratings, impactFactor, false);
        long div = kadane(ratings, impactFactor, true);
        return Math.max(base, Math.max(base + mult, base + div));
    }
    private long kadane(int[] r, int f, boolean divide) {
        if (f == 0) {
            long best = Long.MIN_VALUE, cur = 0;
            for (int x : r) {
                cur = Math.max((long) x, cur + x);
                best = Math.max(best, cur);
            }
            return best;
        }
        long best = Long.MIN_VALUE, cur = 0;
        for (int x : r) {
            long delta;
            if (divide) {
                long d = x >= 0 ? x / f : -(((long) -x) / f);
                delta = d - x;
            } else {
                delta = ((long) f - 1) * x;
            }
            cur = Math.max(delta, cur + delta);
            best = Math.max(best, cur);
        }
        return best;
    }
}

