class Solution {
    public long getMinimalCost(int[] size, int[] cost) {
        int n = size.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(size[a], size[b]));
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long totalInHeap = 0, ans = 0;
        int idx = 0;
        long curSize = Long.MIN_VALUE;
        while (idx < n || !heap.isEmpty()) {
            if (heap.isEmpty()) curSize = size[order[idx]];
            while (idx < n && size[order[idx]] == curSize) {
                heap.offer(cost[order[idx]]);
                totalInHeap += cost[order[idx]];
                idx++;
            }
            int keep = heap.poll();
            totalInHeap -= keep;
            ans += totalInHeap;
            curSize++;
        }
        return ans;
    }
}

