class Solution {
    public long getFewestOperations(int[] boxes) {
        int n = boxes.length;
        long S = 0;
        for (int x : boxes) S += x;
        long q = S / n, r = S % n;
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++) arr[i] = boxes[i];
        Arrays.sort(arr, Collections.reverseOrder());
        long ops = 0;
        for (int i = 0; i < n; i++) {
            long target = (i < r) ? q + 1 : q;
            if (arr[i] > target) ops += arr[i] - target;
        }
        return ops;
    }
}

