from collections import defaultdict

def getNumberIdle(x, y):
    row_x = defaultdict(list)  # y -> sorted xs
    col_y = defaultdict(list)  # x -> sorted ys
    for xi, yi in zip(x, y):
        row_x[yi].append(xi)
        col_y[xi].append(yi)
    for k in row_x: row_x[k].sort()
    for k in col_y: col_y[k].sort()
    ans = 0
    for xi, yi in zip(x, y):
        rx = row_x[yi]
        cy = col_y[xi]
        if xi != rx[0] and xi != rx[-1] and yi != cy[0] and yi != cy[-1]:
            ans += 1
    return ans

import java.util.*;

class Solution {
    public int getNumberIdle(int[] x, int[] y) {
        int n = x.length;
        Map<Integer, List<Integer>> rowX = new HashMap<>();
        Map<Integer, List<Integer>> colY = new HashMap<>();
        for (int i = 0; i < n; i++) {
            rowX.computeIfAbsent(y[i], k -> new ArrayList<>()).add(x[i]);
            colY.computeIfAbsent(x[i], k -> new ArrayList<>()).add(y[i]);
        }
        for (var v : rowX.values()) Collections.sort(v);
        for (var v : colY.values()) Collections.sort(v);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            List<Integer> rx = rowX.get(y[i]);
            List<Integer> cy = colY.get(x[i]);
            if (x[i] != rx.get(0) && x[i] != rx.get(rx.size() - 1)
                && y[i] != cy.get(0) && y[i] != cy.get(cy.size() - 1)) ans++;
        }
        return ans;
    }
}

