def analyzeProductCode(productSeq):
    n = len(productSeq)
    ans = 0
    for l in range(n):
        cnt = [0] * 7
        distinct = 0
        max_f = 0
        for r in range(l, n):
            c = ord(productSeq[r]) - ord('a')
            if cnt[c] == 0:
                distinct += 1
            cnt[c] += 1
            if cnt[c] > max_f:
                max_f = cnt[c]
            if max_f <= distinct:
                ans += 1
    return ans

