class Solution {
    public long[] findPartitionCost(int[] cost, int k) {
        int n = cost.length;
        long base = (long) cost[0] + cost[n - 1];
        if (k == 1) return new long[] { base, base };
        long[] pairs = new long[n - 1];
        for (int i = 0; i < n - 1; i++) pairs[i] = (long) cost[i] + cost[i + 1];
        Arrays.sort(pairs);
        long minSum = base, maxSum = base;
        for (int i = 0; i < k - 1; i++) minSum += pairs[i];
        for (int i = pairs.length - 1; i >= pairs.length - (k - 1); i--) maxSum += pairs[i];
        return new long[] { minSum, maxSum };
    }
}

