def findTime(genome, mutation):
    # stack of (char, round_value): how many rounds it has survived
    stack = []
    ans = 0
    for c in genome:
        if c == mutation:
            r = 0
            # While top exists and is not mutation, pop it (consumed at round r+1)
            while stack and stack[-1][0] != mutation:
                _, top_r = stack.pop()
                r = max(r, top_r) + 1
                ans = max(ans, r)
                # Mutation 'consumes' one non-mutation per round; stop after one consumption
                stack.append((mutation, r))
                break
            else:
                # No consumption; just place
                if not stack or stack[-1][0] == mutation:
                    stack.append((mutation, 0))
        else:
            stack.append((c, 0))
    return ans

import java.util.*;

class Solution {
    public int findTime(String genome, char mutation) {
        Deque<int[]> stack = new ArrayDeque<>(); // [char, round]
        int ans = 0;
        for (char c : genome.toCharArray()) {
            if (c == mutation) {
                if (!stack.isEmpty() && stack.peek()[0] != mutation) {
                    int top = stack.pop()[1];
                    int r = top + 1;
                    ans = Math.max(ans, r);
                    stack.push(new int[] { mutation, r });
                } else {
                    stack.push(new int[] { mutation, 0 });
                }
            } else {
                stack.push(new int[] { c, 0 });
            }
        }
        return ans;
    }
}

