class Solution {
    public long minimizeSystemCost(int[] machines, int k) {
        int n = machines.length;
        if (k >= n) return 0;
        long[] diff = new long[n - 1];
        for (int i = 0; i < n - 1; i++) diff[i] = Math.abs((long) machines[i + 1] - machines[i]);
        long[] pref = new long[n];
        for (int i = 0; i < n - 1; i++) pref[i + 1] = pref[i] + diff[i];
        long total = pref[n - 1];
        long best = Long.MAX_VALUE;
        for (int l = 0; l <= n - k; l++) {
            int r = l + k - 1;
            int lo = Math.max(0, l - 1);
            int hi = Math.min(n - 2, r);
            long removed = pref[hi + 1] - pref[lo];
            long cost = total - removed;
            if (l > 0 && r < n - 1) cost += Math.abs((long) machines[l - 1] - machines[r + 1]);
            best = Math.min(best, cost);
        }
        return best;
    }
}

