class Solution {
    public long getMinRequests(int[] request, int[] health, int k) {
        int n = request.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        int[] hits = new int[n];
        for (int i = 0; i < n; i++) hits[i] = (health[i] + k - 1) / k;
        Arrays.sort(order, (a, b) -> Double.compare((double) request[b] / hits[b], (double) request[a] / hits[a]));
        long totalReq = 0;
        for (int r : request) totalReq += r;
        long total = 0;
        for (int idx : order) {
            total += totalReq * hits[idx];
            totalReq -= request[idx];
        }
        return total + 1;
    }
}

