def minimumSets(a, b, k):
    intervals = sorted(zip(a, b))
    merged = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    c = len(merged)
    if c <= 1:
        return c
    # Gaps between consecutive components
    gaps = [merged[i + 1][0] - merged[i][1] for i in range(c - 1)]
    # Find the longest run of consecutive gaps each <= k
    best = 0
    cur = 0
    for g in gaps:
        if g <= k:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return c - best

import java.util.*;

class Solution {
    public int minimumSets(int[] a, int[] b, int k) {
        int n = a.length;
        int[][] intervals = new int[n][2];
        for (int i = 0; i < n; i++) { intervals[i][0] = a[i]; intervals[i][1] = b[i]; }
        Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));
        List<int[]> merged = new ArrayList<>();
        merged.add(intervals[0].clone());
        for (int i = 1; i < n; i++) {
            int[] last = merged.get(merged.size() - 1);
            if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);
            else merged.add(intervals[i].clone());
        }
        int c = merged.size();
        if (c <= 1) return c;
        int best = 0, cur = 0;
        for (int i = 0; i < c - 1; i++) {
            int g = merged.get(i + 1)[0] - merged.get(i)[1];
            if (g <= k) { cur++; best = Math.max(best, cur); }
            else cur = 0;
        }
        return c - best;
    }
}

