class Solution {
    public long minimizeVariation(int[] productSize) {
        int n = productSize.length;
        int[] s = productSize.clone();
        Arrays.sort(s);
        long[][] dp = new long[n][n];
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                long variation = s[j] - s[i];
                dp[i][j] = Math.min(dp[i + 1][j] + variation, dp[i][j - 1] + variation);
            }
        }
        return dp[0][n - 1];
    }
}

