def specialStrings(s):
    n = len(s)
    pref0 = [0] * (n + 1)
    pref1 = [0] * (n + 1)
    for i, ch in enumerate(s):
        pref0[i + 1] = pref0[i] + (ch == '0')
        pref1[i + 1] = pref1[i] + (ch == '1')
    ans = 0
    for l in range(n):
        for r in range(l, n):
            c1 = pref1[r + 1] - pref1[l]
            c0 = pref0[r + 1] - pref0[l]
            if c0 == c1 * c1:
                ans += 1
    return ans

class Solution {
    public long specialStrings(String s) {
        int n = s.length();
        int[] pref1 = new int[n + 1];
        for (int i = 0; i < n; i++) pref1[i + 1] = pref1[i] + (s.charAt(i) == '1' ? 1 : 0);
        long ans = 0;
        for (int l = 0; l < n; l++) {
            for (int r = l; r < n; r++) {
                int c1 = pref1[r + 1] - pref1[l];
                int c0 = (r - l + 1) - c1;
                if (c0 == c1 * c1) ans++;
            }
        }
        return ans;
    }
}

