from bisect import bisect_right

def getMaxMatching(match):
    tails = []
    for x in match:
        pos = bisect_right(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

import java.util.*;

class Solution {
    public int getMaxMatching(int[] match) {
        List<Integer> tails = new ArrayList<>();
        for (int x : match) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails.get(mid) <= x) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(x);
            else tails.set(lo, x);
        }
        return tails.size();
    }
}

