def getminSubsegments(frames):
    n = len(frames)
    # Resolve each pair to '0' or '1' minimizing flips, tie-break to extend previous segment
    resolved = []
    flips = 0
    for i in range(0, n, 2):
        a, b = frames[i], frames[i + 1]
        if a == b:
            resolved.append(a)
        else:
            flips += 1
            # Match previous if possible to reduce segment count
            if resolved and resolved[-1] in ('0', '1'):
                resolved.append(resolved[-1])
            else:
                resolved.append('0')
    # Count runs
    segs = 1
    for i in range(1, len(resolved)):
        if resolved[i] != resolved[i - 1]:
            segs += 1
    return segs

