        for (int i = 0; i < n; i += 2) {
            char a = frames.charAt(i), b = frames.charAt(i + 1);
            if (a == b) resolved.append(a);
            else {
                if (resolved.length() > 0) resolved.append(resolved.charAt(resolved.length() - 1));
                else resolved.append('0');
            }
        }
        int segs = 1;
        for (int i = 1; i < resolved.length(); i++) {
            if (resolved.charAt(i) != resolved.charAt(i - 1)) segs++;
        }
        return segs;
    }
}

