def getMaximumCredits(inventory, dispatch1, dispatch2, skips):
    # Per warehouse, compute remaining after coworker rounds; if my turn ends it, count it.
    # Without skipping: you go first then coworker. Each cycle removes d1 + d2; you finish if remainder mod cycle in (0, d1].
    ans = 0
    cycle = dispatch1 + dispatch2
    extra_needed = []
    for inv in inventory:
        r = inv % cycle
        if r == 0:
            # coworker finishes
            # Need 1 skip to convert to your finish
            extra_needed.append(1)
        elif r <= dispatch1:
            ans += 1
        else:
            # coworker finishes when r > d1
            # Need 1 skip
            extra_needed.append(1)
    extra_needed.sort()
    for c in extra_needed:
        if skips >= c:
            skips -= c
            ans += 1
        else:
            break
    return ans

