class Solution {
    public int getMaximumCredits(int[] inventory, int dispatch1, int dispatch2, int skips) {
        long cycle = (long) dispatch1 + dispatch2;
        int ans = 0;
        List<Integer> extra = new ArrayList<>();
        for (int inv : inventory) {
            long r = inv % cycle;
            if (r == 0) extra.add(1);
            else if (r <= dispatch1) ans++;
            else extra.add(1);
        }
        Collections.sort(extra);
        long s = skips;
        for (int c : extra) {
            if (s >= c) { s -= c; ans++; }
            else break;
        }
        return ans;
    }
}

