class Solution {
    public int getMaxServers(int[] powers) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int p : powers) cnt.merge(p, 1, Integer::sum);
        int best = 0;
        for (int v : cnt.values()) best = Math.max(best, v);
        for (var e : cnt.entrySet()) {
