def getSortingFactorK(arr):
    n = len(arr)
    misplaced = [v for i, v in enumerate(arr) if i != v]
    if not misplaced:
        return 0
    k = misplaced[0]
    for v in misplaced[1:]:
        k &= v
    return k

class Solution {
    public int getSortingFactorK(int[] arr) {
        int n = arr.length;
        Integer k = null;
        for (int i = 0; i < n; i++) {
            if (arr[i] != i) {
                if (k == null) k = arr[i];
                else k &= arr[i];
            }
        }
        return k == null ? 0 : k;
    }
}

