class Solution {
    public int calculateMinShipments(int[] warehouses) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int w : warehouses) cnt.merge(w, 1, Integer::sum);
        int M = 0;
        for (int v : cnt.values()) M = Math.max(M, v);
        int n = warehouses.length;
        return 2 * M <= n ? (n + 1) / 2 : M;
    }
}

