            while (nextZero < n && state[nextZero] != '0') nextZero++;
            if (nextZero < n) {
                state[nextZero] = '1';
                heap.push({values[nextZero], nextZero});
                nextZero++;
            }
        }
        return out;
    }
};

def getUnfulfilledCustomers(requests, totalInventory):
    req = sorted(requests, key=lambda r: (-r[2], r[3]))
    allocated = {r[0]: 0 for r in req}
    remaining = {r[0]: r[1] for r in req}
    inv = totalInventory
    i = 0
    n = len(req)
    while i < n and inv > 0:
        j = i
        while j < n and req[j][2] == req[i][2]:
            j += 1
        group = req[i:j]
        active = list(range(len(group)))
        while inv > 0 and active:
            new_active = []
            for k in active:
                if inv == 0:
                    break
                cid = group[k][0]
                if remaining[cid] > 0:
                    remaining[cid] -= 1
                    allocated[cid] += 1
                    inv -= 1
                    if remaining[cid] > 0:
                        new_active.append(k)
            active = new_active
        i = j
    unfulfilled = sorted(c for c, q in allocated.items() if q == 0)
    return unfulfilled

import java.util.*;

class Solution {
    public int[] getUnfulfilledCustomers(int[][] requests, int totalInventory) {
        int n = requests.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> requests[a][2] != requests[b][2]
            ? Integer.compare(requests[b][2], requests[a][2])
            : Integer.compare(requests[a][3], requests[b][3]));
        Map<Integer, Integer> alloc = new HashMap<>();
        Map<Integer, Integer> rem = new HashMap<>();
        for (int[] r : requests) {
            alloc.put(r[0], 0);
            rem.put(r[0], r[1]);
        }
        int inv = totalInventory, i = 0;
        while (i < n && inv > 0) {
            int j = i;
            while (j < n && requests[order[j]][2] == requests[order[i]][2]) j++;
            List<Integer> group = new ArrayList<>();
            for (int t = i; t < j; t++) group.add(requests[order[t]][0]);
            List<Integer> active = new ArrayList<>(group);
            while (inv > 0 && !active.isEmpty()) {
                List<Integer> next = new ArrayList<>();
                for (int cid : active) {
                    if (inv == 0) break;
                    if (rem.get(cid) > 0) {
                        rem.put(cid, rem.get(cid) - 1);
                        alloc.put(cid, alloc.get(cid) + 1);
                        inv--;
                        if (rem.get(cid) > 0) next.add(cid);
                    }
                }
                active = next;
            }
            i = j;
        }
        List<Integer> un = new ArrayList<>();
        for (var e : alloc.entrySet()) if (e.getValue() == 0) un.add(e.getKey());
        Collections.sort(un);
        return un.stream().mapToInt(Integer::intValue).toArray();
    }
}

