using namespace std;

class Solution {
public:
    vector<int> getUnfulfilledCustomers(vector<vector<int>>& requests, int totalInventory) {
        int n = requests.size();
        vector<int> order(n);
        for (int i = 0; i < n; i++) order[i] = i;
        sort(order.begin(), order.end(), [&](int a, int b){
            if (requests[a][2] != requests[b][2]) return requests[a][2] > requests[b][2];
            return requests[a][3] < requests[b][3];
        });
        unordered_map<int, int> alloc, rem;
        for (auto& r : requests) { alloc[r[0]] = 0; rem[r[0]] = r[1]; }
        int inv = totalInventory, i = 0;
        while (i < n && inv > 0) {
            int j = i;
            while (j < n && requests[order[j]][2] == requests[order[i]][2]) j++;
            vector<int> active;
            for (int t = i; t < j; t++) active.push_back(requests[order[t]][0]);
            while (inv > 0 && !active.empty()) {
                vector<int> next_a;
                for (int cid : active) {
                    if (inv == 0) break;
                    if (rem[cid] > 0) {
                        rem[cid]--; alloc[cid]++; inv--;
                        if (rem[cid] > 0) next_a.push_back(cid);
                    }
                }
                active = next_a;
            }
            i = j;
        }
        vector<int> un;
        for (auto& [c, q] : alloc) if (q == 0) un.push_back(c);
        sort(un.begin(), un.end());
        return un;
    }
};

class Solution {
    public int getMinimumConflicts(String primary, String secondary) {
        int n = primary.length(), m = secondary.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int[] row : dp) java.util.Arrays.fill(row, Integer.MAX_VALUE);
        dp[0][0] = 0;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (dp[i][j] == Integer.MAX_VALUE) continue;
                int[] freq = new int[26];
                for (int k = 0; k < i; k++) freq[primary.charAt(k) - 'a']++;
                for (int k = 0; k < j; k++) freq[secondary.charAt(k) - 'a']++;
                if (i < n) {
                    int c = primary.charAt(i) - 'a';
                    int higher = 0;
                    for (int k = c + 1; k < 26; k++) higher += freq[k];
                    dp[i + 1][j] = Math.min(dp[i + 1][j], dp[i][j] + higher);
                }
                if (j < m) {
                    int c = secondary.charAt(j) - 'a';
                    int higher = 0;
                    for (int k = c + 1; k < 26; k++) higher += freq[k];
                    dp[i][j + 1] = Math.min(dp[i][j + 1], dp[i][j] + higher);
                }
            }
        }
        return dp[n][m];
    }
}

