import java.util.*;

class Solution {
    public int[] sortBugReportFrequencies(int[] bugs) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int b : bugs) freq.merge(b, 1, Integer::sum);
        Integer[] arr = new Integer[bugs.length];
        for (int i = 0; i < bugs.length; i++) arr[i] = bugs[i];
        Arrays.sort(arr, (a, b) -> freq.get(a) != freq.get(b) ? freq.get(a) - freq.get(b) : a - b);
        int[] out = new int[bugs.length];
        for (int i = 0; i < bugs.length; i++) out[i] = arr[i];
        return out;
    }
}

