class Solution {
    public int[] canAllPackagesBeDelivered(int[][] truckCapacities, int[][] packageWeights) {
        int t = truckCapacities.length;
        int[] out = new int[t];
        for (int s = 0; s < t; s++) {
            TreeMap<Integer, Integer> trucks = new TreeMap<>();
            for (int c : truckCapacities[s]) trucks.merge(c, 1, Integer::sum);
            Integer[] weights = new Integer[packageWeights[s].length];
            for (int i = 0; i < weights.length; i++) weights[i] = packageWeights[s][i];
            Arrays.sort(weights, Collections.reverseOrder());
            boolean ok = true;
            for (int w : weights) {
                Integer fit = trucks.ceilingKey(w);
                if (fit == null) { ok = false; break; }
                if (trucks.get(fit) == 1) trucks.remove(fit);
                else trucks.put(fit, trucks.get(fit) - 1);
                if (fit / 2 > 0) trucks.merge(fit / 2, 1, Integer::sum);
            }
            out[s] = ok ? 1 : 0;
        }
        return out;
    }
}

