class Solution {
public:
    vector<int> canAllPackagesBeDelivered(vector<vector<int>>& truckCapacities, vector<vector<int>>& packageWeights) {
        vector<int> out;
        for (size_t s = 0; s < truckCapacities.size(); s++) {
            multiset<int> trucks(truckCapacities[s].begin(), truckCapacities[s].end());
            vector<int> weights = packageWeights[s];
            sort(weights.begin(), weights.end(), greater<int>());
            bool ok = true;
            for (int w : weights) {
                auto it = trucks.lower_bound(w);
                if (it == trucks.end()) { ok = false; break; }
                int c = *it;
                trucks.erase(it);
                if (c / 2 > 0) trucks.insert(c / 2);
            }
            out.push_back(ok ? 1 : 0);
        }
        return out;
    }
};

