class Solution {
    public int getMinAmount(int[] quality) {
        int n = quality.length;
        Map<Integer, Integer> cnt = new HashMap<>();
        Map<Integer, Integer> maxRun = new HashMap<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && quality[j] == quality[i]) j++;
            int len = j - i;
            cnt.merge(quality[i], len, Integer::sum);
            maxRun.merge(quality[i], len, Math::max);
            i = j;
        }
        int ans = 0;
        for (var e : cnt.entrySet()) ans += e.getValue() - maxRun.get(e.getKey());
        return ans;
    }
}

