def computeMinDeliveryTime(requestedHubs, transitionTime):
    m = len(transitionTime)
    pref = [0] * (m + 1)
    for i in range(m):
        pref[i + 1] = pref[i] + transitionTime[i]
    total = pref[m]
    def dist(a, b):
        # 1-indexed hubs
        if a == b:
            return 0
        lo, hi = min(a, b), max(a, b)
        # distance going lo -> hi clockwise
        cw = pref[hi - 1] - pref[lo - 1]
        return min(cw, total - cw)
    ans = 0
    cur = 1
    for h in requestedHubs:
        ans += dist(cur, h)
        cur = h
    return ans

class Solution {
    public long computeMinDeliveryTime(int[] requestedHubs, int[] transitionTime) {
        int m = transitionTime.length;
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) pref[i + 1] = pref[i] + transitionTime[i];
        long total = pref[m];
        long ans = 0;
        int cur = 1;
        for (int h : requestedHubs) {
            if (cur != h) {
                int lo = Math.min(cur, h), hi = Math.max(cur, h);
                long cw = pref[hi - 1] - pref[lo - 1];
                ans += Math.min(cw, total - cw);
            }
            cur = h;
        }
        return ans;
    }
}

