        long long freeTotal = 0;
        int take = (freeVals.size() + 1) / 2;
        for (int i = 0; i < take; i++) freeTotal += freeVals[i];
        return pairTotal + freeTotal;
    }
};

def getMaximumCost(planCost, featureCost, incompatiblePlans, incompatibleFeatures):
    incompatible = set(zip(incompatiblePlans, incompatibleFeatures))
    plan_sorted = sorted(range(1, len(planCost) + 1), key=lambda i: -planCost[i - 1])
    feat_sorted = sorted(range(1, len(featureCost) + 1), key=lambda i: -featureCost[i - 1])
    best = -1
    for p in plan_sorted[:min(len(plan_sorted), len(incompatible) + 2)]:
        for f in feat_sorted[:min(len(feat_sorted), len(incompatible) + 2)]:
            if (p, f) not in incompatible:
                cand = planCost[p - 1] + featureCost[f - 1]
                if cand > best:
                    best = cand
                break
    return best

import java.util.*;

class Solution {
    public long getMaximumCost(int[] planCost, int[] featureCost,
                                int[] incompatiblePlans, int[] incompatibleFeatures) {
        Set<Long> incompatible = new HashSet<>();
        for (int i = 0; i < incompatiblePlans.length; i++) {
            incompatible.add(((long) incompatiblePlans[i] << 32) | (long) incompatibleFeatures[i]);
        }
        Integer[] planOrder = new Integer[planCost.length];
        Integer[] featOrder = new Integer[featureCost.length];
        for (int i = 0; i < planCost.length; i++) planOrder[i] = i + 1;
        for (int i = 0; i < featureCost.length; i++) featOrder[i] = i + 1;
        Arrays.sort(planOrder, (a, b) -> planCost[b - 1] - planCost[a - 1]);
        Arrays.sort(featOrder, (a, b) -> featureCost[b - 1] - featureCost[a - 1]);
        long best = -1;
        int limit = Math.min(planCost.length, incompatible.size() + 2);
        int featLimit = Math.min(featureCost.length, incompatible.size() + 2);
        for (int pi = 0; pi < limit; pi++) {
            int p = planOrder[pi];
            for (int fi = 0; fi < featLimit; fi++) {
                int f = featOrder[fi];
                if (!incompatible.contains(((long) p << 32) | (long) f)) {
                    long cand = (long) planCost[p - 1] + featureCost[f - 1];
                    if (cand > best) best = cand;
                    break;
                }
            }
        }
        return best;
    }
}

