def minOperations(prices, k, d):
    n = len(prices)
    s = sorted(prices)
    cur = s[-1] - s[0]
    target = d - 1
    if cur <= target:
        return 0
    # Each op moves up to k from a high to a low; reduces spread by at most 2k.
    return (cur - target + 2 * k - 1) // (2 * k)

import java.util.*;

class Solution {
    public int minOperations(int[] prices, int k, int d) {
        int[] s = prices.clone();
        Arrays.sort(s);
        int cur = s[s.length - 1] - s[0];
        int target = d - 1;
        if (cur <= target) return 0;
        return (cur - target + 2 * k - 1) / (2 * k);
    }
}

