def getMinimumOperations(strValue):
    target = ''.join(sorted(strValue))
    if strValue == target:
        return 0
    # Check if one proper-substring sort works: find longest matching prefix and suffix
    n = len(strValue)
    p = 0
    while p < n and strValue[p] == target[p]:
        p += 1
    s = 0
    while s < n and strValue[n - 1 - s] == target[n - 1 - s]:
        s += 1
    # Proper substring excludes the full string; need p > 0 or s > 0
    if (p > 0 or s > 0):
        # Sorting strValue[p..n-1-s] would equal target[p..n-1-s] iff multiset matches
        mid = strValue[p:n - s]
        if ''.join(sorted(mid)) == target[p:n - s]:
            return 1
    return 2

import java.util.*;

class Solution {
    public int getMinimumOperations(String s) {
        char[] target = s.toCharArray();
        Arrays.sort(target);
        String t = new String(target);
        if (s.equals(t)) return 0;
        int n = s.length();
        int p = 0;
        while (p < n && s.charAt(p) == t.charAt(p)) p++;
        int suf = 0;
        while (suf < n && s.charAt(n - 1 - suf) == t.charAt(n - 1 - suf)) suf++;
        if (p > 0 || suf > 0) {
            char[] mid = s.substring(p, n - suf).toCharArray();
            Arrays.sort(mid);
            if (new String(mid).equals(t.substring(p, n - suf))) return 1;
        }
        return 2;
    }
}

