def moveUnits(population, unit):
    n = len(population)
    covered = [False] * n
    # Mark current units
    for i in range(n):
        if unit[i] == '1':
            covered[i] = True
    # Greedy: for each unit, decide stay vs move-left
    for i in range(n):
        if unit[i] == '1' and i > 0 and not covered[i - 1]:
            if population[i - 1] > population[i]:
                covered[i] = False
                covered[i - 1] = True
    return sum(population[i] for i in range(n) if covered[i])

class Solution {
    public long moveUnits(int[] population, String unit) {
        int n = population.length;
        boolean[] covered = new boolean[n];
        for (int i = 0; i < n; i++) if (unit.charAt(i) == '1') covered[i] = true;
        for (int i = 0; i < n; i++) {
            if (unit.charAt(i) == '1' && i > 0 && !covered[i - 1]) {
                if (population[i - 1] > population[i]) {
                    covered[i] = false;
                    covered[i - 1] = true;
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) if (covered[i]) ans += population[i];
        return ans;
    }
}

