class Solution {
    public long getMinTime(int[] startTime, int[] endTime, long maxUsage) {
        List<long[]> events = new ArrayList<>();
        for (int s : startTime) events.add(new long[] { s, 1 });
        for (int e : endTime) events.add(new long[] { (long) e + 1, -1 });
        events.sort((a, b) -> Long.compare(a[0], b[0]));
        long cumulative = 0, active = 0, prev = -1;
        for (long[] ev : events) {
            long t = ev[0];
            if (prev != -1 && active > 0) {
                long span = t - prev;
                if (cumulative + active * span >= maxUsage) {
                    long need = maxUsage - cumulative;
                    long offset = (need + active - 1) / active;
                    return prev + offset - 1;
                }
                cumulative += active * span;
            }
            active += ev[1];
            prev = t;
        }
        return -1;
    }
}

