def getTimeToStabilize(pipeline, failedService):
    stack = []
    ans = 0
    for c in pipeline:
        if c == failedService:
            if stack and stack[-1][0] != failedService:
                _, r = stack.pop()
                new_r = r + 1
                ans = max(ans, new_r)
                stack.append((failedService, new_r))
            else:
                stack.append((failedService, 0))
        else:
            stack.append((c, 0))
    return ans

import java.util.*;

class Solution {
    public int getTimeToStabilize(String pipeline, char failedService) {
        Deque<int[]> stack = new ArrayDeque<>();
        int ans = 0;
        for (char c : pipeline.toCharArray()) {
            if (c == failedService) {
                if (!stack.isEmpty() && stack.peek()[0] != failedService) {
                    int top = stack.pop()[1];
                    int newR = top + 1;
                    ans = Math.max(ans, newR);
                    stack.push(new int[] { failedService, newR });
                } else {
                    stack.push(new int[] { failedService, 0 });
                }
            } else {
                stack.push(new int[] { c, 0 });
            }
        }
        return ans;
    }
}

