class Solution {
    public int findMinimumGroups(int[] security) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int s : security) cnt.merge(s, 1, Integer::sum);
        int maxC = 0;
        for (int v : cnt.values()) maxC = Math.max(maxC, v);
        int best = Integer.MAX_VALUE;
        for (int g = 1; g <= maxC; g++) {
            int groups = 0;
            for (int c : cnt.values()) groups += (c + g) / (g + 1);
            best = Math.min(best, groups);
        }
        return best;
    }
}

