def countBoughtItems(initialMoney, items):
    n = len(items)
    total_per_round = sum(items)
    if total_per_round == 0:
        return 0
    lo, hi = 0, 2 * (10 ** 9)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        cost_k = total_per_round * mid * (mid + 1) // 2
        if cost_k <= initialMoney:
            lo = mid
        else:
            hi = mid - 1
    k = lo
    bought = k * n
    spent = total_per_round * k * (k + 1) // 2
    money_left = initialMoney - spent
    # Continue with k+1 multiplier
    mult = k + 1
    for c in items:
        if money_left >= mult * c:
            money_left -= mult * c
            bought += 1
        else:
            break
    return bought

class Solution {
    public long countBoughtItems(long initialMoney, int[] items) {
        long n = items.length;
        long totalPerRound = 0;
        for (int c : items) totalPerRound += c;
        if (totalPerRound == 0) return 0;
        long lo = 0, hi = (long) 2e9;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            // overflow risk
            long costK = totalPerRound * mid / 2 * (mid + 1);
            if (mid % 2 == 1) costK = totalPerRound * (mid + 1) / 2 * mid;
            if (costK <= initialMoney) lo = mid;
            else hi = mid - 1;
        }
        long k = lo;
        long bought = k * n;
        long spent = totalPerRound * k * (k + 1) / 2;
        long money = initialMoney - spent;
        long mult = k + 1;
        for (int c : items) {
            if (money >= mult * (long) c) {
                money -= mult * (long) c;
                bought++;
            } else break;
        }
        return bought;
    }
}

