def buildInspectionDays(max_products, tasks):
    inv = 0
    emergency_days = 0
    for t in tasks:
        if t > 0:
            inv += t
            if inv > max_products:
                return -1
        elif t < 0:
            inv += t
        else:
            if inv < 0:
                # Need emergency to make inv >= 0 on this inspection morning
                # The emergency was placed on this morning; count this day.
                emergency_days += 1
                inv = 0
    return emergency_days

class Solution {
    public int buildInspectionDays(long maxProducts, int[] tasks) {
        long inv = 0;
        int days = 0;
        for (int t : tasks) {
            if (t > 0) {
                inv += t;
                if (inv > maxProducts) return -1;
            } else if (t < 0) {
                inv += t;
            } else {
                if (inv < 0) { days++; inv = 0; }
            }
        }
        return days;
    }
}

