class Solution {
    public long maximizeRentalRevenue(int[] vmStock, int m) {
        TreeMap<Integer, Integer> stocks = new TreeMap<>();
        for (int s : vmStock) if (s > 0) stocks.merge(s, 1, Integer::sum);
        long revenue = 0;
        for (int i = 0; i < m; i++) {
            if (stocks.isEmpty()) break;
            int top = stocks.lastKey();
            int bot = stocks.firstKey();
            revenue += (long) top + bot;
            if (stocks.get(top) == 1) stocks.remove(top);
            else stocks.put(top, stocks.get(top) - 1);
            if (top - 1 > 0) stocks.merge(top - 1, 1, Integer::sum);
        }
        return revenue;
    }
}

