        long long revenue = 0;
        for (int i = 0; i < m; i++) {
            if (stocks.empty()) break;
            auto& top = *stocks.rbegin();
            auto& bot = *stocks.begin();
            int topKey = top.first;
            revenue += topKey + bot.first;
            if (top.second == 1) stocks.erase(topKey);
            else stocks[topKey]--;
            if (topKey - 1 > 0) stocks[topKey - 1]++;
        }
        return revenue;
    }
};

def calculateMinimumCost(cost):
    V = max(cost)
    present = [False] * (V + 1)
    for c in cost:
        present[c] = True
    min_div = [c for c in range(V + 1)]
    for v in range(1, V + 1):
        if present[v]:
            for mult in range(v, V + 1, v):
                if v < min_div[mult]:
                    min_div[mult] = v
    return sum(min_div[c] for c in cost)

class Solution {
    public long calculateMinimumCost(int[] cost) {
        int V = 0;
        for (int c : cost) V = Math.max(V, c);
        boolean[] present = new boolean[V + 1];
        for (int c : cost) present[c] = true;
        int[] minDiv = new int[V + 1];
        for (int i = 0; i <= V; i++) minDiv[i] = i;
        for (int v = 1; v <= V; v++) {
            if (present[v]) {
                for (int mult = v; mult <= V; mult += v) {
                    if (v < minDiv[mult]) minDiv[mult] = v;
                }
            }
        }
        long ans = 0;
        for (int c : cost) ans += minDiv[c];
        return ans;
    }
}

