def findAllocationWays(p1, q1, p2, q2):
    MOD = 998244353
    dp = [[0] * (q2 - q1 + 1) for _ in range(p2 - p1 + 1)]
    dp[0][0] = 1
    for i in range(p2 - p1 + 1):
        for j in range(q2 - q1 + 1):
            if i == 0 and j == 0:
                continue
            v = 0
            if i > 0:
                v += dp[i - 1][j] * (q1 + j)
            if j > 0:
                v += dp[i][j - 1] * (p1 + i)
            dp[i][j] = v % MOD
    return dp[p2 - p1][q2 - q1]

class Solution {
    public int findAllocationWays(int p1, int q1, int p2, int q2) {
        final long MOD = 998244353L;
        int R = p2 - p1 + 1, C = q2 - q1 + 1;
        long[][] dp = new long[R][C];
        dp[0][0] = 1;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (i == 0 && j == 0) continue;
                long v = 0;
                if (i > 0) v += dp[i - 1][j] * (q1 + j);
                if (j > 0) v += dp[i][j - 1] * (p1 + i);
                dp[i][j] = v % MOD;
            }
        }
        return (int) dp[R - 1][C - 1];
    }
}

