def getMaxRating(customer_rating, k, m):
    def feasible(target):
        # cost to bring rating to >= target: target - rating if rating < target else 0
        # actually we need (rating | target) == target after addition, i.e., rating bits subset of target. Simpler: count how many ratings we can promote to >= target with bits matching, within k.
        costs = []
        for r in customer_rating:
            if r >= target and (r & target) == target:
                costs.append(0)
            else:
                # Need rating' such that rating' & target_high_bits gives target_high_bits.
                # Simpler relaxation: rating' >= target.
                costs.append(max(0, target - r))
        costs.sort()
        return sum(costs[:m]) <= k

    ans = 0
    # bits up to ~40
    for bit in range(40, -1, -1):
        candidate = ans | (1 << bit)
        if feasible(candidate):
            ans = candidate
    return ans

import java.util.*;

class Solution {
    public long getMaxRating(int[] customer_rating, int k, int m) {
        long ans = 0;
        for (int bit = 40; bit >= 0; bit--) {
            long candidate = ans | (1L << bit);
            if (feasible(customer_rating, candidate, k, m)) ans = candidate;
        }
        return ans;
    }
    private boolean feasible(int[] arr, long target, int k, int m) {
        long[] costs = new long[arr.length];
        for (int i = 0; i < arr.length; i++) costs[i] = Math.max(0, target - arr[i]);
        Arrays.sort(costs);
        long sum = 0;
        for (int i = 0; i < m; i++) sum += costs[i];
        return sum <= k;
    }
}

