from bisect import bisect_left, bisect_right
from collections import defaultdict

def getStaleSkillCount(numSkills, requestLogs, queryTimes, timeWindow):
    by_skill = defaultdict(list)
    for sid, t in requestLogs:
        by_skill[sid].append(t)
    for sid in by_skill:
        by_skill[sid].sort()
    out = []
    for qt in queryTimes:
        stale = 0
        for sid in range(1, numSkills + 1):
            ts = by_skill.get(sid, [])
            if not ts:
                stale += 1
                continue
            lo = qt - timeWindow
            li = bisect_left(ts, lo)
            ri = bisect_right(ts, qt)
            if li == ri:
                stale += 1
        out.append(stale)
    return out

import java.util.*;

class Solution {
    public int[] getStaleSkillCount(int numSkills, int[][] requestLogs, int[] queryTimes, int timeWindow) {
        Map<Integer, List<Integer>> bySkill = new HashMap<>();
        for (int[] log : requestLogs) bySkill.computeIfAbsent(log[0], k -> new ArrayList<>()).add(log[1]);
        for (var v : bySkill.values()) Collections.sort(v);
        int[] out = new int[queryTimes.length];
        for (int i = 0; i < queryTimes.length; i++) {
            int qt = queryTimes[i], lo = qt - timeWindow;
            int stale = 0;
            for (int sid = 1; sid <= numSkills; sid++) {
                List<Integer> ts = bySkill.get(sid);
                if (ts == null) { stale++; continue; }
                int li = lowerBound(ts, lo), ri = upperBound(ts, qt);
                if (li == ri) stale++;
            }
            out[i] = stale;
        }
        return out;
    }
    private int lowerBound(List<Integer> l, int v) {
        int lo = 0, hi = l.size();
        while (lo < hi) { int m = (lo + hi) / 2; if (l.get(m) < v) lo = m + 1; else hi = m; }
        return lo;
    }
    private int upperBound(List<Integer> l, int v) {
        int lo = 0, hi = l.size();
        while (lo < hi) { int m = (lo + hi) / 2; if (l.get(m) <= v) lo = m + 1; else hi = m; }
        return lo;
    }
}

