from collections import deque

def minDistance(area):
    rows, cols = len(area), len(area[0])
    if area[0][0] == 0:
        return -1
    visited = [[False] * cols for _ in range(rows)]
    visited[0][0] = True
    q = deque([(0, 0, 0)])
    while q:
        r, c, d = q.popleft()
        if area[r][c] == 9:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and area[nr][nc] != 0:
                visited[nr][nc] = True
                q.append((nr, nc, d + 1))
    return -1

import java.util.*;

class Solution {
    public int minDistance(int[][] area) {
        int rows = area.length, cols = area[0].length;
        if (area[0][0] == 0) return -1;
        boolean[][] visited = new boolean[rows][cols];
        visited[0][0] = true;
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{0, 0, 0});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            if (area[r][c] == 9) return d;
            for (int[] dir : dirs) {
                int nr = r + dir[0], nc = c + dir[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc] && area[nr][nc] != 0) {
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc, d + 1});
                }
            }
        }
        return -1;
    }
}

