        final int MOD = 1_000_000_007;
        long cnt0 = 0, cnt1 = 0, err = 0;
        for (char ch : errorString.toCharArray()) {
            if (ch == '0') {
                err = (err + cnt1 * y) % MOD;
                cnt0++;
            } else if (ch == '1') {
                err = (err + cnt0 * x) % MOD;
                cnt1++;
            } else {
                long cost0 = cnt1 * y;
                long cost1 = cnt0 * x;
                if (cost0 <= cost1) {
                    err = (err + cost0) % MOD;
                    cnt0++;
                } else {
                    err = (err + cost1) % MOD;
                    cnt1++;
                }
            }
        }
        return (int) err;
    }
}

