from collections import Counter

def getDistinctPairs(stocksProfit, target):
    freq = Counter(stocksProfit)
    ans = 0
    for a in freq:
        b = target - a
        if b not in freq:
            continue
        if a < b:
            ans += 1
        elif a == b and freq[a] >= 2:
            ans += 1
    return ans

import java.util.*;

class Solution {
    public int getDistinctPairs(int[] stocksProfit, long target) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : stocksProfit) freq.merge(v, 1, Integer::sum);
        int ans = 0;
        for (int a : freq.keySet()) {
            long b = target - a;
            if (b < Integer.MIN_VALUE || b > Integer.MAX_VALUE) continue;
            Integer cb = freq.get((int) b);
            if (cb == null) continue;
            if (a < b) ans++;
            else if (a == b && cb >= 2) ans++;
        }
        return ans;
    }
}

