class Solution {
    public int countSecurePasswordVariations(String c, String s) {
        final long MOD = 1_000_000_007L;
        int n = c.length(), m = s.length();
        long[] dp = new long[m + 1];
        dp[0] = 1;
        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            char ch = c.charAt(i);
            long tail = pow2[n - i - 1];
            ans = (ans + dp[m] * tail) % MOD;
            for (int j = 0; j < m; j++) {
                if (ch > s.charAt(j)) {
                    ans = (ans + dp[j] * tail) % MOD;
                }
            }
            for (int j = m; j >= 1; j--) {
                if (ch == s.charAt(j - 1)) {
                    dp[j] = (dp[j] + dp[j - 1]) % MOD;
                }
            }
        }
        return (int) ans;
    }
}

