class Solution {
    public int[] assignTasks(int servers, int[] requests) {
        PriorityQueue<Integer> free = new PriorityQueue<>();
        for (int i = 0; i < servers; i++) free.add(i);
        PriorityQueue<long[]> busy = new PriorityQueue<>((a, b) ->
            a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        int[] ans = new int[requests.length];
        for (int t = 0; t < requests.length; t++) {
            while (!busy.isEmpty() && busy.peek()[0] <= t) free.add((int) busy.poll()[1]);
            int sid;
            if (!free.isEmpty()) {
                sid = free.poll();
                busy.add(new long[]{t + requests[t], sid});
            } else {
                long[] top = busy.poll();
                sid = (int) top[1];
                busy.add(new long[]{top[0] + requests[t], sid});
            }
            ans[t] = sid;
        }
        return ans;
    }
}

class Solution {
public:
    vector<int> assignTasks(int servers, vector<int>& requests) {
        priority_queue<int, vector<int>, greater<int>> freeQ;
        for (int i = 0; i < servers; i++) freeQ.push(i);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> busy;
        vector<int> ans;
        for (int t = 0; t < (int)requests.size(); t++) {
            while (!busy.empty() && busy.top().first <= t) {
                freeQ.push(busy.top().second);
                busy.pop();
            }
            int sid;
            if (!freeQ.empty()) {
                sid = freeQ.top(); freeQ.pop();
                busy.push({(long long)t + requests[t], sid});
            } else {
                auto [done, s] = busy.top(); busy.pop();
                sid = s;
                busy.push({done + requests[t], sid});
            }
            ans.push_back(sid);
        }
        return ans;
    }
};

def bestWayToPack(s_id):
    stack = []
    delayed = []
    for ch in s_id:
        while stack and stack[-1] > ch:
            d = stack.pop()
            delayed.append(min(int(d) + 1, 9))
        stack.append(ch)
    tail = sorted(delayed)
    return "".join(stack) + "".join(str(x) for x in tail)

class Solution {
    public String bestWayToPack(String s) {
        StringBuilder stack = new StringBuilder();
        List<Integer> delayed = new ArrayList<>();
        for (char ch : s.toCharArray()) {
            while (stack.length() > 0 && stack.charAt(stack.length() - 1) > ch) {
                int d = stack.charAt(stack.length() - 1) - '0';
                stack.deleteCharAt(stack.length() - 1);
                delayed.add(Math.min(d + 1, 9));
            }
            stack.append(ch);
        }
        Collections.sort(delayed);
        for (int d : delayed) stack.append(d);
        return stack.toString();
    }
}

class Solution {
public:
    string bestWayToPack(string s) {
        string stk;
        vector<int> delayed;
        for (char ch : s) {
            while (!stk.empty() && stk.back() > ch) {
                int d = stk.back() - '0';
                stk.pop_back();
                delayed.push_back(min(d + 1, 9));
            }
            stk.push_back(ch);
        }
        sort(delayed.begin(), delayed.end());
        for (int d : delayed) stk.push_back('0' + d);
        return stk;
    }
};

class Solution {
    public long minimumRequests(int[] request, int[] health, int k) {
        int n = request.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> request[b] - request[a]);
        long aliveSum = 0;
        for (int r : request) aliveSum += r;
        long total = 0;
        for (int i : idx) {
            long secs = (health[i] + k - 1) / k;
            total += aliveSum * secs;
            aliveSum -= request[i];
        }
        return total + 1;
    }
}

