from bisect import bisect_left

def calculateBeautyValues(arr, pairs):
    n = len(arr)
    used = [False] * n
    for l, r in pairs:
        for i in range(l, r + 1):
            used[i] = True
    sorted_arr = sorted(arr)
    total = 0
    for i in range(n):
        if not used[i]:
            total += bisect_left(sorted_arr, arr[i])
    return total

class Solution {
    public int calculateBeautyValues(int[] arr, int[][] pairs) {
        int n = arr.length;
        boolean[] used = new boolean[n];
        for (int[] p : pairs)
            for (int i = p[0]; i <= p[1]; i++) used[i] = true;
        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        int total = 0;
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                int lo = 0, hi = n;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (sorted[mid] < arr[i]) lo = mid + 1;
                    else hi = mid;
                }
                total += lo;
            }
        }
        return total;
    }
}

class Solution {
public:
    int calculateBeautyValues(vector<int>& arr, vector<vector<int>>& pairs) {
        int n = arr.size();
        vector<bool> used(n, false);
        for (auto& p : pairs)
            for (int i = p[0]; i <= p[1]; i++) used[i] = true;
        vector<int> sorted = arr;
        sort(sorted.begin(), sorted.end());
        int total = 0;
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                total += lower_bound(sorted.begin(), sorted.end(), arr[i]) - sorted.begin();
            }
        }
        return total;
    }
};

def calculateMaxProfit(price, futurePrice, principle):
    n = len(price)
    dp = [0] * (principle + 1)
    for i in range(n):
        profit = futurePrice[i] - price[i]
        if profit <= 0 or price[i] > principle:
            continue
        for w in range(principle, price[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - price[i]] + profit)
    return dp[principle]

class Solution {
    public int calculateMaxProfit(int[] price, int[] futurePrice, int principle) {
        int n = price.length;
        int[] dp = new int[principle + 1];
        for (int i = 0; i < n; i++) {
            int profit = futurePrice[i] - price[i];
            if (profit <= 0 || price[i] > principle) continue;
            for (int w = principle; w >= price[i]; w--) {
                dp[w] = Math.max(dp[w], dp[w - price[i]] + profit);
            }
        }
        return dp[principle];
    }
}

