                dp[w] = max(dp[w], dp[w - price[i]] + profit);
            }
        }
        return dp[principle];
    }
};

def calculateMaxQualityScore(impactFactor, ratings):
    cur = best = ratings[0]
    for v in ratings[1:]:
        cur = max(v, cur + v)
        best = max(best, cur)
    if best > 0:
        return best * impactFactor
    mx = max(ratings)
    # mx ≤ 0: for negative x, x // f rounds toward -inf; we want ceiling, i.e., -((-x) // f)
    if mx >= 0:
        return mx * impactFactor
    return -((-mx) // impactFactor)

class Solution {
    public long calculateMaxQualityScore(int impactFactor, int[] ratings) {
        long cur = ratings[0], best = ratings[0];
        for (int i = 1; i < ratings.length; i++) {
            cur = Math.max((long) ratings[i], cur + ratings[i]);
            best = Math.max(best, cur);
        }
        if (best > 0) return best * impactFactor;
        int mx = Integer.MIN_VALUE;
        for (int v : ratings) mx = Math.max(mx, v);
        if (mx >= 0) return (long) mx * impactFactor;
        return -((long)(-mx) / impactFactor);
    }
}

