public:
    long long calculateMaxQualityScore(int impactFactor, vector<int>& ratings) {
        long long cur = ratings[0], best = ratings[0];
        for (size_t i = 1; i < ratings.size(); i++) {
            cur = max<long long>(ratings[i], cur + ratings[i]);
            best = max(best, cur);
        }
        if (best > 0) return best * impactFactor;
        int mx = INT_MIN;
        for (int v : ratings) mx = max(mx, v);
        if (mx >= 0) return (long long) mx * impactFactor;
        return -((long long)(-mx) / impactFactor);
    }
};

def calculateMaxSalary(schedule):
    sal = [1, 10, 100, 1000, 10000]
    pri = lambda c: ord(c) - ord('A')
    s = list(schedule)
    n = len(s)

    def total(arr):
        suf_max = -1
        t = 0
        for i in range(n - 1, -1, -1):
            p = pri(arr[i])
            if suf_max > p:
                t -= sal[p]
            else:
                t += sal[p]
            suf_max = max(suf_max, p)
        return t

    best = total(s)
    for i in range(n):
        orig = s[i]
        for c in "ABCDE":
            if c == orig:
                continue
            s[i] = c
            best = max(best, total(s))
        s[i] = orig
    return best

class Solution {
    int[] sal = {1, 10, 100, 1000, 10000};
    int total(char[] s) {
        int sufMax = -1, t = 0;
        for (int i = s.length - 1; i >= 0; i--) {
            int p = s[i] - 'A';
            if (sufMax > p) t -= sal[p];
            else t += sal[p];
            if (p > sufMax) sufMax = p;
        }
        return t;
    }
    public int calculateMaxSalary(String schedule) {
        char[] s = schedule.toCharArray();
        int best = total(s);
        for (int i = 0; i < s.length; i++) {
            char orig = s[i];
            for (char c = 'A'; c <= 'E'; c++) {
                if (c == orig) continue;
                s[i] = c;
                best = Math.max(best, total(s));
            }
            s[i] = orig;
        }
        return best;
    }
}

