def calculateMedianSum(packets, n):
    arr = sorted(packets, reverse=True)
    total = sum(arr[:n - 1])
    rest = sorted(arr[n - 1:])
    m = len(rest)
    if m == 0:
        return round(total)
    if m % 2 == 1:
        med = rest[m // 2]
    else:
        med = (rest[m // 2 - 1] + rest[m // 2]) / 2
    return round(total + med)

class Solution {
    public int calculateMedianSum(int[] packets, int n) {
        Integer[] arr = Arrays.stream(packets).boxed().toArray(Integer[]::new);
        Arrays.sort(arr, Collections.reverseOrder());
        double total = 0;
        for (int i = 0; i < n - 1; i++) total += arr[i];
        int[] rest = new int[arr.length - (n - 1)];
        for (int i = 0; i < rest.length; i++) rest[i] = arr[n - 1 + i];
        Arrays.sort(rest);
        int m = rest.length;
        double med = 0;
        if (m > 0) {
            med = (m % 2 == 1) ? rest[m / 2] : (rest[m / 2 - 1] + rest[m / 2]) / 2.0;
        }
        return (int) Math.round(total + med);
    }
}

class Solution {
public:
    int calculateMedianSum(vector<int>& packets, int n) {
        vector<int> arr = packets;
        sort(arr.begin(), arr.end(), greater<int>());
        double total = 0;
        for (int i = 0; i < n - 1; i++) total += arr[i];
        vector<int> rest(arr.begin() + (n - 1), arr.end());
        sort(rest.begin(), rest.end());
        int m = rest.size();
        double med = 0;
        if (m > 0) {
            med = (m % 2 == 1) ? rest[m / 2] : (rest[m / 2 - 1] + rest[m / 2]) / 2.0;
        }
        return (int) round(total + med);
    }
};

from bisect import bisect_left

def calculateTotalDistanceTravelled(trucks, extraGasStations):
    n = len(trucks)
    ans = []
    for query in extraGasStations:
        stations = {trucks[n - 1]}
        for idx in query:
            stations.add(trucks[idx - 1])
        s = sorted(stations)
        total = 0
        for pos in trucks:
            j = bisect_left(s, pos)
            total += s[j] - pos
        ans.append(total)
    return ans

class Solution {
    public int[] calculateTotalDistanceTravelled(int[] trucks, int[][] extraGasStations) {
        int n = trucks.length;
        int[] ans = new int[extraGasStations.length];
        for (int q = 0; q < extraGasStations.length; q++) {
            TreeSet<Integer> set = new TreeSet<>();
            set.add(trucks[n - 1]);
            for (int idx : extraGasStations[q]) set.add(trucks[idx - 1]);
            int total = 0;
            for (int pos : trucks) total += set.ceiling(pos) - pos;
            ans[q] = total;
        }
        return ans;
    }
}

class Solution {
public:
    vector<int> calculateTotalDistanceTravelled(vector<int>& trucks, vector<vector<int>>& extraGasStations) {
        int n = trucks.size();
        vector<int> ans;
        for (auto& query : extraGasStations) {
            set<int> st;
            st.insert(trucks[n - 1]);
            for (int idx : query) st.insert(trucks[idx - 1]);
            int total = 0;
            for (int pos : trucks) total += *st.lower_bound(pos) - pos;
            ans.push_back(total);
        }
        return ans;
    }
};

class Solution {
    public long[] calculateTruckDistanceAfterRefueling(int[] position, int[][] extraGasStations) {
        int n = position.length;
        long[] ans = new long[extraGasStations.length];
        for (int q = 0; q < extraGasStations.length; q++) {
            int[] qa = extraGasStations[q];
            TreeSet<Integer> set = new TreeSet<>();
            set.add(position[qa[0] - 1]);
            set.add(position[qa[1] - 1]);
            set.add(position[n - 1]);
            long total = 0;
            for (int p : position) total += set.ceiling(p) - p;
            ans[q] = total;
        }
        return ans;
    }
}

