class Solution {
    public long calculateWarehouseEfficiency(int[] parcelWeights) {
        int n = parcelWeights.length;
        int days = (n + 1) / 2;
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long total = 0;
        for (int t = days; t >= 1; t--) {
            int l = t - 1, r = n - t;
            heap.add(parcelWeights[l]);
            if (r != l) heap.add(parcelWeights[r]);
            total += heap.poll();
        }
        return total;
    }
}

class Solution {
public:
    long long calculateWarehouseEfficiency(vector<int>& parcelWeights) {
        int n = parcelWeights.size();
        int days = (n + 1) / 2;
        priority_queue<int> heap;
        long long total = 0;
        for (int t = days; t >= 1; t--) {
            int l = t - 1, r = n - t;
            heap.push(parcelWeights[l]);
            if (r != l) heap.push(parcelWeights[r]);
            total += heap.top();
            heap.pop();
        }
        return total;
    }
};

def canSortPermutation(p, moves):
    n = len(p)
    visited = [False] * n
    cycles = 0
    for i in range(n):
        if not visited[i]:
            cycles += 1
            j = i
            while not visited[j]:
                visited[j] = True
                j = p[j] - 1
    min_moves = n - cycles
    out = []
    for k in moves:
        if k < min_moves:
            out.append('0')
        elif (k - min_moves) % 2 == 0:
            out.append('1')
        elif n >= 2:
            # need to waste an odd number — impossible
            out.append('0')
        else:
            out.append('0')
    return ''.join(out)

class Solution {
    public String canSortPermutation(int[] p, int[] moves) {
        int n = p.length;
        boolean[] visited = new boolean[n];
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                cycles++;
                int j = i;
                while (!visited[j]) {
                    visited[j] = true;
                    j = p[j] - 1;
                }
            }
        }
        int minMoves = n - cycles;
        StringBuilder sb = new StringBuilder();
        for (int k : moves) {
            if (k >= minMoves && (k - minMoves) % 2 == 0) sb.append('1');
            else sb.append('0');
        }
        return sb.toString();
    }
}

class Solution {
public:
    string canSortPermutation(vector<int>& p, vector<int>& moves) {
        int n = p.size();
        vector<bool> visited(n, false);
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                cycles++;
                int j = i;
                while (!visited[j]) { visited[j] = true; j = p[j] - 1; }
            }
        }
        int minMoves = n - cycles;
        string out;
        for (int k : moves) {
            if (k >= minMoves && (k - minMoves) % 2 == 0) out.push_back('1');
            else out.push_back('0');
        }
        return out;
    }
};

class Solution {
    long[] pre;
    int[] a;
    long cost(int l, int r) {
        if (l > r) return 0;
        int m = (l + r) / 2;
        long rightSum = pre[r + 1] - pre[m + 1];
        long leftSum = pre[m] - pre[l];
        int rightCnt = r - m, leftCnt = m - l;
        return rightSum - (long) a[m] * rightCnt + (long) a[m] * leftCnt - leftSum;
    }
    public long minSumDistancesToWarehouses(int[] dist_centers) {
        a = dist_centers.clone();
        Arrays.sort(a);
        int n = a.length;
        pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        long best = Long.MAX_VALUE;
        for (int i = 0; i < n - 1; i++) {
            best = Math.min(best, cost(0, i) + cost(i + 1, n - 1));
        }
        return best;
    }
}

