        int m = (l + r) / 2;
        long long rightSum = pre[r + 1] - pre[m + 1];
        long long leftSum = pre[m] - pre[l];
        int rightCnt = r - m, leftCnt = m - l;
        return rightSum - (long long) a[m] * rightCnt + (long long) a[m] * leftCnt - leftSum;
    }
    long long minSumDistancesToWarehouses(vector<int>& dist_centers) {
        a = dist_centers;
