        pre.assign(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        long long best = LLONG_MAX;
        for (int i = 0; i < n - 1; i++) {
            best = min(best, cost(0, i) + cost(i + 1, n - 1));
        }
        return best;
    }
};

class Solution {
    public int cinemaShows(int[] start, int[] duration, int[] volume) {
        int n = start.length;
        long[][] shows = new long[n][3]; // start, end, volume
        for (int i = 0; i < n; i++) {
            shows[i] = new long[]{start[i], (long) start[i] + duration[i], volume[i]};
        }
        Arrays.sort(shows, (a, b) -> Long.compare(a[1], b[1]));
        long[] ends = new long[n];
        for (int i = 0; i < n; i++) ends[i] = shows[i][1];
        int[] dp = new int[n + 1];
        for (int i = 0; i < n; i++) {
            long s = shows[i][0];
            int lo = 0, hi = i;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] <= s) lo = mid + 1;
                else hi = mid;
            }
            int j = lo - 1;
            int take = (int) shows[i][2] + (j >= 0 ? dp[j + 1] : 0);
            dp[i + 1] = Math.max(dp[i], take);
        }
        return dp[n];
    }
}

class Solution {
public:
    int cinemaShows(vector<int>& start, vector<int>& duration, vector<int>& volume) {
        int n = start.size();
        vector<tuple<long long, long long, int>> shows;
        for (int i = 0; i < n; i++) {
            shows.emplace_back(start[i], (long long) start[i] + duration[i], volume[i]);
        }
        sort(shows.begin(), shows.end(), [](auto& a, auto& b){ return get<1>(a) < get<1>(b); });
        vector<long long> ends(n);
        for (int i = 0; i < n; i++) ends[i] = get<1>(shows[i]);
        vector<int> dp(n + 1, 0);
        for (int i = 0; i < n; i++) {
            long long s = get<0>(shows[i]);
            int j = (int)(upper_bound(ends.begin(), ends.begin() + i, s) - ends.begin()) - 1;
            int take = get<2>(shows[i]) + (j >= 0 ? dp[j + 1] : 0);
            dp[i + 1] = max(dp[i], take);
        }
        return dp[n];
    }
};

class Solution {
    public long circularRouteQueryDistance(int[] distances, int[][] queries) {
        int n = distances.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + distances[i];
        long total = pre[n];
        long ans = 0;
        for (int[] q : queries) {
            long fwd = ((pre[q[1]] - pre[q[0]]) % total + total) % total;
            ans += Math.min(fwd, total - fwd);
        }
        return ans;
    }
}

