};

class Solution {
    public long cleanupDataset(String dataset, int x, int y) {
        int[] cnt = new int[26];
        for (char c : dataset.toCharArray()) cnt[c - 'a']++;
        int n = dataset.length();
        int ops = n / 2;
        int maxPairsEq = 0, maxC = 0;
        for (int c : cnt) { maxPairsEq += c / 2; if (c > maxC) maxC = c; }
        int minPairsEq = (2 * maxC > n) ? (2 * maxC - n) / 2 : 0;
        int eq = (x <= y) ? Math.min(maxPairsEq, ops) : minPairsEq;
        int diff = ops - eq;
        return (long) eq * x + (long) diff * y;
    }
}

class Solution {
public:
    long long cleanupDataset(string dataset, int x, int y) {
        int cnt[26] = {0};
        for (char c : dataset) cnt[c - 'a']++;
        int n = dataset.size();
        int ops = n / 2;
        int maxPairsEq = 0, maxC = 0;
        for (int c : cnt) { maxPairsEq += c / 2; maxC = max(maxC, c); }
        int minPairsEq = (2 * maxC > n) ? (2 * maxC - n) / 2 : 0;
        int eq = (x <= y) ? min(maxPairsEq, ops) : minPairsEq;
        int diff = ops - eq;
        return (long long) eq * x + (long long) diff * y;
    }
};

def computeBeauty(products, k):
    n = len(products)
    R = [n] * n
    stk = []
    for i in range(n - 1, -1, -1):
        while stk and products[stk[-1]] < products[i]:
            stk.pop()
        R[i] = stk[-1] if stk else n
        stk.append(i)
    if k > n:
        return 0
    total = 0
    for i in range(n):
        lo = max(0, i - k + 1)
        hi = min(i, n - k, R[i] - k)
        if hi >= lo:
            total += hi - lo + 1
    return total

class Solution {
    public long computeBeauty(int[] products, int k) {
        int n = products.length;
        int[] R = new int[n];
        Deque<Integer> stk = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.isEmpty() && products[stk.peek()] < products[i]) stk.pop();
            R[i] = stk.isEmpty() ? n : stk.peek();
            stk.push(i);
        }
        if (k > n) return 0;
        long total = 0;
        for (int i = 0; i < n; i++) {
            int lo = Math.max(0, i - k + 1);
            int hi = Math.min(Math.min(i, n - k), R[i] - k);
            if (hi >= lo) total += hi - lo + 1;
        }
        return total;
    }
}

class Solution {
public:
    long long computeBeauty(vector<int>& products, int k) {
        int n = products.size();
        vector<int> R(n, n);
        vector<int> stk;
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.empty() && products[stk.back()] < products[i]) stk.pop_back();
            R[i] = stk.empty() ? n : stk.back();
            stk.push_back(i);
        }
        if (k > n) return 0;
        long long total = 0;
        for (int i = 0; i < n; i++) {
            int lo = max(0, i - k + 1);
            int hi = min({i, n - k, R[i] - k});
            if (hi >= lo) total += hi - lo + 1;
        }
        return total;
    }
};

def computeEncodedProductName(nameString):
    cnt = [0] * 26
    for c in nameString:
        cnt[ord(c) - ord('a')] += 1
    half = []
    mid = ''
    for i in range(26):
        half.append(chr(ord('a') + i) * (cnt[i] // 2))
        if cnt[i] % 2 == 1:
            mid = chr(ord('a') + i)
    left = ''.join(half)
    return left + mid + left[::-1]

class Solution {
    public String computeEncodedProductName(String nameString) {
        int[] cnt = new int[26];
        for (char c : nameString.toCharArray()) cnt[c - 'a']++;
        StringBuilder half = new StringBuilder();
        char mid = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < cnt[i] / 2; j++) half.append((char) ('a' + i));
            if (cnt[i] % 2 == 1) mid = (char) ('a' + i);
        }
        StringBuilder res = new StringBuilder(half);
        if (mid != 0) res.append(mid);
        res.append(half.reverse());
        return res.toString();
    }
}

class Solution {
public:
    string computeEncodedProductName(string nameString) {
        int cnt[26] = {0};
        for (char c : nameString) cnt[c - 'a']++;
        string half;
        char mid = 0;
        for (int i = 0; i < 26; i++) {
            half.append(cnt[i] / 2, 'a' + i);
            if (cnt[i] % 2 == 1) mid = 'a' + i;
        }
        string res = half;
        if (mid) res += mid;
        reverse(half.begin(), half.end());
        res += half;
        return res;
    }
};

class Solution {
    public int convertToGoodString(String s) {
        int n = s.length();
        int[] preZero = new int[n + 1];
        for (int i = 0; i < n; i++) preZero[i + 1] = preZero[i] + (s.charAt(i) == '0' ? 1 : 0);
        int totalOne = n - preZero[n];
        int best = Integer.MAX_VALUE;
        for (int p = 0; p <= n; p++) {
            int zerosLeft = preZero[p];
            int onesRight = totalOne - (p - preZero[p]);
            best = Math.min(best, zerosLeft + onesRight);
        }
        return best;
    }
}

