class Solution {
    public long countDistinctPasswords(String password) {
        StringBuilder sb = new StringBuilder("#");
        for (char c : password.toCharArray()) { sb.append(c).append('#'); }
        String t = sb.toString();
        int n = t.length();
        int[] p = new int[n];
        int c = 0, r = 0;
        for (int i = 0; i < n; i++) {
            int mirror = 2 * c - i;
            if (i < r) p[i] = Math.min(r - i, p[mirror]);
            while (i + p[i] + 1 < n && i - p[i] - 1 >= 0 && t.charAt(i + p[i] + 1) == t.charAt(i - p[i] - 1)) p[i]++;
            if (i + p[i] > r) { c = i; r = i + p[i]; }
        }
        long palindromes = 0;
        for (int v : p) palindromes += (v + 1) / 2;
        long n2 = password.length();
        long total = n2 * (n2 + 1) / 2;
        return total - palindromes + 1;
    }
}

