class Solution {
    public long countDominantSubstrings(String s) {
        int n = s.length();
        long total = 0;
        boolean[] seen = new boolean[26];
        for (char ch : s.toCharArray()) seen[ch - 'a'] = true;
        for (int c = 0; c < 26; c++) {
            if (!seen[c]) continue;
            HashMap<Integer, Integer> cnt = new HashMap<>();
            cnt.put(0, 1);
            int pre = 0;
            for (int i = 0; i < n; i++) {
                pre += (s.charAt(i) - 'a' == c) ? 1 : -1;
                total += cnt.getOrDefault(pre, 0);
                cnt.merge(pre, 1, Integer::sum);
            }
        }
        for (int c1 = 0; c1 < 26; c1++) {
            if (!seen[c1]) continue;
            for (int c2 = c1 + 1; c2 < 26; c2++) {
                if (!seen[c2]) continue;
                HashMap<Integer, Integer> cnt = new HashMap<>();
                cnt.put(0, 1);
                int pre = 0;
                for (int i = 0; i < n; i++) {
                    int ch = s.charAt(i) - 'a';
                    if (ch == c1) pre++;
                    else if (ch == c2) pre--;
                    else {
                        pre = 0; cnt.clear(); cnt.put(0, 1); continue;
                    }
                    total -= cnt.getOrDefault(pre, 0);
                    cnt.merge(pre, 1, Integer::sum);
                }
            }
        }
        return total;
    }
}

class Solution {
public:
