        bool seen[26] = {false};
        for (char ch : s) seen[ch - 'a'] = true;
        for (int c = 0; c < 26; c++) {
            if (!seen[c]) continue;
            unordered_map<int, int> cnt;
            cnt[0] = 1;
            int pre = 0;
            for (char ch : s) {
                pre += (ch - 'a' == c) ? 1 : -1;
                total += cnt[pre];
                cnt[pre]++;
            }
        }
        for (int c1 = 0; c1 < 26; c1++) {
            if (!seen[c1]) continue;
            for (int c2 = c1 + 1; c2 < 26; c2++) {
                if (!seen[c2]) continue;
                unordered_map<int, int> cnt;
                cnt[0] = 1;
                int pre = 0;
                for (char ch : s) {
                    int x = ch - 'a';
                    if (x == c1) pre++;
                    else if (x == c2) pre--;
                    else { pre = 0; cnt.clear(); cnt[0] = 1; continue; }
                    total -= cnt[pre];
                    cnt[pre]++;
                }
            }
        }
        return total;
    }
};

