def countFaults(n, logs):
    streak = {}
    replaced = 0
    for log in logs:
        sid, status = log.split()
        if status == "error":
            streak[sid] = streak.get(sid, 0) + 1
            if streak[sid] == 3:
                replaced += 1
                streak[sid] = 0
        else:
            streak[sid] = 0
    return replaced

class Solution {
    public int countFaults(int n, String[] logs) {
        Map<String, Integer> streak = new HashMap<>();
        int replaced = 0;
        for (String log : logs) {
            String[] parts = log.split(" ");
            String sid = parts[0];
            if (parts[1].equals("error")) {
                int s = streak.getOrDefault(sid, 0) + 1;
                if (s == 3) { replaced++; streak.put(sid, 0); }
                else streak.put(sid, s);
            } else {
                streak.put(sid, 0);
            }
        }
        return replaced;
    }
}

