public:
    int countFaults(int n, vector<string>& logs) {
        unordered_map<string, int> streak;
        int replaced = 0;
        for (auto& log : logs) {
            size_t sp = log.find(' ');
            string sid = log.substr(0, sp);
            string status = log.substr(sp + 1);
            if (status == "error") {
                int s = ++streak[sid];
                if (s == 3) { replaced++; streak[sid] = 0; }
            } else {
                streak[sid] = 0;
            }
        }
        return replaced;
    }
};

