def countSecuredStrings(s, t):
    MOD = 10**9 + 7
    n, m = len(s), len(t)
    # eq[j] for j in 0..m, plus smaller, greater
    eq = [0] * (m + 1)
    eq[0] = 1
    smaller = 0
    greater = 0
    for c in s:
        new_eq = eq[:]
        new_s = (smaller * 2) % MOD  # skip + include
        new_g = (greater * 2) % MOD
        for j in range(m + 1):
            if eq[j] == 0:
                continue
            if j < m:
                tj = t[j]
                if c == tj:
                    new_eq[j + 1] = (new_eq[j + 1] + eq[j]) % MOD
                elif c < tj:
                    new_s = (new_s + eq[j]) % MOD
                else:
                    new_g = (new_g + eq[j]) % MOD
            else:
                new_g = (new_g + eq[j]) % MOD
        eq = new_eq
        smaller = new_s
        greater = new_g
    return greater

class Solution {
    public int countSecuredStrings(String s, String t) {
        final int MOD = 1_000_000_007;
        int n = s.length(), m = t.length();
        long[] eq = new long[m + 1];
        eq[0] = 1;
        long smaller = 0, greater = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            long[] newEq = eq.clone();
            long newS = smaller * 2 % MOD;
            long newG = greater * 2 % MOD;
            for (int j = 0; j <= m; j++) {
                if (eq[j] == 0) continue;
                if (j < m) {
                    char tj = t.charAt(j);
                    if (c == tj) newEq[j + 1] = (newEq[j + 1] + eq[j]) % MOD;
                    else if (c < tj) newS = (newS + eq[j]) % MOD;
                    else newG = (newG + eq[j]) % MOD;
                } else {
                    newG = (newG + eq[j]) % MOD;
                }
            }
            eq = newEq;
            smaller = newS;
            greater = newG;
        }
        return (int) greater;
    }
}

