class Solution {
    public long countSpecialSubstrings(String genome) {
        int n = genome.length();
        long total = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && genome.charAt(j) == genome.charAt(i)) j++;
            long k = j - i;
            total += k * (k - 1) / 2;
            if (i > 0 && j < n && genome.charAt(i - 1) == genome.charAt(j)) total++;
            i = j;
        }
        return total;
    }
}

