def countSubstrings(s):
    n = len(s)
    total = 0
    for c in range(2 * n - 1):
        l, r = c // 2, c // 2 + (c & 1)
        while l >= 0 and r < n and s[l] == s[r]:
            total += 1
            l -= 1
            r += 1
    return total

class Solution {
    public int countSubstrings(String s) {
        int n = s.length(), total = 0;
        for (int c = 0; c < 2 * n - 1; c++) {
            int l = c / 2, r = c / 2 + (c & 1);
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                total++;
                l--;
                r++;
            }
        }
        return total;
    }
}

