class Solution {
    public int[] createArrayGenerator(int[] elements, String availability, int operations) {
        int n = elements.length;
        boolean[] avail = new boolean[n];
        for (int i = 0; i < n; i++) avail[i] = availability.charAt(i) == '1';
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < n; i++) if (avail[i]) heap.add(new int[]{elements[i], i});
        int[] result = new int[operations];
        for (int op = 0; op < operations; op++) {
            result[op] = heap.peek()[0];
            List<Integer> toFlip = new ArrayList<>();
            for (int i = 1; i < n; i++) {
                if (avail[i - 1] && !avail[i]) toFlip.add(i);
            }
            for (int i : toFlip) {
                avail[i] = true;
                heap.add(new int[]{elements[i], i});
            }
        }
        return result;
    }
}

class Solution {
public:
    vector<int> createArrayGenerator(vector<int>& elements, string availability, int operations) {
        int n = elements.size();
        vector<bool> avail(n);
        for (int i = 0; i < n; i++) avail[i] = availability[i] == '1';
        priority_queue<pair<int,int>> heap;
        for (int i = 0; i < n; i++) if (avail[i]) heap.push({elements[i], i});
        vector<int> result;
        for (int op = 0; op < operations; op++) {
            result.push_back(heap.top().first);
            vector<int> toFlip;
            for (int i = 1; i < n; i++) {
                if (avail[i - 1] && !avail[i]) toFlip.push_back(i);
            }
            for (int i : toFlip) {
                avail[i] = true;
                heap.push({elements[i], i});
            }
        }
        return result;
    }
};

from functools import cmp_to_key

def customSortString(order, arr):
    rank = {c: i for i, c in enumerate(order)}
    def cmp(a, b):
        for ca, cb in zip(a, b):
            if rank[ca] != rank[cb]:
                return rank[ca] - rank[cb]
        return len(a) - len(b)
    return sorted(arr, key=cmp_to_key(cmp))

class Solution {
    public String[] customSortString(String order, String[] arr) {
        int[] rank = new int[128];
        for (int i = 0; i < order.length(); i++) rank[order.charAt(i)] = i;
        String[] res = arr.clone();
        Arrays.sort(res, (a, b) -> {
            int la = a.length(), lb = b.length();
            for (int i = 0; i < Math.min(la, lb); i++) {
                int ra = rank[a.charAt(i)], rb = rank[b.charAt(i)];
                if (ra != rb) return ra - rb;
            }
            return la - lb;
        });
        return res;
    }
}

class Solution {
public:
    vector<string> customSortString(string order, vector<string>& arr) {
        int rank[128] = {0};
        for (int i = 0; i < (int)order.size(); i++) rank[(int)order[i]] = i;
        vector<string> res = arr;
        sort(res.begin(), res.end(), [&](const string& a, const string& b) {
            int la = a.size(), lb = b.size();
            for (int i = 0; i < min(la, lb); i++) {
                int ra = rank[(int)a[i]], rb = rank[(int)b[i]];
                if (ra != rb) return ra < rb;
            }
            return la < lb;
        });
        return res;
    }
};

