            idx += 1
            if idx < n:
                remain = taskDurations[idx]
            else:
                remain = 0
        if idx < n:
            remain -= t
        ans.append(n - idx)
    return ans

class Solution {
    public int[] computeUnfinishedTasks(int[] taskDurations, int[] workShifts) {
        int n = taskDurations.length;
        int[] ans = new int[workShifts.length];
        int idx = 0;
        long remain = n > 0 ? taskDurations[0] : 0;
        for (int s = 0; s < workShifts.length; s++) {
            long t = workShifts[s];
            while (idx < n && t >= remain) {
                t -= remain;
                idx++;
                remain = (idx < n) ? taskDurations[idx] : 0;
            }
            if (idx < n) remain -= t;
            ans[s] = n - idx;
        }
        return ans;
    }
}

class Solution {
public:
    vector<int> computeUnfinishedTasks(vector<int>& taskDurations, vector<int>& workShifts) {
        int n = taskDurations.size();
