        long long remain = n > 0 ? taskDurations[0] : 0;
        for (int s : workShifts) {
            long long t = s;
            while (idx < n && t >= remain) {
                t -= remain;
                idx++;
                remain = (idx < n) ? taskDurations[idx] : 0;
            }
            if (idx < n) remain -= t;
            ans.push_back(n - idx);
        }
        return ans;
    }
};

from math import gcd

def maxPoints(inventory, dispatch1, dispatch2, skips):
    d1, d2 = dispatch1, dispatch2
    cycle = d1 + d2
    period = cycle // gcd(d1, d2) if cycle else 1
    costs = []
    auto = 0
    for v in inventory:
        # find min k ≥ 0 such that A = (v + (k+1)*d2) mod cycle satisfies
        # A == 0 or A > d2 (so next multiple within distance d1)
        found = False
        for k in range(period + 1):
            A = (v + (k + 1) * d2) % cycle
            if A == 0 or A > d2:
                import math as _m
                m = (v + (k + 1) * d2 + cycle - 1) // cycle if A != 0 else (v + (k + 1) * d2) // cycle
                if m - 1 - k >= 0:
                    if k == 0:
                        auto += 1
                    else:
                        costs.append(k)
                    found = True
                    break
        # if not found: warehouse impossible to claim
    costs.sort()
    earned = auto
    for c in costs:
        if skips >= c:
            skips -= c
            earned += 1
        else:
            break
    return earned

class Solution {
    public int maxPoints(int[] inventory, int dispatch1, int dispatch2, int skips) {
        int d1 = dispatch1, d2 = dispatch2;
        int cycle = d1 + d2;
        int period = cycle / gcd(d1, d2);
        List<Integer> costs = new ArrayList<>();
        int auto_ = 0;
        for (int v : inventory) {
            for (int k = 0; k <= period; k++) {
                long A = ((long) v + (long)(k + 1) * d2) % cycle;
                if (A == 0 || A > d2) {
                    long sum = (long) v + (long)(k + 1) * d2;
                    long m = (A == 0) ? sum / cycle : (sum + cycle - 1) / cycle;
                    if (m - 1 - k >= 0) {
                        if (k == 0) auto_++;
                        else costs.add(k);
                        break;
                    }
                }
            }
        }
        Collections.sort(costs);
        int earned = auto_;
        for (int c : costs) {
            if (skips >= c) { skips -= c; earned++; }
            else break;
        }
        return earned;
    }
    int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

