def finalPrices(n, price, q, queries):
    p = list(price)
    floor = 0
    for op, a, b in queries:
        if op == 1:
            p[a - 1] = b
        else:
            if a > floor:
                floor = a
    return [max(v, floor) for v in p]

class Solution {
    public int[] finalPrices(int n, int[] price, int q, int[][] queries) {
        int[] p = price.clone();
        int floor = 0;
        for (int[] qe : queries) {
            if (qe[0] == 1) p[qe[1] - 1] = qe[2];
            else if (qe[1] > floor) floor = qe[1];
        }
        for (int i = 0; i < n; i++) p[i] = Math.max(p[i], floor);
        return p;
    }
}

class Solution {
public:
    vector<int> finalPrices(int n, vector<int>& price, int q, vector<vector<int>>& queries) {
        vector<int> p = price;
        int floor = 0;
        for (auto& qe : queries) {
            if (qe[0] == 1) p[qe[1] - 1] = qe[2];
            else if (qe[1] > floor) floor = qe[1];
        }
        for (int i = 0; i < n; i++) p[i] = max(p[i], floor);
        return p;
    }
};

def distributeGames(games, N):
    def feasible(X):
        parts, cur = 1, 0
        for g in games:
            if cur + g > X:
                parts += 1
                cur = g
            else:
                cur += g
        return parts <= N
    lo, hi = max(games), sum(games)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int N;
    int[] games;
    boolean feasible(long X) {
        int parts = 1;
        long cur = 0;
        for (int g : games) {
            if (g > X) return false;
            if (cur + g > X) { parts++; cur = g; }
            else cur += g;
        }
        return parts <= N;
    }
    public long distributeGames(int[] games, int N) {
        this.games = games; this.N = N;
        long lo = 0, hi = 0;
        for (int g : games) { lo = Math.max(lo, g); hi += g; }
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

