            if (cur + g > X) { parts++; cur = g; }
            else cur += g;
        }
        return parts <= N;
    }
    long long distributeGames(vector<int>& g, int n) {
        games = g; N = n;
        long long lo = 0, hi = 0;
        for (int v : g) { lo = max(lo, (long long) v); hi += v; }
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

def distributePackages(trucks, to_distribute):
    def capacity(X):
        return sum(max(0, X - v) for v in trucks)
    lo, hi = max(trucks), max(trucks) + to_distribute
    while lo < hi:
        mid = (lo + hi) // 2
        if capacity(mid) >= to_distribute:
            hi = mid
        else:
            lo = mid + 1
    X = lo
    res = list(trucks)
    remaining = to_distribute
    for i in range(len(res)):
        add = min(X - res[i], remaining)
        res[i] += add
        remaining -= add
        if remaining == 0:
            break
    return res

class Solution {
    long capacity(int[] trucks, long X) {
        long s = 0;
        for (int v : trucks) s += Math.max(0L, X - v);
        return s;
    }
    public int[] distributePackages(int[] trucks, int to_distribute) {
        long lo = 0, hi = 0;
        for (int v : trucks) { lo = Math.max(lo, v); hi = Math.max(hi, v); }
        hi += to_distribute;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (capacity(trucks, mid) >= to_distribute) hi = mid;
            else lo = mid + 1;
        }
        long X = lo;
        int[] res = trucks.clone();
        long rem = to_distribute;
        for (int i = 0; i < res.length && rem > 0; i++) {
            long add = Math.min(X - res[i], rem);
            res[i] += add;
            rem -= add;
        }
        return res;
    }
}

