        }
        return res;
    }
};

class Solution {
    public long droneDeliveryRoute(int[] transitionTime, int[] requestedHubs) {
        int m = transitionTime.length;
        long[] pre = new long[m + 1];
        for (int i = 0; i < m; i++) pre[i + 1] = pre[i] + transitionTime[i];
        long total = pre[m];
        int cur = 1;
        long ans = 0;
        for (int nxt : requestedHubs) {
            long fwd = ((pre[nxt - 1] - pre[cur - 1]) % total + total) % total;
            ans += Math.min(fwd, total - fwd);
            cur = nxt;
        }
        return ans;
    }
}

