class Solution {
    public int droppedRequests(int[] requestTime) {
        int n = requestTime.length, dropped = 0;
        for (int i = 0; i < n; i++) {
            int t = requestTime[i];
            int l1 = lowerBound(requestTime, 0, i, t);
            if (i - l1 >= 3) { dropped++; continue; }
            int l10 = lowerBound(requestTime, 0, i, t - 9);
            if (i - l10 >= 20) { dropped++; continue; }
            int l60 = lowerBound(requestTime, 0, i, t - 59);
            if (i - l60 >= 60) { dropped++; continue; }
        }
        return dropped;
    }
    int lowerBound(int[] a, int lo, int hi, int v) {
        while (lo < hi) {
            int m = (lo + hi) >>> 1;
            if (a[m] < v) lo = m + 1; else hi = m;
        }
        return lo;
    }
}

class Solution {
public:
    int droppedRequests(vector<int>& requestTime) {
        int n = requestTime.size(), dropped = 0;
        for (int i = 0; i < n; i++) {
            int t = requestTime[i];
            int l1 = lower_bound(requestTime.begin(), requestTime.begin() + i, t) - requestTime.begin();
            if (i - l1 >= 3) { dropped++; continue; }
            int l10 = lower_bound(requestTime.begin(), requestTime.begin() + i, t - 9) - requestTime.begin();
            if (i - l10 >= 20) { dropped++; continue; }
            int l60 = lower_bound(requestTime.begin(), requestTime.begin() + i, t - 59) - requestTime.begin();
            if (i - l60 >= 60) { dropped++; continue; }
        }
        return dropped;
    }
};

def ensureNonZeroLoadSum(queueMessages):
    seen = {0}
    pre = 0
    inserts = 0
    for v in queueMessages:
        pre += v
        if pre in seen:
            inserts += 1
            seen = {0, pre}
        else:
            seen.add(pre)
    return inserts

class Solution {
    public int ensureNonZeroLoadSum(int[] queueMessages) {
        HashSet<Long> seen = new HashSet<>();
        seen.add(0L);
        long pre = 0;
        int inserts = 0;
        for (int v : queueMessages) {
            pre += v;
            if (seen.contains(pre)) {
                inserts++;
                seen.clear();
                seen.add(0L);
                seen.add(pre);
            } else {
                seen.add(pre);
            }
        }
        return inserts;
    }
}

class Solution {
public:
    int ensureNonZeroLoadSum(vector<int>& queueMessages) {
        unordered_set<long long> seen;
        seen.insert(0);
        long long pre = 0;
        int inserts = 0;
        for (int v : queueMessages) {
            pre += v;
            if (seen.count(pre)) {
                inserts++;
                seen.clear();
                seen.insert(0);
                seen.insert(pre);
            } else {
                seen.insert(pre);
            }
        }
        return inserts;
    }
};

class Solution {
    public int[] equalProducts(String[] inventory_alpha, String[] inventory_beta) {
        int n = inventory_alpha.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            String a = inventory_alpha[i], b = inventory_beta[i];
            if (a.length() != b.length()) continue;
            int[] fa = new int[26], fb = new int[26];
            for (char c : a.toCharArray()) fa[c - 'a']++;
            for (char c : b.toCharArray()) fb[c - 'a']++;
            Arrays.sort(fa);
            Arrays.sort(fb);
            ans[i] = Arrays.equals(fa, fb) ? 1 : 0;
        }
        return ans;
    }
}

class Solution {
public:
    vector<int> equalProducts(vector<string>& a, vector<string>& b) {
        vector<int> ans(a.size(), 0);
        for (size_t i = 0; i < a.size(); i++) {
            if (a[i].size() != b[i].size()) continue;
            vector<int> fa(26, 0), fb(26, 0);
            for (char c : a[i]) fa[c - 'a']++;
            for (char c : b[i]) fb[c - 'a']++;
            sort(fa.begin(), fa.end());
            sort(fb.begin(), fb.end());
            ans[i] = (fa == fb) ? 1 : 0;
        }
        return ans;
    }
};

from collections import defaultdict

def totalExecutionTime(execution):
    groups = defaultdict(list)
    for i, v in enumerate(execution):
        groups[v].append(i)
    cur = list(execution)
    done = [False] * len(execution)
    total = 0
    for i, orig in enumerate(execution):
        total += cur[i]
        done[i] = True
        for j in groups[orig]:
            if not done[j]:
                cur[j] = (cur[j] + 1) // 2
    return total

class Solution {
    public long totalExecutionTime(int[] execution) {
        int n = execution.length;
        HashMap<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) groups.computeIfAbsent(execution[i], k -> new ArrayList<>()).add(i);
        long[] cur = new long[n];
        for (int i = 0; i < n; i++) cur[i] = execution[i];
        boolean[] done = new boolean[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += cur[i];
            done[i] = true;
            for (int j : groups.get(execution[i])) {
                if (!done[j]) cur[j] = (cur[j] + 1) / 2;
            }
        }
        return total;
    }
}

class Solution {
public:
    long long totalExecutionTime(vector<int>& execution) {
        int n = execution.size();
        unordered_map<int, vector<int>> groups;
        for (int i = 0; i < n; i++) groups[execution[i]].push_back(i);
        vector<long long> cur(n);
        for (int i = 0; i < n; i++) cur[i] = execution[i];
        vector<bool> done(n, false);
        long long total = 0;
        for (int i = 0; i < n; i++) {
            total += cur[i];
            done[i] = true;
            for (int j : groups[execution[i]]) {
                if (!done[j]) cur[j] = (cur[j] + 1) / 2;
            }
        }
        return total;
    }
};

def findCapableWinners(power_a, power_b, power_c):
    n = len(power_a)
    sorted_p = [tuple(sorted([power_a[i], power_b[i], power_c[i]])) for i in range(n)]
    ans = 0
    for i in range(n):
        ai, bi, ci = sorted_p[i]
        ok = True
        for j in range(n):
            if i == j:
                continue
            aj, bj, cj = sorted_p[j]
            wins = (ai > aj) + (bi > bj) + (ci > cj)
            if wins < 2:
                ok = False
                break
        if ok:
            ans += 1
    return ans

class Solution {
    public int findCapableWinners(int[] a, int[] b, int[] c) {
        int n = a.length;
        int[][] p = new int[n][3];
        for (int i = 0; i < n; i++) {
            p[i] = new int[]{a[i], b[i], c[i]};
            Arrays.sort(p[i]);
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n && ok; j++) {
                if (i == j) continue;
                int w = (p[i][0] > p[j][0] ? 1 : 0) + (p[i][1] > p[j][1] ? 1 : 0) + (p[i][2] > p[j][2] ? 1 : 0);
                if (w < 2) ok = false;
            }
            if (ok) ans++;
        }
        return ans;
    }
}

