            }
            if (ok) ans++;
        }
        return ans;
    }
};

def findDaysS2SubsequenceOfS1(s1, s2, start, end):
    n, m = len(s1), len(s2)
    for d, (l, r) in enumerate(zip(start, end)):
        j = 0
        for i in range(n):
            if l <= i <= r:
                continue
            if j < m and s1[i] == s2[j]:
                j += 1
        if j < m:
            return d
    return len(start)

class Solution {
    public int findDaysS2SubsequenceOfS1(String s1, String s2, int[] start, int[] end) {
        int n = s1.length(), m = s2.length();
        for (int d = 0; d < start.length; d++) {
            int j = 0;
            for (int i = 0; i < n && j < m; i++) {
                if (i >= start[d] && i <= end[d]) continue;
                if (s1.charAt(i) == s2.charAt(j)) j++;
            }
            if (j < m) return d;
        }
        return start.length;
    }
}

