        int n = s1.size(), m = s2.size();
        for (size_t d = 0; d < start.size(); d++) {
            int j = 0;
            for (int i = 0; i < n && j < m; i++) {
                if (i >= start[d] && i <= end[d]) continue;
                if (s1[i] == s2[j]) j++;
            }
            if (j < m) return (int) d;
        }
        return (int) start.size();
    }
};

class Solution {
    public int[] findDominance(String[] s) {
        int n = s.length, m = s[0].length();
        int[] res = new int[m];
        for (int d = 1; d <= m; d++) {
            HashMap<String, Integer> cnt = new HashMap<>();
            int best = 0;
            for (String str : s) {
                String pre = str.substring(0, d);
                int c = cnt.getOrDefault(pre, 0) + 1;
                cnt.put(pre, c);
                if (c > best) best = c;
            }
            res[d - 1] = best;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> findDominance(vector<string>& s) {
        int n = s.size(), m = s[0].size();
        vector<int> res(m, 0);
        for (int d = 1; d <= m; d++) {
            unordered_map<string, int> cnt;
            int best = 0;
            for (auto& str : s) {
                string pre = str.substr(0, d);
                int c = ++cnt[pre];
                if (c > best) best = c;
            }
            res[d - 1] = best;
        }
        return res;
    }
};

def findEncryptedNumber(digit_numbers):
    arr = list(digit_numbers)
    while len(arr) > 2:
        arr = [(arr[i] + arr[i + 1]) % 10 for i in range(len(arr) - 1)]
    return f"{arr[0]}{arr[1]}"

class Solution {
    public String findEncryptedNumber(int[] digit_numbers) {
        int[] arr = digit_numbers.clone();
        int n = arr.length;
        while (n > 2) {
            for (int i = 0; i < n - 1; i++) arr[i] = (arr[i] + arr[i + 1]) % 10;
            n--;
        }
        return "" + arr[0] + arr[1];
    }
}

