        vector<int> arr = digit_numbers;
        while (arr.size() > 2) {
            for (size_t i = 0; i + 1 < arr.size(); i++) arr[i] = (arr[i] + arr[i + 1]) % 10;
            arr.pop_back();
        }
        return string(1, '0' + arr[0]) + string(1, '0' + arr[1]);
    }
};

def findEncryptedPassword(password):
    cnt = [0] * 26
    for c in password:
        cnt[ord(c) - ord('a')] += 1
    half = []
    mid = ''
    for i in range(26):
        half.append(chr(ord('a') + i) * (cnt[i] // 2))
        if cnt[i] % 2 == 1:
            mid = chr(ord('a') + i)
    left = ''.join(half)
    return left + mid + left[::-1]

class Solution {
    public String findEncryptedPassword(String password) {
        int[] cnt = new int[26];
        for (char c : password.toCharArray()) cnt[c - 'a']++;
        StringBuilder half = new StringBuilder();
        char mid = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < cnt[i] / 2; j++) half.append((char) ('a' + i));
            if (cnt[i] % 2 == 1) mid = (char) ('a' + i);
        }
        StringBuilder res = new StringBuilder(half);
