def findIdealDays(forecast, window):
    n = len(forecast)
    leftRun = [1] * n
    rightRun = [1] * n
    for i in range(1, n):
        if forecast[i - 1] >= forecast[i]:
            leftRun[i] = leftRun[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if forecast[i] <= forecast[i + 1]:
            rightRun[i] = rightRun[i + 1] + 1
    ans = []
    for i in range(n):
        if leftRun[i] >= window + 1 and rightRun[i] >= window + 1:
            ans.append(i + 1)
    return ans

class Solution {
    public int[] findIdealDays(int[] forecast, int window) {
        int n = forecast.length;
        int[] leftRun = new int[n], rightRun = new int[n];
        Arrays.fill(leftRun, 1);
        Arrays.fill(rightRun, 1);
        for (int i = 1; i < n; i++) {
            if (forecast[i - 1] >= forecast[i]) leftRun[i] = leftRun[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if (forecast[i] <= forecast[i + 1]) rightRun[i] = rightRun[i + 1] + 1;
        }
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (leftRun[i] >= window + 1 && rightRun[i] >= window + 1) ans.add(i + 1);
        }
        int[] res = new int[ans.size()];
        for (int i = 0; i < ans.size(); i++) res[i] = ans.get(i);
        return res;
    }
}

