    }
};

class Solution {
    public int[] findIdleSkillsQuery(int numSkills, int[][] requestLogs, int[] queryTime, int timeWindow) {
        int[][] logs = requestLogs.clone();
        Arrays.sort(logs, (a, b) -> a[1] - b[1]);
        int m = logs.length;
        int[] times = new int[m];
        for (int i = 0; i < m; i++) times[i] = logs[i][1];
        int[] ans = new int[queryTime.length];
        for (int qi = 0; qi < queryTime.length; qi++) {
            int q = queryTime[qi];
            int lo = lowerBound(times, q - timeWindow);
            int hi = upperBound(times, q);
            HashSet<Integer> seen = new HashSet<>();
            for (int i = lo; i < hi; i++) seen.add(logs[i][0]);
            ans[qi] = numSkills - seen.size();
        }
        return ans;
    }
    int lowerBound(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] < v) lo = m + 1; else hi = m; }
        return lo;
    }
    int upperBound(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= v) lo = m + 1; else hi = m; }
        return lo;
    }
}

class Solution {
public:
    vector<int> findIdleSkillsQuery(int numSkills, vector<vector<int>>& requestLogs, vector<int>& queryTime, int timeWindow) {
        vector<vector<int>> logs = requestLogs;
        sort(logs.begin(), logs.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        int m = logs.size();
        vector<int> times(m);
        for (int i = 0; i < m; i++) times[i] = logs[i][1];
        vector<int> ans;
        for (int q : queryTime) {
            int lo = lower_bound(times.begin(), times.end(), q - timeWindow) - times.begin();
            int hi = upper_bound(times.begin(), times.end(), q) - times.begin();
            unordered_set<int> seen;
            for (int i = lo; i < hi; i++) seen.insert(logs[i][0]);
            ans.push_back(numSkills - (int) seen.size());
        }
        return ans;
    }
};

def findKLevelPermutation(N, K):
    res = []
    lo, hi = 1, K + 1
    while lo <= hi:
        res.append(lo)
        if lo != hi:
            res.append(hi)
        lo += 1
        hi -= 1
    # append remaining K+2 .. N
    for v in range(K + 2, N + 1):
        res.append(v)
    return res

class Solution {
    public int[] findKLevelPermutation(int N, int K) {
        int[] res = new int[N];
        int idx = 0, lo = 1, hi = K + 1;
        while (lo <= hi) {
            res[idx++] = lo;
            if (lo != hi) res[idx++] = hi;
            lo++; hi--;
        }
        for (int v = K + 2; v <= N; v++) res[idx++] = v;
        return res;
    }
}

class Solution {
public:
    vector<int> findKLevelPermutation(int N, int K) {
        vector<int> res;
        int lo = 1, hi = K + 1;
        while (lo <= hi) {
            res.push_back(lo);
            if (lo != hi) res.push_back(hi);
            lo++; hi--;
        }
        for (int v = K + 2; v <= N; v++) res.push_back(v);
        return res;
    }
};

