def findKthMinimumVulnerability(k, m, vulnerability):
    sl = SortedList()
    ans = []
    for i, v in enumerate(vulnerability):
        sl.add(v)
        if i >= m:
            sl.remove(vulnerability[i - m])
        if i >= m - 1:
            ans.append(sl[k - 1])
    return ans

class Solution {
    public int[] findKthMinimumVulnerability(int k, int m, int[] vulnerability) {
        int n = vulnerability.length;
        TreeMap<Integer, Integer> low = new TreeMap<>(); // top-k smallest, key=val cnt
        TreeMap<Integer, Integer> high = new TreeMap<>();
        int lowSize = 0;
        // helper add/remove via methods
        int[] ans = new int[n - m + 1];
        // simple approach: for each window O(m log m) — adequate for OA
        for (int i = 0; i <= n - m; i++) {
            int[] tmp = Arrays.copyOfRange(vulnerability, i, i + m);
            Arrays.sort(tmp);
            ans[i] = tmp[k - 1];
        }
        return ans;
    }
}

