class Solution {
    public int findLargestSetOfOnionBags(int[] onionBags) {
        HashSet<Long> s = new HashSet<>();
        for (int v : onionBags) s.add((long) v);
        int best = 1;
        for (int v : onionBags) {
            long cur = v;
            int length = 1;
            while (cur * cur <= Long.MAX_VALUE / 2 && s.contains(cur * cur)) {
                cur = cur * cur;
                length++;
            }
            if (length > best) best = length;
        }
        return best >= 2 ? best : -1;
    }
}

