from math import gcd

def findLeastPossibleVulnerability(key, maxChange):
    n = len(key)
    def feasible(X):
        changes = 0
        g, length = 0, 0
        for v in key:
            new_g = gcd(g, v) if length > 0 else v
            if length > 0 and new_g > 1:
                length += 1
                g = new_g
            else:
                length = 1
                g = v
            if length > X:
                changes += 1
                if changes > maxChange:
                    return False
                length = 0
                g = 0
        return True
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    long gcd(long a, long b) { while (b != 0) { long t = a % b; a = b; b = t; } return a; }
    boolean feasible(int[] key, int maxChange, int X) {
        int changes = 0;
        long g = 0; int length = 0;
        for (int v : key) {
            long newG = (length > 0) ? gcd(g, v) : v;
            if (length > 0 && newG > 1) { length++; g = newG; }
            else { length = 1; g = v; }
            if (length > X) {
                changes++;
                if (changes > maxChange) return false;
                length = 0; g = 0;
            }
        }
        return true;
    }
    public int findLeastPossibleVulnerability(int[] key, int maxChange) {
        int lo = 0, hi = key.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feasible(key, maxChange, mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

