def findLongestIsolatedSubstring(inputString):
    n = len(inputString)
    first = {}
    last = {}
    for i, c in enumerate(inputString):
        if c not in first:
            first[c] = i
        last[c] = i
    best = 0
    for l in range(n):
        r = last[inputString[l]]
        i = l
        valid = True
        while i <= r and r < n:
            c = inputString[i]
            if first[c] < l:
                valid = False
                break
            if last[c] > r:
                r = last[c]
            i += 1
        if valid and r - l + 1 < n:
            best = max(best, r - l + 1)
    return best

class Solution {
    public int findLongestIsolatedSubstring(String s) {
        int n = s.length();
        int[] first = new int[26], last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int best = 0;
        for (int l = 0; l < n; l++) {
            int r = last[s.charAt(l) - 'a'];
            int i = l;
            boolean valid = true;
            while (i <= r) {
                int c = s.charAt(i) - 'a';
                if (first[c] < l) { valid = false; break; }
                if (last[c] > r) r = last[c];
                i++;
            }
            if (valid && r - l + 1 < n) best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

