def findLexicographicallySmallestString(s):
    n = len(s)
    L = n
    for i in range(1, n):
        if s[i] == s[i - 1]:
            L = i
            break
    s_list = list(s)
    def try_at(k):
        for c_ord in range(ord(s_list[k]) + 1, ord('z') + 1):
            c = chr(c_ord)
            if k > 0 and c == s_list[k - 1]:
                continue
            T = list(s_list[:k]) + [c]
            prev = c
            for j in range(k + 1, n):
                for nc_ord in range(ord('a'), ord('z') + 1):
                    nc = chr(nc_ord)
                    if nc != prev:
                        T.append(nc)
                        prev = nc
                        break
            return "".join(T)
        return None
    for k in range(L, -1, -1):
        if k >= n:
            continue
        res = try_at(k)
        if res is not None:
            return res
    return "-1"

class Solution {
    public String findLexicographicallySmallestString(String s) {
        int n = s.length();
        char[] arr = s.toCharArray();
        int L = n;
        for (int i = 1; i < n; i++) if (arr[i] == arr[i - 1]) { L = i; break; }
        for (int k = Math.min(L, n - 1); k >= 0; k--) {
            for (char c = (char)(arr[k] + 1); c <= 'z'; c++) {
                if (k > 0 && c == arr[k - 1]) continue;
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < k; j++) sb.append(arr[j]);
                sb.append(c);
                char prev = c;
                for (int j = k + 1; j < n; j++) {
                    for (char nc = 'a'; nc <= 'z'; nc++) {
                        if (nc != prev) { sb.append(nc); prev = nc; break; }
                    }
                }
                return sb.toString();
            }
        }
        return "-1";
    }
}

class Solution {
public:
    string findLexicographicallySmallestString(string s) {
        int n = s.size();
        int L = n;
        for (int i = 1; i < n; i++) if (s[i] == s[i - 1]) { L = i; break; }
        for (int k = min(L, n - 1); k >= 0; k--) {
            for (char c = s[k] + 1; c <= 'z'; c++) {
                if (k > 0 && c == s[k - 1]) continue;
                string res = s.substr(0, k);
                res.push_back(c);
                char prev = c;
                for (int j = k + 1; j < n; j++) {
                    for (char nc = 'a'; nc <= 'z'; nc++) {
                        if (nc != prev) { res.push_back(nc); prev = nc; break; }
                    }
                }
                return res;
            }
        }
        return "-1";
    }
};

class Solution {
    public int findMaxToBalance(String s, String kitParentheses, int[] efficiencyRatings) {
        List<Integer> opens = new ArrayList<>(), closes = new ArrayList<>();
        for (int i = 0; i < kitParentheses.length(); i++) {
            if (kitParentheses.charAt(i) == '(') opens.add(efficiencyRatings[i]);
            else closes.add(efficiencyRatings[i]);
        }
        opens.sort(Collections.reverseOrder());
        closes.sort(Collections.reverseOrder());
        long[] pO = new long[opens.size() + 1];
        for (int i = 0; i < opens.size(); i++) pO[i + 1] = pO[i] + opens.get(i);
        long[] pC = new long[closes.size() + 1];
        for (int i = 0; i < closes.size(); i++) pC[i + 1] = pC[i] + closes.get(i);
        int Os = 0, Cs = 0;
        for (char c : s.toCharArray()) if (c == '(') Os++; else Cs++;
        int target = Cs - Os;
        long best = 0;
        int jMin = Math.max(0, target);
        for (int j = jMin; j <= opens.size(); j++) {
            int k = j - target;
            if (k < 0 || k > closes.size()) continue;
            best = Math.max(best, pO[j] + pC[k]);
        }
        return (int) best;
    }
}

class Solution {
public:
