        vector<int> opens, closes;
        for (size_t i = 0; i < kitParentheses.size(); i++) {
            if (kitParentheses[i] == '(') opens.push_back(efficiencyRatings[i]);
            else closes.push_back(efficiencyRatings[i]);
        }
        sort(opens.begin(), opens.end(), greater<int>());
        sort(closes.begin(), closes.end(), greater<int>());
        vector<long long> pO(opens.size() + 1, 0), pC(closes.size() + 1, 0);
        for (size_t i = 0; i < opens.size(); i++) pO[i + 1] = pO[i] + opens[i];
        for (size_t i = 0; i < closes.size(); i++) pC[i + 1] = pC[i] + closes[i];
        int Os = 0, Cs = 0;
        for (char c : s) if (c == '(') Os++; else Cs++;
        int target = Cs - Os;
        long long best = 0;
        int jMin = max(0, target);
        for (int j = jMin; j <= (int) opens.size(); j++) {
            int k = j - target;
            if (k < 0 || k > (int) closes.size()) continue;
            best = max(best, pO[j] + pC[k]);
        }
        return (int) best;
    }
};

class Solution {
    public long findMaximumCalories(int[] height) {
        int[] h = height.clone();
        Arrays.sort(h);
        int n = h.length;
        int[] order = new int[n];
        int idx = 0, lo = 0, hi = n - 1;
        boolean takeHigh = true;
        while (lo <= hi) {
            order[idx++] = takeHigh ? h[hi--] : h[lo++];
            takeHigh = !takeHigh;
        }
        long total = 0;
        long prev = 0;
        for (int x : order) {
            long d = x - prev;
            total += d * d;
            prev = x;
        }
        return total;
    }
}

