def findMaximumMoney(k, segment):
    MOD = 10**9 + 7
    candidates = set()
    for l, r, _ in segment:
        candidates.add(l)
        candidates.add(max(1, r - k + 1))
    best = 0
    for s in candidates:
        e = s + k - 1
        total = 0
        for l, r, v in segment:
            lo = max(l, s)
            hi = min(r, e)
            if lo <= hi:
                total += (hi - lo + 1) * v
        if total > best:
            best = total
    return best % MOD

class Solution {
    public int findMaximumMoney(int k, int[][] segment) {
        final long MOD = 1_000_000_007L;
        HashSet<Long> candidates = new HashSet<>();
        for (int[] s : segment) {
            candidates.add((long) s[0]);
            candidates.add((long) Math.max(1, s[1] - k + 1));
        }
        long best = 0;
        for (long s : candidates) {
            long e = s + k - 1;
            long total = 0;
            for (int[] sg : segment) {
                long lo = Math.max(sg[0], s);
                long hi = Math.min(sg[1], e);
                if (lo <= hi) total += (hi - lo + 1) * (long) sg[2];
            }
            if (total > best) best = total;
        }
        return (int) (best % MOD);
    }
}

