    }
};

def findMaximumNum(answered, needed, q):
    gaps = sorted(max(0, n - a) for a, n in zip(answered, needed))
    cnt = 0
    for g in gaps:
        if q >= g:
            q -= g
            cnt += 1
        else:
            break
    return cnt

class Solution {
    public int findMaximumNum(int[] answered, int[] needed, int q) {
        int n = answered.length;
        long[] gaps = new long[n];
        for (int i = 0; i < n; i++) gaps[i] = Math.max(0, (long) needed[i] - answered[i]);
        Arrays.sort(gaps);
        long budget = q;
        int cnt = 0;
        for (long g : gaps) {
            if (budget >= g) { budget -= g; cnt++; }
            else break;
        }
        return cnt;
    }
}

class Solution {
public:
    int findMaximumNum(vector<int>& answered, vector<int>& needed, int q) {
        int n = answered.size();
        vector<long long> gaps(n);
        for (int i = 0; i < n; i++) gaps[i] = max(0LL, (long long) needed[i] - answered[i]);
        sort(gaps.begin(), gaps.end());
        long long budget = q;
        int cnt = 0;
        for (long long g : gaps) {
            if (budget >= g) { budget -= g; cnt++; }
            else break;
        }
        return cnt;
    }
};

def findMaximumNumberOfBalancedCombinations(arr):
    stk = []  # decreasing stack of indices
    total = 0
    for r, v in enumerate(arr):
        while stk and arr[stk[-1]] <= v:
            stk.pop()
        if stk:
            total += stk[-1] + 1
        stk.append(r)
    return total

class Solution {
    public long findMaximumNumberOfBalancedCombinations(int[] arr) {
        Deque<Integer> stk = new ArrayDeque<>();
        long total = 0;
        for (int r = 0; r < arr.length; r++) {
            while (!stk.isEmpty() && arr[stk.peek()] <= arr[r]) stk.pop();
            if (!stk.isEmpty()) total += stk.peek() + 1;
            stk.push(r);
        }
        return total;
    }
}

class Solution {
public:
    long long findMaximumNumberOfBalancedCombinations(vector<int>& arr) {
        vector<int> stk;
        long long total = 0;
        for (int r = 0; r < (int) arr.size(); r++) {
            while (!stk.empty() && arr[stk.back()] <= arr[r]) stk.pop_back();
            if (!stk.empty()) total += stk.back() + 1;
            stk.push_back(r);
        }
        return total;
    }
};

import heapq

def findMaximumNumberOfBatches(products):
    heap = [-p for p in products]
    heapq.heapify(heap)
    batch = 0
    i = 1
    while len(heap) >= i:
        picked = []
        for _ in range(i):
            picked.append(-heapq.heappop(heap))
        batch += 1
        for v in picked:
            if v - 1 > 0:
                heapq.heappush(heap, -(v - 1))
        i += 1
    return batch

class Solution {
    public int findMaximumNumberOfBatches(int[] products) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int p : products) heap.add(p);
        int batch = 0, i = 1;
        while (heap.size() >= i) {
            int[] picked = new int[i];
            for (int j = 0; j < i; j++) picked[j] = heap.poll();
            batch++;
            for (int v : picked) if (v - 1 > 0) heap.add(v - 1);
            i++;
        }
        return batch;
    }
}

class Solution {
public:
    int findMaximumNumberOfBatches(vector<int>& products) {
        priority_queue<int> heap(products.begin(), products.end());
        int batch = 0, i = 1;
        while ((int) heap.size() >= i) {
            vector<int> picked;
            for (int j = 0; j < i; j++) { picked.push_back(heap.top()); heap.pop(); }
            batch++;
            for (int v : picked) if (v - 1 > 0) heap.push(v - 1);
            i++;
        }
        return batch;
    }
};

def findMaximumPairs(frontend, backend):
    f = sorted(frontend)
    b = sorted(backend)
    i = j = pairs = 0
    while i < len(f) and j < len(b):
        if f[i] > b[j]:
            pairs += 1
            i += 1
            j += 1
        else:
            i += 1
    return pairs

class Solution {
    public int findMaximumPairs(int[] frontend, int[] backend) {
        int[] f = frontend.clone(), b = backend.clone();
        Arrays.sort(f);
        Arrays.sort(b);
        int i = 0, j = 0, pairs = 0;
        while (i < f.length && j < b.length) {
            if (f[i] > b[j]) { pairs++; i++; j++; }
            else i++;
        }
        return pairs;
    }
}

class Solution {
public:
    int findMaximumPairs(vector<int>& frontend, vector<int>& backend) {
        vector<int> f = frontend, b = backend;
        sort(f.begin(), f.end());
        sort(b.begin(), b.end());
        int i = 0, j = 0, pairs = 0;
        while (i < (int) f.size() && j < (int) b.size()) {
            if (f[i] > b[j]) { pairs++; i++; j++; }
            else i++;
        }
        return pairs;
    }
};

class Solution {
    public long findMaximumScore(String data) {
        int n = data.length();
        char[] s = data.toCharArray();
        int[] leftLen = new int[n], rightLen = new int[n];
        Arrays.fill(leftLen, 1);
        Arrays.fill(rightLen, 1);
        for (int i = 1; i < n; i++) if (Math.abs(s[i] - s[i - 1]) <= 1) leftLen[i] = leftLen[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (Math.abs(s[i + 1] - s[i]) <= 1) rightLen[i] = rightLen[i + 1] + 1;
        long base = 0;
        int i = 0;
        while (i < n) { int L = rightLen[i]; base += (long) L * (L + 1) / 2; i += L; }
        long best = base;
        for (int p = 0; p < n; p++) {
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == s[p]) continue;
                int leftPart = 1;
                if (p > 0 && Math.abs(s[p - 1] - c) <= 1) leftPart = 1 + leftLen[p - 1];
                int rightPart = 0;
                if (p < n - 1 && Math.abs(c - s[p + 1]) <= 1) rightPart = rightLen[p + 1];
                long removed = 0;
                int affL = p, affR = p;
                if (p > 0) affL = (p - 1) - leftLen[p - 1] + 1;
                if (p < n - 1) affR = (p + 1) + rightLen[p + 1] - 1;
                int i2 = affL;
                while (i2 <= affR) {
                    int L = rightLen[i2];
                    removed += (long) L * (L + 1) / 2;
                    i2 += L;
                }
                long newRunLen = leftPart + rightPart;
                long added = newRunLen * (newRunLen + 1) / 2;
                if (p > 0 && leftPart == 1) added += (long) leftLen[p - 1] * (leftLen[p - 1] + 1) / 2;
                if (p < n - 1 && rightPart == 0) added += (long) rightLen[p + 1] * (rightLen[p + 1] + 1) / 2;
                long newScore = base - removed + added;
                if (newScore > best) best = newScore;
            }
        }
        return best;
    }
}

