def maxTotalAmount(segment, k):
    MOD = 10**9 + 7
    candidates = set()
    for l, r, _ in segment:
        candidates.add(l)
        candidates.add(max(1, r - k + 1))
    best = 0
    for s in candidates:
        e = s + k - 1
        total = 0
        for l, r, v in segment:
            lo = max(l, s)
            hi = min(r, e)
            if lo <= hi:
                total += (hi - lo + 1) * v
        if total > best:
            best = total
    return best % MOD

