class Solution {
    boolean feasible(int[] a, int X, int target) {
        int curLen = 1, bestLen = 1;
        for (int i = 1; i < a.length; i++) {
            if (a[i] - a[i - 1] <= X) curLen++; else curLen = 1;
            if (curLen > bestLen) bestLen = curLen;
        }
        return bestLen >= target;
    }
    public int findMinMaxDifference(int[] arr, int k) {
        int[] a = arr.clone();
        Arrays.sort(a);
        int n = a.length, target = n - k;
        int lo = 0, hi = a[n - 1] - a[0];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feasible(a, mid, target)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

