from collections import Counter

def findMinTrips(packageweight):
    cnt = Counter(packageweight)
    total = 0
    for c in cnt.values():
        if c == 1:
            return -1
        if c % 3 == 0:
            total += c // 3
        else:
            total += c // 3 + 1
    return total

class Solution {
    public int findMinTrips(int[] packageweight) {
        HashMap<Integer, Integer> cnt = new HashMap<>();
        for (int w : packageweight) cnt.merge(w, 1, Integer::sum);
        int total = 0;
        for (int c : cnt.values()) {
            if (c == 1) return -1;
            total += (c % 3 == 0) ? c / 3 : c / 3 + 1;
        }
        return total;
    }
}

class Solution {
public:
    int findMinTrips(vector<int>& packageweight) {
        unordered_map<int, int> cnt;
        for (int w : packageweight) cnt[w]++;
        int total = 0;
        for (auto& p : cnt) {
            int c = p.second;
            if (c == 1) return -1;
            total += (c % 3 == 0) ? c / 3 : c / 3 + 1;
        }
        return total;
    }
};

def findMinimumCost(products):
    n = len(products)
    avg = sum(products) // n
    def cost(arr):
        cum = 0
        mn = 0
        total = 0
        cums = []
        for v in arr:
            cum += v - avg
            cums.append(cum)
            if cum < mn:
                mn = cum
        return sum(cums) - n * mn
    return min(cost(products), cost(products[::-1]))

class Solution {
    long cost(int[] arr, long avg) {
        long cum = 0, mn = 0, totalCum = 0;
        for (int v : arr) {
            cum += v - avg;
            totalCum += cum;
            if (cum < mn) mn = cum;
        }
        return totalCum - (long) arr.length * mn;
    }
    public long findMinimumCost(int[] products) {
        long sum = 0;
        for (int v : products) sum += v;
        long avg = sum / products.length;
        int[] rev = new int[products.length];
        for (int i = 0; i < products.length; i++) rev[i] = products[products.length - 1 - i];
        return Math.min(cost(products, avg), cost(rev, avg));
    }
}

class Solution {
public:
    long long cost(vector<int>& arr, long long avg) {
        long long cum = 0, mn = 0, totalCum = 0;
        for (int v : arr) {
            cum += v - avg;
            totalCum += cum;
            if (cum < mn) mn = cum;
        }
        return totalCum - (long long) arr.size() * mn;
    }
    long long findMinimumCost(vector<int>& products) {
        long long sum = 0;
        for (int v : products) sum += v;
        long long avg = sum / products.size();
        vector<int> rev(products.rbegin(), products.rend());
        return min(cost(products, avg), cost(rev, avg));
    }
};

def findMinimumDays(pages, k, p):
    n = len(pages)
    need = [(v + p - 1) // p for v in pages]
    def feasible(D):
        used = 0
        cur = 0
        diff = [0] * (n + k + 1)
        for i in range(n):
            cur += diff[i]
            if cur < need[i]:
                add = need[i] - cur
                used += add
                if used > D:
                    return False
                cur += add
                diff[min(i + k, n + k)] -= add
        return used <= D
    lo, hi = 0, 0
    for v in need:
        if v > hi:
            hi = v
    hi = max(hi, sum(need))
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    long[] need;
    int n, k;
    boolean feasible(long D) {
        long used = 0;
        long cur = 0;
        long[] diff = new long[n + k + 1];
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur < need[i]) {
                long add = need[i] - cur;
                used += add;
                if (used > D) return false;
                cur += add;
                int idx = Math.min(i + k, n + k);
                diff[idx] -= add;
            }
        }
        return true;
    }
    public long findMinimumDays(int[] pages, int k, int p) {
        n = pages.length; this.k = k;
        need = new long[n];
        long total = 0, mx = 0;
        for (int i = 0; i < n; i++) {
            need[i] = (pages[i] + p - 1) / p;
            total += need[i];
            mx = Math.max(mx, need[i]);
        }
        long lo = mx, hi = total;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

class Solution {
public:
    vector<long long> need;
    int n, k;
    bool feasible(long long D) {
        long long used = 0, cur = 0;
        vector<long long> diff(n + k + 1, 0);
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur < need[i]) {
                long long add = need[i] - cur;
                used += add;
                if (used > D) return false;
                cur += add;
                int idx = min(i + k, n + k);
                diff[idx] -= add;
            }
        }
        return true;
    }
