    }
};

def findMinimumDist(center, destination):
    a = sorted(center)
    b = sorted(destination)
    return sum(abs(x - y) for x, y in zip(a, b))

class Solution {
    public long findMinimumDist(int[] center, int[] destination) {
        int[] a = center.clone(), b = destination.clone();
        Arrays.sort(a); Arrays.sort(b);
        long total = 0;
        for (int i = 0; i < a.length; i++) total += Math.abs((long) a[i] - b[i]);
        return total;
    }
}

class Solution {
public:
    long long findMinimumDist(vector<int>& center, vector<int>& destination) {
        vector<int> a = center, b = destination;
        sort(a.begin(), a.end()); sort(b.begin(), b.end());
        long long total = 0;
        for (size_t i = 0; i < a.size(); i++) total += abs((long long) a[i] - b[i]);
        return total;
    }
};

def findMinimumMachinesSize(machineCapacity):
    n = len(machineCapacity)
    if n <= 2:
        return n
    count = 2  # endpoints
    prev_sign = 0
    for i in range(1, n):
        d = machineCapacity[i] - machineCapacity[i - 1]
        if d == 0:
            continue
        sign = 1 if d > 0 else -1
        if prev_sign != 0 and sign != prev_sign:
            count += 1
        prev_sign = sign
    return count

class Solution {
    public int findMinimumMachinesSize(int[] mc) {
        int n = mc.length;
        if (n <= 2) return n;
        int count = 2, prev = 0;
        for (int i = 1; i < n; i++) {
            int d = mc[i] - mc[i - 1];
            if (d == 0) continue;
            int sign = (d > 0) ? 1 : -1;
            if (prev != 0 && sign != prev) count++;
            prev = sign;
        }
        return count;
    }
}

