public:
    int findMinimumMachinesSize(vector<int>& mc) {
        int n = mc.size();
        if (n <= 2) return n;
        int count = 2, prev = 0;
        for (int i = 1; i < n; i++) {
            int d = mc[i] - mc[i - 1];
            if (d == 0) continue;
            int sign = (d > 0) ? 1 : -1;
            if (prev != 0 && sign != prev) count++;
            prev = sign;
        }
        return count;
    }
};

from collections import defaultdict

def findMinimumPossibleVariance(height):
    groups = defaultdict(list)
    for i, v in enumerate(height):
        groups[v].append(i)
    best = float('inf')
    for v, positions in groups.items():
        if len(positions) < 2:
            continue
        # val[i] = positions[i] - i (1-based)
        mn = positions[0] - 1
        for i in range(1, len(positions)):
            cur = positions[i] - (i + 1)
            # wait indexing: we want positions[a] - a (1-based a)
            # Let's use 0-based: positions[i] - i.
            pass
        # rewrite cleanly:
        mn = positions[0] - 0
        for i in range(1, len(positions)):
            cur = positions[i] - i
            diff = cur - mn
            if diff < best:
                best = diff
            if cur < mn:
                mn = cur
    return best if best != float('inf') else 0

class Solution {
    public long findMinimumPossibleVariance(int[] height) {
        HashMap<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < height.length; i++) {
            groups.computeIfAbsent(height[i], k -> new ArrayList<>()).add(i);
        }
        long best = Long.MAX_VALUE;
        for (List<Integer> positions : groups.values()) {
            if (positions.size() < 2) continue;
            long mn = positions.get(0);
            for (int i = 1; i < positions.size(); i++) {
                long cur = positions.get(i) - i;
                long diff = cur - mn;
                if (diff < best) best = diff;
                if (cur < mn) mn = cur;
            }
        }
        return best == Long.MAX_VALUE ? 0 : best;
    }
}

class Solution {
public:
    long long findMinimumPossibleVariance(vector<int>& height) {
        unordered_map<int, vector<int>> groups;
        for (int i = 0; i < (int) height.size(); i++) groups[height[i]].push_back(i);
        long long best = LLONG_MAX;
        for (auto& p : groups) {
