    }
};

from collections import Counter

def findMinimumTimeRequired(requests, minGap):
    cnt = Counter(requests)
    f = max(cnt.values())
    t = sum(1 for v in cnt.values() if v == f)
    return max(len(requests), (f - 1) * (minGap + 1) + t)

class Solution {
