def findMinimumTimeToBeauty(n, m, k, paint):
    total = len(paint)
    def feasible(t):
        grid = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(t):
            r, c = paint[i]
            grid[r][c] = 1
        # 2D prefix sum
        pre = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + grid[i][j]
        target = k * k
        for i in range(k, n + 1):
            for j in range(k, m + 1):
                s = pre[i][j] - pre[i - k][j] - pre[i][j - k] + pre[i - k][j - k]
                if s == target:
                    return True
        return False
    lo, hi = k * k, total
    if not feasible(hi):
        return -1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
