        int[][] pre = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                pre[i][j] = pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1] + grid[i][j];
        int target = k * k;
        for (int i = k; i <= n; i++)
            for (int j = k; j <= m; j++) {
                int s = pre[i][j] - pre[i - k][j] - pre[i][j - k] + pre[i - k][j - k];
                if (s == target) return true;
            }
        return false;
    }
    public int findMinimumTimeToBeauty(int n, int m, int k, int[][] paint) {
        this.n = n; this.m = m; this.k = k; this.paint = paint;
