def findMinimumTime(n, k, position):
    a = sorted(position)
    best = float('inf')
    for i in range(len(a) - k + 1):
        L = a[i]
        R = a[i + k - 1]
        if L >= 0:
            t = R
        elif R <= 0:
            t = -L
        else:
            t = min(2 * (-L) + R, 2 * R + (-L))
        if t < best:
            best = t
    return best

class Solution {
    public long findMinimumTime(int n, int k, int[] position) {
        int[] a = position.clone();
        Arrays.sort(a);
        long best = Long.MAX_VALUE;
        for (int i = 0; i + k - 1 < a.length; i++) {
            long L = a[i], R = a[i + k - 1];
            long t;
            if (L >= 0) t = R;
            else if (R <= 0) t = -L;
            else t = Math.min(2 * (-L) + R, 2 * R + (-L));
            if (t < best) best = t;
        }
        return best;
    }
}

