class Solution {
    public long[] findNetworkCalls(int[] feedback, int[] targetCounts) {
        int n = feedback.length;
        int[] a = feedback.clone();
        Arrays.sort(a);
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        long total = pre[n];
        long[] ans = new long[targetCounts.length];
        for (int q = 0; q < targetCounts.length; q++) {
            int T = targetCounts[q];
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (a[mid] <= T) lo = mid + 1; else hi = mid;
            }
            int c = lo;
            long S = pre[c];
            ans[q] = (long) c * T - S + (total - S) - (long) (n - c) * T;
        }
        return ans;
    }
}

class Solution {
public:
    vector<long long> findNetworkCalls(vector<int>& feedback, vector<int>& targetCounts) {
        int n = feedback.size();
        vector<int> a = feedback;
        sort(a.begin(), a.end());
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        long long total = pre[n];
        vector<long long> ans;
        for (int T : targetCounts) {
            int c = upper_bound(a.begin(), a.end(), T) - a.begin();
            long long S = pre[c];
            ans.push_back((long long) c * T - S + (total - S) - (long long)(n - c) * T);
        }
        return ans;
    }
};

from collections import Counter

def findNumberOfCompatibleSubstrings(history, products):
    if not products:
        return 0
    L = len(products[0])
    K = len(products)
    target = Counter(products)
    win = L * K
    n = len(history)
    ans = 0
    for r in range(L):
        chunks = []
        i = r
        while i + L <= n:
            chunks.append(history[i:i + L])
            i += L
        if len(chunks) < K:
            continue
        cnt = Counter()
        matched = 0
        for j in range(K):
            ch = chunks[j]
            cnt[ch] += 1
            if cnt[ch] == target[ch]:
                matched += 1
            elif cnt[ch] == target[ch] + 1:
                matched -= 1
        if matched == len(target):
            ans += 1
        for j in range(K, len(chunks)):
            new_ch = chunks[j]
            old_ch = chunks[j - K]
            cnt[new_ch] += 1
            if cnt[new_ch] == target[new_ch]:
                matched += 1
            elif cnt[new_ch] == target[new_ch] + 1:
                matched -= 1
            cnt[old_ch] -= 1
            if cnt[old_ch] == target[old_ch]:
                matched += 1
            elif cnt[old_ch] == target[old_ch] - 1:
                matched -= 1
            if matched == len(target):
                ans += 1
    return ans

class Solution {
    public int findNumberOfCompatibleSubstrings(String history, String[] products) {
        if (products.length == 0) return 0;
        int L = products[0].length(), K = products.length;
        HashMap<String, Integer> target = new HashMap<>();
        for (String p : products) target.merge(p, 1, Integer::sum);
        int targetSize = target.size();
        int n = history.length();
        int ans = 0;
        for (int r = 0; r < L; r++) {
            List<String> chunks = new ArrayList<>();
            for (int i = r; i + L <= n; i += L) chunks.add(history.substring(i, i + L));
            if (chunks.size() < K) continue;
            HashMap<String, Integer> cnt = new HashMap<>();
            int matched = 0;
            for (int j = 0; j < K; j++) {
                String ch = chunks.get(j);
                int newCnt = cnt.merge(ch, 1, Integer::sum);
                int tCnt = target.getOrDefault(ch, 0);
                if (newCnt == tCnt) matched++;
                else if (newCnt == tCnt + 1) matched--;
            }
            if (matched == targetSize) ans++;
            for (int j = K; j < chunks.size(); j++) {
                String add = chunks.get(j), rm = chunks.get(j - K);
                int addNew = cnt.merge(add, 1, Integer::sum);
                int tAdd = target.getOrDefault(add, 0);
                if (addNew == tAdd) matched++;
                else if (addNew == tAdd + 1) matched--;
                int rmNew = cnt.merge(rm, -1, Integer::sum);
                int tRm = target.getOrDefault(rm, 0);
                if (rmNew == tRm) matched++;
                else if (rmNew == tRm - 1) matched--;
                if (matched == targetSize) ans++;
            }
        }
        return ans;
    }
}

class Solution {
public:
    int findNumberOfCompatibleSubstrings(string history, vector<string>& products) {
        if (products.empty()) return 0;
        int L = products[0].size(), K = products.size();
        unordered_map<string, int> target;
        for (auto& p : products) target[p]++;
        int targetSize = target.size();
        int n = history.size(), ans = 0;
        for (int r = 0; r < L; r++) {
            vector<string> chunks;
            for (int i = r; i + L <= n; i += L) chunks.push_back(history.substr(i, L));
            if ((int) chunks.size() < K) continue;
            unordered_map<string, int> cnt;
            int matched = 0;
            for (int j = 0; j < K; j++) {
                int& c = cnt[chunks[j]];
                c++;
                int t = target.count(chunks[j]) ? target[chunks[j]] : 0;
                if (c == t) matched++;
                else if (c == t + 1) matched--;
            }
            if (matched == targetSize) ans++;
            for (int j = K; j < (int) chunks.size(); j++) {
                auto& add = chunks[j];
                auto& rm = chunks[j - K];
                int& ca = cnt[add]; ca++;
                int ta = target.count(add) ? target[add] : 0;
                if (ca == ta) matched++;
                else if (ca == ta + 1) matched--;
                int& cr = cnt[rm]; cr--;
                int tr = target.count(rm) ? target[rm] : 0;
                if (cr == tr) matched++;
                else if (cr == tr - 1) matched--;
                if (matched == targetSize) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public long findNumberOfPossibleUniqueStrings(String s) {
        StringBuilder sb = new StringBuilder("#");
        for (char c : s.toCharArray()) { sb.append(c).append('#'); }
        String t = sb.toString();
        int n = t.length();
        int[] p = new int[n];
        int c = 0, r = 0;
        for (int i = 0; i < n; i++) {
            int mirror = 2 * c - i;
            if (i < r) p[i] = Math.min(r - i, p[mirror]);
            while (i + p[i] + 1 < n && i - p[i] - 1 >= 0 && t.charAt(i + p[i] + 1) == t.charAt(i - p[i] - 1)) p[i]++;
            if (i + p[i] > r) { c = i; r = i + p[i]; }
        }
        long palindromes = 0;
        for (int v : p) palindromes += (v + 1) / 2;
        long n2 = s.length();
        return n2 * (n2 + 1) / 2 - palindromes + 1;
    }
}

