    }
};

class Solution {
    public long numberOfWaysToGroupParcels(int[] weight, int wt) {
        final long MOD = 1_000_000_007L;
        int n = weight.length;
        if (n % 2 != 0) return 0;
        HashMap<Integer, Integer> cnt = new HashMap<>();
        for (int w : weight) cnt.merge(w, 1, Integer::sum);
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        long[] invFact = new long[n + 1];
        invFact[n] = modpow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        long ans = 1;
        if (wt == 0) {
            for (int c : cnt.values()) {
                if (c % 2 != 0) return 0;
                int k = c / 2;
                long ways = fact[c] * invFact[k] % MOD * modpow(modpow(2, k, MOD), MOD - 2, MOD) % MOD;
                ans = ans * ways % MOD;
            }
            return ans;
        }
        TreeSet<Integer> visited = new TreeSet<>();
        TreeSet<Integer> sortedKeys = new TreeSet<>(cnt.keySet());
        for (int v : sortedKeys) {
            if (visited.contains(v)) continue;
            if (cnt.containsKey(v - wt)) continue;
            int pending = 0;
            int cur = v;
            while (cnt.containsKey(cur)) {
                visited.add(cur);
                int c = cnt.get(cur);
                if (c < pending) return 0;
                ans = ans * fact[c] % MOD * invFact[c - pending] % MOD;
                pending = c - pending;
                cur += wt;
            }
            if (pending != 0) return 0;
        }
        return ans;
    }
    long modpow(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
}

class Solution {
public:
    long long modpow(long long b, long long e, long long m) {
        long long r = 1; b %= m;
        while (e > 0) { if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    long long numberOfWaysToGroupParcels(vector<int>& weight, int wt) {
        const long long MOD = 1'000'000'007LL;
        int n = weight.size();
        if (n % 2 != 0) return 0;
        unordered_map<int, int> cnt;
        for (int w : weight) cnt[w]++;
        vector<long long> fact(n + 1, 1), invFact(n + 1, 1);
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modpow(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        long long ans = 1;
        if (wt == 0) {
            for (auto& p : cnt) {
                int c = p.second;
                if (c % 2 != 0) return 0;
                int k = c / 2;
                long long ways = fact[c] * invFact[k] % MOD * modpow(modpow(2, k, MOD), MOD - 2, MOD) % MOD;
                ans = ans * ways % MOD;
            }
            return ans;
        }
        set<int> visited;
        set<int> keys;
        for (auto& p : cnt) keys.insert(p.first);
        for (int v : keys) {
            if (visited.count(v)) continue;
            if (cnt.count(v - wt)) continue;
            int pending = 0, cur = v;
            while (cnt.count(cur)) {
                visited.insert(cur);
                int c = cnt[cur];
                if (c < pending) return 0;
                ans = ans * fact[c] % MOD * invFact[c - pending] % MOD;
                pending = c - pending;
                cur += wt;
            }
            if (pending != 0) return 0;
        }
        return ans;
    }
};

def findNumber(numbers):
    arr = list(numbers)
    while len(arr) > 2:
        arr = [(arr[i] + arr[i + 1]) % 10 for i in range(len(arr) - 1)]
    return f"{arr[0]}{arr[1]}"

class Solution {
    public String findNumber(int[] numbers) {
        int[] arr = numbers.clone();
        int n = arr.length;
        while (n > 2) {
            for (int i = 0; i < n - 1; i++) arr[i] = (arr[i] + arr[i + 1]) % 10;
            n--;
        }
        return "" + arr[0] + arr[1];
    }
}

