def findObfuscateMessage(message):
    s = list(message)
    n = len(s)
    # suffix_min[i] = min char in s[i..n-1]
    suffix_min = ['z'] * (n + 1)
    suffix_min_pos = [n] * (n + 1)
    for i in range(n - 1, -1, -1):
        if s[i] <= suffix_min[i + 1]:
            suffix_min[i] = s[i]
            suffix_min_pos[i] = i
        else:
            suffix_min[i] = suffix_min[i + 1]
            suffix_min_pos[i] = suffix_min_pos[i + 1]
    for l in range(n - 1):
        if suffix_min[l + 1] < s[l]:
            r = suffix_min_pos[l + 1]
            # rotate s[l..r] right by 1
            rotated = [s[r]] + s[l:r]
            return ''.join(s[:l]) + ''.join(rotated) + ''.join(s[r + 1:])
    return ''.join(s)

class Solution {
    public String findObfuscateMessage(String message) {
        char[] s = message.toCharArray();
        int n = s.length;
        char[] sufMin = new char[n + 1];
        int[] sufMinPos = new int[n + 1];
        sufMin[n] = 'z' + 1;
        sufMinPos[n] = n;
        for (int i = n - 1; i >= 0; i--) {
            if (s[i] <= sufMin[i + 1]) { sufMin[i] = s[i]; sufMinPos[i] = i; }
            else { sufMin[i] = sufMin[i + 1]; sufMinPos[i] = sufMinPos[i + 1]; }
        }
        for (int l = 0; l < n - 1; l++) {
            if (sufMin[l + 1] < s[l]) {
                int r = sufMinPos[l + 1];
                StringBuilder res = new StringBuilder();
                for (int i = 0; i < l; i++) res.append(s[i]);
                res.append(s[r]);
                for (int i = l; i < r; i++) res.append(s[i]);
                for (int i = r + 1; i < n; i++) res.append(s[i]);
                return res.toString();
            }
        }
        return message;
    }
}

class Solution {
public:
    string findObfuscateMessage(string message) {
        int n = message.size();
        vector<char> sufMin(n + 1, 'z' + 1);
        vector<int> sufMinPos(n + 1, n);
        for (int i = n - 1; i >= 0; i--) {
            if (message[i] <= sufMin[i + 1]) { sufMin[i] = message[i]; sufMinPos[i] = i; }
            else { sufMin[i] = sufMin[i + 1]; sufMinPos[i] = sufMinPos[i + 1]; }
        }
        for (int l = 0; l < n - 1; l++) {
            if (sufMin[l + 1] < message[l]) {
                int r = sufMinPos[l + 1];
                string res = message.substr(0, l);
                res.push_back(message[r]);
                res += message.substr(l, r - l);
                res += message.substr(r + 1);
                return res;
            }
        }
        return message;
    }
};

def findOptimalLevel(stockArr, incVal, decVal):
    def feasible(M):
        deficit = sum(max(0, M - v) for v in stockArr)
        surplus = sum(max(0, v - M) for v in stockArr)
        if deficit == 0:
            return True
        ops = (deficit + incVal - 1) // incVal
        return ops * decVal <= surplus
    lo, hi = 1, max(stockArr)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

class Solution {
    boolean feasible(int[] stockArr, long M, long incVal, long decVal) {
        long deficit = 0, surplus = 0;
        for (int v : stockArr) {
            if (v < M) deficit += M - v;
            else surplus += v - M;
        }
        if (deficit == 0) return true;
        long ops = (deficit + incVal - 1) / incVal;
        return ops * decVal <= surplus;
    }
    public int findOptimalLevel(int[] stockArr, int incVal, int decVal) {
        long lo = 1, hi = 0;
        for (int v : stockArr) hi = Math.max(hi, v);
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (feasible(stockArr, mid, incVal, decVal)) lo = mid;
            else hi = mid - 1;
        }
        return (int) lo;
    }
}

class Solution {
public:
    bool feasible(vector<int>& stockArr, long long M, long long incVal, long long decVal) {
        long long deficit = 0, surplus = 0;
        for (int v : stockArr) {
            if (v < M) deficit += M - v;
            else surplus += v - M;
        }
        if (deficit == 0) return true;
        long long ops = (deficit + incVal - 1) / incVal;
        return ops * decVal <= surplus;
    }
    int findOptimalLevel(vector<int>& stockArr, int incVal, int decVal) {
        long long lo = 1, hi = 0;
        for (int v : stockArr) hi = max(hi, (long long) v);
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (feasible(stockArr, mid, incVal, decVal)) lo = mid;
            else hi = mid - 1;
        }
        return (int) lo;
    }
};

class Solution {
    public long[] getLargestNumber(int[] expense, int p) {
        int n = expense.length;
        int[] adj = new int[n - 1];
        for (int i = 0; i < n - 1; i++) adj[i] = expense[i] + expense[i + 1];
        Arrays.sort(adj);
        long base = expense[0] + expense[n - 1];
        long minC = base, maxC = base;
        for (int i = 0; i < p - 1; i++) {
            minC += adj[i];
            maxC += adj[n - 2 - i];
        }
        return new long[]{minC, maxC};
    }
}

