        for (int i = 0; i < n - 1; i++) adj[i] = expense[i] + expense[i + 1];
        sort(adj.begin(), adj.end());
        long long base = expense[0] + expense[n - 1];
        long long minC = base, maxC = base;
        for (int i = 0; i < p - 1; i++) {
            minC += adj[i];
            maxC += adj[n - 2 - i];
        }
        return {minC, maxC};
    }
};

def findPasswordStrength(password):
    n = len(password)
    last = {}
    total = 0
    for i, c in enumerate(password):
        prev = last.get(c, -1)
        total += (i - prev) * (n - i)
        last[c] = i
    return total

class Solution {
    public long findPasswordStrength(String password) {
        int n = password.length();
        int[] last = new int[26];
        Arrays.fill(last, -1);
        long total = 0;
        for (int i = 0; i < n; i++) {
            int c = password.charAt(i) - 'a';
            total += (long)(i - last[c]) * (n - i);
            last[c] = i;
        }
        return total;
    }
}

class Solution {
public:
    long long findPasswordStrength(string password) {
        int n = password.size();
        int last[26];
        fill(last, last + 26, -1);
        long long total = 0;
        for (int i = 0; i < n; i++) {
            int c = password[i] - 'a';
            total += (long long)(i - last[c]) * (n - i);
            last[c] = i;
        }
        return total;
    }
};

class Solution {
    public List<String> findRecurringNames(String[] realNames, String[] allNames) {
        HashMap<String, Integer> cnt = new HashMap<>();
        for (String name : allNames) {
            char[] arr = name.toCharArray();
            Arrays.sort(arr);
            cnt.merge(new String(arr), 1, Integer::sum);
        }
        List<String> res = new ArrayList<>();
        for (String name : realNames) {
            char[] arr = name.toCharArray();
            Arrays.sort(arr);
            if (cnt.getOrDefault(new String(arr), 0) > 1) res.add(name);
        }
        Collections.sort(res);
        if (res.isEmpty()) res.add("None");
        return res;
    }
}

class Solution {
public:
    vector<string> findRecurringNames(vector<string>& realNames, vector<string>& allNames) {
        unordered_map<string, int> cnt;
        for (auto& name : allNames) {
            string s = name;
            sort(s.begin(), s.end());
            cnt[s]++;
        }
        vector<string> res;
        for (auto& name : realNames) {
            string s = name;
            sort(s.begin(), s.end());
            if (cnt[s] > 1) res.push_back(name);
        }
        sort(res.begin(), res.end());
        if (res.empty()) res.push_back("None");
        return res;
    }
};

import java.util.*;
class Solution {
    public int[] findRequestsInQueue(int[] wait) {
        int n = wait.length;
        List<Integer> res = new ArrayList<>();
        res.add(n);
        int served = 1, t = 1, i = 1;
        while (served < n) {
            while (i < n && wait[i] < t) { i++; served++; }
            if (served >= n) break;
            res.add(n - served);
            served++;
            i = Math.max(i, served);
            t++;
        }
        res.add(0);
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

