import java.util.*;
class Solution {
    public long findSecurityLevel(int[] pid, int k) {
        Map<Long, Long> cnt = new HashMap<>();
        cnt.put(0L, 1L);
        long pre = 0, ans = 0;
        for (int i = 1; i <= pid.length; i++) {
            pre = (pre + pid[i - 1]) % k;
            long key = ((pre - i) % k + k) % k;
            ans += cnt.getOrDefault(key, 0L);
            cnt.merge(key, 1L, Long::sum);
        }
        return ans;
    }
}

class Solution {
public:
    long long findSecurityLevel(vector<int>& pid, int k) {
        unordered_map<long long, long long> cnt;
        cnt[0] = 1;
        long long pre = 0, ans = 0;
        for (int i = 1; i <= (int)pid.size(); i++) {
            pre = (pre + pid[i - 1]) % k;
            long long key = ((pre - i) % k + k) % k;
            ans += cnt[key];
            cnt[key]++;
        }
        return ans;
    }
};

def findSubarrayWithMinimumDistinctIntegers(array: list[int], series1: int, series2: int) -> int:
    if series1 == series2:
        return 1 if series1 in array else 0
    n = len(array)
    pos1 = [i for i, v in enumerate(array) if v == series1]
    pos2 = [i for i, v in enumerate(array) if v == series2]
    if not pos1 or not pos2:
        return 0
    best = n + 1
    import bisect
    for i in pos1:
        # nearest pos2 around i
        j = bisect.bisect_left(pos2, i)
        for cand in (j - 1, j):
            if 0 <= cand < len(pos2):
                l, r = min(i, pos2[cand]), max(i, pos2[cand])
                distinct = len(set(array[l:r + 1]))
                best = min(best, distinct)
    return best

import java.util.*;
class Solution {
    public int findSubarrayWithMinimumDistinctIntegers(int[] array, int s1, int s2) {
        if (s1 == s2) {
            for (int v : array) if (v == s1) return 1;
            return 0;
        }
        List<Integer> p1 = new ArrayList<>(), p2 = new ArrayList<>();
        for (int i = 0; i < array.length; i++) {
            if (array[i] == s1) p1.add(i);
            if (array[i] == s2) p2.add(i);
        }
        if (p1.isEmpty() || p2.isEmpty()) return 0;
        int best = Integer.MAX_VALUE;
        for (int i : p1) {
            int idx = Collections.binarySearch(p2, i);
            if (idx < 0) idx = -idx - 1;
            for (int k : new int[]{idx - 1, idx}) {
                if (k < 0 || k >= p2.size()) continue;
                int l = Math.min(i, p2.get(k)), r = Math.max(i, p2.get(k));
                Set<Integer> seen = new HashSet<>();
                for (int j = l; j <= r; j++) seen.add(array[j]);
                best = Math.min(best, seen.size());
            }
        }
        return best;
    }
}

class Solution {
public:
    int findSubarrayWithMinimumDistinctIntegers(vector<int>& a, int s1, int s2) {
        if (s1 == s2) {
            for (int v : a) if (v == s1) return 1;
            return 0;
        }
        vector<int> p1, p2;
        for (int i = 0; i < (int)a.size(); i++) {
            if (a[i] == s1) p1.push_back(i);
            if (a[i] == s2) p2.push_back(i);
        }
        if (p1.empty() || p2.empty()) return 0;
        int best = INT_MAX;
        for (int i : p1) {
            auto it = lower_bound(p2.begin(), p2.end(), i);
            for (auto cand : {it - 1, it}) {
                if (cand < p2.begin() || cand >= p2.end()) continue;
                int l = min(i, *cand), r = max(i, *cand);
                set<int> seen(a.begin() + l, a.begin() + r + 1);
                best = min(best, (int)seen.size());
            }
        }
        return best;
    }
};

def findSumOfBeauties(arr: list[int], pairs: list[list[int]]) -> int:
    import bisect
    n = len(arr)
    diff = [0] * (n + 1)
    for l, r in pairs:
        diff[l] += 1
        diff[r + 1] -= 1
    cnt = [0] * n
    cur = 0
    for i in range(n):
        cur += diff[i]
        cnt[i] = cur
    beautiful = []
    for i in range(n):
        if cnt[i] > 0:
            beautiful.extend([arr[i]] * cnt[i])
    beautiful.sort()
    total = 0
    for i in range(n):
        if cnt[i] == 0:
            total += bisect.bisect_left(beautiful, arr[i])
    return total

import java.util.*;
class Solution {
    public long findSumOfBeauties(int[] arr, int[][] pairs) {
        int n = arr.length;
        int[] diff = new int[n + 1];
        for (int[] p : pairs) { diff[p[0]]++; diff[p[1] + 1]--; }
        int[] cnt = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) { cur += diff[i]; cnt[i] = cur; }
        List<Integer> bf = new ArrayList<>();
        for (int i = 0; i < n; i++) for (int k = 0; k < cnt[i]; k++) bf.add(arr[i]);
        Collections.sort(bf);
        long total = 0;
        for (int i = 0; i < n; i++) {
            if (cnt[i] == 0) {
                int lo = 0, hi = bf.size();
                while (lo < hi) {
                    int m = (lo + hi) >>> 1;
                    if (bf.get(m) < arr[i]) lo = m + 1; else hi = m;
                }
                total += lo;
            }
        }
        return total;
    }
}

class Solution {
public:
    long long findSumOfBeauties(vector<int>& arr, vector<vector<int>>& pairs) {
        int n = arr.size();
        vector<int> diff(n + 1, 0);
        for (auto& p : pairs) { diff[p[0]]++; diff[p[1] + 1]--; }
        vector<int> cnt(n);
        int cur = 0;
        for (int i = 0; i < n; i++) { cur += diff[i]; cnt[i] = cur; }
        vector<int> bf;
        for (int i = 0; i < n; i++) for (int k = 0; k < cnt[i]; k++) bf.push_back(arr[i]);
        sort(bf.begin(), bf.end());
        long long total = 0;
        for (int i = 0; i < n; i++) {
            if (cnt[i] == 0) {
                total += lower_bound(bf.begin(), bf.end(), arr[i]) - bf.begin();
            }
        }
        return total;
    }
};

