import java.util.*;
class Solution {
    public int[] getActiveRequestsCount(int requests, int[] wait_time) {
        Deque<Integer> active = new ArrayDeque<>();
        for (int i = 0; i < requests; i++) active.add(i);
        List<Integer> res = new ArrayList<>();
        int t = 0;
        while (!active.isEmpty()) {
            res.add(active.size());
            active.pollFirst();
            t++;
            final int tt = t;
            active.removeIf(idx -> wait_time[idx] < tt);
        }
        res.add(0);
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> getActiveRequestsCount(int requests, vector<int>& wait_time) {
        deque<int> active;
        for (int i = 0; i < requests; i++) active.push_back(i);
        vector<int> res;
        int t = 0;
        while (!active.empty()) {
            res.push_back(active.size());
            active.pop_front();
            t++;
            int tt = t;
            while (!active.empty()) {
                bool changed = false;
                deque<int> next;
                for (int x : active) if (wait_time[x] >= tt) next.push_back(x);
                if (next.size() == active.size()) break;
                active = next;
            }
        }
        res.push_back(0);
        return res;
    }
};

