def getMaxAggregateTemperatureChange(tempChange: list[int]) -> int:
    n = len(tempChange)
    prefix = [0] * n
    suffix = [0] * n
    s = 0
    for i in range(n):
        s += tempChange[i]
        prefix[i] = s
    s = 0
    for i in range(n - 1, -1, -1):
        s += tempChange[i]
        suffix[i] = s
    return max(max(prefix[i], suffix[i]) for i in range(n))

class Solution {
    public long getMaxAggregateTemperatureChange(int[] tempChange) {
        int n = tempChange.length;
        long[] prefix = new long[n], suffix = new long[n];
        long s = 0;
        for (int i = 0; i < n; i++) { s += tempChange[i]; prefix[i] = s; }
        s = 0;
        for (int i = n - 1; i >= 0; i--) { s += tempChange[i]; suffix[i] = s; }
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) best = Math.max(best, Math.max(prefix[i], suffix[i]));
        return best;
    }
}

