        for (int i = 0; i < n; i++) best = max(best, max(prefix[i], suffix[i]));
        return best;
    }
};

def getMaxAlternatingMusic(music: str, k: int) -> int:
    def best(start_bit: str) -> int:
        flips = 0
        left = 0
        ans = 0
        for right, ch in enumerate(music):
            expected = start_bit if (right - left) % 2 == 0 else ('1' if start_bit == '0' else '0')
            # easier: compute expected based on absolute index parity
            pass
        # Restart cleanly with absolute parity approach
        flips = 0
        left = 0
        ans = 0
        for right in range(len(music)):
            expected = start_bit if right % 2 == 0 else ('1' if start_bit == '0' else '0')
            if music[right] != expected:
                flips += 1
            while flips > k:
                exp_l = start_bit if left % 2 == 0 else ('1' if start_bit == '0' else '0')
                if music[left] != exp_l:
                    flips -= 1
                left += 1
            ans = max(ans, right - left + 1)
        return ans
    return max(best('0'), best('1'))

class Solution {
    public int getMaxAlternatingMusic(String music, int k) {
        return Math.max(best(music, k, '0'), best(music, k, '1'));
    }
    private int best(String s, int k, char start) {
        char other = start == '0' ? '1' : '0';
        int flips = 0, left = 0, ans = 0;
        for (int right = 0; right < s.length(); right++) {
            char exp = (right % 2 == 0) ? start : other;
            if (s.charAt(right) != exp) flips++;
            while (flips > k) {
                char expL = (left % 2 == 0) ? start : other;
                if (s.charAt(left) != expL) flips--;
                left++;
            }
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

class Solution {
public:
    int getMaxAlternatingMusic(string music, int k) {
        return max(best(music, k, '0'), best(music, k, '1'));
    }
private:
    int best(const string& s, int k, char start) {
        char other = start == '0' ? '1' : '0';
        int flips = 0, left = 0, ans = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            char exp = (right % 2 == 0) ? start : other;
            if (s[right] != exp) flips++;
            while (flips > k) {
                char expL = (left % 2 == 0) ? start : other;
                if (s[left] != expL) flips--;
                left++;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

def getMaxConsecutiveON(machine_status: str, max_flips: int) -> int:
    n = len(machine_status)
    # 0 段开始位置标记
    zero_starts = [0] * (n + 1)
    for i in range(n):
        zero_starts[i + 1] = zero_starts[i] + (1 if machine_status[i] == '0' and (i == 0 or machine_status[i - 1] != '0') else 0)
    def zero_segs(l: int, r: int) -> int:
        # 区间 [l, r] 内 0 段数 = zero_starts[r+1] - zero_starts[l] (- 调整)
        base = zero_starts[r + 1] - zero_starts[l]
        # 若 l > 0 且 machine_status[l] == '0' 且 machine_status[l-1] == '0'，则首段并非新段
        if l > 0 and machine_status[l] == '0' and machine_status[l - 1] == '0':
            base += 1
        return base
    ans = 0
    l = 0
    for r in range(n):
        while zero_segs(l, r) > max_flips:
            l += 1
        ans = max(ans, r - l + 1)
    return ans

class Solution {
    public int getMaxConsecutiveON(String s, int maxFlips) {
        int n = s.length();
        int ans = 0, l = 0;
        for (int r = 0; r < n; r++) {
            while (zeroSegs(s, l, r) > maxFlips) l++;
            ans = Math.max(ans, r - l + 1);
        }
        return ans;
    }
    private int zeroSegs(String s, int l, int r) {
        int cnt = 0;
        for (int i = l; i <= r; i++) {
            if (s.charAt(i) == '0' && (i == l || s.charAt(i - 1) != '0')) cnt++;
        }
        return cnt;
    }
}

class Solution {
public:
    int getMaxConsecutiveON(string s, int maxFlips) {
        int n = s.size(), ans = 0, l = 0;
        auto zeroSegs = [&](int l, int r) {
            int cnt = 0;
            for (int i = l; i <= r; i++)
                if (s[i] == '0' && (i == l || s[i - 1] != '0')) cnt++;
            return cnt;
        };
        for (int r = 0; r < n; r++) {
            while (zeroSegs(l, r) > maxFlips) l++;
            ans = max(ans, r - l + 1);
        }
        return ans;
    }
};

def getMaxDiscountPairs(price: list[int]) -> int:
    from collections import defaultdict
    if not price:
        return 0
    max_sum = max(price) * 2 + 1
    powers = []
    p = 1
    while p <= max_sum:
        powers.append(p)
        p *= 3
    cnt = defaultdict(int)
    ans = 0
    for v in price:
        for T in powers:
            if T - v in cnt:
                ans += cnt[T - v]
        cnt[v] += 1
    return ans

import java.util.*;
class Solution {
    public long getMaxDiscountPairs(int[] price) {
        if (price.length == 0) return 0;
        int mx = 0;
        for (int v : price) mx = Math.max(mx, v);
        List<Long> powers = new ArrayList<>();
        long p = 1;
        while (p <= 2L * mx + 1) { powers.add(p); p *= 3; }
        Map<Long, Long> cnt = new HashMap<>();
        long ans = 0;
        for (int v : price) {
            for (long T : powers) ans += cnt.getOrDefault(T - v, 0L);
            cnt.merge((long) v, 1L, Long::sum);
        }
        return ans;
    }
}

class Solution {
public:
    long long getMaxDiscountPairs(vector<int>& price) {
        if (price.empty()) return 0;
        int mx = *max_element(price.begin(), price.end());
        vector<long long> powers;
        long long p = 1;
        while (p <= 2LL * mx + 1) { powers.push_back(p); p *= 3; }
        unordered_map<long long, long long> cnt;
        long long ans = 0;
        for (int v : price) {
            for (long long T : powers) {
                auto it = cnt.find(T - v);
                if (it != cnt.end()) ans += it->second;
            }
            cnt[v]++;
        }
        return ans;
    }
};

