def getMaxInformationGain(dataSet: list[str], max_common_features: int) -> int:
    from collections import Counter
    profiles = [Counter(s) for s in dataSet]
    lengths = [len(s) for s in dataSet]
    n = len(dataSet)
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            common = sum(min(profiles[i][c], profiles[j][c]) for c in profiles[i])
            if common <= max_common_features:
                best = max(best, abs(lengths[i] - lengths[j]))
    return best

