def getMaxPrograms(time: list[int], m: int, k: int) -> int:
    n = len(time)
    def feasible(start: int) -> bool:
        slot_left = k
        slots_used = 1
        for i in range(start, n):
            t = time[i]
            if t > k:
                return False
            if t <= slot_left:
                slot_left -= t
            else:
                slots_used += 1
                if slots_used > m:
                    return False
                slot_left = k - t
        return True
    best = 0
    for start in range(n - 1, -1, -1):
        if feasible(start):
            best = n - start
        else:
            break  # 注：从右往左扩张，一旦不可行就停（前缀不会更优）
    return best

class Solution {
    public int getMaxPrograms(int[] time, int m, int k) {
        int n = time.length, best = 0;
        for (int start = n - 1; start >= 0; start--) {
            if (feasible(time, start, m, k)) best = n - start;
            else break;
        }
        return best;
    }
    private boolean feasible(int[] time, int start, int m, int k) {
        int slotLeft = k, used = 1;
        for (int i = start; i < time.length; i++) {
            if (time[i] > k) return false;
            if (time[i] <= slotLeft) slotLeft -= time[i];
            else {
                used++;
                if (used > m) return false;
                slotLeft = k - time[i];
            }
        }
        return true;
    }
}

class Solution {
public:
    int getMaxPrograms(vector<int>& time, int m, int k) {
        int n = time.size(), best = 0;
        auto feasible = [&](int start) {
            int slotLeft = k, used = 1;
            for (int i = start; i < n; i++) {
                if (time[i] > k) return false;
                if (time[i] <= slotLeft) slotLeft -= time[i];
                else {
                    used++;
                    if (used > m) return false;
                    slotLeft = k - time[i];
                }
            }
            return true;
        };
        for (int start = n - 1; start >= 0; start--) {
            if (feasible(start)) best = n - start;
            else break;
        }
        return best;
    }
};

import java.util.*;
class Solution {
    public int getMaxRacers(int[] speed, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int l = 0, maxFreq = 0, ans = 0;
        for (int r = 0; r < speed.length; r++) {
            cnt.merge(speed[r], 1, Integer::sum);
            maxFreq = Math.max(maxFreq, cnt.get(speed[r]));
            while ((r - l + 1) - maxFreq > k) {
                cnt.merge(speed[l], -1, Integer::sum);
                l++;
            }
            ans = Math.max(ans, maxFreq);
        }
        return ans;
    }
}

class Solution {
public:
    int getMaxRacers(vector<int>& speed, int k) {
        unordered_map<int, int> cnt;
        int l = 0, maxFreq = 0, ans = 0;
        for (int r = 0; r < (int)speed.size(); r++) {
            maxFreq = max(maxFreq, ++cnt[speed[r]]);
            while ((r - l + 1) - maxFreq > k) {
                cnt[speed[l]]--;
                l++;
            }
            ans = max(ans, maxFreq);
        }
        return ans;
    }
};

def getMaxSkillSum(expertise: list[int], skill: list[int]) -> int:
    first = {0: 0}  # diff -> prefix_skill_at_that_time
    diff = 0
    pref = 0
    best = 0
    for i in range(len(expertise)):
        diff += 1 if expertise[i] == 0 else -1
        pref += skill[i]
        if diff in first:
            best = max(best, pref - first[diff])
        else:
            first[diff] = pref
    return best

import java.util.*;
class Solution {
    public long getMaxSkillSum(int[] expertise, int[] skill) {
        Map<Integer, Long> first = new HashMap<>();
        first.put(0, 0L);
        int diff = 0;
        long pref = 0, best = 0;
        for (int i = 0; i < expertise.length; i++) {
            diff += expertise[i] == 0 ? 1 : -1;
            pref += skill[i];
            if (first.containsKey(diff)) best = Math.max(best, pref - first.get(diff));
            else first.put(diff, pref);
        }
        return best;
    }
}

class Solution {
public:
    long long getMaxSkillSum(vector<int>& expertise, vector<int>& skill) {
        unordered_map<int, long long> first;
        first[0] = 0;
        int diff = 0;
        long long pref = 0, best = 0;
        for (int i = 0; i < (int)expertise.size(); i++) {
            diff += expertise[i] == 0 ? 1 : -1;
            pref += skill[i];
            auto it = first.find(diff);
            if (it != first.end()) best = max(best, pref - it->second);
            else first[diff] = pref;
        }
        return best;
    }
};

