class Solution {
    public int getMaxStability(int[] reliability, int[] availability) {
        final long MOD = 1_000_000_007L;
        int n = reliability.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(availability[b], availability[a]));
        long total = 0, best = 0;
        for (int i : idx) {
            total += reliability[i];
            best = Math.max(best, (long) availability[i] * total);
        }
        return (int) (best % MOD);
    }
}

