        int n = reliability.size();
        vector<pair<int, int>> p(n);
        for (int i = 0; i < n; i++) p[i] = {availability[i], reliability[i]};
        sort(p.begin(), p.end(), greater<>());
        long long total = 0, best = 0;
        for (auto& [a, r] : p) {
            total += r;
            best = max(best, (long long) a * total);
        }
        return (int) (best % MOD);
    }
};

