class Solution {
    public int computeMaxScheduledTasks(int maxDailyHours, int[] mandatoryTasks, int[] optionalTasks) {
        int n = mandatoryTasks.length;
        Integer[] remain = new Integer[n];
        for (int i = 0; i < n; i++) remain[i] = maxDailyHours - mandatoryTasks[i];
        Arrays.sort(remain, Comparator.reverseOrder());
        int[] opts = optionalTasks.clone();
        Arrays.sort(opts);
        int j = 0, placed = 0;
        for (int o : opts) {
            if (j < n && remain[j] >= o) { placed++; j++; }
        }
        return placed;
    }
}

