def getMaxTotalArea(sideLengths: list[int]) -> int:
    MOD = 10**9 + 7
    arr = sorted(sideLengths, reverse=True)
    sides = []  # 已配对的边长
    i = 0
    n = len(arr)
    while i < n - 1:
        if arr[i] == arr[i + 1]:
            sides.append(arr[i])
            i += 2
        elif arr[i] - arr[i + 1] == 1:
            sides.append(arr[i + 1])
            i += 2
        else:
            i += 1
    total = 0
    for k in range(0, len(sides) - 1, 2):
        total = (total + sides[k] * sides[k + 1]) % MOD
    return total

import java.util.*;
class Solution {
    public int getMaxTotalArea(int[] sideLengths) {
        final long MOD = 1_000_000_007L;
        Integer[] arr = Arrays.stream(sideLengths).boxed().toArray(Integer[]::new);
        Arrays.sort(arr, Comparator.reverseOrder());
        List<Integer> sides = new ArrayList<>();
        int i = 0, n = arr.length;
        while (i < n - 1) {
            if (arr[i].equals(arr[i + 1])) { sides.add(arr[i]); i += 2; }
            else if (arr[i] - arr[i + 1] == 1) { sides.add(arr[i + 1]); i += 2; }
            else { i++; }
        }
        long total = 0;
        for (int k = 0; k + 1 < sides.size(); k += 2) {
            total = (total + (long) sides.get(k) * sides.get(k + 1)) % MOD;
        }
        return (int) total;
    }
}

