import java.util.*;
class Solution {
    public int getMaximumCount(int[] arr, int k) {
        int base = 0;
        Set<Integer> values = new HashSet<>();
        for (int v : arr) { if (v == k) base++; else values.add(v); }
        int bestGain = 0;
        for (int v : values) {
            int cur = 0, localBest = 0;
            for (int x : arr) {
                int delta = (x == v ? 1 : 0) - (x == k ? 1 : 0);
                cur = Math.max(delta, cur + delta);
                localBest = Math.max(localBest, cur);
            }
            bestGain = Math.max(bestGain, localBest);
        }
        return base + bestGain;
    }
}

