def getMinAdjustments(videoScores, maxAdjustments):
    def need(x):
        return sum((s + x - 1) // x for s in videoScores)
    lo, hi = 1, max(videoScores)
    while lo < hi:
        mid = (lo + hi) // 2
        if need(mid) <= maxAdjustments:
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int getMinAdjustments(int[] videoScores, int maxAdjustments) {
        int lo = 1, hi = 0;
        for (int v : videoScores) hi = Math.max(hi, v);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long need = 0;
            for (int s : videoScores) need += (s + mid - 1) / mid;
            if (need <= maxAdjustments) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

