class Solution {
    long getMinCost(int[] cost, int pairCost, int k) {
        int n = cost.length;
        long[] pref = new long[n + 1], suf = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + cost[i];
        for (int i = n - 1; i >= 0; i--) suf[n - i] = suf[n - i - 1] + cost[i];
        long best = Long.MAX_VALUE;
        int maxJ = Math.min(k, n / 2);
        for (int j = 0; j <= maxJ; j++) {
            int rem = n - 2 * j;
