        for (char c : errorString.toCharArray()) {
            if (c == '0') { cost += y * pre1; pre0++; }
            else if (c == '1') { cost += x * pre0; pre1++; }
            else {
                if (y * pre1 <= x * pre0) { cost += y * pre1; pre0++; }
                else { cost += x * pre0; pre1++; }
            }
        }
        return (int)(cost % MOD);
    }
}

class Solution {
public:
    int getMinErrors(string errorString, int x, int y) {
        long long MOD = 1'000'000'007;
        long long pre0 = 0, pre1 = 0, cost = 0;
        for (char c : errorString) {
            if (c == '0') { cost += (long long)y * pre1; pre0++; }
            else if (c == '1') { cost += (long long)x * pre0; pre1++; }
            else {
                if ((long long)y * pre1 <= (long long)x * pre0) { cost += y * pre1; pre0++; }
                else { cost += x * pre0; pre1++; }
            }
        }
        return cost % MOD;
    }
};

