class Solution {
    long getMinOperations(int[] source, int[] target) {
        int n = source.length;
        long[] d = new long[n];
        for (int i = 0; i < n; i++) { d[i] = target[i] - source[i]; if (d[i] < 0) return -1; }
        long[] s = new long[n], p = new long[n];
        for (int i = 1; i < n; i++) s[i] = s[i-1] + Math.max(0, d[i] - d[i-1]);
        for (int i = 0; i < n; i++) { p[i] = d[i] - s[i]; if (p[i] < 0) return -1; }
        for (int i = 1; i < n; i++) if (p[i] > p[i-1]) return -1;
        return p[0] + s[n-1];
    }
}

class Solution {
public:
