        int n = source.size();
        vector<long long> d(n);
        for (int i = 0; i < n; i++) { d[i] = target[i] - source[i]; if (d[i] < 0) return -1; }
        vector<long long> s(n), p(n);
        for (int i = 1; i < n; i++) s[i] = s[i-1] + max(0LL, d[i] - d[i-1]);
        for (int i = 0; i < n; i++) { p[i] = d[i] - s[i]; if (p[i] < 0) return -1; }
        for (int i = 1; i < n; i++) if (p[i] > p[i-1]) return -1;
        return p[0] + s[n-1];
    }
};

def getMinRemoval(catalogue, k):
