def getMinTime(total_servers, servers):
    s = sorted(set(servers))
    if len(s) <= 1:
        return 0
    max_gap = 0
    for i in range(1, len(s)):
        max_gap = max(max_gap, s[i] - s[i-1])
    # 跨环 gap
    max_gap = max(max_gap, total_servers - s[-1] + s[0])
    return total_servers - max_gap

class Solution {
    int getMinTime(int total_servers, int[] servers) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int v : servers) set.add(v);
        if (set.size() <= 1) return 0;
        Integer[] s = set.toArray(new Integer[0]);
        int max_gap = 0;
        for (int i = 1; i < s.length; i++) max_gap = Math.max(max_gap, s[i] - s[i-1]);
        max_gap = Math.max(max_gap, total_servers - s[s.length-1] + s[0]);
        return total_servers - max_gap;
    }
}

