        set<int> st(servers.begin(), servers.end());
        if (st.size() <= 1) return 0;
        vector<int> s(st.begin(), st.end());
        int max_gap = 0;
        for (int i = 1; i < (int)s.size(); i++) max_gap = max(max_gap, s[i] - s[i-1]);
        max_gap = max(max_gap, total_servers - s.back() + s.front());
        return total_servers - max_gap;
    }
};

class Solution {
    long getMinimalCost(int[] dimensions, int[] adjustmentCosts) {
        int n = dimensions.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> dimensions[a] - dimensions[b]);
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long total = 0;
        int cur = dimensions[idx[0]], i = 0;
        while (i < n || !heap.isEmpty()) {
            while (i < n && dimensions[idx[i]] <= cur) {
                heap.add(adjustmentCosts[idx[i]]);
                i++;
            }
            if (heap.isEmpty()) {
                cur = dimensions[idx[i]];
                continue;
            }
            int keep = heap.poll();
            for (int c : heap) total += c;
            // 模拟：每个剩余每轮 +1 直到独占某 d
            // 简化版本中我们按 cost 累加即可
            heap.clear();
            heap.add(keep);
            cur++;
        }
        return total;
    }
}

class Solution {
public:
    long long getMinimalCost(vector<int>& dimensions, vector<int>& adjustmentCosts) {
        int n = dimensions.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){ return dimensions[a] < dimensions[b]; });
        priority_queue<int> heap;
        long long total = 0;
        int cur = dimensions[idx[0]], i = 0;
        while (i < n || !heap.empty()) {
            while (i < n && dimensions[idx[i]] <= cur) {
                heap.push(adjustmentCosts[idx[i]]);
                i++;
            }
            if (heap.empty()) {
                cur = dimensions[idx[i]];
                continue;
            }
            int keep = heap.top(); heap.pop();
            vector<int> rest;
            while (!heap.empty()) { rest.push_back(heap.top()); heap.pop(); }
            for (int c : rest) { total += c; heap.push(c); }
            heap.push(keep);
            cur++;
        }
        return total;
    }
};

def getMinimumBoxes(boxes, capacity):
    arr = sorted(boxes)
    n = len(arr)
    best = 1
    j = 0
    for i in range(n):
        if j < i:
            j = i
        while j + 1 < n and arr[j + 1] <= capacity * arr[i]:
            j += 1
        best = max(best, j - i + 1)
    return n - best

