def getMinimumDockBays(truckCargoSize, maxTurnaroundTime):
    import heapq
    n = len(truckCargoSize)
    def ok(d):
        heap = [0] * d
        max_end = 0
        for t in truckCargoSize:
            cur = heapq.heappop(heap)
            cur += t
            if cur > maxTurnaroundTime:
                return False
            max_end = max(max_end, cur)
            heapq.heappush(heap, cur)
        return max_end <= maxTurnaroundTime
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int getMinimumDockBays(int[] truckCargoSize, long maxTurnaroundTime) {
        int n = truckCargoSize.length, lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(truckCargoSize, mid, maxTurnaroundTime)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
    boolean ok(int[] cargo, int d, long T) {
        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (int i = 0; i < d; i++) heap.add(0L);
        for (int t : cargo) {
            long cur = heap.poll() + t;
            if (cur > T) return false;
            heap.add(cur);
        }
        return true;
    }
}

class Solution {
public:
    int getMinimumDockBays(vector<int>& truckCargoSize, long long maxTurnaroundTime) {
        int n = truckCargoSize.size(), lo = 1, hi = n;
        auto ok = [&](int d) {
            priority_queue<long long, vector<long long>, greater<>> heap;
            for (int i = 0; i < d; i++) heap.push(0);
            for (int t : truckCargoSize) {
                long long cur = heap.top() + t; heap.pop();
                if (cur > maxTurnaroundTime) return false;
                heap.push(cur);
            }
            return true;
        };
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

def computeLeastTruckCount(items, capacity, max_same_type_limit):
    total = sum(items)
    a = (total + capacity - 1) // capacity
    b = max((c + max_same_type_limit - 1) // max_same_type_limit for c in items)
    return max(a, b)

class Solution {
    int computeLeastTruckCount(int[] items, int capacity, int maxSameTypeLimit) {
        long total = 0;
        for (int v : items) total += v;
        long a = (total + capacity - 1) / capacity;
        long b = 0;
        for (int v : items) b = Math.max(b, (v + maxSameTypeLimit - 1) / maxSameTypeLimit);
        return (int) Math.max(a, b);
    }
}

