        return max(a, b);
    }
};

def getMinimumNumberOfUniqueDistributionCenters(n, dailyTrend):
    # 简化为：对相邻关系（<, >, =），合并连续 = 为一个；得到 +/- 序列。
    # 答案 = 序列中最长"折线段"上的不同节点数 = LIS（按方向变化分段）
    # 实际：等价于 dilworth：最少链覆盖 = 最长反链 = 最长 zig-zag 长度的一半 …
    # 更直接：对每个位置算"以此结尾的最长 strictly increasing run" 与 "strictly decreasing run"，取 max。
    if n == 0:
        return 0
    inc = [1] * n
    dec = [1] * n
    for i in range(1, n):
        if dailyTrend[i] > dailyTrend[i-1]:
            inc[i] = inc[i-1] + 1
            dec[i] = 1
        elif dailyTrend[i] < dailyTrend[i-1]:
            dec[i] = dec[i-1] + 1
            inc[i] = 1
        else:
            inc[i] = inc[i-1]
            dec[i] = dec[i-1]
    return max(max(inc), max(dec))

class Solution {
    int getMinimumNumberOfUniqueDistributionCenters(int n, int[] dailyTrend) {
        if (n == 0) return 0;
        int[] inc = new int[n], dec = new int[n];
        inc[0] = dec[0] = 1;
        int best = 1;
        for (int i = 1; i < n; i++) {
            if (dailyTrend[i] > dailyTrend[i-1]) { inc[i] = inc[i-1] + 1; dec[i] = 1; }
            else if (dailyTrend[i] < dailyTrend[i-1]) { dec[i] = dec[i-1] + 1; inc[i] = 1; }
            else { inc[i] = inc[i-1]; dec[i] = dec[i-1]; }
            best = Math.max(best, Math.max(inc[i], dec[i]));
        }
        return best;
    }
}

class Solution {
public:
    int getMinimumNumberOfUniqueDistributionCenters(int n, vector<int>& dailyTrend) {
        if (n == 0) return 0;
        vector<int> inc(n, 1), dec(n, 1);
        int best = 1;
        for (int i = 1; i < n; i++) {
            if (dailyTrend[i] > dailyTrend[i-1]) { inc[i] = inc[i-1] + 1; dec[i] = 1; }
            else if (dailyTrend[i] < dailyTrend[i-1]) { dec[i] = dec[i-1] + 1; inc[i] = 1; }
            else { inc[i] = inc[i-1]; dec[i] = dec[i-1]; }
            best = max(best, max(inc[i], dec[i]));
        }
        return best;
    }
};

