def getNumPerfectPackaging(prices):
    MOD = 10**9 + 7
    n = len(prices)
    dp = [1] * 6  # 1..5，0 不用
    dp[0] = 0
    for i in range(1, n):
        new_dp = [0] * 6
        for s in range(1, 6):
            for ps in range(1, 6):
                if prices[i] > prices[i-1] and s > ps:
                    new_dp[s] = (new_dp[s] + dp[ps]) % MOD
                elif prices[i] < prices[i-1] and s < ps:
                    new_dp[s] = (new_dp[s] + dp[ps]) % MOD
                elif prices[i] == prices[i-1] and s != ps:
                    new_dp[s] = (new_dp[s] + dp[ps]) % MOD
        dp = new_dp
    return sum(dp) % MOD

class Solution {
    int getNumPerfectPackaging(int[] prices) {
        int MOD = 1_000_000_007, n = prices.length;
        long[] dp = new long[6];
        for (int s = 1; s <= 5; s++) dp[s] = 1;
        for (int i = 1; i < n; i++) {
            long[] nd = new long[6];
            for (int s = 1; s <= 5; s++) for (int p = 1; p <= 5; p++) {
                boolean ok = (prices[i] > prices[i-1] && s > p)
                          || (prices[i] < prices[i-1] && s < p)
                          || (prices[i] == prices[i-1] && s != p);
                if (ok) nd[s] = (nd[s] + dp[p]) % MOD;
            }
            dp = nd;
        }
        long ans = 0;
        for (long v : dp) ans = (ans + v) % MOD;
        return (int) ans;
    }
}

