        int n = a.length;
        for (int i = 0; i < n; i++) {
            int lo = lowerBound(a, i + 1, n, min_skill - a[i]);
            int hi = upperBound(a, i + 1, n, max_skill - a[i]);
            ans += hi - lo;
        }
        return ans;
    }
    int lowerBound(int[] a, int l, int r, int v) {
        while (l < r) { int m = (l + r) >>> 1; if (a[m] < v) l = m + 1; else r = m; } return l;
    }
    int upperBound(int[] a, int l, int r, int v) {
        while (l < r) { int m = (l + r) >>> 1; if (a[m] <= v) l = m + 1; else r = m; } return l;
    }
}

