def getOperations(resource):
    sorted_arr = sorted(resource)
    n = len(resource)
    # 找最长 sorted_arr 的前缀作为已是子序列的部分
    i = 0  # sorted_arr 指针
    for v in resource:
        if i < n and v == sorted_arr[i]:
            i += 1
    ops = sorted_arr[i:]
    if not ops:
        return [-1]
    return ops

class Solution {
    int[] getOperations(int[] resource) {
        int n = resource.length;
        int[] sorted = resource.clone();
        Arrays.sort(sorted);
        int i = 0;
        for (int v : resource) if (i < n && v == sorted[i]) i++;
        if (i == n) return new int[]{-1};
        int[] ops = new int[n - i];
        for (int k = 0; k < n - i; k++) ops[k] = sorted[i + k];
        return ops;
    }
}

