            else prefC++;
            long long key = (long long)(a - 1) * prefV + (long long)(b - 1) * prefC;
            ans += cnt[key];
            cnt[key]++;
        }
        return ans;
    }
};

def getSpecialString(s):
    arr = list(s)
    n = len(arr)
    i = n - 1
    while i >= 0:
        # 尝试 arr[i] += 1
        c = ord(arr[i]) + 1
        while c <= ord('z'):
            arr[i] = chr(c)
            if i == 0 or arr[i] != arr[i-1]:
                # 后续填最小字符
                for j in range(i+1, n):
                    for cc in 'ab':
                        if (j == 0 or cc != arr[j-1]):
                            arr[j] = cc
                            break
                return ''.join(arr)
            c += 1
        i -= 1
    return "-1"

class Solution {
