        int n = arr.length, i = n - 1;
        while (i >= 0) {
            for (char c = (char)(arr[i] + 1); c <= 'z'; c++) {
                arr[i] = c;
                if (i == 0 || arr[i] != arr[i-1]) {
                    for (int j = i + 1; j < n; j++) {
                        for (char cc = 'a'; cc <= 'z'; cc++) {
