class Solution {
    int getStablePeriodsCount(int[] revenues, int k) {
        int MOD = 1_000_000_007;
        HashMap<Integer,Integer> cnt = new HashMap<>();
        int distinct = 0, l = 0;
        long ans = 0;
        for (int r = 0; r < revenues.length; r++) {
            if (cnt.getOrDefault(revenues[r], 0) == 0) distinct++;
            cnt.merge(revenues[r], 1, Integer::sum);
            while (distinct > k) {
                cnt.merge(revenues[l], -1, Integer::sum);
                if (cnt.get(revenues[l]) == 0) distinct--;
                l++;
            }
            ans = (ans + r - l + 1) % MOD;
        }
        return (int) ans;
    }
}

