        }
        return ans;
    }
};

class Solution {
    int[] getTotalRequests(int[] server, int[] replaced, int[] newId) {
        HashMap<Integer, Long> cnt = new HashMap<>();
        long total = 0;
        for (int v : server) { cnt.merge(v, 1L, Long::sum); total += v; }
        int n = replaced.length;
        int[] ans = new int[n];
        for (int j = 0; j < n; j++) {
            long c = cnt.getOrDefault(replaced[j], 0L);
            total -= (long) replaced[j] * c;
            cnt.put(replaced[j], 0L);
            cnt.merge(newId[j], c, Long::sum);
            total += (long) newId[j] * c;
            ans[j] = (int) total;
        }
        return ans;
    }
}

