class Solution {
    int helpAmazonFindMinTimeAgain(String password, int[] attackOrder, int m) {
        int n = password.length();
        long total = (long) n * (n + 1) / 2;
        TreeSet<Integer> bad = new TreeSet<>();
        bad.add(0); bad.add(n + 1);
        long clean = total;
        for (int t = 0; t < attackOrder.length; t++) {
            int pos = attackOrder[t];
            Integer left = bad.lower(pos);
            Integer right = bad.higher(pos);
            long L = right - left - 1;
            clean -= L * (L + 1) / 2;
            long a = pos - left - 1, b = right - pos - 1;
            clean += a * (a + 1) / 2 + b * (b + 1) / 2;
            bad.add(pos);
            if (total - clean >= m) return t + 1;
        }
        return -1;
    }
}

class Solution {
