        int n = password.size();
        long long total = (long long) n * (n + 1) / 2;
        set<int> bad = {0, n + 1};
        long long clean = total;
        for (int t = 0; t < (int)attackOrder.size(); t++) {
            int pos = attackOrder[t];
            auto it = bad.upper_bound(pos);
            int right = *it;
            int left = *(--it);
            long long L = right - left - 1;
            clean -= L * (L + 1) / 2;
            long long a = pos - left - 1, b = right - pos - 1;
            clean += a * (a + 1) / 2 + b * (b + 1) / 2;
            bad.insert(pos);
            if (total - clean >= m) return t + 1;
        }
        return -1;
    }
};

