def isRegexMatching(regex, arr):
    # parse tokens: list of (pattern_str, has_star)
    tokens = []
    i = 0
    n = len(regex)
    while i < n:
        if regex[i] == '(':
            j = regex.index(')', i)
            pat = regex[i+1:j]
            i = j + 1
            has_star = i < n and regex[i] == '*'
            if has_star:
                i += 1
            tokens.append((pat, True, has_star))
        else:
            pat = regex[i]
            i += 1
            has_star = i < n and regex[i] == '*'
            if has_star:
                i += 1
            tokens.append((pat, False, has_star))
    def match_pat(pat, s, j):
        # 匹配 pat 与 s[j:j+len(pat)]，返回新 j 或 -1
        if j + len(pat) > len(s):
            return -1
        for k, c in enumerate(pat):
            if c != '.' and c != s[j + k]:
                return -1
        return j + len(pat)
    ans = []
    for s in arr:
        # dp[idx_token][j] = 可达
        m = len(s)
        # 状态压缩：保留当前层 set
        cur = {0}
        for pat, _, has_star in tokens:
            nxt = set()
            if has_star:
                # 0 次保持当前位置
                nxt |= cur
            for j in cur:
                # 至少 1 次
                k = j
                while True:
                    nk = match_pat(pat, s, k)
                    if nk < 0:
                        break
                    nxt.add(nk)
                    if not has_star:
                        break
                    k = nk
            cur = nxt
        ans.append("YES" if m in cur else "NO")
    return ans

class Solution {
    String[] isRegexMatching(String regex, String[] arr) {
        // 简化：按 token 解析 + BFS 匹配
        List<String[]> tokens = new ArrayList<>();
        int n = regex.length(), i = 0;
        while (i < n) {
            String pat;
            if (regex.charAt(i) == '(') {
                int j = regex.indexOf(')', i);
                pat = regex.substring(i + 1, j);
                i = j + 1;
            } else { pat = String.valueOf(regex.charAt(i)); i++; }
            boolean star = i < n && regex.charAt(i) == '*';
            if (star) i++;
            tokens.add(new String[]{pat, star ? "1" : "0"});
        }
        String[] result = new String[arr.length];
        for (int idx = 0; idx < arr.length; idx++) {
            String s = arr[idx];
            HashSet<Integer> cur = new HashSet<>();
            cur.add(0);
            for (String[] tk : tokens) {
                String pat = tk[0];
                boolean star = tk[1].equals("1");
                HashSet<Integer> nxt = new HashSet<>();
                if (star) nxt.addAll(cur);
                for (int j : cur) {
                    int k = j;
                    while (true) {
                        if (k + pat.length() > s.length()) break;
                        boolean ok = true;
                        for (int p = 0; p < pat.length(); p++) {
                            if (pat.charAt(p) != '.' && pat.charAt(p) != s.charAt(k + p)) { ok = false; break; }
                        }
                        if (!ok) break;
                        k += pat.length();
                        nxt.add(k);
                        if (!star) break;
                    }
                }
                cur = nxt;
            }
            result[idx] = cur.contains(s.length()) ? "YES" : "NO";
        }
        return result;
    }
}

class Solution {
public:
    vector<string> isRegexMatching(string regex, vector<string>& arr) {
        vector<pair<string, bool>> tokens;
        int n = regex.size(), i = 0;
        while (i < n) {
            string pat;
            if (regex[i] == '(') {
                int j = regex.find(')', i);
                pat = regex.substr(i + 1, j - i - 1);
                i = j + 1;
            } else { pat = string(1, regex[i]); i++; }
            bool star = i < n && regex[i] == '*';
            if (star) i++;
            tokens.push_back({pat, star});
        }
        vector<string> result;
        for (string& s : arr) {
            unordered_set<int> cur = {0};
            for (auto& [pat, star] : tokens) {
                unordered_set<int> nxt;
                if (star) nxt.insert(cur.begin(), cur.end());
                for (int j : cur) {
                    int k = j;
                    while (true) {
                        if (k + (int)pat.size() > (int)s.size()) break;
                        bool ok = true;
                        for (int p = 0; p < (int)pat.size(); p++) {
                            if (pat[p] != '.' && pat[p] != s[k + p]) { ok = false; break; }
                        }
                        if (!ok) break;
                        k += pat.size();
                        nxt.insert(k);
                        if (!star) break;
                    }
                }
                cur = nxt;
            }
            result.push_back(cur.count((int)s.size()) ? "YES" : "NO");
        }
        return result;
    }
};

def isSpecialSequence(dna_sequence):
    n = len(dna_sequence)
    if n < 2:
        return "NO"
    # 前缀 mask
    pref = [0] * (n + 1)
    for i, c in enumerate(dna_sequence):
        pref[i+1] = pref[i] ^ (1 << (ord(c) - ord('a')))
    total = pref[n]
    for i in range(1, n):
        left = pref[i]
        right = pref[n] ^ pref[i]
        if bin(left).count('1') <= 3 and bin(right).count('1') <= 3:
            return "YES"
    return "NO"

class Solution {
    String isSpecialSequence(String dna_sequence) {
        int n = dna_sequence.length();
        if (n < 2) return "NO";
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i+1] = pref[i] ^ (1 << (dna_sequence.charAt(i) - 'a'));
        for (int i = 1; i < n; i++) {
            int left = pref[i], right = pref[n] ^ pref[i];
            if (Integer.bitCount(left) <= 3 && Integer.bitCount(right) <= 3) return "YES";
        }
        return "NO";
    }
}

