class Solution {
    int[] lexicographicallyMaximalResultingArray(int[] weight, int k) {
        int n = weight.length;
        List<Integer> res = new ArrayList<>();
        int i = 0, prev = Integer.MAX_VALUE;
        while (i < n) {
            int cand = -1, candIdx = -1;
            for (int j = i; j < n; j++) {
                if (weight[j] <= prev && weight[j] > cand) { cand = weight[j]; candIdx = j; }
            }
            if (cand < 0) break;
            res.add(cand);
            prev = cand;
            i = candIdx + 1 + k;
        }
        int[] r = new int[res.size()];
        for (int j = 0; j < r.length; j++) r[j] = res.get(j);
        return r;
    }
}

class Solution {
public:
    vector<int> lexicographicallyMaximalResultingArray(vector<int>& weight, int k) {
        int n = weight.size();
        vector<int> res;
        int i = 0, prev = INT_MAX;
        while (i < n) {
            int cand = -1, candIdx = -1;
            for (int j = i; j < n; j++) {
                if (weight[j] <= prev && weight[j] > cand) { cand = weight[j]; candIdx = j; }
            }
            if (cand < 0) break;
            res.push_back(cand);
            prev = cand;
            i = candIdx + 1 + k;
        }
        return res;
    }
};

def solve(s):
    arr = list(s); n = len(arr)
    from collections import Counter
    cnt = Counter(c for c in arr if c != '?')
    i, j = 0, n - 1
    while i < j:
        if arr[i] != '?' and arr[j] != '?':
            if arr[i] != arr[j]: return "-1"
            cnt[arr[i]] -= 2
        elif arr[i] != '?': arr[j] = arr[i]; cnt[arr[i]] -= 1
        elif arr[j] != '?': arr[i] = arr[j]; cnt[arr[j]] -= 1
        i += 1; j -= 1
    if n % 2 == 1 and arr[n // 2] == '?':
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if cnt[c] > 0: arr[n // 2] = c; cnt[c] -= 1; break
        else: arr[n // 2] = 'a'
    elif n % 2 == 1: cnt[arr[n // 2]] -= 1
    for v in cnt.values():
        if v % 2: return "-1"
    pool = []
    for c in 'abcdefghijklmnopqrstuvwxyz': pool.extend([c] * (cnt[c] // 2))
    p = 0; i, j = 0, n - 1
    while i < j:
        if arr[i] == '?': arr[i] = pool[p]; arr[j] = pool[p]; p += 1
        i += 1; j -= 1
    return ''.join(arr)

class Solution {
    String solve(String s) {
        char[] arr = s.toCharArray();
        int n = arr.length;
        int[] cnt = new int[26];
        for (char c : arr) if (c != '?') cnt[c - 'a']++;
        int i = 0, j = n - 1;
        while (i < j) {
            if (arr[i] != '?' && arr[j] != '?') {
                if (arr[i] != arr[j]) return "-1";
                cnt[arr[i] - 'a'] -= 2;
            } else if (arr[i] != '?') { arr[j] = arr[i]; cnt[arr[i] - 'a']--; }
            else if (arr[j] != '?') { arr[i] = arr[j]; cnt[arr[j] - 'a']--; }
            i++; j--;
        }
        if ((n & 1) == 1 && arr[n / 2] == '?') {
            for (int c = 0; c < 26; c++) if (cnt[c] > 0) { arr[n / 2] = (char)('a' + c); cnt[c]--; break; }
            if (arr[n / 2] == '?') arr[n / 2] = 'a';
        } else if ((n & 1) == 1) cnt[arr[n / 2] - 'a']--;
        for (int c = 0; c < 26; c++) if ((cnt[c] & 1) != 0) return "-1";
        StringBuilder pool = new StringBuilder();
        for (int c = 0; c < 26; c++) for (int t = 0; t < cnt[c] / 2; t++) pool.append((char)('a' + c));
        int p = 0; i = 0; j = n - 1;
        while (i < j) {
            if (arr[i] == '?') { arr[i] = pool.charAt(p); arr[j] = pool.charAt(p); p++; }
            i++; j--;
        }
        return new String(arr);
    }
}

class Solution {
public:
    string solve(string s) {
        int n = s.size();
        vector<int> cnt(26);
        for (char c : s) if (c != '?') cnt[c - 'a']++;
        int i = 0, j = n - 1;
        while (i < j) {
            if (s[i] != '?' && s[j] != '?') {
                if (s[i] != s[j]) return "-1";
                cnt[s[i] - 'a'] -= 2;
            } else if (s[i] != '?') { s[j] = s[i]; cnt[s[i] - 'a']--; }
            else if (s[j] != '?') { s[i] = s[j]; cnt[s[j] - 'a']--; }
            i++; j--;
        }
        if ((n & 1) && s[n / 2] == '?') {
            for (int c = 0; c < 26; c++) if (cnt[c] > 0) { s[n / 2] = 'a' + c; cnt[c]--; break; }
            if (s[n / 2] == '?') s[n / 2] = 'a';
        } else if (n & 1) cnt[s[n / 2] - 'a']--;
        for (int c = 0; c < 26; c++) if (cnt[c] & 1) return "-1";
        string pool;
        for (int c = 0; c < 26; c++) pool.append(cnt[c] / 2, 'a' + c);
        int p = 0; i = 0; j = n - 1;
        while (i < j) {
            if (s[i] == '?') { s[i] = pool[p]; s[j] = pool[p]; p++; }
            i++; j--;
        }
        return s;
    }
};

def longestPerfectAnagrams(s):
    from collections import defaultdict
    n = len(s)
    for L in range(n - 1, 0, -1):
        sigs = defaultdict(set)
        cnt = [0] * 26
        for i in range(L):
            cnt[ord(s[i]) - ord('a')] += 1
        sigs[tuple(cnt)].add(s[0:L])
        for r in range(L, n):
            cnt[ord(s[r]) - ord('a')] += 1
            cnt[ord(s[r - L]) - ord('a')] -= 1
            sigs[tuple(cnt)].add(s[r - L + 1:r + 1])
        for v in sigs.values():
            if len(v) >= 2:
                return L
    return -1

class Solution {
    int longestPerfectAnagrams(String s) {
        int n = s.length();
        for (int L = n - 1; L >= 1; L--) {
            HashMap<String, HashSet<String>> sigs = new HashMap<>();
            int[] cnt = new int[26];
            for (int i = 0; i < L; i++) cnt[s.charAt(i) - 'a']++;
            sigs.computeIfAbsent(Arrays.toString(cnt), k -> new HashSet<>()).add(s.substring(0, L));
            for (int r = L; r < n; r++) {
                cnt[s.charAt(r) - 'a']++;
                cnt[s.charAt(r - L) - 'a']--;
                sigs.computeIfAbsent(Arrays.toString(cnt), k -> new HashSet<>()).add(s.substring(r - L + 1, r + 1));
            }
            for (var v : sigs.values()) if (v.size() >= 2) return L;
        }
        return -1;
    }
}

class Solution {
public:
    int longestPerfectAnagrams(string s) {
        int n = s.size();
        for (int L = n - 1; L >= 1; L--) {
            map<vector<int>, set<string>> sigs;
            vector<int> cnt(26, 0);
            for (int i = 0; i < L; i++) cnt[s[i] - 'a']++;
            sigs[cnt].insert(s.substr(0, L));
            for (int r = L; r < n; r++) {
                cnt[s[r] - 'a']++;
                cnt[s[r - L] - 'a']--;
                sigs[cnt].insert(s.substr(r - L + 1, L));
            }
            for (auto& [k, v] : sigs) if (v.size() >= 2) return L;
        }
        return -1;
    }
};

