import java.util.*;
class Solution {
    public long makeArrayDistinct(int[] size, int[] cost) {
        int n = size.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(size[a], size[b]));
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long totalCost = 0, saved = 0;
        int pos = size[idx[0]];
        int j = 0;
        while (j < n || !heap.isEmpty()) {
            if (heap.isEmpty()) pos = size[idx[j]];
            while (j < n && size[idx[j]] <= pos) {
                heap.add(cost[idx[j]]);
                j++;
            }
            saved += heap.poll();
            pos++;
        }
        for (int c : cost) totalCost += c;
        return totalCost - saved;
    }
}

class Solution {
public:
    long long makeArrayDistinct(vector<int>& size, vector<int>& cost) {
        int n = size.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) { return size[a] < size[b]; });
        priority_queue<int> heap;
        long long totalCost = 0, saved = 0;
        int pos = size[idx[0]];
        int j = 0;
        while (j < n || !heap.empty()) {
            if (heap.empty()) pos = size[idx[j]];
            while (j < n && size[idx[j]] <= pos) {
                heap.push(cost[idx[j]]);
                j++;
            }
            saved += heap.top();
            heap.pop();
            pos++;
        }
        for (int c : cost) totalCost += c;
        return totalCost - saved;
    }
};

