def minOperationsToMakeValuesContiguous(arr: list[int]) -> int:
    from collections import Counter
    segments = []
    for v in arr:
        if not segments or segments[-1] != v:
            segments.append(v)
    cnt = Counter(segments)
    return sum(1 for v in cnt.values() if v >= 2)

import java.util.*;
class Solution {
    public int minOperationsToMakeValuesContiguous(int[] arr) {
        List<Integer> segs = new ArrayList<>();
        for (int v : arr) {
            if (segs.isEmpty() || segs.get(segs.size() - 1) != v) segs.add(v);
        }
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int v : segs) cnt.merge(v, 1, Integer::sum);
        int ans = 0;
        for (int v : cnt.values()) if (v >= 2) ans++;
        return ans;
    }
}

class Solution {
public:
    int minOperationsToMakeValuesContiguous(vector<int>& arr) {
        vector<int> segs;
        for (int v : arr) if (segs.empty() || segs.back() != v) segs.push_back(v);
        unordered_map<int, int> cnt;
        for (int v : segs) cnt[v]++;
        int ans = 0;
        for (auto& [k, v] : cnt) if (v >= 2) ans++;
        return ans;
    }
};

def matchStrings(text: list[str], pat: list[str]) -> list[str]:
    res = []
    for t, p in zip(text, pat):
        star = p.index('*')
        prefix, suffix = p[:star], p[star + 1:]
        if len(t) >= len(prefix) + len(suffix) and t.startswith(prefix) and t.endswith(suffix):
            res.append("YES")
        else:
            res.append("NO")
    return res

class Solution {
    public String[] matchStrings(String[] text, String[] pat) {
        String[] res = new String[text.length];
        for (int i = 0; i < text.length; i++) {
            String t = text[i], p = pat[i];
            int star = p.indexOf('*');
            String pre = p.substring(0, star), suf = p.substring(star + 1);
            res[i] = (t.length() >= pre.length() + suf.length() && t.startsWith(pre) && t.endsWith(suf)) ? "YES" : "NO";
        }
        return res;
    }
}

class Solution {
public:
    vector<string> matchStrings(vector<string>& text, vector<string>& pat) {
        vector<string> res;
        for (int i = 0; i < (int) text.size(); i++) {
            const string& t = text[i];
            const string& p = pat[i];
            int star = p.find('*');
            string pre = p.substr(0, star), suf = p.substr(star + 1);
            bool ok = (int) t.size() >= (int) (pre.size() + suf.size())
                   && t.compare(0, pre.size(), pre) == 0
                   && t.compare(t.size() - suf.size(), suf.size(), suf) == 0;
            res.push_back(ok ? "YES" : "NO");
        }
        return res;
    }
};

def maxBatchesForShipment(inventory):
    a = sorted(inventory, reverse=True)
    s = 0; k = 0
    for i, v in enumerate(a):
        s += v
        if s >= (i + 1) * (i + 2) // 2:
            k = i + 1
    return k

class Solution {
    int maxBatchesForShipment(int[] inventory) {
        int[] a = inventory.clone();
        Arrays.sort(a);
        for (int i = 0, j = a.length - 1; i < j; i++, j--) { int t = a[i]; a[i] = a[j]; a[j] = t; }
        long s = 0; int k = 0;
        for (int i = 0; i < a.length; i++) {
            s += a[i];
            if (s >= (long)(i + 1) * (i + 2) / 2) k = i + 1;
        }
        return k;
    }
}

