class Solution {
    long maxSumOfNonOverlappingIntervals(int[] starts, int[] durations, int[] costs) {
        int n = starts.length;
        int[][] iv = new int[n][3];
        for (int i = 0; i < n; i++) { iv[i][0] = starts[i]; iv[i][1] = starts[i] + durations[i]; iv[i][2] = costs[i]; }
        Arrays.sort(iv, (a, b) -> a[1] - b[1]);
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            int lo = 0, hi = i - 1;
            while (lo < hi) {
                int m = (lo + hi) >>> 1;
                if (iv[m][1] <= iv[i-1][0]) lo = m + 1;
                else hi = m;
            }
            dp[i] = Math.max(dp[i-1], dp[lo] + iv[i-1][2]);
        }
        return dp[n];
    }
}

class Solution {
public:
    long long maxSumOfNonOverlappingIntervals(vector<int>& starts, vector<int>& durations, vector<int>& costs) {
        int n = starts.size();
        vector<array<int, 3>> iv(n);
        for (int i = 0; i < n; i++) iv[i] = {starts[i], starts[i] + durations[i], costs[i]};
        sort(iv.begin(), iv.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        vector<int> ends(n);
        for (int i = 0; i < n; i++) ends[i] = iv[i][1];
        vector<long long> dp(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            int j = upper_bound(ends.begin(), ends.begin() + i - 1, iv[i-1][0]) - ends.begin();
            dp[i] = max(dp[i-1], dp[j] + iv[i-1][2]);
        }
        return dp[n];
    }
};

def maxTransferRate(throughput, pipelineCount):
    import heapq
    n = len(throughput)
    t = sorted(throughput, reverse=True)
    heap = [(-(t[0] + t[0]), 0, 0)]
    seen = {(0, 0)}
    total = 0
    for _ in range(pipelineCount):
        neg, i, j = heapq.heappop(heap)
        total += -neg
        for ni, nj in ((i + 1, j), (i, j + 1)):
            if ni < n and nj < n and (ni, nj) not in seen:
                seen.add((ni, nj))
                heapq.heappush(heap, (-(t[ni] + t[nj]), ni, nj))
    return total

class Solution {
    long maxTransferRate(int[] throughput, int pipelineCount) {
        int n = throughput.length;
        int[] t = throughput.clone();
        Arrays.sort(t);
        for (int i = 0, j = n - 1; i < j; i++, j--) { int tmp = t[i]; t[i] = t[j]; t[j] = tmp; }
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(b[0], a[0]));
        HashSet<Long> seen = new HashSet<>();
        heap.add(new long[]{(long)t[0] + t[0], 0, 0});
        seen.add(0L);
        long total = 0;
        for (int k = 0; k < pipelineCount; k++) {
            long[] top = heap.poll();
            total += top[0];
            int i = (int) top[1], j = (int) top[2];
            for (int[] d : new int[][]{{i + 1, j}, {i, j + 1}}) {
                if (d[0] < n && d[1] < n) {
                    long key = (long) d[0] * 200000 + d[1];
                    if (!seen.contains(key)) {
                        seen.add(key);
                        heap.add(new long[]{(long)t[d[0]] + t[d[1]], d[0], d[1]});
                    }
                }
            }
        }
        return total;
    }
}

class Solution {
public:
    long long maxTransferRate(vector<int>& throughput, int pipelineCount) {
        int n = throughput.size();
        vector<int> t = throughput;
        sort(t.begin(), t.end(), greater<int>());
        priority_queue<tuple<long long, int, int>> heap;
        set<pair<int,int>> seen;
        heap.push({(long long)t[0] + t[0], 0, 0});
        seen.insert({0, 0});
        long long total = 0;
        for (int k = 0; k < pipelineCount; k++) {
            auto [r, i, j] = heap.top(); heap.pop();
            total += r;
            for (auto& [ni, nj] : vector<pair<int,int>>{{i+1, j}, {i, j+1}}) {
                if (ni < n && nj < n && !seen.count({ni, nj})) {
                    seen.insert({ni, nj});
                    heap.push({(long long)t[ni] + t[nj], ni, nj});
                }
            }
        }
        return total;
    }
};

def maximizeClusterPower(n, arr):
    a = sorted(arr)
    k = n // 3
    return sum(a[n - 2 - 2 * i] for i in range(k))

class Solution {
    long maximizeClusterPower(int n, int[] arr) {
        int[] a = arr.clone();
        Arrays.sort(a);
        int k = n / 3;
        long total = 0;
        for (int i = 0; i < k; i++) total += a[n - 2 - 2 * i];
        return total;
    }
}

class Solution {
public:
    long long maximizeClusterPower(int n, vector<int>& arr) {
        vector<int> a = arr;
        sort(a.begin(), a.end());
        int k = n / 3;
        long long total = 0;
        for (int i = 0; i < k; i++) total += a[n - 2 - 2 * i];
        return total;
    }
};

def maximizeFinalElement(arr):
    a = sorted(arr)
    a[0] = 1
    for i in range(1, len(a)):
        a[i] = min(a[i], a[i-1] + 1)
    return a[-1]

class Solution {
    int maximizeFinalElement(int[] arr) {
        int[] a = arr.clone();
        Arrays.sort(a);
        a[0] = 1;
        for (int i = 1; i < a.length; i++) a[i] = Math.min(a[i], a[i-1] + 1);
        return a[a.length - 1];
    }
}

class Solution {
public:
    int maximizeFinalElement(vector<int>& arr) {
        vector<int> a = arr;
        sort(a.begin(), a.end());
        a[0] = 1;
        for (int i = 1; i < (int)a.size(); i++) a[i] = min(a[i], a[i-1] + 1);
        return a.back();
    }
};

class Solution {
    public int maximizePagesBeforeSuspension(int[] pages, int limit) {
        int l = 0, best = 0;
        long s = 0;
        for (int r = 0; r < pages.length; r++) {
            s += pages[r];
            while (s > limit && l <= r) {
                s -= pages[l];
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

