def maximizeParenthesesEfficiencyScore(s: str) -> int:
    stack = []
    score = 0
    for ch in s:
        if ch == '(':
            stack.append(ch)
        elif ch == ')' and stack:
            stack.pop()
            score += 1
    return score

import java.util.*;
class Solution {
    public int maximizeParenthesesEfficiencyScore(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        int score = 0;
        for (char ch : s.toCharArray()) {
            if (ch == '(') stack.push(ch);
            else if (ch == ')' && !stack.isEmpty()) { stack.pop(); score++; }
        }
        return score;
    }
}

class Solution {
public:
    int maximizeParenthesesEfficiencyScore(string s) {
        stack<char> st;
        int score = 0;
        for (char ch : s) {
            if (ch == '(') st.push(ch);
            else if (ch == ')' && !st.empty()) { st.pop(); score++; }
        }
        return score;
    }
};

def maximizePartitions(s: str) -> int:
    last = {ch: i for i, ch in enumerate(s)}
    end = 0
    count = 0
    for i, ch in enumerate(s):
        end = max(end, last[ch])
        if i == end:
            count += 1
    return count

class Solution {
    public int maximizePartitions(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;
        int end = 0, count = 0;
        for (int i = 0; i < s.length(); i++) {
            end = Math.max(end, last[s.charAt(i) - 'a']);
            if (i == end) count++;
        }
        return count;
    }
}

class Solution {
public:
    int maximizePartitions(string s) {
        int last[26] = {0};
        for (int i = 0; i < (int) s.size(); i++) last[s[i] - 'a'] = i;
        int end = 0, count = 0;
        for (int i = 0; i < (int) s.size(); i++) {
            end = max(end, last[s[i] - 'a']);
            if (i == end) count++;
        }
        return count;
    }
};

import java.util.*;
class Solution {
    long best = 0;
    int n;
    List<List<Integer>> g;
    public long maximizeProductOfSizesOfSubtrees(int n, int[][] edges) {
        this.n = n;
        g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        dfs(1, -1);
        return best;
    }
    int dfs(int u, int p) {
        int s = 1;
        for (int v : g.get(u)) {
            if (v != p) {
                int ch = dfs(v, u);
                s += ch;
                best = Math.max(best, (long) ch * (n - ch));
            }
        }
        return s;
    }
}

class Solution {
public:
    long long best = 0;
    int n;
    vector<vector<int>> g;
    long long maximizeProductOfSizesOfSubtrees(int n_, vector<vector<int>>& edges) {
        n = n_;
        g.assign(n + 1, {});
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        function<int(int, int)> dfs = [&](int u, int p) {
            int s = 1;
            for (int v : g[u]) if (v != p) {
                int ch = dfs(v, u);
                s += ch;
                best = max(best, (long long) ch * (n - ch));
            }
            return s;
        };
        dfs(1, -1);
        return best;
    }
};

