def maximizeSubtreeProduct(n: int, edges: list[list[int]], values: list[int]) -> int:
    MOD = 10**9 + 7
    from collections import defaultdict
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    total = sum(values)
    best = [0]
    def dfs(u: int, p: int) -> int:
        s = values[u - 1] if 1 <= u <= n else 0
        for v in g[u]:
            if v != p:
                s += dfs(v, u)
        if p != -1:
            best[0] = max(best[0], s * (total - s))
        return s
    dfs(1, -1)
    return best[0] % MOD

