class Solution {
    long best = 0;
    long total = 0;
    List<List<Integer>> g;
    int[] values;
    public int maximizeSubtreeProduct(int n, int[][] edges, int[] values) {
        this.values = values;
        g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        for (int v : values) total += v;
        dfs(1, -1);
        return (int) (best % 1_000_000_007L);
    }
    long dfs(int u, int p) {
        long s = (1 <= u && u <= values.length) ? values[u - 1] : 0;
        for (int v : g.get(u)) if (v != p) s += dfs(v, u);
        if (p != -1) best = Math.max(best, s * (total - s));
        return s;
    }
}

