def maximizeSumOfArray(arr: list[int], k: int) -> int:
    arr = sorted(arr)
    i = 0
    while k > 0 and i < len(arr) and arr[i] < 0:
        arr[i] = -arr[i]
        i += 1
        k -= 1
    if k % 2 == 1:
        m = min(range(len(arr)), key=lambda x: arr[x])
        arr[m] = -arr[m]
    return sum(arr)

