def maximumNumberOfProductsYouCanPick(weights: list[int], capacity: int) -> int:
    n = len(weights)
    # 前缀和 + 滑窗反向
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + weights[i]
    best = 0
    suf = 0
    j = n
    for i in range(n + 1):
        # 从右边取 j..n-1
        while j > i and pref[i] + (pref[n] - pref[j]) > capacity:
            j -= 1
            if j < i:
                break
        if pref[i] > capacity:
            break
        best = max(best, i + (n - j))
    return best

class Solution {
    public int maximumNumberOfProductsYouCanPick(int[] weights, int capacity) {
        int n = weights.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + weights[i];
        int best = 0, j = n;
        for (int i = 0; i <= n; i++) {
            if (pref[i] > capacity) break;
            while (j > i && pref[i] + (pref[n] - pref[j]) > capacity) j--;
            if (j < i) break;
            best = Math.max(best, i + (n - j));
        }
        return best;
    }
}

