import java.util.*;
class Solution {
    public int maximumPossibleRacers(int[] speed, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int l = 0, maxFreq = 0, ans = 0;
        for (int r = 0; r < speed.length; r++) {
            cnt.merge(speed[r], 1, Integer::sum);
            maxFreq = Math.max(maxFreq, cnt.get(speed[r]));
            while ((r - l + 1) - maxFreq > k) {
                cnt.merge(speed[l], -1, Integer::sum);
                l++;
            }
            ans = Math.max(ans, maxFreq);
        }
        return ans;
    }
}

