public:
    int maximumPossibleRacers(vector<int>& speed, int k) {
        unordered_map<int, int> cnt;
        int l = 0, maxFreq = 0, ans = 0;
        for (int r = 0; r < (int) speed.size(); r++) {
            maxFreq = max(maxFreq, ++cnt[speed[r]]);
            while ((r - l + 1) - maxFreq > k) {
                cnt[speed[l]]--;
                l++;
            }
            ans = max(ans, maxFreq);
        }
        return ans;
    }
};

