def minimumSets(a, b, k):
    intervals = sorted(zip(a, b))
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    m = len(merged)
    # 找最小 gap
    min_gap = float('inf')
    for i in range(1, m):
        gap = merged[i][0] - merged[i-1][1] - 1
        min_gap = min(min_gap, gap)
    if m > 1 and min_gap <= k:
        return m - 1
    return m

class Solution {
    int minimumSets(List<Integer> a, List<Integer> b, int k) {
        int n = a.size();
        int[][] iv = new int[n][2];
        for (int i = 0; i < n; i++) { iv[i][0] = a.get(i); iv[i][1] = b.get(i); }
        Arrays.sort(iv, (x, y) -> x[0] - y[0]);
        List<int[]> merged = new ArrayList<>();
        for (int[] x : iv) {
            if (!merged.isEmpty() && x[0] <= merged.get(merged.size() - 1)[1]) {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], x[1]);
            } else merged.add(x.clone());
        }
        int m = merged.size();
        int minGap = Integer.MAX_VALUE;
        for (int i = 1; i < m; i++) minGap = Math.min(minGap, merged.get(i)[0] - merged.get(i-1)[1] - 1);
        return (m > 1 && minGap <= k) ? m - 1 : m;
    }
}

class Solution {
public:
    int minimumSets(vector<int>& a, vector<int>& b, int k) {
        int n = a.size();
        vector<pair<int,int>> iv(n);
        for (int i = 0; i < n; i++) iv[i] = {a[i], b[i]};
        sort(iv.begin(), iv.end());
        vector<pair<int,int>> merged;
        for (auto& [s, e] : iv) {
            if (!merged.empty() && s <= merged.back().second) merged.back().second = max(merged.back().second, e);
            else merged.push_back({s, e});
        }
        int m = merged.size();
        int minGap = INT_MAX;
        for (int i = 1; i < m; i++) minGap = min(minGap, merged[i].first - merged[i-1].second - 1);
        return (m > 1 && minGap <= k) ? m - 1 : m;
    }
};

def minErrors(errorString, x, y):
    MOD = 10**9 + 7
    pre0 = pre1 = 0
    cost = 0
    for c in errorString:
        if c == '0':
            cost += y * pre1; pre0 += 1
        elif c == '1':
            cost += x * pre0; pre1 += 1
        else:
            if y * pre1 <= x * pre0:
                cost += y * pre1; pre0 += 1
            else:
                cost += x * pre0; pre1 += 1
    return cost % MOD

class Solution {
    int minErrors(String errorString, int x, int y) {
        long MOD = 1_000_000_007;
        long pre0 = 0, pre1 = 0, cost = 0;
        for (char c : errorString.toCharArray()) {
            if (c == '0') { cost += y * pre1; pre0++; }
            else if (c == '1') { cost += x * pre0; pre1++; }
            else {
                if (y * pre1 <= x * pre0) { cost += y * pre1; pre0++; }
                else { cost += x * pre0; pre1++; }
            }
        }
        return (int)(cost % MOD);
    }
}

class Solution {
public:
