def minOperations(prices, k, d):
    mx = max(prices); mn = min(prices)
    diff = mx - mn
    if diff < d:
        return 0
    reduce = diff - (d - 1)
    return (reduce + 2 * k - 1) // (2 * k)

class Solution {
    int minOperations(int[] prices, int k, int d) {
        int mx = Integer.MIN_VALUE, mn = Integer.MAX_VALUE;
        for (int v : prices) { mx = Math.max(mx, v); mn = Math.min(mn, v); }
        int diff = mx - mn;
        if (diff < d) return 0;
        int reduce = diff - (d - 1);
        return (reduce + 2 * k - 1) / (2 * k);
    }
}

