def minimalHeaviestSetA(arr):
    a = sorted(arr, reverse=True)
    total = sum(a)
    picked = []
    s = 0
    for v in a:
        picked.append(v)
        s += v
        if s > total - s:
            break
    return sorted(picked)

class Solution {
    int[] minimalHeaviestSetA(int[] arr) {
        int[] a = arr.clone();
        Arrays.sort(a);
        long total = 0;
        for (int v : a) total += v;
        List<Integer> picked = new ArrayList<>();
        long s = 0;
        for (int i = a.length - 1; i >= 0; i--) {
            picked.add(a[i]);
            s += a[i];
            if (s > total - s) break;
        }
        Collections.sort(picked);
        int[] res = new int[picked.size()];
        for (int i = 0; i < res.length; i++) res[i] = picked.get(i);
        return res;
    }
}

