    }
};

def minimizeArraySumDifference(arr):
    n = len(arr)
    if n <= 2:
        return arr[:]
    res = [arr[0]]
    for i in range(1, n - 1):
        if (arr[i] - arr[i - 1]) * (arr[i + 1] - arr[i]) < 0:
            res.append(arr[i])
    res.append(arr[-1])
    return res

class Solution {
    public int[] minimizeArraySumDifference(int[] arr) {
        int n = arr.length;
        if (n <= 2) return arr.clone();
        java.util.List<Integer> res = new java.util.ArrayList<>();
        res.add(arr[0]);
        for (int i = 1; i < n - 1; i++) {
            if ((long)(arr[i] - arr[i - 1]) * (arr[i + 1] - arr[i]) < 0) res.add(arr[i]);
        }
        res.add(arr[n - 1]);
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

