        if (n <= 2) return arr;
        vector<int> res{arr[0]};
        for (int i = 1; i < n - 1; i++) {
            long long a = arr[i] - arr[i - 1], b = arr[i + 1] - arr[i];
            if (a * b < 0) res.push_back(arr[i]);
        }
        res.push_back(arr.back());
        return res;
    }
};

