def fortuneTelling(n, m, A, B):
    vals = sorted(set(A) | set(B))
    best = float('inf')
    for i in range(len(vals)):
        for j in range(i, len(vals)):
            L, R = vals[i], vals[j]
            flips = 0
            ok = True
            for a, b in zip(A, B):
                aIn = L <= a <= R
                bIn = L <= b <= R
                if not aIn and not bIn:
                    ok = False; break
                if not aIn:
                    flips += 1
                    if flips > m:
                        ok = False; break
            if ok:
                best = min(best, R - L)
    return best

class Solution {
    public int fortuneTelling(int n, int m, int[] A, int[] B) {
        java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
        for (int x : A) set.add(x);
        for (int x : B) set.add(x);
        int[] vals = set.stream().mapToInt(Integer::intValue).toArray();
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < vals.length; i++) {
            for (int j = i; j < vals.length; j++) {
                int L = vals[i], R = vals[j], flips = 0;
                boolean ok = true;
                for (int k = 0; k < n; k++) {
                    boolean aIn = A[k] >= L && A[k] <= R;
                    boolean bIn = B[k] >= L && B[k] <= R;
                    if (!aIn && !bIn) { ok = false; break; }
                    if (!aIn) { flips++; if (flips > m) { ok = false; break; } }
                }
                if (ok) best = Math.min(best, R - L);
            }
        }
        return best;
    }
}

