                    if (!aIn) { flips++; if (flips > m) { ok = false; break; } }
                }
                if (ok) best = min(best, R - L);
            }
        }
        return best;
    }
};

class Solution {
    public long minimizeWarehouseTransferCost(int[] warehouses) {
        int n = warehouses.length;
        long sum = 0; for (int x : warehouses) sum += x;
