        long[] pref = new long[n];
        long s = 0;
        for (int i = 0; i < n; i++) { s += warehouses[i] - avg; pref[i] = s; }
        java.util.Arrays.sort(pref);
        long med = pref[n / 2], ans = 0;
        for (long p : pref) ans += Math.abs(p - med);
        return ans;
    }
