def minimumEnergyCost(weights, X, Y, El, Er):
    n = len(weights)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(l, r, last):
        if l > r:
            return 0
        cl = weights[l]*X + (El if last == 0 else 0) + dp(l+1, r, 0)
        cr = weights[r]*Y + (Er if last == 1 else 0) + dp(l, r-1, 1)
        return min(cl, cr)
    return dp(0, n - 1, 2)

class Solution {
    int[] w; int X, Y, El, Er;
    long[][][] memo; boolean[][][] vis;
    public long minimumEnergyCost(int[] weights, int X_, int Y_, int El_, int Er_) {
        w = weights; X = X_; Y = Y_; El = El_; Er = Er_;
        int n = weights.length;
        memo = new long[n][n][3]; vis = new boolean[n][n][3];
        return dp(0, n - 1, 2);
    }
    long dp(int l, int r, int last) {
        if (l > r) return 0;
        if (vis[l][r][last]) return memo[l][r][last];
        long cl = (long)w[l]*X + (last == 0 ? El : 0) + dp(l+1, r, 0);
        long cr = (long)w[r]*Y + (last == 1 ? Er : 0) + dp(l, r-1, 1);
        vis[l][r][last] = true;
        return memo[l][r][last] = Math.min(cl, cr);
    }
}

class Solution {
public:
    vector<int> w; int X, Y, El, Er;
    vector<vector<vector<long long>>> memo;
    vector<vector<vector<bool>>> vis;
    long long dp(int l, int r, int last) {
        if (l > r) return 0;
        if (vis[l][r][last]) return memo[l][r][last];
        long long cl = (long long)w[l]*X + (last == 0 ? El : 0) + dp(l+1, r, 0);
        long long cr = (long long)w[r]*Y + (last == 1 ? Er : 0) + dp(l, r-1, 1);
        vis[l][r][last] = true;
        return memo[l][r][last] = min(cl, cr);
    }
    long long minimumEnergyCost(vector<int>& weights, int X_, int Y_, int El_, int Er_) {
        w = weights; X = X_; Y = Y_; El = El_; Er = Er_;
        int n = weights.size();
        memo.assign(n, vector<vector<long long>>(n, vector<long long>(3, 0)));
        vis.assign(n, vector<vector<bool>>(n, vector<bool>(3, false)));
        return dp(0, n - 1, 2);
    }
};

def minimumInsertions(finalList, initialList):
    pos = {v: i for i, v in enumerate(finalList)}
    seq = [pos[v] for v in initialList if v in pos]
    from bisect import bisect_left
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(finalList) - len(tails)

class Solution {
    public int minimumInsertions(int[] finalList, int[] initialList) {
        java.util.Map<Integer, Integer> pos = new java.util.HashMap<>();
        for (int i = 0; i < finalList.length; i++) pos.put(finalList[i], i);
        java.util.List<Integer> tails = new java.util.ArrayList<>();
        for (int v : initialList) {
            Integer x = pos.get(v);
            if (x == null) continue;
            int lo = 0, hi = tails.size();
            while (lo < hi) { int m = (lo + hi) >>> 1; if (tails.get(m) < x) lo = m + 1; else hi = m; }
            if (lo == tails.size()) tails.add(x); else tails.set(lo, x);
        }
        return finalList.length - tails.size();
    }
}

class Solution {
public:
    int minimumInsertions(vector<int>& finalList, vector<int>& initialList) {
        unordered_map<int,int> pos;
        for (int i = 0; i < (int)finalList.size(); i++) pos[finalList[i]] = i;
        vector<int> tails;
        for (int v : initialList) {
            auto it = pos.find(v);
            if (it == pos.end()) continue;
            int x = it->second;
            auto p = lower_bound(tails.begin(), tails.end(), x);
            if (p == tails.end()) tails.push_back(x); else *p = x;
        }
        return finalList.size() - tails.size();
    }
};

class Solution {
    public int minimumMergeConflicts(String primary, String secondary) {
        int n = primary.length(), m = secondary.length();
        int[][] cntS = new int[m+1][26], cntP = new int[n+1][26];
        for (int j = m - 1; j >= 0; j--) { cntS[j] = cntS[j+1].clone(); cntS[j][secondary.charAt(j)-'a']++; }
        for (int i = n - 1; i >= 0; i--) { cntP[i] = cntP[i+1].clone(); cntP[i][primary.charAt(i)-'a']++; }
        int INF = Integer.MAX_VALUE / 2;
        int[][] f = new int[n+1][m+1];
        for (int[] r : f) java.util.Arrays.fill(r, INF);
        f[n][m] = 0;
        for (int i = n; i >= 0; i--) {
            for (int j = m; j >= 0; j--) {
                if (i == n && j == m) continue;
                int best = INF;
                if (i < n) {
                    int c = primary.charAt(i) - 'a', add = 0;
                    for (int k = 0; k < c; k++) add += cntS[j][k];
                    best = Math.min(best, f[i+1][j] + add);
                }
                if (j < m) {
                    int c = secondary.charAt(j) - 'a', add = 0;
                    for (int k = 0; k < c; k++) add += cntP[i][k];
                    best = Math.min(best, f[i][j+1] + add);
                }
                f[i][j] = best;
            }
        }
        return f[0][0];
    }
}

class Solution {
public:
    int minimumMergeConflicts(string primary, string secondary) {
        int n = primary.size(), m = secondary.size();
        vector<array<int,26>> cntS(m+1, {}), cntP(n+1, {});
        for (int j = m - 1; j >= 0; j--) { cntS[j] = cntS[j+1]; cntS[j][secondary[j]-'a']++; }
        for (int i = n - 1; i >= 0; i--) { cntP[i] = cntP[i+1]; cntP[i][primary[i]-'a']++; }
        vector<vector<int>> f(n+1, vector<int>(m+1, INT_MAX/2));
        f[n][m] = 0;
        for (int i = n; i >= 0; i--) {
            for (int j = m; j >= 0; j--) {
                if (i == n && j == m) continue;
                int best = INT_MAX/2;
                if (i < n) { int c = primary[i]-'a', add = 0; for (int k = 0; k < c; k++) add += cntS[j][k]; best = min(best, f[i+1][j] + add); }
                if (j < m) { int c = secondary[j]-'a', add = 0; for (int k = 0; k < c; k++) add += cntP[i][k]; best = min(best, f[i][j+1] + add); }
                f[i][j] = best;
            }
        }
        return f[0][0];
    }
};

