class Solution {
    public int minPreparationTime(int[] workList, int[] longPrepTime, int[] shortPrepTime) {
        int n = workList.length;
        java.util.HashMap<Integer, Integer> cur = new java.util.HashMap<>();
        cur.put(0, 0);
        int INF = Integer.MAX_VALUE / 2;
        for (int i = 0; i < n; i++) {
            int t = workList[i];
            java.util.HashMap<Integer, Integer> nxt = new java.util.HashMap<>();
            for (var e : cur.entrySet()) {
                int otherPrev = e.getKey(), val = e.getValue();
                if (i == 0) {
                    int add = longPrepTime[t-1];
                    nxt.merge(0, val + add, Math::min);
                } else {
                    int prev_this = workList[i-1];
                    int add_a = (prev_this == t) ? shortPrepTime[t-1] : longPrepTime[t-1];
                    nxt.merge(otherPrev, val + add_a, Math::min);
                    int add_b = (otherPrev == t) ? shortPrepTime[t-1] : longPrepTime[t-1];
                    nxt.merge(prev_this, val + add_b, Math::min);
                }
            }
            cur = nxt;
        }
        int best = INF;
        for (int v : cur.values()) best = Math.min(best, v);
        return best;
    }
}

class Solution {
public:
    int minPreparationTime(vector<int>& workList, vector<int>& longPrepTime, vector<int>& shortPrepTime) {
        int n = workList.size();
        unordered_map<int,int> cur; cur[0] = 0;
        for (int i = 0; i < n; i++) {
            int t = workList[i];
            unordered_map<int,int> nxt;
            for (auto& [otherPrev, val] : cur) {
                if (i == 0) {
                    int add = longPrepTime[t-1];
                    auto it = nxt.find(0);
                    if (it == nxt.end() || it->second > val + add) nxt[0] = val + add;
                } else {
                    int prev_this = workList[i-1];
                    int add_a = (prev_this == t) ? shortPrepTime[t-1] : longPrepTime[t-1];
                    int va = val + add_a;
                    auto it = nxt.find(otherPrev);
                    if (it == nxt.end() || it->second > va) nxt[otherPrev] = va;
                    int add_b = (otherPrev == t) ? shortPrepTime[t-1] : longPrepTime[t-1];
                    int vb = val + add_b;
                    it = nxt.find(prev_this);
                    if (it == nxt.end() || it->second > vb) nxt[prev_this] = vb;
                }
            }
            cur = move(nxt);
        }
        int best = INT_MAX;
        for (auto& [k, v] : cur) best = min(best, v);
        return best;
    }
};

class Solution {
    public int minimumRetailers(int[] zoneStart, int[] zoneEnd) {
        int n = zoneStart.length;
        int[][] ivs = new int[n][2];
        for (int i = 0; i < n; i++) { ivs[i][0] = zoneStart[i]; ivs[i][1] = zoneEnd[i]; }
        java.util.Arrays.sort(ivs, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        int best = 0;
        for (int[] iv : ivs) {
            while (!pq.isEmpty() && pq.peek() < iv[0]) pq.poll();
            pq.offer(iv[1]);
            best = Math.max(best, pq.size());
        }
        return n - best;
    }
}

class Solution {
public:
    int minimumRetailers(vector<int>& zoneStart, vector<int>& zoneEnd) {
        int n = zoneStart.size();
        vector<pair<int,int>> ivs(n);
        for (int i = 0; i < n; i++) ivs[i] = {zoneStart[i], zoneEnd[i]};
        sort(ivs.begin(), ivs.end());
        priority_queue<int, vector<int>, greater<int>> pq;
        int best = 0;
        for (auto& [s, e] : ivs) {
            while (!pq.empty() && pq.top() < s) pq.pop();
            pq.push(e);
            best = max(best, (int)pq.size());
        }
        return n - best;
    }
};

