def minimumSwapsToPalindrome(s):
    s = list(s)
    n = len(s)
    swaps = 0
    l, r = 0, n - 1
    while l < r:
        if s[l] == s[r]:
            l += 1; r -= 1
        else:
            j = r
            while j > l and s[j] != s[l]:
                j -= 1
            if j == l:
                s[l], s[l+1] = s[l+1], s[l]
                swaps += 1
            else:
                while j < r:
                    s[j], s[j+1] = s[j+1], s[j]
                    swaps += 1
                    j += 1
                l += 1; r -= 1
    return swaps

class Solution {
    public int minimumSwapsToPalindrome(String str) {
        char[] s = str.toCharArray();
        int n = s.length, swaps = 0, l = 0, r = n - 1;
        while (l < r) {
            if (s[l] == s[r]) { l++; r--; }
            else {
                int j = r;
                while (j > l && s[j] != s[l]) j--;
                if (j == l) {
                    char t = s[l]; s[l] = s[l+1]; s[l+1] = t;
                    swaps++;
                } else {
                    while (j < r) {
                        char t = s[j]; s[j] = s[j+1]; s[j+1] = t;
                        swaps++; j++;
                    }
                    l++; r--;
                }
            }
        }
        return swaps;
    }
}

class Solution {
public:
    int minimumSwapsToPalindrome(string s) {
        int n = s.size(), swaps = 0, l = 0, r = n - 1;
        while (l < r) {
            if (s[l] == s[r]) { l++; r--; }
            else {
                int j = r;
                while (j > l && s[j] != s[l]) j--;
                if (j == l) { swap(s[l], s[l+1]); swaps++; }
                else {
                    while (j < r) { swap(s[j], s[j+1]); swaps++; j++; }
                    l++; r--;
                }
            }
        }
        return swaps;
    }
};

class Solution {
    public long minimumTotalPackagingEffort(int[] packEffort, int[] packageCount) {
        int[] a = packEffort.clone();
        java.util.Arrays.sort(a);
        int m = a.length;
        long total = 0;
        for (int x : a) total += x;
        long best = total;
        java.util.TreeSet<Integer> pcs = new java.util.TreeSet<>();
        for (int c : packageCount) pcs.add(c);
        if (m >= 3) {
            for (int c : pcs) {
                if (c <= m - 2 && a[1] <= a[m - c]) {
                    best = Math.min(best, total - a[0] - a[1]);
                }
            }
        }
        return best;
    }
}

