def calculateMinimumValue(s, x, y):
    n = len(s)
    INF = float('inf')
    f = [INF, INF]
    if s[0] == '0' or s[0] == '!':
        f[0] = 0
    if s[0] == '1' or s[0] == '!':
        f[1] = 0
    for i in range(1, n):
        nf = [INF, INF]
        for b in range(2):
            if s[i] != '!' and s[i] != str(b):
                continue
            for pb in range(2):
                if f[pb] == INF:
                    continue
                add = 0
                if pb == 0 and b == 1: add = x
                if pb == 1 and b == 0: add = y
                if f[pb] + add < nf[b]:
                    nf[b] = f[pb] + add
        f = nf
    return min(f)

class Solution {
    public long calculateMinimumValue(String s, int x, int y) {
        int n = s.length();
        long INF = Long.MAX_VALUE / 4;
        long[] f = {INF, INF};
        char c0 = s.charAt(0);
        if (c0 == '0' || c0 == '!') f[0] = 0;
        if (c0 == '1' || c0 == '!') f[1] = 0;
        for (int i = 1; i < n; i++) {
            long[] nf = {INF, INF};
            char ci = s.charAt(i);
            for (int b = 0; b < 2; b++) {
                if (ci != '!' && ci - '0' != b) continue;
                for (int pb = 0; pb < 2; pb++) {
                    if (f[pb] == INF) continue;
                    long add = 0;
                    if (pb == 0 && b == 1) add = x;
                    if (pb == 1 && b == 0) add = y;
                    if (f[pb] + add < nf[b]) nf[b] = f[pb] + add;
                }
            }
            f = nf;
        }
        return Math.min(f[0], f[1]);
    }
}

class Solution {
public:
    long long calculateMinimumValue(string s, int x, int y) {
        int n = s.size();
        long long INF = LLONG_MAX / 4;
        long long f[2] = {INF, INF};
        if (s[0] == '0' || s[0] == '!') f[0] = 0;
        if (s[0] == '1' || s[0] == '!') f[1] = 0;
        for (int i = 1; i < n; i++) {
            long long nf[2] = {INF, INF};
            for (int b = 0; b < 2; b++) {
                if (s[i] != '!' && s[i] - '0' != b) continue;
                for (int pb = 0; pb < 2; pb++) {
                    if (f[pb] == INF) continue;
                    long long add = 0;
                    if (pb == 0 && b == 1) add = x;
                    if (pb == 1 && b == 0) add = y;
                    if (f[pb] + add < nf[b]) nf[b] = f[pb] + add;
                }
            }
            f[0] = nf[0]; f[1] = nf[1];
        }
        return min(f[0], f[1]);
    }
};

def minimumWeeklyInput(costs, weeks):
    n = len(costs)
    INF = float('inf')
    f = [[INF]*(weeks+1) for _ in range(n+1)]
    f[0][0] = 0
    for i in range(1, n+1):
        for k in range(1, min(i, weeks)+1):
            mx = 0
            for j in range(i-1, k-2, -1):
                mx = max(mx, costs[j])
                if f[j][k-1] != INF:
                    f[i][k] = min(f[i][k], f[j][k-1] + mx)
    return f[n][weeks]

class Solution {
    public int minimumWeeklyInput(int[] costs, int weeks) {
        int n = costs.length, INF = Integer.MAX_VALUE / 2;
        int[][] f = new int[n+1][weeks+1];
        for (int[] r : f) java.util.Arrays.fill(r, INF);
        f[0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int k = 1; k <= Math.min(i, weeks); k++) {
                int mx = 0;
                for (int j = i - 1; j >= k - 1; j--) {
                    mx = Math.max(mx, costs[j]);
                    if (f[j][k-1] != INF) f[i][k] = Math.min(f[i][k], f[j][k-1] + mx);
                }
            }
        }
        return f[n][weeks];
    }
}

