def mostCommonProductPair(transactions):
    from collections import Counter
    cnt = Counter()
    for tr in transactions:
        items = sorted(set(tr))
        for i in range(len(items)):
            for j in range(i+1, len(items)):
                cnt[(items[i], items[j])] += 1
    if not cnt:
        return []
    best_freq = max(cnt.values())
    best = min(p for p, c in cnt.items() if c == best_freq)
    return [best[0], best[1]]

class Solution {
    public String[] mostCommonProductPair(String[][] transactions) {
        java.util.HashMap<String, Integer> cnt = new java.util.HashMap<>();
        for (String[] tr : transactions) {
            java.util.TreeSet<String> set = new java.util.TreeSet<>(java.util.Arrays.asList(tr));
            String[] items = set.toArray(new String[0]);
            for (int i = 0; i < items.length; i++)
                for (int j = i + 1; j < items.length; j++)
                    cnt.merge(items[i] + "|" + items[j], 1, Integer::sum);
        }
        if (cnt.isEmpty()) return new String[0];
        int best = cnt.values().stream().max(Integer::compare).get();
        String bestKey = null;
        for (var e : cnt.entrySet()) if (e.getValue() == best && (bestKey == null || e.getKey().compareTo(bestKey) < 0)) bestKey = e.getKey();
        return bestKey.split("\\|");
    }
}

class Solution {
public:
    vector<string> mostCommonProductPair(vector<vector<string>>& transactions) {
        map<pair<string,string>, int> cnt;
        for (auto& tr : transactions) {
            set<string> s(tr.begin(), tr.end());
            vector<string> items(s.begin(), s.end());
            for (int i = 0; i < (int)items.size(); i++)
                for (int j = i + 1; j < (int)items.size(); j++)
                    cnt[{items[i], items[j]}]++;
        }
        if (cnt.empty()) return {};
        int best = 0;
        for (auto& [k, v] : cnt) best = max(best, v);
        for (auto& [k, v] : cnt) if (v == best) return {k.first, k.second};
        return {};
    }
};

def nextGreaterPerfectString(s):
    arr = list(s)
    n = len(arr)
    for i in range(n - 1, -1, -1):
        # try to increase arr[i]
        for c in range(ord(arr[i]) + 1, ord('z') + 1):
            if i > 0 and c == ord(arr[i-1]):
                continue
            arr[i] = chr(c)
            # fill the rest with smallest perfect chars
            for k in range(i + 1, n):
                for cc in range(ord('a'), ord('z') + 1):
                    if cc != ord(arr[k-1]):
                        arr[k] = chr(cc)
                        break
            return ''.join(arr)
        # restore: nothing to restore, we just continue
    return "-1"

class Solution {
    public String nextGreaterPerfectString(String s) {
        char[] a = s.toCharArray();
        int n = a.length;
        for (int i = n - 1; i >= 0; i--) {
            for (char c = (char)(a[i] + 1); c <= 'z'; c++) {
                if (i > 0 && c == a[i-1]) continue;
                a[i] = c;
                for (int k = i + 1; k < n; k++) {
                    for (char cc = 'a'; cc <= 'z'; cc++) {
                        if (cc != a[k-1]) { a[k] = cc; break; }
                    }
                }
                return new String(a);
            }
        }
        return "-1";
    }
}

