        int n = s.size();
        for (int i = n - 1; i >= 0; i--) {
            for (char c = s[i] + 1; c <= 'z'; c++) {
                if (i > 0 && c == s[i-1]) continue;
                s[i] = c;
                for (int k = i + 1; k < n; k++) {
                    for (char cc = 'a'; cc <= 'z'; cc++) {
                        if (cc != s[k-1]) { s[k] = cc; break; }
                    }
                }
                return s;
            }
        }
        return "-1";
    }
};

