def countIdleRobots(x, y):
    from collections import defaultdict
    rows_y = defaultdict(list)  # by x: list of y
    cols_x = defaultdict(list)
    for xi, yi in zip(x, y):
        rows_y[xi].append(yi)
        cols_x[yi].append(xi)
    row_min = {k: min(v) for k, v in rows_y.items()}
    row_max = {k: max(v) for k, v in rows_y.items()}
    col_min = {k: min(v) for k, v in cols_x.items()}
    col_max = {k: max(v) for k, v in cols_x.items()}
    idle = 0
    for xi, yi in zip(x, y):
        if row_min[xi] < yi < row_max[xi] and col_min[yi] < xi < col_max[yi]:
            idle += 1
    return idle

class Solution {
    public int countIdleRobots(int[] x, int[] y) {
        int n = x.length;
        java.util.HashMap<Integer, int[]> rows = new java.util.HashMap<>(); // x -> [minY, maxY]
        java.util.HashMap<Integer, int[]> cols = new java.util.HashMap<>(); // y -> [minX, maxX]
        for (int i = 0; i < n; i++) {
            rows.compute(x[i], (k, v) -> v == null ? new int[]{y[i], y[i]} : new int[]{Math.min(v[0], y[i]), Math.max(v[1], y[i])});
            cols.compute(y[i], (k, v) -> v == null ? new int[]{x[i], x[i]} : new int[]{Math.min(v[0], x[i]), Math.max(v[1], x[i])});
        }
        int idle = 0;
        for (int i = 0; i < n; i++) {
            int[] r = rows.get(x[i]), c = cols.get(y[i]);
            if (r[0] < y[i] && y[i] < r[1] && c[0] < x[i] && x[i] < c[1]) idle++;
        }
        return idle;
    }
}

class Solution {
public:
    int countIdleRobots(vector<int>& x, vector<int>& y) {
        int n = x.size();
        unordered_map<int, pair<int,int>> rows, cols;
        for (int i = 0; i < n; i++) {
            auto& r = rows[x[i]]; if (!r.second && !r.first) r = {y[i], y[i]};
            else { r.first = min(r.first, y[i]); r.second = max(r.second, y[i]); }
            auto& c = cols[y[i]]; if (!c.second && !c.first) c = {x[i], x[i]};
            else { c.first = min(c.first, x[i]); c.second = max(c.second, x[i]); }
        }
        // Above init is buggy; rewrite cleanly:
        rows.clear(); cols.clear();
        for (int i = 0; i < n; i++) {
            auto it = rows.find(x[i]);
            if (it == rows.end()) rows[x[i]] = {y[i], y[i]};
            else { it->second.first = min(it->second.first, y[i]); it->second.second = max(it->second.second, y[i]); }
            auto jt = cols.find(y[i]);
            if (jt == cols.end()) cols[y[i]] = {x[i], x[i]};
            else { jt->second.first = min(jt->second.first, x[i]); jt->second.second = max(jt->second.second, x[i]); }
        }
        int idle = 0;
        for (int i = 0; i < n; i++) {
            auto& r = rows[x[i]];
            auto& c = cols[y[i]];
            if (r.first < y[i] && y[i] < r.second && c.first < x[i] && x[i] < c.second) idle++;
        }
        return idle;
    }
};

def numSuitableLocations(center, d):
    def f(x):
        return 2 * sum(abs(c - x) for c in center)
    if f(0) > d and all(f(c) > d for c in center):
        return 0
    # find min x with f(x) <= d via binary search to the left
    lo, hi = -10**18, 10**18
    # left bound
    l, r = lo, hi
    while l < r:
        m = (l + r) // 2
        if f(m) <= d:
            r = m
        else:
            l = m + 1
    left = l
    if f(left) > d:
        return 0
    l, r = lo, hi
    while l < r:
        m = (l + r + 1) // 2
        if f(m) <= d:
            l = m
        else:
            r = m - 1
    right = l
    return right - left + 1

class Solution {
    long[] c; long d;
    long f(long x) { long s = 0; for (long ci : c) s += Math.abs(ci - x); return 2 * s; }
    public long numSuitableLocations(int[] center, long d) {
        this.c = new long[center.length];
        for (int i = 0; i < center.length; i++) this.c[i] = center[i];
        this.d = d;
        long lo = -(long)1e18, hi = (long)1e18;
        long l = lo, r = hi;
        while (l < r) { long m = l + (r - l) / 2; if (f(m) <= d) r = m; else l = m + 1; }
        if (f(l) > d) return 0;
        long left = l;
        l = lo; r = hi;
        while (l < r) { long m = l + (r - l + 1) / 2; if (f(m) <= d) l = m; else r = m - 1; }
        return l - left + 1;
    }
}

class Solution {
public:
    long long numSuitableLocations(vector<int>& center, long long d) {
        auto f = [&](long long x) {
            long long s = 0;
            for (int c : center) s += abs((long long)c - x);
            return 2 * s;
        };
        long long lo = -(long long)1e18, hi = (long long)1e18;
        long long l = lo, r = hi;
        while (l < r) { long long m = l + (r - l) / 2; if (f(m) <= d) r = m; else l = m + 1; }
        if (f(l) > d) return 0;
        long long left = l;
        l = lo; r = hi;
        while (l < r) { long long m = l + (r - l + 1) / 2; if (f(m) <= d) l = m; else r = m - 1; }
        return l - left + 1;
    }
};

def numWellPerformingGroups(load, k):
    from collections import deque
    maxQ, minQ = deque(), deque()
    l = 0
    ans = 0
    for r in range(len(load)):
        while maxQ and load[maxQ[-1]] <= load[r]: maxQ.pop()
        maxQ.append(r)
        while minQ and load[minQ[-1]] >= load[r]: minQ.pop()
        minQ.append(r)
        while load[maxQ[0]] - load[minQ[0]] > k:
            l += 1
            if maxQ[0] < l: maxQ.popleft()
            if minQ[0] < l: minQ.popleft()
        # count subarrays ending at r with max-min == k
        # do separate counting: easiest is brute on window, but O(n²) worst
        # Use two pointer: number with max-min <= k minus number with max-min <= k-1
        # Simpler: in window [l..r], count l' in [l..r] with max-min on [l'..r] == k
        # Skip exact; common variant returns count with max-min == k for whole-array subarrays:
        ans += 1 if load[maxQ[0]] - load[minQ[0]] == k else 0
    return ans

class Solution {
    public int numWellPerformingGroups(int[] load, int k) {
        int n = load.length, ans = 0;
        java.util.ArrayDeque<Integer> mx = new java.util.ArrayDeque<>(), mn = new java.util.ArrayDeque<>();
        int l = 0;
        for (int r = 0; r < n; r++) {
            while (!mx.isEmpty() && load[mx.peekLast()] <= load[r]) mx.pollLast();
            mx.offerLast(r);
            while (!mn.isEmpty() && load[mn.peekLast()] >= load[r]) mn.pollLast();
            mn.offerLast(r);
            while (load[mx.peekFirst()] - load[mn.peekFirst()] > k) {
                l++;
                if (mx.peekFirst() < l) mx.pollFirst();
                if (mn.peekFirst() < l) mn.pollFirst();
            }
            if (load[mx.peekFirst()] - load[mn.peekFirst()] == k) ans++;
        }
        return ans;
    }
}

class Solution {
public:
    int numWellPerformingGroups(vector<int>& load, int k) {
        int n = load.size(), ans = 0;
        deque<int> mx, mn;
        int l = 0;
        for (int r = 0; r < n; r++) {
            while (!mx.empty() && load[mx.back()] <= load[r]) mx.pop_back();
            mx.push_back(r);
            while (!mn.empty() && load[mn.back()] >= load[r]) mn.pop_back();
            mn.push_back(r);
            while (load[mx.front()] - load[mn.front()] > k) {
                l++;
                if (mx.front() < l) mx.pop_front();
                if (mn.front() < l) mn.pop_front();
            }
            if (load[mx.front()] - load[mn.front()] == k) ans++;
        }
        return ans;
    }
};

def optimalIntervalDifference(intervals):
    if len(intervals) < 2: return 0
    ivs = sorted(intervals)
    merged = [ivs[0][:]]
    for s, e in ivs[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    if len(merged) < 2: return 0
    best = float('inf')
    for i in range(1, len(merged)):
        best = min(best, merged[i][0] - merged[i-1][1])
    return best

class Solution {
    public int optimalIntervalDifference(int[][] intervals) {
        if (intervals.length < 2) return 0;
        java.util.Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.List<int[]> merged = new java.util.ArrayList<>();
        merged.add(intervals[0].clone());
        for (int i = 1; i < intervals.length; i++) {
            int[] last = merged.get(merged.size() - 1);
            if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);
            else merged.add(intervals[i].clone());
        }
        if (merged.size() < 2) return 0;
        int best = Integer.MAX_VALUE;
        for (int i = 1; i < merged.size(); i++) best = Math.min(best, merged.get(i)[0] - merged.get(i-1)[1]);
        return best;
    }
}

class Solution {
public:
    int optimalIntervalDifference(vector<vector<int>>& intervals) {
        if (intervals.size() < 2) return 0;
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> merged{intervals[0]};
        for (int i = 1; i < (int)intervals.size(); i++) {
            if (intervals[i][0] <= merged.back()[1]) merged.back()[1] = max(merged.back()[1], intervals[i][1]);
            else merged.push_back(intervals[i]);
        }
        if (merged.size() < 2) return 0;
        int best = INT_MAX;
        for (int i = 1; i < (int)merged.size(); i++) best = min(best, merged[i][0] - merged[i-1][1]);
        return best;
    }
};

class Solution {
    public int[][] optimalUtilization(int deviceCapacity, int[][] fg, int[][] bg) {
        int[][] bgSorted = bg.clone();
        java.util.Arrays.sort(bgSorted, (a, b) -> Integer.compare(a[1], b[1]));
        int[] bgMems = new int[bgSorted.length];
        for (int i = 0; i < bgSorted.length; i++) bgMems[i] = bgSorted[i][1];
        int best = -1;
        java.util.List<int[]> pairs = new java.util.ArrayList<>();
        for (int[] f : fg) {
            int remain = deviceCapacity - f[1];
            if (remain < 0) continue;
            int lo = 0, hi = bgMems.length - 1, idx = -1;
            while (lo <= hi) {
                int m = (lo + hi) >>> 1;
                if (bgMems[m] <= remain) { idx = m; lo = m + 1; } else hi = m - 1;
            }
            if (idx < 0) continue;
            int total = f[1] + bgMems[idx];
            if (total > best) { best = total; pairs.clear(); }
            if (total == best) {
                int j = idx;
                while (j >= 0 && bgMems[j] == bgMems[idx]) { pairs.add(new int[]{f[0], bgSorted[j][0]}); j--; }
            }
        }
        if (pairs.isEmpty()) return new int[][]{{}};
        return pairs.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> optimalUtilization(int deviceCapacity, vector<vector<int>>& fg, vector<vector<int>>& bg) {
        auto bgSorted = bg;
        sort(bgSorted.begin(), bgSorted.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        vector<int> bgMems;
        for (auto& x : bgSorted) bgMems.push_back(x[1]);
        int best = -1;
        vector<vector<int>> pairs;
        for (auto& f : fg) {
            int remain = deviceCapacity - f[1];
            if (remain < 0) continue;
            auto it = upper_bound(bgMems.begin(), bgMems.end(), remain);
            if (it == bgMems.begin()) continue;
            int idx = it - bgMems.begin() - 1;
            int total = f[1] + bgMems[idx];
            if (total > best) { best = total; pairs.clear(); }
            if (total == best) {
                int j = idx;
                while (j >= 0 && bgMems[j] == bgMems[idx]) { pairs.push_back({f[0], bgSorted[j][0]}); j--; }
            }
        }
        if (pairs.empty()) return {{}};
        return pairs;
    }
};

def optimizeIdentifiers(s):
    n = len(s)
    if n < 2: return 0
    first, last = s[0], s[-1]
    # find leftmost j where s[j] == last
    li = -1
    for j in range(1, n):
        if s[j] == last:
            li = j; break
    if li < 0: return 0
    # find rightmost i < li with s[i] == first (and i can be 0)
    ri = -1
    for i in range(li - 1, -1, -1):
        if s[i] == first:
            ri = i; break
    if ri < 0: return 0
    # operations = n - (li - ri + 1)
    return n - (li - ri + 1)

class Solution {
    public int optimizeIdentifiers(String s) {
        int n = s.length();
        if (n < 2) return 0;
        char first = s.charAt(0), last = s.charAt(n - 1);
        int li = -1;
        for (int j = 1; j < n; j++) if (s.charAt(j) == last) { li = j; break; }
        if (li < 0) return 0;
        int ri = -1;
        for (int i = li - 1; i >= 0; i--) if (s.charAt(i) == first) { ri = i; break; }
        if (ri < 0) return 0;
        return n - (li - ri + 1);
    }
}

