    }
};

class Solution {
    public int optimizedIdentifiers(String s) {
        int n = s.length();
        if (n < 2) return 0;
        char first = s.charAt(0), last = s.charAt(n - 1);
        int bestKeep = n;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) != first) continue;
            for (int j = i; j < n; j++) {
                if (s.charAt(j) == last) { bestKeep = Math.min(bestKeep, j - i + 1); break; }
            }
        }
        return n - bestKeep;
    }
}

class Solution {
