        for (int i = 0; i < n; i++) {
            if (s[i] != first) continue;
            for (int j = i; j < n; j++) if (s[j] == last) { bestKeep = min(bestKeep, j - i + 1); break; }
        }
        return n - bestKeep;
    }
};

class Solution {
    public String[] orderLayout(String layout) {
        String[] parts = layout.split("\\|");
        int n = parts.length;
        java.util.HashMap<Integer, String> seen = new java.util.HashMap<>();
        for (String p : parts) {
            if (p.length() < 5) return new String[]{"Invalid configuration"};
            String idxS = p.substring(0, 4), val = p.substring(4);
            if (!idxS.matches("\\d{4}") || !val.matches("[A-Za-z0-9]+")) return new String[]{"Invalid configuration"};
            int idx = Integer.parseInt(idxS);
            if (seen.containsKey(idx)) return new String[]{"Invalid configuration"};
            seen.put(idx, val);
        }
        String[] res = new String[n];
        for (int i = 1; i <= n; i++) {
            if (!seen.containsKey(i)) return new String[]{"Invalid configuration"};
            res[i - 1] = seen.get(i);
        }
        return res;
    }
}

class Solution {
public:
    vector<string> orderLayout(string layout) {
        vector<string> parts;
        string cur;
        for (char c : layout) { if (c == '|') { parts.push_back(cur); cur.clear(); } else cur += c; }
        parts.push_back(cur);
        int n = parts.size();
        map<int, string> seen;
        for (auto& p : parts) {
            if (p.size() < 5) return {"Invalid configuration"};
            string idxS = p.substr(0, 4), val = p.substr(4);
            for (char c : idxS) if (!isdigit(c)) return {"Invalid configuration"};
            for (char c : val) if (!isalnum(c)) return {"Invalid configuration"};
            int idx = stoi(idxS);
            if (seen.count(idx)) return {"Invalid configuration"};
            seen[idx] = val;
        }
        vector<string> res;
        for (int i = 1; i <= n; i++) {
            if (!seen.count(i)) return {"Invalid configuration"};
            res.push_back(seen[i]);
        }
        return res;
    }
};

def packItems(arr):
    a = sorted(arr)
    total = sum(a)
    sumA = 0
    A = []
    for x in reversed(a):
        A.append(x)
        sumA += x
        if sumA > total - sumA:
            break
    return sorted(A)

class Solution {
    public int[] packItems(int[] arr) {
        int[] a = arr.clone();
        java.util.Arrays.sort(a);
        long total = 0;
        for (int x : a) total += x;
        long sumA = 0;
        java.util.List<Integer> A = new java.util.ArrayList<>();
        for (int i = a.length - 1; i >= 0; i--) {
            A.add(a[i]);
            sumA += a[i];
            if (sumA > total - sumA) break;
        }
        java.util.Collections.sort(A);
        return A.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> packItems(vector<int>& arr) {
        vector<int> a = arr;
        sort(a.begin(), a.end());
        long long total = 0;
        for (int x : a) total += x;
        long long sumA = 0;
        vector<int> A;
        for (int i = a.size() - 1; i >= 0; i--) {
            A.push_back(a[i]);
            sumA += a[i];
            if (sumA > total - sumA) break;
        }
        sort(A.begin(), A.end());
        return A;
    }
};

def packageDeliverySystem(truckCapacities, packageWeights):
    res = []
    for trucks, pkgs in zip(truckCapacities, packageWeights):
        caps = sorted(trucks, reverse=True)
        ps = sorted(pkgs, reverse=True)
        feasible = True
        i = 0  # truck index
        for w in ps:
            while i < len(caps) and caps[i] < w:
                i += 1
            if i >= len(caps):
                feasible = False; break
            caps[i] -= w
            # re-sort small section
            j = i
            while j + 1 < len(caps) and caps[j] < caps[j+1]:
                caps[j], caps[j+1] = caps[j+1], caps[j]
                j += 1
        res.append(1 if feasible else 0)
    return res

class Solution {
    public int[] packageDeliverySystem(int[][] truckCapacities, int[][] packageWeights) {
        int[] res = new int[truckCapacities.length];
        for (int s = 0; s < truckCapacities.length; s++) {
            java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
            for (int c : truckCapacities[s]) pq.offer(c);
            Integer[] pkgs = java.util.stream.IntStream.of(packageWeights[s]).boxed().toArray(Integer[]::new);
            java.util.Arrays.sort(pkgs, java.util.Collections.reverseOrder());
            boolean ok = true;
            for (int w : pkgs) {
                if (pq.isEmpty() || pq.peek() < w) { ok = false; break; }
                int c = pq.poll();
                pq.offer(c - w);
            }
            res[s] = ok ? 1 : 0;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> packageDeliverySystem(vector<vector<int>>& trucks, vector<vector<int>>& pkgs) {
        vector<int> res;
        for (int s = 0; s < (int)trucks.size(); s++) {
            priority_queue<int> pq(trucks[s].begin(), trucks[s].end());
            vector<int> p = pkgs[s];
            sort(p.begin(), p.end(), greater<int>());
            bool ok = true;
            for (int w : p) {
                if (pq.empty() || pq.top() < w) { ok = false; break; }
                int c = pq.top(); pq.pop();
                pq.push(c - w);
            }
            res.push_back(ok ? 1 : 0);
        }
        return res;
    }
};

