def performQueries(queries):
    from collections import deque
    q = deque()
    out = []
    for op, arg in queries:
        if op == "INSERT":
            q.append(arg)
        else:  # SHIP
            if len(q) >= 3:
                out.append([q.popleft(), q.popleft(), q.popleft()])
            else:
                out.append(["N/A"])
    return out

class Solution {
    public java.util.List<java.util.List<String>> performQueries(java.util.List<java.util.List<String>> queries) {
        java.util.ArrayDeque<String> q = new java.util.ArrayDeque<>();
        java.util.List<java.util.List<String>> out = new java.util.ArrayList<>();
        for (var qry : queries) {
            if (qry.get(0).equals("INSERT")) q.offer(qry.get(1));
            else {
                if (q.size() >= 3) {
                    java.util.List<String> g = new java.util.ArrayList<>();
                    for (int i = 0; i < 3; i++) g.add(q.poll());
                    out.add(g);
                } else out.add(java.util.List.of("N/A"));
            }
        }
        return out;
    }
}

class Solution {
public:
    vector<vector<string>> performQueries(vector<vector<string>>& queries) {
        deque<string> q;
        vector<vector<string>> out;
        for (auto& qry : queries) {
            if (qry[0] == "INSERT") q.push_back(qry[1]);
            else {
                if (q.size() >= 3) {
                    vector<string> g{q.front()}; q.pop_front();
                    g.push_back(q.front()); q.pop_front();
                    g.push_back(q.front()); q.pop_front();
                    out.push_back(g);
                } else out.push_back({"N/A"});
            }
        }
        return out;
    }
};

class Solution {
    public int[] predictAnswer(int[] stockData, int[] queries) {
        int n = stockData.length;
        int[] left = new int[n], right = new int[n];
        java.util.Arrays.fill(left, -1); java.util.Arrays.fill(right, -1);
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && stockData[st.peek()] >= stockData[i]) st.pop();
            if (!st.isEmpty()) left[i] = st.peek();
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && stockData[st.peek()] >= stockData[i]) st.pop();
            if (!st.isEmpty()) right[i] = st.peek();
            st.push(i);
        }
        int[] nearest = new int[n];
        for (int i = 0; i < n; i++) {
            int l = left[i], r = right[i];
            if (l == -1 && r == -1) nearest[i] = -1;
            else if (l == -1) nearest[i] = r + 1;
            else if (r == -1) nearest[i] = l + 1;
            else nearest[i] = (i - l <= r - i) ? l + 1 : r + 1;
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) ans[i] = nearest[queries[i] - 1];
        return ans;
    }
}

class Solution {
public:
    vector<int> predictAnswer(vector<int>& stockData, vector<int>& queries) {
        int n = stockData.size();
        vector<int> left(n, -1), right(n, -1);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && stockData[st.top()] >= stockData[i]) st.pop();
            if (!st.empty()) left[i] = st.top();
            st.push(i);
        }
        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && stockData[st.top()] >= stockData[i]) st.pop();
            if (!st.empty()) right[i] = st.top();
            st.push(i);
        }
        vector<int> nearest(n);
        for (int i = 0; i < n; i++) {
            int l = left[i], r = right[i];
            if (l == -1 && r == -1) nearest[i] = -1;
            else if (l == -1) nearest[i] = r + 1;
            else if (r == -1) nearest[i] = l + 1;
            else nearest[i] = (i - l <= r - i) ? l + 1 : r + 1;
        }
        vector<int> ans;
        for (int q : queries) ans.push_back(nearest[q - 1]);
        return ans;
    }
};

class Solution {
    public long[][] processExecution(int[] power, int[] minPower, int[] maxPower) {
        int[] p = power.clone();
        java.util.Arrays.sort(p);
        long[] pref = new long[p.length + 1];
        for (int i = 0; i < p.length; i++) pref[i + 1] = pref[i] + p[i];
        int m = minPower.length;
        long[][] res = new long[m][2];
        for (int j = 0; j < m; j++) {
            int lo = lowerBound(p, minPower[j]);
            int hi = upperBound(p, maxPower[j]);
            res[j][0] = hi - lo;
            res[j][1] = pref[hi] - pref[lo];
        }
        return res;
    }
    int lowerBound(int[] a, int v) { int l = 0, r = a.length; while (l < r) { int m = (l + r) >>> 1; if (a[m] < v) l = m + 1; else r = m; } return l; }
    int upperBound(int[] a, int v) { int l = 0, r = a.length; while (l < r) { int m = (l + r) >>> 1; if (a[m] <= v) l = m + 1; else r = m; } return l; }
}

class Solution {
public:
    vector<vector<long long>> processExecution(vector<int>& power, vector<int>& minPower, vector<int>& maxPower) {
        vector<int> p = power;
        sort(p.begin(), p.end());
        vector<long long> pref(p.size() + 1, 0);
        for (int i = 0; i < (int)p.size(); i++) pref[i + 1] = pref[i] + p[i];
        vector<vector<long long>> res;
        for (int j = 0; j < (int)minPower.size(); j++) {
            int lo = lower_bound(p.begin(), p.end(), minPower[j]) - p.begin();
            int hi = upper_bound(p.begin(), p.end(), maxPower[j]) - p.begin();
            res.push_back({hi - lo, pref[hi] - pref[lo]});
        }
        return res;
    }
};

class Solution {
    public int[] processQueriesOnCart(int[] items, int[] query) {
        java.util.LinkedHashMap<Integer, Integer> ids = new java.util.LinkedHashMap<>();
        java.util.HashMap<Integer, java.util.ArrayDeque<Integer>> idsByVal = new java.util.HashMap<>();
        int[] cnt = {0};
        java.util.function.IntConsumer add = v -> {
            int id = cnt[0]++;
            ids.put(id, v);
            idsByVal.computeIfAbsent(v, k -> new java.util.ArrayDeque<>()).offer(id);
        };
        for (int v : items) add.accept(v);
        for (int q : query) {
            if (q > 0) add.accept(q);
            else {
                int v = -q;
                var dq = idsByVal.get(v);
                if (dq != null && !dq.isEmpty()) {
                    int id = dq.poll();
                    ids.remove(id);
                }
            }
        }
        int[] res = new int[ids.size()];
