        for (int v : ids.values()) res[i++] = v;
        return res;
    }
}

class Solution {
public:
    vector<int> processQueriesOnCart(vector<int>& items, vector<int>& query) {
        list<int> lst;
        unordered_map<int, queue<list<int>::iterator>> byVal;
        auto add = [&](int v) {
            lst.push_back(v);
            auto it = prev(lst.end());
            byVal[v].push(it);
        };
        for (int v : items) add(v);
        for (int q : query) {
            if (q > 0) add(q);
            else {
                int v = -q;
                auto& dq = byVal[v];
                if (!dq.empty()) { lst.erase(dq.front()); dq.pop(); }
            }
        }
        return vector<int>(lst.begin(), lst.end());
    }
};

class Solution {
    public int[] processQueue(int[] wait) {
        java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
        for (int i = 0; i < wait.length; i++) q.offer(new int[]{i, wait[i]});
        java.util.List<Integer> res = new java.util.ArrayList<>();
        int t = 0;
        while (!q.isEmpty()) {
            q.poll();
            while (!q.isEmpty() && q.peek()[1] <= t) q.poll();
            res.add(q.size());
            t++;
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> processQueue(vector<int>& wait) {
        deque<pair<int,int>> q;
        for (int i = 0; i < (int)wait.size(); i++) q.push_back({i, wait[i]});
        vector<int> res;
        int t = 0;
        while (!q.empty()) {
            q.pop_front();
            while (!q.empty() && q.front().second <= t) q.pop_front();
            res.push_back(q.size());
            t++;
        }
        return res;
    }
};

def productCategoryGroupSizes(products, pairs):
    parent = {p: p for p in products}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    for a, b in pairs:
        union(a, b)
    from collections import Counter
    sizes = Counter(find(p) for p in products)
    return sorted(sizes.values())

class Solution {
    java.util.HashMap<String, String> par = new java.util.HashMap<>();
    String find(String x) {
        while (!par.get(x).equals(x)) { par.put(x, par.get(par.get(x))); x = par.get(x); }
        return x;
    }
    public int[] productCategoryGroupSizes(String[] products, String[][] pairs) {
        for (String p : products) par.put(p, p);
        for (String[] e : pairs) {
            String ra = find(e[0]), rb = find(e[1]);
            if (!ra.equals(rb)) par.put(ra, rb);
        }
        java.util.HashMap<String, Integer> sz = new java.util.HashMap<>();
        for (String p : products) sz.merge(find(p), 1, Integer::sum);
        return sz.values().stream().mapToInt(Integer::intValue).sorted().toArray();
    }
}

