def minCostToPurchaseServers(power, cost, target):
    totalCost = sum(cost)
    INF = -1
    dp = [0] * (totalCost + 1)
    for i in range(len(power)):
        c = cost[i]; p = power[i]
        for j in range(totalCost, c - 1, -1):
            dp[j] = max(dp[j], dp[j - c] + p)
    for j in range(totalCost + 1):
        if dp[j] >= target:
            return j
    return -1

class Solution {
    public int minCostToPurchaseServers(int[] power, int[] cost, int target) {
        int total = 0;
        for (int c : cost) total += c;
        int[] dp = new int[total + 1];
        for (int i = 0; i < power.length; i++) {
            int c = cost[i], p = power[i];
            for (int j = total; j >= c; j--) dp[j] = Math.max(dp[j], dp[j - c] + p);
        }
        for (int j = 0; j <= total; j++) if (dp[j] >= target) return j;
        return -1;
    }
}

