        for (int j = 0; j <= total; j++) if (dp[j] >= target) return j;
        return -1;
    }
};

def canRearrangeBinaryString(binary, arr):
    ones = binary.count('1')
    res = []
    for t in arr:
        ones_t = t.count('1')
        qs = t.count('?')
        if ones_t <= ones <= ones_t + qs:
            res.append("YES")
        else:
            res.append("NO")
    return res

class Solution {
    public String[] canRearrangeBinaryString(String binary, String[] arr) {
        int ones = 0;
        for (char c : binary.toCharArray()) if (c == '1') ones++;
        String[] res = new String[arr.length];
        for (int i = 0; i < arr.length; i++) {
            int ot = 0, qs = 0;
            for (char c : arr[i].toCharArray()) { if (c == '1') ot++; else if (c == '?') qs++; }
            res[i] = (ot <= ones && ones <= ot + qs) ? "YES" : "NO";
        }
        return res;
    }
}

class Solution {
public:
    vector<string> canRearrangeBinaryString(string binary, vector<string>& arr) {
        int ones = count(binary.begin(), binary.end(), '1');
        vector<string> res;
        for (auto& t : arr) {
            int ot = count(t.begin(), t.end(), '1');
            int qs = count(t.begin(), t.end(), '?');
            res.push_back((ot <= ones && ones <= ot + qs) ? "YES" : "NO");
        }
        return res;
    }
};

class Solution {
    public int reduceMemoryUsage(int[] processes, int m) {
        int total = 0; for (int x : processes) total += x;
        int cur = 0;
        for (int i = 0; i < m; i++) cur += processes[i];
        int best = cur;
        for (int i = m; i < processes.length; i++) { cur += processes[i] - processes[i - m]; best = Math.max(best, cur); }
        return total - best;
    }
}

class Solution {
public:
