        int total = 0; for (int x : processes) total += x;
        int cur = 0;
        for (int i = 0; i < m; i++) cur += processes[i];
        int best = cur;
        for (int i = m; i < (int)processes.size(); i++) { cur += processes[i] - processes[i - m]; best = max(best, cur); }
        return total - best;
    }
};

def signInPages(requests):
    users = {}
    logged = set()
    out = []
    for r in requests:
        parts = r.split()
        op = parts[0]
        if op == "register":
            u, p = parts[1], parts[2]
            if u in users: out.append("Username already exists")
            else: users[u] = p; out.append("Registered Successfully")
        elif op == "login":
            u, p = parts[1], parts[2]
            if u not in users or users[u] != p: out.append("Login Unsuccessful")
            elif u in logged: out.append("Login Unsuccessful")
            else: logged.add(u); out.append("Logged In Successfully")
        else:  # logout
            u = parts[1]
            if u in logged: logged.remove(u); out.append("Logged Out Successfully")
            else: out.append("Logout Unsuccessful")
    return out

class Solution {
    public String[] signInPages(String[] requests) {
        java.util.HashMap<String, String> users = new java.util.HashMap<>();
        java.util.HashSet<String> logged = new java.util.HashSet<>();
        String[] out = new String[requests.length];
        for (int i = 0; i < requests.length; i++) {
            String[] parts = requests[i].split(" ");
            String op = parts[0];
            if (op.equals("register")) {
                if (users.containsKey(parts[1])) out[i] = "Username already exists";
                else { users.put(parts[1], parts[2]); out[i] = "Registered Successfully"; }
            } else if (op.equals("login")) {
                if (!users.containsKey(parts[1]) || !users.get(parts[1]).equals(parts[2]) || logged.contains(parts[1])) out[i] = "Login Unsuccessful";
                else { logged.add(parts[1]); out[i] = "Logged In Successfully"; }
            } else {
                if (logged.remove(parts[1])) out[i] = "Logged Out Successfully";
                else out[i] = "Logout Unsuccessful";
            }
        }
        return out;
    }
}

