class Solution {
    public int findReviewScore(String review, String[] prohibitedWords) {
        String s = review.toLowerCase();
        int n = s.length();
        int[] events = new int[n + 1];
        for (String w : prohibitedWords) {
            String wl = w.toLowerCase();
            int idx = 0;
            while (true) {
                int j = s.indexOf(wl, idx);
                if (j < 0) break;
                int end = j + wl.length();
                events[end - 1] = Math.max(events[end - 1], j + 1);
                idx = j + 1;
            }
        }
        int best = 0, l = 0;
        for (int r = 0; r < n; r++) {
            if (events[r] > l) l = events[r];
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

class Solution {
public:
    int findReviewScore(string review, vector<string>& prohibitedWords) {
        string s = review;
        for (auto& c : s) c = tolower(c);
        int n = s.size();
        vector<int> events(n + 1, 0);
        for (auto w : prohibitedWords) {
            for (auto& c : w) c = tolower(c);
            size_t idx = 0;
            while (true) {
                size_t j = s.find(w, idx);
                if (j == string::npos) break;
                int end = j + w.size();
                events[end - 1] = max(events[end - 1], (int)j + 1);
                idx = j + 1;
            }
        }
        int best = 0, l = 0;
        for (int r = 0; r < n; r++) {
            if (events[r] > l) l = events[r];
            best = max(best, r - l + 1);
        }
        return best;
    }
};

def minRooksLeft(board):
    R, C = len(board), len(board[0])
    rooks = []
    for i in range(R):
        for j in range(C):
            if board[i][j] == 1:
                rooks.append((i, j))
    if not rooks: return 0
    parent = list(range(len(rooks)))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    by_row = {}
    by_col = {}
    for idx, (i, j) in enumerate(rooks):
        by_row.setdefault(i, []).append(idx)
        by_col.setdefault(j, []).append(idx)
    for group in list(by_row.values()) + list(by_col.values()):
        for k in range(1, len(group)):
            union(group[0], group[k])
    return len(set(find(i) for i in range(len(rooks))))

class Solution {
    int[] par;
    int find(int x) { while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; } return x; }
    public int minRooksLeft(int[][] board) {
        int R = board.length, C = board[0].length;
        java.util.List<int[]> rs = new java.util.ArrayList<>();
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) if (board[i][j] == 1) rs.add(new int[]{i, j});
        if (rs.isEmpty()) return 0;
        par = new int[rs.size()];
        for (int i = 0; i < par.length; i++) par[i] = i;
        java.util.HashMap<Integer, java.util.List<Integer>> byRow = new java.util.HashMap<>(), byCol = new java.util.HashMap<>();
        for (int idx = 0; idx < rs.size(); idx++) {
            byRow.computeIfAbsent(rs.get(idx)[0], k -> new java.util.ArrayList<>()).add(idx);
            byCol.computeIfAbsent(rs.get(idx)[1], k -> new java.util.ArrayList<>()).add(idx);
        }
        for (var g : byRow.values()) for (int k = 1; k < g.size(); k++) { int a = find(g.get(0)), b = find(g.get(k)); if (a != b) par[a] = b; }
        for (var g : byCol.values()) for (int k = 1; k < g.size(); k++) { int a = find(g.get(0)), b = find(g.get(k)); if (a != b) par[a] = b; }
        java.util.HashSet<Integer> roots = new java.util.HashSet<>();
        for (int i = 0; i < par.length; i++) roots.add(find(i));
        return roots.size();
    }
}

class Solution {
public:
    vector<int> par;
    int find(int x) { while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; } return x; }
    int minRooksLeft(vector<vector<int>>& board) {
        int R = board.size(), C = board[0].size();
        vector<pair<int,int>> rs;
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) if (board[i][j] == 1) rs.push_back({i, j});
        if (rs.empty()) return 0;
        par.resize(rs.size());
        iota(par.begin(), par.end(), 0);
        unordered_map<int, vector<int>> byRow, byCol;
        for (int idx = 0; idx < (int)rs.size(); idx++) { byRow[rs[idx].first].push_back(idx); byCol[rs[idx].second].push_back(idx); }
        for (auto& [k, g] : byRow) for (int t = 1; t < (int)g.size(); t++) { int a = find(g[0]), b = find(g[t]); if (a != b) par[a] = b; }
        for (auto& [k, g] : byCol) for (int t = 1; t < (int)g.size(); t++) { int a = find(g[0]), b = find(g[t]); if (a != b) par[a] = b; }
        set<int> roots;
        for (int i = 0; i < (int)par.size(); i++) roots.insert(find(i));
        return roots.size();
    }
};

class Solution {
    public int[] scheduleRequestsToServers(int servers, int[] requests) {
        int[] load = new int[servers];
        int[] res = new int[requests.length];
        for (int q = 0; q < requests.length; q++) {
            int upper = requests[q] > 0 ? requests[q] : servers;
            int bestId = 0, bestLoad = load[0];
            for (int i = 1; i < upper; i++) if (load[i] < bestLoad) { bestLoad = load[i]; bestId = i; }
            load[bestId]++;
            res[q] = bestId;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> scheduleRequestsToServers(int servers, vector<int>& requests) {
        vector<int> load(servers, 0), res;
        for (int r : requests) {
            int upper = r > 0 ? r : servers;
            int bestId = 0, bestLoad = load[0];
            for (int i = 1; i < upper; i++) if (load[i] < bestLoad) { bestLoad = load[i]; bestId = i; }
            load[bestId]++;
            res.push_back(bestId);
        }
        return res;
    }
};

def maximizeSecondaryTasksScheduling(primary, secondary, limit):
    p = sorted(primary)
    s = sorted(secondary)
    i = j = ans = 0
    while i < len(p) and j < len(s):
        if p[i] + s[j] <= limit:
            ans += 1
            i += 1; j += 1
        else:
            i += 1  # primary too big for current smallest secondary; skip primary
    return ans

class Solution {
    public int maximizeSecondaryTasksScheduling(int[] primary, int[] secondary, int limit) {
        int[] p = primary.clone(), s = secondary.clone();
        java.util.Arrays.sort(p); java.util.Arrays.sort(s);
        int i = 0, j = 0, ans = 0;
        while (i < p.length && j < s.length) {
            if (p[i] + s[j] <= limit) { ans++; i++; j++; }
            else i++;
        }
        return ans;
    }
}

