        int i = 0, j = 0, ans = 0;
        while (i < (int)p.size() && j < (int)s.size()) {
            if (p[i] + s[j] <= limit) { ans++; i++; j++; }
            else i++;
        }
        return ans;
    }
};

class Solution {
    public int serverSelection(int[] powers) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int v : powers) cnt.merge(v, 1, Integer::sum);
        int best = 0;
        for (int v : cnt.keySet()) best = Math.max(best, cnt.get(v) + cnt.getOrDefault(v + 1, 0));
        return best;
    }
}

class Solution {
public:
    int serverSelection(vector<int>& powers) {
        unordered_map<int, int> cnt;
        for (int v : powers) cnt[v]++;
        int best = 0;
        for (auto& [v, c] : cnt) {
            int t = c + (cnt.count(v + 1) ? cnt[v + 1] : 0);
            best = max(best, t);
        }
        return best;
    }
};

def similarTextSubstringCount(target, content):
    n, m = len(content), len(target)
    cnt = 0
    for i in range(n - m + 1):
        sub = content[i:i+m]
        diffs = [j for j in range(m) if sub[j] != target[j]]
        if not diffs:
            cnt += 1
        elif len(diffs) == 2 and diffs[1] == diffs[0] + 1 and sub[diffs[0]] == target[diffs[1]] and sub[diffs[1]] == target[diffs[0]]:
            cnt += 1
    return cnt

class Solution {
    public int similarTextSubstringCount(String target, String content) {
        int n = content.length(), m = target.length(), cnt = 0;
        for (int i = 0; i + m <= n; i++) {
            int d1 = -1, d2 = -1, total = 0;
            boolean fail = false;
            for (int j = 0; j < m && !fail; j++) {
                if (content.charAt(i + j) != target.charAt(j)) {
                    total++;
                    if (total == 1) d1 = j;
                    else if (total == 2) d2 = j;
                    else fail = true;
                }
            }
            if (fail) continue;
            if (total == 0) cnt++;
            else if (total == 2 && d2 == d1 + 1 && content.charAt(i + d1) == target.charAt(d2) && content.charAt(i + d2) == target.charAt(d1)) cnt++;
        }
        return cnt;
    }
}

