def sortErrorCodesByFrequency(codes):
    from collections import Counter
    cnt = Counter(codes)
    return sorted(codes, key=lambda x: (cnt[x], x))

class Solution {
    public int[] sortErrorCodesByFrequency(int[] codes) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int x : codes) cnt.merge(x, 1, Integer::sum);
        Integer[] boxed = java.util.stream.IntStream.of(codes).boxed().toArray(Integer[]::new);
        java.util.Arrays.sort(boxed, (a, b) -> { int c = Integer.compare(cnt.get(a), cnt.get(b)); return c != 0 ? c : Integer.compare(a, b); });
        return java.util.stream.Stream.of(boxed).mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> sortErrorCodesByFrequency(vector<int>& codes) {
        unordered_map<int, int> cnt;
        for (int x : codes) cnt[x]++;
        vector<int> res = codes;
        sort(res.begin(), res.end(), [&](int a, int b){
            if (cnt[a] != cnt[b]) return cnt[a] < cnt[b];
            return a < b;
        });
        return res;
    }
};

def sortProductCodes(order, productCodes):
    pri = {c: i for i, c in enumerate(order)}
    def key(s):
        return [pri[c] for c in s]
    return sorted(productCodes, key=key)

class Solution {
    public String[] sortProductCodes(String order, String[] productCodes) {
        int[] pri = new int[128];
        for (int i = 0; i < order.length(); i++) pri[order.charAt(i)] = i;
        String[] res = productCodes.clone();
        java.util.Arrays.sort(res, (a, b) -> {
            int n = Math.min(a.length(), b.length());
            for (int i = 0; i < n; i++) {
                int da = pri[a.charAt(i)], db = pri[b.charAt(i)];
                if (da != db) return da - db;
            }
            return a.length() - b.length();
        });
        return res;
    }
}

class Solution {
public:
    vector<string> sortProductCodes(string order, vector<string>& productCodes) {
        int pri[128] = {0};
        for (int i = 0; i < (int)order.size(); i++) pri[(int)order[i]] = i;
        vector<string> res = productCodes;
        sort(res.begin(), res.end(), [&](const string& a, const string& b){
            int n = min(a.size(), b.size());
            for (int i = 0; i < n; i++) if (pri[(int)a[i]] != pri[(int)b[i]]) return pri[(int)a[i]] < pri[(int)b[i]];
            return a.size() < b.size();
        });
        return res;
    }
};

def splitPrefixSuffix(categories, k):
    n = len(categories)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] | (1 << (ord(categories[i]) - ord('a')))
    suf = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf[i] = suf[i + 1] | (1 << (ord(categories[i]) - ord('a')))
    cnt = 0
    for i in range(1, n):
        if bin(pref[i] & suf[i]).count('1') > k:
            cnt += 1
    return cnt

class Solution {
    public int splitPrefixSuffix(String categories, int k) {
        int n = categories.length();
        int[] pref = new int[n + 1], suf = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] | (1 << (categories.charAt(i) - 'a'));
        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] | (1 << (categories.charAt(i) - 'a'));
        int cnt = 0;
        for (int i = 1; i < n; i++) if (Integer.bitCount(pref[i] & suf[i]) > k) cnt++;
        return cnt;
    }
}

class Solution {
public:
    int splitPrefixSuffix(string categories, int k) {
        int n = categories.size();
        vector<int> pref(n + 1, 0), suf(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] | (1 << (categories[i] - 'a'));
        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] | (1 << (categories[i] - 'a'));
        int cnt = 0;
        for (int i = 1; i < n; i++) if (__builtin_popcount(pref[i] & suf[i]) > k) cnt++;
        return cnt;
    }
};

class Solution {
    public long[] getSumAfterQueries(int[] data, int[][] queries) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        long s = 0;
        for (int x : data) { cnt.merge(x, 1, Integer::sum); s += x; }
        long[] res = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int old = queries[i][0], nv = queries[i][1];
            if (cnt.getOrDefault(old, 0) > 0 && old != nv) {
                int c = cnt.get(old);
                s += (long)c * (nv - old);
                cnt.put(old, 0);
                cnt.merge(nv, c, Integer::sum);
            }
            res[i] = s;
        }
        return res;
    }
}

class Solution {
public:
    vector<long long> getSumAfterQueries(vector<int>& data, vector<vector<int>>& queries) {
        unordered_map<int, int> cnt;
        long long s = 0;
        for (int x : data) { cnt[x]++; s += x; }
        vector<long long> res;
        for (auto& q : queries) {
            int oldV = q[0], nv = q[1];
            if (cnt[oldV] > 0 && oldV != nv) {
                int c = cnt[oldV];
                s += (long long)c * (nv - oldV);
                cnt[oldV] = 0;
                cnt[nv] += c;
            }
            res.push_back(s);
        }
        return res;
    }
};

class Solution {
    public long sumMaxPlusMinAfterOperations(int[] arr, int requests) {
        int mn = Integer.MAX_VALUE;
        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int x : arr) { heap.offer(x); mn = Math.min(mn, x); }
        long ans = 0;
        for (int t = 0; t < requests; t++) {
            int mx = heap.poll();
            ans += (long)mx + mn;
            heap.offer(mx - 1);
            if (mx - 1 < mn) mn = mx - 1;
        }
        return ans;
    }
}

class Solution {
public:
    long long sumMaxPlusMinAfterOperations(vector<int>& arr, int requests) {
        priority_queue<int> heap(arr.begin(), arr.end());
        int mn = *min_element(arr.begin(), arr.end());
        long long ans = 0;
        for (int t = 0; t < requests; t++) {
            int mx = heap.top(); heap.pop();
            ans += (long long)mx + mn;
            heap.push(mx - 1);
            if (mx - 1 < mn) mn = mx - 1;
        }
        return ans;
    }
};

