def leastInterval(tasks, n):
    from collections import Counter
    cnt = Counter(tasks)
    f = max(cnt.values())
    c = sum(1 for v in cnt.values() if v == f)
    return max(len(tasks), (f - 1) * (n + 1) + c)

class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] cnt = new int[26];
        for (char c : tasks) cnt[c - 'A']++;
        int f = 0;
        for (int v : cnt) f = Math.max(f, v);
        int c = 0;
        for (int v : cnt) if (v == f) c++;
        return Math.max(tasks.length, (f - 1) * (n + 1) + c);
    }
}

class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        int cnt[26] = {0};
        for (char c : tasks) cnt[c - 'A']++;
        int f = *max_element(cnt, cnt + 26);
        int c = count(cnt, cnt + 26, f);
        return max((int)tasks.size(), (f - 1) * (n + 1) + c);
    }
};

class Solution {
    public long traderJoeTrades(String tasks, int[] rewards, int k) {
        int n = tasks.length();
        long total = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && tasks.charAt(j) == tasks.charAt(i)) j++;
            Integer[] runR = new Integer[j - i];
            for (int t = i; t < j; t++) runR[t - i] = rewards[t];
            java.util.Arrays.sort(runR, java.util.Collections.reverseOrder());
            for (int t = 0; t < Math.min(k, runR.length); t++) total += runR[t];
            i = j;
        }
        return total;
    }
}

class Solution {
public:
