        int n = tasks.size();
        long long total = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && tasks[j] == tasks[i]) j++;
            vector<int> runR(rewards.begin() + i, rewards.begin() + j);
            sort(runR.begin(), runR.end(), greater<int>());
            for (int t = 0; t < min(k, (int)runR.size()); t++) total += runR[t];
            i = j;
        }
        return total;
    }
};

class Solution {
    public String treeNodeRelationship(int n, int[][] edges, int nodeA, int nodeB) {
        java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new java.util.ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] par = new int[n], dep = new int[n];
        java.util.Arrays.fill(par, -1);
        boolean[] vis = new boolean[n]; vis[0] = true;
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.offer(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (!vis[v]) { vis[v] = true; par[v] = u; dep[v] = dep[u] + 1; q.offer(v); }
        }
        if (dep[nodeA] != dep[nodeB]) return "others";
        return par[nodeA] == par[nodeB] ? "siblings" : "cousins";
    }
}

class Solution {
public:
    string treeNodeRelationship(int n, vector<vector<int>>& edges, int nodeA, int nodeB) {
        vector<vector<int>> g(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), dep(n, 0);
        vector<bool> vis(n, false); vis[0] = true;
        queue<int> q; q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) if (!vis[v]) { vis[v] = true; par[v] = u; dep[v] = dep[u] + 1; q.push(v); }
        }
        if (dep[nodeA] != dep[nodeB]) return "others";
        return par[nodeA] == par[nodeB] ? "siblings" : "cousins";
    }
};

class Solution {
    public String[] solveUniquePairsWithTargetSum(String input) {
        String[] lines = input.split("\n");
        String[] h = lines[0].split(" ");
        int target = Integer.parseInt(h[1]);
        String[] tok = lines[1].split(" ");
        java.util.HashSet<Integer> seen = new java.util.HashSet<>();
        java.util.TreeSet<long[]> pairs = new java.util.TreeSet<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        for (String t : tok) {
            int x = Integer.parseInt(t), c = target - x;
            if (seen.contains(c)) {
                long a = Math.min(x, c), b = Math.max(x, c);
                pairs.add(new long[]{a, b});
            }
            seen.add(x);
        }
        if (pairs.isEmpty()) return new String[]{"None"};
        String[] res = new String[pairs.size()];
        int i = 0;
        for (long[] p : pairs) res[i++] = p[0] + "," + p[1];
        return res;
    }
}

class Solution {
public:
    vector<string> solveUniquePairsWithTargetSum(string input) {
        stringstream ss(input);
        int n, target;
        ss >> n >> target;
        unordered_set<int> seen;
        set<pair<int,int>> pairs;
        for (int i = 0; i < n; i++) {
            int x; ss >> x;
            int c = target - x;
            if (seen.count(c)) pairs.insert({min(x, c), max(x, c)});
            seen.insert(x);
        }
        if (pairs.empty()) return {"None"};
        vector<string> res;
        for (auto& [a, b] : pairs) res.push_back(to_string(a) + "," + to_string(b));
        return res;
    }
};

class Solution {
    public long[] useMinimumTokens(int[] warehouse, long[][] catalog) {
        long total = 0;
        int mx = 0, mx2 = -1;
        for (int w : warehouse) { total += w; if (w > mx) { mx2 = mx; mx = w; } else if (w > mx2) mx2 = w; }
        long[] res = new long[catalog.length];
        for (int i = 0; i < catalog.length; i++) {
            long a = catalog[i][0], b = catalog[i][1];
            long c1 = Math.max(0L, a - mx) + Math.max(0L, b - (total - mx));
            long c2 = Long.MAX_VALUE;
            if (mx2 != -1) c2 = Math.max(0L, a - mx2) + Math.max(0L, b - (total - mx2));
            res[i] = Math.min(c1, c2);
        }
        return res;
    }
}

