def calculateEfficiencyScore(s, kitParentheses, m, efficiencyRatings):
    # Count needed balance from s
    open_count = 0
    need_open = 0  # ')' that came when no open
    for c in s:
        if c == '(': open_count += 1
        else:
            if open_count > 0: open_count -= 1
            else: need_open += 1
    need_close = open_count  # remaining unmatched '('
    # Split kit
    opens, closes = [], []
    for i, c in enumerate(kitParentheses):
        if c == '(': opens.append(efficiencyRatings[i])
        else: closes.append(efficiencyRatings[i])
    opens.sort(reverse=True)
    closes.sort(reverse=True)
    score = 0
    # Need need_open '(' from kit
    if len(opens) < need_open or len(closes) < need_close:
        return 0  # not guaranteed; assume 0
    score += sum(opens[:need_open])
    score += sum(closes[:need_close])
    # Add remaining positive pairs: pair one extra '(' with one ')' (must be added in matched pair)
    i, j = need_open, need_close
    while i < len(opens) and j < len(closes):
        if opens[i] + closes[j] > 0:
            score += opens[i] + closes[j]
            i += 1; j += 1
        else:
            break
    return score

class Solution {
    public long calculateEfficiencyScore(String s, String kitParentheses, int m, int[] eff) {
        int openCount = 0, needOpen = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') openCount++;
            else { if (openCount > 0) openCount--; else needOpen++; }
        }
        int needClose = openCount;
        java.util.List<Integer> opens = new java.util.ArrayList<>(), closes = new java.util.ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (kitParentheses.charAt(i) == '(') opens.add(eff[i]);
            else closes.add(eff[i]);
        }
        opens.sort(java.util.Collections.reverseOrder());
        closes.sort(java.util.Collections.reverseOrder());
        if (opens.size() < needOpen || closes.size() < needClose) return 0;
        long score = 0;
        for (int i = 0; i < needOpen; i++) score += opens.get(i);
        for (int i = 0; i < needClose; i++) score += closes.get(i);
        int i = needOpen, j = needClose;
        while (i < opens.size() && j < closes.size() && opens.get(i) + closes.get(j) > 0) {
            score += opens.get(i) + closes.get(j);
            i++; j++;
        }
        return score;
    }
}

class Solution {
public:
