};

def checkSimilarPasswords(newPasswords, oldPasswords):
    res = []
    for n, o in zip(newPasswords, oldPasswords):
        i = 0
        for ch in n:
            if i < len(o):
                if ch == o[i]:
                    i += 1
                elif chr((ord(ch) - ord('a') + 1) % 26 + ord('a')) == o[i]:
                    i += 1
        res.append("YES" if i == len(o) else "NO")
    return res

class Solution {
    public String[] checkSimilarPasswords(String[] newPasswords, String[] oldPasswords) {
        String[] res = new String[newPasswords.length];
        for (int t = 0; t < newPasswords.length; t++) {
            String n = newPasswords[t], o = oldPasswords[t];
            int i = 0;
            for (int j = 0; j < n.length(); j++) {
                if (i < o.length()) {
                    char c = n.charAt(j);
                    char next = (char)((c - 'a' + 1) % 26 + 'a');
                    if (c == o.charAt(i) || next == o.charAt(i)) i++;
                }
            }
            res[t] = i == o.length() ? "YES" : "NO";
        }
        return res;
    }
}

