                    if (c == o[i] || nx == o[i]) i++;
                }
            }
            res.push_back(i == (int)o.size() ? "YES" : "NO");
        }
        return res;
    }
};

def countMaxNumTeams(skill, teamSize, maxDiff):
    a = sorted(skill)
    n = len(a)
    teams = 0
    i = 0
    while i + teamSize <= n:
        if a[i + teamSize - 1] - a[i] <= maxDiff:
            teams += 1
            i += teamSize
        else:
            i += 1
    return teams

