class Solution {
    public long countMaximumProfitableGroups(int[] stockPrice) {
        int n = stockPrice.length;
        long total = (long)n * (n + 1) / 2;
        int[] left = new int[n], right = new int[n];
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && stockPrice[st.peek()] <= stockPrice[i]) st.pop();
            left[i] = st.isEmpty() ? -1 : st.peek();
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && stockPrice[st.peek()] < stockPrice[i]) st.pop();
            right[i] = st.isEmpty() ? n : st.peek();
            st.push(i);
        }
        long bad = 0;
        for (int i = 0; i < n; i++) bad += (long)(i - left[i] - 1) * (right[i] - i - 1);
        return total - bad;
    }
}

class Solution {
public:
    long long countMaximumProfitableGroups(vector<int>& stockPrice) {
        int n = stockPrice.size();
        long long total = (long long)n * (n + 1) / 2;
        vector<int> left(n), right(n);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && stockPrice[st.top()] <= stockPrice[i]) st.pop();
            left[i] = st.empty() ? -1 : st.top();
            st.push(i);
        }
        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && stockPrice[st.top()] < stockPrice[i]) st.pop();
            right[i] = st.empty() ? n : st.top();
            st.push(i);
        }
        long long bad = 0;
        for (int i = 0; i < n; i++) bad += (long long)(i - left[i] - 1) * (right[i] - i - 1);
        return total - bad;
    }
};

def countNumWays(s, k):
    n = len(s)
    cnt = 0
    for i in range(n - k + 1):
        for j in range(k // 2):
            a, b = s[i + j], s[i + k - 1 - j]
            if a != b:
                if a > b:
                    cnt += 1
                break
    return cnt

class Solution {
    public int countNumWays(String s, int k) {
        int n = s.length(), cnt = 0;
        for (int i = 0; i + k <= n; i++) {
            for (int j = 0; j < k / 2; j++) {
                char a = s.charAt(i + j), b = s.charAt(i + k - 1 - j);
                if (a != b) { if (a > b) cnt++; break; }
            }
        }
        return cnt;
    }
}

