def countSpikes(prices, k):
    n = len(prices)
    cnt = 0
    for i in range(n):
        leftLess = sum(1 for j in range(i) if prices[j] < prices[i])
        rightLess = sum(1 for j in range(i + 1, n) if prices[j] < prices[i])
        if leftLess >= k and rightLess >= k:
            cnt += 1
    return cnt

class Solution {
    public int countSpikes(int[] prices, int k) {
        int n = prices.length, cnt = 0;
        for (int i = 0; i < n; i++) {
            int l = 0, r = 0;
            for (int j = 0; j < i; j++) if (prices[j] < prices[i]) l++;
            for (int j = i + 1; j < n; j++) if (prices[j] < prices[i]) r++;
            if (l >= k && r >= k) cnt++;
        }
        return cnt;
    }
}

