class Solution {
    int n;
    int[] arr;
    long countLE(int k) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        int distinct = 0, l = 0;
        long total = 0;
        for (int r = 0; r < n; r++) {
            cnt.merge(arr[r], 1, Integer::sum);
            if (cnt.get(arr[r]) == 1) distinct++;
            while (distinct > k) {
                cnt.merge(arr[l], -1, Integer::sum);
                if (cnt.get(arr[l]) == 0) { cnt.remove(arr[l]); distinct--; }
                l++;
            }
            total += r - l + 1;
        }
        return total;
    }
    public int findMedianOfSubarrayUniqueness(int[] arr) {
        this.arr = arr; this.n = arr.length;
        long N = (long)n * (n + 1) / 2;
        long mid = (N - 1) / 2;
        int lo = 1, hi = n;
        while (lo < hi) {
            int m = (lo + hi) >>> 1;
            if (countLE(m) > mid) hi = m; else lo = m + 1;
        }
        return lo;
    }
}

class Solution {
public:
    int findMedianOfSubarrayUniqueness(vector<int>& arr) {
        int n = arr.size();
        auto countLE = [&](int k) -> long long {
            unordered_map<int, int> cnt;
            int distinct = 0, l = 0;
            long long total = 0;
            for (int r = 0; r < n; r++) {
                if (++cnt[arr[r]] == 1) distinct++;
                while (distinct > k) {
                    if (--cnt[arr[l]] == 0) distinct--;
                    l++;
                }
                total += r - l + 1;
            }
            return total;
        };
        long long N = (long long)n * (n + 1) / 2;
        long long mid = (N - 1) / 2;
        int lo = 1, hi = n;
        while (lo < hi) {
            int m = (lo + hi) / 2;
            if (countLE(m) > mid) hi = m; else lo = m + 1;
        }
        return lo;
    }
};

def findMinimumInefficiency(serverType):
    n = len(serverType)
    INF = float('inf')
    f = [0, 0]
    if serverType[0] == '0': f = [0, INF]
    elif serverType[0] == '1': f = [INF, 0]
    for i in range(1, n):
        nf = [INF, INF]
        for b in range(2):
            if serverType[i] != '?' and serverType[i] != str(b): continue
            for pb in range(2):
                if f[pb] == INF: continue
                nf[b] = min(nf[b], f[pb] + (1 if pb != b else 0))
        f = nf
    return min(f)

class Solution {
    public int findMinimumInefficiency(String s) {
        int n = s.length(), INF = Integer.MAX_VALUE / 2;
        int[] f = {INF, INF};
        if (s.charAt(0) == '0') f[0] = 0;
        else if (s.charAt(0) == '1') f[1] = 0;
        else { f[0] = 0; f[1] = 0; }
        for (int i = 1; i < n; i++) {
            int[] nf = {INF, INF};
            for (int b = 0; b < 2; b++) {
                if (s.charAt(i) != '?' && s.charAt(i) - '0' != b) continue;
                for (int pb = 0; pb < 2; pb++) {
                    if (f[pb] == INF) continue;
                    nf[b] = Math.min(nf[b], f[pb] + (pb != b ? 1 : 0));
                }
            }
            f = nf;
        }
        return Math.min(f[0], f[1]);
    }
}

class Solution {
public:
    int findMinimumInefficiency(string s) {
        int n = s.size(), INF = INT_MAX / 2;
        int f[2] = {INF, INF};
        if (s[0] == '0') f[0] = 0;
        else if (s[0] == '1') f[1] = 0;
        else { f[0] = 0; f[1] = 0; }
        for (int i = 1; i < n; i++) {
            int nf[2] = {INF, INF};
            for (int b = 0; b < 2; b++) {
                if (s[i] != '?' && s[i] - '0' != b) continue;
                for (int pb = 0; pb < 2; pb++) {
                    if (f[pb] == INF) continue;
                    nf[b] = min(nf[b], f[pb] + (pb != b ? 1 : 0));
                }
            }
            f[0] = nf[0]; f[1] = nf[1];
        }
        return min(f[0], f[1]);
    }
};

def getAverageStanding(d, records):
    from collections import defaultdict
    from math import gcd
    races = defaultdict(list)
    for race_id, pid, ptime in records:
        races[race_id].append((pid, ptime))
    p_sum = [0] * d
    p_cnt = [0] * d
    for race_id, lst in races.items():
        lst.sort(key=lambda x: (x[1], x[0]))
        for rank, (pid, _) in enumerate(lst, 1):
            p_sum[pid] += rank
            p_cnt[pid] += 1
    res = []
    for i in range(d):
        if p_cnt[i] == 0:
            res.append([-1, -1])
        else:
            g = gcd(p_sum[i], p_cnt[i])
            res.append([p_sum[i] // g, p_cnt[i] // g])
    return res

class Solution {
    long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public int[][] getAverageStanding(int d, int[][] records) {
        java.util.HashMap<Integer, java.util.List<int[]>> races = new java.util.HashMap<>();
        for (int[] r : records) races.computeIfAbsent(r[0], k -> new java.util.ArrayList<>()).add(new int[]{r[1], r[2]});
        long[] sum = new long[d];
        int[] cnt = new int[d];
        for (var lst : races.values()) {
            lst.sort((a, b) -> a[1] != b[1] ? Integer.compare(a[1], b[1]) : Integer.compare(a[0], b[0]));
            for (int i = 0; i < lst.size(); i++) {
                int pid = lst.get(i)[0];
                sum[pid] += i + 1;
                cnt[pid]++;
            }
        }
        int[][] res = new int[d][2];
        for (int i = 0; i < d; i++) {
            if (cnt[i] == 0) { res[i][0] = -1; res[i][1] = -1; }
            else { long g = gcd(sum[i], cnt[i]); res[i][0] = (int)(sum[i] / g); res[i][1] = (int)(cnt[i] / g); }
        }
        return res;
    }
}

class Solution {
public:
    long long gcd(long long a, long long b) { return b == 0 ? a : gcd(b, a % b); }
    vector<vector<int>> getAverageStanding(int d, vector<vector<int>>& records) {
        unordered_map<int, vector<pair<int,int>>> races;
        for (auto& r : records) races[r[0]].push_back({r[1], r[2]});
        vector<long long> sum(d, 0);
        vector<int> cnt(d, 0);
        for (auto& [k, lst] : races) {
            sort(lst.begin(), lst.end(), [](auto& a, auto& b){ return a.second != b.second ? a.second < b.second : a.first < b.first; });
            for (int i = 0; i < (int)lst.size(); i++) {
                int pid = lst[i].first;
                sum[pid] += i + 1;
                cnt[pid]++;
            }
        }
        vector<vector<int>> res(d, vector<int>(2));
        for (int i = 0; i < d; i++) {
            if (cnt[i] == 0) { res[i] = {-1, -1}; }
            else { long long g = gcd(sum[i], cnt[i]); res[i] = {(int)(sum[i] / g), (int)(cnt[i] / g)}; }
        }
        return res;
    }
};

def getDiscountPairs(x, prices):
    from collections import Counter
    cnt = Counter(p % x for p in prices)
    total = cnt[0] * (cnt[0] - 1) // 2
    if x % 2 == 0:
        total += cnt[x // 2] * (cnt[x // 2] - 1) // 2
    for r in range(1, (x + 1) // 2):
        total += cnt[r] * cnt[x - r]
    return total

class Solution {
    public long getDiscountPairs(int x, int[] prices) {
        java.util.HashMap<Integer, Long> cnt = new java.util.HashMap<>();
        for (int p : prices) cnt.merge(p % x, 1L, Long::sum);
        long total = 0;
        long c0 = cnt.getOrDefault(0, 0L);
        total += c0 * (c0 - 1) / 2;
        if (x % 2 == 0) {
            long ch = cnt.getOrDefault(x / 2, 0L);
            total += ch * (ch - 1) / 2;
        }
        for (int r = 1; r < (x + 1) / 2; r++) {
            total += cnt.getOrDefault(r, 0L) * cnt.getOrDefault(x - r, 0L);
        }
        return total;
    }
}

class Solution {
public:
    long long getDiscountPairs(int x, vector<int>& prices) {
        unordered_map<int, long long> cnt;
        for (int p : prices) cnt[p % x]++;
        long long total = 0;
        long long c0 = cnt[0];
        total += c0 * (c0 - 1) / 2;
        if (x % 2 == 0) {
            long long ch = cnt[x / 2];
            total += ch * (ch - 1) / 2;
        }
        for (int r = 1; r < (x + 1) / 2; r++) total += cnt[r] * cnt[x - r];
        return total;
    }
};

