def getMeanRankCount(rank):
    n = len(rank)
    res = [0] * n
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += rank[j]
            length = j - i + 1
            if s % length == 0:
                m = s // length
                if 1 <= m <= n:
                    res[m - 1] += 1
    return res

class Solution {
