            for (int j = i; j < n; j++) {
                s += rank[j];
                int len = j - i + 1;
                if (s % len == 0) {
                    long m = s / len;
                    if (m >= 1 && m <= n) res[(int)m - 1]++;
                }
            }
        }
        return res;
    }
}

