def getMinCostData(data):
    a = list(data)
    n = len(a)
    for i in range(n):
        if a[i] == '?':
            for c in range(ord('a'), ord('z') + 1):
                left = a[i - 1] if i > 0 else None
                right = a[i + 1] if i + 1 < n and a[i + 1] != '?' else None
                if chr(c) != left and chr(c) != right:
                    a[i] = chr(c)
                    break
    return ''.join(a)

class Solution {
