        char[] a = data.toCharArray();
        int n = a.length;
        for (int i = 0; i < n; i++) {
            if (a[i] == '?') {
                for (char c = 'a'; c <= 'z'; c++) {
                    char left = i > 0 ? a[i - 1] : 0;
                    char right = (i + 1 < n && a[i + 1] != '?') ? a[i + 1] : 0;
                    if (c != left && c != right) { a[i] = c; break; }
                }
            }
        }
        return new String(a);
    }
}

