class Solution {
    public long getMinimumCost(int[] a, int[] b, int m) {
        java.util.PriorityQueue<long[]> heap = new java.util.PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        for (int i = 0; i < a.length; i++) heap.offer(new long[]{a[i], i, 1});
        long total = 0;
        for (int t = 0; t < m; t++) {
            long[] x = heap.poll();
            total += x[0];
            int i = (int)x[1]; long j = x[2];
            heap.offer(new long[]{a[i] + j * b[i], i, j + 1});
        }
        return total;
    }
}

class Solution {
public:
    long long getMinimumCost(vector<int>& a, vector<int>& b, int m) {
        priority_queue<tuple<long long, int, long long>, vector<tuple<long long, int, long long>>, greater<>> heap;
        for (int i = 0; i < (int)a.size(); i++) heap.push({a[i], i, 1});
        long long total = 0;
        for (int t = 0; t < m; t++) {
            auto [c, i, j] = heap.top(); heap.pop();
            total += c;
            heap.push({a[i] + j * b[i], i, j + 1});
        }
        return total;
    }
};

class Solution {
    public int getMinimumFruits(int[] fruitsArray) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int v : fruitsArray) cnt.merge(v, 1, Integer::sum);
        int n = fruitsArray.length, f = 0;
        for (int v : cnt.values()) f = Math.max(f, v);
        if (f > n - f) return 2 * f - n;
        return n % 2;
    }
}

