    }
};

class Solution {
    public int getMinimumRoundTripCost(int[] departing, int[] returning) {
        int n = departing.length;
        if (n < 2) return -1;
        int prefMin = departing[0], best = Integer.MAX_VALUE;
        for (int j = 1; j < n; j++) {
            best = Math.min(best, prefMin + returning[j]);
            prefMin = Math.min(prefMin, departing[j]);
        }
        return best;
    }
}

