def getPrioritiesAfterExecution(priority):
    arr = list(priority)
    while True:
        from collections import defaultdict
        by_p = defaultdict(list)
        for i, p in enumerate(arr):
            by_p[p].append(i)
        # find max p with at least 2 entries
        best_p = -1
        for p in by_p:
            if len(by_p[p]) >= 2 and p > best_p:
                best_p = p
        if best_p <= 0:
            return arr
        i1, i2 = by_p[best_p][0], by_p[best_p][1]
        arr[i2] = best_p // 2
        arr.pop(i1)

class Solution {
    public int[] getPrioritiesAfterExecution(int[] priority) {
        java.util.ArrayList<Integer> arr = new java.util.ArrayList<>();
        for (int p : priority) arr.add(p);
        while (true) {
            java.util.HashMap<Integer, int[]> first2 = new java.util.HashMap<>();
            int bestP = -1;
            for (int i = 0; i < arr.size(); i++) {
                int p = arr.get(i);
                int[] arr2 = first2.computeIfAbsent(p, k -> new int[]{-1, -1});
                if (arr2[0] == -1) arr2[0] = i;
                else if (arr2[1] == -1) { arr2[1] = i; if (p > bestP) bestP = p; }
            }
            if (bestP <= 0) break;
            int[] pair = first2.get(bestP);
            arr.set(pair[1], bestP / 2);
            arr.remove(pair[0]);
        }
        return arr.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> getPrioritiesAfterExecution(vector<int>& priority) {
        vector<int> arr = priority;
        while (true) {
            unordered_map<int, pair<int,int>> first2;
            int bestP = -1;
            for (int i = 0; i < (int)arr.size(); i++) {
                int p = arr[i];
                auto& pr = first2[p];
                if (pr.first == 0 && pr.second == 0 && (i == 0 || (pr.first != 0 || pr.second != 0))) { /* skip */ }
                if (!first2.count(p) || true) {} // overhead
                // Use map<int, vector<int>> for clarity:
            }
            map<int, vector<int>> m;
            for (int i = 0; i < (int)arr.size(); i++) m[arr[i]].push_back(i);
            bestP = -1;
            for (auto& [p, v] : m) if (v.size() >= 2 && p > bestP) bestP = p;
            if (bestP <= 0) break;
            auto& v = m[bestP];
            arr[v[1]] = bestP / 2;
            arr.erase(arr.begin() + v[0]);
        }
        return arr;
    }
};

