def getSuccessValue(num_viewers, queries):
    a = sorted(num_viewers, reverse=True)
    pref = [0]
    for x in a: pref.append(pref[-1] + x)
    return [pref[k] for k in queries]

class Solution {
    public long[] getSuccessValue(int[] num_viewers, int[] queries) {
        Integer[] a = java.util.stream.IntStream.of(num_viewers).boxed().toArray(Integer[]::new);
        java.util.Arrays.sort(a, java.util.Collections.reverseOrder());
        long[] pref = new long[a.length + 1];
        for (int i = 0; i < a.length; i++) pref[i + 1] = pref[i] + a[i];
        long[] res = new long[queries.length];
        for (int i = 0; i < queries.length; i++) res[i] = pref[queries[i]];
        return res;
    }
}

