    }
};

class Solution {
    public int[] getTrucksForItems(int[] trucks, int[] items) {
        int n = trucks.length;
        int[][] st = new int[n][2];
        for (int i = 0; i < n; i++) { st[i][0] = trucks[i]; st[i][1] = i; }
        java.util.Arrays.sort(st, (a, b) -> Integer.compare(a[0], b[0]));
        int[] caps = new int[n];
        for (int i = 0; i < n; i++) caps[i] = st[i][0];
        int[] sufMin = new int[n + 1];
        sufMin[n] = Integer.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) sufMin[i] = Math.min(sufMin[i + 1], st[i][1]);
        int[] res = new int[items.length];
        for (int i = 0; i < items.length; i++) {
            int lo = 0, hi = n;
            while (lo < hi) { int m = (lo + hi) >>> 1; if (caps[m] <= items[i]) lo = m + 1; else hi = m; }
            if (lo >= n) res[i] = -1; else res[i] = sufMin[lo];
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getTrucksForItems(vector<int>& trucks, vector<int>& items) {
        int n = trucks.size();
        vector<pair<int,int>> st;
        for (int i = 0; i < n; i++) st.push_back({trucks[i], i});
        sort(st.begin(), st.end());
        vector<int> caps(n), sufMin(n + 1, INT_MAX);
        for (int i = 0; i < n; i++) caps[i] = st[i].first;
        for (int i = n - 1; i >= 0; i--) sufMin[i] = min(sufMin[i + 1], st[i].second);
        vector<int> res;
        for (int w : items) {
            auto it = upper_bound(caps.begin(), caps.end(), w);
            int i = it - caps.begin();
            if (i >= n) res.push_back(-1); else res.push_back(sufMin[i]);
        }
        return res;
    }
};

