def makeArrayBitonic(arr):
    n = len(arr)
    INF = float('inf')
    best = INF
    for k in range(n):
        # peak at k with height arr[k]
        h = arr[k]
        if h < 1: continue
        # left: positions ..k must satisfy arr'[i] in {0} ∪ [1..arr[k]] strictly increasing in non-zero suffix ending at h
        # min cost: greedy from right to left
        cur_max = h
        left_cost = 0
        for i in range(k - 1, -1, -1):
            cur_max -= 1
            if cur_max <= 0:
                # all earlier positions must be 0
                for j in range(i + 1):
                    left_cost += arr[j]
                break
            if arr[i] > cur_max:
                left_cost += arr[i] - cur_max
            else:
                cur_max = arr[i]
        # right
        cur_max = h
        right_cost = 0
        for i in range(k + 1, n):
            cur_max -= 1
            if cur_max <= 0:
                for j in range(i, n):
                    right_cost += arr[j]
                break
            if arr[i] > cur_max:
                right_cost += arr[i] - cur_max
            else:
                cur_max = arr[i]
        best = min(best, left_cost + right_cost)
    return best

class Solution {
    public long makeArrayBitonic(int[] arr) {
        int n = arr.length;
        long best = Long.MAX_VALUE;
        for (int k = 0; k < n; k++) {
            int h = arr[k];
            if (h < 1) continue;
            long left = 0;
            int cur = h;
            int i = k - 1;
            while (i >= 0) {
                cur--;
                if (cur <= 0) { for (int j = i; j >= 0; j--) left += arr[j]; break; }
                if (arr[i] > cur) left += arr[i] - cur;
                else cur = arr[i];
                i--;
            }
            long right = 0;
            cur = h;
            i = k + 1;
            while (i < n) {
                cur--;
                if (cur <= 0) { for (int j = i; j < n; j++) right += arr[j]; break; }
                if (arr[i] > cur) right += arr[i] - cur;
                else cur = arr[i];
                i++;
            }
            best = Math.min(best, left + right);
        }
        return best;
    }
}

