class Solution {
    public int maxSetSize(long[] riceBags) {
        java.util.HashSet<Long> s = new java.util.HashSet<>();
        for (long x : riceBags) s.add(x);
        int best = -1;
        for (long a : s) {
            long r = (long) Math.sqrt(a);
            while (r * r > a) r--;
            while ((r + 1) * (r + 1) <= a) r++;
            if (r * r == a && s.contains(r)) continue;
            int len = 0;
            long cur = a;
            while (s.contains(cur)) {
                len++;
                if (cur > 1_000_000_000L) break;
                cur = cur * cur;
            }
            if (len >= 2 && len > best) best = len;
        }
        return best;
    }
}

