    }
};

class Solution {
    public int maximizeNegativeSigns(int[] sequence) {
        // Note: simpler approach - process left to right, maintain prefix sum after flips
        long sum = 0;
        java.util.PriorityQueue<Integer> minHeapOfPositives = new java.util.PriorityQueue<>();
        int neg = 0;
        for (int x : sequence) {
            sum += x;
            minHeapOfPositives.offer(x); // tracks currently positive
            // greedily flip the smallest still-positive that keeps sum > 0
            // Actually want to flip largest possible.
            // Switch to maxHeap:
        }
        // Re-implement cleanly:
        java.util.PriorityQueue<Integer> mx = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        sum = 0; neg = 0;
        for (int x : sequence) {
            sum += x;
            mx.offer(x);
            // pop and flip largest while still safe
            if (!mx.isEmpty() && sum - 2L * mx.peek() > 0) {
                int v = mx.poll();
                sum -= 2L * v;
                neg++;
            }
        }
        return neg;
    }
}

class Solution {
public:
    int maximizeNegativeSigns(vector<int>& sequence) {
        priority_queue<int> mx;
        long long sum = 0;
        int neg = 0;
        for (int x : sequence) {
            sum += x;
            mx.push(x);
            if (!mx.empty() && sum - 2LL * mx.top() > 0) {
                int v = mx.top(); mx.pop();
                sum -= 2LL * v;
                neg++;
            }
        }
        return neg;
    }
};

def maximizeRepeatedSubstringLength(s):
    n = len(s)
    for k in range(n // 2, 0, -1):
        for i in range(n - 2 * k + 1):
            ok = True
            for j in range(k):
                a, b = s[i + j], s[i + k + j]
                if a != '?' and b != '?' and a != b:
                    ok = False; break
            if ok:
                return 2 * k
    return 0

class Solution {
