        int n = s.length();
        for (int k = n / 2; k >= 1; k--) {
            for (int i = 0; i + 2 * k <= n; i++) {
                boolean ok = true;
                for (int j = 0; j < k; j++) {
                    char a = s.charAt(i + j), b = s.charAt(i + k + j);
                    if (a != '?' && b != '?' && a != b) { ok = false; break; }
                }
                if (ok) return 2 * k;
            }
        }
        return 0;
    }
}

