def maximumScoreInBalancedString(s):
    # use greedy: rightmost open with leftmost close gives maximum (j-i)
    opens = [i for i, c in enumerate(s) if c == '(']
    closes = [i for i, c in enumerate(s) if c == ')']
    # match opens (in order) with closes (in order) but choose pairs to maximize sum(j-i) with valid (j > i in pairing & balance)
    # Greedy: match outermost first; for balanced sub, take all valid (i, j) with i in opens, j in closes, i<j, ensuring balanced by stack
    stack = []
    score = 0
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        else:
            if stack:
                j = stack.pop()
                score += i - j
    return score

class Solution {
    public int maximumScoreInBalancedString(String s) {
        java.util.ArrayDeque<Integer> st = new java.util.ArrayDeque<>();
        int score = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') st.push(i);
            else if (!st.isEmpty()) { int j = st.pop(); score += i - j; }
        }
        return score;
    }
}

class Solution {
public:
    int maximumScoreInBalancedString(string s) {
        stack<int> st;
        int score = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') st.push(i);
            else if (!st.empty()) { int j = st.top(); st.pop(); score += i - j; }
        }
        return score;
    }
};

class Solution {
    public long minimalCostToIncreasePackageSize(int[] size, int[] cost) {
        int n = size.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> size[a] != size[b] ? Integer.compare(size[a], size[b]) : Integer.compare(cost[b], cost[a]));
        java.util.HashSet<Long> used = new java.util.HashSet<>();
        long total = 0;
        for (int i : idx) {
            long cur = size[i];
            while (used.contains(cur)) { cur++; total += cost[i]; }
            used.add(cur);
        }
        return total;
    }
}

class Solution {
public:
    long long minimalCostToIncreasePackageSize(vector<int>& size, vector<int>& cost) {
        int n = size.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){
            if (size[a] != size[b]) return size[a] < size[b];
            return cost[a] > cost[b];
        });
        unordered_set<long long> used;
        long long total = 0;
        for (int i : idx) {
            long long cur = size[i];
            while (used.count(cur)) { cur++; total += cost[i]; }
            used.insert(cur);
        }
        return total;
    }
};

class Solution {
    public int minimumTimeSpent(int[] cR, int[] cD, int[] dR, int[] dD) {
        int cMin = Integer.MAX_VALUE, dMin = Integer.MAX_VALUE;
        for (int i = 0; i < cR.length; i++) cMin = Math.min(cMin, cR[i] + cD[i]);
        for (int i = 0; i < dR.length; i++) dMin = Math.min(dMin, dR[i] + dD[i]);
        int best1 = Integer.MAX_VALUE;
        for (int i = 0; i < dR.length; i++) best1 = Math.min(best1, Math.max(cMin, dR[i]) + dD[i]);
        int best2 = Integer.MAX_VALUE;
        for (int i = 0; i < cR.length; i++) best2 = Math.min(best2, Math.max(dMin, cR[i]) + cD[i]);
        return Math.min(best1, best2);
    }
}

class Solution {
public:
    int minimumTimeSpent(vector<int>& cR, vector<int>& cD, vector<int>& dR, vector<int>& dD) {
        int cMin = INT_MAX, dMin = INT_MAX;
        for (int i = 0; i < (int)cR.size(); i++) cMin = min(cMin, cR[i] + cD[i]);
        for (int i = 0; i < (int)dR.size(); i++) dMin = min(dMin, dR[i] + dD[i]);
