    import re
    # find two parenthesized groups
    groups = re.findall(r'\(([^()]+)\)', s)
    var = None
    for ch in s:
        if ch.isalpha():
            var = ch; break
    def parse(expr):
        # expr like "2x²+4" or "-1x³" or "3"
        tokens = re.findall(r'([+-]?\d*)(' + re.escape(var) + r')?(?:\^(-?\d+))?', expr)
        terms = []
        for c, v, e in tokens:
            if c == '' and not v and not e: continue
            if c in ('', '+'): coef = 1
            elif c == '-': coef = -1
            else: coef = int(c)
            if v:
                exp = int(e) if e else 1
            else:
                exp = 0
            terms.append((coef, exp))
        return terms
    p1 = parse(groups[0])
    p2 = parse(groups[1])
    result = {}
    for c1, e1 in p1:
        for c2, e2 in p2:
            result[e1 + e2] = result.get(e1 + e2, 0) + c1 * c2
    items = sorted(((e, c) for e, c in result.items() if c != 0), reverse=True)
    out = ''
    for e, c in items:
        sign = '+' if c > 0 and out else ('-' if c < 0 else '')
        ac = abs(c)
        if e == 0:
            coef_s = str(ac)
        else:
            coef_s = str(ac) if ac != 1 else ''
        var_s = ''
        if e != 0: var_s = var + ('^' + str(e) if e != 1 else '')
        out += sign + coef_s + var_s
    return out or '0'

class Solution {
    public String mathChallenge(String s) {
        java.util.regex.Matcher gm = java.util.regex.Pattern.compile("\\(([^()]+)\\)").matcher(s);
        java.util.List<String> groups = new java.util.ArrayList<>();
        while (gm.find()) groups.add(gm.group(1));
        char var = ' ';
        for (char c : s.toCharArray()) if (Character.isLetter(c)) { var = c; break; }
        java.util.List<int[]> p1 = parse(groups.get(0), var);
        java.util.List<int[]> p2 = parse(groups.get(1), var);
        java.util.TreeMap<Integer, Integer> result = new java.util.TreeMap<>(java.util.Collections.reverseOrder());
        for (int[] a : p1) for (int[] b : p2) result.merge(a[1] + b[1], a[0] * b[0], Integer::sum);
        StringBuilder out = new StringBuilder();
        for (var e : result.entrySet()) {
            int c = e.getValue(); int ex = e.getKey();
            if (c == 0) continue;
            if (out.length() > 0 && c > 0) out.append('+');
            if (c < 0) out.append('-');
            int ac = Math.abs(c);
            if (ex == 0) out.append(ac);
            else {
                if (ac != 1) out.append(ac);
                out.append(var);
                if (ex != 1) out.append("^").append(ex);
            }
        }
        return out.length() == 0 ? "0" : out.toString();
    }
    java.util.List<int[]> parse(String expr, char var) {
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("([+-]?\\d*)(" + java.util.regex.Pattern.quote(String.valueOf(var)) + ")?(?:\\^(-?\\d+))?").matcher(expr);
        java.util.List<int[]> terms = new java.util.ArrayList<>();
        while (m.find()) {
            if (m.group().isEmpty()) continue;
            String c = m.group(1), v = m.group(2), e = m.group(3);
            int coef;
            if (c.isEmpty() || c.equals("+")) coef = 1;
            else if (c.equals("-")) coef = -1;
            else coef = Integer.parseInt(c);
            int exp = (v != null) ? (e != null ? Integer.parseInt(e) : 1) : 0;
            terms.add(new int[]{coef, exp});
        }
        return terms;
    }
}

class Solution {
public:
    string mathChallenge(string s) {
        vector<string> groups;
        size_t i = 0;
        while (i < s.size()) {
            if (s[i] == '(') {
                size_t j = s.find(')', i);
                groups.push_back(s.substr(i + 1, j - i - 1));
                i = j + 1;
            } else i++;
        }
        char var = ' ';
        for (char c : s) if (isalpha(c)) { var = c; break; }
        auto parse = [&](const string& expr) {
            vector<pair<int,int>> terms;
            int idx = 0, n = expr.size();
            while (idx < n) {
                int sign = 1;
                if (expr[idx] == '+') { idx++; }
                else if (expr[idx] == '-') { sign = -1; idx++; }
                int coef = 0;
                bool hasCoef = false;
                while (idx < n && isdigit(expr[idx])) { coef = coef * 10 + (expr[idx] - '0'); hasCoef = true; idx++; }
                if (!hasCoef) coef = 1;
                coef *= sign;
                int exp = 0;
                if (idx < n && expr[idx] == var) {
                    idx++; exp = 1;
                    if (idx < n && expr[idx] == '^') {
                        idx++;
                        int es = 1, ev = 0;
                        if (expr[idx] == '-') { es = -1; idx++; }
                        while (idx < n && isdigit(expr[idx])) { ev = ev * 10 + (expr[idx] - '0'); idx++; }
                        exp = es * ev;
                    }
                }
                terms.push_back({coef, exp});
            }
            return terms;
        };
        auto p1 = parse(groups[0]);
        auto p2 = parse(groups[1]);
        map<int, int, greater<int>> result;
        for (auto& a : p1) for (auto& b : p2) result[a.second + b.second] += a.first * b.first;
        string out;
        for (auto& [ex, c] : result) {
            if (c == 0) continue;
            if (!out.empty() && c > 0) out += '+';
            if (c < 0) out += '-';
            int ac = abs(c);
            if (ex == 0) out += to_string(ac);
            else {
                if (ac != 1) out += to_string(ac);
                out += var;
                if (ex != 1) out += "^" + to_string(ex);
            }
        }
        return out.empty() ? "0" : out;
    }
};

class Solution {
    public long warehouseAllocation(int[] boxes) {
        int n = boxes.length;
        long s = 0; for (int b : boxes) s += b;
        long high = (s + n - 1) / n;
        long ops = 0;
        for (int b : boxes) if (b > high) ops += b - high;
        return ops;
    }
}

