def ignore10(arr: List[int]) -> Tuple[List[int], int]:
    res = []
    i = 0
    n = len(arr)
    while i < n:
        if arr[i] == 1:
            j = i + 1
            while j < n and arr[j] != 0:
                j += 1
            if j < n:
                i = j + 1
            else:
