        while (i < n) {
            if (arr[i] == 1) {
                int j = i + 1;
                while (j < n && arr[j] != 0) ++j;
                if (j < n) i = j + 1; else break;
            } else { res.push_back(arr[i]); ++i; }
        }
        int s = 0; for (int x : res) s += x;
        return {res, s};
    }
};

