def rollTheString(s, roll):
    n = len(s)
    inc = [0] * (n + 1)
    for r in roll:
        inc[r] += 1
    # at position j, total increments = sum_{r >= j+1} inc[r]
    suf = 0
    add = [0] * n
    for j in range(n - 1, -1, -1):
        suf += inc[j + 1]
        add[j] = suf
    out = []
    for j, c in enumerate(s):
        out.append(chr((ord(c) - ord('a') + add[j]) % 26 + ord('a')))
    return ''.join(out)

class Solution {
    String rollTheString(String s, int[] roll) {
        int n = s.length();
        int[] inc = new int[n + 1];
        for (int r : roll) inc[r]++;
        int suf = 0;
        int[] add = new int[n];
        for (int j = n - 1; j >= 0; j--) {
            suf += inc[j + 1];
            add[j] = suf;
        }
        char[] out = s.toCharArray();
        for (int j = 0; j < n; j++) {
            out[j] = (char) ((out[j] - 'a' + add[j]) % 26 + 'a');
        }
        return new String(out);
    }
}

