import java.util.*;

class Solution {
    Object[] finalPrice(int[] prices) {
        int n = prices.length;
        int[] discount = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && prices[stack.peek()] >= prices[i]) {
                discount[stack.pop()] = prices[i];
            }
            stack.push(i);
        }
        long total = 0;
        List<Integer> full = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            total += prices[i] - discount[i];
            if (discount[i] == 0) full.add(i);
        }
        return new Object[]{total, full};
    }
}

