def findSuitableLocations(A: List[List[int]], K: int) -> int:
    n, m = len(A), len(A[0])
    houses = [(i, j) for i in range(n) for j in range(m) if A[i][j] == 1]
    cnt = 0
    for i in range(n):
        for j in range(m):
            if A[i][j] != 0:
                continue
            ok = all(abs(i - hi) + abs(j - hj) <= K for hi, hj in houses)
            if ok:
                cnt += 1
    return cnt

import java.util.*;

class Solution {
    int findSuitableLocations(int[][] A, int K) {
        int n = A.length, m = A[0].length;
        List<int[]> houses = new ArrayList<>();
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) if (A[i][j] == 1) houses.add(new int[]{i, j});
        int cnt = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            if (A[i][j] != 0) continue;
            boolean ok = true;
            for (int[] h : houses) if (Math.abs(i - h[0]) + Math.abs(j - h[1]) > K) { ok = false; break; }
            if (ok) cnt++;
        }
        return cnt;
    }
}

class Solution {
public:
    int findSuitableLocations(vector<vector<int>>& A, int K) {
        int n = A.size(), m = A[0].size();
        vector<pair<int,int>> houses;
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) if (A[i][j] == 1) houses.push_back({i, j});
        int cnt = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            if (A[i][j] != 0) continue;
            bool ok = true;
            for (auto& [hi, hj] : houses) if (abs(i - hi) + abs(j - hj) > K) { ok = false; break; }
            if (ok) cnt++;
        }
        return cnt;
    }
};

