class Solution {
    long assignValues(int N, int[] A, int[] B) {
        int[] deg = new int[N + 1];
        for (int i = 0; i < A.length; i++) { deg[A[i]]++; deg[B[i]]++; }
        Integer[] degs = new Integer[N];
        for (int i = 0; i < N; i++) degs[i] = deg[i + 1];
        Arrays.sort(degs, Collections.reverseOrder());
        long total = 0;
        for (int i = 0; i < N; i++) total += (long) degs[i] * (N - i);
        return total;
    }
}

