import java.util.*;

class Solution {
    int balanceTheGameBoard(String L, int start) {
        int n = L.length();
        int ca = 0;
        for (char c : L.toCharArray()) if (c == 'a') ca++;
        if ((ca - (n - ca)) % 2 != 0 && ((n - ca) - ca) % 2 != 0) return -1;
        Map<String, Boolean> visited = new HashMap<>();
        Deque<Object[]> q = new ArrayDeque<>();
        q.offer(new Object[]{start, L, 0});
        visited.put(start + "|" + L, true);
        while (!q.isEmpty()) {
            Object[] cur = q.poll();
            int pos = (int) cur[0];
            String b = (String) cur[1];
            int steps = (int) cur[2];
            int caCur = 0;
            for (char c : b.toCharArray()) if (c == 'a') caCur++;
            if (caCur * 2 == n) return steps;
            if (steps > 2 * n) continue;
            for (int npos : new int[]{pos - 1, pos + 1}) {
                if (npos < 0 || npos > n) continue;
                int cross = Math.min(pos, npos);
                char[] nb = b.toCharArray();
                nb[cross] = nb[cross] == 'a' ? 'b' : 'a';
                String ns = new String(nb);
                String key = npos + "|" + ns;
                if (!visited.containsKey(key)) {
                    visited.put(key, true);
                    q.offer(new Object[]{npos, ns, steps + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int balanceTheGameBoard(string L, int start) {
        int n = L.size();
        unordered_set<string> visited;
        queue<tuple<int, string, int>> q;
        q.push({start, L, 0});
        visited.insert(to_string(start) + "|" + L);
        while (!q.empty()) {
            auto [pos, b, steps] = q.front(); q.pop();
            int ca = 0;
            for (char c : b) if (c == 'a') ca++;
            if (ca * 2 == n) return steps;
            if (steps > 2 * n) continue;
            for (int npos : {pos - 1, pos + 1}) {
                if (npos < 0 || npos > n) continue;
                int cross = min(pos, npos);
                string nb = b;
                nb[cross] = nb[cross] == 'a' ? 'b' : 'a';
                string key = to_string(npos) + "|" + nb;
                if (!visited.count(key)) {
                    visited.insert(key);
                    q.push({npos, nb, steps + 1});
                }
            }
        }
        return -1;
    }
};

class Solution {
    int calculateLeftoverStacks(int[] stacks) {
        int leftover = 0, carry = 0;
        for (int s : stacks) {
            int cur = s + carry;
            leftover += cur % 2;
            carry = cur / 2;
        }
        leftover += carry;
        return leftover;
    }
}

