def checkPathPresence(N: int, A: List[int], B: List[int]) -> int:
    edges = set()
    for u, v in zip(A, B):
        edges.add((min(u, v), max(u, v)))
    for i in range(1, N):
        if (i, i + 1) not in edges:
            return 0
    return 1

import java.util.*;

class Solution {
    int checkPathPresence(int N, int[] A, int[] B) {
        Set<Long> edges = new HashSet<>();
        for (int i = 0; i < A.length; i++) {
            long u = Math.min(A[i], B[i]), v = Math.max(A[i], B[i]);
            edges.add(u * 100000L + v);
        }
        for (int i = 1; i < N; i++) {
            if (!edges.contains((long) i * 100000L + (i + 1))) return 0;
        }
        return 1;
    }
}

class Solution {
public:
    int checkPathPresence(int N, vector<int>& A, vector<int>& B) {
        set<pair<int,int>> edges;
        for (size_t i = 0; i < A.size(); i++) {
            edges.insert({min(A[i], B[i]), max(A[i], B[i])});
        }
        for (int i = 1; i < N; i++) if (!edges.count({i, i + 1})) return 0;
        return 1;
    }
};

