def cleaningBot(R: List[str]) -> int:
    n, m = len(R), len(R[0])
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = {(0, 0)}
    x, y, d = 0, 0, 0
    fail = 0
    while fail < 4:
        nx, ny = x + dirs[d][0], y + dirs[d][1]
        if 0 <= nx < n and 0 <= ny < m and R[nx][ny] != 'X':
            x, y = nx, ny
            visited.add((x, y))
            fail = 0
        else:
            d = (d + 1) % 4
            fail += 1
    return len(visited)

