class Solution {
    int cleaningBot(String[] R) {
        int n = R.length, m = R[0].length();
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        Set<Long> visited = new HashSet<>();
        visited.add(0L);
        int x = 0, y = 0, d = 0, fail = 0;
        while (fail < 4) {
            int nx = x + dirs[d][0], ny = y + dirs[d][1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && R[nx].charAt(ny) != 'X') {
                x = nx; y = ny;
                visited.add((long) x * 10000L + y);
                fail = 0;
            } else { d = (d + 1) % 4; fail++; }
        }
        return visited.size();
    }
}

