class Solution {
    int compressLen(String t) {
        int out = 0, i = 0, n = t.length();
        while (i < n) {
            int j = i;
            while (j < n && t.charAt(j) == t.charAt(i)) j++;
            int cnt = j - i;
            out += 1 + (cnt > 1 ? String.valueOf(cnt).length() : 0);
            i = j;
        }
        return out;
    }
    int compressedRepresentationSize(String s, int k) {
        int n = s.length(), best = Integer.MAX_VALUE;
        for (int i = 0; i <= n - k; i++) {
            String t = s.substring(0, i) + s.substring(i + k);
            best = Math.min(best, compressLen(t));
        }
        return best;
    }
}

class Solution {
public:
    int compressLen(const string& t) {
        int out = 0, i = 0, n = t.size();
        while (i < n) {
            int j = i;
            while (j < n && t[j] == t[i]) j++;
            int cnt = j - i;
            out += 1 + (cnt > 1 ? (int) to_string(cnt).size() : 0);
            i = j;
        }
        return out;
    }
    int compressedRepresentationSize(string s, int k) {
        int n = s.size(), best = INT_MAX;
        for (int i = 0; i <= n - k; i++) {
            string t = s.substr(0, i) + s.substr(i + k);
            best = min(best, compressLen(t));
        }
        return best;
    }
};

