class Solution {
    int[] constructMaximumBalancedCircle(int[] heights) {
        TreeMap<Integer, Integer> cnt = new TreeMap<>();
        for (int h : heights) cnt.merge(h, 1, Integer::sum);
        Integer[] sorted = cnt.keySet().toArray(new Integer[0]);
        int bestSum = 0, bestL = sorted[0], bestR = sorted[0];
        int i = 0;
        while (i < sorted.length) {
            int j = i, segSum = cnt.get(sorted[i]);
            while (j + 1 < sorted.length && sorted[j + 1] == sorted[j] + 1) {
                j++; segSum += cnt.get(sorted[j]);
            }
            if (segSum > bestSum) { bestSum = segSum; bestL = sorted[i]; bestR = sorted[j]; }
            i = j + 1;
        }
        List<Integer> res = new ArrayList<>();
        for (int h = bestL; h <= bestR; h++) res.add(h);
        for (int h = bestR; h >= bestL; h--) {
            int extra = cnt.get(h) - 1;
            for (int k = 0; k < extra; k++) res.add(h);
        }
        int[] out = new int[res.size()];
        for (int k = 0; k < res.size(); k++) out[k] = res.get(k);
        return out;
    }
}

