        for (auto& [k, v] : cnt) sorted.push_back(k);
        int bestSum = 0, bestL = sorted[0], bestR = sorted[0];
        int i = 0;
        while (i < (int) sorted.size()) {
            int j = i, segSum = cnt[sorted[i]];
            while (j + 1 < (int) sorted.size() && sorted[j + 1] == sorted[j] + 1) {
                j++; segSum += cnt[sorted[j]];
            }
            if (segSum > bestSum) { bestSum = segSum; bestL = sorted[i]; bestR = sorted[j]; }
            i = j + 1;
        }
        vector<int> res;
        for (int h = bestL; h <= bestR; h++) res.push_back(h);
        for (int h = bestR; h >= bestL; h--) {
            int extra = cnt[h] - 1;
            for (int k = 0; k < extra; k++) res.push_back(h);
        }
        return res;
    }
};

