def countSimilarSubstrings(key: str, text: str) -> int:
    k = len(key)
    cnt = 0
    for i in range(len(text) - k + 1):
        sub = text[i:i + k]
        if sub == key:
            cnt += 1
            continue
        # 找差异位置
        diff = [j for j in range(k) if sub[j] != key[j]]
        if len(diff) == 2 and diff[1] == diff[0] + 1 and sub[diff[0]] == key[diff[1]] and sub[diff[1]] == key[diff[0]]:
            cnt += 1
    return cnt

class Solution {
    int countSimilarSubstrings(String key, String text) {
        int k = key.length(), cnt = 0;
        for (int i = 0; i + k <= text.length(); i++) {
            String sub = text.substring(i, i + k);
            if (sub.equals(key)) { cnt++; continue; }
            List<Integer> diff = new ArrayList<>();
            for (int j = 0; j < k; j++) if (sub.charAt(j) != key.charAt(j)) diff.add(j);
            if (diff.size() == 2 && diff.get(1) == diff.get(0) + 1
                && sub.charAt(diff.get(0)) == key.charAt(diff.get(1))
                && sub.charAt(diff.get(1)) == key.charAt(diff.get(0))) cnt++;
        }
        return cnt;
    }
}

class Solution {
public:
    int countSimilarSubstrings(string key, string text) {
        int k = key.size(), cnt = 0;
        for (int i = 0; i + k <= (int) text.size(); i++) {
            string sub = text.substr(i, k);
            if (sub == key) { cnt++; continue; }
            vector<int> diff;
            for (int j = 0; j < k; j++) if (sub[j] != key[j]) diff.push_back(j);
            if (diff.size() == 2 && diff[1] == diff[0] + 1
                && sub[diff[0]] == key[diff[1]] && sub[diff[1]] == key[diff[0]]) cnt++;
        }
        return cnt;
    }
};

