def countSubarraysWithBitwiseOrPresent(arr: List[int]) -> int:
    arr_set = set(arr)
    cnt = 0
    prev = set()
    for x in arr:
        cur = {x} | {p | x for p in prev}
        cnt += sum(1 for v in cur if v in arr_set)
        prev = cur
    return cnt

