class Solution {
    int countSubarraysWithBitwiseOrPresent(int[] arr) {
        Set<Integer> arrSet = new HashSet<>();
        for (int x : arr) arrSet.add(x);
        int cnt = 0;
        Set<Integer> prev = new HashSet<>();
        for (int x : arr) {
            Set<Integer> cur = new HashSet<>();
            cur.add(x);
            for (int p : prev) cur.add(p | x);
            for (int v : cur) if (arrSet.contains(v)) cnt++;
            prev = cur;
        }
        return cnt;
    }
}

