class Solution {
    int[] A;
    boolean ok(int L) {
        int firstEnd = A[0] + L, j = 0;
        while (j < A.length && A[j] <= firstEnd) j++;
        if (j == A.length) return true;
        int secondEnd = A[j] + L;
        while (j < A.length && A[j] <= secondEnd) j++;
        return j == A.length;
    }
    int coverHoles(int[] A) {
        this.A = A.clone();
        Arrays.sort(this.A);
        if (this.A.length == 1) return 1;
        int lo = 1, hi = this.A[this.A.length - 1] - this.A[0] + 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (ok(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

