        }
        return lo;
    }
};

class Solution {
    int findFairIndexes(int[] A, int[] B) {
        long sumA = 0, sumB = 0;
        for (int x : A) sumA += x;
        for (int x : B) sumB += x;
        if (sumA != sumB || sumA % 2 != 0) return 0;
        long half = sumA / 2;
        int cnt = 0;
        long pa = 0, pb = 0;
        for (int k = 0; k < A.length - 1; k++) {
            pa += A[k];
            pb += B[k];
            if (pa == half && pb == half) cnt++;
        }
        return cnt;
    }
}

