class Solution {
    int[] arr;
    int n;
    long countLe(int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int unique = 0, l = 0;
        long res = 0;
        for (int r = 0; r < n; r++) {
            if (cnt.getOrDefault(arr[r], 0) == 0) unique++;
            cnt.merge(arr[r], 1, Integer::sum);
            while (unique > k) {
                cnt.merge(arr[l], -1, Integer::sum);
                if (cnt.get(arr[l]) == 0) unique--;
                l++;
            }
            res += r - l + 1;
        }
        return res;
    }
    int findArrayUniquenessMedian(int[] arr) {
        this.arr = arr;
        n = arr.length;
        long total = (long) n * (n + 1) / 2;
        long target = (total - 1) / 2;
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (countLe(mid) > target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

