            string key = "" + s.front() + s.back();
            buckets[key].push_back(x);
        }
        int best = -1;
        for (auto& [k, vals] : buckets) {
            if (vals.size() >= 2) {
                sort(vals.begin(), vals.end(), greater<int>());
                best = max(best, vals[0] + vals[1]);
            }
        }
        return best;
    }
};

class Solution {
    int findMinNumMoves(String[] grid) {
        int n = grid.length, m = grid[0].length();
        int rowCost = 0;
        for (String r : grid) {
            int b = 0, w = 0;
            for (char c : r.toCharArray()) if (c == 'B') b++; else w++;
            rowCost += Math.min(b, w);
        }
        int colCost = 0;
        for (int j = 0; j < m; j++) {
            int b = 0, w = 0;
            for (int i = 0; i < n; i++) if (grid[i].charAt(j) == 'B') b++; else w++;
            colCost += Math.min(b, w);
        }
        return Math.min(rowCost, colCost);
    }
}

