            for (char c : r) if (c == 'B') b++; else w++;
            rowCost += min(b, w);
        }
        int colCost = 0;
        for (int j = 0; j < m; j++) {
            int b = 0, w = 0;
            for (int i = 0; i < n; i++) if (grid[i][j] == 'B') b++; else w++;
            colCost += min(b, w);
        }
        return min(rowCost, colCost);
    }
};

class Solution {
    int findMinimumCost(int[] A, int X, int Y) {
        int n = A.length;
        if (n == 0) return 0;
        int[] dp = new int[n + 1];
        dp[1] = Math.min(X, Y);
        for (int i = 2; i <= n; i++) dp[i] = Math.min(dp[i - 1] + X, dp[i - 2] + Y);
        return dp[n];
    }
}

