    int findMinimumCost(vector<int>& A, int X, int Y) {
        int n = A.size();
        if (n == 0) return 0;
        vector<int> dp(n + 1, 0);
        dp[1] = min(X, Y);
        for (int i = 2; i <= n; i++) dp[i] = min(dp[i - 1] + X, dp[i - 2] + Y);
        return dp[n];
    }
};

from typing import List

def frogGame(blocks: List[int]) -> int:
    n = len(blocks)
    left = [1] * n
    for i in range(1, n):
        if blocks[i] >= blocks[i - 1]:
            left[i] = left[i - 1] + 1
    right = [1] * n
    for i in range(n - 2, -1, -1):
        if blocks[i] >= blocks[i + 1]:
            right[i] = right[i + 1] + 1
    return max(left[i] + right[i] - 1 for i in range(n))

class Solution {
    int frogGame(int[] blocks) {
        int n = blocks.length;
        int[] left = new int[n], right = new int[n];
        Arrays.fill(left, 1);
        Arrays.fill(right, 1);
        for (int i = 1; i < n; i++) if (blocks[i] >= blocks[i - 1]) left[i] = left[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (blocks[i] >= blocks[i + 1]) right[i] = right[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, left[i] + right[i] - 1);
        return best;
    }
}

