def getMaxOrSum(arr: List[int], k: int) -> int:
    n = len(arr)
    # 前缀 OR 和后缀 OR
    pre = [0] * (n + 1)
    suf = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] | arr[i]
    for i in range(n - 1, -1, -1):
        suf[i] = suf[i + 1] | arr[i]
    best = 0
    for i in range(n):
        cur = (arr[i] << k) | pre[i] | suf[i + 1]
        if cur > best:
            best = cur
    return best

