        for (int i = n - 1; i >= 0; i--) suf[i] = suf[i + 1] | arr[i];
        long best = 0;
        for (int i = 0; i < n; i++) {
            long cur = ((long) arr[i] << k) | pre[i] | suf[i + 1];
            if (cur > best) best = cur;
