class Solution {
    int getMinimumTime(String[] schedule, int k) {
        int n = schedule.length;
        List<int[]> rowCosts = new ArrayList<>();
        for (String row : schedule) {
            int m = row.length();
            List<Integer> ones = new ArrayList<>();
            for (int i = 0; i < m; i++) if (row.charAt(i) == '1') ones.add(i);
            int c = ones.size();
            int[] rc = new int[c + 1];
            for (int j = 0; j <= c; j++) {
                if (j >= c) rc[j] = 0;
                else {
                    int best = Integer.MAX_VALUE;
                    for (int a = 0; a <= j; a++) {
                        int b = j - a;
                        int L = ones.get(a), R = ones.get(c - 1 - b);
                        best = Math.min(best, R - L + 1);
                    }
                    rc[j] = best;
                }
            }
            rowCosts.add(rc);
        }
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[k + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int[] rc : rowCosts) {
            int[] nd = new int[k + 1];
            Arrays.fill(nd, INF);
            for (int j = 0; j <= k; j++) {
                if (dp[j] == INF) continue;
                for (int s = 0; s < rc.length && j + s <= k; s++) {
                    nd[j + s] = Math.min(nd[j + s], dp[j] + rc[s]);
                }
            }
            dp = nd;
        }
        int best = INF;
        for (int v : dp) best = Math.min(best, v);
        return best;
    }
}

