from typing import List

def greatSubsequences(A: List[int], queries: List[List[int]]) -> int:
    MOD = 10**9 + 7
    A = list(A)
    total = 0
    for x, y in queries:
        A[x - 1] = y
        # 朴素：枚举所有子集，O(2^n)；n ≤ 20 时可行
        n = len(A)
        cnt = 0
        for mask in range(1, 1 << n):
            g = 0
            for i in range(n):
                if mask & (1 << i):
                    g = gcd(g, A[i])
            if g > 1:
                cnt += 1
        total = (total + cnt) % MOD
    return total

class Solution {
    int greatSubsequences(int[] A, int[][] queries) {
        int MOD = 1_000_000_007;
        int[] arr = A.clone();
        long total = 0;
        int n = arr.length;
        for (int[] q : queries) {
            arr[q[0] - 1] = q[1];
            long cnt = 0;
            for (int mask = 1; mask < (1 << n); mask++) {
                int g = 0;
                for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) g = gcd(g, arr[i]);
                if (g > 1) cnt++;
            }
            total = (total + cnt) % MOD;
        }
        return (int) total;
    }
    int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

