};

import java.util.*;

class Solution {
    int handmadeItem(int[] T) {
        long MOD = 1_000_000_000L;
        int n = T.length;
        int[] s = T.clone();
        Arrays.sort(s);
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + s[i];
        long total = 0;
        for (int v : T) {
            int idx = upperBound(s, v);
            long contrib = pref[idx] + (long) (n - idx) * v;
            total = (total + contrib) % MOD;
        }
        return (int) total;
    }
    int upperBound(int[] a, int t) {
        int l = 0, r = a.length;
        while (l < r) { int m = (l + r) >>> 1; if (a[m] <= t) l = m + 1; else r = m; }
        return l;
    }
}

