        sort(s.begin(), s.end());
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + s[i];
        long long total = 0;
        for (int v : T) {
            int idx = upper_bound(s.begin(), s.end(), v) - s.begin();
            long long contrib = pref[idx] + (long long) (n - idx) * v;
            total = (total + contrib) % MOD;
        }
        return (int) total;
    }
};

class MyQueue:
    def __init__(self):
        self.inStack = []
        self.outStack = []
    def push(self, x: int) -> None:
        self.inStack.append(x)
    def _shift(self):
        if not self.outStack:
            while self.inStack:
                self.outStack.append(self.inStack.pop())
    def pop(self) -> int:
        self._shift()
        return self.outStack.pop()
    def peek(self) -> int:
        self._shift()
        return self.outStack[-1]
    def empty(self) -> bool:
        return not self.inStack and not self.outStack

