    public void push(int x) { inStack.push(x); }
    void shift() { if (outStack.isEmpty()) while (!inStack.isEmpty()) outStack.push(inStack.pop()); }
    public int pop() { shift(); return outStack.pop(); }
    public int peek() { shift(); return outStack.peek(); }
    public boolean empty() { return inStack.isEmpty() && outStack.isEmpty(); }
}

