    void push(int x) { inStack.push(x); }
    void shift() { if (outStack.empty()) while (!inStack.empty()) { outStack.push(inStack.top()); inStack.pop(); } }
    int pop() { shift(); int v = outStack.top(); outStack.pop(); return v; }
    int peek() { shift(); return outStack.top(); }
    bool empty() { return inStack.empty() && outStack.empty(); }
};

import java.util.*;

class Solution {
    String[] runInMemorySql(String csv, String[] commands) {
        String[] lines = csv.split("\n");
        String[] cols = lines[0].split(",");
        List<Map<String, String>> table = new ArrayList<>();
        for (int i = 1; i < lines.length; i++) {
            String[] vals = lines[i].split(",");
            Map<String, String> row = new LinkedHashMap<>();
            for (int j = 0; j < cols.length && j < vals.length; j++) row.put(cols[j], vals[j]);
            table.add(row);
        }
        List<String> out = new ArrayList<>();
        for (String cmd : commands) {
            if (cmd.startsWith("SELECT")) {
                String[] parts = cmd.substring(7).split(" WHERE ");
                String[] sel = parts[0].split(",");
                String[] kv = parts[1].split("=");
                for (Map<String, String> row : table) {
                    if (kv[1].equals(row.get(kv[0]))) {
                        StringBuilder sb = new StringBuilder();
                        for (int i = 0; i < sel.length; i++) {
                            if (i > 0) sb.append(",");
                            sb.append(row.getOrDefault(sel[i], ""));
                        }
                        out.add(sb.toString());
                    }
                }
            } else if (cmd.startsWith("INSERT")) {
                String[] vals = cmd.substring(7).split(",");
                Map<String, String> row = new LinkedHashMap<>();
                for (int j = 0; j < cols.length && j < vals.length; j++) row.put(cols[j], vals[j]);
                table.add(row);
            } else if (cmd.startsWith("DELETE")) {
                String[] kv = cmd.substring("DELETE WHERE ".length()).split("=");
                table.removeIf(row -> kv[1].equals(row.get(kv[0])));
            }
        }
        return out.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> split(const string& s, char d) {
        vector<string> r;
        stringstream ss(s);
        string t;
        while (getline(ss, t, d)) r.push_back(t);
        return r;
    }
    vector<string> runInMemorySql(string csv, vector<string>& commands) {
        auto lines = split(csv, '\n');
        auto cols = split(lines[0], ',');
        vector<map<string, string>> table;
        for (size_t i = 1; i < lines.size(); i++) {
            auto vals = split(lines[i], ',');
            map<string, string> row;
            for (size_t j = 0; j < cols.size() && j < vals.size(); j++) row[cols[j]] = vals[j];
            table.push_back(row);
        }
        vector<string> out;
        for (auto& cmd : commands) {
            if (cmd.find("SELECT") == 0) {
                auto parts = split(cmd.substr(7), ' ');
                // Simplified: SELECT cols WHERE col=val
                auto sel = split(parts[0], ',');
                size_t wIdx = cmd.find(" WHERE ");
                auto kv = split(cmd.substr(wIdx + 7), '=');
                for (auto& row : table) {
                    if (row[kv[0]] == kv[1]) {
                        string line;
                        for (size_t i = 0; i < sel.size(); i++) {
                            if (i > 0) line += ",";
                            line += row[sel[i]];
                        }
                        out.push_back(line);
                    }
                }
            } else if (cmd.find("INSERT") == 0) {
                auto vals = split(cmd.substr(7), ',');
                map<string, string> row;
                for (size_t j = 0; j < cols.size() && j < vals.size(); j++) row[cols[j]] = vals[j];
                table.push_back(row);
            } else if (cmd.find("DELETE") == 0) {
                auto kv = split(cmd.substr(13), '=');
                table.erase(remove_if(table.begin(), table.end(), [&](auto& r) { return r[kv[0]] == kv[1]; }), table.end());
            }
        }
        return out;
    }
};

