def longestPathWithDifferentAdjacentCharacters(parent: List[int], s: str) -> int:
    sys.setrecursionlimit(200000)
    n = len(parent)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parent[i]].append(i)
    ans = 1
    def dfs(u):
        nonlocal ans
        top1 = top2 = 0
        for v in children[u]:
            d = dfs(v)
            if s[v] != s[u]:
                if d > top1:
                    top2 = top1; top1 = d
                elif d > top2:
                    top2 = d
        ans = max(ans, top1 + top2 + 1)
        return top1 + 1
    dfs(0)
    return ans

