def maxNumOfMoves(A: List[int]) -> int:
    n = len(A)
    if n < 2: return 0
    candidates = {A[0] + A[1], A[-2] + A[-1], A[0] + A[-1]}
    best = 0
    for s in candidates:
        l, r = 0, n - 1
        cnt = 0
        while r - l >= 1:
            if A[l] + A[l + 1] == s:
                l += 2; cnt += 1
            elif A[r - 1] + A[r] == s:
                r -= 2; cnt += 1
            elif A[l] + A[r] == s:
                l += 1; r -= 1; cnt += 1
            else:
                break
        best = max(best, cnt)
    return best

