class Solution {
    int maxNumOfMoves(int[] A) {
        int n = A.length;
        if (n < 2) return 0;
        Set<Integer> cand = new HashSet<>();
        cand.add(A[0] + A[1]);
        cand.add(A[n - 2] + A[n - 1]);
        cand.add(A[0] + A[n - 1]);
        int best = 0;
        for (int s : cand) {
            int l = 0, r = n - 1, cnt = 0;
            while (r - l >= 1) {
                if (A[l] + A[l + 1] == s) { l += 2; cnt++; }
                else if (A[r - 1] + A[r] == s) { r -= 2; cnt++; }
                else if (A[l] + A[r] == s) { l++; r--; cnt++; }
                else break;
            }
            best = Math.max(best, cnt);
        }
        return best;
    }
}

