def maxNumOfProducedCars(H: List[int], X: int, Y: int) -> int:
    sorted_h = sorted(H)
    cnt = 0
    remX, remY = X, Y
    for h in sorted_h:
        if remX >= remY:
            if h <= remX: remX -= h; cnt += 1
            elif h <= remY: remY -= h; cnt += 1
        else:
            if h <= remY: remY -= h; cnt += 1
            elif h <= remX: remX -= h; cnt += 1
    return cnt

