        for (int h : s) {
            if (remX >= remY) {
                if (h <= remX) { remX -= h; cnt++; }
                else if (h <= remY) { remY -= h; cnt++; }
            } else {
                if (h <= remY) { remY -= h; cnt++; }
                else if (h <= remX) { remX -= h; cnt++; }
            }
        }
        return cnt;
    }
