def maxNumberOfOrdersFulfilled(D: List[int], C: List[int], P: int) -> int:
    orders = sorted(zip(D, C))
    cnt = 0
    total = 0
    for d, c in orders:
        if total + c <= P:
            total += c
            cnt += 1
        else:
            break
    return cnt

import java.util.*;

class Solution {
    int maxNumberOfOrdersFulfilled(int[] D, int[] C, long P) {
        int n = D.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> D[a] - D[b]);
        int cnt = 0;
        long total = 0;
        for (int i : idx) {
            if (total + C[i] <= P) { total += C[i]; cnt++; }
            else break;
        }
        return cnt;
    }
}

