class Solution {
    long maximizeSumOfTwoNonOverlappingFragments(int[] A, int K, int L) {
        int n = A.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + A[i];
        long best = Long.MIN_VALUE;
        for (int i = 0; i + K <= n; i++) {
            for (int j = 0; j + L <= n; j++) {
                int s1 = i, e1 = i + K - 1;
                int s2 = j, e2 = j + L - 1;
                int ol = Math.min(e1, e2) - Math.max(s1, s2) + 1;
                long sum = pref[e1 + 1] - pref[s1] + pref[e2 + 1] - pref[s2];
                if (ol > 0) {
                    long over = pref[Math.min(e1, e2) + 1] - pref[Math.max(s1, s2)];
                    sum -= 3 * over;
                }
                best = Math.max(best, sum);
            }
        }
        return best;
    }
}

