};

import java.util.*;

class Solution {
    int maximizeTypesAfterFreeingShelves(int[] A, int R) {
        int n = A.length;
        Map<Integer, Integer> full = new HashMap<>(), win = new HashMap<>();
        for (int x : A) full.merge(x, 1, Integer::sum);
        for (int i = 0; i < R; i++) win.merge(A[i], 1, Integer::sum);
        int best = 0;
        for (int i = 0; i <= n - R; i++) {
            int cnt = 0;
            for (var e : full.entrySet()) if (e.getValue() > win.getOrDefault(e.getKey(), 0)) cnt++;
            best = Math.max(best, cnt);
            if (i + R < n) {
                win.merge(A[i + R], 1, Integer::sum);
                int v = win.get(A[i]);
                if (v == 1) win.remove(A[i]);
                else win.put(A[i], v - 1);
            }
        }
        return best;
    }
}

class Solution {
public:
    int maximizeTypesAfterFreeingShelves(vector<int>& A, int R) {
        int n = A.size();
        unordered_map<int, int> full, win;
        for (int x : A) full[x]++;
        for (int i = 0; i < R; i++) win[A[i]]++;
        int best = 0;
        for (int i = 0; i <= n - R; i++) {
            int cnt = 0;
            for (auto& [k, v] : full) if (v > (win.count(k) ? win[k] : 0)) cnt++;
            best = max(best, cnt);
            if (i + R < n) {
                win[A[i + R]]++;
                if (--win[A[i]] == 0) win.erase(A[i]);
            }
        }
        return best;
    }
};

