def maxCells(A: List[str]) -> int:
    n = len(A)
    m = len(A[0])
    # 每行 / 每列最长连续 '.'
    def max_runs(strs):
        runs = []
        for s in strs:
            best = cur = 0
            for c in s:
                if c == '.':
                    cur += 1
                    best = max(best, cur)
                else:
                    cur = 0
            runs.append(best)
        return runs
    row_runs = max_runs(A)
    cols = [''.join(A[i][j] for i in range(n)) for j in range(m)]
    col_runs = max_runs(cols)
    # 取两条最大（不同行 / 不同列；为简化 + 安全取 top 2 各方向）
    rows_sorted = sorted(row_runs, reverse=True)
    cols_sorted = sorted(col_runs, reverse=True)
    best = 0
    if len(rows_sorted) >= 2: best = max(best, rows_sorted[0] + rows_sorted[1])
    if len(cols_sorted) >= 2: best = max(best, cols_sorted[0] + cols_sorted[1])
    # 一行 + 一列
    if rows_sorted and cols_sorted:
        best = max(best, rows_sorted[0] + cols_sorted[0])
    return best

import java.util.*;

class Solution {
    int[] maxRuns(String[] strs) {
        int[] out = new int[strs.length];
        for (int i = 0; i < strs.length; i++) {
            int best = 0, cur = 0;
            for (char c : strs[i].toCharArray()) {
                if (c == '.') { cur++; best = Math.max(best, cur); }
                else cur = 0;
            }
            out[i] = best;
        }
        return out;
    }
    int maxCells(String[] A) {
        int n = A.length, m = A[0].length();
        int[] rowRuns = maxRuns(A);
        String[] cols = new String[m];
        for (int j = 0; j < m; j++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(A[i].charAt(j));
            cols[j] = sb.toString();
        }
        int[] colRuns = maxRuns(cols);
        Arrays.sort(rowRuns);
        Arrays.sort(colRuns);
        int best = 0;
        if (rowRuns.length >= 2) best = Math.max(best, rowRuns[n - 1] + rowRuns[n - 2]);
        if (colRuns.length >= 2) best = Math.max(best, colRuns[m - 1] + colRuns[m - 2]);
        if (rowRuns.length > 0 && colRuns.length > 0) best = Math.max(best, rowRuns[n - 1] + colRuns[m - 1]);
        return best;
    }
}

class Solution {
public:
    vector<int> maxRuns(vector<string>& strs) {
        vector<int> out;
        for (auto& s : strs) {
            int best = 0, cur = 0;
            for (char c : s) {
                if (c == '.') { cur++; best = max(best, cur); }
                else cur = 0;
            }
            out.push_back(best);
        }
        return out;
    }
    int maxCells(vector<string>& A) {
        int n = A.size(), m = A[0].size();
        auto rowRuns = maxRuns(A);
        vector<string> cols(m, string(n, '.'));
        for (int j = 0; j < m; j++) for (int i = 0; i < n; i++) cols[j][i] = A[i][j];
        auto colRuns = maxRuns(cols);
        sort(rowRuns.begin(), rowRuns.end());
        sort(colRuns.begin(), colRuns.end());
        int best = 0;
        if ((int) rowRuns.size() >= 2) best = max(best, rowRuns[n - 1] + rowRuns[n - 2]);
        if ((int) colRuns.size() >= 2) best = max(best, colRuns[m - 1] + colRuns[m - 2]);
        if (!rowRuns.empty() && !colRuns.empty()) best = max(best, rowRuns[n - 1] + colRuns[m - 1]);
        return best;
    }
};

def maximumNumberPossible(s: str, k: int) -> str:
    arr = list(s)
    non5 = sum(1 for c in arr if c != '5')
    if k > non5:
        return "IMPOSSIBLE"
    # 从左到右替换非 5 且 < 5 的，再替换非 5 且 ≥ 5（实际上这样会减小）
    # 正确做法：从左到右，凡 < 5 的（最先变大效益最大）先替换
    for i in range(len(arr)):
        if k == 0: break
        if arr[i] != '5' and arr[i] < '5':
            arr[i] = '5'
            k -= 1
    # 若还有 k，从右到左替换 > 5 的（减小最少）
    for i in range(len(arr) - 1, -1, -1):
        if k == 0: break
        if arr[i] != '5':
            arr[i] = '5'
            k -= 1
    return ''.join(arr)

class Solution {
    String maximumNumberPossible(String s, int k) {
        char[] arr = s.toCharArray();
        int non5 = 0;
        for (char c : arr) if (c != '5') non5++;
        if (k > non5) return "IMPOSSIBLE";
        for (int i = 0; i < arr.length && k > 0; i++) {
            if (arr[i] != '5' && arr[i] < '5') { arr[i] = '5'; k--; }
        }
        for (int i = arr.length - 1; i >= 0 && k > 0; i--) {
            if (arr[i] != '5') { arr[i] = '5'; k--; }
        }
        return new String(arr);
    }
}

