from bisect import bisect_right

def minNumLetters(S: str) -> int:
    tails = []
    for c in S:
        idx = bisect_right(tails, c)
        if idx == len(tails):
            tails.append(c)
        else:
            tails[idx] = c
    return len(S) - len(tails)

import java.util.*;

class Solution {
    int minNumLetters(String S) {
        List<Character> tails = new ArrayList<>();
        for (char c : S.toCharArray()) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails.get(mid) <= c) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(c);
            else tails.set(lo, c);
        }
        return S.length() - tails.size();
    }
}

class Solution {
public:
    int minNumLetters(string S) {
        vector<char> tails;
        for (char c : S) {
            auto it = upper_bound(tails.begin(), tails.end(), c);
            if (it == tails.end()) tails.push_back(c);
            else *it = c;
        }
        return S.size() - tails.size();
    }
};

class Solution {
    int minNumTiles(int[] A) {
        int n = A.length / 2;
        if (n == 0) return 0;
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        int best = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (A[2 * j + 1] == A[2 * i]) dp[i] = Math.max(dp[i], dp[j] + 1);
            }
            best = Math.max(best, dp[i]);
        }
        return n - best;
    }
}

