import java.math.BigInteger;

class Solution {
    int minimizeDifference(String S, String T) {
        int n = S.length();
        BigInteger curDiff = BigInteger.ZERO;
        BigInteger TEN = BigInteger.TEN;
        BigInteger[] pow = new BigInteger[n];
        pow[n - 1] = BigInteger.ONE;
        for (int i = n - 2; i >= 0; i--) pow[i] = pow[i + 1].multiply(TEN);
        for (int i = 0; i < n; i++) {
            int ds = S.charAt(i) - T.charAt(i);
            curDiff = curDiff.add(pow[i].multiply(BigInteger.valueOf(ds)));
        }
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            int ds = S.charAt(i) - T.charAt(i);
            if (ds == 0) continue;
            BigInteger newDiff = curDiff.subtract(pow[i].multiply(BigInteger.valueOf(2L * ds)));
            if (newDiff.abs().compareTo(curDiff.abs()) < 0) {
                curDiff = newDiff;
                swaps++;
            }
        }
        return swaps;
    }
}

class Solution {
public:
    int minimizeDifference(string S, string T) {
        int n = S.size();
        // 用 double 估算（n ≤ 18 安全），实际需 BigInt
        double curDiff = 0;
        vector<double> pow(n);
        pow[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) pow[i] = pow[i + 1] * 10;
        for (int i = 0; i < n; i++) curDiff += (S[i] - T[i]) * pow[i];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            int ds = S[i] - T[i];
            if (ds == 0) continue;
            double newDiff = curDiff - 2.0 * ds * pow[i];
            if (abs(newDiff) < abs(curDiff)) {
                curDiff = newDiff;
                swaps++;
            }
        }
        return swaps;
    }
};

