def minimumCarsToRemove(weights: List[int], capacity: int) -> int:
    removed = 0
    prev = -1
    for w in weights:
        if prev == -1:
            prev = w
        else:
            if prev + w > capacity:
                # 移除当前或前一辆中较重的（保留轻的）
                if w >= prev:
                    removed += 1
                else:
                    removed += 1
                    prev = w
            else:
                prev = w
    return removed

class Solution {
