        int removed = 0, prev = -1;
        for (int w : weights) {
            if (prev == -1) prev = w;
            else {
                if (prev + w > capacity) {
                    removed++;
                    if (w < prev) prev = w;
                } else prev = w;
            }
        }
        return removed;
    }
}

