class Solution {
    int minimumSwapsRedBalls(String s) {
        int n = s.length(), R = 0;
        for (char c : s.toCharArray()) if (c == 'R') R++;
        if (R == 0 || R == n) return 0;
        int cur = 0;
        for (int i = 0; i < R; i++) if (s.charAt(i) == 'W') cur++;
        int best = cur;
        for (int i = R; i < n; i++) {
            if (s.charAt(i) == 'W') cur++;
            if (s.charAt(i - R) == 'W') cur--;
            best = Math.min(best, cur);
        }
        return best;
    }
}

