    # 链头：其 start 不在任何 end 中
    end_set = {r[-1] for r in records}
    head_idx = None
    for i, r in enumerate(records):
        if r[0] not in end_set:
            head_idx = i
            break
    if head_idx is None:
        head_idx = 0
    out = [records[head_idx]]
    start_to_idx = {r[0]: i for i, r in enumerate(records)}
    cur = head_idx
    visited = {cur}
    while True:
        end = records[cur][-1]
        if end in start_to_idx and start_to_idx[end] not in visited:
            cur = start_to_idx[end]
            visited.add(cur)
            out.append(records[cur])
        else:
            break
    return out

import java.util.*;

class Solution {
    String[][] orderRecordsByMatching(String[][] records) {
        Map<String, Integer> startToIdx = new HashMap<>();
        Set<String> ends = new HashSet<>();
        for (int i = 0; i < records.length; i++) {
            startToIdx.put(records[i][0], i);
            ends.add(records[i][records[i].length - 1]);
        }
        int head = 0;
        for (int i = 0; i < records.length; i++) {
            if (!ends.contains(records[i][0])) { head = i; break; }
        }
        List<String[]> out = new ArrayList<>();
        Set<Integer> visited = new HashSet<>();
        int cur = head;
        out.add(records[cur]);
        visited.add(cur);
        while (true) {
            String end = records[cur][records[cur].length - 1];
            Integer next = startToIdx.get(end);
            if (next == null || visited.contains(next)) break;
            cur = next;
            visited.add(cur);
            out.add(records[cur]);
        }
        return out.toArray(new String[0][]);
    }
}

class Solution {
public:
    vector<vector<string>> orderRecordsByMatching(vector<vector<string>>& records) {
        unordered_map<string, int> startToIdx;
        unordered_set<string> ends;
        for (size_t i = 0; i < records.size(); i++) {
            startToIdx[records[i][0]] = i;
            ends.insert(records[i].back());
        }
        int head = 0;
        for (size_t i = 0; i < records.size(); i++) {
            if (!ends.count(records[i][0])) { head = i; break; }
        }
        vector<vector<string>> out;
        unordered_set<int> visited;
        int cur = head;
        out.push_back(records[cur]);
        visited.insert(cur);
        while (true) {
            string end = records[cur].back();
            auto it = startToIdx.find(end);
            if (it == startToIdx.end() || visited.count(it->second)) break;
            cur = it->second;
            visited.insert(cur);
            out.push_back(records[cur]);
        }
        return out;
    }
};

from collections import deque
from typing import List

def pathInGrid(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[n - 1][m - 1] == 1:
        return -1
    q = deque([(0, 0, 0)])
    visited = {(0, 0)}
    while q:
        x, y, d = q.popleft()
        if x == n - 1 and y == m - 1:
            return d
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny, d + 1))
    return -1

import java.util.*;

class Solution {
    int pathInGrid(int[][] grid) {
        int n = grid.length, m = grid[0].length;
        if (grid[0][0] == 1 || grid[n - 1][m - 1] == 1) return -1;
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{0, 0, 0});
        boolean[][] vis = new boolean[n][m];
        vis[0][0] = true;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == n - 1 && cur[1] == m - 1) return cur[2];
            for (int[] d : dirs) {
                int nx = cur[0] + d[0], ny = cur[1] + d[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 0 && !vis[nx][ny]) {
                    vis[nx][ny] = true;
                    q.offer(new int[]{nx, ny, cur[2] + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int pathInGrid(vector<vector<int>>& grid) {
        int n = grid.size(), m = grid[0].size();
        if (grid[0][0] == 1 || grid[n - 1][m - 1] == 1) return -1;
        queue<tuple<int,int,int>> q;
        q.push({0, 0, 0});
        vector<vector<bool>> vis(n, vector<bool>(m, false));
        vis[0][0] = true;
        int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.empty()) {
            auto [x, y, d] = q.front(); q.pop();
            if (x == n - 1 && y == m - 1) return d;
            for (auto& dr : dirs) {
                int nx = x + dr[0], ny = y + dr[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 0 && !vis[nx][ny]) {
                    vis[nx][ny] = true;
                    q.push({nx, ny, d + 1});
                }
            }
        }
        return -1;
    }
};

