def prepareNotification(template: str, data: Dict[str, str]) -> str:
    return re.sub(r'\{(\w+)\}', lambda m: data.get(m.group(1), ''), template)

import java.util.*;
import java.util.regex.*;

class Solution {
    String prepareNotification(String template, Map<String, String> data) {
        Matcher m = Pattern.compile("\\{(\\w+)\\}").matcher(template);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            m.appendReplacement(sb, data.getOrDefault(m.group(1), ""));
        }
        m.appendTail(sb);
        return sb.toString();
    }
}

