class Solution {
public:
    string prepareNotification(string tmpl, map<string, string>& data) {
        regex re("\\{(\\w+)\\}");
        string out;
        auto begin = sregex_iterator(tmpl.begin(), tmpl.end(), re);
        auto end = sregex_iterator();
        size_t last = 0;
        for (auto it = begin; it != end; ++it) {
            out += tmpl.substr(last, it->position() - last);
            auto it_data = data.find((*it)[1].str());
            if (it_data != data.end()) out += it_data->second;
            last = it->position() + it->length();
        }
        out += tmpl.substr(last);
        return out;
    }
};

