def productOfXorOfAllGoodPairs(a: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(a)
    prod = 1
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] + a[j]) % 2 == 0:
                prod = prod * (a[i] ^ a[j]) % MOD
    return prod

class Solution {
    int productOfXorOfAllGoodPairs(int[] a) {
        long MOD = 1_000_000_007L;
        long prod = 1;
        for (int i = 0; i < a.length; i++) for (int j = i + 1; j < a.length; j++) {
            if ((a[i] + a[j]) % 2 == 0) prod = prod * (a[i] ^ a[j]) % MOD;
        }
        return (int) prod;
    }
}

class Solution {
public:
    int productOfXorOfAllGoodPairs(vector<int>& a) {
        long long MOD = 1'000'000'007LL;
        long long prod = 1;
        for (size_t i = 0; i < a.size(); i++) for (size_t j = i + 1; j < a.size(); j++) {
            if ((a[i] + a[j]) % 2 == 0) prod = prod * (a[i] ^ a[j]) % MOD;
        }
        return (int) prod;
    }
};

