class Solution {
    String[] rankOpenBusinesses(String[][] businesses) {
        List<String[]> open = new ArrayList<>();
        for (String[] b : businesses) if ("open".equals(b[1])) open.add(b);
        open.sort((a, b) -> {
            int c = Integer.parseInt(b[2]) - Integer.parseInt(a[2]);
            return c != 0 ? c : a[0].compareTo(b[0]);
        });
        String[] out = new String[open.size()];
        for (int i = 0; i < open.size(); i++) out[i] = open.get(i)[0];
        return out;
    }
}

