public:
    vector<string> rankOpenBusinesses(vector<vector<string>>& businesses) {
        vector<vector<string>> open;
        for (auto& b : businesses) if (b[1] == "open") open.push_back(b);
        sort(open.begin(), open.end(), [](auto& a, auto& b) {
            int sa = stoi(a[2]), sb = stoi(b[2]);
            if (sa != sb) return sa > sb;
            return a[0] < b[0];
        });
        vector<string> out;
        for (auto& b : open) out.push_back(b[0]);
        return out;
    }
};

