class Solution {
    int reorderRoutes(int n, int[][] connections) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : connections) {
            adj.get(e[0]).add(new int[]{e[1], 1});
            adj.get(e[1]).add(new int[]{e[0], 0});
        }
        boolean[] vis = new boolean[n];
        Deque<Integer> q = new ArrayDeque<>();
        q.offer(0);
        vis[0] = true;
        int ans = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] e : adj.get(u)) {
                if (!vis[e[0]]) {
                    vis[e[0]] = true;
                    ans += e[1];
                    q.offer(e[0]);
                }
            }
        }
        return ans;
    }
}

class Solution {
public:
    int reorderRoutes(int n, vector<vector<int>>& connections) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : connections) {
            adj[e[0]].push_back({e[1], 1});
            adj[e[1]].push_back({e[0], 0});
        }
        vector<bool> vis(n, false);
        queue<int> q;
        q.push(0);
        vis[0] = true;
        int ans = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& [v, d] : adj[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    ans += d;
                    q.push(v);
                }
            }
        }
        return ans;
    }
};

from collections import defaultdict
from typing import List

def retainTopKValues(records: List[List[int]], k: int) -> List[List[int]]:
    # records[i] = [group, value]
    groups = defaultdict(list)
    for g, v in records:
        groups[g].append(v)
    out = []
    for g, vals in groups.items():
        vals.sort(reverse=True)
        for v in vals[:k]:
            out.append([g, v])
    return out

import java.util.*;

class Solution {
    int[][] retainTopKValues(int[][] records, int k) {
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int[] r : records) groups.computeIfAbsent(r[0], x -> new ArrayList<>()).add(r[1]);
        List<int[]> out = new ArrayList<>();
        for (var e : groups.entrySet()) {
            List<Integer> v = e.getValue();
            v.sort(Collections.reverseOrder());
            for (int i = 0; i < Math.min(k, v.size()); i++) out.add(new int[]{e.getKey(), v.get(i)});
        }
        return out.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> retainTopKValues(vector<vector<int>>& records, int k) {
        unordered_map<int, vector<int>> groups;
        for (auto& r : records) groups[r[0]].push_back(r[1]);
        vector<vector<int>> out;
        for (auto& [g, vals] : groups) {
            sort(vals.begin(), vals.end(), greater<int>());
            for (int i = 0; i < min(k, (int) vals.size()); i++) out.push_back({g, vals[i]});
        }
        return out;
    }
};

