def shortestPossibleLength(s: str) -> int:
    stack = []
    for c in s:
        if stack and stack[-1] == c:
            stack.pop()
        else:
            stack.append(c)
    return len(stack)

class Solution {
    int shortestPossibleLength(String s) {
        StringBuilder st = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (st.length() > 0 && st.charAt(st.length() - 1) == c) st.deleteCharAt(st.length() - 1);
            else st.append(c);
        }
        return st.length();
    }
}

class Solution {
public:
    int shortestPossibleLength(string s) {
        string st;
        for (char c : s) {
            if (!st.empty() && st.back() == c) st.pop_back();
            else st += c;
        }
        return st.size();
    }
};

