def skyscraper(heights: List[int]) -> int:
    visible_left = 0
    cur = 0
    for h in heights:
        if h > cur:
            visible_left += 1
            cur = h
    visible_right = 0
    cur = 0
    for h in reversed(heights):
        if h > cur:
            visible_right += 1
            cur = h
    return visible_left + visible_right

class Solution {
    int skyscraper(int[] heights) {
        int vL = 0, cur = 0;
        for (int h : heights) if (h > cur) { vL++; cur = h; }
        int vR = 0; cur = 0;
        for (int i = heights.length - 1; i >= 0; i--) if (heights[i] > cur) { vR++; cur = heights[i]; }
        return vL + vR;
    }
}

