public:
    int skyscraper(vector<int>& heights) {
        int vL = 0, cur = 0;
        for (int h : heights) if (h > cur) { vL++; cur = h; }
        int vR = 0; cur = 0;
        for (int i = heights.size() - 1; i >= 0; i--) if (heights[i] > cur) { vR++; cur = heights[i]; }
        return vL + vR;
    }
};

