def sumWithTiles(arr: List[int], K: int) -> int:
    n = len(arr)
    if K > n: return sum(arr)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + arr[i]
    best = 0
    for i in range(n - K + 1):
        best = max(best, pref[i + K] - pref[i])
    return best

class Solution {
    long sumWithTiles(int[] arr, int K) {
        int n = arr.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + arr[i];
        if (K > n) return pref[n];
        long best = 0;
        for (int i = 0; i + K <= n; i++) best = Math.max(best, pref[i + K] - pref[i]);
        return best;
    }
}

