def theLongestSpike(arr: List[int]) -> int:
    n = len(arr)
    if n == 0: return 0
    inc = [1] * n
    for i in range(1, n):
        if arr[i] > arr[i - 1]: inc[i] = inc[i - 1] + 1
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]: dec[i] = dec[i + 1] + 1
    return max(inc[i] + dec[i] - 1 for i in range(n))

class Solution {
    int theLongestSpike(int[] arr) {
        int n = arr.length;
        if (n == 0) return 0;
        int[] inc = new int[n], dec = new int[n];
        Arrays.fill(inc, 1); Arrays.fill(dec, 1);
        for (int i = 1; i < n; i++) if (arr[i] > arr[i - 1]) inc[i] = inc[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (arr[i] > arr[i + 1]) dec[i] = dec[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, inc[i] + dec[i] - 1);
        return best;
    }
}

