        for (int i = n - 2; i >= 0; i--) if (arr[i] > arr[i + 1]) dec[i] = dec[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = max(best, inc[i] + dec[i] - 1);
        return best;
    }
};

class Solution {
    int threePartitionArray(int[] arr) {
        long total = 0;
        for (int v : arr) total += v;
        if (total % 3 != 0) return 0;
        long target = total / 3, cur = 0;
        boolean found1 = false;
        for (int i = 0; i < arr.length; i++) {
            cur += arr[i];
            if (!found1 && cur == target) { found1 = true; cur = 0; }
            else if (found1 && cur == target && i < arr.length - 1) return 1;
        }
        return 0;
    }
}

