from bisect import bisect_right
from typing import List

def toGoodArrays(arr: List[int]) -> int:
    tails = []
    for x in arr:
        idx = bisect_right(tails, x)
        if idx == len(tails): tails.append(x)
        else: tails[idx] = x
    return len(arr) - len(tails)

import java.util.*;

class Solution {
    int toGoodArrays(int[] arr) {
        List<Integer> tails = new ArrayList<>();
        for (int x : arr) {
            int lo = 0, hi = tails.size();
            while (lo < hi) { int m = (lo + hi) >>> 1; if (tails.get(m) <= x) lo = m + 1; else hi = m; }
            if (lo == tails.size()) tails.add(x);
            else tails.set(lo, x);
        }
        return arr.length - tails.size();
    }
}

class Solution {
public:
    int toGoodArrays(vector<int>& arr) {
        vector<int> tails;
        for (int x : arr) {
            auto it = upper_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) tails.push_back(x);
            else *it = x;
        }
        return arr.size() - tails.size();
    }
};

def validMixedCaseLetters(s: str) -> bool:
    if not s.isalpha(): return False
    return any(c.isupper() for c in s) and any(c.islower() for c in s)

class Solution {
    boolean validMixedCaseLetters(String s) {
        boolean hasUp = false, hasLo = false;
        for (char c : s.toCharArray()) {
            if (!Character.isLetter(c)) return false;
            if (Character.isUpperCase(c)) hasUp = true;
            if (Character.isLowerCase(c)) hasLo = true;
        }
        return hasUp && hasLo;
    }
}

class Solution {
public:
    bool validMixedCaseLetters(string s) {
        bool hasUp = false, hasLo = false;
        for (char c : s) {
            if (!isalpha((unsigned char) c)) return false;
            if (isupper((unsigned char) c)) hasUp = true;
            if (islower((unsigned char) c)) hasLo = true;
        }
        return hasUp && hasLo;
    }
};

def wordPatternII(pattern: str, s: str) -> bool:
    def bt(i, j, mp, used):
        if i == len(pattern) and j == len(s): return True
        if i == len(pattern) or j == len(s): return False
        c = pattern[i]
        if c in mp:
            w = mp[c]
            if s.startswith(w, j):
                return bt(i + 1, j + len(w), mp, used)
            return False
        for k in range(j + 1, len(s) + 1):
            w = s[j:k]
            if w in used: continue
            mp[c] = w
            used.add(w)
            if bt(i + 1, k, mp, used): return True
            del mp[c]
            used.remove(w)
        return False
    return bt(0, 0, {}, set())

import java.util.*;

class Solution {
    boolean bt(int i, int j, String p, String s, Map<Character, String> mp, Set<String> used) {
        if (i == p.length() && j == s.length()) return true;
        if (i == p.length() || j == s.length()) return false;
        char c = p.charAt(i);
        if (mp.containsKey(c)) {
            String w = mp.get(c);
            if (s.startsWith(w, j)) return bt(i + 1, j + w.length(), p, s, mp, used);
            return false;
        }
        for (int k = j + 1; k <= s.length(); k++) {
            String w = s.substring(j, k);
            if (used.contains(w)) continue;
            mp.put(c, w);
            used.add(w);
            if (bt(i + 1, k, p, s, mp, used)) return true;
            mp.remove(c);
            used.remove(w);
        }
        return false;
    }
    boolean wordPatternII(String pattern, String s) {
        return bt(0, 0, pattern, s, new HashMap<>(), new HashSet<>());
    }
}

class Solution {
public:
    bool bt(int i, int j, string& p, string& s, unordered_map<char, string>& mp, unordered_set<string>& used) {
        if (i == (int) p.size() && j == (int) s.size()) return true;
        if (i == (int) p.size() || j == (int) s.size()) return false;
        char c = p[i];
        if (mp.count(c)) {
            string w = mp[c];
            if (s.compare(j, w.size(), w) == 0) return bt(i + 1, j + w.size(), p, s, mp, used);
            return false;
        }
        for (int k = j + 1; k <= (int) s.size(); k++) {
            string w = s.substr(j, k - j);
            if (used.count(w)) continue;
            mp[c] = w; used.insert(w);
            if (bt(i + 1, k, p, s, mp, used)) return true;
            mp.erase(c); used.erase(w);
        }
        return false;
    }
    bool wordPatternII(string pattern, string s) {
        unordered_map<char, string> mp;
        unordered_set<string> used;
        return bt(0, 0, pattern, s, mp, used);
    }
};

