        for (auto& group : movieGroups) {
            vector<double> scores;
            for (int i : group) scores.push_back(similarityScores[i]);
            sort(scores.begin(), scores.end(), greater<double>());
            double s = 0;
            for (int i = 0; i < min((int) scores.size(), k); i++) s += scores[i];
            res.push_back(s);
        }
        return res;
    }
