def break_palindrome(s: str) -> str:
    n = len(s)
    if n <= 1:
        return "IMPOSSIBLE"
    arr = list(s)
    for i in range(n // 2):
        if arr[i] != 'a':
            arr[i] = 'a'
            return "".join(arr)
    arr[-1] = 'b'
    return "".join(arr)

class Solution {
    public String breakPalindrome(String s) {
        int n = s.length();
        if (n <= 1) return "IMPOSSIBLE";
        char[] a = s.toCharArray();
        for (int i = 0; i < n / 2; i++) {
            if (a[i] != 'a') { a[i] = 'a'; return new String(a); }
        }
        a[n - 1] = 'b';
        return new String(a);
    }
}

