def count_palindromes(arr: List[str]) -> int:
    n = len(arr)
    cnt: Counter = Counter()
    for s in arr:
        cnt.update(s)
    odd_chars = sum(1 for c in cnt.values() if c % 2 == 1)
    odd_len = sum(1 for s in arr if len(s) % 2 == 1)
    if odd_chars <= odd_len:
        return n
    return n - (odd_chars - odd_len)

import java.util.*;

class Solution {
    public int countPalindromes(String[] arr) {
        int[] cnt = new int[26];
        int oddLen = 0;
        for (String s : arr) {
            for (char c : s.toCharArray()) cnt[c - 'a']++;
            if (s.length() % 2 == 1) oddLen++;
        }
        int oddChars = 0;
        for (int c : cnt) if (c % 2 == 1) oddChars++;
        if (oddChars <= oddLen) return arr.length;
        return arr.length - (oddChars - oddLen);
    }
}

