def runChatAppCommands(commands: List[str]) -> List[str]:
    class Bot:
        def reply(self, user: str, text: str):
            return None
    class EchoBot(Bot):
        name = "EchoBot"
        def reply(self, user, text):
            return f"{self.name}: {text}"
    class HelpBot(Bot):
        name = "HelpBot"
        def reply(self, user, text):
            return f"{self.name}: type 'help' for assistance" if text == "help" else None
    REGISTRY = {"EchoBot": EchoBot, "HelpBot": HelpBot}

    channels: dict = {}      # channelId -> list[str]
    active_bots: list = []   # global registered bots
    out: List[str] = []
    for cmd in commands:
        parts = cmd.split()
        op = parts[0]
        if op == "REGISTER":
            for name in parts[1:]:
                if name in REGISTRY:
                    active_bots.append(REGISTRY[name]())
        elif op == "SEND":
            ch, user = parts[1], parts[2]
            text = " ".join(parts[3:])
            channels.setdefault(ch, []).append(f"{user}: {text}")
            for bot in active_bots:
                r = bot.reply(user, text)
                if r is not None:
                    channels[ch].append(r)
        elif op == "PRINT":
            ch = parts[1]
            for msg in channels.get(ch, []):
                out.append(msg)
    return out

import java.util.*;

class Solution {
    interface Bot { String reply(String user, String text); String name(); }
    static class EchoBot implements Bot {
        public String name() { return "EchoBot"; }
        public String reply(String u, String t) { return name() + ": " + t; }
    }
    static class HelpBot implements Bot {
        public String name() { return "HelpBot"; }
        public String reply(String u, String t) {
            return "help".equals(t) ? name() + ": type 'help' for assistance" : null;
        }
    }
    String[] runChatAppCommands(String[] commands) {
        Map<String, List<String>> channels = new HashMap<>();
        List<Bot> bots = new ArrayList<>();
        List<String> out = new ArrayList<>();
        for (String cmd : commands) {
            String[] p = cmd.split(" ");
            if (p[0].equals("REGISTER")) {
                for (int i = 1; i < p.length; i++) {
                    if (p[i].equals("EchoBot")) bots.add(new EchoBot());
                    else if (p[i].equals("HelpBot")) bots.add(new HelpBot());
                }
            } else if (p[0].equals("SEND")) {
                String ch = p[1], user = p[2];
                StringBuilder sb = new StringBuilder();
                for (int i = 3; i < p.length; i++) {
                    if (i > 3) sb.append(' ');
                    sb.append(p[i]);
                }
                String text = sb.toString();
                channels.computeIfAbsent(ch, k -> new ArrayList<>()).add(user + ": " + text);
                for (Bot b : bots) {
                    String r = b.reply(user, text);
                    if (r != null) channels.get(ch).add(r);
                }
            } else if (p[0].equals("PRINT")) {
                List<String> hist = channels.get(p[1]);
                if (hist != null) out.addAll(hist);
            }
        }
        return out.toArray(new String[0]);
    }
}

