class Solution {
public:
    vector<string> runChatAppCommands(vector<string>& commands) {
        unordered_map<string, vector<string>> channels;
        vector<unique_ptr<Bot>> bots;
        vector<string> out;
        for (const string& cmd : commands) {
            stringstream ss(cmd);
            vector<string> p;
            string tok;
            while (ss >> tok) p.push_back(tok);
            if (p.empty()) continue;
            if (p[0] == "REGISTER") {
                for (size_t i = 1; i < p.size(); i++) {
                    if (p[i] == "EchoBot") bots.emplace_back(new EchoBot());
                    else if (p[i] == "HelpBot") bots.emplace_back(new HelpBot());
                }
            } else if (p[0] == "SEND") {
                string ch = p[1], user = p[2];
                string text;
                for (size_t i = 3; i < p.size(); i++) {
                    if (i > 3) text += ' ';
                    text += p[i];
                }
                channels[ch].push_back(user + ": " + text);
                for (auto& b : bots) {
                    string r = b->reply(user, text);
                    if (!r.empty()) channels[ch].push_back(r);
                }
            } else if (p[0] == "PRINT") {
                auto it = channels.find(p[1]);
                if (it != channels.end()) for (auto& m : it->second) out.push_back(m);
            }
        }
        return out;
    }
};

class Solution {
    long countValidSequences(int n, int[][] pairs) {
        int[] block = new int[n + 2];
        for (int[] p : pairs) {
            int lo = Math.min(p[0], p[1]), hi = Math.max(p[0], p[1]);
            block[hi] = Math.max(block[hi], lo);
        }
        long ans = 0;
        int l = 1;
        for (int r = 1; r <= n; r++) {
            if (block[r] >= l) l = block[r] + 1;
            ans += r - l + 1;
        }
        return ans;
    }
}

