from typing import List

def ipRangeToCidrBlocks(startIp: str, count: int) -> List[str]:
    def to_int(ip):
        return sum(int(p) << (24 - 8 * i) for i, p in enumerate(ip.split('.')))
    def to_ip(x):
        return '.'.join(str((x >> (24 - 8 * i)) & 255) for i in range(4))
    start = to_int(startIp)
    res = []
    while count > 0:
        # 最大可对齐 size = start 的最低位
        if start == 0:
            align = 1 << 32
        else:
            align = start & (-start)
        # 同时不能超过 count
        size = 1
        while size * 2 <= align and size * 2 <= count:
            size *= 2
        prefix = 32
        s = size
        while s > 1:
            prefix -= 1
            s >>= 1
        res.append(f"{to_ip(start)}/{prefix}")
        start += size
        count -= size
    return res

import java.util.*;

class Solution {
    String[] ipRangeToCidrBlocks(String startIp, long count) {
        long start = 0;
        String[] parts = startIp.split("\\.");
        for (int i = 0; i < 4; i++) start = (start << 8) | Long.parseLong(parts[i]);
        List<String> res = new ArrayList<>();
        while (count > 0) {
            long align = (start == 0) ? (1L << 32) : (start & -start);
            long size = 1;
            while (size * 2 <= align && size * 2 <= count) size *= 2;
            int prefix = 32;
            long s = size;
            while (s > 1) { prefix--; s >>= 1; }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 4; i++) {
                if (i > 0) sb.append('.');
                sb.append((start >> (24 - 8 * i)) & 255);
            }
            sb.append('/').append(prefix);
            res.add(sb.toString());
            start += size;
            count -= size;
        }
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> ipRangeToCidrBlocks(string startIp, long long count) {
        long long start = 0;
        size_t pos = 0;
        for (int i = 0; i < 4; i++) {
            size_t nxt = startIp.find('.', pos);
            long long v = stoll(startIp.substr(pos, nxt - pos));
            start = (start << 8) | v;
            pos = nxt + 1;
        }
        vector<string> res;
        while (count > 0) {
            long long align = (start == 0) ? (1LL << 32) : (start & -start);
            long long size = 1;
            while (size * 2 <= align && size * 2 <= count) size *= 2;
            int prefix = 32;
            long long s = size;
            while (s > 1) { prefix--; s >>= 1; }
            string out;
            for (int i = 0; i < 4; i++) {
                if (i > 0) out += '.';
                out += to_string((start >> (24 - 8 * i)) & 255);
            }
            out += '/' + to_string(prefix);
            res.push_back(out);
            start += size;
            count -= size;
        }
        return res;
    }
};

