class Solution {
    int[] dirHit(int[][] arr, long budget) {
        long cost = 0; int hit = 0; long prevPos = 0;
        for (int[] w : arr) {
            long pos = w[0], th = w[1];
            long delta = (pos - prevPos) + th;
            if (cost + delta <= budget) {
                cost += delta; hit++; prevPos = pos;
            } else break;
        }
        return new int[]{hit, (int) cost};
    }
    int maximizeTheHits(int[] walls, int[] thickness, int energy) {
        List<int[]> L = new ArrayList<>(), R = new ArrayList<>();
        for (int i = 0; i < walls.length; i++) {
            if (walls[i] < 0) L.add(new int[]{-walls[i], thickness[i]});
            else if (walls[i] > 0) R.add(new int[]{walls[i], thickness[i]});
        }
        L.sort((a, b) -> a[0] - b[0]);
        R.sort((a, b) -> a[0] - b[0]);
        int[][] LA = L.toArray(new int[0][]);
        int[][] RA = R.toArray(new int[0][]);
        int best = Math.max(dirHit(LA, energy)[0], dirHit(RA, energy)[0]);
        long sum = 0;
        for (int i = 0; i <= LA.length; i++) {
            long costL = 0;
            if (i > 0) {
                long pos = LA[i - 1][0];
                long s = 0;
                for (int k = 0; k < i; k++) s += LA[k][1];
                costL = 2 * pos + s;
            }
            if (costL > energy) break;
            int hr = dirHit(RA, energy - costL)[0];
            best = Math.max(best, i + hr);
        }
        for (int j = 0; j <= RA.length; j++) {
            long costR = 0;
            if (j > 0) {
                long pos = RA[j - 1][0];
                long s = 0;
                for (int k = 0; k < j; k++) s += RA[k][1];
                costR = 2 * pos + s;
            }
            if (costR > energy) break;
            int hl = dirHit(LA, energy - costR)[0];
            best = Math.max(best, j + hl);
        }
        return best;
    }
}

class Solution {
public:
    int dirHit(vector<pair<int,int>>& arr, long long budget) {
        long long cost = 0; int hit = 0; long long prevPos = 0;
        for (auto& [pos, th] : arr) {
            long long delta = (pos - prevPos) + th;
            if (cost + delta <= budget) { cost += delta; hit++; prevPos = pos; }
            else break;
        }
        return hit;
    }
    int maximizeTheHits(vector<int>& walls, vector<int>& thickness, int energy) {
        vector<pair<int,int>> L, R;
        for (size_t i = 0; i < walls.size(); i++) {
            if (walls[i] < 0) L.push_back({-walls[i], thickness[i]});
            else if (walls[i] > 0) R.push_back({walls[i], thickness[i]});
        }
        sort(L.begin(), L.end());
        sort(R.begin(), R.end());
        int best = max(dirHit(L, energy), dirHit(R, energy));
        for (int i = 0; i <= (int) L.size(); i++) {
            long long costL = 0;
            if (i > 0) {
                long long pos = L[i - 1].first, s = 0;
                for (int k = 0; k < i; k++) s += L[k].second;
                costL = 2 * pos + s;
            }
            if (costL > energy) break;
            int hr = dirHit(R, energy - costL);
            best = max(best, i + hr);
        }
        for (int j = 0; j <= (int) R.size(); j++) {
            long long costR = 0;
            if (j > 0) {
                long long pos = R[j - 1].first, s = 0;
                for (int k = 0; k < j; k++) s += R[k].second;
                costR = 2 * pos + s;
            }
            if (costR > energy) break;
            int hl = dirHit(L, energy - costR);
            best = max(best, j + hl);
        }
        return best;
    }
};

from typing import List

def solveInMemoryDatabaseBackupRestore(input: str) -> List[str]:
    lines = input.split("\n")
    n = int(lines[0])
    db: dict[str, str] = {}
    snapshots: dict[int, dict[str, str]] = {}
    next_id = 1
    out: List[str] = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        cmd = parts[0]
        if cmd == "SET":
            db[parts[1]] = parts[2]
            out.append("OK")
        elif cmd == "GET":
            out.append(db.get(parts[1], "NULL"))
        elif cmd == "DELETE":
            if parts[1] in db:
                del db[parts[1]]
                out.append("OK")
            else:
                out.append("NULL")
        elif cmd == "BACKUP":
            snapshots[next_id] = dict(db)
            out.append(str(next_id))
            next_id += 1
        elif cmd == "RESTORE":
            bid = int(parts[1])
            if bid in snapshots:
                db = dict(snapshots[bid])
                out.append("OK")
            else:
                out.append("NULL")
    return out

import java.util.*;

class Solution {
    String[] solveInMemoryDatabaseBackupRestore(String input) {
        String[] lines = input.split("\n");
        int n = Integer.parseInt(lines[0].trim());
        Map<String, String> db = new HashMap<>();
        Map<Integer, Map<String, String>> snapshots = new HashMap<>();
        int nextId = 1;
        List<String> out = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            String[] parts = lines[i].split(" ");
            switch (parts[0]) {
                case "SET":
                    db.put(parts[1], parts[2]);
                    out.add("OK");
                    break;
                case "GET":
                    out.add(db.getOrDefault(parts[1], "NULL"));
                    break;
                case "DELETE":
                    out.add(db.remove(parts[1]) != null ? "OK" : "NULL");
                    break;
                case "BACKUP":
                    snapshots.put(nextId, new HashMap<>(db));
                    out.add(String.valueOf(nextId++));
                    break;
                case "RESTORE":
                    int bid = Integer.parseInt(parts[1]);
                    if (snapshots.containsKey(bid)) {
                        db = new HashMap<>(snapshots.get(bid));
                        out.add("OK");
                    } else {
                        out.add("NULL");
                    }
                    break;
            }
        }
        return out.toArray(new String[0]);
    }
}

#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

class Solution {
public:
    std::vector<std::string> solveInMemoryDatabaseBackupRestore(std::string input) {
        std::vector<std::string> lines;
        std::stringstream ss(input);
        std::string line;
        while (std::getline(ss, line)) lines.push_back(line);
        int n = std::stoi(lines[0]);
        std::unordered_map<std::string, std::string> db;
        std::unordered_map<int, std::unordered_map<std::string, std::string>> snapshots;
        int nextId = 1;
        std::vector<std::string> out;
        for (int i = 1; i <= n; i++) {
            std::stringstream ls(lines[i]);
            std::string cmd; ls >> cmd;
            if (cmd == "SET") {
                std::string k, v; ls >> k >> v;
                db[k] = v;
                out.push_back("OK");
            } else if (cmd == "GET") {
                std::string k; ls >> k;
                auto it = db.find(k);
                out.push_back(it == db.end() ? "NULL" : it->second);
            } else if (cmd == "DELETE") {
                std::string k; ls >> k;
                out.push_back(db.erase(k) ? "OK" : "NULL");
            } else if (cmd == "BACKUP") {
                snapshots[nextId] = db;
                out.push_back(std::to_string(nextId++));
            } else if (cmd == "RESTORE") {
                int bid; ls >> bid;
                auto it = snapshots.find(bid);
                if (it != snapshots.end()) { db = it->second; out.push_back("OK"); }
                else out.push_back("NULL");
            }
        }
        return out;
    }
};

class Solution {
    public String encrypt(String text) {
        StringBuilder sb = new StringBuilder(text.length());
        for (char c : text.toCharArray()) sb.append((char) ((c - 'A' + 4) % 26 + 'A'));
        return sb.toString();
    }
}

class Solution {
public:
    string encrypt(string text) {
        string out;
        out.reserve(text.size());
        for (char c : text) out += char((c - 'A' + 4) % 26 + 'A');
        return out;
    }
};

