def consecutive(num: int) -> int:
    cnt = 0
    k = 2
    while k * (k - 1) // 2 < num:
        rem = num - k * (k - 1) // 2
        if rem > 0 and rem % k == 0:
            cnt += 1
        k += 1
    return cnt

class Solution {
    public int consecutive(long num) {
        int cnt = 0;
        for (long k = 2; k * (k - 1) / 2 < num; k++) {
            long rem = num - k * (k - 1) / 2;
            if (rem > 0 && rem % k == 0) cnt++;
        }
        return cnt;
    }
}

