import java.util.*;

class Solution {
    int findThePath(int N, int[][] edges, int K) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= N; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] best = new int[N + 1];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[1] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.add(new int[]{0, 1});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > best[u]) continue;
            if (u == K) return d;
            for (int[] e : adj.get(u)) {
                int nd = Math.max(d, e[1]);
                if (nd < best[e[0]]) { best[e[0]] = nd; pq.add(new int[]{nd, e[0]}); }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int findThePath(int N, vector<vector<int>>& edges, int K) {
        vector<vector<pair<int, int>>> adj(N + 1);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> best(N + 1, INT_MAX);
        best[1] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        pq.push({0, 1});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > best[u]) continue;
            if (u == K) return d;
            for (auto& [v, w] : adj[u]) {
                int nd = max(d, w);
                if (nd < best[v]) { best[v] = nd; pq.push({nd, v}); }
            }
        }
        return -1;
    }
};

def first_occurrence(s: str, x: str) -> int:
    n, m = len(s), len(x)
    for i in range(n - m + 1):
        ok = True
        for j in range(m):
            if x[j] != '*' and x[j] != s[i + j]:
                ok = False
                break
        if ok:
            return i
    return -1

class Solution {
    int firstOccurrence(String s, String x) {
        int n = s.length(), m = x.length();
        for (int i = 0; i + m <= n; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                if (x.charAt(j) != '*' && x.charAt(j) != s.charAt(i + j)) { ok = false; break; }
            }
            if (ok) return i;
        }
        return -1;
    }
}

class Solution {
public:
    int firstOccurrence(string s, string x) {
        int n = s.size(), m = x.size();
        for (int i = 0; i + m <= n; i++) {
            bool ok = true;
            for (int j = 0; j < m; j++) {
                if (x[j] != '*' && x[j] != s[i + j]) { ok = false; break; }
            }
            if (ok) return i;
        }
        return -1;
    }
};

