from functools import lru_cache

def get_process_time(time: List[int]) -> List[int]:
    n = len(time)
    @lru_cache(maxsize=None)
    def solve(i, latch):
        if i == n:
            return (0, 0)
        op_a = solve(i + 1, 3 - latch)
        op_b = solve(i + 1, latch)
        cur_time = time[i - 1] if i >= 1 else 0
        # op A: latch keeps current process? Re-read problem: at step i, the assignment is for the i-th process.
        # Simplified: assume current process at i goes to latch core (op A), or to other core (op B).
        if latch == 1:
            a_c1 = op_a[0] + cur_time
            a_c2 = op_a[1]
            b_c1 = op_b[0]
            b_c2 = op_b[1] + cur_time
            if a_c1 >= b_c1:
                return (a_c1, a_c2)
            return (b_c1, b_c2)
        else:
            a_c2 = op_a[1] + cur_time
            a_c1 = op_a[0]
            b_c2 = op_b[1]
            b_c1 = op_b[0] + cur_time
            if a_c2 >= b_c2:
                return (a_c1, a_c2)
            return (b_c1, b_c2)
    c1, c2 = solve(1, 1)
    c1 += time[0]
    return [c1, c2]

import java.util.*;

class Solution {
    int[] time;
    long[][][] memo;

    long[] getProcessTime(int[] time) {
        this.time = time;
        int n = time.length;
        memo = new long[n + 1][3][2];
        for (long[][] a : memo) for (long[] b : a) Arrays.fill(b, -1);
        long[] r = solve(1, 1);
        r[0] += time[0];
        return r;
    }

    private long[] solve(int i, int latch) {
        int n = time.length;
        if (i == n) return new long[]{0, 0};
        long[] opA = solve(i + 1, 3 - latch);
        long[] opB = solve(i + 1, latch);
        long curTime = time[i];
        if (latch == 1) {
            long aC1 = opA[0] + curTime, aC2 = opA[1];
            long bC1 = opB[0], bC2 = opB[1] + curTime;
            return aC1 >= bC1 ? new long[]{aC1, aC2} : new long[]{bC1, bC2};
        } else {
            long aC2 = opA[1] + curTime, aC1 = opA[0];
            long bC2 = opB[1], bC1 = opB[0] + curTime;
            return aC2 >= bC2 ? new long[]{aC1, aC2} : new long[]{bC1, bC2};
        }
    }
}

class Solution {
public:
    vector<int>* timeRef;
    pair<long long, long long> solve(int i, int latch) {
        int n = timeRef->size();
        if (i == n) return {0, 0};
        auto opA = solve(i + 1, 3 - latch);
        auto opB = solve(i + 1, latch);
        long long curTime = (*timeRef)[i];
        if (latch == 1) {
            long long aC1 = opA.first + curTime, aC2 = opA.second;
            long long bC1 = opB.first, bC2 = opB.second + curTime;
            return aC1 >= bC1 ? make_pair(aC1, aC2) : make_pair(bC1, bC2);
        } else {
            long long aC2 = opA.second + curTime, aC1 = opA.first;
            long long bC2 = opB.second, bC1 = opB.first + curTime;
            return aC2 >= bC2 ? make_pair(aC1, aC2) : make_pair(bC1, bC2);
        }
    }
    vector<long long> getProcessTime(vector<int>& time) {
        timeRef = &time;
        auto p = solve(1, 1);
        p.first += time[0];
        return {p.first, p.second};
    }
};

