def longest_string_chain(words: List[str]) -> int:
    words = sorted(set(words), key=len)
    dp = {}
    best = 1
    for w in words:
        cur = 1
        for i in range(len(w)):
            pre = w[:i] + w[i + 1:]
            if pre in dp and dp[pre] + 1 > cur:
                cur = dp[pre] + 1
        dp[w] = cur
        best = max(best, cur)
    return best

import java.util.*;

class Solution {
    int longestStringChain(String[] words) {
        Arrays.sort(words, (a, b) -> a.length() - b.length());
        Map<String, Integer> dp = new HashMap<>();
        int best = 1;
        for (String w : words) {
            int cur = 1;
            for (int i = 0; i < w.length(); i++) {
                String pre = w.substring(0, i) + w.substring(i + 1);
                if (dp.containsKey(pre)) cur = Math.max(cur, dp.get(pre) + 1);
            }
            dp.put(w, cur);
            best = Math.max(best, cur);
        }
        return best;
    }
}

class Solution {
public:
    int longestStringChain(vector<string>& words) {
        sort(words.begin(), words.end(), [](const string& a, const string& b) { return a.size() < b.size(); });
        unordered_map<string, int> dp;
        int best = 1;
        for (auto& w : words) {
            int cur = 1;
            for (size_t i = 0; i < w.size(); ++i) {
                string pre = w.substr(0, i) + w.substr(i + 1);
                auto it = dp.find(pre);
                if (it != dp.end()) cur = max(cur, it->second + 1);
            }
            dp[w] = cur;
            best = max(best, cur);
        }
        return best;
    }
};

