        int n = arr.length;
        long total = 0;
        for (int i = 1; i < n - 1; i += 2) {
            long need = Math.max(arr[i - 1], arr[i + 1]) + 1;
            if (arr[i] < need) {
                total += need - arr[i];
                arr[i] = need;
            }
        }
        return total;
    }
