def split_array_largest_sum(arr: List[int], K: int) -> int:
    n = len(arr)
    INF = float("inf")
    dp = [[INF] * (K + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for k in range(1, K + 1):
            cur_max = 0
            for j in range(i - 1, -1, -1):
                cur_max = max(cur_max, arr[j])
                if dp[j][k - 1] + cur_max < dp[i][k]:
                    dp[i][k] = dp[j][k - 1] + cur_max
    return dp[n][K]

class Solution {
    int splitArrayLargestSum(int[] arr, int K) {
        int n = arr.length;
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n + 1][K + 1];
        for (long[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int i = 1; i <= n; i++)
            for (int k = 1; k <= K; k++) {
                int curMax = 0;
                for (int j = i - 1; j >= 0; j--) {
                    curMax = Math.max(curMax, arr[j]);
                    if (dp[j][k - 1] + curMax < dp[i][k]) dp[i][k] = dp[j][k - 1] + curMax;
                }
            }
        return (int) dp[n][K];
    }
}

