def numPlayers(k, scores):
    s = sorted(scores, reverse=True)
    cnt = 0
    rank = 0
    prev = None
    for i, score in enumerate(s):
        if score != prev:
            rank = i + 1
            prev = score
        if rank <= k and score > 0:
            cnt += 1
        elif rank > k:
            break
    return cnt

