        for (int i = 0; i < s.length; i++) {
            if (prev == null || !s[i].equals(prev)) { rank = i + 1; prev = s[i]; }
            if (rank <= k && s[i] > 0) cnt++; else if (rank > k) break;
        }
        return cnt;
    }
}

