def partition_array(k: int, numbers: list[int]) -> str:
    n = len(numbers)
    if n % k != 0:
        return "No"
    groups = n // k
    cnt = Counter(numbers)
    for v in cnt.values():
        if v > groups:
            return "No"
    return "Yes"

class Solution {
    static String partitionArray(int k, int[] numbers) {
        int n = numbers.length;
        if (n % k != 0) return "No";
        int groups = n / k;
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : numbers) cnt.merge(x, 1, Integer::sum);
        for (int v : cnt.values()) if (v > groups) return "No";
        return "Yes";
    }
}

