from collections import deque
from typing import List, Optional

def ladderLength(beginWord: str, endWord: str, wordList: List[str]) -> Optional[int]:
    if beginWord == endWord:
        return 0
    words = set(wordList)
    if endWord not in words:
        return None
    q = deque([(beginWord, 1)])
    visited = {beginWord}
    while q:
        word, steps = q.popleft()
        if word == endWord:
            return steps - 1
        for i in range(len(word)):
            for c in "abcdefghijklmnopqrstuvwxyz":
                if c == word[i]:
                    continue
                nxt = word[:i] + c + word[i + 1:]
                if nxt in words and nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, steps + 1))
    return None

import java.util.*;

class Solution {
    int ladderLength(String beginWord, String endWord, List<String> wordList) {
        if (beginWord.equals(endWord)) return 0;
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return -1;
        Queue<String> q = new ArrayDeque<>();
        q.offer(beginWord);
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);
        int steps = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int s = 0; s < sz; s++) {
                String word = q.poll();
                if (word.equals(endWord)) return steps - 1;
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char orig = chars[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == orig) continue;
                        chars[i] = c;
                        String nxt = new String(chars);
                        if (words.contains(nxt) && visited.add(nxt)) q.offer(nxt);
                    }
                    chars[i] = orig;
                }
            }
            steps++;
        }
        return -1;
    }
}

