from typing import List

def getMinimumOperations(executionTime: List[int], x: int, y: int) -> int:
    def feasible(k: int) -> bool:
        need = 0
        for t in executionTime:
            if k * y >= t:
                continue
            # need c such that c*x + (k-c)*y >= t -> c >= (t - k*y)/(x - y)
            num = t - k * y
            den = x - y
            c = (num + den - 1) // den
            need += c
            if need > k:
                return False
        return need <= k

    lo, hi = 1, max(executionTime) // y + 2 if y > 0 else max(executionTime) + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int getMinimumOperations(int[] executionTime, int x, int y) {
        long maxT = 0;
        for (int t : executionTime) maxT = Math.max(maxT, t);
        long lo = 1, hi = (y > 0 ? maxT / y + 2 : maxT + 1);
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            if (feasible(executionTime, x, y, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
    private boolean feasible(int[] et, int x, int y, long k) {
        long need = 0;
        long den = x - y;
        for (int t : et) {
            if ((long) k * y >= t) continue;
            long num = t - k * y;
            long c = (num + den - 1) / den;
            need += c;
            if (need > k) return false;
        }
        return need <= k;
    }
}

