import heapq

def findMinWeight(weights, d):
    h = [-w for w in weights]
    heapq.heapify(h)
    for _ in range(d):
        w = -heapq.heappop(h)
        eaten = w // 2
        heapq.heappush(h, -(w - eaten))
    return -sum(h)

class Solution {
    public long findMinWeight(int[] weights, int d) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
        for (int w : weights) pq.add(w);
        for (int i = 0; i < d; i++) { int w = pq.poll(); pq.add(w - w / 2); }
        long s = 0; while (!pq.isEmpty()) s += pq.poll();
        return s;
    }
}

