 return s;
}

def vowelSubstring(s):
    from collections import Counter
    V = set("aeiou")
    total = 0
    segments = []
    cur = []
    for c in s:
        if c in V: cur.append(c)
        else:
            if cur: segments.append(''.join(cur))
            cur = []
    if cur: segments.append(''.join(cur))
    for seg in segments:
        cnt = Counter()
        kinds = 0
        l = 0
        for r, c in enumerate(seg):
            if cnt[c] == 0: kinds += 1
            cnt[c] += 1
            while kinds == 5:
                total += len(seg) - r
                cnt[seg[l]] -= 1
                if cnt[seg[l]] == 0: kinds -= 1
                l += 1
    return total

class Solution {
    public long vowelSubstring(String s) {
        String V = "aeiou";
        long total = 0; int n = s.length(), i = 0;
        while (i < n) {
            if (V.indexOf(s.charAt(i)) < 0) { i++; continue; }
            int j = i; while (j < n && V.indexOf(s.charAt(j)) >= 0) j++;
            Map<Character, Integer> cnt = new HashMap<>(); int kinds = 0, l = i;
            for (int r = i; r < j; r++) {
                if (cnt.merge(s.charAt(r), 1, Integer::sum) == 1) kinds++;
                while (kinds == 5) {
                    total += j - r;
                    if (cnt.merge(s.charAt(l), -1, Integer::sum) == 0) kinds--;
                    l++;
                }
            }
            i = j;
        }
        return total;
    }
}

