}

def getMinCost(cost, time):
    n = len(cost)
    INF = float('inf')
    f = [INF] * (n + 1)
    f[0] = 0
    for i in range(n):
        for j in range(n, -1, -1):
            if f[j] < INF:
                nj = min(n, j + time[i] + 1)
                f[nj] = min(f[nj], f[j] + cost[i])
    return f[n]

class Solution {
    public int getMinCost(int[] cost, int[] time) {
        int n = cost.length;
        int[] f = new int[n + 1];
        Arrays.fill(f, Integer.MAX_VALUE);
        f[0] = 0;
        for (int i = 0; i < n; i++)
            for (int j = n; j >= 0; j--) {
                if (f[j] == Integer.MAX_VALUE) continue;
                int nj = Math.min(n, j + time[i] + 1);
                f[nj] = Math.min(f[nj], f[j] + cost[i]);
            }
        return f[n];
    }
}

