class Solution {
    static final long MOD = 1_000_000_007;
    public int countPaintings(int n) {
        long r = 1, b = 2; int e = n - 1;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return (int) (3 * r % MOD);
    }
}

