def calculateWays(wordLen, maxVowels):
    f = [[0] * (maxVowels + 1) for _ in range(wordLen + 1)]
    f[0][0] = 1
    for i in range(1, wordLen + 1):
        total_prev = sum(f[i-1]) % MOD
        f[i][0] = total_prev * 21 % MOD
        for j in range(1, maxVowels + 1):
            f[i][j] = f[i-1][j-1] * 5 % MOD
    return sum(f[wordLen]) % MOD

class Solution {
