        for (int i = 1; i <= wordLen; i++) {
            long s = 0; for (long x : f[i-1]) s = (s + x) % MOD;
            f[i][0] = s * 21 % MOD;
            for (int j = 1; j <= maxVowels; j++) f[i][j] = f[i-1][j-1] * 5 % MOD;
        }
        long ans = 0; for (long x : f[wordLen]) ans = (ans + x) % MOD;
        return (int) ans;
    }
