def findSchedules(work_hours, day_hours, pattern):
    p = list(pattern)
    qs = [i for i, c in enumerate(p) if c == '?']
    fixed_sum = sum(int(c) for c in p if c != '?')
    need = work_hours - fixed_sum
    results = []

    def backtrack(idx, remaining):
        if idx == len(qs):
            if remaining == 0:
                results.append(''.join(p))
            return
        slots_left = len(qs) - idx - 1
        for v in range(min(day_hours, remaining) + 1):
            if remaining - v <= slots_left * day_hours:
                p[qs[idx]] = str(v)
                backtrack(idx + 1, remaining - v)
        p[qs[idx]] = '?'

    if 0 <= need <= len(qs) * day_hours:
        backtrack(0, need)
    return sorted(results)

class Solution {
    public List<String> findSchedules(int workHours, int dayHours, String pattern) {
        char[] p = pattern.toCharArray();
        List<Integer> qs = new ArrayList<>();
        int fixed = 0;
        for (int i = 0; i < 7; i++) { if (p[i] == '?') qs.add(i); else fixed += p[i] - '0'; }
        int need = workHours - fixed;
        List<String> out = new ArrayList<>();
        if (need >= 0 && need <= qs.size() * dayHours) bt(0, need, p, qs, dayHours, out);
        Collections.sort(out);
        return out;
    }
    private void bt(int idx, int rem, char[] p, List<Integer> qs, int D, List<String> out) {
        if (idx == qs.size()) { if (rem == 0) out.add(new String(p)); return; }
        int left = qs.size() - idx - 1;
        for (int v = 0; v <= Math.min(D, rem); v++) {
            if (rem - v <= left * D) { p[qs.get(idx)] = (char)('0' + v); bt(idx + 1, rem - v, p, qs, D, out); }
        }
        p[qs.get(idx)] = '?';
    }
}

vector<string> findSchedules(int workHours, int dayHours, string pattern) {
 vector<int> qs; int fixed = 0;
 for (int i = 0; i < 7; ++i) {
 if (pattern[i] == '?') qs.push_back(i);
 else fixed += pattern[i] - '0';
 }
 int need = workHours - fixed;
 vector<string> out;
 function<void(int, int)> bt = [&](int idx, int rem) {
 if (idx == (int)qs.size()) { if (rem == 0) out.push_back(pattern); return; }
 int left = qs.size() - idx - 1;
 for (int v = 0; v <= min(dayHours, rem); ++v) {
 if (rem - v <= left * dayHours) {
 pattern[qs[idx]] = '0' + v;
 bt(idx + 1, rem - v);
 }
 }
 pattern[qs[idx]] = '?';
 };
 if (need >= 0 && need <= (int)qs.size() * dayHours) bt(0, need);
 sort(out.begin(), out.end());
 return out;
}

class Solution {
    public int teamFormation(int[] score, int teamSize, int k) {
        LinkedList<int[]> dq = new LinkedList<>();
        for (int i = 0; i < score.length; i++) dq.add(new int[]{i, score[i]});
        int total = 0;
        for (int t = 0; t < teamSize; t++) {
            List<int[]> cand = new ArrayList<>();
            int n = dq.size();
            for (int i = 0; i < Math.min(k, n); i++) cand.add(dq.get(i));
            for (int i = Math.max(0, n - k); i < n; i++) cand.add(dq.get(i));
            Set<Integer> seen = new HashSet<>();
            int[] best = {-1, -1};
            for (int[] p : cand) {
                if (!seen.add(p[0])) continue;
                if (p[1] > best[1] || (p[1] == best[1] && (best[0] == -1 || p[0] < best[0]))) best = p;
            }
            total += best[1];
            final int rm = best[0];
            dq.removeIf(p -> p[0] == rm);
        }
        return total;
    }
}

int teamFormation(vector<int>& score, int teamSize, int k) {
 list<pair<int,int>> dq;
 for (int i = 0; i < (int)score.size(); ++i) dq.push_back({i, score[i]});
 int total = 0;
 for (int t = 0; t < teamSize; ++t) {
 vector<pair<int,int>> cand;
 int cnt = 0;
 for (auto& p : dq) { if (cnt++ < k) cand.push_back(p); else break; }
 if ((int)dq.size() > k) {
 auto it = dq.end(); for (int i = 0; i < k; ++i) --it;
 for (auto j = it; j != dq.end(); ++j) cand.push_back(*j);
 }
 set<int> seen;
 pair<int,int> best{-1, -1};
 for (auto& p : cand) {
 if (seen.count(p.first)) continue;
 seen.insert(p.first);
 if (p.second > best.second || (p.second == best.second && (best.first == -1 || p.first < best.first))) best = p;
 }
 total += best.second;
 dq.remove_if([&](pair<int,int>& p) { return p.first == best.first; });
 }
 return total;
}

import java.util.*;

class Solution {
    static long phoneCalls(int[] start, int[] duration, int[] volume) {
        int n = start.length;
        long[][] iv = new long[n][3];
        for (int i = 0; i < n; i++) {
            iv[i][0] = start[i];
            iv[i][1] = (long) start[i] + duration[i];
            iv[i][2] = volume[i];
        }
        Arrays.sort(iv, (a, b) -> Long.compare(a[1], b[1]));
        long[] ends = new long[n];
        for (int i = 0; i < n; i++) ends[i] = iv[i][1];
        long[] f = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            long s = iv[i - 1][0], v = iv[i - 1][2];
            int lo = 0, hi = i - 1;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] <= s) lo = mid + 1; else hi = mid;
            }
            int p = lo;
            f[i] = Math.max(f[i - 1], f[p] + v);
        }
        return f[n];
    }
}

