def findMaxLength(skills, k):
    n = len(skills)
    # f[i][j] = 以 i 结尾、用了 j 次切换的最长子序列长度
    f = [[1] * (k + 1) for _ in range(n)]
    ans = 1
    for i in range(n):
        for p in range(i):
            same = (skills[p] == skills[i])
            for j in range(k + 1):
                cost = 0 if same else 1
                if j - cost >= 0 and f[p][j - cost] + 1 > f[i][j]:
                    f[i][j] = f[p][j - cost] + 1
            ans = max(ans, max(f[i]))
    return ans

class Solution {
    public int findMaxLength(int[] skills, int k) {
        int n = skills.length;
        int[][] f = new int[n][k + 1];
        for (int[] r : f) java.util.Arrays.fill(r, 1);
        int ans = 1;
        for (int i = 0; i < n; i++) {
            for (int p = 0; p < i; p++) {
                int cost = skills[p] == skills[i] ? 0 : 1;
                for (int j = cost; j <= k; j++) {
                    if (f[p][j - cost] + 1 > f[i][j]) f[i][j] = f[p][j - cost] + 1;
                    if (f[i][j] > ans) ans = f[i][j];
                }
            }
        }
        return ans;
    }
}

