def getMaxBarrier(initialEnergy, th):
    def remain(b):
        return sum(max(e - b, 0) for e in initialEnergy)
    lo, hi = 0, max(initialEnergy)
    while lo < hi:
        mid = (lo + hi + 1) // 2  # 找最大可行值，上取整
        if remain(mid) >= th:
            lo = mid
        else:
            hi = mid - 1
    return lo

class Solution {
    public int getMaxBarrier(int[] initialEnergy, long th) {
        int hi = 0;
        for (int e : initialEnergy) hi = Math.max(hi, e);
        int lo = 0;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            long s = 0;
            for (int e : initialEnergy) if (e > mid) s += e - mid;
            if (s >= th) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

