        int hi = *max_element(initialEnergy.begin(), initialEnergy.end()), lo = 0;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            long long s = 0;
            for (int e : initialEnergy) if (e > mid) s += (long long)(e - mid);
            if (s >= th) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
};

from collections import deque

def getMinJumps(grid):
    n, m = len(grid), len(grid[0])
    sr = sc = er = ec = -1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S': sr, sc = i, j
            elif grid[i][j] == 'E': er, ec = i, j
    dist = [[-1] * m for _ in range(n)]
    dist[sr][sc] = 0
    q = deque([(sr, sc)])
    while q:
        r, c = q.popleft()
        if (r, c) == (er, ec):
            return dist[r][c]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '#':
                if dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
                nr += dr
                nc += dc
    return dist[er][ec]

class Solution {
    public int getMinJumps(String[] grid) {
        int n = grid.length, m = grid[0].length();
        int sr = 0, sc = 0, er = 0, ec = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            char ch = grid[i].charAt(j);
            if (ch == 'S') { sr = i; sc = j; }
            else if (ch == 'E') { er = i; ec = j; }
        }
        int[][] dist = new int[n][m];
        for (int[] r : dist) java.util.Arrays.fill(r, -1);
        dist[sr][sc] = 0;
        java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
        q.offer(new int[]{sr, sc});
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            if (r == er && c == ec) return dist[r][c];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                while (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr].charAt(nc) != '#') {
                    if (dist[nr][nc] == -1) {
                        dist[nr][nc] = dist[r][c] + 1;
                        q.offer(new int[]{nr, nc});
                    }
                    nr += d[0]; nc += d[1];
                }
            }
        }
        return dist[er][ec];
    }
}

