def getMinimumOperations(executionTime, x, y):
    diff = x - y
    def ok(T):
        need = 0
        for t in executionTime:
            rem = t - T * y
            if rem > 0:
                need += (rem + diff - 1) // diff
                if need > T:
                    return False
        return need <= T
    lo, hi = 1, max(executionTime) // y + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    public long getMinimumOperations(int[] executionTime, int x, int y) {
        long diff = x - y;
        long lo = 1, hi = 0;
        for (int t : executionTime) hi = Math.max(hi, (long) t);
        hi = hi / y + 1;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            long need = 0;
            boolean ok = true;
            for (int t : executionTime) {
                long rem = (long) t - mid * y;
                if (rem > 0) {
                    need += (rem + diff - 1) / diff;
                    if (need > mid) { ok = false; break; }
                }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

