                    if (need > mid) { ok = false; break; }
                }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

def numWays(words, target):
    MOD = 10**9 + 7
    m, k = len(target), len(words[0])
    cnt = [[0] * 26 for _ in range(k)]
    for w in words:
        for j, c in enumerate(w):
            cnt[j][ord(c) - 97] += 1
    # f[i] = 已匹配 target[:i] 的方案数
    f = [0] * (m + 1)
    f[0] = 1
    for j in range(k):
        for i in range(m, 0, -1):
            c = ord(target[i - 1]) - 97
            f[i] = (f[i] + f[i - 1] * cnt[j][c]) % MOD
    return f[m]

class Solution {
    static final int MOD = 1_000_000_007;
    public int numWays(String[] words, String target) {
        int m = target.length(), k = words[0].length();
        int[][] cnt = new int[k][26];
        for (String w : words) for (int j = 0; j < k; j++) cnt[j][w.charAt(j) - 'a']++;
        long[] f = new long[m + 1];
        f[0] = 1;
        for (int j = 0; j < k; j++) {
            for (int i = m; i >= 1; i--) {
                int c = target.charAt(i - 1) - 'a';
                f[i] = (f[i] + f[i - 1] * cnt[j][c]) % MOD;
            }
        }
        return (int) f[m];
    }
}

class Solution {
public:
    int numWays(vector<string>& words, string target) {
        const int MOD = 1e9 + 7;
        int m = target.size(), k = words[0].size();
        vector<vector<int>> cnt(k, vector<int>(26, 0));
        for (auto& w : words) for (int j = 0; j < k; ++j) cnt[j][w[j] - 'a']++;
        vector<long long> f(m + 1, 0);
        f[0] = 1;
        for (int j = 0; j < k; ++j) {
            for (int i = m; i >= 1; --i) {
                int c = target[i - 1] - 'a';
                f[i] = (f[i] + f[i - 1] * cnt[j][c]) % MOD;
            }
        }
        return (int) f[m];
    }
};

def getPerfectPairsCount(arr):
    a = sorted(abs(x) for x in arr)
    n = len(a)
    ans = 0
    j = 0
    for i in range(n):
        if j < i + 1:
            j = i + 1
        while j < n and a[j] <= 2 * a[i]:
            j += 1
        ans += j - i - 1
    return ans

