class Solution {
    public int interval(int[] first, int[] last) {
        int n = first.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (x, y) -> last[x] != last[y] ? last[x] - last[y] : first[y] - first[x]);
        int a = -1, b = -1, ans = 0;
        for (int k : idx) {
            int s = first[k], e = last[k];
            int cnt = (s <= a && a <= e ? 1 : 0) + (s <= b && b <= e ? 1 : 0);
            if (cnt == 0) {
                a = e; b = e - 1; ans += 2;
            } else if (cnt == 1) {
                int pick = (a != e) ? e : e - 1;
                if (pick > a) { b = a; a = pick; } else b = pick;
                ans += 1;
            }
        }
        return ans;
    }
}

