        }
        return ans;
    }
};

class Solution {
    public int[] arrayReduction(int[] arr) {
        int n = arr.length;
        java.util.List<Integer> res = new java.util.ArrayList<>();
        int i = 0;
        while (i < n) {
            java.util.Set<Integer> present = new java.util.HashSet<>();
            for (int k = i; k < n; k++) present.add(arr[k]);
            int mex = 0;
            while (present.contains(mex)) mex++;
            res.add(mex);
            if (mex == 0) break;
            java.util.Set<Integer> need = new java.util.HashSet<>();
            for (int v = 0; v < mex; v++) need.add(v);
            int j = i;
            while (!need.isEmpty()) {
                need.remove(arr[j]);
                j++;
            }
            i = j;
        }
        int[] out = new int[res.size()];
        for (int k = 0; k < out.length; k++) out[k] = res.get(k);
        return out;
    }
}

class Solution {
public:
    vector<int> arrayReduction(vector<int>& arr) {
        int n = arr.size();
        vector<int> res;
        int i = 0;
        while (i < n) {
            unordered_set<int> present;
            for (int k = i; k < n; ++k) present.insert(arr[k]);
            int mex = 0;
            while (present.count(mex)) mex++;
            res.push_back(mex);
            if (mex == 0) break;
            unordered_set<int> need;
            for (int v = 0; v < mex; ++v) need.insert(v);
            int j = i;
            while (!need.empty()) {
                need.erase(arr[j]);
                j++;
            }
            i = j;
        }
        return res;
    }
};

def closestSquaredDistance(x, y):
    pts = sorted(zip(x, y))
    def rec(lo, hi):
        if hi - lo <= 3:
            best = float('inf')
            for i in range(lo, hi):
                for j in range(i + 1, hi):
                    dx = pts[i][0] - pts[j][0]
                    dy = pts[i][1] - pts[j][1]
                    best = min(best, dx * dx + dy * dy)
            return best
        mid = (lo + hi) // 2
        mx = pts[mid][0]
        d = min(rec(lo, mid), rec(mid, hi))
        strip = [p for p in pts[lo:hi] if (p[0] - mx) ** 2 < d]
        strip.sort(key=lambda p: p[1])
        for i in range(len(strip)):
            for j in range(i + 1, len(strip)):
                if (strip[j][1] - strip[i][1]) ** 2 >= d: break
                dx = strip[i][0] - strip[j][0]
                dy = strip[i][1] - strip[j][1]
                d = min(d, dx * dx + dy * dy)
        return d
    return rec(0, len(pts))

class Solution {
    long[][] pts;
    public long closestSquaredDistance(int[] x, int[] y) {
        int n = x.length;
        pts = new long[n][2];
        for (int i = 0; i < n; i++) { pts[i][0] = x[i]; pts[i][1] = y[i]; }
        java.util.Arrays.sort(pts, (a, b) -> Long.compare(a[0], b[0]));
        return rec(0, n);
    }
    long rec(int lo, int hi) {
        if (hi - lo <= 3) {
            long best = Long.MAX_VALUE;
            for (int i = lo; i < hi; i++) for (int j = i + 1; j < hi; j++) {
                long dx = pts[i][0] - pts[j][0], dy = pts[i][1] - pts[j][1];
                best = Math.min(best, dx * dx + dy * dy);
            }
            return best;
        }
        int mid = (lo + hi) >>> 1;
        long mx = pts[mid][0];
        long d = Math.min(rec(lo, mid), rec(mid, hi));
        java.util.List<long[]> strip = new java.util.ArrayList<>();
        for (int i = lo; i < hi; i++) {
            long dx = pts[i][0] - mx;
            if (dx * dx < d) strip.add(pts[i]);
        }
        strip.sort((a, b) -> Long.compare(a[1], b[1]));
        for (int i = 0; i < strip.size(); i++) for (int j = i + 1; j < strip.size(); j++) {
            long dy = strip.get(j)[1] - strip.get(i)[1];
            if (dy * dy >= d) break;
            long dx = strip.get(i)[0] - strip.get(j)[0];
            d = Math.min(d, dx * dx + dy * dy);
        }
        return d;
    }
}

class Solution {
public:
    vector<pair<long long,long long>> pts;
    long long rec(int lo, int hi) {
        if (hi - lo <= 3) {
            long long best = LLONG_MAX;
            for (int i = lo; i < hi; ++i) for (int j = i + 1; j < hi; ++j) {
                long long dx = pts[i].first - pts[j].first;
                long long dy = pts[i].second - pts[j].second;
                best = min(best, dx * dx + dy * dy);
            }
            return best;
        }
        int mid = (lo + hi) / 2;
        long long mx = pts[mid].first;
        long long d = min(rec(lo, mid), rec(mid, hi));
        vector<pair<long long,long long>> strip;
        for (int i = lo; i < hi; ++i) {
            long long dx = pts[i].first - mx;
            if (dx * dx < d) strip.push_back(pts[i]);
        }
        sort(strip.begin(), strip.end(), [](auto& a, auto& b){ return a.second < b.second; });
        for (int i = 0; i < (int) strip.size(); ++i) for (int j = i + 1; j < (int) strip.size(); ++j) {
            long long dy = strip[j].second - strip[i].second;
            if (dy * dy >= d) break;
            long long dx = strip[i].first - strip[j].first;
            d = min(d, dx * dx + dy * dy);
        }
        return d;
    }
    long long closestSquaredDistance(vector<int>& x, vector<int>& y) {
        int n = x.size();
        pts.resize(n);
        for (int i = 0; i < n; ++i) pts[i] = {x[i], y[i]};
        sort(pts.begin(), pts.end());
        return rec(0, n);
    }
};

def countMinimumCharacters(s, arr):
    pos = [[] for _ in range(10)]
    for i, c in enumerate(s):
        pos[int(c)].append(i)
    ans = []
    for q in arr:
        cnt = [0] * 10
        for c in q:
            cnt[int(c)] += 1
        far = -1
        ok = True
        for d in range(10):
            if cnt[d] == 0:
                continue
            if len(pos[d]) < cnt[d]:
                ok = False
                break
            far = max(far, pos[d][cnt[d] - 1])
        ans.append(far + 1 if ok else -1)
