def countPrimeStrings(s):
    MOD = 10**9 + 7
    LIM = 10**6
    sieve = [True] * (LIM + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(LIM**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, LIM + 1, i):
                sieve[j] = False
    n = len(s)
    f = [0] * (n + 1)
    f[0] = 1
    for i in range(1, n + 1):
        for j in range(max(0, i - 7), i):
            if i - j > 1 and s[j] == '0':
                continue
            v = int(s[j:i])
            if v <= LIM and sieve[v]:
                f[i] = (f[i] + f[j]) % MOD
    return f[n]

class Solution {
    static final int MOD = 1_000_000_007;
    public int countPrimeStrings(String s) {
        int LIM = 1_000_000;
        boolean[] sieve = new boolean[LIM + 1];
        java.util.Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        for (int i = 2; (long) i * i <= LIM; i++)
            if (sieve[i]) for (int j = i * i; j <= LIM; j += i) sieve[j] = false;
        int n = s.length();
        long[] f = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = Math.max(0, i - 7); j < i; j++) {
                if (i - j > 1 && s.charAt(j) == '0') continue;
                long v = Long.parseLong(s.substring(j, i));
                if (v <= LIM && sieve[(int) v]) f[i] = (f[i] + f[j]) % MOD;
            }
        }
        return (int) f[n];
    }
}

