def countWaysToColorHouses(n):
    MOD = 10**9 + 7
    states = [(a, b) for a in range(3) for b in range(3) if a != b]
    # 初始化：第一对任意 (a, b) 各 1 种
    cur = {s: 1 for s in states}
    for _ in range(n // 2 - 1):
        nxt = {s: 0 for s in states}
        for (a, b), v in cur.items():
            for (c, d) in states:
                if c != a and d != b:
                    nxt[(c, d)] = (nxt[(c, d)] + v) % MOD
        cur = nxt
    return sum(cur.values()) % MOD

class Solution {
    public int countWaysToColorHouses(int n) {
        int MOD = 1_000_000_007;
        int[] sa = new int[6], sb = new int[6];
        int idx = 0;
        for (int a = 0; a < 3; a++) for (int b = 0; b < 3; b++) if (a != b) { sa[idx] = a; sb[idx] = b; idx++; }
        long[] cur = new long[6];
        java.util.Arrays.fill(cur, 1);
        for (int step = 0; step < n / 2 - 1; step++) {
            long[] nxt = new long[6];
            for (int s = 0; s < 6; s++) {
                if (cur[s] == 0) continue;
                int a = sa[s], b = sb[s];
                for (int t = 0; t < 6; t++) {
                    int c = sa[t], d = sb[t];
                    if (c != a && d != b) nxt[t] = (nxt[t] + cur[s]) % MOD;
                }
            }
            cur = nxt;
        }
        long ans = 0;
        for (long v : cur) ans = (ans + v) % MOD;
        return (int) ans;
    }
}

