class Solution {
    public java.util.List<java.util.List<String>> effectiveRolePrivileges(java.util.List<java.util.List<String>> privileges, int[][] grants) {
        int n = privileges.size();
        int[] indeg = new int[n];
        java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new java.util.ArrayList<>());
        for (int[] e : grants) { g.get(e[0]).add(e[1]); indeg[e[1]]++; }
        java.util.List<java.util.HashSet<String>> eff = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) eff.add(new java.util.HashSet<>(privileges.get(i)));
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.offer(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) {
                eff.get(v).addAll(eff.get(u));
                if (--indeg[v] == 0) q.offer(v);
            }
        }
        java.util.List<java.util.List<String>> ans = new java.util.ArrayList<>();
        for (java.util.HashSet<String> s : eff) {
            java.util.List<String> l = new java.util.ArrayList<>(s);
            java.util.Collections.sort(l);
            ans.add(l);
        }
        return ans;
    }
}

class Solution {
public:
    vector<vector<string>> effectiveRolePrivileges(vector<vector<string>>& privileges, vector<vector<int>>& grants) {
        int n = privileges.size();
        vector<int> indeg(n, 0);
        vector<vector<int>> g(n);
        for (auto& e : grants) { g[e[0]].push_back(e[1]); indeg[e[1]]++; }
        vector<unordered_set<string>> eff(n);
        for (int i = 0; i < n; ++i) for (auto& p : privileges[i]) eff[i].insert(p);
        queue<int> q;
        for (int i = 0; i < n; ++i) if (indeg[i] == 0) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) {
                for (auto& p : eff[u]) eff[v].insert(p);
                if (--indeg[v] == 0) q.push(v);
            }
        }
        vector<vector<string>> ans(n);
        for (int i = 0; i < n; ++i) {
            ans[i] = vector<string>(eff[i].begin(), eff[i].end());
            sort(ans[i].begin(), ans[i].end());
        }
        return ans;
    }
};

def efficientCost(arr, threshold):
    n = len(arr)
    INF = float('inf')
    f = [INF] * (n + 1)
    f[0] = 0
    for i in range(1, n + 1):
        mx = 0
        for L in range(1, min(threshold, i) + 1):
            mx = max(mx, arr[i - L])
            if f[i - L] + mx < f[i]:
                f[i] = f[i - L] + mx
    return f[n]

class Solution {
    public int efficientCost(int[] arr, int threshold) {
        int n = arr.length;
        int[] f = new int[n + 1];
        java.util.Arrays.fill(f, Integer.MAX_VALUE / 2);
        f[0] = 0;
        for (int i = 1; i <= n; i++) {
            int mx = 0;
            for (int L = 1; L <= Math.min(threshold, i); L++) {
                mx = Math.max(mx, arr[i - L]);
                if (f[i - L] + mx < f[i]) f[i] = f[i - L] + mx;
            }
        }
        return f[n];
    }
}

