class Solution {
    public long maxEfficiency(int[] noAdjacent, int[] oneAdjacent, int[] bothAdjacent) {
        int n = noAdjacent.length;
        int[][] val = {noAdjacent, oneAdjacent, bothAdjacent};
        if (n == 1) return noAdjacent[0];
        long[] f = new long[]{val[1][0], val[0][0]};
        for (int i = 1; i < n - 1; i++) {
            long[] nf = {Long.MIN_VALUE, Long.MIN_VALUE};
            for (int bp = 0; bp < 2; bp++) for (int bc = 0; bc < 2; bc++) {
                int k = (bp == 1 ? 1 : 0) + (bc == 0 ? 1 : 0);
                long cand = f[bp] + val[k][i];
                if (cand > nf[bc]) nf[bc] = cand;
            }
            f = nf;
        }
        return Math.max(f[0] + val[0][n - 1], f[1] + val[1][n - 1]);
    }
}

class Solution {
public:
    long long maxEfficiency(vector<int>& noAdjacent, vector<int>& oneAdjacent, vector<int>& bothAdjacent) {
        int n = noAdjacent.size();
        vector<int>* val[3] = {&noAdjacent, &oneAdjacent, &bothAdjacent};
        if (n == 1) return noAdjacent[0];
        long long f[2] = {(*val[1])[0], (*val[0])[0]};
        for (int i = 1; i < n - 1; ++i) {
            long long nf[2] = {LLONG_MIN, LLONG_MIN};
            for (int bp = 0; bp < 2; ++bp) for (int bc = 0; bc < 2; ++bc) {
                int k = (bp == 1 ? 1 : 0) + (bc == 0 ? 1 : 0);
                long long cand = f[bp] + (*val[k])[i];
                if (cand > nf[bc]) nf[bc] = cand;
            }
            f[0] = nf[0]; f[1] = nf[1];
        }
        return max(f[0] + (long long)(*val[0])[n - 1], f[1] + (long long)(*val[1])[n - 1]);
    }
};

class Solution {
    public double[] findA(double X, double[][] B, double[] C) {
        double p = B[0][0] * C[0] + B[0][1] * C[1];
        double q = B[1][0] * C[0] + B[1][1] * C[1];
        double a = (X - q) / (p - q);
        return new double[]{Math.round(a * 100) / 100.0, Math.round((1 - a) * 100) / 100.0};
    }
}

class Solution {
public:
    vector<double> findA(double X, vector<vector<double>>& B, vector<double>& C) {
        double p = B[0][0] * C[0] + B[0][1] * C[1];
        double q = B[1][0] * C[0] + B[1][1] * C[1];
        double a = (X - q) / (p - q);
        return {round(a * 100) / 100.0, round((1 - a) * 100) / 100.0};
    }
};

import heapq

def findMaxLiveThreads(service_nodes, service_from, service_to, currentValues):
    n = service_nodes
    g = [[] for _ in range(n + 1)]
    for u, v in zip(service_from, service_to):
        g[u].append(v)
        g[v].append(u)
    val = [-1] * (n + 1)
    # 大根堆：弹出当前最大 val 的节点
    h = []
    for i, v in currentValues:
        if val[i] == -1 or val[i] < v:
            val[i] = v
        heapq.heappush(h, (-v, i))
    while h:
        nv, u = heapq.heappop(h)
        v = -nv
        if val[u] != v:
            continue
        for w in g[u]:
            if val[w] == -1 or val[w] < v - 1:
                val[w] = v - 1
                heapq.heappush(h, (-(v - 1), w))
    return val[1:]

class Solution {
    public int[] findMaxLiveThreads(int service_nodes, int[] service_from, int[] service_to, int[][] currentValues) {
        int n = service_nodes;
        java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new java.util.ArrayList<>());
        for (int i = 0; i < service_from.length; i++) {
            g.get(service_from[i]).add(service_to[i]);
            g.get(service_to[i]).add(service_from[i]);
        }
        int[] val = new int[n + 1];
        java.util.Arrays.fill(val, -1);
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int[] cv : currentValues) {
            if (val[cv[0]] < cv[1]) val[cv[0]] = cv[1];
            pq.offer(new int[]{cv[1], cv[0]});
        }
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int v = cur[0], u = cur[1];
            if (val[u] != v) continue;
            for (int w : g.get(u)) {
                if (val[w] < v - 1) {
                    val[w] = v - 1;
                    pq.offer(new int[]{v - 1, w});
                }
            }
        }
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) ans[i] = val[i + 1];
        return ans;
    }
}

class Solution {
public:
    vector<int> findMaxLiveThreads(int service_nodes, vector<int>& service_from, vector<int>& service_to, vector<vector<int>>& currentValues) {
        int n = service_nodes;
        vector<vector<int>> g(n + 1);
        for (int i = 0; i < (int) service_from.size(); ++i) {
            g[service_from[i]].push_back(service_to[i]);
            g[service_to[i]].push_back(service_from[i]);
        }
        vector<int> val(n + 1, -1);
        priority_queue<pair<int,int>> pq;
        for (auto& cv : currentValues) {
            if (val[cv[0]] < cv[1]) val[cv[0]] = cv[1];
            pq.push({cv[1], cv[0]});
        }
        while (!pq.empty()) {
            auto [v, u] = pq.top(); pq.pop();
            if (val[u] != v) continue;
            for (int w : g[u]) {
                if (val[w] < v - 1) {
                    val[w] = v - 1;
                    pq.push({v - 1, w});
                }
            }
        }
        vector<int> ans(n);
        for (int i = 0; i < n; ++i) ans[i] = val[i + 1];
        return ans;
    }
};

def findPodCount(pods, logs):
    n = len(pods)
    res = [-1] * n
    max_floor_after = 0
    for typ, p, x in reversed(logs):
        if typ == 2:
            if x > max_floor_after:
                max_floor_after = x
        else:  # typ == 1
            idx = p - 1
            if res[idx] == -1:
                res[idx] = max(x, max_floor_after)
    for i in range(n):
        if res[i] == -1:
            res[i] = max(pods[i], max_floor_after)
    return res

class Solution {
    public int[] findPodCount(int[] pods, int[][] logs) {
        int n = pods.length;
        int[] res = new int[n];
        java.util.Arrays.fill(res, -1);
        int maxFloor = 0;
        for (int i = logs.length - 1; i >= 0; i--) {
            int typ = logs[i][0], p = logs[i][1], x = logs[i][2];
            if (typ == 2) {
                if (x > maxFloor) maxFloor = x;
            } else {
                int idx = p - 1;
                if (res[idx] == -1) res[idx] = Math.max(x, maxFloor);
            }
        }
        for (int i = 0; i < n; i++) if (res[i] == -1) res[i] = Math.max(pods[i], maxFloor);
        return res;
    }
}

class Solution {
public:
    vector<int> findPodCount(vector<int>& pods, vector<vector<int>>& logs) {
        int n = pods.size();
        vector<int> res(n, -1);
        int maxFloor = 0;
        for (int i = (int) logs.size() - 1; i >= 0; --i) {
            int typ = logs[i][0], p = logs[i][1], x = logs[i][2];
            if (typ == 2) { if (x > maxFloor) maxFloor = x; }
            else {
                int idx = p - 1;
                if (res[idx] == -1) res[idx] = max(x, maxFloor);
            }
        }
        for (int i = 0; i < n; ++i) if (res[i] == -1) res[i] = max(pods[i], maxFloor);
        return res;
    }
};

def maxLengthGoodSubsequence(nums, k):
    n = len(nums)
    f = [[1] * (k + 1) for _ in range(n)]
    ans = 1
    for i in range(n):
        for p in range(i):
            cost = 0 if nums[p] == nums[i] else 1
            for j in range(cost, k + 1):
                if f[p][j - cost] + 1 > f[i][j]:
                    f[i][j] = f[p][j - cost] + 1
                if f[i][j] > ans:
                    ans = f[i][j]
    return ans

class Solution {
    public int maxLengthGoodSubsequence(int[] nums, int k) {
        int n = nums.length;
        int[][] f = new int[n][k + 1];
        for (int[] r : f) java.util.Arrays.fill(r, 1);
        int ans = 1;
        for (int i = 0; i < n; i++) {
            for (int p = 0; p < i; p++) {
                int cost = nums[p] == nums[i] ? 0 : 1;
                for (int j = cost; j <= k; j++) {
                    if (f[p][j - cost] + 1 > f[i][j]) f[i][j] = f[p][j - cost] + 1;
                    if (f[i][j] > ans) ans = f[i][j];
                }
            }
        }
        return ans;
    }
}

