                    if (f[i][j] > ans) ans = f[i][j];
                }
            }
        }
        return ans;
    }
};

def getEarliestMeetTime(events, k):
    def to_min(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)
    busy = []
    for e in events:
        parts = e.split()
        s, en = to_min(parts[-2]), to_min(parts[-1]) + 1   # end inclusive → +1
        busy.append((s, en))
    busy.sort()
    merged = []
    for s, en in busy:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], en))
        else:
            merged.append((s, en))
    cur = 0
    for s, en in merged:
        if s - cur >= k:
            h, m = divmod(cur, 60)
            return f"{h:02d}:{m:02d}"
        cur = max(cur, en)
    if 1440 - cur >= k:
        h, m = divmod(cur, 60)
        return f"{h:02d}:{m:02d}"
    return "-1"

class Solution {
    int toMin(String t) {
        String[] p = t.split(":");
        return Integer.parseInt(p[0]) * 60 + Integer.parseInt(p[1]);
    }
    public String getEarliestMeetTime(String[] events, int k) {
        java.util.List<int[]> busy = new java.util.ArrayList<>();
        for (String e : events) {
            String[] parts = e.split(" ");
            int s = toMin(parts[parts.length - 2]);
            int en = toMin(parts[parts.length - 1]) + 1;
            busy.add(new int[]{s, en});
        }
        busy.sort((a, b) -> a[0] - b[0]);
        java.util.List<int[]> merged = new java.util.ArrayList<>();
        for (int[] iv : busy) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1]) {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
            } else merged.add(iv);
        }
        int cur = 0;
        for (int[] iv : merged) {
            if (iv[0] - cur >= k) return String.format("%02d:%02d", cur / 60, cur % 60);
            cur = Math.max(cur, iv[1]);
        }
        if (1440 - cur >= k) return String.format("%02d:%02d", cur / 60, cur % 60);
        return "-1";
    }
}

class Solution {
public:
    int toMin(const string& t) { return stoi(t.substr(0, 2)) * 60 + stoi(t.substr(3, 2)); }
    string getEarliestMeetTime(vector<string>& events, int k) {
        vector<pair<int,int>> busy;
        for (auto& e : events) {
            vector<string> parts;
            stringstream ss(e);
            string tok;
            while (ss >> tok) parts.push_back(tok);
            int s = toMin(parts[parts.size() - 2]);
            int en = toMin(parts[parts.size() - 1]) + 1;
            busy.push_back({s, en});
        }
        sort(busy.begin(), busy.end());
        vector<pair<int,int>> merged;
        for (auto& iv : busy) {
            if (!merged.empty() && iv.first <= merged.back().second)
                merged.back().second = max(merged.back().second, iv.second);
            else merged.push_back(iv);
        }
        int cur = 0;
        char buf[8];
        for (auto& iv : merged) {
            if (iv.first - cur >= k) {
                snprintf(buf, sizeof(buf), "%02d:%02d", cur / 60, cur % 60);
                return string(buf);
            }
            cur = max(cur, iv.second);
        }
        if (1440 - cur >= k) {
            snprintf(buf, sizeof(buf), "%02d:%02d", cur / 60, cur % 60);
            return string(buf);
        }
        return "-1";
    }
};

def getMaxBeautifulSubstrings(color):
    NEG = -1
    f = [0] * 26   # 当前最佳 beautiful 数；NEG 表示不可达
    r = [0] * 26
    reachable = [False] * 26
    # 初始：空串，0 个字符；"起新段" 时取 max(f[*]) + 1，r = 1
    best_prev = 0   # max(f[c]) 当 prev 状态可用，初始为 0（空）
    best_prev_c = -1
    for ch in color:
        nf = [0] * 26
        nr = [0] * 26
        nreach = [False] * 26
        if ch == '.':
            cs = range(26)
        else:
            cs = [ord(ch) - ord('a')]
        # 预计算除某 c 外的最大 f
        max1, c1 = -1, -1
        max2 = -1
        for c in range(26):
            if reachable[c]:
                if f[c] > max1:
                    max2 = max1
                    max1 = f[c]; c1 = c
                elif f[c] > max2:
                    max2 = f[c]
        for c in cs:
            # 延续：要求上一位字符就是 c 且 reachable
            best_extend = -1
            if reachable[c]:
                best_extend = f[c] + r[c] + 1
            # 新起：从非 c 的最大 f 起，得分 + 1，r = 1
            if c == c1:
                base = max2
            else:
                base = max1
            best_new = -1
            if base >= 0:
                best_new = base + 1
            elif not any(reachable):
                # 第一字符
                best_new = 1
            # 也可能完全没有上一段（只有第一个字符）
            if not any(reachable):
                best_new = 1
            cand_f, cand_r = -1, 0
            if best_extend > cand_f:
                cand_f = best_extend; cand_r = r[c] + 1
            if best_new > cand_f:
                cand_f = best_new; cand_r = 1
            if cand_f >= 0:
                nf[c] = cand_f
                nr[c] = cand_r
                nreach[c] = True
        f, r, reachable = nf, nr, nreach
    ans = 0
    for c in range(26):
        if reachable[c] and f[c] > ans:
            ans = f[c]
    return ans

class Solution {
    public int getMaxBeautifulSubstrings(String color) {
        int n = color.length();
        int[] f = new int[26], r = new int[26];
        boolean[] reach = new boolean[26];
        for (int i = 0; i < n; i++) {
            char ch = color.charAt(i);
            int[] nf = new int[26], nr = new int[26];
            boolean[] nreach = new boolean[26];
            int max1 = -1, c1 = -1, max2 = -1;
            boolean anyReach = false;
            for (int c = 0; c < 26; c++) if (reach[c]) {
                anyReach = true;
                if (f[c] > max1) { max2 = max1; max1 = f[c]; c1 = c; }
                else if (f[c] > max2) max2 = f[c];
            }
            int lo, hi;
            if (ch == '.') { lo = 0; hi = 26; }
            else { lo = ch - 'a'; hi = lo + 1; }
            for (int c = lo; c < hi; c++) {
                int cand = -1, cr = 0;
                if (reach[c]) { int v = f[c] + r[c] + 1; if (v > cand) { cand = v; cr = r[c] + 1; } }
                int base = (c == c1) ? max2 : max1;
                if (base >= 0) { int v = base + 1; if (v > cand) { cand = v; cr = 1; } }
                if (!anyReach) { cand = 1; cr = 1; }
                if (cand >= 0) { nf[c] = cand; nr[c] = cr; nreach[c] = true; }
            }
            f = nf; r = nr; reach = nreach;
        }
        int ans = 0;
        for (int c = 0; c < 26; c++) if (reach[c] && f[c] > ans) ans = f[c];
        return ans;
    }
}

