def getMaxUpgradedServers(num_servers, money, sell, upgrade):
    ans = []
    for num, m, s, u in zip(num_servers, money, sell, upgrade):
        cap = (m + num * s) // (u + s)
        ans.append(min(num, cap))
    return ans

class Solution {
    public int[] getMaxUpgradedServers(int[] num_servers, int[] money, int[] sell, int[] upgrade) {
        int n = num_servers.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            long cap = ((long) money[i] + (long) num_servers[i] * sell[i]) / (upgrade[i] + sell[i]);
            ans[i] = (int) Math.min(num_servers[i], cap);
        }
        return ans;
    }
}

