    }
};

def getMaximumRemovals(order, source, target):
    n = len(source)
    removed_at = [0] * n
    for step, pos in enumerate(order, start=1):
        removed_at[pos - 1] = step
    def ok(k):
        j = 0
        for i in range(n):
            if removed_at[i] > k and source[i] == target[j]:
                j += 1
                if j == len(target):
                    return True
        return False
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

class Solution {
    public int getMaximumRemovals(int[] order, String source, String target) {
        int n = source.length();
        int[] removedAt = new int[n];
        for (int s = 0; s < order.length; s++) removedAt[order[s] - 1] = s + 1;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (ok(removedAt, source, target, mid)) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
    boolean ok(int[] removedAt, String source, String target, int k) {
        int j = 0;
        for (int i = 0; i < source.length(); i++) {
            if (removedAt[i] > k && source.charAt(i) == target.charAt(j)) {
                j++;
                if (j == target.length()) return true;
            }
        }
        return false;
    }
}

class Solution {
public:
