        int n = source.size();
        vector<int> removedAt(n);
        for (int s = 0; s < (int) order.size(); ++s) removedAt[order[s] - 1] = s + 1;
        auto ok = [&](int k) {
            int j = 0;
            for (int i = 0; i < n; ++i) if (removedAt[i] > k && source[i] == target[j]) {
                j++;
                if (j == (int) target.size()) return true;
            }
            return false;
        };
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (ok(mid)) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
};

class Solution {
    public int getMaxFrequencySubstring(String s, int minLength, int maxLength, int maxUnique) {
        int n = s.length();
        int[] freq = new int[26];
        int unique = 0, best = 0, L = minLength;
        java.util.HashMap<String, Integer> cnt = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (freq[c] == 0) unique++;
            freq[c]++;
            if (i >= L) {
                int c2 = s.charAt(i - L) - 'a';
                freq[c2]--;
                if (freq[c2] == 0) unique--;
            }
            if (i >= L - 1 && unique <= maxUnique) {
                String sub = s.substring(i - L + 1, i + 1);
                int v = cnt.getOrDefault(sub, 0) + 1;
                cnt.put(sub, v);
                if (v > best) best = v;
            }
        }
        return best;
    }
}

class Solution {
public:
    int getMaxFrequencySubstring(string s, int minLength, int maxLength, int maxUnique) {
        int n = s.size();
        int freq[26] = {0};
        int unique = 0, best = 0, L = minLength;
        unordered_map<string, int> cnt;
        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a';
            if (freq[c] == 0) unique++;
            freq[c]++;
            if (i >= L) {
                int c2 = s[i - L] - 'a';
                freq[c2]--;
                if (freq[c2] == 0) unique--;
            }
            if (i >= L - 1 && unique <= maxUnique) {
                string sub = s.substr(i - L + 1, L);
                int v = ++cnt[sub];
                if (v > best) best = v;
            }
        }
        return best;
    }
};

def maxPassengers(mat):
    n = len(mat)
    NEG = float('-inf')
    # f[i1][i2] 当前步数下两条路径分别位于 row i1, row i2
    f = [[NEG] * n for _ in range(n)]
    if mat[0][0] != -1:
        f[0][0] = mat[0][0]
    for k in range(1, 2 * n - 1):
        nf = [[NEG] * n for _ in range(n)]
        for i1 in range(max(0, k - n + 1), min(n, k + 1)):
            j1 = k - i1
            if mat[i1][j1] == -1: continue
            for i2 in range(max(0, k - n + 1), min(n, k + 1)):
                j2 = k - i2
                if mat[i2][j2] == -1: continue
                best = NEG
                for d1 in (0, -1):
                    for d2 in (0, -1):
                        pi1, pi2 = i1 + d1, i2 + d2
                        if 0 <= pi1 < n and 0 <= pi2 < n and f[pi1][pi2] > best:
                            best = f[pi1][pi2]
                if best == NEG: continue
                add = mat[i1][j1] if mat[i1][j1] > 0 else 0
                if i1 != i2:
                    add += mat[i2][j2] if mat[i2][j2] > 0 else 0
                nf[i1][i2] = best + add
        f = nf
    ans = f[n - 1][n - 1]
    return max(ans, 0)

class Solution {
    public int maxPassengers(int[][] mat) {
        int n = mat.length;
        int NEG = Integer.MIN_VALUE / 2;
        int[][] f = new int[n][n];
        for (int[] row : f) java.util.Arrays.fill(row, NEG);
        if (mat[0][0] != -1) f[0][0] = mat[0][0];
        for (int k = 1; k < 2 * n - 1; k++) {
            int[][] nf = new int[n][n];
            for (int[] row : nf) java.util.Arrays.fill(row, NEG);
            for (int i1 = Math.max(0, k - n + 1); i1 < Math.min(n, k + 1); i1++) {
                int j1 = k - i1;
                if (mat[i1][j1] == -1) continue;
                for (int i2 = Math.max(0, k - n + 1); i2 < Math.min(n, k + 1); i2++) {
                    int j2 = k - i2;
                    if (mat[i2][j2] == -1) continue;
                    int best = NEG;
                    for (int d1 = 0; d1 >= -1; d1--) for (int d2 = 0; d2 >= -1; d2--) {
                        int pi1 = i1 + d1, pi2 = i2 + d2;
                        if (pi1 >= 0 && pi1 < n && pi2 >= 0 && pi2 < n) best = Math.max(best, f[pi1][pi2]);
                    }
                    if (best == NEG) continue;
                    int add = Math.max(mat[i1][j1], 0);
                    if (i1 != i2) add += Math.max(mat[i2][j2], 0);
                    nf[i1][i2] = best + add;
                }
            }
            f = nf;
        }
        return Math.max(f[n - 1][n - 1], 0);
    }
}

class Solution {
public:
    int maxPassengers(vector<vector<int>>& mat) {
        int n = mat.size();
        int NEG = INT_MIN / 2;
        vector<vector<int>> f(n, vector<int>(n, NEG));
        if (mat[0][0] != -1) f[0][0] = mat[0][0];
        for (int k = 1; k < 2 * n - 1; ++k) {
            vector<vector<int>> nf(n, vector<int>(n, NEG));
            for (int i1 = max(0, k - n + 1); i1 < min(n, k + 1); ++i1) {
