                    if (mat[i2][j2] == -1) continue;
                    int best = NEG;
                    for (int d1 = 0; d1 >= -1; --d1) for (int d2 = 0; d2 >= -1; --d2) {
                        int pi1 = i1 + d1, pi2 = i2 + d2;
