    }
};

from collections import deque, defaultdict

def solveMinimumWikiClicks(input_str):
    lines = input_str.strip().split('\n')
    m = int(lines[0])
    g = defaultdict(list)
    for i in range(1, m + 1):
        u, v = lines[i].split()
        g[u].append(v)
    start, target = lines[m + 1].split()
    if start == target:
        return ["0"]
    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in g[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                if v == target:
                    return [str(dist[v])]
                q.append(v)
    return ["-1"]

class Solution {
    public String[] solveMinimumWikiClicks(String input) {
        String[] lines = input.strip().split("\n");
        int m = Integer.parseInt(lines[0]);
        java.util.HashMap<String, java.util.List<String>> g = new java.util.HashMap<>();
        for (int i = 1; i <= m; i++) {
            String[] p = lines[i].split(" ");
            g.computeIfAbsent(p[0], k -> new java.util.ArrayList<>()).add(p[1]);
        }
        String[] se = lines[m + 1].split(" ");
        String start = se[0], target = se[1];
        if (start.equals(target)) return new String[]{"0"};
        java.util.HashMap<String, Integer> dist = new java.util.HashMap<>();
        dist.put(start, 0);
        java.util.ArrayDeque<String> q = new java.util.ArrayDeque<>();
        q.offer(start);
        while (!q.isEmpty()) {
            String u = q.poll();
            for (String v : g.getOrDefault(u, java.util.Collections.emptyList())) {
                if (!dist.containsKey(v)) {
                    dist.put(v, dist.get(u) + 1);
                    if (v.equals(target)) return new String[]{dist.get(v).toString()};
                    q.offer(v);
                }
            }
        }
        return new String[]{"-1"};
    }
}

class Solution {
public:
    vector<string> solveMinimumWikiClicks(string input) {
        vector<string> lines;
        size_t p = 0;
        while (p < input.size()) {
            size_t q = input.find('\n', p);
            if (q == string::npos) q = input.size();
            lines.push_back(input.substr(p, q - p));
            p = q + 1;
        }
        int m = stoi(lines[0]);
        unordered_map<string, vector<string>> g;
        for (int i = 1; i <= m; ++i) {
            size_t sp = lines[i].find(' ');
            g[lines[i].substr(0, sp)].push_back(lines[i].substr(sp + 1));
        }
        size_t sp = lines[m + 1].find(' ');
        string start = lines[m + 1].substr(0, sp), target = lines[m + 1].substr(sp + 1);
        if (start == target) return {"0"};
        unordered_map<string, int> dist;
        dist[start] = 0;
        queue<string> q;
        q.push(start);
        while (!q.empty()) {
            string u = q.front(); q.pop();
            for (auto& v : g[u]) {
                if (!dist.count(v)) {
                    dist[v] = dist[u] + 1;
                    if (v == target) return {to_string(dist[v])};
                    q.push(v);
                }
            }
        }
        return {"-1"};
    }
};

def minimumDivision(a, b, k):
    n = len(a)
    iv = sorted(zip(a, b))
    merged = []
    for s, e in iv:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    C = len(merged)
    if C <= 1:
        return 1
    # 滑窗找最大连续可桥接的块数
    best = 1
    l = 0
    for r in range(C):
        while l < r and merged[r][0] - merged[l][1] > k:
            l += 1
        best = max(best, r - l + 1)
    return C - (best - 1)

class Solution {
    public int minimumDivision(int[] a, int[] b, int k) {
        int n = a.length;
        int[][] iv = new int[n][2];
        for (int i = 0; i < n; i++) { iv[i][0] = a[i]; iv[i][1] = b[i]; }
        java.util.Arrays.sort(iv, (x, y) -> x[0] - y[0]);
        java.util.List<int[]> merged = new java.util.ArrayList<>();
        for (int[] iv2 : iv) {
            if (!merged.isEmpty() && iv2[0] <= merged.get(merged.size() - 1)[1])
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv2[1]);
            else merged.add(iv2);
        }
        int C = merged.size();
        if (C <= 1) return 1;
        int best = 1, l = 0;
        for (int r = 0; r < C; r++) {
            while (l < r && (long) merged.get(r)[0] - merged.get(l)[1] > k) l++;
            best = Math.max(best, r - l + 1);
        }
        return C - (best - 1);
    }
}

class Solution {
public:
    int minimumDivision(vector<int>& a, vector<int>& b, int k) {
        int n = a.size();
        vector<pair<int,int>> iv;
        for (int i = 0; i < n; ++i) iv.push_back({a[i], b[i]});
        sort(iv.begin(), iv.end());
        vector<pair<int,int>> merged;
        for (auto& p : iv) {
            if (!merged.empty() && p.first <= merged.back().second)
                merged.back().second = max(merged.back().second, p.second);
            else merged.push_back(p);
        }
        int C = merged.size();
        if (C <= 1) return 1;
        int best = 1, l = 0;
        for (int r = 0; r < C; ++r) {
            while (l < r && (long long) merged[r].first - merged[l].second > k) l++;
            best = max(best, r - l + 1);
        }
        return C - (best - 1);
    }
};

def solveMinimumPersonCakeDistance(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    last1 = last2 = -1
    best = float('inf')
    for i, v in enumerate(a):
        if v == 1:
            if last2 != -1:
                best = min(best, i - last2)
            last1 = i
        elif v == 2:
            if last1 != -1:
                best = min(best, i - last1)
            last2 = i
    return [str(best) if best != float('inf') else "-1"]

class Solution {
    public String[] solveMinimumPersonCakeDistance(String input) {
        String[] lines = input.strip().split("\n");
        int n = Integer.parseInt(lines[0]);
        String[] toks = lines[1].split("\\s+");
        int last1 = -1, last2 = -1, best = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int v = Integer.parseInt(toks[i]);
            if (v == 1) {
                if (last2 != -1) best = Math.min(best, i - last2);
                last1 = i;
            } else if (v == 2) {
                if (last1 != -1) best = Math.min(best, i - last1);
                last2 = i;
            }
        }
        return new String[]{best == Integer.MAX_VALUE ? "-1" : Integer.toString(best)};
    }
}

class Solution {
