def paintTheCeiling(s0, n, k, b, m, a):
    s = [0] * n
    s[0] = s0
    for i in range(1, n):
        s[i] = ((k * s[i - 1] + b) % m) + 1 + s[i - 1]
    # s 严格递增。对每个 i 找最大 j 使 s[i]*s[j] <= a
    ans = 0
    j = n - 1
    for i in range(n):
        if j < i:
            j = i - 1
        while j >= 0 and s[i] * s[j] > a:
            j -= 1
        if j >= 0:
            ans += j + 1   # j 个 s[0..j] 都能配 s[i]
    return ans

class Solution {
    public long paintTheCeiling(int s0, int n, int k, int b, int m, long a) {
        long[] s = new long[n];
        s[0] = s0;
        for (int i = 1; i < n; i++) s[i] = ((long)(k * s[i - 1] + b) % m) + 1 + s[i - 1];
        long ans = 0;
        int j = n - 1;
        for (int i = 0; i < n; i++) {
            if (j < i) j = i - 1;
            while (j >= 0 && s[i] * s[j] > a) j--;
            if (j >= 0) ans += j + 1;
        }
        return ans;
    }
}

