        long long ans = 0;
        int j = n - 1;
        for (int i = 0; i < n; ++i) {
            if (j < i) j = i - 1;
            while (j >= 0 && s[i] * s[j] > a) j--;
            if (j >= 0) ans += j + 1;
        }
        return ans;
    }
};

from collections import Counter

def processLogs(logs, threshold):
    cnt = Counter()
    for log in logs:
        s, r, _ = log.split()
        if s == r:
            cnt[s] += 1
        else:
            cnt[s] += 1
            cnt[r] += 1
    res = [u for u, c in cnt.items() if c >= threshold]
    res.sort(key=int)
    return res

class Solution {
    public String[] processLogs(String[] logs, int threshold) {
        java.util.HashMap<String, Integer> cnt = new java.util.HashMap<>();
        for (String log : logs) {
            String[] p = log.split(" ");
            cnt.merge(p[0], 1, Integer::sum);
            if (!p[0].equals(p[1])) cnt.merge(p[1], 1, Integer::sum);
        }
        java.util.List<String> res = new java.util.ArrayList<>();
        for (var e : cnt.entrySet()) if (e.getValue() >= threshold) res.add(e.getKey());
        res.sort((x, y) -> Long.compare(Long.parseLong(x), Long.parseLong(y)));
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> processLogs(vector<string>& logs, int threshold) {
        unordered_map<string, int> cnt;
        for (auto& log : logs) {
            stringstream ss(log);
            string s, r, amt;
            ss >> s >> r >> amt;
            cnt[s]++;
            if (s != r) cnt[r]++;
        }
        vector<string> res;
        for (auto& [k, v] : cnt) if (v >= threshold) res.push_back(k);
        sort(res.begin(), res.end(), [](const string& a, const string& b){
            return stoll(a) < stoll(b);
        });
        return res;
    }
};

from collections import deque

def radioWaves(network_nodes, network_from, network_to, frequency):
    n = network_nodes
    g = [[] for _ in range(n + 1)]
    for u, v in zip(network_from, network_to):
        if abs(frequency[u - 1] - frequency[v - 1]) <= 1:
            g[u].append(v)
            g[v].append(u)
    visited = [False] * (n + 1)
    best = 0
    def bfs_far(src):
        dist = {src: 0}
        q = deque([src])
        far_node, far_d = src, 0
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    if dist[v] > far_d:
                        far_d = dist[v]; far_node = v
                    q.append(v)
        return far_node, far_d, dist
    for i in range(1, n + 1):
        if not visited[i]:
            u, _, dist = bfs_far(i)
            for x in dist: visited[x] = True
            _, d, dist2 = bfs_far(u)
            for x in dist2: visited[x] = True
            best = max(best, d)
    return best

class Solution {
    public int radioWaves(int n, int[] network_from, int[] network_to, int[] frequency) {
        java.util.List<java.util.List<Integer>> g = new java.util.ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new java.util.ArrayList<>());
        for (int i = 0; i < network_from.length; i++) {
            int u = network_from[i], v = network_to[i];
            if (Math.abs(frequency[u - 1] - frequency[v - 1]) <= 1) {
                g.get(u).add(v); g.get(v).add(u);
            }
        }
        boolean[] vis = new boolean[n + 1];
        int best = 0;
        for (int s = 1; s <= n; s++) if (!vis[s]) {
            int[] f1 = bfsFar(g, s, vis, false);
            int[] f2 = bfsFar(g, f1[0], vis, true);
            best = Math.max(best, f2[1]);
        }
        return best;
    }
    int[] bfsFar(java.util.List<java.util.List<Integer>> g, int src, boolean[] vis, boolean markVisited) {
        java.util.HashMap<Integer, Integer> dist = new java.util.HashMap<>();
        dist.put(src, 0);
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.offer(src);
        int farNode = src, farD = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (!dist.containsKey(v)) {
                dist.put(v, dist.get(u) + 1);
                if (dist.get(v) > farD) { farD = dist.get(v); farNode = v; }
                q.offer(v);
            }
        }
        if (markVisited) for (int x : dist.keySet()) vis[x] = true;
        else for (int x : dist.keySet()) vis[x] = true;
        return new int[]{farNode, farD};
    }
}

class Solution {
public:
    int radioWaves(int n, vector<int>& network_from, vector<int>& network_to, vector<int>& frequency) {
        vector<vector<int>> g(n + 1);
        for (int i = 0; i < (int) network_from.size(); ++i) {
            int u = network_from[i], v = network_to[i];
            if (abs(frequency[u - 1] - frequency[v - 1]) <= 1) {
                g[u].push_back(v); g[v].push_back(u);
            }
        }
        vector<bool> vis(n + 1, false);
        int best = 0;
        auto bfsFar = [&](int src) -> pair<int,int> {
            unordered_map<int,int> dist;
            dist[src] = 0;
            queue<int> q;
            q.push(src);
            int farNode = src, farD = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : g[u]) if (!dist.count(v)) {
                    dist[v] = dist[u] + 1;
                    if (dist[v] > farD) { farD = dist[v]; farNode = v; }
                    q.push(v);
                }
            }
            for (auto& p : dist) vis[p.first] = true;
            return {farNode, farD};
        };
        for (int s = 1; s <= n; ++s) if (!vis[s]) {
            auto first = bfsFar(s);
            auto second = bfsFar(first.first);
            best = max(best, second.second);
        }
        return best;
    }
};

import heapq

def minStoneSum(piles, k):
    h = [-p for p in piles]
    heapq.heapify(h)
    for _ in range(k):
        p = -heapq.heappop(h)
        heapq.heappush(h, -((p + 1) // 2))
    return -sum(h)

class Solution {
    public int minStoneSum(int[] piles, int k) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int p : piles) pq.offer(p);
        for (int i = 0; i < k; i++) {
            int p = pq.poll();
            pq.offer((p + 1) / 2);
        }
        int ans = 0;
        for (int v : pq) ans += v;
        return ans;
    }
}

class Solution {
public:
    int minStoneSum(vector<int>& piles, int k) {
        priority_queue<int> pq(piles.begin(), piles.end());
        for (int i = 0; i < k; ++i) {
            int p = pq.top(); pq.pop();
            pq.push((p + 1) / 2);
        }
        int ans = 0;
        while (!pq.empty()) { ans += pq.top(); pq.pop(); }
        return ans;
    }
};

def selectStock(saving, currentValue, futureValue):
    n = len(currentValue)
    f = [0] * (saving + 1)
    for i in range(n):
        w = currentValue[i]
        p = futureValue[i] - currentValue[i]
        if p <= 0:
            continue
        for j in range(saving, w - 1, -1):
            if f[j - w] + p > f[j]:
                f[j] = f[j - w] + p
    return f[saving]

class Solution {
    public int selectStock(int saving, int[] currentValue, int[] futureValue) {
        int[] f = new int[saving + 1];
        for (int i = 0; i < currentValue.length; i++) {
            int w = currentValue[i], p = futureValue[i] - currentValue[i];
            if (p <= 0) continue;
            for (int j = saving; j >= w; j--) {
                if (f[j - w] + p > f[j]) f[j] = f[j - w] + p;
            }
        }
        return f[saving];
    }
}

class Solution {
