        vector<int> f(saving + 1, 0);
        for (int i = 0; i < (int) currentValue.size(); ++i) {
            int w = currentValue[i], p = futureValue[i] - currentValue[i];
            if (p <= 0) continue;
            for (int j = saving; j >= w; --j) {
                if (f[j - w] + p > f[j]) f[j] = f[j - w] + p;
            }
        }
        return f[saving];
    }
};

