def superBitstrings(n, bitStrings):
    k = len(bitStrings)
    ans = 0
    for mask in range(1, 1 << k):
        orv = 0
        bits = 0
        for i in range(k):
            if mask >> i & 1:
                orv |= bitStrings[i]
                bits += 1
        sign = 1 if bits % 2 == 1 else -1
        ans += sign * (1 << (n - bin(orv).count('1')))
    return ans

class Solution {
    public long superBitstrings(int n, int[] bitStrings) {
        int k = bitStrings.length;
        long ans = 0;
        for (int mask = 1; mask < (1 << k); mask++) {
            int orv = 0, bits = 0;
            for (int i = 0; i < k; i++) if ((mask >> i & 1) == 1) { orv |= bitStrings[i]; bits++; }
            long sign = (bits % 2 == 1) ? 1 : -1;
            ans += sign * (1L << (n - Integer.bitCount(orv)));
        }
        return ans;
    }
}

class Solution {
public:
    long long superBitstrings(int n, vector<int>& bitStrings) {
        int k = bitStrings.size();
        long long ans = 0;
        for (int mask = 1; mask < (1 << k); ++mask) {
            int orv = 0, bits = 0;
            for (int i = 0; i < k; ++i) if (mask >> i & 1) { orv |= bitStrings[i]; bits++; }
            long long sign = (bits % 2 == 1) ? 1 : -1;
            ans += sign * (1LL << (n - __builtin_popcount(orv)));
        }
        return ans;
    }
};

def distinct_goodness(arr):
    n = len(arr)
    dp = []
    all_ = {0}
    for i in range(n):
        cur = {arr[i]}
        for j in range(i):
            if arr[j] < arr[i]:
                for x in dp[j]:
                    cur.add(x | arr[i])
        dp.append(cur)
        all_ |= cur
    return len(all_)

import java.util.*;

class Solution {
    int distinctGoodness(int[] arr) {
        int n = arr.length;
        List<Set<Integer>> dp = new ArrayList<>();
        Set<Integer> all = new HashSet<>();
        all.add(0);
        for (int i = 0; i < n; i++) {
            Set<Integer> cur = new HashSet<>();
            cur.add(arr[i]);
            for (int j = 0; j < i; j++) {
                if (arr[j] < arr[i]) {
                    for (int x : dp.get(j)) cur.add(x | arr[i]);
                }
            }
            dp.add(cur);
            all.addAll(cur);
        }
        return all.size();
    }
}

