def distinct_palindromic_substrings(s):
    n = len(s)
    out = set()
    for c in range(n):
        l, r = c, c
        while l >= 0 and r < n and s[l] == s[r]:
            out.add(s[l:r + 1]); l -= 1; r += 1
        l, r = c, c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            out.add(s[l:r + 1]); l -= 1; r += 1
    return len(out)

