class Solution {
    int distinctPalindromicSubstrings(String s) {
        int n = s.length();
        Set<String> out = new HashSet<>();
        for (int c = 0; c < n; c++) {
            int l = c, r = c;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                out.add(s.substring(l, r + 1)); l--; r++;
            }
            l = c; r = c + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                out.add(s.substring(l, r + 1)); l--; r++;
            }
        }
        return out.size();
    }
}

