def largest_path_sum(parent, values):
    n = len(parent)
    children = [[] for _ in range(n)]
    root = 0
    for i, p in enumerate(parent):
        if p == -1: root = i
        else: children[p].append(i)
    best = [0] * n
    order = []
    stack = [root]
    while stack:
        u = stack.pop()
        order.append(u)
        for c in children[u]: stack.append(c)
    for u in reversed(order):
        best[u] = values[u] + max((max(0, best[c]) for c in children[u]), default=0)
    return max(best)

import java.util.*;

class Solution {
    long largestPathSum(int[] parent, int[] values) {
        int n = parent.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        int root = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == -1) root = i;
            else children.get(parent[i]).add(i);
        }
        long[] best = new long[n];
        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[idx++] = u;
            for (int c : children.get(u)) stack.push(c);
        }
        for (int k = n - 1; k >= 0; k--) {
            int u = order[k];
            long m = 0;
            for (int c : children.get(u)) m = Math.max(m, best[c]);
            best[u] = values[u] + m;
        }
        long ans = Long.MIN_VALUE;
        for (long b : best) ans = Math.max(ans, b);
        return ans;
    }
}

