def calculate_score(text, prefixString, suffixString):
    n = len(text)
    def pre(i):
        m = len(prefixString)
        best = 0
        for L in range(1, min(m, n - i) + 1):
            if prefixString[m - L:] == text[i:i + L]:
                best = L
        return best
    def suf(j):
        best = 0
        for L in range(1, min(len(suffixString), j + 1) + 1):
            if suffixString[:L] == text[j - L + 1:j + 1]:
                best = L
        return best
    pre_arr = [pre(i) for i in range(n)]
    suf_arr = [suf(j) for j in range(n)]
    best_sc, best_sub = -1, ""
    for i in range(n):
        for j in range(i, n):
            sc = pre_arr[i] + suf_arr[j]
            sub = text[i:j + 1]
            if sc > best_sc or (sc == best_sc and sub < best_sub):
                best_sc, best_sub = sc, sub
    return best_sub

class Solution {
    String calculateScore(String text, String prefixString, String suffixString) {
        int n = text.length();
        int[] preArr = new int[n];
        int[] sufArr = new int[n];
        for (int i = 0; i < n; i++) {
            int best = 0, m = prefixString.length(), lim = Math.min(m, n - i);
            for (int L = 1; L <= lim; L++)
                if (prefixString.substring(m - L).equals(text.substring(i, i + L)))
                    best = L;
            preArr[i] = best;
        }
        for (int j = 0; j < n; j++) {
            int best = 0, lim = Math.min(suffixString.length(), j + 1);
            for (int L = 1; L <= lim; L++)
                if (suffixString.substring(0, L).equals(text.substring(j - L + 1, j + 1)))
                    best = L;
            sufArr[j] = best;
        }
        int bestSc = -1;
        String bestSub = "";
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                int sc = preArr[i] + sufArr[j];
                String sub = text.substring(i, j + 1);
                if (sc > bestSc || (sc == bestSc && sub.compareTo(bestSub) < 0)) {
                    bestSc = sc;
                    bestSub = sub;
                }
            }
        return bestSub;
    }
}

