def find_valid_sizes(memoryBlocks):
    a = sorted(memoryBlocks)
    K = 0
    for k in range(1, len(a) + 1):
        if a[k - 1] <= k - 1:
            K = k
        else:
            break
    return list(range(K + 1))

import java.util.*;

class Solution {
    int[] findValidSizes(int[] memoryBlocks) {
        int n = memoryBlocks.length;
        int[] a = memoryBlocks.clone();
        Arrays.sort(a);
        int K = 0;
        for (int k = 1; k <= n; k++) {
            if (a[k - 1] <= k - 1) K = k;
            else break;
        }
        int[] out = new int[K + 1];
        for (int i = 0; i <= K; i++) out[i] = i;
        return out;
    }
}

