def max_earnings(n, k, fixedPay, bonus, schedule):
    NEG = float('-inf')
    f = [[[NEG] * 2 for _ in range(k + 1)] for _ in range(n + 1)]
    f[0][0][0] = 0
    for i in range(n):
        for j in range(k + 1):
            for last in range(2):
                if f[i][j][last] == NEG: continue
                cur = int(schedule[i])
                earn = fixedPay + (bonus if last and cur else 0) if cur else 0
                if f[i + 1][j][cur] < f[i][j][last] + earn:
                    f[i + 1][j][cur] = f[i][j][last] + earn
                if schedule[i] == '0' and j < k:
                    e2 = fixedPay + (bonus if last else 0)
                    if f[i + 1][j + 1][1] < f[i][j][last] + e2:
                        f[i + 1][j + 1][1] = f[i][j][last] + e2
    return max(f[n][j][last] for j in range(k + 1) for last in range(2))

class Solution {
    long maxEarnings(int n, int k, int fixedPay, int bonus, String schedule) {
        long NEG = Long.MIN_VALUE / 4;
        long[][][] f = new long[n + 1][k + 1][2];
        for (long[][] g : f) for (long[] h : g) java.util.Arrays.fill(h, NEG);
        f[0][0][0] = 0;
        for (int i = 0; i < n; i++) {
            int cur = schedule.charAt(i) - '0';
            for (int j = 0; j <= k; j++)
                for (int last = 0; last < 2; last++) {
                    if (f[i][j][last] == NEG) continue;
                    long earn = cur == 1 ? fixedPay + (last == 1 ? bonus : 0) : 0;
                    if (f[i + 1][j][cur] < f[i][j][last] + earn)
                        f[i + 1][j][cur] = f[i][j][last] + earn;
                    if (schedule.charAt(i) == '0' && j < k) {
                        long e2 = fixedPay + (last == 1 ? bonus : 0);
                        if (f[i + 1][j + 1][1] < f[i][j][last] + e2)
                            f[i + 1][j + 1][1] = f[i][j][last] + e2;
                    }
                }
        }
        long best = Long.MIN_VALUE;
        for (int j = 0; j <= k; j++)
            for (int last = 0; last < 2; last++)
                best = Math.max(best, f[n][j][last]);
        return best;
    }
}

