class Solution {
    int checksumAggregation(int n) {
        final long MOD = 1_000_000_007L;
        long s = 0;
        for (long j = 1; j <= n; j++) {
            long q = n / j, r = n % j;
            s = (s + q * j * (j - 1) / 2 + r * (r + 1) / 2) % MOD;
        }
        return (int) (2 * s % MOD);
    }
}

long long checksumAggregation(int n) {
 const long long MOD = 1e9 + 7;
 long long s = 0;
 for (long long j = 1; j <= n; j++) {
 long long q = n / j, r = n % j;
 s = (s + q * j * (j - 1) / 2 + r * (r + 1) / 2) % MOD;
 }
 return 2 * s % MOD;
}

def get_optimal_team_size(lowerSkill, higherSkill):
    n = len(lowerSkill)

    def feasible(T):
        if T == 0:
            return True
        cands = []
        for i in range(n):
            lo = max(0, T - 1 - higherSkill[i])
            hi = min(T - 1, lowerSkill[i])
            if lo <= hi:
                cands.append((lo, hi))
        if len(cands) < T:
            return False
        # greedy: positions 0..T-1; pick smallest-hi candidate whose lo<=pos
        cands.sort(key=lambda x: (x[0], x[1]))
        # for each position p in 0..T-1, choose any candidate with lo<=p<=hi unused.
        # use a priority queue keyed by hi over candidates with lo<=p.
        import heapq
        heap = []
        idx = 0
        used = 0
        for p in range(T):
            while idx < len(cands) and cands[idx][0] <= p:
                heapq.heappush(heap, cands[idx][1])
                idx += 1
            while heap and heap[0] < p:
                heapq.heappop(heap)
            if not heap:
                return False
            heapq.heappop(heap)
            used += 1
        return used == T

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

import java.util.*;

class Solution {
    int[] lower, higher;
    int n;

    int getOptimalTeamSize(int[] lowerSkill, int[] higherSkill) {
        this.lower = lowerSkill;
        this.higher = higherSkill;
        this.n = lowerSkill.length;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (feasible(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }

    boolean feasible(int T) {
        if (T == 0) return true;
        List<int[]> cands = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int lo = Math.max(0, T - 1 - higher[i]);
            int hi = Math.min(T - 1, lower[i]);
            if (lo <= hi) cands.add(new int[]{lo, hi});
        }
        if (cands.size() < T) return false;
        cands.sort((a, b) -> a[0] - b[0]);
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        int idx = 0;
        for (int p = 0; p < T; p++) {
            while (idx < cands.size() && cands.get(idx)[0] <= p) {
                heap.offer(cands.get(idx)[1]);
                idx++;
            }
            while (!heap.isEmpty() && heap.peek() < p) heap.poll();
            if (heap.isEmpty()) return false;
            heap.poll();
        }
        return true;
    }
}

