        vector<pair<int,int>> cands;
        for (int i = 0; i < n; i++) {
            int lo = max(0, T - 1 - hi_[i]);
            int hi = min(T - 1, lo_[i]);
            if (lo <= hi) cands.push_back({lo, hi});
        }
        if ((int) cands.size() < T) return false;
        sort(cands.begin(), cands.end());
        priority_queue<int, vector<int>, greater<int>> heap;
        int idx = 0;
        for (int p = 0; p < T; p++) {
            while (idx < (int) cands.size() && cands[idx].first <= p) {
                heap.push(cands[idx].second);
                idx++;
            }
            while (!heap.empty() && heap.top() < p) heap.pop();
            if (heap.empty()) return false;
            heap.pop();
        }
        return true;
    }
