import java.util.*;

class Solution {
    long countStableSegments(int[] capacity) {
        int n = capacity.length;
        if (n < 3) return 0;
        long[] S = new long[n + 1];
        for (int i = 0; i < n; i++) S[i + 1] = S[i] + capacity[i];
        Map<Long, Integer> cnt = new HashMap<>();
        for (int r = 2; r < n; r++) {
            long key = ((long) capacity[r] << 32) ^ ((S[r] - capacity[r]) & 0xffffffffL);
            cnt.merge(key, 1, Integer::sum);
        }
        long ans = 0;
        for (int l = 0; l <= n - 3; l++) {
            long key = ((long) capacity[l] << 32) ^ (S[l + 1] & 0xffffffffL);
            ans += cnt.getOrDefault(key, 0);
            int nxtR = l + 2;
            if (nxtR < n) {
                long k = ((long) capacity[nxtR] << 32) ^ ((S[nxtR] - capacity[nxtR]) & 0xffffffffL);
                cnt.merge(k, -1, Integer::sum);
            }
        }
        return ans;
    }
}

class Solution {
public:
    long long countStableSegments(vector<int>& capacity) {
        int n = capacity.size();
        if (n < 3) return 0;
        vector<long long> S(n + 1, 0);
        for (int i = 0; i < n; i++) S[i + 1] = S[i] + capacity[i];
        map<pair<long long, long long>, int> cnt;
        for (int r = 2; r < n; r++) cnt[{capacity[r], S[r] - capacity[r]}]++;
        long long ans = 0;
        for (int l = 0; l <= n - 3; l++) {
            auto it = cnt.find({capacity[l], S[l + 1]});
            if (it != cnt.end()) ans += it->second;
            int nxtR = l + 2;
            if (nxtR < n) cnt[{capacity[nxtR], S[nxtR] - capacity[nxtR]}]--;
        }
        return ans;
    }
};

