class Solution {
    int findConsistentLogs(int[] userEvent) {
        int n = userEvent.length;
        Map<Integer, Integer> global = new HashMap<>();
        for (int u : userEvent) global.merge(u, 1, Integer::sum);
        int target = Integer.MAX_VALUE;
        for (int v : global.values()) target = Math.min(target, v);
        Map<Integer, Integer> cnt = new HashMap<>();
        int l = 0, best = 0;
        for (int r = 0; r < n; r++) {
            cnt.merge(userEvent[r], 1, Integer::sum);
            while (cnt.get(userEvent[r]) > target) {
                cnt.merge(userEvent[l], -1, Integer::sum);
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

class Solution {
public:
    int findConsistentLogs(vector<int>& userEvent) {
        int n = userEvent.size();
        unordered_map<int, int> global;
        for (int u : userEvent) global[u]++;
        int target = INT_MAX;
        for (auto& [k, v] : global) target = min(target, v);
        unordered_map<int, int> cnt;
        int l = 0, best = 0;
        for (int r = 0; r < n; r++) {
            cnt[userEvent[r]]++;
            while (cnt[userEvent[r]] > target) {
                cnt[userEvent[l]]--;
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};

class Solution {
    int findMinimumEqualSum(int[] rowA, int[] rowB) {
        long sumA = 0, sumB = 0;
        int zeroA = 0, zeroB = 0;
        for (int x : rowA) { sumA += x; if (x == 0) zeroA++; }
        for (int x : rowB) { sumB += x; if (x == 0) zeroB++; }
        long minA = sumA + zeroA, minB = sumB + zeroB;
        long target = Math.max(minA, minB);
        if (zeroA == 0 && sumA != target) return -1;
        if (zeroB == 0 && sumB != target) return -1;
        return (int) target;
    }
}

