class Solution {
    int[] getDistinctGoodnessValues(int[] arr) {
        int n = arr.length;
        List<Set<Integer>> dp = new ArrayList<>();
        TreeSet<Integer> all = new TreeSet<>();
        all.add(0);
        for (int i = 0; i < n; i++) {
            Set<Integer> cur = new HashSet<>();
            cur.add(arr[i]);
            for (int j = 0; j < i; j++) {
                if (arr[j] < arr[i]) {
                    for (int x : dp.get(j)) cur.add(x | arr[i]);
