def getMaxThroughput(throughput: List[int], scaling_cost: List[int], budget: int) -> int:
    n = len(throughput)
    def feasible(T: int) -> bool:
        total = 0
        for i in range(n):
            base = i + 1
            # 需 throughput[i] * (base + x) >= T → x >= T/throughput[i] - base
            need = (T + throughput[i] - 1) // throughput[i] - base
            if need < 0:
                need = 0
            total += need * scaling_cost[i]
            if total > budget:
                return False
        return True
    lo, hi = 1, max(throughput) * (n + budget + 1)
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best

class Solution {
    long getMaxThroughput(int[] throughput, int[] scaling_cost, int budget) {
        int n = throughput.length;
        long maxTp = 0;
        for (int t : throughput) maxTp = Math.max(maxTp, t);
        long lo = 1, hi = maxTp * (n + (long) budget + 1), best = 0;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            if (feasible(throughput, scaling_cost, budget, mid)) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return best;
    }
    boolean feasible(int[] tp, int[] sc, int budget, long T) {
        long total = 0;
        for (int i = 0; i < tp.length; i++) {
            long base = i + 1;
            long need = (T + tp[i] - 1) / tp[i] - base;
            if (need < 0) need = 0;
            total += need * sc[i];
            if (total > budget) return false;
        }
        return true;
    }
}

