def citadelGetMinOperations(executionTime: List[int], x: int, y: int) -> int:
    diff = x - y
    lo, hi = 1, max(executionTime)
    while lo < hi:
        mid = (lo + hi) // 2
        total = 0
        for t in executionTime:
            need = t - y * mid
            if need > 0:
                total += (need + diff - 1) // diff
            if total > mid:
                break
        if total <= mid:
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int citadelGetMinOperations(int[] executionTime, int x, int y) {
        long lo = 1, hi = 0, diff = x - y;
        for (int t : executionTime) hi = Math.max(hi, t);
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            long total = 0;
            boolean over = false;
            for (int t : executionTime) {
                long need = t - (long) y * mid;
                if (need > 0) total += (need + diff - 1) / diff;
                if (total > mid) { over = true; break; }
            }
            if (!over) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
}

