        for (int t : executionTime) hi = max(hi, (long long) t);
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            long long total = 0;
            bool over = false;
            for (int t : executionTime) {
                long long need = t - (long long) y * mid;
                if (need > 0) total += (need + diff - 1) / diff;
                if (total > mid) { over = true; break; }
            }
            if (!over) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
};

