def getRecommendedFriends(n: int, friendships: List[List[int]]) -> List[int]:
    adj = [set() for _ in range(n)]
    for u, v in friendships:
        adj[u].add(v)
        adj[v].add(u)
    res = []
    for y in range(n):
        cnt = {}
        for f in adj[y]:
            for x in adj[f]:
                if x == y or x in adj[y]:
                    continue
                cnt[x] = cnt.get(x, 0) + 1
        if not cnt:
            res.append(-1)
        else:
            best_x, best_c = -1, -1
            for x, c in cnt.items():
                if c > best_c or (c == best_c and (best_x == -1 or x < best_x)):
                    best_x, best_c = x, c
            res.append(best_x)
    return res

