class Solution {
    int[] getRecommendedFriends(int n, int[][] friendships) {
        List<Set<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new HashSet<>());
        for (int[] e : friendships) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] res = new int[n];
        for (int y = 0; y < n; y++) {
            Map<Integer, Integer> cnt = new HashMap<>();
            for (int f : adj.get(y)) {
                for (int x : adj.get(f)) {
                    if (x == y || adj.get(y).contains(x)) continue;
                    cnt.merge(x, 1, Integer::sum);
                }
            }
            if (cnt.isEmpty()) {
                res[y] = -1;
            } else {
                int bestX = -1, bestC = -1;
                for (var e : cnt.entrySet()) {
                    int x = e.getKey(), c = e.getValue();
                    if (c > bestC || (c == bestC && (bestX == -1 || x < bestX))) {
                        bestX = x; bestC = c;
                    }
                }
                res[y] = bestX;
            }
        }
        return res;
    }
}

