def maximizeLotteryId(lotteryID: str, winnerID: str, k: int) -> int:
    n, m = len(lotteryID), len(winnerID)
    def dist(a: str, b: str) -> int:
        d = abs(ord(a) - ord(b))
        return min(d, 26 - d)
    # dp[i][j][r] = 处理 lotteryID 前 i 字符、winnerID 前 j 字符、用了 r 次操作的 LCS 最长
    dp = [[[0] * (k + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    for i in range(n):
        for j in range(m):
            for r in range(k + 1):
                cur = dp[i][j][r]
                if dp[i + 1][j][r] < cur:
                    dp[i + 1][j][r] = cur
                if dp[i][j + 1][r] < cur:
                    dp[i][j + 1][r] = cur
                d = dist(lotteryID[i], winnerID[j])
                if d <= r and dp[i + 1][j + 1][r - d] < cur + 1:
                    dp[i + 1][j + 1][r - d] = cur + 1
        # 推进结尾行
        for r in range(k + 1):
            if dp[i + 1][m][r] < dp[i][m][r]:
                dp[i + 1][m][r] = dp[i][m][r]
    best = 0
    for r in range(k + 1):
        if dp[n][m][r] > best:
            best = dp[n][m][r]
    return best

class Solution {
    int dist(char a, char b) {
        int d = Math.abs(a - b);
        return Math.min(d, 26 - d);
    }
    int maximizeLotteryId(String lotteryID, String winnerID, int k) {
        int n = lotteryID.length(), m = winnerID.length();
        int[][][] dp = new int[n + 1][m + 1][k + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int r = 0; r <= k; r++) {
                    int cur = dp[i][j][r];
                    if (dp[i + 1][j][r] < cur) dp[i + 1][j][r] = cur;
                    if (dp[i][j + 1][r] < cur) dp[i][j + 1][r] = cur;
                    int d = dist(lotteryID.charAt(i), winnerID.charAt(j));
                    if (d <= r && dp[i + 1][j + 1][r - d] < cur + 1) {
                        dp[i + 1][j + 1][r - d] = cur + 1;
                    }
                }
            }
            for (int r = 0; r <= k; r++) {
                if (dp[i + 1][m][r] < dp[i][m][r]) dp[i + 1][m][r] = dp[i][m][r];
            }
        }
        int best = 0;
        for (int r = 0; r <= k; r++) best = Math.max(best, dp[n][m][r]);
        return best;
    }
}

