from collections import deque

def findMinimumTargetPath(levelOrder: List[str], targetSum: int) -> List[int]:
    if not levelOrder or levelOrder[0] == "null":
        return []
    # 节点存为 (value, left_idx, right_idx)
    n = len(levelOrder)
    vals = [int(x) if x != "null" else None for x in levelOrder]
    left = [-1] * n
    right = [-1] * n
    q = deque([0])
    i = 1
    while q and i < n:
        u = q.popleft()
        if u == -1 or vals[u] is None:
            continue
        if i < n:
            if vals[i] is not None:
                left[u] = i
                q.append(i)
            i += 1
        if i < n:
            if vals[i] is not None:
                right[u] = i
                q.append(i)
            i += 1
    best = None
    path = []
    def dfs(u: int, cur_sum: int):
        nonlocal best
        if u == -1 or vals[u] is None:
            return
        path.append(vals[u])
        s = cur_sum + vals[u]
        if left[u] == -1 and right[u] == -1:
            if s == targetSum:
                cand = list(path)
                if best is None or (len(cand), cand) < (len(best), best):
                    best = cand
        else:
            dfs(left[u], s)
            dfs(right[u], s)
        path.pop()
    dfs(0, 0)
    return best if best else []

import java.util.*;

class Solution {
    int[] vals, left, right;
    int target;
    List<Integer> best;
    List<Integer> path;
    int[] findMinimumTargetPath(String[] levelOrder, int targetSum) {
        int n = levelOrder.length;
        vals = new int[n];
        boolean[] isNull = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (levelOrder[i].equals("null")) isNull[i] = true;
            else vals[i] = Integer.parseInt(levelOrder[i]);
        }
        left = new int[n]; right = new int[n];
        Arrays.fill(left, -1); Arrays.fill(right, -1);
        Deque<Integer> q = new ArrayDeque<>();
        if (isNull[0]) return new int[0];
        q.offer(0);
        int idx = 1;
        while (!q.isEmpty() && idx < n) {
            int u = q.poll();
            if (idx < n) {
                if (!isNull[idx]) { left[u] = idx; q.offer(idx); }
                idx++;
            }
            if (idx < n) {
                if (!isNull[idx]) { right[u] = idx; q.offer(idx); }
                idx++;
            }
        }
        target = targetSum;
        path = new ArrayList<>();
        best = null;
        dfs(0, 0, isNull);
        if (best == null) return new int[0];
        int[] out = new int[best.size()];
        for (int i = 0; i < best.size(); i++) out[i] = best.get(i);
        return out;
    }
    void dfs(int u, int sum, boolean[] isNull) {
        if (u == -1 || isNull[u]) return;
        path.add(vals[u]);
        int s = sum + vals[u];
        if (left[u] == -1 && right[u] == -1) {
            if (s == target) {
                List<Integer> cand = new ArrayList<>(path);
                if (best == null || cand.size() < best.size() || (cand.size() == best.size() && lessLex(cand, best))) {
                    best = cand;
                }
            }
        } else {
            dfs(left[u], s, isNull);
            dfs(right[u], s, isNull);
        }
        path.remove(path.size() - 1);
    }
    boolean lessLex(List<Integer> a, List<Integer> b) {
        for (int i = 0; i < a.size(); i++) {
            if (!a.get(i).equals(b.get(i))) return a.get(i) < b.get(i);
        }
        return false;
    }
}

class Solution {
public:
    vector<int> vals, leftArr, rightArr;
    vector<bool> isNull;
    int target;
    vector<int> best, path;
    void dfs(int u, int sum) {
        if (u == -1 || isNull[u]) return;
        path.push_back(vals[u]);
        int s = sum + vals[u];
        if (leftArr[u] == -1 && rightArr[u] == -1) {
            if (s == target) {
                if (best.empty() || path.size() < best.size() || (path.size() == best.size() && path < best)) {
                    best = path;
                }
            }
        } else {
            dfs(leftArr[u], s);
            dfs(rightArr[u], s);
        }
        path.pop_back();
    }
    vector<int> findMinimumTargetPath(vector<string>& levelOrder, int targetSum) {
        int n = levelOrder.size();
        vals.assign(n, 0);
        isNull.assign(n, false);
        for (int i = 0; i < n; i++) {
            if (levelOrder[i] == "null") isNull[i] = true;
            else vals[i] = stoi(levelOrder[i]);
        }
        leftArr.assign(n, -1);
        rightArr.assign(n, -1);
        if (n == 0 || isNull[0]) return {};
        queue<int> q;
        q.push(0);
        int idx = 1;
        while (!q.empty() && idx < n) {
            int u = q.front(); q.pop();
            if (idx < n) {
                if (!isNull[idx]) { leftArr[u] = idx; q.push(idx); }
                idx++;
            }
            if (idx < n) {
                if (!isNull[idx]) { rightArr[u] = idx; q.push(idx); }
                idx++;
            }
        }
        target = targetSum;
        best.clear();
        path.clear();
        dfs(0, 0);
        return best;
    }
};

class Solution {
    int countPalindromicSubstrings(String s) {
        int n = s.length(), ans = 0;
        for (int c = 0; c < n; c++) {
            int l = c, r = c;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) { ans++; l--; r++; }
            l = c; r = c + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) { ans++; l--; r++; }
        }
        return ans;
    }
}

