def priceCheck(products: List[str], productPrices: List[float],
               productSold: List[str], soldPrice: List[float]) -> int:
    price = dict(zip(products, productPrices))
    errors = 0
    for name, sp in zip(productSold, soldPrice):
        if name in price and abs(price[name] - sp) > 1e-9:
            errors += 1
