def nums_that_can_be_divided_by_n(N: int, arr: List[int]) -> int:
    mod_cnt = Counter(x % N for x in arr)
    total = 0
    keys = list(mod_cnt.keys())
    for r in mod_cnt:
        if r == 0:
            c = mod_cnt[r]
            total += c * (c - 1) // 2
        elif 2 * r == N:
            c = mod_cnt[r]
            total += c * (c - 1) // 2
        elif r < N - r:
            total += mod_cnt[r] * mod_cnt.get(N - r, 0)
    return total

