class Solution {
    String[] solvePiecewiseLinearInterpolation(String input) {
        String[] lines = input.strip().split("\n");
        String[] hdr = lines[0].split(" ");
        int n = Integer.parseInt(hdr[0]), q = Integer.parseInt(hdr[1]);
        double[][] pts = new double[n][2];
        for (int i = 0; i < n; i++) {
            String[] p = lines[1 + i].split(" ");
            pts[i][0] = Double.parseDouble(p[0]);
            pts[i][1] = Double.parseDouble(p[1]);
        }
        Arrays.sort(pts, (a, b) -> Double.compare(a[0], b[0]));
        double[] xs = new double[n], ys = new double[n];
        for (int i = 0; i < n; i++) { xs[i] = pts[i][0]; ys[i] = pts[i][1]; }
        String[] out = new String[q];
        for (int j = 0; j < q; j++) {
            double xq = Double.parseDouble(lines[1 + n + j]);
            double xa, ya, xb, yb;
            if (xq <= xs[0]) { xa = xs[0]; ya = ys[0]; xb = xs[1]; yb = ys[1]; }
            else if (xq >= xs[n - 1]) { xa = xs[n - 2]; ya = ys[n - 2]; xb = xs[n - 1]; yb = ys[n - 1]; }
            else {
                int lo = 0, hi = n;
                while (lo < hi) { int mid = (lo + hi) >>> 1; if (xs[mid] < xq) lo = mid + 1; else hi = mid; }
                if (xs[lo] == xq) { out[j] = String.format("%.6f", ys[lo]); continue; }
                xa = xs[lo - 1]; ya = ys[lo - 1]; xb = xs[lo]; yb = ys[lo];
            }
            double y = ya + (yb - ya) * (xq - xa) / (xb - xa);
            out[j] = String.format("%.6f", y);
        }
        return out;
    }
}

class Solution {
public:
    vector<string> solvePiecewiseLinearInterpolation(string input) {
        vector<string> lines;
        string cur;
        for (char c : input) { if (c == '\n') { lines.push_back(cur); cur.clear(); } else cur += c; }
        if (!cur.empty()) lines.push_back(cur);
        int n, q;
        sscanf(lines[0].c_str(), "%d %d", &n, &q);
        vector<pair<double, double>> pts(n);
        for (int i = 0; i < n; i++) sscanf(lines[1 + i].c_str(), "%lf %lf", &pts[i].first, &pts[i].second);
        sort(pts.begin(), pts.end());
        vector<double> xs(n), ys(n);
        for (int i = 0; i < n; i++) { xs[i] = pts[i].first; ys[i] = pts[i].second; }
        vector<string> out;
        for (int j = 0; j < q; j++) {
            double xq = stod(lines[1 + n + j]);
            double xa, ya, xb, yb;
            if (xq <= xs[0]) { xa = xs[0]; ya = ys[0]; xb = xs[1]; yb = ys[1]; }
            else if (xq >= xs[n - 1]) { xa = xs[n - 2]; ya = ys[n - 2]; xb = xs[n - 1]; yb = ys[n - 1]; }
            else {
                int lo = lower_bound(xs.begin(), xs.end(), xq) - xs.begin();
                if (xs[lo] == xq) { char buf[64]; snprintf(buf, sizeof(buf), "%.6f", ys[lo]); out.push_back(buf); continue; }
                xa = xs[lo - 1]; ya = ys[lo - 1]; xb = xs[lo]; yb = ys[lo];
            }
            double y = ya + (yb - ya) * (xq - xa) / (xb - xa);
            char buf[64]; snprintf(buf, sizeof(buf), "%.6f", y);
            out.push_back(buf);
        }
        return out;
    }
};

from typing import List
import sys

def drainage_partition(parent: List[int], input_: List[int]) -> int:
    sys.setrecursionlimit(200000)
    n = len(parent)
    children = [[] for _ in range(n)]
    for i, p in enumerate(parent):
        if p != -1:
            children[p].append(i)
    sub = [0] * n
    order = []
    stack = [0]
    visited = [False] * n
    while stack:
        u = stack[-1]
        if not visited[u]:
            visited[u] = True
            for c in children[u]:
                stack.append(c)
        else:
            stack.pop()
            order.append(u)
    for u in order:
        sub[u] = input_[u] + sum(sub[c] for c in children[u])
    total = sub[0]
    best = float("inf")
    for i in range(1, n):
        diff = abs(total - 2 * sub[i])
        if diff < best:
            best = diff
    return best

import java.util.*;

class Solution {
    int drainagePartition(int[] parent, int[] input) {
        int n = parent.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 0; i < n; i++) if (parent[i] != -1) children.get(parent[i]).add(i);
        long[] sub = new long[n];
        int[] order = new int[n], idx = new int[]{0};
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int u = stack.peek();
            if (!visited[u]) {
                visited[u] = true;
                for (int c : children.get(u)) stack.push(c);
            } else {
                stack.pop();
                order[idx[0]++] = u;
            }
        }
        for (int u : order) {
            long s = input[u];
            for (int c : children.get(u)) s += sub[c];
            sub[u] = s;
        }
        long total = sub[0], best = Long.MAX_VALUE;
        for (int i = 1; i < n; i++) {
            long diff = Math.abs(total - 2 * sub[i]);
            if (diff < best) best = diff;
        }
        return (int) best;
    }
}

