def count_triplets(d, t):
    a = sorted(d)
    n = len(a)
    cnt = 0
    for c in range(2, n):
        limit = min(a[c], t - a[c])
        l, r = 0, c - 1
        while l < r:
            if a[l] + a[r] < limit:
                cnt += r - l
                l += 1
