class Solution {
    static long countTriplets(int[] d, int t) {
        int[] a = d.clone();
        Arrays.sort(a);
        int n = a.length;
        long cnt = 0;
        for (int c = 2; c < n; c++) {
            int limit = Math.min(a[c], t - a[c]);
            int l = 0, r = c - 1;
            while (l < r) {
                if (a[l] + a[r] < limit) { cnt += r - l; l++; }
                else r--;
            }
        }
        return cnt;
    }
}

