def optimal_priority(priority):
    odd = [p for p in priority if p % 2 == 1]
    even = [p for p in priority if p % 2 == 0]
    i = j = 0
    out = []
    while i < len(odd) or j < len(even):
        if i == len(odd):
            out.append(even[j]); j += 1
        elif j == len(even):
            out.append(odd[i]); i += 1
        elif odd[i] <= even[j]:
            out.append(odd[i]); i += 1
        else:
            out.append(even[j]); j += 1
    return out

