class ListNode:
    def __init__(self, val=0, next=None):
        self.val, self.next = val, next

def remove_even(head):
    dummy = ListNode(0, head)
    cur = dummy
    while cur.next:
        if cur.next.val % 2 == 0:
            cur.next = cur.next.next
        else:
            cur = cur.next
    return dummy.next

class Solution {
