    static ListNode removeEven(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode cur = dummy;
        while (cur.next != null) {
            if (cur.next.val % 2 == 0) cur.next = cur.next.next;
            else cur = cur.next;
        }
        return dummy.next;
    }
}

