class Solution {
    static List<String> predictionDiff(String p1, String p2) {
        Map<String, String> m1 = parse(p1), m2 = parse(p2);
        Set<String> keys = new TreeSet<>();
        keys.addAll(m1.keySet());
        keys.addAll(m2.keySet());
        List<String> out = new ArrayList<>();
        for (String k : keys)
            if (!Objects.equals(m1.get(k), m2.get(k))) out.add(k);
