map<string, string> parseJson(const string& s) {
 map<string, string> m;
 string body = s;
 while (!body.empty() && (body.front() == '{' || isspace(body.front()))) body.erase(body.begin());
 while (!body.empty() && (body.back() == '}' || isspace(body.back()))) body.pop_back();
 if (body.empty()) return m;
 stringstream ss(body);
 string entry;
 while (getline(ss, entry, ',')) {
 auto colon = entry.find(':');
 string k = entry.substr(0, colon), v = entry.substr(colon + 1);
 auto strip = [](string& t) {
 while (!t.empty() && (isspace(t.front()) || t.front() == '"')) t.erase(t.begin());
 while (!t.empty() && (isspace(t.back()) || t.back() == '"')) t.pop_back();
 };
 strip(k); strip(v);
 m[k] = v;
 }
 return m;
}

vector<string> predictionDiff(const string& p1, const string& p2) {
 auto m1 = parseJson(p1), m2 = parseJson(p2);
 set<string> keys;
 for (auto& [k, _] : m1) keys.insert(k);
 for (auto& [k, _] : m2) keys.insert(k);
 vector<string> out;
 for (auto& k : keys)
 if (m1.count(k) + m2.count(k) == 1 || m1[k] != m2[k]) out.push_back(k);
 return out;
}

