import math

def circles(circlePairs: List[str]) -> List[str]:
    out = []
    for line in circlePairs:
        v = list(map(int, line.split()))
        xa, ya, ra, xb, yb, rb = v
        d2 = (xa - xb) ** 2 + (ya - yb) ** 2
        d = math.isqrt(d2)
        if d2 == 0:
            out.append("Concentric")
        elif d2 == (ra + rb) ** 2 or d2 == (ra - rb) ** 2:
            out.append("Touching")
        elif (ra - rb) ** 2 < d2 < (ra + rb) ** 2:
            out.append("Intersecting")
        elif d2 > (ra + rb) ** 2:
            out.append("Disjoint-Outside")
        else:
            out.append("Disjoint-Inside")
    return out

class Solution {
    String[] circles(String[] circlePairs) {
        String[] out = new String[circlePairs.length];
        for (int i = 0; i < circlePairs.length; i++) {
            String[] p = circlePairs[i].split(" ");
            long xa = Long.parseLong(p[0]), ya = Long.parseLong(p[1]), ra = Long.parseLong(p[2]);
            long xb = Long.parseLong(p[3]), yb = Long.parseLong(p[4]), rb = Long.parseLong(p[5]);
            long d2 = (xa - xb) * (xa - xb) + (ya - yb) * (ya - yb);
            long sum2 = (ra + rb) * (ra + rb), diff2 = (ra - rb) * (ra - rb);
            if (d2 == 0) out[i] = "Concentric";
            else if (d2 == sum2 || d2 == diff2) out[i] = "Touching";
            else if (d2 > diff2 && d2 < sum2) out[i] = "Intersecting";
            else if (d2 > sum2) out[i] = "Disjoint-Outside";
            else out[i] = "Disjoint-Inside";
        }
        return out;
    }
}

