};

class Solution {
    long countDescendingSubarrays(int[] nums) {
        int n = nums.length;
        long ans = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && nums[j + 1] == nums[j] - 1) j++;
            long L = j - i + 1;
            ans += L * (L - 1) / 2;
            i = j + 1;
        }
        return ans;
    }
}

