        int cnt = 0;
        for (long px = 1; px <= high; px *= 3) {
            for (long py = px; py <= high; py *= 5) {
                if (py >= low) cnt++;
                if (py > high / 5) break;
            }
            if (px > high / 3) break;
        }
        return cnt;
    }
}

