import java.math.BigInteger;

class Solution {
    int countTeams(int[] skills, int minPlayers, int minLevel, int maxLevel) {
        int m = 0;
        for (int s : skills) if (s >= minLevel && s <= maxLevel) m++;
        BigInteger ans = BigInteger.ZERO;
        BigInteger[] fact = new BigInteger[m + 1];
        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= m; i++) fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i));
        for (int k = minPlayers; k <= m; k++) {
            ans = ans.add(fact[m].divide(fact[k]).divide(fact[m - k]));
        }
        return ans.intValue();
    }
}

class Solution {
public:
    int countTeams(vector<int>& skills, int minPlayers, int minLevel, int maxLevel) {
        int m = 0;
        for (int s : skills) if (s >= minLevel && s <= maxLevel) m++;
        // 计算 C(m, k) 累加：用 Pascal 三角
        vector<vector<long long>> C(m + 1, vector<long long>(m + 1, 0));
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
        long long ans = 0;
        for (int k = minPlayers; k <= m; k++) ans += C[m][k];
        return (int) ans;
    }
};

