import java.util.*;

class Solution {
    int equalizeTeamSize(int[] teamSize, int k) {
        Map<Integer, Integer> cnt = new TreeMap<>();
        for (int x : teamSize) cnt.merge(x, 1, Integer::sum);
        int total = teamSize.length;
        int prefix = 0;  // ≤ s 的累计（包含 s）
        int best = 0;
        for (var e : cnt.entrySet()) {
            int s = e.getKey(), c = e.getValue();
            prefix += c;
            int larger = total - prefix;  // > s
            best = Math.max(best, c + Math.min(k, larger));
        }
        return best;
    }
}

class Solution {
public:
    int equalizeTeamSize(vector<int>& teamSize, int k) {
        map<int, int> cnt;
        for (int x : teamSize) cnt[x]++;
        int total = teamSize.size();
        int prefix = 0;
        int best = 0;
        for (auto& [s, c] : cnt) {
            prefix += c;
            int larger = total - prefix;
            best = max(best, c + min(k, larger));
        }
        return best;
    }
};

def findArrangements(P: int, C: int, N: int) -> int:
    MOD = 10**9 + 7
    # dp[p][c][last][run] = 已放 p 个 P 和 c 个 C，上一个是 last（0=P, 1=C），连续 run 个该类
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def solve(p, c, last, run):
        if p == 0 and c == 0:
            return 1
        total = 0
        # 放 P
        if p > 0:
            new_run = run + 1 if last == 0 else 1
            if new_run <= N:
                total = (total + solve(p - 1, c, 0, new_run)) % MOD
        if c > 0:
            new_run = run + 1 if last == 1 else 1
            if new_run <= N:
                total = (total + solve(p, c - 1, 1, new_run)) % MOD
        return total
    return solve(P, C, -1, 0)

class Solution {
    int MOD = 1_000_000_007;
    Long[][][][] memo;
    int N;
    int findArrangements(int P, int C, int N) {
        this.N = N;
        memo = new Long[P + 1][C + 1][3][N + 2];
        return (int) solve(P, C, 2, 0);  // last=2 表示初始
    }
    long solve(int p, int c, int last, int run) {
        if (p == 0 && c == 0) return 1;
        if (memo[p][c][last][run] != null) return memo[p][c][last][run];
        long total = 0;
        if (p > 0) {
            int nr = (last == 0) ? run + 1 : 1;
            if (nr <= N) total = (total + solve(p - 1, c, 0, nr)) % MOD;
        }
        if (c > 0) {
            int nr = (last == 1) ? run + 1 : 1;
            if (nr <= N) total = (total + solve(p, c - 1, 1, nr)) % MOD;
        }
        return memo[p][c][last][run] = total;
    }
}

class Solution {
public:
    int MOD = 1'000'000'007;
    vector<vector<vector<vector<long long>>>> memo;
    int N;
    long long solve(int p, int c, int last, int run) {
        if (p == 0 && c == 0) return 1;
        if (memo[p][c][last][run] != -1) return memo[p][c][last][run];
        long long total = 0;
        if (p > 0) {
            int nr = (last == 0) ? run + 1 : 1;
            if (nr <= N) total = (total + solve(p - 1, c, 0, nr)) % MOD;
        }
        if (c > 0) {
            int nr = (last == 1) ? run + 1 : 1;
            if (nr <= N) total = (total + solve(p, c - 1, 1, nr)) % MOD;
        }
        return memo[p][c][last][run] = total;
    }
    int findArrangements(int P, int C, int N) {
        this->N = N;
        memo.assign(P + 1, vector<vector<vector<long long>>>(C + 1, vector<vector<long long>>(3, vector<long long>(N + 2, -1))));
        return (int) solve(P, C, 2, 0);
    }
};

from typing import List

def findLengthOfLongestBitonicSubarray(arr: List[int]) -> int:
    n = len(arr)
    inc = [1] * n
    for i in range(1, n):
        if arr[i] >= arr[i - 1]:
            inc[i] = inc[i - 1] + 1
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        if arr[i] >= arr[i + 1]:
            dec[i] = dec[i + 1] + 1
    return max(inc[i] + dec[i] - 1 for i in range(n))

class Solution {
    int findLengthOfLongestBitonicSubarray(int[] arr) {
        int n = arr.length;
        int[] inc = new int[n], dec = new int[n];
        Arrays.fill(inc, 1);
        Arrays.fill(dec, 1);
        for (int i = 1; i < n; i++) if (arr[i] >= arr[i - 1]) inc[i] = inc[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (arr[i] >= arr[i + 1]) dec[i] = dec[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, inc[i] + dec[i] - 1);
        return best;
    }
}

