        for (int i = n - 2; i >= 0; i--) if (arr[i] >= arr[i + 1]) dec[i] = dec[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = max(best, inc[i] + dec[i] - 1);
