class Solution {
    int findMaximumEvenSum(int[] val) {
        long total = 0;
        for (int v : val) if (v > 0) total += v;
        if (total % 2 == 0) return (int) total;
        int bestLoss = Integer.MAX_VALUE;
        for (int v : val) {
            if (v > 0 && Math.abs(v) % 2 != 0) bestLoss = Math.min(bestLoss, v);
            if (v < 0 && Math.abs(v) % 2 != 0) bestLoss = Math.min(bestLoss, -v);
        }
        return (int) (total - bestLoss);
    }
}

