import java.util.*;

class Solution {
    long findMissingInteger(int[] arr, long k) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int x : arr) set.add(x);
        Integer[] a = set.toArray(new Integer[0]);
        long lo = 1, hi = (long) 1e18;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            int idx = upperBound(a, mid);
            long missing = mid - idx;
            if (missing >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
    int upperBound(Integer[] a, long target) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

class Solution {
public:
    long long findMissingInteger(vector<int>& arr, long long k) {
        set<int> s(arr.begin(), arr.end());
        vector<int> a(s.begin(), s.end());
        long long lo = 1, hi = (long long) 1e18;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            int idx = upper_bound(a.begin(), a.end(), (int) min((long long) INT_MAX, mid)) - a.begin();
            long long missing = mid - idx;
            if (missing >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

