def getFinalString(s: str) -> str:
    stack = []
    for c in s:
        stack.append(c)
        if len(stack) >= 3 and stack[-3] == 'A' and stack[-2] == 'W' and stack[-1] == 'S':
            stack.pop(); stack.pop(); stack.pop()
    return ''.join(stack) if stack else "-1"

class Solution {
    String getFinalString(String s) {
        StringBuilder st = new StringBuilder();
        for (char c : s.toCharArray()) {
            st.append(c);
            int n = st.length();
            if (n >= 3 && st.charAt(n - 3) == 'A' && st.charAt(n - 2) == 'W' && st.charAt(n - 1) == 'S') {
                st.delete(n - 3, n);
            }
        }
        return st.length() == 0 ? "-1" : st.toString();
    }
}

class Solution {
public:
    string getFinalString(string s) {
        string st;
        for (char c : s) {
            st += c;
            int n = st.size();
            if (n >= 3 && st[n - 3] == 'A' && st[n - 2] == 'W' && st[n - 1] == 'S') {
                st.erase(n - 3, 3);
            }
        }
        return st.empty() ? "-1" : st;
    }
};

