def getLatestKRequests(requests: List[str], k: int) -> List[str]:
    seen = set()
    out = []
    for r in reversed(requests):
        if r not in seen:
            seen.add(r)
            out.append(r)
            if len(out) == k:
                break
    return out

import java.util.*;

class Solution {
    String[] getLatestKRequests(String[] requests, int k) {
        Set<String> seen = new HashSet<>();
        List<String> out = new ArrayList<>();
        for (int i = requests.length - 1; i >= 0; i--) {
            if (!seen.contains(requests[i])) {
                seen.add(requests[i]);
                out.add(requests[i]);
                if (out.size() == k) break;
            }
        }
        return out.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> getLatestKRequests(vector<string>& requests, int k) {
        unordered_set<string> seen;
        vector<string> out;
        for (int i = requests.size() - 1; i >= 0; i--) {
            if (!seen.count(requests[i])) {
                seen.insert(requests[i]);
                out.push_back(requests[i]);
                if ((int) out.size() == k) break;
            }
        }
        return out;
    }
};

