def getMaxOccurrences(components: str, minLength: int, maxLength: int, maxUnique: int) -> int:
    cnt = Counter()
    for i in range(len(components) - minLength + 1):
        sub = components[i:i + minLength]
        if len(set(sub)) <= maxUnique:
            cnt[sub] += 1
    return max(cnt.values()) if cnt else 0

import java.util.*;

class Solution {
    int getMaxOccurrences(String components, int minLength, int maxLength, int maxUnique) {
        Map<String, Integer> cnt = new HashMap<>();
        for (int i = 0; i + minLength <= components.length(); i++) {
            String sub = components.substring(i, i + minLength);
            Set<Character> uniq = new HashSet<>();
            for (char c : sub.toCharArray()) uniq.add(c);
            if (uniq.size() <= maxUnique) cnt.merge(sub, 1, Integer::sum);
        }
        int best = 0;
        for (int v : cnt.values()) best = Math.max(best, v);
        return best;
    }
}

class Solution {
public:
    int getMaxOccurrences(string components, int minLength, int maxLength, int maxUnique) {
        unordered_map<string, int> cnt;
        for (int i = 0; i + minLength <= (int) components.size(); i++) {
            string sub = components.substr(i, minLength);
            set<char> uniq(sub.begin(), sub.end());
            if ((int) uniq.size() <= maxUnique) cnt[sub]++;
        }
        int best = 0;
        for (auto& [k, v] : cnt) best = max(best, v);
        return best;
    }
};

