class Solution {
    int getMaxTrafficTime(int[] start, int[] end) {
        List<int[]> evs = new ArrayList<>();
        for (int i = 0; i < start.length; i++) {
            evs.add(new int[]{start[i], 1});
            evs.add(new int[]{end[i] + 1, -1});
        }
        evs.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int cur = 0, best = 0, bestT = 0;
        int i = 0;
        while (i < evs.size()) {
            int t = evs.get(i)[0];
            while (i < evs.size() && evs.get(i)[0] == t) {
                cur += evs.get(i)[1];
                i++;
            }
            if (cur > best) { best = cur; bestT = t; }
        }
        return bestT;
    }
}

