class Solution {
    long getMaximumAmount(int[] quantity, int m) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int q : quantity) heap.offer(q);
        long total = 0;
        for (int k = 0; k < m; k++) {
            int q = heap.poll();
            total += q;
            if (q > 1) heap.offer(q - 1);
        }
        return total;
    }
}

class Solution {
public:
    long long getMaximumAmount(vector<int>& quantity, int m) {
        priority_queue<int> heap(quantity.begin(), quantity.end());
        long long total = 0;
        for (int k = 0; k < m; k++) {
            int q = heap.top(); heap.pop();
            total += q;
            if (q > 1) heap.push(q - 1);
        }
        return total;
    }
};

