def getMinOperations(s: str, m: int, k: int) -> int:
    n = len(s)
    ops = 0
    i = 0
    while i < n:
        if s[i] == '0':
            j = i
            while j < n and s[j] == '0':
                j += 1
            L = j - i
            if L >= m:
                ops += (L - m + 1 + k - 1) // k
            i = j
        else:
            i += 1
    return ops

