from typing import List

def getMinTime(cache_size: int, cache_time: int, server_time: int, urls: List[str]) -> List[int]:
    cache = OrderedDict()
    out = []
    for url in urls:
        if url in cache:
            cache.move_to_end(url)
            out.append(cache_time)
        else:
            cache[url] = True
            if len(cache) > cache_size:
                cache.popitem(last=False)
            out.append(server_time)
    return out

import java.util.*;

class Solution {
    int[] getMinTime(int cache_size, int cache_time, int server_time, String[] urls) {
        LinkedHashMap<String, Boolean> cache = new LinkedHashMap<>();
        int[] out = new int[urls.length];
        for (int i = 0; i < urls.length; i++) {
            if (cache.containsKey(urls[i])) {
                cache.remove(urls[i]);
                cache.put(urls[i], true);
                out[i] = cache_time;
            } else {
                cache.put(urls[i], true);
                if (cache.size() > cache_size) {
                    Iterator<String> it = cache.keySet().iterator();
                    it.next(); it.remove();
                }
                out[i] = server_time;
            }
        }
        return out;
    }
}

class Solution {
public:
    vector<int> getMinTime(int cache_size, int cache_time, int server_time, vector<string>& urls) {
        list<string> order;
        unordered_map<string, list<string>::iterator> pos;
        vector<int> out;
        for (auto& url : urls) {
            auto it = pos.find(url);
            if (it != pos.end()) {
                order.erase(it->second);
                order.push_front(url);
                pos[url] = order.begin();
                out.push_back(cache_time);
            } else {
                order.push_front(url);
                pos[url] = order.begin();
                if ((int) order.size() > cache_size) {
                    pos.erase(order.back());
                    order.pop_back();
                }
                out.push_back(server_time);
            }
        }
        return out;
    }
};

class Solution {
    long getMinimumCost(int edgeDeviceCost, int inputPeripheralCost, int bundleCost, int x, int y) {
        long b = Math.min(x, y);
        long c1 = b * bundleCost + (x - b) * (long) edgeDeviceCost + (y - b) * (long) inputPeripheralCost;
        long b2 = Math.max(x, y);
        long c2 = b2 * bundleCost;
        long c3 = (long) x * edgeDeviceCost + (long) y * inputPeripheralCost;
        return Math.min(c1, Math.min(c2, c3));
    }
}

class Solution {
public:
    long long getMinimumCost(int edgeDeviceCost, int inputPeripheralCost, int bundleCost, int x, int y) {
        long long b = min(x, y);
        long long c1 = b * bundleCost + (x - b) * (long long) edgeDeviceCost + (y - b) * (long long) inputPeripheralCost;
        long long b2 = max(x, y);
        long long c2 = b2 * bundleCost;
        long long c3 = (long long) x * edgeDeviceCost + (long long) y * inputPeripheralCost;
        return min({c1, c2, c3});
    }
};

