from typing import List

def getMinimumDifference(a: List[str], b: List[str]) -> List[int]:
    out = []
    for sa, sb in zip(a, b):
        if len(sa) != len(sb):
            out.append(-1)
        else:
            ca, cb = Counter(sa), Counter(sb)
            diff = sum(abs(ca[c] - cb[c]) for c in set(ca) | set(cb))
            out.append(diff // 2)
    return out

class Solution {
    int[] getMinimumDifference(String[] a, String[] b) {
        int[] out = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            if (a[i].length() != b[i].length()) { out[i] = -1; continue; }
            int[] ca = new int[26], cb = new int[26];
            for (char c : a[i].toCharArray()) ca[c - 'a']++;
            for (char c : b[i].toCharArray()) cb[c - 'a']++;
            int diff = 0;
            for (int j = 0; j < 26; j++) diff += Math.abs(ca[j] - cb[j]);
            out[i] = diff / 2;
        }
        return out;
    }
}

class Solution {
public:
    vector<int> getMinimumDifference(vector<string>& a, vector<string>& b) {
        vector<int> out;
        for (size_t i = 0; i < a.size(); i++) {
            if (a[i].size() != b[i].size()) { out.push_back(-1); continue; }
            int ca[26] = {0}, cb[26] = {0};
            for (char c : a[i]) ca[c - 'a']++;
            for (char c : b[i]) cb[c - 'a']++;
            int diff = 0;
            for (int j = 0; j < 26; j++) diff += abs(ca[j] - cb[j]);
            out.push_back(diff / 2);
        }
        return out;
    }
};

