    def check(x: int) -> bool:
        # dp: 在 i 位置加 x（chose）或不加（unchose），同时满足非递减
        # prev[0] = 不加 x 时 arr[i] 的值，prev[1] = 加 x 时 arr[i] + x
        # 注意：相邻不能都加（subset 不相邻）
        # 转移：i 处 chose -> 必须 i-1 unchose；unchose 都可以
        INF = float('inf')
        # state: (prev_val, prev_chose)
        # 起点：i = 0
        prev = {(arr[0], False): True, (arr[0] + x, True): True}
        for i in range(1, n):
            new_prev = {}
            for (pv, pc), _ in prev.items():
                # 不加
                if arr[i] >= pv:
                    new_prev[(arr[i], False)] = True
                # 加
                if not pc and arr[i] + x >= pv:
                    new_prev[(arr[i] + x, True)] = True
            if not new_prev:
                return False
            prev = new_prev
        return True
    lo, hi = 0, 2 * 10**9
    if check(0):
        return 0
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo if check(lo) else -1

