from typing import List

def getMinimumMoves(price: List[int], k: int) -> int:
    p = sorted(price)
    n = len(p)
    m = (n - 1) // 2  # 中位数下标（n 奇）
    ops = abs(p[m] - k)
    # 左侧 < k 但 > p[m] 时不影响（≤ k）；右侧 > k 不影响（≥ k）
    # 但若 p[m] < k，p[m+1..n-1] 中 < k 的也需要 ≥ k（否则中位数 != k）
    if p[m] < k:
        for i in range(m + 1, n):
            if p[i] < k:
                ops += k - p[i]
    else:
        for i in range(0, m):
            if p[i] > k:
                ops += p[i] - k
    return ops

class Solution {
    long getMinimumMoves(int[] price, int k) {
        int[] p = price.clone();
        Arrays.sort(p);
        int n = p.length, m = (n - 1) / 2;
        long ops = Math.abs(p[m] - k);
        if (p[m] < k) {
            for (int i = m + 1; i < n; i++) if (p[i] < k) ops += k - p[i];
        } else {
            for (int i = 0; i < m; i++) if (p[i] > k) ops += p[i] - k;
        }
        return ops;
    }
}

