        }
        return ops;
    }
};

def getMinimumOperationCount(s: str) -> int:
    n = len(s)
    arr = list(s)
    ops = 0
    i = 1
    while i < n:
        if arr[i] == arr[i - 1] or abs(ord(arr[i]) - ord(arr[i - 1])) == 1:
            ops += 1
            arr[i] = '?'  # 标记为已改，不影响后续判断
            i += 2  # 跳过下一位（已改的字符可选任意合法字符）
        else:
            i += 1
    return ops

