def getOptimalStringLength(countA: int, countB: int, maxA: int, maxB: int) -> int:
    def try_start(cA, cB, mA, mB):
        # 先放 A 块，再放 B 块，交替
        total = 0
        turn = 0  # 0=A, 1=B
        rem_a, rem_b = cA, cB
        while True:
            if turn == 0:
                if rem_a == 0:
                    if rem_b == 0:
                        break
                    # 不能放 B（因为上次也是 B 块）—— 实际开头若 A 没了，但只要交替了上一次是 B 上一上次是 A，可以放 B
                    # 重新设计：交替放，第一次 A，第二次 B，第三次 A...
                    break
                take = min(rem_a, mA)
                total += take
                rem_a -= take
            else:
                if rem_b == 0:
                    break
                take = min(rem_b, mB)
                total += take
                rem_b -= take
            turn ^= 1
        return total
    return max(try_start(countA, countB, maxA, maxB), try_start(countB, countA, maxB, maxA))

class Solution {
    long tryStart(long cA, long cB, long mA, long mB) {
        long total = 0;
        int turn = 0;
        long ra = cA, rb = cB;
        while (true) {
            if (turn == 0) {
                if (ra == 0) break;
                long take = Math.min(ra, mA);
                total += take;
                ra -= take;
            } else {
                if (rb == 0) break;
                long take = Math.min(rb, mB);
                total += take;
                rb -= take;
            }
            turn ^= 1;
        }
        return total;
    }
    long getOptimalStringLength(int countA, int countB, int maxA, int maxB) {
        return Math.max(tryStart(countA, countB, maxA, maxB), tryStart(countB, countA, maxB, maxA));
    }
}

