};

import java.util.*;

class Solution {
    int getPotentialOfWinner(int[] potential, long k) {
        Deque<Integer> dq = new ArrayDeque<>();
        for (int p : potential) dq.offer(p);
        int mx = 0;
        for (int p : potential) mx = Math.max(mx, p);
        int cur = dq.poll();
        long streak = 0;
        while (true) {
            int opp = dq.poll();
            if (cur > opp) { streak++; dq.offer(opp); }
            else { dq.offer(cur); cur = opp; streak = 1; }
            if (streak >= k || cur == mx) return cur;
        }
    }
}

class Solution {
public:
    int getPotentialOfWinner(vector<int>& potential, long long k) {
        deque<int> dq(potential.begin(), potential.end());
        int mx = *max_element(potential.begin(), potential.end());
        int cur = dq.front(); dq.pop_front();
        long long streak = 0;
        while (true) {
            int opp = dq.front(); dq.pop_front();
            if (cur > opp) { streak++; dq.push_back(opp); }
            else { dq.push_back(cur); cur = opp; streak = 1; }
            if (streak >= k || cur == mx) return cur;
        }
    }
};

