        for (String[] e : cache_entries) store.put(e[1] + "|" + e[0], Integer.parseInt(e[2]));
        int[] out = new int[queries.length];
        for (int i = 0; i < queries.length; i++) out[i] = store.getOrDefault(queries[i][0] + "|" + queries[i][1], 0);
