def getSmallestString(s: str) -> str:
    arr = list(s)
    n = len(arr)
    i = 0
    while i < n and arr[i] == 'a':
        i += 1
    if i == n:
        # 全 a，必须把最后一个变 z
        arr[-1] = 'z'
        return ''.join(arr)
    # 从 i 开始，连续非 'a' 的字符各减 1
    while i < n and arr[i] != 'a':
        arr[i] = chr(ord(arr[i]) - 1)
        i += 1
    return ''.join(arr)

class Solution {
    String getSmallestString(String s) {
        char[] arr = s.toCharArray();
        int n = arr.length, i = 0;
        while (i < n && arr[i] == 'a') i++;
        if (i == n) { arr[n - 1] = 'z'; return new String(arr); }
        while (i < n && arr[i] != 'a') { arr[i] = (char) (arr[i] - 1); i++; }
        return new String(arr);
    }
}

class Solution {
public:
    string getSmallestString(string s) {
        int n = s.size(), i = 0;
        while (i < n && s[i] == 'a') i++;
        if (i == n) { s[n - 1] = 'z'; return s; }
        while (i < n && s[i] != 'a') { s[i]--; i++; }
        return s;
    }
};

import java.util.*;

class Solution {
    int[] getTotalExecutionTime(int n, String[] logs) {
        int[] res = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        int prev = 0;
        for (String log : logs) {
            String[] p = log.split(":");
            int fid = Integer.parseInt(p[0]);
            int ts = Integer.parseInt(p[2]);
            if (p[1].equals("start")) {
                if (!st.isEmpty()) res[st.peek()] += ts - prev;
                st.push(fid);
                prev = ts;
            } else {
                res[st.pop()] += ts - prev + 1;
                prev = ts + 1;
            }
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getTotalExecutionTime(int n, vector<string>& logs) {
        vector<int> res(n, 0);
        stack<int> st;
        int prev = 0;
        for (auto& log : logs) {
            size_t c1 = log.find(':'), c2 = log.find(':', c1 + 1);
            int fid = stoi(log.substr(0, c1));
            string typ = log.substr(c1 + 1, c2 - c1 - 1);
            int ts = stoi(log.substr(c2 + 1));
            if (typ == "start") {
                if (!st.empty()) res[st.top()] += ts - prev;
                st.push(fid);
                prev = ts;
            } else {
                res[st.top()] += ts - prev + 1;
                st.pop();
                prev = ts + 1;
            }
        }
        return res;
    }
};

class Solution {
    int[] isConvertibleData(String[] dataset) {
        int[] out = new int[dataset.length];
        for (int i = 0; i < dataset.length; i++) {
            String s = dataset[i];
            int opens = 0, closes = 0;
            for (char c : s.toCharArray()) { if (c == '(') opens++; else closes++; }
            if (opens != closes) { out[i] = 0; continue; }
            int bal = 0, minBal = 0;
            for (char c : s.toCharArray()) {
                bal += (c == '(') ? 1 : -1;
                minBal = Math.min(minBal, bal);
            }
            out[i] = minBal >= -1 ? 1 : 0;
        }
        return out;
    }
}

