def maxIndex(steps: int, badIndex: int) -> int:
    full = steps * (steps + 1) // 2
    if full != badIndex:
        # 还需检查路径是否经过 badIndex（前缀和）
        cur = 0
        hits = False
        for j in range(1, steps + 1):
            cur += j
            if cur == badIndex:
                hits = True; break
        if not hits:
            return full
    # 跳过某 j：减去 j，取最大不撞的
    for j in range(1, steps + 1):
        candidate = full - j
        # 模拟跳过第 j 步
        cur = 0
        hits = False
        for jj in range(1, steps + 1):
            if jj == j: continue
            cur += jj
            if cur == badIndex:
                hits = True; break
        if not hits and full - j > 0:
            return full - j  # 取最小跳过（最大候选）—— 我们贪心找第一个能避开的
    return 0

class Solution {
    int maxIndex(int steps, int badIndex) {
        int full = steps * (steps + 1) / 2;
        if (full != badIndex) {
            int cur = 0;
            boolean hits = false;
            for (int j = 1; j <= steps; j++) {
                cur += j;
                if (cur == badIndex) { hits = true; break; }
            }
            if (!hits) return full;
        }
        for (int j = 1; j <= steps; j++) {
            int cur = 0;
            boolean hits = false;
            for (int jj = 1; jj <= steps; jj++) {
                if (jj == j) continue;
                cur += jj;
                if (cur == badIndex) { hits = true; break; }
            }
            if (!hits) return full - j;
        }
        return 0;
    }
}

