from typing import List

def maxProfit(cost: List[int], x: int) -> int:
    MOD = 10**9 + 7
    n = len(cost)
    profit = 0
    for i in range(n - 1, -1, -1):
        if cost[i] <= x:
            x -= cost[i]
            profit = (profit + pow(2, i, MOD)) % MOD
    return profit

class Solution {
    int maxProfit(int[] cost, int x) {
        final int MOD = 1_000_000_007;
        long profit = 0;
        long[] pow2 = new long[cost.length + 1];
        pow2[0] = 1;
        for (int i = 1; i <= cost.length; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
        for (int i = cost.length - 1; i >= 0; i--) {
            if (cost[i] <= x) {
                x -= cost[i];
                profit = (profit + pow2[i]) % MOD;
            }
        }
        return (int) profit;
    }
}

