public:
    int maxProfit(vector<int>& cost, int x) {
        const int MOD = 1'000'000'007;
        int n = cost.size();
        vector<long long> pow2(n + 1, 1);
        for (int i = 1; i <= n; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
        long long profit = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (cost[i] <= x) {
                x -= cost[i];
                profit = (profit + pow2[i]) % MOD;
            }
        }
        return (int) profit;
    }
};

