def maxSubjectsNumber(answered: List[int], needed: List[int], q: int) -> int:
    diffs = sorted(max(0, needed[i] - answered[i]) for i in range(len(answered)))
    cnt = 0
    for d in diffs:
        if q >= d:
            q -= d
            cnt += 1
        else:
            break
    return cnt

