def maximizeMinimumDistance(x: List[int], k: int) -> int:
    x.sort()
    def can(d):
        cnt = 1
        last = x[0]
        for v in x[1:]:
            if v - last >= d:
                cnt += 1
                last = v
                if cnt >= k:
                    return True
        return cnt >= k
    lo, hi = 1, x[-1] - x[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

