class Solution {
    int[] x;
    int k;
    boolean can(int d) {
        int cnt = 1, last = x[0];
        for (int i = 1; i < x.length; i++) {
            if (x[i] - last >= d) { cnt++; last = x[i]; if (cnt >= k) return true; }
        }
        return cnt >= k;
    }
    int maximizeMinimumDistance(int[] x, int k) {
        this.x = x.clone();
        Arrays.sort(this.x);
        this.k = k;
        int lo = 1, hi = this.x[this.x.length - 1] - this.x[0];
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (can(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}

