        int l = 0;
        long best = -1;
        for (int r = 0; r < n; r++) {
            freq.merge(arr[r], 1, Integer::sum);
            cur += arr[r];
            while (freq.get(arr[r]) > 1) {
                freq.merge(arr[l], -1, Integer::sum);
                cur -= arr[l];
                l++;
            }
            while (r - l + 1 > k) {
                freq.merge(arr[l], -1, Integer::sum);
                cur -= arr[l];
                l++;
            }
            if (r - l + 1 == k) best = Math.max(best, cur);
        }
        return (int) best;
    }
}

class Solution {
public:
    int maximizeResourceAllocation(vector<int>& arr, int k) {
        int n = arr.size();
        if (k > n) return -1;
        unordered_map<int, int> freq;
        long long cur = 0, best = -1;
        int l = 0;
        for (int r = 0; r < n; r++) {
            freq[arr[r]]++;
            cur += arr[r];
            while (freq[arr[r]] > 1) {
                freq[arr[l]]--;
                cur -= arr[l];
                l++;
            }
            while (r - l + 1 > k) {
                freq[arr[l]]--;
                cur -= arr[l];
                l++;
            }
            if (r - l + 1 == k) best = max(best, cur);
        }
        return (int) best;
    }
};

