def maximumEfficiency(arrivalTime: List[int]) -> float:
    a = sorted(arrivalTime)
    n = len(a)
    best = -float('inf')
    # 等 arrival 累加扩展
    cnt = 1
    l = 0
    for r in range(1, n):
        if a[r] == a[r - 1]:
            cnt += 1
        else:
            # 计算从 a[l] 到 a[r] 的效率
            span = a[r] - a[l]
            eff = (cnt + 1) / span
            if eff > best:
                best = eff
            # 也试更短窗口
            for ll in range(l, r):
                span2 = a[r] - a[ll]
                if span2 > 0:
                    eff2 = (r - ll + 1) / span2
                    if eff2 > best:
                        best = eff2
            cnt += 1
    return best

