class Solution {
    int[] minimumOperationsRequired(int[] price, int[] query) {
        int[] p = price.clone();
        Arrays.sort(p);
        int n = p.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + p[i];
        int[] out = new int[query.length];
        for (int qi = 0; qi < query.length; qi++) {
            int q = query[qi];
            int idx = lowerBound(p, q);
            long left = (long) q * idx - pref[idx];
            long right = (pref[n] - pref[idx]) - (long) q * (n - idx);
            out[qi] = (int) (left + right);
        }
        return out;
    }
    int lowerBound(int[] a, int t) {
        int l = 0, r = a.length;
        while (l < r) { int m = (l + r) >>> 1; if (a[m] < t) l = m + 1; else r = m; }
        return l;
    }
}

