public:
    vector<int> minimumOperationsRequired(vector<int>& price, vector<int>& query) {
        vector<int> p = price;
        sort(p.begin(), p.end());
        int n = p.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + p[i];
        vector<int> out;
        for (int q : query) {
            int idx = lower_bound(p.begin(), p.end(), q) - p.begin();
            long long left = (long long) q * idx - pref[idx];
            long long right = (pref[n] - pref[idx]) - (long long) q * (n - idx);
            out.push_back((int) (left + right));
        }
        return out;
    }
};

