def minimumOperationsToMakeAlternatingBinaryString(s: str) -> int:
    n = len(s)
    diff1 = sum(1 for i in range(n) if s[i] != str(i % 2))      # 0101...
    diff2 = sum(1 for i in range(n) if s[i] != str((i + 1) % 2)) # 1010...
    return min(diff1, diff2)

