def processExecutionTime(start: List[int], end: List[int]) -> int:
    intervals = sorted(zip(start, end))
    total = 0
    cur_s, cur_e = -1, -1
    for s, e in intervals:
        if cur_e == -1 or s > cur_e:
            if cur_e != -1:
                total += cur_e - cur_s + 1
            cur_s, cur_e = s, e
        else:
            cur_e = max(cur_e, e)
    if cur_e != -1:
        total += cur_e - cur_s + 1
    return total

import java.util.*;

class Solution {
    int processExecutionTime(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> start[a] - start[b]);
        long total = 0;
        int curS = -1, curE = -1;
        for (int i : idx) {
            if (curE == -1 || start[i] > curE) {
                if (curE != -1) total += curE - curS + 1;
                curS = start[i]; curE = end[i];
            } else curE = Math.max(curE, end[i]);
        }
        if (curE != -1) total += curE - curS + 1;
        return (int) total;
    }
}

