def processLogs(logs: List[str], threshold: int) -> List[str]:
    cnt = Counter()
    for log in logs:
        s, r, _ = log.split()
        if s == r:
            cnt[s] += 1
        else:
            cnt[s] += 1
            cnt[r] += 1
    return [u for u in sorted(cnt, key=lambda x: int(x)) if cnt[u] >= threshold]

import java.util.*;

class Solution {
    String[] processLogs(String[] logs, int threshold) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String log : logs) {
            String[] p = log.split(" ");
            if (p[0].equals(p[1])) cnt.merge(p[0], 1, Integer::sum);
            else { cnt.merge(p[0], 1, Integer::sum); cnt.merge(p[1], 1, Integer::sum); }
        }
        List<String> res = new ArrayList<>();
        for (var e : cnt.entrySet()) if (e.getValue() >= threshold) res.add(e.getKey());
        res.sort((a, b) -> Long.compare(Long.parseLong(a), Long.parseLong(b)));
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> processLogs(vector<string>& logs, int threshold) {
        unordered_map<string, int> cnt;
        for (auto& log : logs) {
            stringstream ss(log);
            string s, r, amt;
            ss >> s >> r >> amt;
            if (s == r) cnt[s]++;
            else { cnt[s]++; cnt[r]++; }
        }
        vector<string> res;
        for (auto& [k, v] : cnt) if (v >= threshold) res.push_back(k);
        sort(res.begin(), res.end(), [](const string& a, const string& b) { return stoll(a) < stoll(b); });
        return res;
    }
};

