class Solution {
    int[] rearrangeServerLoad(int[] serverCapacity, int[] serverLoad) {
        int n = serverCapacity.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> serverCapacity[a] - serverCapacity[b]);
        int[] rank = new int[n];
        for (int r = 0; r < n; r++) rank[order[r]] = r;
        Integer[] loads = new Integer[n];
        for (int i = 0; i < n; i++) loads[i] = serverLoad[i];
        Arrays.sort(loads, Collections.reverseOrder());
        int[] out = new int[n];
        for (int i = 0; i < n; i++) out[i] = loads[rank[i]];
        return out;
    }
}

class Solution {
public:
    vector<int> rearrangeServerLoad(vector<int>& serverCapacity, vector<int>& serverLoad) {
        int n = serverCapacity.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return serverCapacity[a] < serverCapacity[b]; });
        vector<int> rank(n);
        for (int r = 0; r < n; r++) rank[order[r]] = r;
        vector<int> loads = serverLoad;
        sort(loads.begin(), loads.end(), greater<int>());
        vector<int> out(n);
        for (int i = 0; i < n; i++) out[i] = loads[rank[i]];
        return out;
    }
};

from typing import List

def requestParser(validAuthTokens: List[str], requests: List[List[str]]) -> List[str]:
    valid = set(validAuthTokens)
    out = []
    for method, url in requests:
        idx = url.find('?')
        if idx == -1:
            out.append("INVALID"); continue
        params = {}
        for kv in url[idx + 1:].split('&'):
            if '=' in kv:
                k, v = kv.split('=', 1)
                params[k] = v
        token = params.get('token', '')
        if token not in valid:
            out.append("INVALID"); continue
        if method == 'POST':
            csrf = params.get('csrf', '')
            if len(csrf) < 8 or not all(c.islower() or c.isdigit() for c in csrf) or not csrf.isalnum():
                out.append("INVALID"); continue
            other = {k: v for k, v in params.items() if k not in ('token', 'csrf')}
        else:
            other = {k: v for k, v in params.items() if k != 'token'}
        parts = ["VALID"]
        for k, v in other.items():
            parts.append(k); parts.append(v)
        out.append(",".join(parts))
    return out

import java.util.*;

class Solution {
    String[] requestParser(String[] validAuthTokens, String[][] requests) {
        Set<String> valid = new HashSet<>(Arrays.asList(validAuthTokens));
        String[] out = new String[requests.length];
        for (int i = 0; i < requests.length; i++) {
            String method = requests[i][0], url = requests[i][1];
            int idx = url.indexOf('?');
            if (idx == -1) { out[i] = "INVALID"; continue; }
            LinkedHashMap<String, String> params = new LinkedHashMap<>();
            for (String kv : url.substring(idx + 1).split("&")) {
                int eq = kv.indexOf('=');
                if (eq != -1) params.put(kv.substring(0, eq), kv.substring(eq + 1));
            }
            String token = params.getOrDefault("token", "");
            if (!valid.contains(token)) { out[i] = "INVALID"; continue; }
            if (method.equals("POST")) {
                String csrf = params.getOrDefault("csrf", "");
                boolean ok = csrf.length() >= 8;
                for (int j = 0; ok && j < csrf.length(); j++) {
                    char c = csrf.charAt(j);
                    if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))) ok = false;
                }
                if (!ok) { out[i] = "INVALID"; continue; }
            }
            StringBuilder sb = new StringBuilder("VALID");
            for (var e : params.entrySet()) {
                if (e.getKey().equals("token") || (method.equals("POST") && e.getKey().equals("csrf"))) continue;
                sb.append(",").append(e.getKey()).append(",").append(e.getValue());
            }
            out[i] = sb.toString();
        }
        return out;
    }
}

class Solution {
public:
    vector<string> requestParser(vector<string>& validAuthTokens, vector<vector<string>>& requests) {
        unordered_set<string> valid(validAuthTokens.begin(), validAuthTokens.end());
        vector<string> out;
        for (auto& req : requests) {
            string method = req[0], url = req[1];
            size_t idx = url.find('?');
            if (idx == string::npos) { out.push_back("INVALID"); continue; }
            vector<pair<string,string>> params;
            stringstream ss(url.substr(idx + 1));
            string kv;
            while (getline(ss, kv, '&')) {
                size_t eq = kv.find('=');
                if (eq != string::npos) params.push_back({kv.substr(0, eq), kv.substr(eq + 1)});
            }
            string token;
            for (auto& [k, v] : params) if (k == "token") token = v;
            if (!valid.count(token)) { out.push_back("INVALID"); continue; }
            if (method == "POST") {
                string csrf;
                for (auto& [k, v] : params) if (k == "csrf") csrf = v;
                bool ok = csrf.size() >= 8;
                for (size_t j = 0; ok && j < csrf.size(); j++) {
                    char c = csrf[j];
                    if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))) ok = false;
                }
                if (!ok) { out.push_back("INVALID"); continue; }
            }
            string result = "VALID";
            for (auto& [k, v] : params) {
                if (k == "token" || (method == "POST" && k == "csrf")) continue;
                result += "," + k + "," + v;
            }
            out.push_back(result);
        }
        return out;
    }
};

