def roverMove(n: int, cmds: List[str]) -> int:
    r = c = 0
    moves = {'UP': (-1, 0), 'DOWN': (1, 0), 'LEFT': (0, -1), 'RIGHT': (0, 1)}
    for cmd in cmds:
        dr, dc = moves[cmd]
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            r, c = nr, nc
    return r * n + c

import java.util.*;

class Solution {
    int roverMove(int n, String[] cmds) {
        int r = 0, c = 0;
        Map<String, int[]> moves = Map.of("UP", new int[]{-1, 0}, "DOWN", new int[]{1, 0}, "LEFT", new int[]{0, -1}, "RIGHT", new int[]{0, 1});
        for (String cmd : cmds) {
            int[] d = moves.get(cmd);
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) { r = nr; c = nc; }
        }
        return r * n + c;
    }
}

