            if (cmd == "UP") dr = -1;
            else if (cmd == "DOWN") dr = 1;
            else if (cmd == "LEFT") dc = -1;
            else if (cmd == "RIGHT") dc = 1;
            int nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) { r = nr; c = nc; }
        }
        return r * n + c;
    }
};

