from typing import List

def serviceTimeoutDetection(timestamps: List[int], serviceIds: List[str], threshold: int) -> List[str]:
    groups = defaultdict(list)
    for t, s in zip(timestamps, serviceIds):
        groups[s].append(t)
    out = []
    for s, ts in groups.items():
        ts.sort()
        for i in range(len(ts) - 1):
            if ts[i + 1] - ts[i] > threshold:
                out.append(s)
                break
    return sorted(out)

import java.util.*;

class Solution {
    String[] serviceTimeoutDetection(int[] timestamps, String[] serviceIds, int threshold) {
        Map<String, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < timestamps.length; i++) {
            groups.computeIfAbsent(serviceIds[i], k -> new ArrayList<>()).add(timestamps[i]);
        }
        List<String> out = new ArrayList<>();
        for (var e : groups.entrySet()) {
            List<Integer> ts = e.getValue();
            Collections.sort(ts);
            for (int i = 0; i + 1 < ts.size(); i++) {
                if (ts.get(i + 1) - ts.get(i) > threshold) {
                    out.add(e.getKey());
                    break;
                }
            }
        }
        Collections.sort(out);
        return out.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> serviceTimeoutDetection(vector<int>& timestamps, vector<string>& serviceIds, int threshold) {
        unordered_map<string, vector<int>> groups;
        for (size_t i = 0; i < timestamps.size(); i++) groups[serviceIds[i]].push_back(timestamps[i]);
        vector<string> out;
        for (auto& [k, ts] : groups) {
            sort(ts.begin(), ts.end());
            for (size_t i = 0; i + 1 < ts.size(); i++) {
                if (ts[i + 1] - ts[i] > threshold) { out.push_back(k); break; }
            }
        }
        sort(out.begin(), out.end());
        return out;
    }
};

