def subsetA(arr: List[int]) -> List[int]:
    s = sorted(arr, reverse=True)
    total = sum(s)
    A = []
    sumA = 0
    for v in s:
        A.append(v)
        sumA += v
        if sumA > total - sumA:
            break
    return sorted(A)

import java.util.*;

class Solution {
    int[] subsetA(int[] arr) {
        Integer[] s = new Integer[arr.length];
        for (int i = 0; i < arr.length; i++) s[i] = arr[i];
        Arrays.sort(s, Collections.reverseOrder());
        long total = 0;
        for (int v : arr) total += v;
        List<Integer> A = new ArrayList<>();
        long sumA = 0;
        for (int v : s) {
            A.add(v);
            sumA += v;
            if (sumA > total - sumA) break;
        }
        Collections.sort(A);
        int[] out = new int[A.size()];
        for (int i = 0; i < A.size(); i++) out[i] = A.get(i);
        return out;
    }
}

