class Solution {
    int[] parent, size;
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    int[] visibleProfilesCount(int connection_nodes, int connection_edges, int[] connection_from, int[] connection_to, int[] queries) {
        parent = new int[connection_nodes + 1];
        size = new int[connection_nodes + 1];
        for (int i = 0; i <= connection_nodes; i++) { parent[i] = i; size[i] = 1; }
        for (int i = 0; i < connection_from.length; i++) {
            int a = find(connection_from[i]), b = find(connection_to[i]);
            if (a == b) continue;
            if (size[a] < size[b]) { int t = a; a = b; b = t; }
            parent[b] = a; size[a] += size[b];
        }
        int[] out = new int[queries.length];
        for (int i = 0; i < queries.length; i++) out[i] = size[find(queries[i])];
        return out;
    }
}

class Solution {
public:
    vector<int> parent_, size_;
    int find(int x) {
        while (parent_[x] != x) { parent_[x] = parent_[parent_[x]]; x = parent_[x]; }
        return x;
    }
    vector<int> visibleProfilesCount(int connection_nodes, int connection_edges, vector<int>& connection_from, vector<int>& connection_to, vector<int>& queries) {
        parent_.resize(connection_nodes + 1);
        size_.assign(connection_nodes + 1, 1);
        iota(parent_.begin(), parent_.end(), 0);
        for (size_t i = 0; i < connection_from.size(); i++) {
            int a = find(connection_from[i]), b = find(connection_to[i]);
            if (a == b) continue;
            if (size_[a] < size_[b]) swap(a, b);
            parent_[b] = a; size_[a] += size_[b];
        }
        vector<int> out;
        for (int q : queries) out.push_back(size_[find(q)]);
        return out;
    }
};

