def balance_parentheses(s: str) -> int:
    open_cnt = 0
    insert = 0
    for c in s:
        if c == '(':
            open_cnt += 1
        else:
            if open_cnt > 0:
                open_cnt -= 1
            else:
                insert += 1
    return insert + open_cnt

class Solution {
    public int balanceParentheses(String s) {
        int open = 0, insert = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') open++;
            else if (open > 0) open--;
            else insert++;
        }
        return insert + open;
    }
}

