def find_circle_num(query_type: List[str], student1: List[int], student2: List[int]) -> int:
    nodes = set(student1) | set(student2)
    parent = {x: x for x in nodes}
    size = {x: 1 for x in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb: return
        if size[ra] < size[rb]: ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    # Single answer or array? Returns int based on signature; for the first Total query.
    for i, q in enumerate(query_type):
        a, b = student1[i], student2[i]
        if q == "Friend":
            union(a, b)
        else:
            return size[find(a)] + size[find(b)]
    return -1

import java.util.*;

class Solution {
    int[] parent, size;
    int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    void union_(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra; size[ra] += size[rb];
    }
    public int findCircleNum(String[] queryType, int[] student1, int[] student2) {
        int maxId = 0;
        for (int x : student1) maxId = Math.max(maxId, x);
        for (int x : student2) maxId = Math.max(maxId, x);
        parent = new int[maxId + 1];
        size = new int[maxId + 1];
        for (int i = 0; i <= maxId; i++) { parent[i] = i; size[i] = 1; }
        for (int i = 0; i < queryType.length; i++) {
            if ("Friend".equals(queryType[i])) union_(student1[i], student2[i]);
            else return size[find(student1[i])] + size[find(student2[i])];
        }
        return -1;
    }
}

