    int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        parent[rb] = ra; sz[ra] += sz[rb];
    }
public:
    int findCircleNum(vector<string>& queryType, vector<int>& student1, vector<int>& student2) {
        int maxId = 0;
        for (int x : student1) maxId = max(maxId, x);
        for (int x : student2) maxId = max(maxId, x);
        parent.resize(maxId + 1); sz.assign(maxId + 1, 1);
        iota(parent.begin(), parent.end(), 0);
        for (int i = 0; i < (int)queryType.size(); i++) {
            if (queryType[i] == "Friend") unite(student1[i], student2[i]);
            else return sz[find(student1[i])] + sz[find(student2[i])];
        }
        return -1;
    }
};

