def get_subsequence_count(s1, s2):
    n = len(s1)
    if n > len(s2):
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    for c in s2:
        for i in range(n, 0, -1):
            if s1[i-1] == c:
                dp[i] += dp[i-1]
    return dp[n]

class Solution {
    static long getSubsequenceCount(String s1, String s2) {
        int n = s1.length(), m = s2.length();
        if (n > m) return 0;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int j = 0; j < m; j++) {
            char c = s2.charAt(j);
            for (int i = n; i >= 1; i--)
                if (s1.charAt(i - 1) == c) dp[i] += dp[i - 1];
        }
        return dp[n];
    }
}

