class Solution {
    public String[] bitPattern(int[] num) {
        int n = num.length;
        java.util.HashSet<Integer> seen = new java.util.HashSet<>();
        char[] left = new char[n], right = new char[n];
        for (int i = 0; i < n; i++) {
            left[i] = seen.contains(num[i]) ? '1' : '0';
            seen.add(num[i]);
        }
        seen.clear();
        for (int i = n - 1; i >= 0; i--) {
            right[i] = seen.contains(num[i]) ? '1' : '0';
            seen.add(num[i]);
        }
        return new String[]{new String(left), new String(right)};
    }
}

class Solution {
public:
    vector<string> bitPattern(vector<int>& num) {
        int n = num.size();
        unordered_set<int> seen;
        string left(n, '0'), right(n, '0');
        for (int i = 0; i < n; ++i) {
            if (seen.count(num[i])) left[i] = '1';
            seen.insert(num[i]);
        }
        seen.clear();
        for (int i = n - 1; i >= 0; --i) {
            if (seen.count(num[i])) right[i] = '1';
            seen.insert(num[i]);
        }
        return {left, right};
    }
};

import re

def classifyTexts(texts, spamWords):
    spam = {w.lower() for w in spamWords}
    res = []
    for t in texts:
        words = re.findall(r"[a-zA-Z]+", t.lower())
        res.append("spam" if any(w in spam for w in words) else "not_spam")
    return res

class Solution {
    public String[] classifyTexts(String[] texts, String[] spamWords) {
        java.util.HashSet<String> spam = new java.util.HashSet<>();
        for (String w : spamWords) spam.add(w.toLowerCase());
        String[] res = new String[texts.length];
        for (int i = 0; i < texts.length; i++) {
            boolean hit = false;
            for (String w : texts[i].toLowerCase().split("[^a-z]+")) {
                if (!w.isEmpty() && spam.contains(w)) { hit = true; break; }
            }
            res[i] = hit ? "spam" : "not_spam";
        }
        return res;
    }
}

class Solution {
public:
    vector<string> classifyTexts(vector<string>& texts, vector<string>& spamWords) {
        unordered_set<string> spam;
        for (auto w : spamWords) {
            transform(w.begin(), w.end(), w.begin(), ::tolower);
            spam.insert(w);
        }
        vector<string> res;
        for (auto& t : texts) {
            string lower = t;
            transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
            bool hit = false;
            string cur;
            for (char c : lower) {
                if (isalpha(c)) cur += c;
                else {
                    if (!cur.empty() && spam.count(cur)) { hit = true; break; }
                    cur.clear();
                }
            }
            if (!hit && !cur.empty() && spam.count(cur)) hit = true;
            res.push_back(hit ? "spam" : "not_spam");
        }
        return res;
    }
};

from bisect import bisect_left

def minAbsDifference(nums, goal):
    def all_sums(arr):
        sums = [0]
        for x in arr:
            sums += [s + x for s in sums]
        return sums
    n = len(nums)
    L, R = nums[:n // 2], nums[n // 2:]
    A = all_sums(L)
    B = sorted(set(all_sums(R)))
    best = abs(goal)
    for a in A:
        need = goal - a
        i = bisect_left(B, need)
        for j in (i - 1, i):
            if 0 <= j < len(B):
                best = min(best, abs(a + B[j] - goal))
    return best

class Solution {
    public int minAbsDifference(int[] nums, int goal) {
        int n = nums.length;
        int[] L = java.util.Arrays.copyOfRange(nums, 0, n / 2);
        int[] R = java.util.Arrays.copyOfRange(nums, n / 2, n);
        int[] A = allSums(L), B = allSums(R);
        java.util.Arrays.sort(B);
        long best = Math.abs((long) goal);
        for (int a : A) {
            int need = goal - a;
            int lo = 0, hi = B.length;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (B[mid] < need) lo = mid + 1; else hi = mid;
            }
            for (int j : new int[]{lo - 1, lo}) {
                if (j >= 0 && j < B.length) {
                    long d = Math.abs((long) a + B[j] - goal);
                    if (d < best) best = d;
                }
            }
        }
        return (int) best;
    }
    int[] allSums(int[] arr) {
        int sz = 1 << arr.length;
        int[] s = new int[sz];
        for (int mask = 1; mask < sz; mask++) {
            int lo = Integer.numberOfTrailingZeros(mask);
            s[mask] = s[mask ^ (1 << lo)] + arr[lo];
        }
        return s;
    }
}

class Solution {
public:
    vector<int> allSums(vector<int>& arr) {
        int sz = 1 << arr.size();
        vector<int> s(sz, 0);
        for (int mask = 1; mask < sz; ++mask) {
            int lo = __builtin_ctz(mask);
            s[mask] = s[mask ^ (1 << lo)] + arr[lo];
        }
        return s;
    }
    int minAbsDifference(vector<int>& nums, int goal) {
        int n = nums.size();
        vector<int> L(nums.begin(), nums.begin() + n / 2);
        vector<int> R(nums.begin() + n / 2, nums.end());
        auto A = allSums(L), B = allSums(R);
        sort(B.begin(), B.end());
        long long best = abs((long long) goal);
        for (int a : A) {
            int need = goal - a;
            auto it = lower_bound(B.begin(), B.end(), need);
            for (auto p : {it - B.begin() - 1, it - B.begin()}) {
                if (p >= 0 && p < (long long) B.size()) {
                    long long d = abs((long long) a + B[p] - goal);
                    if (d < best) best = d;
                }
            }
        }
        return (int) best;
    }
};

from collections import defaultdict, deque
from itertools import product

def collectOpportunityData(n, edges, opportunityData):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v); g[v].append(u)
    importants = [i for i in range(n) if opportunityData[i] == 1]
    if not importants:
        return 0
    # 距离 <= 2 的覆盖关系
    def neighbors2(src):
        d = {src: 0}
        q = deque([src])
        while q:
            u = q.popleft()
            if d[u] == 2: continue
            for v in g[u]:
                if v not in d:
                    d[v] = d[u] + 1
                    q.append(v)
        return list(d.keys())
    covers = [neighbors2(i) for i in importants]
    best = float('inf')
    # 求树的 Steiner 子树边数：选 anchors 后，子树边数 = ((Σ deg in induced subgraph)/2) 但对树可以用 DFS：保留所有 anchors 及它们之间路径上的所有节点。
    def steiner_edges(anchors):
        anchors = set(anchors)
        if len(anchors) <= 1: return 0
        # 在树上从任一 anchor 出发 DFS，标记从该子树是否含 anchor，递归累加贡献边数
        root = next(iter(anchors))
        seen = [False] * n
        seen[root] = True
        order = []
        stack = [(root, -1)]
        parent = [-1] * n
        while stack:
            u, p = stack.pop()
            order.append(u)
            parent[u] = p
            for v in g[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append((v, u))
        # 自下而上：每子树含 anchor → 父边算入
        has = [False] * n
        edges_used = 0
        for u in reversed(order):
            if u in anchors:
                has[u] = True
            if has[u] and parent[u] != -1:
                edges_used += 1
                has[parent[u]] = True
        return edges_used
    for combo in product(*covers):
        e = steiner_edges(set(combo))
        if 2 * e < best:
            best = 2 * e
    return best

class Solution {
    int n;
    java.util.List<java.util.List<Integer>> g;
    public int collectOpportunityData(int n, int[][] edges, int[] opportunityData) {
        this.n = n;
        g = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new java.util.ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        java.util.List<Integer> imps = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) if (opportunityData[i] == 1) imps.add(i);
        if (imps.isEmpty()) return 0;
        java.util.List<int[]> covers = new java.util.ArrayList<>();
        for (int i : imps) covers.add(neighbors2(i));
        int[] best = {Integer.MAX_VALUE};
        dfs(covers, 0, new java.util.HashSet<>(), best);
        return best[0];
    }
    int[] neighbors2(int src) {
        int[] dist = new int[n];
        java.util.Arrays.fill(dist, -1);
        dist[src] = 0;
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.offer(src);
        java.util.List<Integer> res = new java.util.ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            res.add(u);
            if (dist[u] == 2) continue;
            for (int v : g.get(u)) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.offer(v); }
        }
        int[] arr = new int[res.size()];
        for (int i = 0; i < res.size(); i++) arr[i] = res.get(i);
        return arr;
    }
    void dfs(java.util.List<int[]> covers, int k, java.util.HashSet<Integer> anchors, int[] best) {
        if (k == covers.size()) {
            int e = steinerEdges(anchors);
            if (2 * e < best[0]) best[0] = 2 * e;
            return;
        }
        for (int c : covers.get(k)) {
            boolean added = anchors.add(c);
            dfs(covers, k + 1, anchors, best);
            if (added) anchors.remove(c);
        }
    }
    int steinerEdges(java.util.HashSet<Integer> anchors) {
        if (anchors.size() <= 1) return 0;
        int root = anchors.iterator().next();
        boolean[] seen = new boolean[n];
        seen[root] = true;
        int[] parent = new int[n], order = new int[n];
        java.util.Arrays.fill(parent, -1);
        java.util.ArrayDeque<Integer> stk = new java.util.ArrayDeque<>();
        stk.push(root);
        int idx = 0;
        while (!stk.isEmpty()) {
            int u = stk.pop();
            order[idx++] = u;
            for (int v : g.get(u)) if (!seen[v]) { seen[v] = true; parent[v] = u; stk.push(v); }
        }
        boolean[] has = new boolean[n];
        int used = 0;
        for (int i = idx - 1; i >= 0; i--) {
            int u = order[i];
            if (anchors.contains(u)) has[u] = true;
            if (has[u] && parent[u] != -1) { used++; has[parent[u]] = true; }
        }
        return used;
    }
}

class Solution {
public:
    int n;
    vector<vector<int>> g;
    vector<int> neighbors2(int src) {
        vector<int> dist(n, -1);
        dist[src] = 0;
        queue<int> q;
        q.push(src);
        vector<int> res;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            res.push_back(u);
            if (dist[u] == 2) continue;
            for (int v : g[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }
        }
        return res;
    }
    int steinerEdges(unordered_set<int>& anchors) {
        if (anchors.size() <= 1) return 0;
        int root = *anchors.begin();
        vector<bool> seen(n, false);
        seen[root] = true;
        vector<int> parent(n, -1), order;
        stack<int> stk;
        stk.push(root);
        while (!stk.empty()) {
            int u = stk.top(); stk.pop();
            order.push_back(u);
            for (int v : g[u]) if (!seen[v]) { seen[v] = true; parent[v] = u; stk.push(v); }
        }
        vector<bool> has(n, false);
        int used = 0;
        for (int i = (int) order.size() - 1; i >= 0; --i) {
            int u = order[i];
            if (anchors.count(u)) has[u] = true;
            if (has[u] && parent[u] != -1) { used++; has[parent[u]] = true; }
        }
        return used;
    }
    int best;
    void dfs(vector<vector<int>>& covers, int k, unordered_set<int>& anchors) {
        if (k == (int) covers.size()) {
            best = min(best, 2 * steinerEdges(anchors));
            return;
        }
        for (int c : covers[k]) {
            bool added = anchors.insert(c).second;
            dfs(covers, k + 1, anchors);
            if (added) anchors.erase(c);
        }
    }
    int collectOpportunityData(int n_, vector<vector<int>>& edges, vector<int>& opportunityData) {
        n = n_;
        g.assign(n, {});
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> imps;
        for (int i = 0; i < n; ++i) if (opportunityData[i] == 1) imps.push_back(i);
        if (imps.empty()) return 0;
        vector<vector<int>> covers;
        for (int i : imps) covers.push_back(neighbors2(i));
        best = INT_MAX;
        unordered_set<int> anchors;
        dfs(covers, 0, anchors);
        return best;
    }
};

def constructWinningSequence(n, lo, hi):
    rng = hi - lo
    p = max(0, n - 1 - rng)
    if p > rng:
        return [-1]
    seq = []
    for i in range(p + 1):
        seq.append(hi - p + i)
    for i in range(1, n - p):
        seq.append(hi - i)
    return seq

class Solution {
    public int[] constructWinningSequence(int n, int lo, int hi) {
        int rng = hi - lo;
        int p = Math.max(0, n - 1 - rng);
        if (p > rng) return new int[]{-1};
        int[] seq = new int[n];
        for (int i = 0; i <= p; i++) seq[i] = hi - p + i;
        for (int i = 1; i < n - p; i++) seq[p + i] = hi - i;
        return seq;
    }
}

class Solution {
