        int p = max(0, n - 1 - rng);
        if (p > rng) return {-1};
        vector<int> seq(n);
        for (int i = 0; i <= p; ++i) seq[i] = hi - p + i;
        for (int i = 1; i < n - p; ++i) seq[p + i] = hi - i;
        return seq;
    }
};

class Solution {
    public int countMinimumOperations(int h, int w, int h1, int w1) {
        return folds(h, h1) + folds(w, w1);
    }
    int folds(int big, int small) {
        if (small >= big) return 0;
        int k = 0;
        double cur = big;
        while (cur > small) {
            cur = cur / 2.0;
            k++;
        }
        return k;
    }
}

