    }
};

def countUniqueDigits(numbers, l, r):
    cnt = 0
    for i in range(l, r + 1):
        s = str(numbers[i])
        if len(set(s)) == len(s):
            cnt += 1
    return cnt

class Solution {
    public int countUniqueDigits(int[] numbers, int l, int r) {
        int cnt = 0;
        for (int i = l; i <= r; i++) {
            String s = Integer.toString(numbers[i]);
            int mask = 0;
            boolean ok = true;
            for (char c : s.toCharArray()) {
                int bit = 1 << (c - '0');
                if ((mask & bit) != 0) { ok = false; break; }
                mask |= bit;
            }
            if (ok) cnt++;
        }
        return cnt;
    }
}

