def countSubstrings(s):
    ans = 0
    prev = 0
    cur = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            cur += 1
        else:
            ans += min(prev, cur)
            prev = cur
            cur = 1
    ans += min(prev, cur)
    return ans

class Solution {
    public int countSubstrings(String s) {
        int ans = 0, prev = 0, cur = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) cur++;
            else {
                ans += Math.min(prev, cur);
                prev = cur;
                cur = 1;
            }
        }
        return ans + Math.min(prev, cur);
    }
}

class Solution {
public:
    int countSubstrings(string s) {
        int ans = 0, prev = 0, cur = 1;
        for (int i = 1; i < (int) s.size(); ++i) {
            if (s[i] == s[i - 1]) cur++;
            else { ans += min(prev, cur); prev = cur; cur = 1; }
        }
        return ans + min(prev, cur);
    }
};

def findAllPairs(arr):
    n = len(arr)
    res = []
    for i in range(n):
        for j in range(i + 1, n):
            x, y = arr[i], arr[j]
            cond1 = min(abs(x - y), abs(x + y))
            cond2 = max(abs(x), abs(y))
            if cond1 <= cond2:
                res.append([x, y])
    return res

class Solution {
    public int[][] findAllPairs(int[] arr) {
        int n = arr.length;
        java.util.List<int[]> res = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) {
            int x = arr[i], y = arr[j];
            int c1 = Math.min(Math.abs(x - y), Math.abs(x + y));
            int c2 = Math.max(Math.abs(x), Math.abs(y));
            if (c1 <= c2) res.add(new int[]{x, y});
        }
        return res.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> findAllPairs(vector<int>& arr) {
        int n = arr.size();
        vector<vector<int>> res;
        for (int i = 0; i < n; ++i) for (int j = i + 1; j < n; ++j) {
            int x = arr[i], y = arr[j];
            int c1 = min(abs(x - y), abs(x + y));
            int c2 = max(abs(x), abs(y));
            if (c1 <= c2) res.push_back({x, y});
        }
        return res;
    }
};

def findLongestSubsequenceSubstring(x, y):
    n, m = len(x), len(y)
    best = 0
    for i in range(m):
        j, k = i, 0
        while j < m and k < n:
            if y[j] == x[k]:
                j += 1
            k += 1
        best = max(best, j - i)
    return best

class Solution {
    public int findLongestSubsequenceSubstring(String x, String y) {
        int n = x.length(), m = y.length(), best = 0;
        for (int i = 0; i < m; i++) {
            int j = i, k = 0;
            while (j < m && k < n) {
                if (y.charAt(j) == x.charAt(k)) j++;
                k++;
            }
            best = Math.max(best, j - i);
        }
        return best;
    }
}

class Solution {
