        int n = x.size(), m = y.size(), best = 0;
        for (int i = 0; i < m; ++i) {
            int j = i, k = 0;
            while (j < m && k < n) {
                if (y[j] == x[k]) j++;
                k++;
            }
            best = max(best, j - i);
        }
        return best;
    }
};

def findMinimumIdleness(shader, switchCount):
    def ok(L):
        flips = 0
        cnt = 1
        chars = list(shader)
        for i in range(1, len(chars)):
            if chars[i] == chars[i - 1]:
                cnt += 1
                if cnt > L:
                    flips += 1
                    chars[i] = 'b' if chars[i] == 'a' else 'a'
                    cnt = 1
                    # 若 i+1 与新 chars[i] 相同需重新计 cnt（但只是单步）
            else:
                cnt = 1
        return flips <= switchCount
    lo, hi = 1, len(shader)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

class Solution {
    int switchCount;
    String shader;
    public int findMinimumIdleness(String shader, int switchCount) {
        this.shader = shader;
        this.switchCount = switchCount;
        int lo = 1, hi = shader.length();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    boolean ok(int L) {
        char[] cs = shader.toCharArray();
        int flips = 0, cnt = 1;
        for (int i = 1; i < cs.length; i++) {
            if (cs[i] == cs[i - 1]) {
                cnt++;
                if (cnt > L) {
                    flips++;
                    cs[i] = cs[i] == 'a' ? 'b' : 'a';
                    cnt = 1;
                }
            } else cnt = 1;
        }
        return flips <= switchCount;
    }
}

class Solution {
public:
    int switchCount_;
    string shader_;
    bool ok(int L) {
        string cs = shader_;
        int flips = 0, cnt = 1;
        for (int i = 1; i < (int) cs.size(); ++i) {
            if (cs[i] == cs[i - 1]) {
                cnt++;
                if (cnt > L) {
                    flips++;
                    cs[i] = cs[i] == 'a' ? 'b' : 'a';
                    cnt = 1;
                }
            } else cnt = 1;
        }
        return flips <= switchCount_;
    }
    int findMinimumIdleness(string shader, int switchCount) {
        shader_ = shader; switchCount_ = switchCount;
        int lo = 1, hi = shader.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

class Solution {
    public long findNumberOfPerfectPairs(int[] arr) {
        int n = arr.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = Math.abs((long) arr[i]);
        java.util.Arrays.sort(a);
        long ans = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (j < i + 1) j = i + 1;
            while (j < n && a[j] <= 2 * a[i]) j++;
            ans += j - i - 1;
        }
        return ans;
    }
}

