        }
        return ans;
    }
};

def findWordsNotInSubsequence(s, t):
    def is_subseq(w):
        i = 0
        for c in t:
            if i < len(w) and c == w[i]:
                i += 1
        return i == len(w)
    return [w for w in s.split() if not is_subseq(w)]

class Solution {
    public String[] findWordsNotInSubsequence(String s, String t) {
        java.util.List<String> res = new java.util.ArrayList<>();
        for (String w : s.split("\\s+")) {
            int i = 0;
            for (int j = 0; j < t.length() && i < w.length(); j++) {
                if (t.charAt(j) == w.charAt(i)) i++;
            }
            if (i != w.length()) res.add(w);
        }
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> findWordsNotInSubsequence(string s, string t) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        vector<string> res;
        for (auto& word : words) {
            int i = 0;
            for (int j = 0; j < (int) t.size() && i < (int) word.size(); ++j) {
                if (t[j] == word[i]) i++;
            }
            if (i != (int) word.size()) res.push_back(word);
        }
        return res;
    }
};

def getMaxEfficiency(capacity, numServers):
    cap = sorted(capacity)
    n = len(cap)
    b = sum(1 for s in numServers if s > 1)
    return sum(cap[n - 1 - i] - cap[i] for i in range(b))

class Solution {
    long getMaxEfficiency(int[] capacity, int[] numServers) {
        int[] cap = capacity.clone();
        Arrays.sort(cap);
        int n = cap.length, b = 0;
        for (int s : numServers) if (s > 1) b++;
        long ans = 0;
        for (int i = 0; i < b; i++) ans += (long)(cap[n - 1 - i] - cap[i]);
        return ans;
    }
}

class Solution {
public:
    long long getMaxEfficiency(vector<int>& capacity, vector<int>& numServers) {
        vector<int> cap = capacity;
        sort(cap.begin(), cap.end());
        int n = cap.size(), b = 0;
        for (int s : numServers) if (s > 1) ++b;
        long long ans = 0;
        for (int i = 0; i < b; ++i) ans += (long long)(cap[n - 1 - i] - cap[i]);
        return ans;
    }
};

def getMaximumSumOfStrengths(arr):
    a = sorted(arr)
    return sum((i + 1) * v for i, v in enumerate(a))

class Solution {
    long getMaximumSumOfStrengths(int[] arr) {
        int[] a = arr.clone();
        Arrays.sort(a);
        long ans = 0;
        for (int i = 0; i < a.length; i++) ans += (long)(i + 1) * a[i];
        return ans;
    }
}

class Solution {
public:
    long long getMaximumSumOfStrengths(vector<int>& arr) {
        vector<int> a = arr;
        sort(a.begin(), a.end());
        long long ans = 0;
        for (int i = 0; i < (int)a.size(); ++i) ans += (long long)(i + 1) * a[i];
        return ans;
    }
};

def getMinimumDevelopmentTime(developmentTime, integrationTime):
    n = len(developmentTime)
    def feasible(T):
        s = 0
        for i in range(n):
            if developmentTime[i] > T:
                s += integrationTime[i]
                if s > T: return False
        return True
    lo, hi = 0, max(max(developmentTime), sum(integrationTime))
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid): hi = mid
        else: lo = mid + 1
    return lo

class Solution {
    int getMinimumDevelopmentTime(int[] developmentTime, int[] integrationTime) {
        int n = developmentTime.length;
        long sumI = 0, maxD = 0;
        for (int v : integrationTime) sumI += v;
        for (int v : developmentTime) maxD = Math.max(maxD, v);
        long lo = 0, hi = Math.max(maxD, sumI);
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            long s = 0;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if (developmentTime[i] > mid) {
                    s += integrationTime[i];
                    if (s > mid) { ok = false; break; }
                }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
}

class Solution {
public:
    int getMinimumDevelopmentTime(vector<int>& developmentTime, vector<int>& integrationTime) {
        int n = developmentTime.size();
        long long sumI = 0, maxD = 0;
        for (int v : integrationTime) sumI += v;
        for (int v : developmentTime) maxD = max<long long>(maxD, v);
        long long lo = 0, hi = max(maxD, sumI);
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            long long s = 0;
            bool ok = true;
            for (int i = 0; i < n; ++i) {
                if (developmentTime[i] > mid) {
                    s += integrationTime[i];
                    if (s > mid) { ok = false; break; }
                }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
};

from bisect import bisect_left, bisect_right
from functools import lru_cache

def getMinimumTime(n, high_priority, normal_time, priority_time):
    hp = sorted(high_priority)
    @lru_cache(maxsize=None)
    def solve(l, r):
        length = r - l + 1
        x = bisect_right(hp, r) - bisect_left(hp, l)
        execute = length * x * priority_time if x > 0 else length * normal_time
        if length > 1 and length % 2 == 0:
            mid = (l + r) // 2
            return min(execute, solve(l, mid) + solve(mid + 1, r))
        return execute
    return solve(1, n)

class Solution {
    int[] hp; int normalT, priorityT;
    Map<Long, Long> memo = new HashMap<>();
    int getMinimumTime(int n, int[] high_priority, int normal_time, int priority_time) {
        hp = high_priority.clone();
        Arrays.sort(hp);
        normalT = normal_time; priorityT = priority_time;
        return (int) solve(1, n);
    }
    long solve(int l, int r) {
        long key = ((long) l << 32) | (r & 0xffffffffL);
        Long cached = memo.get(key);
        if (cached != null) return cached;
        int length = r - l + 1;
        int lo = lowerBound(l), hi = upperBound(r);
        int x = hi - lo;
        long execute = (x > 0) ? (long) length * x * priorityT : (long) length * normalT;
        long best = execute;
        if (length > 1 && length % 2 == 0) {
            int mid = l + length / 2 - 1;
            best = Math.min(best, solve(l, mid) + solve(mid + 1, r));
        }
        memo.put(key, best);
        return best;
    }
    int lowerBound(int v) {
        int lo = 0, hi = hp.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (hp[m] < v) lo = m + 1; else hi = m; }
        return lo;
    }
    int upperBound(int v) {
        int lo = 0, hi = hp.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (hp[m] <= v) lo = m + 1; else hi = m; }
        return lo;
    }
}

class Solution {
    vector<int> hp; int normalT, priorityT;
    unordered_map<long long, long long> memo;
    long long solve(int l, int r) {
        long long key = ((long long) l << 32) | (unsigned) r;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int length = r - l + 1;
        int lo = lower_bound(hp.begin(), hp.end(), l) - hp.begin();
        int hi = upper_bound(hp.begin(), hp.end(), r) - hp.begin();
        int x = hi - lo;
        long long execute = (x > 0) ? (long long) length * x * priorityT : (long long) length * normalT;
        long long best = execute;
        if (length > 1 && length % 2 == 0) {
            int mid = l + length / 2 - 1;
            best = min(best, solve(l, mid) + solve(mid + 1, r));
        }
        return memo[key] = best;
    }
public:
    int getMinimumTime(int n, vector<int>& high_priority, int normal_time, int priority_time) {
        hp = high_priority;
        sort(hp.begin(), hp.end());
        normalT = normal_time; priorityT = priority_time;
        return (int) solve(1, n);
    }
};

from collections import deque

def getNodeToRemove(g_nodes, g_from, g_to, malware):
    adj = [[] for _ in range(g_nodes + 1)]
    for u, v in zip(g_from, g_to):
        adj[u].append(v); adj[v].append(u)
    infected_nodes = [i + 1 for i, m in enumerate(malware) if m == 1]
    best_count, best_node = float('inf'), -1
    for remove in infected_nodes:
        visited = [False] * (g_nodes + 1)
        visited[remove] = True
        q = deque()
        for s in infected_nodes:
            if s != remove and not visited[s]:
                visited[s] = True; q.append(s)
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True; q.append(v)
        cnt = sum(1 for i in range(1, g_nodes + 1) if visited[i] and i != remove)
        if cnt < best_count or (cnt == best_count and remove < best_node):
            best_count, best_node = cnt, remove
    return best_node

class Solution {
    int getNodeToRemove(int g_nodes, int[] g_from, int[] g_to, int[] malware) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= g_nodes; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < g_from.length; i++) {
            adj.get(g_from[i]).add(g_to[i]);
            adj.get(g_to[i]).add(g_from[i]);
        }
        List<Integer> infectedNodes = new ArrayList<>();
        for (int i = 0; i < malware.length; i++) if (malware[i] == 1) infectedNodes.add(i + 1);
        int bestCount = Integer.MAX_VALUE, bestNode = -1;
        for (int remove : infectedNodes) {
            boolean[] visited = new boolean[g_nodes + 1];
            visited[remove] = true;
            Deque<Integer> q = new ArrayDeque<>();
            for (int s : infectedNodes) if (s != remove && !visited[s]) { visited[s] = true; q.offer(s); }
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u)) if (!visited[v]) { visited[v] = true; q.offer(v); }
            }
            int cnt = 0;
            for (int i = 1; i <= g_nodes; i++) if (visited[i] && i != remove) cnt++;
            if (cnt < bestCount || (cnt == bestCount && remove < bestNode)) {
                bestCount = cnt; bestNode = remove;
            }
        }
        return bestNode;
    }
}

class Solution {
public:
    int getNodeToRemove(int g_nodes, vector<int>& g_from, vector<int>& g_to, vector<int>& malware) {
        vector<vector<int>> adj(g_nodes + 1);
        for (int i = 0; i < (int) g_from.size(); ++i) {
            adj[g_from[i]].push_back(g_to[i]);
            adj[g_to[i]].push_back(g_from[i]);
        }
        vector<int> infectedNodes;
        for (int i = 0; i < (int) malware.size(); ++i) if (malware[i] == 1) infectedNodes.push_back(i + 1);
        int bestCount = INT_MAX, bestNode = -1;
        for (int remove : infectedNodes) {
            vector<bool> visited(g_nodes + 1, false);
            visited[remove] = true;
            queue<int> q;
            for (int s : infectedNodes) if (s != remove && !visited[s]) { visited[s] = true; q.push(s); }
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) if (!visited[v]) { visited[v] = true; q.push(v); }
            }
            int cnt = 0;
            for (int i = 1; i <= g_nodes; ++i) if (visited[i] && i != remove) ++cnt;
            if (cnt < bestCount || (cnt == bestCount && remove < bestNode)) {
                bestCount = cnt; bestNode = remove;
            }
        }
        return bestNode;
    }
};

