def getSpecialSubstring(s, k, charValue):
    def is_normal(c):
        return charValue[ord(c) - ord('a')] == '0'
    left = 0; cnt = 0; ans = 0
    for right, c in enumerate(s):
        if is_normal(c): cnt += 1
        while cnt > k:
            if is_normal(s[left]): cnt -= 1
            left += 1
        ans = max(ans, right - left + 1)
    return ans

class Solution {
    int getSpecialSubstring(String s, int k, String charValue) {
        int left = 0, cnt = 0, ans = 0;
        for (int right = 0; right < s.length(); right++) {
            if (charValue.charAt(s.charAt(right) - 'a') == '0') cnt++;
            while (cnt > k) {
                if (charValue.charAt(s.charAt(left) - 'a') == '0') cnt--;
                left++;
            }
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

class Solution {
public:
    int getSpecialSubstring(string s, int k, string charValue) {
        int left = 0, cnt = 0, ans = 0;
        for (int right = 0; right < (int) s.size(); ++right) {
            if (charValue[s[right] - 'a'] == '0') ++cnt;
            while (cnt > k) {
                if (charValue[s[left] - 'a'] == '0') --cnt;
                ++left;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

class Solution {
    int leastHours(int[] developmentTime, int[] integrationTime) {
        int n = developmentTime.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> developmentTime[b] - developmentTime[a]);
        int ans = developmentTime[idx[0]];
        long acc = 0;
        for (int k = 1; k <= n; k++) {
            acc += integrationTime[idx[k - 1]];
            int remainingMax = (k < n) ? developmentTime[idx[k]] : 0;
            ans = Math.min(ans, (int) Math.max(acc, remainingMax));
        }
        return ans;
    }
}

class Solution {
public:
    int leastHours(vector<int>& developmentTime, vector<int>& integrationTime) {
        int n = developmentTime.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            return developmentTime[a] > developmentTime[b];
        });
        int ans = developmentTime[idx[0]];
        long long acc = 0;
        for (int k = 1; k <= n; ++k) {
            acc += integrationTime[idx[k - 1]];
            int remainingMax = (k < n) ? developmentTime[idx[k]] : 0;
            ans = min<long long>(ans, max<long long>(acc, remainingMax));
        }
        return ans;
    }
};

class Solution {
    int leastStressfulPath(int graph_nodes, int[] graph_from, int[] graph_to, int[] graph_weight, int source, int destination) {
        List<int[]>[] adj = new List[graph_nodes + 1];
        for (int i = 0; i <= graph_nodes; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < graph_from.length; i++) {
            adj[graph_from[i]].add(new int[]{graph_to[i], graph_weight[i]});
            adj[graph_to[i]].add(new int[]{graph_from[i], graph_weight[i]});
        }
        int[] dist = new int[graph_nodes + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, source});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > dist[u]) continue;
            if (u == destination) return d;
            for (int[] e : adj[u]) {
                int v = e[0], w = e[1];
                int nd = Math.max(d, w);
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new int[]{nd, v});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int leastStressfulPath(int graph_nodes, vector<int>& graph_from, vector<int>& graph_to, vector<int>& graph_weight, int source, int destination) {
        vector<vector<pair<int,int>>> adj(graph_nodes + 1);
        for (int i = 0; i < (int) graph_from.size(); ++i) {
            adj[graph_from[i]].push_back({graph_to[i], graph_weight[i]});
            adj[graph_to[i]].push_back({graph_from[i], graph_weight[i]});
        }
        vector<int> dist(graph_nodes + 1, INT_MAX);
        dist[source] = 0;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
        pq.push({0, source});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            if (u == destination) return d;
            for (auto [v, w] : adj[u]) {
                int nd = max(d, w);
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.push({nd, v});
                }
            }
        }
        return -1;
    }
};

def longestSubsequenceWhichIsSubstring(x, y):
    n, m = len(x), len(y)
    ans = 0
    for j in range(m):
        k = j; i = 0
        while i < n and k < m:
            if x[i] == y[k]:
                k += 1
            i += 1
        ans = max(ans, k - j)
    return ans

class Solution {
    int longestSubsequenceWhichIsSubstring(String x, String y) {
        int n = x.length(), m = y.length(), ans = 0;
        for (int j = 0; j < m; j++) {
            int k = j, i = 0;
            while (i < n && k < m) {
                if (x.charAt(i) == y.charAt(k)) k++;
                i++;
            }
            ans = Math.max(ans, k - j);
        }
        return ans;
    }
}

class Solution {
public:
    int longestSubsequenceWhichIsSubstring(string x, string y) {
        int n = x.size(), m = y.size(), ans = 0;
        for (int j = 0; j < m; ++j) {
            int k = j, i = 0;
            while (i < n && k < m) {
                if (x[i] == y[k]) ++k;
                ++i;
            }
            ans = max(ans, k - j);
        }
        return ans;
    }
};

def maxNumberOfOperations(s):
    stack = []; ops = 0
    for c in s:
        if stack and stack[-1] == c:
            stack.pop(); ops += 1
        else:
            stack.append(c)
    return ops

class Solution {
    int maxNumberOfOperations(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        int ops = 0;
        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && stack.peek() == c) {
                stack.pop(); ops++;
            } else {
                stack.push(c);
            }
        }
        return ops;
    }
}

class Solution {
public:
    int maxNumberOfOperations(string s) {
        string stack;
        int ops = 0;
        for (char c : s) {
            if (!stack.empty() && stack.back() == c) {
                stack.pop_back(); ++ops;
            } else {
                stack.push_back(c);
            }
        }
        return ops;
    }
};

from functools import lru_cache

def maximizeSumOfProcessedTimes(times):
    n = len(times)
    @lru_cache(maxsize=None)
    def rec(i, c):
        if i == n: return (0, 0)
        # 选 A: 给 c 核，latch 给对方
        a1, a2 = rec(i + 1, 3 - c)
        if c == 1: a1 += times[i]
        else: a2 += times[i]
        # 选 B: 给对方核，latch 留住
        b1, b2 = rec(i + 1, c)
        if c == 1: b2 += times[i]
        else: b1 += times[i]
        # 持有 latch 的核选自己更大的那个
        if c == 1:
            return (a1, a2) if a1 >= b1 else (b1, b2)
        else:
            return (a1, a2) if a2 >= b2 else (b1, b2)
    s1, s2 = rec(0, 1)
    return [s1, s2]

class Solution {
    int[] times; long[][][] memo; boolean[][] seen;
    int[] maximizeSumOfProcessedTimes(int[] times) {
        this.times = times;
        int n = times.length;
        memo = new long[n + 1][3][2];
        seen = new boolean[n + 1][3];
        long[] res = rec(0, 1);
        return new int[]{(int) res[0], (int) res[1]};
    }
    long[] rec(int i, int c) {
        if (i == times.length) return new long[]{0, 0};
        if (seen[i][c]) return new long[]{memo[i][c][0], memo[i][c][1]};
        long[] a = rec(i + 1, 3 - c);
        long a1 = a[0], a2 = a[1];
        if (c == 1) a1 += times[i]; else a2 += times[i];
        long[] b = rec(i + 1, c);
        long b1 = b[0], b2 = b[1];
        if (c == 1) b2 += times[i]; else b1 += times[i];
        long r1, r2;
        if (c == 1) { if (a1 >= b1) { r1 = a1; r2 = a2; } else { r1 = b1; r2 = b2; } }
        else { if (a2 >= b2) { r1 = a1; r2 = a2; } else { r1 = b1; r2 = b2; } }
        memo[i][c][0] = r1; memo[i][c][1] = r2; seen[i][c] = true;
        return new long[]{r1, r2};
    }
}

class Solution {
    vector<int> times;
    vector<vector<pair<long long,long long>>> memo;
    vector<vector<bool>> seen;
    pair<long long,long long> rec(int i, int c) {
        if (i == (int) times.size()) return {0, 0};
        if (seen[i][c]) return memo[i][c];
        auto [a1, a2] = rec(i + 1, 3 - c);
        if (c == 1) a1 += times[i]; else a2 += times[i];
        auto [b1, b2] = rec(i + 1, c);
        if (c == 1) b2 += times[i]; else b1 += times[i];
        pair<long long,long long> res;
        if (c == 1) res = (a1 >= b1) ? make_pair(a1, a2) : make_pair(b1, b2);
        else res = (a2 >= b2) ? make_pair(a1, a2) : make_pair(b1, b2);
        seen[i][c] = true;
        return memo[i][c] = res;
    }
public:
    vector<int> maximizeSumOfProcessedTimes(vector<int>& times) {
        this->times = times;
        int n = times.size();
        memo.assign(n + 1, vector<pair<long long,long long>>(3));
        seen.assign(n + 1, vector<bool>(3, false));
        auto [s1, s2] = rec(0, 1);
        return {(int) s1, (int) s2};
    }
};

def minCost(numProjects, projectId, bid):
    best = [float('inf')] * numProjects
    for pid, b in zip(projectId, bid):
        if b < best[pid]: best[pid] = b
    if any(x == float('inf') for x in best): return -1
    return sum(best)

class Solution {
    long minCost(int numProjects, int[] projectId, int[] bid) {
        int[] best = new int[numProjects];
        Arrays.fill(best, Integer.MAX_VALUE);
        for (int i = 0; i < projectId.length; i++) {
            best[projectId[i]] = Math.min(best[projectId[i]], bid[i]);
        }
        long total = 0;
        for (int v : best) {
            if (v == Integer.MAX_VALUE) return -1;
            total += v;
        }
        return total;
    }
}

