from bisect import bisect_left

def minDeletions(arr):
    tails = []
    for x in arr:
        i = bisect_left(tails, x)
        if i == len(tails): tails.append(x)
        else: tails[i] = x
    L = len(tails)
    return max(0, len(arr) - L - 1)

class Solution {
    int minDeletions(int[] arr) {
        List<Integer> tails = new ArrayList<>();
        for (int x : arr) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int m = (lo + hi) >>> 1;
                if (tails.get(m) < x) lo = m + 1; else hi = m;
            }
            if (lo == tails.size()) tails.add(x);
            else tails.set(lo, x);
        }
        return Math.max(0, arr.length - tails.size() - 1);
    }
}

class Solution {
public:
    int minDeletions(vector<int>& arr) {
        vector<int> tails;
        for (int x : arr) {
            auto it = lower_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) tails.push_back(x);
            else *it = x;
        }
        return max(0, (int) arr.size() - (int) tails.size() - 1);
    }
};

