class Solution {
    int minimizeLengthOfLongestSubstring(String s, int k) {
        int n = s.length();
        List<Integer> runs = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            runs.add(j - i); i = j;
        }
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long flips = 0;
            for (int r : runs) flips += r / (mid + 1);
            if (flips <= k) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

