def minimizeTotalInputCost(campaignCosts, numberOfWeeks):
    n = len(campaignCosts)
    INF = float('inf')
    dp = [[INF] * (numberOfWeeks + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for j in range(1, numberOfWeeks + 1):
        for i in range(j, n + 1):
            mx = 0
            for l in range(i - 1, j - 2, -1):
                mx = max(mx, campaignCosts[l])
                if dp[l][j - 1] != INF:
                    dp[i][j] = min(dp[i][j], dp[l][j - 1] + mx)
    return dp[n][numberOfWeeks]

class Solution {
    int minimizeTotalInputCost(int[] campaignCosts, int numberOfWeeks) {
        int n = campaignCosts.length;
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[n + 1][numberOfWeeks + 1];
        for (int[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int j = 1; j <= numberOfWeeks; j++) {
            for (int i = j; i <= n; i++) {
                int mx = 0;
                for (int l = i - 1; l >= j - 1; l--) {
                    mx = Math.max(mx, campaignCosts[l]);
                    if (dp[l][j - 1] < INF) {
                        dp[i][j] = Math.min(dp[i][j], dp[l][j - 1] + mx);
                    }
                }
            }
        }
        return dp[n][numberOfWeeks];
    }
}

