def minimumDifference(measurements):
    a = sorted(measurements)
    n = len(a)
    d = min(a[i + 1] - a[i] for i in range(n - 1))
    res = []
    for i in range(n - 1):
        if a[i + 1] - a[i] == d:
            res.append(a[i]); res.append(a[i + 1])
    return res

class Solution {
    int[] minimumDifference(int[] measurements) {
        int[] a = measurements.clone();
        Arrays.sort(a);
        int n = a.length;
        int d = Integer.MAX_VALUE;
        for (int i = 0; i < n - 1; i++) d = Math.min(d, a[i + 1] - a[i]);
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if (a[i + 1] - a[i] == d) { res.add(a[i]); res.add(a[i + 1]); }
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

