        for (int i = 0; i < n - 1; ++i) d = min(d, a[i + 1] - a[i]);
        vector<int> res;
        for (int i = 0; i < n - 1; ++i) {
            if (a[i + 1] - a[i] == d) { res.push_back(a[i]); res.push_back(a[i + 1]); }
