    }
};

def planCuts(rodLengths, minLength):
    n = len(rodLengths)
    pre = [0] * (n + 1)
    for i, v in enumerate(rodLengths): pre[i + 1] = pre[i] + v
    dp = [[False] * n for _ in range(n)]
    for i in range(n): dp[i][i] = True
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            if pre[r + 1] - pre[l] < minLength: continue
            for p in range(l + 1, r + 1):
                if dp[l][p - 1] and dp[p][r]:
                    dp[l][r] = True; break
    return "Possible" if dp[0][n - 1] else "Impossible"

class Solution {
    String planCuts(int[] rodLengths, int minLength) {
        int n = rodLengths.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + rodLengths[i];
        boolean[][] dp = new boolean[n][n];
        for (int i = 0; i < n; i++) dp[i][i] = true;
        for (int length = 2; length <= n; length++) {
            for (int l = 0; l + length - 1 < n; l++) {
                int r = l + length - 1;
                if (pre[r + 1] - pre[l] < minLength) continue;
                for (int p = l + 1; p <= r; p++) {
                    if (dp[l][p - 1] && dp[p][r]) { dp[l][r] = true; break; }
                }
            }
        }
        return dp[0][n - 1] ? "Possible" : "Impossible";
    }
}

