def replaceQuestionMark(s):
    MOD = 10**9 + 7
    dp = [0] * 26
    if s[0] == '?':
        dp = [1] * 26
    else:
        dp[ord(s[0]) - ord('a')] = 1
    for i in range(1, len(s)):
        total = sum(dp) % MOD
        new_dp = [0] * 26
        if s[i] == '?':
            for c in range(26):
                new_dp[c] = (total - dp[c]) % MOD
        else:
            x = ord(s[i]) - ord('a')
            new_dp[x] = (total - dp[x]) % MOD
        dp = new_dp
    return sum(dp) % MOD

class Solution {
    int replaceQuestionMark(String s) {
        final int MOD = 1_000_000_007;
        long[] dp = new long[26];
        if (s.charAt(0) == '?') Arrays.fill(dp, 1);
        else dp[s.charAt(0) - 'a'] = 1;
        for (int i = 1; i < s.length(); i++) {
            long total = 0;
            for (long v : dp) total = (total + v) % MOD;
            long[] nd = new long[26];
            if (s.charAt(i) == '?') {
                for (int c = 0; c < 26; c++) nd[c] = (total - dp[c] + MOD) % MOD;
            } else {
                int x = s.charAt(i) - 'a';
                nd[x] = (total - dp[x] + MOD) % MOD;
            }
            dp = nd;
        }
        long ans = 0;
        for (long v : dp) ans = (ans + v) % MOD;
        return (int) ans;
    }
}

