        for (int right = 0; right < (int) s.size(); ++right) {
            cost += abs(s[right] - t[right]);
            while (cost > K) {
                cost -= abs(s[left] - t[left]);
                ++left;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

