def toolchanger(tools, startIndex, target):
    n = len(tools); ans = n
    for i, t in enumerate(tools):
        if t == target:
            diff = abs(i - startIndex)
            ans = min(ans, min(diff, n - diff))
    return ans

class Solution {
    int toolchanger(String[] tools, int startIndex, String target) {
        int n = tools.length, ans = n;
        for (int i = 0; i < n; i++) {
            if (tools[i].equals(target)) {
                int diff = Math.abs(i - startIndex);
                ans = Math.min(ans, Math.min(diff, n - diff));
            }
        }
        return ans;
    }
}

class Solution {
public:
    int toolchanger(vector<string>& tools, int startIndex, string target) {
        int n = tools.size(), ans = n;
        for (int i = 0; i < n; ++i) {
            if (tools[i] == target) {
                int diff = abs(i - startIndex);
                ans = min(ans, min(diff, n - diff));
            }
        }
        return ans;
    }
};

class Solution {
    int[] visibleTowers(int[] height) {
        int n = height.length;
        int[] rightV = new int[n], leftV = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && height[stack.peek()] < height[i]) stack.pop();
            rightV[i] = stack.isEmpty() ? (n - 1 - i) : (stack.peek() - i);
            stack.push(i);
        }
        stack.clear();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && height[stack.peek()] < height[i]) stack.pop();
            leftV[i] = stack.isEmpty() ? i : (i - stack.peek());
            stack.push(i);
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = leftV[i] + rightV[i];
        return res;
    }
}

class Solution {
public:
    vector<int> visibleTowers(vector<int>& height) {
        int n = height.size();
        vector<int> rightV(n), leftV(n);
        vector<int> stk;
        for (int i = n - 1; i >= 0; --i) {
            while (!stk.empty() && height[stk.back()] < height[i]) stk.pop_back();
            rightV[i] = stk.empty() ? (n - 1 - i) : (stk.back() - i);
            stk.push_back(i);
        }
        stk.clear();
        for (int i = 0; i < n; ++i) {
            while (!stk.empty() && height[stk.back()] < height[i]) stk.pop_back();
            leftV[i] = stk.empty() ? i : (i - stk.back());
            stk.push_back(i);
        }
        vector<int> res(n);
        for (int i = 0; i < n; ++i) res[i] = leftV[i] + rightV[i];
        return res;
    }
};

