def saddle_point(a: list[list[int]]) -> int:
    n, m = len(a), len(a[0])
    row_max_col = [max(range(m), key=lambda j: a[i][j]) for i in range(n)]
    col_min_row = [min(range(n), key=lambda i: a[i][j]) for j in range(m)]
    for i in range(n):
        j = row_max_col[i]
        if col_min_row[j] == i:
            return a[i][j]
    return -1

