import java.util.*;

class Solution {
    int[] addNumbers(int[] list1, int[] list2) {
        List<Integer> out = new ArrayList<>();
        int carry = 0, i = 0;
        while (i < list1.length || i < list2.length || carry > 0) {
            int s = carry;
            if (i < list1.length) s += list1[i];
            if (i < list2.length) s += list2[i];
            out.add(s % 10);
            carry = s / 10;
            i++;
        }
        int[] arr = new int[out.size()];
        for (int k = 0; k < out.size(); k++) arr[k] = out.get(k);
        return arr;
    }
}

class Solution {
public:
    vector<int> addNumbers(vector<int>& list1, vector<int>& list2) {
        vector<int> out;
        int carry = 0, i = 0;
        while (i < (int) list1.size() || i < (int) list2.size() || carry) {
            int s = carry;
            if (i < (int) list1.size()) s += list1[i];
            if (i < (int) list2.size()) s += list2[i];
            out.push_back(s % 10);
            carry = s / 10;
            i++;
        }
        return out;
    }
};

import java.util.*;

class Solution {
    int[] calculateMeanAndMode(int[] inputNums) {
        int n = inputNums.length;
        long sum = 0;
        for (int x : inputNums) sum += x;
        int mean = (int) (sum / n);
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : inputNums) cnt.merge(x, 1, Integer::sum);
        int maxFreq = Collections.max(cnt.values());
        int mode = Integer.MAX_VALUE;
        for (var e : cnt.entrySet()) if (e.getValue() == maxFreq) mode = Math.min(mode, e.getKey());
        return new int[]{mean, mode};
    }
}

class Solution {
public:
    vector<int> calculateMeanAndMode(vector<int>& inputNums) {
        int n = inputNums.size();
        long long sum = 0;
        for (int x : inputNums) sum += x;
        int mean = (int) (sum / n);
        unordered_map<int, int> cnt;
        for (int x : inputNums) cnt[x]++;
        int maxFreq = 0;
        for (auto& [k, v] : cnt) maxFreq = max(maxFreq, v);
        int mode = INT_MAX;
        for (auto& [k, v] : cnt) if (v == maxFreq) mode = min(mode, k);
        return {mean, mode};
    }
};

