import java.util.*;

class Solution {
    int collectCoins(int treeNodes, int[] coins, int[] tree_from, int[] tree_to) {
        int n = treeNodes;
        List<Set<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new HashSet<>());
        for (int i = 0; i < tree_from.length; i++) {
            adj.get(tree_from[i]).add(tree_to[i]);
            adj.get(tree_to[i]).add(tree_from[i]);
        }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (adj.get(i).size() == 1 && coins[i] == 0) q.offer(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            if (adj.get(u).isEmpty()) continue;
            int v = adj.get(u).iterator().next();
            adj.get(v).remove(u);
            adj.get(u).clear();
            if (adj.get(v).size() == 1 && coins[v] == 0) q.offer(v);
        }
        for (int k = 0; k < 2; k++) {
            List<Integer> leaves = new ArrayList<>();
            for (int i = 0; i < n; i++) if (adj.get(i).size() == 1) leaves.add(i);
            for (int u : leaves) {
                if (adj.get(u).isEmpty()) continue;
                int v = adj.get(u).iterator().next();
                adj.get(v).remove(u);
                adj.get(u).clear();
            }
        }
        int edges = 0;
        for (int i = 0; i < n; i++) edges += adj.get(i).size();
        return edges;  // 已经 * 2
    }
}

class Solution {
public:
    int collectCoins(int treeNodes, vector<int>& coins, vector<int>& tree_from, vector<int>& tree_to) {
        int n = treeNodes;
        vector<unordered_set<int>> adj(n);
        for (size_t i = 0; i < tree_from.size(); i++) {
            adj[tree_from[i]].insert(tree_to[i]);
            adj[tree_to[i]].insert(tree_from[i]);
        }
        queue<int> q;
        for (int i = 0; i < n; i++) if (adj[i].size() == 1 && coins[i] == 0) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (adj[u].empty()) continue;
            int v = *adj[u].begin();
            adj[v].erase(u);
            adj[u].clear();
            if (adj[v].size() == 1 && coins[v] == 0) q.push(v);
        }
        for (int k = 0; k < 2; k++) {
            vector<int> leaves;
            for (int i = 0; i < n; i++) if (adj[i].size() == 1) leaves.push_back(i);
            for (int u : leaves) {
                if (adj[u].empty()) continue;
                int v = *adj[u].begin();
                adj[v].erase(u);
                adj[u].clear();
            }
        }
        int edges = 0;
        for (int i = 0; i < n; i++) edges += adj[i].size();
        return edges;
    }
};

