def compactTheList(inputList: List[int]) -> List[str]:
    if not inputList:
        return []
    out = []
    i = 0
    n = len(inputList)
    while i < n:
        j = i
        while j + 1 < n and inputList[j + 1] == inputList[j] + 1:
            j += 1
        if j == i:
            out.append(str(inputList[i]))
        else:
            out.append(f"{inputList[i]} to {inputList[j]}")
        i = j + 1
    return out

