def countNumbersWithDigitSum(X: int, Y: int) -> int:
    cnt = 0
    for i in range(1, X + 1):
        s = 0
        x = i
        while x:
            s += x % 10
            x //= 10
        if s == Y:
            cnt += 1
    return cnt if cnt > 0 else -1

class Solution {
    int countNumbersWithDigitSum(int X, int Y) {
        int cnt = 0;
        for (int i = 1; i <= X; i++) {
            int s = 0, x = i;
            while (x > 0) { s += x % 10; x /= 10; }
            if (s == Y) cnt++;
        }
        return cnt == 0 ? -1 : cnt;
    }
}

