def createNewVersion(s: str) -> str:
    out = []
    buf = ""
    for c in s:
        if c.isalpha():
            buf += c
        else:
            d = int(c)
            if d >= 2 and buf:
                out.append(buf * d)
                buf = ""
            elif buf:
                out.append(buf)
                buf = ""
    if buf:
        out.append(buf)
    return ''.join(out)

class Solution {
    String createNewVersion(String s) {
        StringBuilder out = new StringBuilder();
        StringBuilder buf = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) buf.append(c);
            else {
                int d = c - '0';
                if (d >= 2 && buf.length() > 0) {
                    for (int i = 0; i < d; i++) out.append(buf);
                    buf.setLength(0);
                } else if (buf.length() > 0) {
                    out.append(buf);
                    buf.setLength(0);
                }
            }
        }
        if (buf.length() > 0) out.append(buf);
        return out.toString();
    }
}

class Solution {
public:
    string createNewVersion(string s) {
        string out, buf;
        for (char c : s) {
            if (isalpha((unsigned char) c)) buf += c;
            else {
                int d = c - '0';
                if (d >= 2 && !buf.empty()) {
                    for (int i = 0; i < d; i++) out += buf;
                    buf.clear();
                } else if (!buf.empty()) {
                    out += buf;
                    buf.clear();
                }
