import re

def expandGivenString(inputStr: str) -> str:
    tokens = re.findall(r'\(([^)]*)\)', inputStr)
    out = []
    for i in range(0, len(tokens), 2):
        if i + 1 < len(tokens):
            pat = tokens[i]
            n = int(tokens[i + 1])
            out.append(pat * n)
    return ''.join(out)

import java.util.*;
import java.util.regex.*;

class Solution {
    String expandGivenString(String inputStr) {
        Matcher m = Pattern.compile("\\(([^)]*)\\)").matcher(inputStr);
        List<String> toks = new ArrayList<>();
        while (m.find()) toks.add(m.group(1));
        StringBuilder out = new StringBuilder();
        for (int i = 0; i + 1 < toks.size(); i += 2) {
            int n = Integer.parseInt(toks.get(i + 1));
            for (int k = 0; k < n; k++) out.append(toks.get(i));
        }
        return out.toString();
    }
}

