from typing import List

def findCriticalNodes(pods: int, n: int, connections: List[List[int]], q: int, queries: List[List[int]]) -> List[int]:
    parent = list(range(pods + 1))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    for u, v in connections:
        union(u, v)
    # 每个连通分量的 active set
    comp_active = {}
    for i in range(1, pods + 1):
        r = find(i)
        comp_active.setdefault(r, SortedSet()).add(i)
    out = []
    for op, p in queries:
        r = find(p)
        if op == 1:
            if comp_active[r]:
                out.append(comp_active[r][0])
            else:
                out.append(-1)
        else:  # 2: 移除 p
            comp_active[r].discard(p)
    return out

import java.util.*;

class Solution {
    int[] parent;
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    int[] findCriticalNodes(int pods, int n, int[][] connections, int q, int[][] queries) {
        parent = new int[pods + 1];
        for (int i = 0; i <= pods; i++) parent[i] = i;
        for (int[] e : connections) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra != rb) parent[ra] = rb;
        }
        Map<Integer, TreeSet<Integer>> compActive = new HashMap<>();
        for (int i = 1; i <= pods; i++) {
            int r = find(i);
            compActive.computeIfAbsent(r, k -> new TreeSet<>()).add(i);
        }
        List<Integer> out = new ArrayList<>();
        for (int[] qy : queries) {
            int op = qy[0], p = qy[1];
            int r = find(p);
            if (op == 1) {
                TreeSet<Integer> s = compActive.get(r);
                out.add(s != null && !s.isEmpty() ? s.first() : -1);
            } else {
                TreeSet<Integer> s = compActive.get(r);
                if (s != null) s.remove(p);
            }
        }
        int[] arr = new int[out.size()];
        for (int i = 0; i < out.size(); i++) arr[i] = out.get(i);
        return arr;
    }
}

class Solution {
public:
    vector<int> parent;
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    vector<int> findCriticalNodes(int pods, int n, vector<vector<int>>& connections, int q, vector<vector<int>>& queries) {
        parent.resize(pods + 1);
        iota(parent.begin(), parent.end(), 0);
        for (auto& e : connections) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra != rb) parent[ra] = rb;
        }
        unordered_map<int, set<int>> compActive;
        for (int i = 1; i <= pods; i++) compActive[find(i)].insert(i);
        vector<int> out;
        for (auto& qy : queries) {
            int op = qy[0], p = qy[1];
            int r = find(p);
            if (op == 1) {
                auto it = compActive.find(r);
                if (it != compActive.end() && !it->second.empty()) out.push_back(*it->second.begin());
                else out.push_back(-1);
            } else {
                auto it = compActive.find(r);
                if (it != compActive.end()) it->second.erase(p);
            }
        }
        return out;
    }
};

