def findElementsLargestRowSmallestColumn(matrix: List[List[int]]) -> int:
    n, m = len(matrix), len(matrix[0])
    row_max = [max(row) for row in matrix]
    col_min = [min(matrix[i][j] for i in range(n)) for j in range(m)]
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == row_max[i] and matrix[i][j] == col_min[j]:
                return matrix[i][j]
    return -1

