class Solution {
    int findLastCell(int[][] matrix) {
        int n = matrix.length, m = matrix[0].length;
        boolean[][] visited = new boolean[n][m];
        int[][] dirs = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        int x = 0, y = 0, d = 0;
        int last = matrix[0][0];
        visited[0][0] = true;
        while (true) {
            int nx = x + dirs[d][0] * 2, ny = y + dirs[d][1] * 2;
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                x = nx; y = ny;
                visited[x][y] = true;
                last = matrix[x][y];
            } else {
                d = (d + 1) % 4;
                nx = x + dirs[d][0] * 2;
                ny = y + dirs[d][1] * 2;
                if (nx < 0 || nx >= n || ny < 0 || ny >= m || visited[nx][ny]) break;
                x = nx; y = ny;
                visited[x][y] = true;
                last = matrix[x][y];
            }
        }
        return last;
    }
}

