def findLongestPalindromicSubstring(inputStr: str) -> str:
    n = len(inputStr)
    best = ""
    for c in range(n):
        for (l, r) in [(c, c), (c, c + 1)]:
            while l >= 0 and r < n and inputStr[l] == inputStr[r]:
                sub = inputStr[l:r + 1]
                if len(sub) > 1:
                    if len(sub) > len(best) or (len(sub) == len(best) and sub < best):
                        best = sub
                l -= 1
                r += 1
    return best if best else "None"

class Solution {
    String findLongestPalindromicSubstring(String s) {
        int n = s.length();
        String best = "";
        for (int c = 0; c < n; c++) {
            for (int[] start : new int[][]{{c, c}, {c, c + 1}}) {
                int l = start[0], r = start[1];
                while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                    String sub = s.substring(l, r + 1);
                    if (sub.length() > 1) {
                        if (sub.length() > best.length() || (sub.length() == best.length() && sub.compareTo(best) < 0)) {
                            best = sub;
                        }
                    }
                    l--; r++;
                }
            }
        }
        return best.isEmpty() ? "None" : best;
    }
}

class Solution {
public:
    string findLongestPalindromicSubstring(string s) {
        int n = s.size();
        string best = "";
        for (int c = 0; c < n; c++) {
            for (auto& [li, ri] : vector<pair<int,int>>{{c, c}, {c, c + 1}}) {
                int l = li, r = ri;
                while (l >= 0 && r < n && s[l] == s[r]) {
                    string sub = s.substr(l, r - l + 1);
                    if (sub.size() > 1) {
                        if (sub.size() > best.size() || (sub.size() == best.size() && sub < best)) {
                            best = sub;
                        }
                    }
                    l--; r++;
                }
            }
        }
        return best.empty() ? "None" : best;
    }
};

