def findMaximumDifference(inputArray: List[int]) -> int:
    min_so_far = inputArray[0]
    best = 0
    for x in inputArray[1:]:
        if x - min_so_far > best:
            best = x - min_so_far
        if x < min_so_far:
            min_so_far = x
    return best

