class Solution {
    int findMaximumNumberDropPointsConnected(int[] x, int[] y) {
        Map<Integer, Integer> cx = new HashMap<>(), cy = new HashMap<>();
        for (int v : x) cx.merge(v, 1, Integer::sum);
        for (int v : y) cy.merge(v, 1, Integer::sum);
