    int shiftCost;
    int[] picks;
    int[] others;
    int[] destAssign;
    void tryAssign(int i, int dm) {
        // ... 实现可参考 Python
    }
    int findMinimumCostToShiftMachines(int[] machineCount, int[] finalMachineCount, int shiftingCost) {
        // 简化：n 较小直接暴力，与 Python 等价；这里给出框架
        int n = machineCount.length;
        best = Integer.MAX_VALUE;
        List<int[]> combs = new ArrayList<>();
        combinations(n, 3, 0, new int[3], 0, combs);
        for (int[] pk : combs) {
            List<Integer> oth = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                boolean in = false;
                for (int p : pk) if (p == i) { in = true; break; }
                if (!in) oth.add(i);
            }
            int K = oth.size();
            for (int mask = 0; mask < (1 << K); mask++) {
                List<Integer> destroyed = new ArrayList<>();
                for (int i = 0; i < K; i++) if ((mask & (1 << i)) != 0) destroyed.add(oth.get(i));
                tryAssignDFS(0, destroyed, pk, machineCount, finalMachineCount, shiftingCost, new int[destroyed.size()]);
            }
        }
        return best;
    }
    void combinations(int n, int k, int start, int[] cur, int depth, List<int[]> out) {
        if (depth == k) { out.add(cur.clone()); return; }
        for (int i = start; i <= n - (k - depth); i++) {
            cur[depth] = i;
            combinations(n, k, i + 1, cur, depth + 1, out);
        }
    }
    void tryAssignDFS(int i, List<Integer> destroyed, int[] picks, int[] mc, int[] fmc, int sc, int[] assign) {
        if (i == destroyed.size()) {
            int[] pmach = {mc[picks[0]], mc[picks[1]], mc[picks[2]]};
            for (int k = 0; k < destroyed.size(); k++) pmach[assign[k]] += mc[destroyed.get(k)];
            int[][] perms = {{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}};
            for (int[] perm : perms) {
                int cost = destroyed.size() * sc;
                for (int k = 0; k < 3; k++) cost += Math.abs(pmach[k] - fmc[perm[k]]);
                if (cost < best) best = cost;
            }
            return;
        }
        for (int j = 0; j < 3; j++) { assign[i] = j; tryAssignDFS(i + 1, destroyed, picks, mc, fmc, sc, assign); }
    }
}

