class Solution {
    String[] findWordsInGrid(char[][] grid, String[] words) {
        int n = grid.length, m = grid[0].length;
        String[] rows = new String[n];
        for (int i = 0; i < n; i++) rows[i] = new String(grid[i]);
        String[] cols = new String[m];
        for (int j = 0; j < m; j++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(grid[i][j]);
            cols[j] = sb.toString();
        }
        String[] out = new String[words.length];
        for (int k = 0; k < words.length; k++) {
            String w = words[k];
            boolean found = false;
            for (String s : rows) if (s.contains(w) || new StringBuilder(s).reverse().toString().contains(w)) { found = true; break; }
            if (!found) for (String s : cols) if (s.contains(w) || new StringBuilder(s).reverse().toString().contains(w)) { found = true; break; }
            out[k] = found ? "Yes" : "No";
        }
        return out;
    }
}

