        vector<string> rows(n), cols(m);
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) rows[i] += grid[i][j];
        for (int j = 0; j < m; j++) for (int i = 0; i < n; i++) cols[j] += grid[i][j];
        vector<string> out;
        for (auto& w : words) {
            bool found = false;
            for (auto& s : rows) {
                string rev(s.rbegin(), s.rend());
                if (s.find(w) != string::npos || rev.find(w) != string::npos) { found = true; break; }
            }
            if (!found) for (auto& s : cols) {
                string rev(s.rbegin(), s.rend());
                if (s.find(w) != string::npos || rev.find(w) != string::npos) { found = true; break; }
            }
            out.push_back(found ? "Yes" : "No");
        }
        return out;
    }
};

import java.util.*;

class Solution {
    int getMinServers(int server_nodes, int[] server_from, int[] server_to, int[] server_weight, int[] minActivity) {
        int n = server_nodes;
        List<int[]>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < server_from.length; i++) {
            adj[server_from[i]].add(new int[]{server_to[i], server_weight[i]});
            adj[server_to[i]].add(new int[]{server_from[i], server_weight[i]});
        }
        long[] cumW = new long[n + 1];
        int[] parent = new int[n + 1];
        parent[1] = -1;
        Deque<Integer> st = new ArrayDeque<>();
        st.push(1);
        while (!st.isEmpty()) {
            int u = st.pop();
            for (int[] e : adj[u]) {
                if (e[0] != parent[u]) {
                    parent[e[0]] = u;
                    cumW[e[0]] = cumW[u] + e[1];
                    st.push(e[0]);
                }
            }
        }
        int count = 0;
        for (int v = 2; v <= n; v++) {
            int u = parent[v];
            while (u != -1) {
                if (cumW[v] - cumW[u] > minActivity[v - 1]) { count++; break; }
                u = parent[u];
            }
        }
        return count;
    }
}

class Solution {
public:
    int getMinServers(int server_nodes, vector<int>& server_from, vector<int>& server_to, vector<int>& server_weight, vector<int>& minActivity) {
        int n = server_nodes;
        vector<vector<pair<int,int>>> adj(n + 1);
        for (size_t i = 0; i < server_from.size(); i++) {
            adj[server_from[i]].push_back({server_to[i], server_weight[i]});
            adj[server_to[i]].push_back({server_from[i], server_weight[i]});
        }
        vector<long long> cumW(n + 1, 0);
        vector<int> parent(n + 1, 0);
        parent[1] = -1;
        stack<int> st;
        st.push(1);
        while (!st.empty()) {
            int u = st.top(); st.pop();
            for (auto& [v, w] : adj[u]) {
                if (v != parent[u]) {
                    parent[v] = u;
                    cumW[v] = cumW[u] + w;
                    st.push(v);
                }
            }
        }
        int count = 0;
        for (int v = 2; v <= n; v++) {
            int u = parent[v];
            while (u != -1) {
                if (cumW[v] - cumW[u] > minActivity[v - 1]) { count++; break; }
                u = parent[u];
            }
        }
        return count;
    }
};

