def longestPalindromicSubstring(s: str) -> str:
    n = len(s)
    if n == 0: return ""
    start = end = 0
    for c in range(n):
        for (l, r) in [(c, c), (c, c + 1)]:
            while l >= 0 and r < n and s[l] == s[r]:
                if r - l > end - start:
                    start, end = l, r
                l -= 1; r += 1
    return s[start:end + 1]

class Solution {
    String longestPalindromicSubstring(String s) {
        int n = s.length();
        if (n == 0) return "";
        int start = 0, end = 0;
        for (int c = 0; c < n; c++) {
            for (int[] st : new int[][]{{c,c},{c,c+1}}) {
                int l = st[0], r = st[1];
                while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                    if (r - l > end - start) { start = l; end = r; }
                    l--; r++;
                }
            }
        }
        return s.substring(start, end + 1);
    }
}

