        self.val = val; self.next = next

def removeNodes(listHead: ListNode, x: int) -> ListNode:
    dummy = ListNode(0, listHead)
    cur = dummy
    while cur.next:
        if cur.next.val > x:
            cur.next = cur.next.next
        else:
            cur = cur.next
    return dummy.next

