import java.util.*;

class Solution {
    int waterJugProblem(int[] capacities, int[] initial, int[] target) {
        String start = Arrays.toString(initial);
        String tgt = Arrays.toString(target);
        if (start.equals(tgt)) return 0;
        Set<String> seen = new HashSet<>();
        seen.add(start);
        Deque<Object[]> q = new ArrayDeque<>();
        q.offer(new Object[]{initial.clone(), 0});
        while (!q.isEmpty()) {
            Object[] cur = q.poll();
            int[] state = (int[]) cur[0];
            int steps = (int) cur[1];
            if (Arrays.toString(state).equals(tgt)) return steps;
            for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) {
                if (i == j || state[i] == 0) continue;
                int pour = Math.min(state[i], capacities[j] - state[j]);
                if (pour == 0) continue;
                int[] ns = state.clone();
                ns[i] -= pour;
                ns[j] += pour;
                String key = Arrays.toString(ns);
                if (!seen.contains(key)) {
                    seen.add(key);
                    q.offer(new Object[]{ns, steps + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int waterJugProblem(vector<int>& capacities, vector<int>& initial, vector<int>& target) {
        if (initial == target) return 0;
        set<vector<int>> seen;
        seen.insert(initial);
        queue<pair<vector<int>, int>> q;
        q.push({initial, 0});
        while (!q.empty()) {
            auto [state, steps] = q.front(); q.pop();
            if (state == target) return steps;
            for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) {
                if (i == j || state[i] == 0) continue;
                int pour = min(state[i], capacities[j] - state[j]);
                if (pour == 0) continue;
                auto ns = state;
                ns[i] -= pour;
                ns[j] += pour;
                if (!seen.count(ns)) {
                    seen.insert(ns);
                    q.push({ns, steps + 1});
                }
            }
        }
        return -1;
    }
};

from typing import List
from collections import defaultdict

def find_optimal_resources(arr: List[int], k: int) -> int:
    n = len(arr)
    if k > n:
        return -1
    cnt = defaultdict(int)
    s = 0
    dup = 0
    best = -1
    for i, x in enumerate(arr):
        cnt[x] += 1
        if cnt[x] == 2:
            dup += 1
        s += x
        if i >= k:
            old = arr[i - k]
            if cnt[old] == 2:
                dup -= 1
            cnt[old] -= 1
            s -= old
        if i >= k - 1 and dup == 0:
            if s > best:
                best = s
    return best

import java.util.*;

class Solution {
    int findOptimalResources(int[] arr, int k) {
        int n = arr.length;
        if (k > n) return -1;
        Map<Integer, Integer> cnt = new HashMap<>();
        long s = 0;
        int dup = 0;
        long best = -1;
        for (int i = 0; i < n; i++) {
            int c = cnt.merge(arr[i], 1, Integer::sum);
            if (c == 2) dup++;
            s += arr[i];
            if (i >= k) {
                int old = arr[i - k];
                if (cnt.get(old) == 2) dup--;
                cnt.merge(old, -1, Integer::sum);
                s -= old;
            }
            if (i >= k - 1 && dup == 0 && s > best) best = s;
        }
        return (int) best;
    }
}

class Solution {
public:
    int findOptimalResources(vector<int>& arr, int k) {
        int n = arr.size();
        if (k > n) return -1;
        unordered_map<int, int> cnt;
        long long s = 0, best = -1;
        int dup = 0;
        for (int i = 0; i < n; i++) {
            if (++cnt[arr[i]] == 2) dup++;
            s += arr[i];
            if (i >= k) {
                int old = arr[i - k];
                if (cnt[old] == 2) dup--;
                if (--cnt[old] == 0) cnt.erase(old);
                s -= old;
            }
            if (i >= k - 1 && dup == 0 && s > best) best = s;
        }
        return (int) best;
    }
};

def get_substring_count(s: str) -> int:
    prev, cur = 0, 1
    ans = 0
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            cur += 1
        else:
            ans += min(prev, cur)
            prev, cur = cur, 1
    ans += min(prev, cur)
    return ans

