class Solution {
    long solution(int[] rates, int[] strategy, int k) {
        int n = rates.length;

        long[] presStrat = new long[n + 1];
        long[] presRate = new long[n + 1];
        for (int i = 0; i < n; i++) {
            presStrat[i + 1] = presStrat[i] + (long) strategy[i] * rates[i];
            presRate[i + 1] = presRate[i] + rates[i];
        }

        long base = presStrat[n];
        long best = base;
        int half = k / 2;

        for (int l = 0; l + k <= n; l++) {
            int r = l + k;
            long delta = presStrat[r] - presStrat[l];
            long sellHalf = presRate[r] - presRate[l + half];
            best = Math.max(best, base - delta + sellHalf);
        }
        return best;
    }
}

