import java.util.ArrayList;
import java.util.List;

class Solution {
    String[] solution(String[][] paragraphs, int width) {
        List<String> out = new ArrayList<>();
        StringBuilder borderSb = new StringBuilder();
        for (int i = 0; i < width + 2; i++) borderSb.append('*');
        String border = borderSb.toString();
        out.add(border);

        for (String[] para : paragraphs) {
            // Step 1: greedy line wrapping
            List<int[]> lineSpans = new ArrayList<>();
            int i = 0;
            while (i < para.length) {
                int j = i, curLen = para[j].length();
                j++;
                while (j < para.length && curLen + 1 + para[j].length() <= width) {
                    curLen += 1 + para[j].length();
                    j++;
                }
                lineSpans.add(new int[]{i, j});
                i = j;
            }

            for (int[] span : lineSpans) {
                int s = span[0], e = span[1];
                int total = 0;
                for (int k = s; k < e; k++) total += para[k].length();
                int leftover = width - total;

                StringBuilder line = new StringBuilder("*");
                if (e - s == 1) {
                    line.append(para[s]);
                    for (int k = 0; k < leftover; k++) line.append(' ');
                } else {
                    int gaps = e - s - 1;
                    int base = leftover / gaps, extra = leftover % gaps;
                    for (int k = s; k < e; k++) {
                        line.append(para[k]);
                        if (k < e - 1) {
                            int spaces = base + ((k - s) < extra ? 1 : 0);
                            for (int t = 0; t < spaces; t++) line.append(' ');
                        }
                    }
                }
                line.append('*');
                out.add(line.toString());
            }
        }
        out.add(border);
        return out.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> solution(vector<vector<string>>& paragraphs, int width) {
        vector<string> out;
        string border(width + 2, '*');
        out.push_back(border);

        for (auto& para : paragraphs) {
            // Step 1: greedy line wrapping
            vector<pair<int,int>> spans;
            int i = 0;
            while (i < (int) para.size()) {
                int j = i;
                int curLen = (int) para[j].size();
                j++;
                while (j < (int) para.size() && curLen + 1 + (int) para[j].size() <= width) {
                    curLen += 1 + (int) para[j].size();
                    j++;
                }
                spans.push_back({i, j});
                i = j;
            }

            for (auto& span : spans) {
                int s = span.first, e = span.second;
                int total = 0;
                for (int k = s; k < e; k++) total += (int) para[k].size();
                int leftover = width - total;

                string line = "*";
                if (e - s == 1) {
                    line += para[s];
                    line += string(leftover, ' ');
                } else {
                    int gaps = e - s - 1;
                    int base = leftover / gaps, extra = leftover % gaps;
                    for (int k = s; k < e; k++) {
                        line += para[k];
                        if (k < e - 1) {
                            int spaces = base + ((k - s) < extra ? 1 : 0);
                            line += string(spaces, ' ');
                        }
                    }
                }
                line += "*";
                out.push_back(line);
            }
        }
        out.push_back(border);
        return out;
    }
};

class Solution {
    long solution(int[] structures) {
        int n = structures.length;

        long cAsc = Long.MIN_VALUE, cDesc = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            cAsc = Math.max(cAsc, (long) structures[i] - i);
            cDesc = Math.max(cDesc, (long) structures[i] + i);
        }

        long opsAsc = 0, opsDesc = 0;
        for (int i = 0; i < n; i++) {
            opsAsc += (cAsc + i) - structures[i];
            opsDesc += (cDesc - i) - structures[i];
        }
        return Math.min(opsAsc, opsDesc);
    }
}

