class Solution {
    int solution(String text) {
        int n = text.length();
        if (n < 3) return 0;

        int cnt = 0;
        for (int i = 0; i < 3; i++) if (isVowel(text.charAt(i))) cnt++;
        int ans = (cnt == 2) ? 1 : 0;

        for (int i = 3; i < n; i++) {
