public:
    int solution(string text) {
        int n = (int) text.size();
        if (n < 3) return 0;
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };

        int cnt = 0;
        for (int i = 0; i < 3; i++) if (isVowel(text[i])) cnt++;
        int ans = (cnt == 2) ? 1 : 0;

        for (int i = 3; i < n; i++) {
            if (isVowel(text[i])) cnt++;
            if (isVowel(text[i - 3])) cnt--;
            if (cnt == 2) ans++;
        }
        return ans;
    }
};

class Solution {
    int solution(int t, int[] capacity, int[] recharge) {
        int n = capacity.length;
        int[] availableAt = new int[n];
        int now = 0, fullUsed = 0;

        while (now < t) {
            int idx = 0;
            for (int i = 1; i < n; i++) {
                if (availableAt[i] < availableAt[idx]) idx = i;
            }
            if (availableAt[idx] >= t) break;
            if (availableAt[idx] > now) now = availableAt[idx];
            if (now >= t) break;

            int useTime = Math.min(capacity[idx], t - now);
            now += useTime;

            if (useTime == capacity[idx]) {
                fullUsed++;
                availableAt[idx] = now + recharge[idx];
            } else {
                break;
            }
        }
        return fullUsed;
    }
}

