import java.util.HashMap;

class Solution {
    long solution(int[] fragments, long accessCode) {
        HashMap<Long, Long> freq = new HashMap<>();
        for (int f : fragments) freq.merge((long) f, 1L, Long::sum);

        String s = Long.toString(accessCode);
        long ans = 0;

        for (int k = 1; k < s.length(); k++) {
            String left = s.substring(0, k), right = s.substring(k);
            if (left.charAt(0) == '0' || right.charAt(0) == '0') continue;
            long l = Long.parseLong(left);
            long r = Long.parseLong(right);
            long cntL = freq.getOrDefault(l, 0L);
            long cntR = freq.getOrDefault(r, 0L);
            long same = (l == r) ? cntL : 0L;
            ans += cntL * cntR - same;
        }
        return ans;
    }
}

