import java.util.TreeMap;

class Solution {
    int solution(int[] heights, int viewingGap) {
        int n = heights.length;
        TreeMap<Integer, Integer> map = new TreeMap<>();
        long best = Long.MAX_VALUE;
        for (int j = viewingGap; j < n; j++) {
            int v = heights[j - viewingGap];
            map.merge(v, 1, Integer::sum);
            int h = heights[j];
            Integer hi = map.ceilingKey(h);
            Integer lo = map.floorKey(h);
            if (hi != null) best = Math.min(best, (long) hi - h);
            if (lo != null) best = Math.min(best, (long) h - lo);
        }
        return (int) best;
    }
}

