def maxGameScore(cell):
    n = len(cell)
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    primes3 = [p for p in range(3, n) if sieve[p] and p % 10 == 3]

    NEG = float('-inf')
    dp = [NEG] * n
    dp[0] = 0
    for i in range(1, n):
        best = dp[i - 1]
        for p in primes3:
            if p > i:
                break
            if dp[i - p] > best:
                best = dp[i - p]
        if best != NEG:
            dp[i] = best + cell[i]
    return dp[n - 1]

import java.util.ArrayList;
import java.util.List;

class Solution {
    int maxGameScore(int[] cell) {
        int n = cell.length;
        boolean[] sieve = new boolean[n + 1];
        for (int i = 2; i <= n; i++) sieve[i] = true;
        for (int i = 2; (long) i * i <= n; i++) {
            if (sieve[i]) {
                for (int j = i * i; j <= n; j += i) sieve[j] = false;
            }
        }
        List<Integer> primes3 = new ArrayList<>();
        for (int p = 3; p < n; p++) {
            if (sieve[p] && p % 10 == 3) primes3.add(p);
        }

        final int NEG = Integer.MIN_VALUE / 2;
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) dp[i] = NEG;
        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            int best = dp[i - 1];
            for (int p : primes3) {
                if (p > i) break;
                if (dp[i - p] > best) best = dp[i - p];
            }
            if (best != NEG) dp[i] = best + cell[i];
        }
        return dp[n - 1];
    }
}

