import sys
from collections import defaultdict

def palindromePaths(tree_nodes, tree_from, tree_to, arr, queries):
    sys.setrecursionlimit(1 << 25)
    g = [[] for _ in range(tree_nodes)]
    for u, v in zip(tree_from, tree_to):
        g[u].append(v)
        g[v].append(u)

    qs_at = defaultdict(list)
    for qi, node in enumerate(queries):
        qs_at[node].append(qi)
    ans = [0] * len(queries)
    path_cnt = defaultdict(int)

    def dfs(u, parent, mask):
        bit = 1 << (ord(arr[u]) - ord('a'))
        mask ^= bit
        path_cnt[mask] += 1
        if u in qs_at:
            total = path_cnt[mask]
            for c in range(26):
                total += path_cnt[mask ^ (1 << c)]
            for qi in qs_at[u]:
                ans[qi] = total
        for w in g[u]:
            if w != parent:
                dfs(w, u, mask)
        path_cnt[mask] -= 1

    dfs(0, -1, 0)
    return ans

import java.util.*;

class Solution {
    int[] palindromePaths(int treeNodes, int[] treeFrom, int[] treeTo,
                          char[] arr, int[] queries) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < treeNodes; i++) g.add(new ArrayList<>());
        for (int i = 0; i < treeFrom.length; i++) {
            g.get(treeFrom[i]).add(treeTo[i]);
            g.get(treeTo[i]).add(treeFrom[i]);
        }
        Map<Integer, List<Integer>> qsAt = new HashMap<>();
        for (int qi = 0; qi < queries.length; qi++) {
            qsAt.computeIfAbsent(queries[qi], k -> new ArrayList<>()).add(qi);
        }
        int[] ans = new int[queries.length];
        Map<Integer, Integer> pathCnt = new HashMap<>();

        int[] stack = new int[treeNodes + 1];
        int[] parent = new int[treeNodes];
        int[] childIter = new int[treeNodes];
        int[] maskAt = new int[treeNodes];
        Arrays.fill(parent, -2);
        parent[0] = -1;
        int top = 0;
        stack[top] = 0;
        maskAt[0] = 1 << (arr[0] - 'a');
        pathCnt.merge(maskAt[0], 1, Integer::sum);
        processQueries(0, maskAt[0], qsAt, pathCnt, ans);

        while (top >= 0) {
            int u = stack[top];
            List<Integer> nbrs = g.get(u);
            if (childIter[u] < nbrs.size()) {
                int v = nbrs.get(childIter[u]++);
                if (v == parent[u]) continue;
                parent[v] = u;
                maskAt[v] = maskAt[u] ^ (1 << (arr[v] - 'a'));
                pathCnt.merge(maskAt[v], 1, Integer::sum);
                processQueries(v, maskAt[v], qsAt, pathCnt, ans);
                stack[++top] = v;
            } else {
                pathCnt.merge(maskAt[u], -1, Integer::sum);
                top--;
            }
        }
        return ans;
    }

    void processQueries(int u, int mask, Map<Integer, List<Integer>> qsAt,
                        Map<Integer, Integer> pathCnt, int[] ans) {
        if (!qsAt.containsKey(u)) return;
        int total = pathCnt.getOrDefault(mask, 0);
        for (int c = 0; c < 26; c++) {
            total += pathCnt.getOrDefault(mask ^ (1 << c), 0);
        }
        for (int qi : qsAt.get(u)) ans[qi] = total;
    }
}

#include <unordered_map>
#include <vector>
class Solution {
public:
    vector<int> palindromePaths(int treeNodes, vector<int>& treeFrom,
                                vector<int>& treeTo, vector<char>& arr,
                                vector<int>& queries) {
        vector<vector<int>> g(treeNodes);
        for (int i = 0; i < (int) treeFrom.size(); i++) {
            g[treeFrom[i]].push_back(treeTo[i]);
            g[treeTo[i]].push_back(treeFrom[i]);
        }
        unordered_map<int, vector<int>> qsAt;
        for (int qi = 0; qi < (int) queries.size(); qi++) {
            qsAt[queries[qi]].push_back(qi);
        }
        vector<int> ans(queries.size(), 0);
        unordered_map<int, int> pathCnt;

        function<void(int, int, int)> dfs = [&](int u, int parent, int mask) {
            mask ^= 1 << (arr[u] - 'a');
            pathCnt[mask]++;
            auto it = qsAt.find(u);
            if (it != qsAt.end()) {
                int total = pathCnt[mask];
                for (int c = 0; c < 26; c++) {
                    auto f = pathCnt.find(mask ^ (1 << c));
                    if (f != pathCnt.end()) total += f->second;
                }
                for (int qi : it->second) ans[qi] = total;
            }
            for (int v : g[u]) {
                if (v != parent) dfs(v, u, mask);
            }
            if (--pathCnt[mask] == 0) pathCnt.erase(mask);
        };
        dfs(0, -1, 0);
        return ans;
    }
};

from collections import deque

def canAscend(wall, w):
    N = len(wall)
    M = len(wall[0])
    INF = float('inf')
    best = INF
    for sj in range(M):
        if wall[N - 1][sj] != 'x': continue
        # state: (row, col, horiz_count)
        dist = {}
        dq = deque()
        start = (N - 1, sj, 0)
        dist[start] = 0
        dq.append(start)
        while dq:
            r, c, hc = dq.popleft()
            if r == 0:
                if dist[(r, c, hc)] < best: best = dist[(r, c, hc)]
                continue
            d = dist[(r, c, hc)]
            # 水平：只在同一行
            if hc < 2:
                for nc in range(M):
                    if nc == c or wall[r][nc] != 'x': continue
                    if (r - r) ** 2 + (nc - c) ** 2 <= w * w:
                        st = (r, nc, hc + 1)
                        if st not in dist:
                            dist[st] = d + 1
                            dq.append(st)
            # 向上跳到 < r 的任意行
            for nr in range(r):
                for nc in range(M):
                    if wall[nr][nc] != 'x': continue
                    if (r - nr) ** 2 + (nc - c) ** 2 <= w * w:
                        st = (nr, nc, 0)
                        if st not in dist:
                            dist[st] = d + 1
                            dq.append(st)
    return best if best < INF else -1

class Solution {
    int canAscend(String[][] wall, int w) {
        int N = wall.length, M = wall[0].length;
        int best = Integer.MAX_VALUE;
        for (int sj = 0; sj < M; sj++) {
            if (!wall[N-1][sj].equals("x")) continue;
            java.util.HashMap<Long, Integer> dist = new java.util.HashMap<>();
            java.util.ArrayDeque<long[]> q = new java.util.ArrayDeque<>();
            long start = ((long)(N-1) << 32) | ((long)sj << 4);
            dist.put(start, 0);
            q.add(new long[]{N-1, sj, 0});
            while (!q.isEmpty()) {
                long[] s = q.poll();
                int r = (int) s[0], c = (int) s[1], hc = (int) s[2];
                int d = dist.get(((long)r << 32) | ((long)c << 4) | hc);
                if (r == 0) { best = Math.min(best, d); continue; }
                if (hc < 2) {
                    for (int nc = 0; nc < M; nc++) {
                        if (nc == c || !wall[r][nc].equals("x")) continue;
                        if ((long)(nc-c)*(nc-c) <= (long)w*w) {
                            long ks = ((long)r << 32) | ((long)nc << 4) | (hc+1);
                            if (!dist.containsKey(ks)) { dist.put(ks, d+1); q.add(new long[]{r, nc, hc+1}); }
                        }
                    }
                }
                for (int nr = 0; nr < r; nr++)
                    for (int nc = 0; nc < M; nc++) {
                        if (!wall[nr][nc].equals("x")) continue;
                        if ((long)(r-nr)*(r-nr) + (long)(nc-c)*(nc-c) <= (long)w*w) {
                            long ks = ((long)nr << 32) | ((long)nc << 4);
                            if (!dist.containsKey(ks)) { dist.put(ks, d+1); q.add(new long[]{nr, nc, 0}); }
                        }
                    }
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

class Solution {
public:
    int canAscend(vector<vector<string>>& wall, int w) {
        int N = wall.size(), M = wall[0].size();
        int best = INT_MAX;
        for (int sj = 0; sj < M; sj++) {
            if (wall[N-1][sj] != "x") continue;
            map<tuple<int,int,int>, int> dist;
            queue<tuple<int,int,int>> q;
            dist[{N-1, sj, 0}] = 0;
            q.push({N-1, sj, 0});
            while (!q.empty()) {
                auto [r, c, hc] = q.front(); q.pop();
                int d = dist[{r, c, hc}];
                if (r == 0) { best = min(best, d); continue; }
                if (hc < 2) for (int nc = 0; nc < M; nc++) {
                    if (nc == c || wall[r][nc] != "x") continue;
                    if ((long long)(nc-c)*(nc-c) <= (long long)w*w) {
                        if (!dist.count({r, nc, hc+1})) { dist[{r, nc, hc+1}] = d+1; q.push({r, nc, hc+1}); }
                    }
                }
                for (int nr = 0; nr < r; nr++) for (int nc = 0; nc < M; nc++) {
                    if (wall[nr][nc] != "x") continue;
                    if ((long long)(r-nr)*(r-nr) + (long long)(nc-c)*(nc-c) <= (long long)w*w) {
                        if (!dist.count({nr, nc, 0})) { dist[{nr, nc, 0}] = d+1; q.push({nr, nc, 0}); }
                    }
                }
            }
        }
        return best == INT_MAX ? -1 : best;
    }
};

def balancedPrefixSetsMask(p):
    n = len(p)
    pos = [0] * (n + 1)
    for i, v in enumerate(p):
        pos[v] = i
    mn = float('inf')
    mx = -1
    out = []
    for k in range(1, n + 1):
        mn = min(mn, pos[k])
        mx = max(mx, pos[k])
        out.append('1' if mx - mn + 1 == k else '0')
    return ''.join(out)

class Solution {
    String balancedPrefixSetsMask(int[] p) {
        int n = p.length;
        int[] pos = new int[n + 1];
        for (int i = 0; i < n; i++) pos[p[i]] = i;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= n; k++) {
            mn = Math.min(mn, pos[k]);
            mx = Math.max(mx, pos[k]);
            sb.append(mx - mn + 1 == k ? '1' : '0');
        }
        return sb.toString();
    }
}

class Solution {
public:
    string balancedPrefixSetsMask(vector<int>& p) {
        int n = p.size();
        vector<int> pos(n + 1);
        for (int i = 0; i < n; i++) pos[p[i]] = i;
        int mn = INT_MAX, mx = INT_MIN;
        string out;
        for (int k = 1; k <= n; k++) {
            mn = min(mn, pos[k]);
            mx = max(mx, pos[k]);
            out += (mx - mn + 1 == k ? '1' : '0');
        }
        return out;
    }
};

class Solution {
    int[] values;
    int[][] children;
    long best;
    java.util.List<Integer> bestPath;
    Object[] dfs(int u) {
        int v = values[u];
        int L = children[u][0], R = children[u][1];
        long lSum = 0; java.util.List<Integer> lPath = new java.util.ArrayList<>();
        long rSum = 0; java.util.List<Integer> rPath = new java.util.ArrayList<>();
        if (L != -1) { Object[] o = dfs(L); lSum = (long) o[0]; lPath = (java.util.List<Integer>) o[1]; }
        if (R != -1) { Object[] o = dfs(R); rSum = (long) o[0]; rPath = (java.util.List<Integer>) o[1]; }
        if (lSum < 0) { lSum = 0; lPath = new java.util.ArrayList<>(); }
        if (rSum < 0) { rSum = 0; rPath = new java.util.ArrayList<>(); }
        long through = v + lSum + rSum;
        if (through > best) {
            best = through;
            java.util.List<Integer> p = new java.util.ArrayList<>();
            for (int i = lPath.size() - 1; i >= 0; i--) p.add(lPath.get(i));
            p.add(v);
            p.addAll(rPath);
            bestPath = p;
        }
        if (lSum >= rSum) {
            java.util.List<Integer> p = new java.util.ArrayList<>();
            p.add(v); p.addAll(lPath);
            return new Object[]{v + lSum, p};
        } else {
            java.util.List<Integer> p = new java.util.ArrayList<>();
            p.add(v); p.addAll(rPath);
            return new Object[]{v + rSum, p};
        }
    }
    String[] binaryTreeSubtreeSumPath(int[] values, int[][] children) {
        this.values = values; this.children = children;
        long total = 0;
        for (int x : values) total += x;
        best = Long.MIN_VALUE;
        bestPath = new java.util.ArrayList<>();
        dfs(0);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bestPath.size(); i++) { if (i > 0) sb.append(' '); sb.append(bestPath.get(i)); }
        return new String[]{String.valueOf(total), String.valueOf(best), sb.toString()};
    }
}

class Solution {
public:
    vector<int> values;
    vector<vector<int>> children;
    long long best;
    vector<int> bestPath;
    pair<long long, vector<int>> dfs(int u) {
        int v = values[u];
        long long lSum = 0, rSum = 0;
        vector<int> lPath, rPath;
        int L = children[u][0], R = children[u][1];
        if (L != -1) { auto p = dfs(L); lSum = p.first; lPath = p.second; }
        if (R != -1) { auto p = dfs(R); rSum = p.first; rPath = p.second; }
        if (lSum < 0) { lSum = 0; lPath.clear(); }
        if (rSum < 0) { rSum = 0; rPath.clear(); }
        long long through = v + lSum + rSum;
        if (through > best) {
            best = through;
            bestPath.clear();
            for (auto it = lPath.rbegin(); it != lPath.rend(); ++it) bestPath.push_back(*it);
            bestPath.push_back(v);
            for (int x : rPath) bestPath.push_back(x);
        }
        vector<int> p = {v};
        if (lSum >= rSum) { for (int x : lPath) p.push_back(x); return {v + lSum, p}; }
        else { for (int x : rPath) p.push_back(x); return {v + rSum, p}; }
    }
    vector<string> binaryTreeSubtreeSumPath(vector<int>& vals, vector<vector<int>>& ch) {
