class Solution {
    int minimumShuttleCost(int[] passengers, int[][] edges) {
        int n = passengers.length;
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new java.util.ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        boolean any = false;
        for (int p : passengers) if (p == 1) { any = true; break; }
        if (!any) return 0;
        int best = Integer.MAX_VALUE;
        for (int u = 0; u < n; u++) {
            int[] dist = new int[n], par = new int[n];
            java.util.Arrays.fill(dist, -1); java.util.Arrays.fill(par, -1);
            dist[u] = 0;
            java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
            q.add(u);
            while (!q.isEmpty()) {
                int x = q.poll();
                for (int y : adj.get(x)) if (dist[y] < 0) { dist[y] = dist[x] + 1; par[y] = x; q.add(y); }
            }
            java.util.HashSet<Integer> keep = new java.util.HashSet<>();
            keep.add(u);
            for (int p = 0; p < n; p++) if (passengers[p] == 1) {
                int cur = p;
                for (int t = 0; t < 2 && par[cur] != -1 && cur != u; t++) cur = par[cur];
                while (cur != -1) { keep.add(cur); cur = par[cur]; }
            }
            best = Math.min(best, 2 * (keep.size() - 1));
        }
        return best;
    }
}

