class Solution {
    String[] solveConvexFunctionMinimization(String input) {
        String[] lines = input.strip().split("\n");
        int q = Integer.parseInt(lines[0]);
        String[] out = new String[q];
        for (int i = 1; i <= q; i++) {
            String[] p = lines[i].split("\\s+");
            double A = Double.parseDouble(p[0]), B = Double.parseDouble(p[1]);
            double lo = Double.parseDouble(p[3]), hi = Double.parseDouble(p[4]);
            double x = -B / (2 * A);
            if (x < lo) x = lo; if (x > hi) x = hi;
            out[i - 1] = String.format("%.6f", x);
        }
        return out;
    }
}

class Solution {
public:
    vector<string> solveConvexFunctionMinimization(string input) {
        stringstream ss(input);
        int q; ss >> q;
        vector<string> out;
        for (int i = 0; i < q; i++) {
            double A, B, C, lo, hi;
            ss >> A >> B >> C >> lo >> hi;
            double x = -B / (2 * A);
            if (x < lo) x = lo; if (x > hi) x = hi;
            char buf[32];
            snprintf(buf, sizeof(buf), "%.6f", x);
            out.push_back(buf);
        }
        return out;
    }
};

