def countLShapes(row, col, magicNumber, mod):
    grid = [[((i + j * magicNumber) % mod) % 2 for j in range(col)] for i in range(row)]
    rowCnt = [sum(g) for g in grid]
    colCnt = [sum(grid[i][j] for i in range(row)) for j in range(col)]
    total = 0
    for i in range(row):
        for j in range(col):
            if grid[i][j] == 1:
                total += (rowCnt[i] - 1) * (colCnt[j] - 1)
    return total

