def countRoutes(grid, w):
    MOD = 998244353
    n = len(grid)
    m = len(grid[0])
    w2 = w * w
    def nodes_in_row(r):
        return [j for j in range(m) if grid[r][j] == 'X']
    def row_subsets(r):
        nodes = nodes_in_row(r)
        subs = []
        for j in nodes:
            subs.append([j])  # 单点
        for i, a in enumerate(nodes):
            for b in nodes[i+1:]:
                if abs(a - b) ** 2 <= w2:
                    subs.append([a, b])
                    subs.append([b, a])
        return subs
    # dp[r][(last_node, subset_tuple)] = count
    # 起始：r = n-1（底行），任意 subset；每子集 [first, ..., last]
    cur = {}
    for sub in row_subsets(n - 1):
        cur[(sub[-1], tuple(sorted(sub)))] = cur.get((sub[-1], tuple(sorted(sub))), 0) + 1
    for r in range(n - 2, -1, -1):
        nxt = {}
        for sub in row_subsets(r):
            first = sub[0]
            sub_t = tuple(sorted(sub))
            for (last, _), c in cur.items():
                d2 = (r - (r + 1)) ** 2 + (first - last) ** 2
                if d2 <= w2:
                    key = (sub[-1], sub_t)
                    nxt[key] = (nxt.get(key, 0) + c) % MOD
        cur = nxt
    return sum(cur.values()) % MOD

class Solution {
    int countRoutes(char[][] grid, int w) {
        final int MOD = 998244353;
        int n = grid.length, m = grid[0].length, w2 = w * w;
        java.util.HashMap<Long, Long> cur = new java.util.HashMap<>();
        for (int[] sub : rowSubsets(grid, n - 1, w2)) {
            long key = encode(sub[sub.length - 1], sub);
            cur.merge(key, 1L, Long::sum);
        }
        for (int r = n - 2; r >= 0; r--) {
            java.util.HashMap<Long, Long> nxt = new java.util.HashMap<>();
            int[][] subs = rowSubsets(grid, r, w2);
            for (int[] sub : subs) {
                int first = sub[0];
                long subKey = subsetKey(sub);
                for (var e : cur.entrySet()) {
                    int last = (int)(e.getKey() >>> 32);
                    int dx = 1, dy = first - last;
                    if (dx * dx + dy * dy <= w2) {
                        long k = ((long)sub[sub.length - 1] << 32) | subKey;
                        nxt.merge(k, e.getValue(), (a, b) -> (a + b) % MOD);
                    }
                }
            }
            cur = nxt;
        }
        long s = 0;
        for (long c : cur.values()) s = (s + c) % MOD;
        return (int) s;
    }
    long subsetKey(int[] sub) {
        int[] s = sub.clone();
        java.util.Arrays.sort(s);
        long k = 0;
        for (int x : s) k = k * 31 + x;
        return k & 0x7FFFFFFFL;
    }
    long encode(int last, int[] sub) {
        return ((long) last << 32) | subsetKey(sub);
    }
    int[][] rowSubsets(char[][] grid, int r, int w2) {
        java.util.List<int[]> res = new java.util.ArrayList<>();
        java.util.List<Integer> nodes = new java.util.ArrayList<>();
        for (int j = 0; j < grid[r].length; j++) if (grid[r][j] == 'X') nodes.add(j);
        for (int j : nodes) res.add(new int[]{j});
        for (int i = 0; i < nodes.size(); i++)
            for (int j = i + 1; j < nodes.size(); j++) {
                int a = nodes.get(i), b = nodes.get(j);
                if ((a - b) * (a - b) <= w2) {
                    res.add(new int[]{a, b});
                    res.add(new int[]{b, a});
                }
            }
        return res.toArray(new int[0][]);
    }
}

class Solution {
public:
    int countRoutes(vector<vector<char>>& grid, int w) {
        const int MOD = 998244353;
        int n = grid.size(), m = grid[0].size(), w2 = w * w;
        auto subsets = [&](int r) {
            vector<vector<int>> res;
            vector<int> nodes;
            for (int j = 0; j < m; j++) if (grid[r][j] == 'X') nodes.push_back(j);
            for (int j : nodes) res.push_back({j});
            for (size_t i = 0; i < nodes.size(); i++)
                for (size_t j = i + 1; j < nodes.size(); j++)
                    if ((nodes[i] - nodes[j]) * (nodes[i] - nodes[j]) <= w2) {
                        res.push_back({nodes[i], nodes[j]});
                        res.push_back({nodes[j], nodes[i]});
                    }
            return res;
        };
        auto subKey = [](vector<int> s) {
            sort(s.begin(), s.end());
            long long k = 0;
            for (int x : s) k = k * 31 + x;
            return k;
        };
        map<pair<int,long long>, long long> cur;
        for (auto& sub : subsets(n - 1)) cur[{sub.back(), subKey(sub)}]++;
        for (int r = n - 2; r >= 0; r--) {
            map<pair<int,long long>, long long> nxt;
            for (auto& sub : subsets(r)) {
                int first = sub.front(), last = sub.back();
                long long sk = subKey(sub);
                for (auto& [k, v] : cur) {
                    int prevLast = k.first;
                    int dx = 1, dy = first - prevLast;
                    if (dx * dx + dy * dy <= w2)
                        nxt[{last, sk}] = (nxt[{last, sk}] + v) % MOD;
                }
            }
            cur = nxt;
        }
        long long s = 0;
        for (auto& [k, v] : cur) s = (s + v) % MOD;
        return (int) s;
    }
};

class Solution {
    long countGoodSubarrays(int[] nums, int k) {
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        long pairs = 0, res = 0;
        int l = 0;
        for (int r = 0; r < nums.length; r++) {
            int c = cnt.getOrDefault(nums[r], 0);
            pairs += c;
            cnt.put(nums[r], c + 1);
            while (pairs >= k) {
                int cl = cnt.get(nums[l]) - 1;
                cnt.put(nums[l], cl);
                pairs -= cl;
                l++;
            }
            res += l;
        }
        return res;
    }
}

class Solution {
public:
    long long countGoodSubarrays(vector<int>& nums, int k) {
        unordered_map<int, int> cnt;
        long long pairs = 0, res = 0;
        int l = 0;
        for (size_t r = 0; r < nums.size(); r++) {
            pairs += cnt[nums[r]];
            cnt[nums[r]]++;
            while (pairs >= k) {
                cnt[nums[l]]--;
                pairs -= cnt[nums[l]];
                l++;
            }
            res += l;
        }
        return res;
    }
};

class Solution {
    long[] countWaysToReachSum(int[] a, int[] b, int[][] queries) {
        int[] bb = b.clone();
        java.util.HashMap<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int v : bb) cnt.merge(v, 1, Integer::sum);
        java.util.List<Long> res = new java.util.ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 0) {
                int i = q[1], x = q[2];
                if (cnt.merge(bb[i], -1, Integer::sum) == 0) cnt.remove(bb[i]);
                bb[i] += x;
                cnt.merge(bb[i], 1, Integer::sum);
            } else {
                int x = q[1];
                long total = 0;
                for (int v : a) total += cnt.getOrDefault(x - v, 0);
                res.add(total);
            }
        }
        long[] arr = new long[res.size()];
        for (int i = 0; i < res.size(); i++) arr[i] = res.get(i);
        return arr;
    }
}

class Solution {
public:
    vector<long long> countWaysToReachSum(vector<int>& a, vector<int>& b, vector<vector<int>>& queries) {
        vector<long long> bb(b.begin(), b.end());
        unordered_map<long long, long long> cnt;
        for (long long v : bb) cnt[v]++;
        vector<long long> res;
        for (auto& q : queries) {
            if (q[0] == 0) {
                int i = q[1], x = q[2];
                if (--cnt[bb[i]] == 0) cnt.erase(bb[i]);
                bb[i] += x;
                cnt[bb[i]]++;
            } else {
                long long x = q[1], total = 0;
                for (int v : a) {
                    auto it = cnt.find(x - v);
                    if (it != cnt.end()) total += it->second;
                }
                res.push_back(total);
            }
        }
        return res;
    }
};

class Solution {
    int[] countingSegmentsAfterRemovals(int[] houses, int[] queries) {
        java.util.TreeSet<Integer> s = new java.util.TreeSet<>();
        for (int h : houses) s.add(h);
        int segs = 0;
        Integer prev = null;
        for (int h : s) {
            if (prev == null || h - prev != 1) segs++;
            prev = h;
        }
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int p = queries[i];
            if (!s.contains(p)) { res[i] = segs; continue; }
            boolean left = s.contains(p - 1), right = s.contains(p + 1);
            s.remove(p);
            if (left && right) segs++;
            else if (!left && !right) segs--;
            res[i] = segs;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> countingSegmentsAfterRemovals(vector<int>& houses, vector<int>& queries) {
        set<int> s(houses.begin(), houses.end());
        int segs = 0;
        int prev = INT_MIN;
        bool first = true;
        for (int h : s) {
            if (first || h - prev != 1) segs++;
            prev = h; first = false;
        }
        vector<int> res(queries.size());
        for (size_t i = 0; i < queries.size(); i++) {
            int p = queries[i];
            if (!s.count(p)) { res[i] = segs; continue; }
            bool left = s.count(p - 1), right = s.count(p + 1);
            s.erase(p);
            if (left && right) segs++;
            else if (!left && !right) segs--;
            res[i] = segs;
        }
        return res;
    }
};

class Solution {
    int defuseBombs(int[][] bombInfo) {
        int[][] a = bombInfo.clone();
        java.util.Arrays.sort(a, (p, q) -> Integer.compare(p[1], q[1]));
        long t = 0;
        for (int[] b : a) {
            t += b[0];
            if (t > b[1]) return -1;
        }
        return (int) t;
    }
}

class Solution {
public:
    int defuseBombs(vector<vector<int>>& bombInfo) {
        vector<vector<int>> a = bombInfo;
        sort(a.begin(), a.end(), [](auto& p, auto& q){ return p[1] < q[1]; });
        long long t = 0;
        for (auto& b : a) {
            t += b[0];
            if (t > b[1]) return -1;
        }
        return (int) t;
    }
};

def earliestFullConnection(users, logs):
    name_to_idx = {u: i for i, u in enumerate(users)}
    n = len(users)
    par = list(range(n))
    def find(u):
        while par[u] != u:
            par[u] = par[par[u]]; u = par[u]
        return u
    parsed = []
    for log in logs:
        parts = log.split()
        t = int(parts[0])
        a, b = name_to_idx[parts[1]], name_to_idx[parts[2]]
        parsed.append((t, a, b))
    parsed.sort()
    comp = n
    for t, a, b in parsed:
        ra, rb = find(a), find(b)
        if ra != rb:
            par[ra] = rb
            comp -= 1
            if comp == 1:
                return t
    return -1

class Solution {
    int[] par;
    int find(int u) { while (par[u] != u) { par[u] = par[par[u]]; u = par[u]; } return u; }
    int earliestFullConnection(String[] users, String[] logs) {
        java.util.HashMap<String, Integer> idx = new java.util.HashMap<>();
        for (int i = 0; i < users.length; i++) idx.put(users[i], i);
        int n = users.length;
        par = new int[n];
        for (int i = 0; i < n; i++) par[i] = i;
        int[][] parsed = new int[logs.length][3];
        for (int i = 0; i < logs.length; i++) {
            String[] p = logs[i].split(" ");
            parsed[i] = new int[]{Integer.parseInt(p[0]), idx.get(p[1]), idx.get(p[2])};
        }
        java.util.Arrays.sort(parsed, (a, b) -> Integer.compare(a[0], b[0]));
        int comp = n;
        for (int[] e : parsed) {
            int ra = find(e[1]), rb = find(e[2]);
            if (ra != rb) { par[ra] = rb; comp--; if (comp == 1) return e[0]; }
        }
        return -1;
    }
}

