def efficientBatching(rides):
    # rides[i] = "id, location, time"
    def to_min(s):
        h, m = s.split(":")
        return int(h) * 60 + int(m)
    parsed = []
    for i, r in enumerate(rides):
        parts = [p.strip() for p in r.split(",")]
        parsed.append((int(parts[0]), parts[1], to_min(parts[2]), i))
    # 按 (location, time) 分组
    groups = {}
    for rid, loc, tm, idx in parsed:
        groups.setdefault(loc, []).append((tm, rid, idx))
    batches = []
    for loc, items in groups.items():
        items.sort()
        i = 0
        while i < len(items):
            cur = [items[i]]
            j = i + 1
            while j < len(items) and len(cur) < 3 and items[j][0] - items[i][0] <= 10:
                cur.append(items[j])
                j += 1
            batches.append((min(x[2] for x in cur), sorted(x[1] for x in cur)))
            i = j
    batches.sort()
    return [b[1] for b in batches]

class Solution {
    java.util.List<java.util.List<Integer>> efficientBatching(String[] rides) {
        int n = rides.length;
        java.util.HashMap<String, java.util.List<int[]>> groups = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            String[] p = rides[i].split(",");
            int rid = Integer.parseInt(p[0].trim());
            String loc = p[1].trim();
            String[] hm = p[2].trim().split(":");
            int tm = Integer.parseInt(hm[0]) * 60 + Integer.parseInt(hm[1]);
            groups.computeIfAbsent(loc, k -> new java.util.ArrayList<>()).add(new int[]{tm, rid, i});
        }
        java.util.List<int[]> batchHeaders = new java.util.ArrayList<>();
        java.util.List<java.util.List<Integer>> batchIds = new java.util.ArrayList<>();
        for (var e : groups.entrySet()) {
            java.util.List<int[]> items = e.getValue();
            items.sort((a, b) -> Integer.compare(a[0], b[0]));
            int i = 0;
            while (i < items.size()) {
                java.util.List<int[]> cur = new java.util.ArrayList<>();
                cur.add(items.get(i));
                int j = i + 1;
                while (j < items.size() && cur.size() < 3 && items.get(j)[0] - items.get(i)[0] <= 10) {
                    cur.add(items.get(j)); j++;
                }
                int minIdx = Integer.MAX_VALUE;
                java.util.List<Integer> ids = new java.util.ArrayList<>();
                for (int[] x : cur) { minIdx = Math.min(minIdx, x[2]); ids.add(x[1]); }
                java.util.Collections.sort(ids);
                batchHeaders.add(new int[]{minIdx, batchIds.size()});
                batchIds.add(ids);
                i = j;
            }
        }
        batchHeaders.sort((a, b) -> Integer.compare(a[0], b[0]));
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        for (int[] h : batchHeaders) res.add(batchIds.get(h[1]));
        return res;
    }
}

class Solution {
public:
    vector<vector<int>> efficientBatching(vector<string>& rides) {
        unordered_map<string, vector<array<int,3>>> groups;
        for (size_t i = 0; i < rides.size(); i++) {
            stringstream ss(rides[i]);
            string id, loc, tm;
            getline(ss, id, ','); getline(ss, loc, ','); getline(ss, tm);
            auto trim = [](string& s) { while (!s.empty() && s.front() == ' ') s.erase(s.begin()); while (!s.empty() && s.back() == ' ') s.pop_back(); };
            trim(id); trim(loc); trim(tm);
            int colon = tm.find(':');
            int t = stoi(tm.substr(0, colon)) * 60 + stoi(tm.substr(colon + 1));
            groups[loc].push_back({t, stoi(id), (int)i});
        }
        vector<pair<int, vector<int>>> batches;
        for (auto& [loc, items] : groups) {
            sort(items.begin(), items.end());
            int i = 0;
            while (i < (int)items.size()) {
                vector<array<int,3>> cur = {items[i]};
                int j = i + 1;
                while (j < (int)items.size() && cur.size() < 3 && items[j][0] - items[i][0] <= 10) {
                    cur.push_back(items[j]); j++;
                }
                int minIdx = INT_MAX;
                vector<int> ids;
                for (auto& x : cur) { minIdx = min(minIdx, x[2]); ids.push_back(x[1]); }
                sort(ids.begin(), ids.end());
                batches.push_back({minIdx, ids});
                i = j;
            }
        }
        sort(batches.begin(), batches.end());
        vector<vector<int>> res;
        for (auto& [_, ids] : batches) res.push_back(ids);
        return res;
    }
};

class Solution {
    int[] farthestSeatAssignment(int n, int count) {
        if (count == 0) return new int[0];
        java.util.List<Integer> res = new java.util.ArrayList<>();
        res.add(0);
        if (count == 1 || n == 1) return res.stream().mapToInt(Integer::intValue).toArray();
        res.add(n - 1);
        if (count == 2 || n == 2) return res.stream().mapToInt(Integer::intValue).toArray();
        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) -> {
            int dA = (a[1] - a[0]) / 2, dB = (b[1] - b[0]) / 2;
            if (dA != dB) return Integer.compare(dB, dA);
            return Integer.compare(a[0], b[0]);
        });
        if (n - 1 > 1) heap.add(new int[]{0, n - 1});
        while (res.size() < count && !heap.isEmpty()) {
            int[] s = heap.poll();
            int l = s[0], r = s[1];
            int mid = l + (r - l) / 2;
            res.add(mid);
            if (mid - l > 1) heap.add(new int[]{l, mid});
            if (r - mid > 1) heap.add(new int[]{mid, r});
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> farthestSeatAssignment(int n, int count) {
        if (count == 0) return {};
        vector<int> res = {0};
        if (count == 1 || n == 1) return res;
        res.push_back(n - 1);
        if (count == 2 || n == 2) return res;
        auto cmp = [](const pair<int,int>& a, const pair<int,int>& b) {
            int dA = (a.second - a.first) / 2, dB = (b.second - b.first) / 2;
            if (dA != dB) return dA < dB;
            return a.first > b.first;
        };
        priority_queue<pair<int,int>, vector<pair<int,int>>, decltype(cmp)> heap(cmp);
        if (n - 1 > 1) heap.push({0, n - 1});
        while ((int)res.size() < count && !heap.empty()) {
            auto [l, r] = heap.top(); heap.pop();
            int mid = l + (r - l) / 2;
            res.push_back(mid);
            if (mid - l > 1) heap.push({l, mid});
            if (r - mid > 1) heap.push({mid, r});
        }
        return res;
    }
};

def findLengthOfLongestCommonPrefix(arr1, arr2):
    pre = set()
    for x in arr1:
        s = str(x)
        for i in range(1, len(s) + 1):
            pre.add(s[:i])
    best = 0
    for x in arr2:
        s = str(x)
        for i in range(1, len(s) + 1):
            if s[:i] in pre:
                if i > best: best = i
            else:
                break
    return best

class Solution {
    int findLengthOfLongestCommonPrefix(int[] arr1, int[] arr2) {
        java.util.HashSet<String> pre = new java.util.HashSet<>();
        for (int x : arr1) {
            String s = String.valueOf(x);
            for (int i = 1; i <= s.length(); i++) pre.add(s.substring(0, i));
        }
        int best = 0;
        for (int x : arr2) {
            String s = String.valueOf(x);
            for (int i = 1; i <= s.length(); i++) {
                if (pre.contains(s.substring(0, i))) { if (i > best) best = i; }
                else break;
            }
        }
        return best;
    }
}

