    }
};

class Solution {
    int findMaximumLengthSubarray(int[] a, long k) {
        int n = a.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            boolean ok = true;
            for (int i = 0; i + mid <= n; i++) {
                if (pre[i + mid] - pre[i] >= k) { ok = false; break; }
            }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

