class Solution {
    int[] findTopTwoTeams(int[] wins, int[] draws, int[] scored, int[] conceded) {
        int n = wins.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> {
            int pa = 3 * wins[a] + draws[a], pb = 3 * wins[b] + draws[b];
            if (pa != pb) return Integer.compare(pb, pa);
            int da = scored[a] - conceded[a], db = scored[b] - conceded[b];
            return Integer.compare(db, da);
        });
        return new int[]{idx[0], idx[1]};
    }
}

class Solution {
public:
    vector<int> findTopTwoTeams(vector<int>& wins, vector<int>& draws, vector<int>& scored, vector<int>& conceded) {
        int n = wins.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){
            int pa = 3*wins[a] + draws[a], pb = 3*wins[b] + draws[b];
            if (pa != pb) return pa > pb;
            return (scored[a] - conceded[a]) > (scored[b] - conceded[b]);
        });
        return {idx[0], idx[1]};
    }
};

from collections import OrderedDict

def processFirstUniqueIpCommands(commands):
    cnt = {}
    unique_order = OrderedDict()  # ip -> True
    res = []
    for cmd in commands:
        if cmd.startswith("ADD"):
            ip = cmd[4:]
            cnt[ip] = cnt.get(ip, 0) + 1
            if cnt[ip] == 1:
                unique_order[ip] = True
            elif cnt[ip] == 2:
                unique_order.pop(ip, None)
        else:  # FIRST_UNIQUE
            if unique_order:
                res.append(next(iter(unique_order)))
            else:
                res.append("")
    return res

class Solution {
    String[] processFirstUniqueIpCommands(String[] commands) {
        java.util.HashMap<String, Integer> cnt = new java.util.HashMap<>();
        java.util.LinkedHashSet<String> uniq = new java.util.LinkedHashSet<>();
        java.util.List<String> res = new java.util.ArrayList<>();
        for (String cmd : commands) {
            if (cmd.startsWith("ADD")) {
                String ip = cmd.substring(4);
                int c = cnt.merge(ip, 1, Integer::sum);
                if (c == 1) uniq.add(ip);
                else if (c == 2) uniq.remove(ip);
            } else {
                res.add(uniq.isEmpty() ? "" : uniq.iterator().next());
            }
        }
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> processFirstUniqueIpCommands(vector<string>& commands) {
        unordered_map<string, int> cnt;
        list<string> uniq;
        unordered_map<string, list<string>::iterator> pos;
        vector<string> res;
        for (auto& cmd : commands) {
            if (cmd.rfind("ADD", 0) == 0) {
                string ip = cmd.substr(4);
                int c = ++cnt[ip];
                if (c == 1) {
                    uniq.push_back(ip);
                    pos[ip] = prev(uniq.end());
                } else if (c == 2) {
                    uniq.erase(pos[ip]);
                    pos.erase(ip);
                }
            } else {
                res.push_back(uniq.empty() ? "" : uniq.front());
            }
        }
        return res;
    }
};

