def getBalancedString(arr):
    n = len(arr)
    pos = [0] * (n + 1)
    for i, v in enumerate(arr):
        pos[v] = i
    mn = float('inf')
    mx = -1
    out = []
    for k in range(1, n + 1):
        mn = min(mn, pos[k])
        mx = max(mx, pos[k])
        out.append('1' if mx - mn + 1 == k else '0')
    return ''.join(out)

class Solution {
    String getBalancedString(int[] arr) {
        int n = arr.length;
        int[] pos = new int[n + 1];
        for (int i = 0; i < n; i++) pos[arr[i]] = i;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= n; k++) {
            mn = Math.min(mn, pos[k]);
            mx = Math.max(mx, pos[k]);
            sb.append(mx - mn + 1 == k ? '1' : '0');
        }
        return sb.toString();
    }
}

