class Solution {
    int[][] par;
    int[] depth, xorToRoot;
    int LOG;
    boolean[] graphPalindromeQueries(int n, String labels, int[][] edges, int[][] queries) {
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new java.util.ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        LOG = Math.max(1, (int) Math.ceil(Math.log(n + 1) / Math.log(2)));
        par = new int[LOG][n];
        depth = new int[n];
        xorToRoot = new int[n];
        boolean[] vis = new boolean[n];
        vis[0] = true;
        xorToRoot[0] = 1 << (labels.charAt(0) - 'a');
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.add(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj.get(u)) if (!vis[v]) {
                vis[v] = true; par[0][v] = u;
                depth[v] = depth[u] + 1;
                xorToRoot[v] = xorToRoot[u] ^ (1 << (labels.charAt(v) - 'a'));
                q.add(v);
            }
        }
        for (int k = 1; k < LOG; k++) for (int v = 0; v < n; v++) par[k][v] = par[k-1][par[k-1][v]];
        boolean[] res = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int u = queries[i][0], v = queries[i][1];
            int l = lca(u, v);
            int mask = xorToRoot[u] ^ xorToRoot[v] ^ (1 << (labels.charAt(l) - 'a'));
            res[i] = Integer.bitCount(mask) <= 1;
        }
        return res;
    }
    int lca(int u, int v) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) if (((diff >> k) & 1) == 1) u = par[k][u];
        if (u == v) return u;
        for (int k = LOG - 1; k >= 0; k--)
            if (par[k][u] != par[k][v]) { u = par[k][u]; v = par[k][v]; }
        return par[0][u];
    }
}

class Solution {
public:
    vector<vector<int>> par;
    vector<int> depth, xorToRoot;
    int LOG;
    int lca(int u, int v) {
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) if ((diff >> k) & 1) u = par[k][u];
        if (u == v) return u;
        for (int k = LOG - 1; k >= 0; k--)
            if (par[k][u] != par[k][v]) { u = par[k][u]; v = par[k][v]; }
        return par[0][u];
    }
    vector<bool> graphPalindromeQueries(int n, string labels, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        LOG = max(1, (int) ceil(log2(n + 1)));
        par.assign(LOG, vector<int>(n, 0));
        depth.assign(n, 0); xorToRoot.assign(n, 0);
        vector<bool> vis(n, false);
        vis[0] = true;
        xorToRoot[0] = 1 << (labels[0] - 'a');
        queue<int> q; q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) if (!vis[v]) {
                vis[v] = true; par[0][v] = u;
                depth[v] = depth[u] + 1;
                xorToRoot[v] = xorToRoot[u] ^ (1 << (labels[v] - 'a'));
                q.push(v);
            }
        }
        for (int k = 1; k < LOG; k++) for (int v = 0; v < n; v++) par[k][v] = par[k-1][par[k-1][v]];
        vector<bool> res(queries.size());
        for (size_t i = 0; i < queries.size(); i++) {
            int u = queries[i][0], v = queries[i][1];
            int l = lca(u, v);
            int mask = xorToRoot[u] ^ xorToRoot[v] ^ (1 << (labels[l] - 'a'));
            res[i] = __builtin_popcount(mask) <= 1;
        }
        return res;
    }
};

class Solution {
    int canReachWithPrimeSteps(int[] nums) {
        int n = nums.length;
        if (n == 1) return 1;
        int maxStep = 0;
        for (int x : nums) maxStep = Math.max(maxStep, x);
        maxStep = Math.min(maxStep, n - 1);
        if (maxStep < 2) return 0;
        boolean[] sieve = new boolean[maxStep + 1];
        java.util.Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        for (int i = 2; (long) i * i <= maxStep; i++)
            if (sieve[i]) for (int j = i * i; j <= maxStep; j += i) sieve[j] = false;
        java.util.List<Integer> primes = new java.util.ArrayList<>();
        for (int i = 2; i <= maxStep; i++) if (sieve[i]) primes.add(i);
        boolean[] vis = new boolean[n];
        vis[0] = true;
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.add(0);
        while (!q.isEmpty()) {
            int i = q.poll();
            for (int p : primes) {
                if (p > nums[i]) break;
                int j = i + p;
                if (j >= n) continue;
                if (j == n - 1) return 1;
                if (!vis[j]) { vis[j] = true; q.add(j); }
            }
        }
        return 0;
    }
}

