def matchSubarrayToPattern(numbers, pattern):
    n = len(numbers)
    m = len(pattern)
    cnt = 0
    for i in range(n - m):
        ok = True
        for j in range(m):
            a, b = numbers[i + j], numbers[i + j + 1]
            sign = 1 if b > a else (-1 if b < a else 0)
            if sign != pattern[j]:
                ok = False; break
        if ok: cnt += 1
    return cnt

class Solution {
    int matchSubarrayToPattern(int[] numbers, int[] pattern) {
        int n = numbers.length, m = pattern.length, cnt = 0;
        for (int i = 0; i <= n - m - 1; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                int sign = Integer.compare(numbers[i + j + 1], numbers[i + j]);
                if (sign != pattern[j]) { ok = false; break; }
            }
            if (ok) cnt++;
        }
        return cnt;
    }
}

