        for (int i = 0; i <= n - m - 1; i++) {
            bool ok = true;
            for (int j = 0; j < m; j++) {
                int a = numbers[i + j], b = numbers[i + j + 1];
                int sign = (b > a) - (b < a);
                if (sign != pattern[j]) { ok = false; break; }
            }
            if (ok) cnt++;
        }
        return cnt;
    }
};

def matrixTransformation(a, q):
    a = [row[:] for row in a]
    n = len(a)
    for op in q:
        if op == 0:
            a = [[a[n-1-j][i] for j in range(n)] for i in range(n)]
        elif op == 1:
            a = [[a[j][i] for j in range(n)] for i in range(n)]
        else:
            a = [[a[n-1-j][n-1-i] for j in range(n)] for i in range(n)]
    return a

class Solution {
    int[][] matrixTransformation(int[][] a, int[] q) {
        int n = a.length;
        int[][] cur = new int[n][n];
        for (int i = 0; i < n; i++) cur[i] = a[i].clone();
        for (int op : q) {
            int[][] nx = new int[n][n];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) {
                    if (op == 0) nx[i][j] = cur[n-1-j][i];
                    else if (op == 1) nx[i][j] = cur[j][i];
                    else nx[i][j] = cur[n-1-j][n-1-i];
                }
            cur = nx;
        }
        return cur;
    }
}

