def solveMaximalSquareArea(input_str):
    lines = input_str.strip().split('\n')
    m, n = map(int, lines[0].split())
    mat = lines[1:1+m]
    dp = [[0] * n for _ in range(m)]
    side = 0
    for i in range(m):
        for j in range(n):
            if mat[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                if dp[i][j] > side: side = dp[i][j]
    return [str(side * side)]

class Solution {
    String[] solveMaximalSquareArea(String input) {
        String[] lines = input.strip().split("\n");
        String[] hdr = lines[0].split("\\s+");
        int m = Integer.parseInt(hdr[0]), n = Integer.parseInt(hdr[1]);
        int[][] dp = new int[m][n];
        int side = 0;
        for (int i = 0; i < m; i++) {
            String row = lines[1 + i];
            for (int j = 0; j < n; j++) {
                if (row.charAt(j) == '1') {
                    dp[i][j] = (i == 0 || j == 0) ? 1 : Math.min(Math.min(dp[i-1][j], dp[i][j-1]), dp[i-1][j-1]) + 1;
                    if (dp[i][j] > side) side = dp[i][j];
                }
            }
        }
        return new String[]{String.valueOf(side * side)};
    }
}

class Solution {
public:
