        stringstream ss(input);
        int m, n; ss >> m >> n;
        vector<string> mat(m);
        for (int i = 0; i < m; i++) ss >> mat[i];
        vector<vector<int>> dp(m, vector<int>(n, 0));
        int side = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (mat[i][j] == '1') {
                    dp[i][j] = (i == 0 || j == 0) ? 1 : min({dp[i-1][j], dp[i][j-1], dp[i-1][j-1]}) + 1;
                    side = max(side, dp[i][j]);
                }
        return {to_string(side * side)};
    }
};

class Solution {
    int maximumValueOfL(int[] fruits, long k) {
        int n = fruits.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + fruits[i];
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            boolean ok = true;
            for (int i = 0; i + mid <= n; i++) if (pre[i + mid] - pre[i] >= k) { ok = false; break; }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

