def maximumXORForEachQuery(arr, l, r):
    sub = arr[l:r+1]
    n = len(sub)
    def f(a):
        cur = a[:]
        while len(cur) > 1:
            cur = [cur[i] ^ cur[i+1] for i in range(len(cur) - 1)]
        return cur[0]
    best = 0
    for i in range(n):
        for j in range(i, n):
            best = max(best, f(sub[i:j+1]))
    return best

class Solution {
    int f(int[] a) {
        int[] cur = a.clone();
        int m = cur.length;
        while (m > 1) {
            int[] nx = new int[m - 1];
            for (int i = 0; i < m - 1; i++) nx[i] = cur[i] ^ cur[i + 1];
            cur = nx; m--;
        }
        return cur[0];
    }
    int maximumXORForEachQuery(int[] arr, int l, int r) {
        int[] sub = java.util.Arrays.copyOfRange(arr, l, r + 1);
        int n = sub.length, best = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++)
                best = Math.max(best, f(java.util.Arrays.copyOfRange(sub, i, j + 1)));
        return best;
    }
}

class Solution {
public:
    int f(vector<int> a) {
        while (a.size() > 1) {
            vector<int> nx;
            for (size_t i = 0; i + 1 < a.size(); i++) nx.push_back(a[i] ^ a[i + 1]);
            a = nx;
        }
        return a[0];
    }
    int maximumXORForEachQuery(vector<int>& arr, int l, int r) {
        vector<int> sub(arr.begin() + l, arr.begin() + r + 1);
        int n = sub.size(), best = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++)
                best = max(best, f(vector<int>(sub.begin() + i, sub.begin() + j + 1)));
        return best;
    }
};

class Solution {
    int minEdgeReversalsForRoot(int n, int[][] edges) {
        java.util.List<int[]>[] adj = new java.util.List[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], 0});
            adj[e[1]].add(new int[]{e[0], 1});
        }
        int[] res = new int[n];
        boolean[] vis = new boolean[n];
        // BFS 算 res[0]
        vis[0] = true;
        java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
        q.add(0);
        int[] parent = new int[n];
        java.util.Arrays.fill(parent, -1);
        int total = 0;
        java.util.List<Integer> order = new java.util.ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int[] e : adj[u]) {
                int v = e[0], w = e[1];
                if (!vis[v]) {
                    vis[v] = true; parent[v] = u;
                    total += w;
                    q.add(v);
                }
            }
        }
        res[0] = total;
        for (int u : order) {
            for (int[] e : adj[u]) {
                int v = e[0], w = e[1];
                if (parent[v] == u) {
                    res[v] = res[u] + (w == 0 ? 1 : -1);
                }
            }
        }
        int mn = Integer.MAX_VALUE;
        for (int x : res) mn = Math.min(mn, x);
        return mn;
    }
}

class Solution {
