        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], 0});
            adj[e[1]].push_back({e[0], 1});
        }
        vector<int> res(n, 0), parent(n, -1);
        vector<bool> vis(n, false);
        vis[0] = true;
        queue<int> q; q.push(0);
        int total = 0;
        vector<int> order;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            order.push_back(u);
            for (auto& [v, w] : adj[u]) if (!vis[v]) {
                vis[v] = true; parent[v] = u; total += w; q.push(v);
            }
        }
        res[0] = total;
        for (int u : order) {
            for (auto& [v, w] : adj[u]) if (parent[v] == u) {
                res[v] = res[u] + (w == 0 ? 1 : -1);
            }
        }
        return *min_element(res.begin(), res.end());
    }
};

def minObstacleRemoval(matrix):
    m, n = len(matrix), len(matrix[0])
    total = 0
    for c in range(n):
        col = [matrix[r][c] for r in range(m)]
        # 从下往上模拟"自由落体"
        write = m - 1
        for r in range(m - 1, -1, -1):
            if col[r] == '|':
                while write > r and col[write] != '.':
                    if col[write] == '#':
                        total += 1
                        col[write] = '.'
                    write -= 1
                if write > r:
                    col[write] = '|'
                    col[r] = '.'
                    write -= 1
        # 计算 | 落到底过程中遇到的 #
    return total

class Solution {
    int minObstacleRemoval(char[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int total = 0;
        for (int c = 0; c < n; c++) {
            char[] col = new char[m];
            for (int r = 0; r < m; r++) col[r] = matrix[r][c];
            int write = m - 1;
            for (int r = m - 1; r >= 0; r--) {
                if (col[r] == '|') {
                    while (write > r && col[write] != '.') {
                        if (col[write] == '#') { total++; col[write] = '.'; }
                        write--;
                    }
                    if (write > r) {
                        col[write] = '|';
                        col[r] = '.';
                        write--;
                    }
                }
            }
        }
        return total;
    }
}

