def minOperationsToMakeSequenceHarmonious(A):
    n = len(A)
    dp = [0] * (n + 1)
    for i in range(n):
        # 选择删除 A[i]
        if dp[i] > dp[i + 1]: dp[i + 1] = dp[i]
        # 选择保留 A[i] 作为组头
        k = A[i]
        if i + k < n:
            if dp[i] + k + 1 > dp[i + k + 1]:
                dp[i + k + 1] = dp[i] + k + 1
    return n - dp[n]

class Solution {
    int minOperationsToMakeSequenceHarmonious(int[] A) {
        int n = A.length;
        int[] dp = new int[n + 1];
        for (int i = 0; i < n; i++) {
            if (dp[i] > dp[i + 1]) dp[i + 1] = dp[i];
            int k = A[i];
            if (i + k < n) {
                int t = dp[i] + k + 1;
                if (t > dp[i + k + 1]) dp[i + k + 1] = t;
            }
        }
        return n - dp[n];
    }
}

