};

class Solution {
    int minimumRightShiftsToSortArray(int[] nums) {
        int n = nums.length, breaks = 0, bp = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] > nums[(i + 1) % n]) { breaks++; bp = i; }
        }
        if (breaks == 0) return 0;
        if (breaks == 1) return n - bp - 1;
        return -1;
    }
}

