def reverseAndAppend(s):
    seen = set()
    res = []
    for i in range(1, len(s)):
        a = s[:i][::-1] + s[i:]
        if a != s and a not in seen:
            seen.add(a); res.append(a)
        b = s[:i] + s[i:][::-1]
        if b != s and b not in seen:
            seen.add(b); res.append(b)
    return res

class Solution {
    java.util.List<String> reverseAndAppend(String s) {
        java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<>();
        for (int i = 1; i < s.length(); i++) {
            String a = new StringBuilder(s.substring(0, i)).reverse().toString() + s.substring(i);
            if (!a.equals(s)) seen.add(a);
            String b = s.substring(0, i) + new StringBuilder(s.substring(i)).reverse().toString();
            if (!b.equals(s)) seen.add(b);
        }
        return new java.util.ArrayList<>(seen);
    }
}

class Solution {
public:
    vector<string> reverseAndAppend(string s) {
        vector<string> res;
        unordered_set<string> seen;
        for (size_t i = 1; i < s.size(); i++) {
            string a = s.substr(0, i);
            reverse(a.begin(), a.end());
            a += s.substr(i);
            if (a != s && !seen.count(a)) { seen.insert(a); res.push_back(a); }
            string b = s.substr(0, i);
            string rest = s.substr(i);
            reverse(rest.begin(), rest.end());
            b += rest;
            if (b != s && !seen.count(b)) { seen.insert(b); res.push_back(b); }
        }
        return res;
    }
};

class Solution {
    long maximizePipelineThroughput(int[] throughputs, int[] costs, long budget) {
        long lo = Long.MAX_VALUE, hi = 0;
        for (int t : throughputs) lo = Math.min(lo, t);
        for (int i = 0; i < throughputs.length; i++) {
            hi = Math.max(hi, (long) throughputs[i] * (1 + budget / Math.max(costs[i], 1)));
        }
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            long cost = 0;
            boolean ok = true;
            for (int i = 0; i < throughputs.length; i++) {
                if (throughputs[i] >= mid) continue;
                long x = (mid + throughputs[i] - 1) / throughputs[i] - 1;
                cost += x * costs[i];
                if (cost > budget) { ok = false; break; }
            }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

class Solution {
public:
