        long long lo = LLONG_MAX, hi = 0;
        for (int t : throughputs) lo = min(lo, (long long) t);
        for (size_t i = 0; i < throughputs.size(); i++) {
            hi = max(hi, (long long) throughputs[i] * (1 + budget / max(costs[i], 1)));
