def findRegionalMaxima(array):
    R = len(array)
    C = len(array[0]) if R > 0 else 0
    res = []
    for i in range(R):
        for j in range(C):
            cell = array[i][j]
            if cell == 0: continue
            ok = True
            for di in range(-cell, cell + 1):
                for dj in range(-cell, cell + 1):
                    ni, nj = i + di, j + dj
                    if ni < 0 or ni >= R or nj < 0 or nj >= C: continue
                    if (di, dj) in {(-cell, -cell), (-cell, cell), (cell, -cell), (cell, cell)}:
                        continue
                    if ni == i and nj == j: continue
                    if array[ni][nj] > cell:
                        ok = False; break
                if not ok: break
            if ok: res.append([i, j])
    return res

class Solution {
    int[][] findRegionalMaxima(int[][] array) {
        int R = array.length, C = R > 0 ? array[0].length : 0;
        java.util.List<int[]> res = new java.util.ArrayList<>();
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) {
                int cell = array[i][j];
                if (cell == 0) continue;
                boolean ok = true;
                outer:
                for (int di = -cell; di <= cell; di++)
                    for (int dj = -cell; dj <= cell; dj++) {
                        int ni = i + di, nj = j + dj;
                        if (ni < 0 || ni >= R || nj < 0 || nj >= C) continue;
                        if ((di == -cell || di == cell) && (dj == -cell || dj == cell)) continue;
                        if (ni == i && nj == j) continue;
                        if (array[ni][nj] > cell) { ok = false; break outer; }
                    }
                if (ok) res.add(new int[]{i, j});
            }
        return res.toArray(new int[0][]);
    }
}

class Solution {
