class Solution {
    int[][] simulateWaterFlow(int[][] heights, int startRow, int startCol) {
        int m = heights.length, n = m > 0 ? heights[0].length : 0;
        int[][] res = new int[m][n];
        for (int[] row : res) java.util.Arrays.fill(row, -1);
        res[startRow][startCol] = 0;
        java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
        q.add(new int[]{startRow, startCol});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] x = q.poll();
            for (int[] d : dirs) {
                int nr = x[0] + d[0], nc = x[1] + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && res[nr][nc] == -1 && heights[nr][nc] <= heights[x[0]][x[1]]) {
                    res[nr][nc] = res[x[0]][x[1]] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return res;
    }
}

