class Solution {
    int findPointMostLamps(int[][] lamps) {
        java.util.List<int[]> ev = new java.util.ArrayList<>();
        for (int[] l : lamps) { ev.add(new int[]{l[0] - l[1], 1}); ev.add(new int[]{l[0] + l[1] + 1, -1}); }
        ev.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int cur = 0, best = 0, bestPos = 0;
        int i = 0;
        while (i < ev.size()) {
            int x = ev.get(i)[0], delta = 0;
            while (i < ev.size() && ev.get(i)[0] == x) { delta += ev.get(i)[1]; i++; }
            cur += delta;
            if (cur > best) { best = cur; bestPos = x; }
        }
        return bestPos;
    }
}

