def sumOfScoresOfBuiltArrays(low, high):
    MOD = 10**9 + 7
    M = max(high) + 1
    sieve = [True] * M
    sieve[0] = sieve[1] = False
    for i in range(2, int(M**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, M, i):
                sieve[j] = False
    psum = [0] * (M + 1)
    for i in range(M):
        psum[i + 1] = psum[i] + (i if sieve[i] else 0)
    ans = 1
    for lo, hi in zip(low, high):
        s = psum[hi + 1] - psum[lo]
        ans = (ans * s) % MOD
    return ans

class Solution {
    int sumOfScoresOfBuiltArrays(int[] low, int[] high) {
        final int MOD = 1_000_000_007;
        int M = 0;
        for (int h : high) M = Math.max(M, h);
        M++;
        boolean[] sieve = new boolean[M];
        java.util.Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        for (int i = 2; (long) i * i < M; i++) if (sieve[i]) for (int j = i * i; j < M; j += i) sieve[j] = false;
        long[] psum = new long[M + 1];
        for (int i = 0; i < M; i++) psum[i + 1] = psum[i] + (sieve[i] ? i : 0);
        long ans = 1;
        for (int i = 0; i < low.length; i++) {
            long s = psum[high[i] + 1] - psum[low[i]];
            ans = (ans * (s % MOD)) % MOD;
        }
        return (int) ans;
    }
}

