import heapq

def topK(nums, k):
    heap = []
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)
    return heap

class Solution {
    int[] topK(int[] nums, int k) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        for (int x : nums) {
            if (pq.size() < k) pq.add(x);
            else if (x > pq.peek()) { pq.poll(); pq.add(x); }
        }
        int[] res = new int[pq.size()];
        int i = 0;
        for (int x : pq) res[i++] = x;
        return res;
    }
}

class Solution {
public:
    vector<int> topK(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<>> pq;
        for (int x : nums) {
            if ((int)pq.size() < k) pq.push(x);
            else if (x > pq.top()) { pq.pop(); pq.push(x); }
        }
        vector<int> res;
        while (!pq.empty()) { res.push_back(pq.top()); pq.pop(); }
        return res;
    }
};

class Solution {
    int[][] simulateTournamentRounds(int[] ranks) {
        java.util.List<int[]> res = new java.util.ArrayList<>();
        int[] cur = ranks.clone();
        while (cur.length > 1) {
            int sz = (cur.length + 1) / 2;
            int[] nxt = new int[sz];
            int idx = 0, i = 0;
            while (i + 1 < cur.length) { nxt[idx++] = Math.min(cur[i], cur[i+1]); i += 2; }
            if (i < cur.length) nxt[idx++] = cur[i];
            res.add(nxt);
            cur = nxt;
        }
        return res.toArray(new int[0][]);
    }
}

