            size_t i = 0;
            while (i + 1 < cur.size()) { nxt.push_back(min(cur[i], cur[i+1])); i += 2; }
            if (i < cur.size()) nxt.push_back(cur[i]);
            res.push_back(nxt);
            cur = nxt;
        }
