class Solution {
    int wordPairs(String[] magics) {
        java.util.List<java.util.HashMap<Character, Integer>> trie = new java.util.ArrayList<>();
        trie.add(new java.util.HashMap<>());
        java.util.List<Integer> endCount = new java.util.ArrayList<>();
        java.util.List<Integer> subCount = new java.util.ArrayList<>();
        endCount.add(0); subCount.add(0);
        for (String w : magics) {
            int cur = 0;
            subCount.set(0, subCount.get(0) + 1);
            for (char c : w.toCharArray()) {
                if (!trie.get(cur).containsKey(c)) {
                    trie.add(new java.util.HashMap<>());
                    endCount.add(0); subCount.add(0);
                    trie.get(cur).put(c, trie.size() - 1);
                }
                cur = trie.get(cur).get(c);
                subCount.set(cur, subCount.get(cur) + 1);
            }
            endCount.set(cur, endCount.get(cur) + 1);
        }
        long total = 0;
        for (String w : magics) {
            int cur = 0;
            boolean ok = true;
            for (char c : w.toCharArray()) {
                Integer nxt = trie.get(cur).get(c);
                if (nxt == null) { ok = false; break; }
                cur = nxt;
            }
            if (!ok) continue;
            total += subCount.get(cur) - 1;
            int cur2 = 0;
            for (int i = 0; i < w.length() - 1; i++) {
                cur2 = trie.get(cur2).get(w.charAt(i));
                total += endCount.get(cur2);
            }
            total += endCount.get(cur) - 1;
        }
        return (int) (total / 2);
    }
}

