                    trie.push_back({});
                    endCount.push_back(0);
                    subCount.push_back(0);
                    trie[cur][c] = trie.size() - 1;
                }
                cur = trie[cur][c];
                subCount[cur]++;
            }
            endCount[cur]++;
        }
        long long total = 0;
        for (auto& w : magics) {
            int cur = 0;
            bool ok = true;
            for (char c : w) {
                auto it = trie[cur].find(c);
                if (it == trie[cur].end()) { ok = false; break; }
                cur = it->second;
            }
            if (!ok) continue;
            total += subCount[cur] - 1;
            int cur2 = 0;
            for (size_t i = 0; i + 1 < w.size(); i++) {
                cur2 = trie[cur2][w[i]];
                total += endCount[cur2];
            }
