def count_subarrays(nums, k):
    if k < 1:
        return 0
    ans = 0
    prod, l = 1, 0
    for r, x in enumerate(nums):
        prod *= x
        while prod > k:
            prod //= nums[l]
            l += 1
        ans += r - l + 1
    return ans

class Solution {
    public static long count(int[] nums, int k) {
        if (k < 1) return 0;
        long ans = 0, prod = 1;
        int l = 0;
        for (int r = 0; r < nums.length; r++) {
            prod *= nums[r];
            while (prod > k) prod /= nums[l++];
            ans += r - l + 1;
        }
        return ans;
    }
}

