from collections import deque
from typing import List

def get_minimum_moves(maze: List[List[int]], k: int) -> int:
    n, m = len(maze), len(maze[0])
    if maze[0][0] == 1 or maze[n - 1][m - 1] == 1:
        return -1
    dist = [[-1] * m for _ in range(n)]
    dist[0][0] = 0
    q = deque([(0, 0)])
    while q:
        r, c = q.popleft()
        if (r, c) == (n - 1, m - 1):
            return dist[r][c]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            for x in range(1, k + 1):
                nr, nc = r + dr * x, c + dc * x
                if not (0 <= nr < n and 0 <= nc < m) or maze[nr][nc] == 1:
                    break
                if dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
    return dist[n - 1][m - 1]

import java.util.*;

class Solution {
    public int getMinimumMoves(int[][] maze, int k) {
        int n = maze.length, m = maze[0].length;
        if (maze[0][0] == 1 || maze[n - 1][m - 1] == 1) return -1;
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[0][0] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            if (r == n - 1 && c == m - 1) return dist[r][c];
            for (int i = 0; i < 4; i++) {
                for (int x = 1; x <= k; x++) {
                    int nr = r + dr[i] * x, nc = c + dc[i] * x;
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m || maze[nr][nc] == 1) break;
                    if (dist[nr][nc] == -1) {
                        dist[nr][nc] = dist[r][c] + 1;
                        q.add(new int[]{nr, nc});
                    }
                }
            }
        }
        return dist[n - 1][m - 1];
    }
}

