class Solution {
    public String[] solvePrintSentencesAsTable(String input) {
        String[] lines = input.split("\n", -1);
        if (lines[0].isBlank()) return new String[0];
        String[] hp = lines[0].split("\\s+");
        int n = Integer.parseInt(hp[0]), width = Integer.parseInt(hp[1]);
        if (n == 0) return new String[0];
        String border = "+" + "-".repeat(width + 2) + "+";
        List<String> out = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String s = i + 1 < lines.length ? lines[i + 1] : "";
            out.add(border);
            StringBuilder row = new StringBuilder("| ").append(s);
            for (int k = s.length(); k < width; k++) row.append(' ');
            row.append(" |");
            out.add(row.toString());
        }
        out.add(border);
        return out.toArray(new String[0]);
    }
}

