from collections import defaultdict
from typing import List

def resolve_battles(actions: List[str]) -> List[str]:
    armies = {}  # name -> (loc, type, target_or_dest)
    for act in actions:
        toks = act.split()
        name, loc, kind = toks[0], toks[1], toks[2]
        target = toks[3] if len(toks) > 3 else None
        armies[name] = (loc, kind, target)

    # Determine moves: who attacks where, and who is at where (Hold + Support)
    attacks_at = defaultdict(list)  # loc -> list of attacker names
    occupants = {}  # loc -> name (for Hold/Support)
    for name, (loc, kind, target) in armies.items():
        if kind == "Move":
            attacks_at[target].append(name)
        else:
            occupants[loc] = name

    # Determine which Supports are interrupted (their location is being attacked)
    valid_support = {}  # supporter_name -> supported_army_name
    for name, (loc, kind, target) in armies.items():
        if kind == "Support" and not attacks_at.get(loc):
            valid_support[name] = target

    # Strength of each army present in any location
    # A Hold/Support has strength 1 (in its own loc). A Move attacks with strength 1 plus supports targeting that move
    strength = defaultdict(int)
    for name, (loc, kind, target) in armies.items():
        if kind in ("Hold", "Move"):
            strength[name] = 1
    for supporter, supported in valid_support.items():
        strength[supported] += 1

    # Resolve each contested location
    result = {}
    for loc, attackers in attacks_at.items():
        defender = occupants.get(loc)  # may be None
        contenders = list(attackers)
        if defender:
            contenders.append(defender)
        max_str = max(strength[c] for c in contenders)
        winners = [c for c in contenders if strength[c] == max_str]
        if len(winners) == 1:
            w = winners[0]
            # Move winner takes location; defender (if not winner) dies
            if w in attackers:
                result[w] = loc
                if defender and defender != w:
                    result[defender] = "[dead]"
                for a in attackers:
                    if a != w:
                        result[a] = "[dead]"
            else:
                # defender holds
                result[defender] = loc
                for a in attackers:
                    result[a] = "[dead]"
        else:
            # all tie => all lose: defender stays, attackers dead (bounced)
            if defender:
                result[defender] = loc
            for a in attackers:
                result[a] = "[dead]"

    # Final positions
    out: List[str] = []
    for name, (loc, kind, target) in armies.items():
        if name in result:
            out.append(f"{name} {result[name]}")
        else:
            out.append(f"{name} {loc}")
    return out

import java.util.*;

class Solution {
    public List<String> resolveBattles(List<String> actions) {
        // Java implementation mirrors the Python logic above.
        Map<String, String[]> armies = new LinkedHashMap<>();
        for (String act : actions) {
            String[] t = act.split("\\s+");
            armies.put(t[0], new String[]{t[1], t[2], t.length > 3 ? t[3] : null});
        }
        Map<String, List<String>> attacksAt = new HashMap<>();
        Map<String, String> occupants = new HashMap<>();
        for (var e : armies.entrySet()) {
            String[] v = e.getValue();
            if ("Move".equals(v[1])) attacksAt.computeIfAbsent(v[2], k -> new ArrayList<>()).add(e.getKey());
            else occupants.put(v[0], e.getKey());
        }
        Map<String, String> validSupport = new HashMap<>();
        for (var e : armies.entrySet()) {
            String[] v = e.getValue();
            if ("Support".equals(v[1]) && !attacksAt.containsKey(v[0])) validSupport.put(e.getKey(), v[2]);
        }
        Map<String, Integer> strength = new HashMap<>();
        for (var e : armies.entrySet()) {
            String[] v = e.getValue();
            if ("Hold".equals(v[1]) || "Move".equals(v[1])) strength.put(e.getKey(), 1);
        }
        for (var e : validSupport.entrySet()) strength.merge(e.getValue(), 1, Integer::sum);
        Map<String, String> result = new HashMap<>();
        for (var e : attacksAt.entrySet()) {
            String loc = e.getKey();
            List<String> contenders = new ArrayList<>(e.getValue());
            String defender = occupants.get(loc);
            if (defender != null) contenders.add(defender);
            int maxStr = 0;
            for (String c : contenders) maxStr = Math.max(maxStr, strength.getOrDefault(c, 0));
            List<String> winners = new ArrayList<>();
            for (String c : contenders) if (strength.getOrDefault(c, 0) == maxStr) winners.add(c);
            if (winners.size() == 1) {
                String w = winners.get(0);
                if (e.getValue().contains(w)) {
                    result.put(w, loc);
                    if (defender != null && !defender.equals(w)) result.put(defender, "[dead]");
                    for (String a : e.getValue()) if (!a.equals(w)) result.put(a, "[dead]");
                } else {
                    result.put(defender, loc);
                    for (String a : e.getValue()) result.put(a, "[dead]");
                }
            } else {
                if (defender != null) result.put(defender, loc);
                for (String a : e.getValue()) result.put(a, "[dead]");
            }
        }
        List<String> out = new ArrayList<>();
        for (var e : armies.entrySet()) {
            out.add(e.getKey() + " " + (result.getOrDefault(e.getKey(), e.getValue()[0])));
        }
        return out;
    }
}

