class Solution {
public:
    vector<string> resolveBattles(vector<string>& actions) {
        // Mirror Python logic.
        vector<pair<string, vector<string>>> armies;
        for (auto& act : actions) {
            stringstream ss(act); string a, b, c, d;
            ss >> a >> b >> c;
            if (ss >> d) armies.push_back({a, {b, c, d}});
            else armies.push_back({a, {b, c, ""}});
        }
        unordered_map<string, vector<string>> attacksAt;
        unordered_map<string, string> occupants;
        for (auto& [name, v] : armies) {
            if (v[1] == "Move") attacksAt[v[2]].push_back(name);
            else occupants[v[0]] = name;
        }
        unordered_map<string, string> validSupport;
        for (auto& [name, v] : armies) {
            if (v[1] == "Support" && !attacksAt.count(v[0])) validSupport[name] = v[2];
        }
        unordered_map<string, int> strength;
        for (auto& [name, v] : armies) {
            if (v[1] == "Hold" || v[1] == "Move") strength[name] = 1;
        }
        for (auto& [s, t] : validSupport) strength[t]++;
        unordered_map<string, string> result;
        for (auto& [loc, attackers] : attacksAt) {
            vector<string> contenders = attackers;
            string defender = occupants.count(loc) ? occupants[loc] : "";
            if (!defender.empty()) contenders.push_back(defender);
            int maxStr = 0;
            for (auto& c : contenders) maxStr = max(maxStr, strength[c]);
            vector<string> winners;
            for (auto& c : contenders) if (strength[c] == maxStr) winners.push_back(c);
            if (winners.size() == 1) {
                string w = winners[0];
                if (find(attackers.begin(), attackers.end(), w) != attackers.end()) {
                    result[w] = loc;
                    if (!defender.empty() && defender != w) result[defender] = "[dead]";
                    for (auto& a : attackers) if (a != w) result[a] = "[dead]";
                } else {
                    result[defender] = loc;
                    for (auto& a : attackers) result[a] = "[dead]";
                }
            } else {
                if (!defender.empty()) result[defender] = loc;
                for (auto& a : attackers) result[a] = "[dead]";
            }
        }
        vector<string> out;
        for (auto& [name, v] : armies) {
            out.push_back(name + " " + (result.count(name) ? result[name] : v[0]));
        }
        return out;
    }
};

import java.util.*;

class Solution {
    public int[] roundPrices(double[] prices, int target) {
        int n = prices.length;
        int[] floors = new int[n];
        int sum = 0;
        for (int i = 0; i < n; i++) { floors[i] = (int) Math.floor(prices[i]); sum += floors[i]; }
        int diff = target - sum;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Double.compare(prices[b] - floors[b], prices[a] - floors[a]));
        for (int k = 0; k < diff && k < n; k++) floors[order[k]] += 1;
        return floors;
    }
}

