def card_range_part4(BIN: str, info: List[List[str]]) -> List[List[str]]:
    # Reuse Part 3 logic
    low = BIN + "0" * 10
    high = BIN + "9" * 10
    ivs = sorted([[BIN + s, BIN + e, b] for s, e, b in info], key=lambda x: (x[0], -int(x[1])))
    outer, inner = [], []
    for iv in ivs:
        if outer and iv[0] >= outer[-1][0] and iv[1] <= outer[-1][1]:
            inner.append(iv)
        else:
            outer.append(iv)
    if outer:
        outer.sort(key=lambda x: x[0])
        outer[0][0] = low
        outer[-1][1] = high
        for i in range(len(outer) - 1):
            n = int(outer[i + 1][0]) - 1
            outer[i][1] = str(n).zfill(16)
    # Merge adjacent same-brand
    merged: list = []
    for iv in outer:
        if merged and merged[-1][2] == iv[2] and int(merged[-1][1]) + 1 == int(iv[0]):
            merged[-1][1] = iv[1]
        else:
            merged.append(iv)
    return merged + inner

