class Solution {
    public String[] calculateMonthlyBilling(String[] sessions) {
        Map<String, List<int[]>> byUser = new TreeMap<>();
        Map<String, List<String>> userPlan = new HashMap<>();
        for (String s : sessions) {
            String[] p = s.split(",");
            byUser.computeIfAbsent(p[0], k -> new ArrayList<>()).add(new int[]{Integer.parseInt(p[1]), Integer.parseInt(p[2])});
            userPlan.computeIfAbsent(p[0], k -> new ArrayList<>()).add(p[3]);
        }
        List<String> out = new ArrayList<>();
        for (var uid : byUser.keySet()) {
            var sess = byUser.get(uid);
            var plans = userPlan.get(uid);
            int n = sess.size(), nFixed = 0;
            for (String p : plans) if ("fixed".equals(p)) nFixed++;
            double ratio = n > 0 ? (double) nFixed / n : 0;
            double total = 0;
            long inFixed = 0, outFixed = 0;
            for (int i = 0; i < n; i++) {
                int[] arr = sess.get(i);
                if ("payg".equals(plans.get(i))) total += (arr[0] / 100) * 0.03 + (arr[1] / 100) * 0.04;
                else { inFixed += arr[0]; outFixed += arr[1]; }
            }
            if (nFixed > 0) {
                total += 15.0 * ratio;
                long inOver = Math.max(0, inFixed - (long)(40000 * ratio));
                long outOver = Math.max(0, outFixed - (long)(20000 * ratio));
                total += (inOver / 100) * 0.03 + (outOver / 100) * 0.04;
            }
            out.add(String.format("%s: $%.2f", uid, total));
        }
        return out.toArray(new String[0]);
    }
}

