class Solution {
    public String[] solveEmailLogGroupingAndSorting(String input) {
        String[] lines = input.split("\n", -1);
        if (lines.length == 0 || lines[0].isBlank()) return new String[0];
        int n = Integer.parseInt(lines[0].trim());
        Map<String, List<Object[]>> groups = new TreeMap<>();
        for (int i = 1; i <= n; i++) {
            String[] p = lines[i].split("\\s+", 4);
            int ts = Integer.parseInt(p[0]);
            String sender = p[1], receiver = p[2];
            String subj = p.length > 3 ? p[3] : "";
            groups.computeIfAbsent(sender, k -> new ArrayList<>()).add(new Object[]{ts, receiver, subj});
        }
        List<String> out = new ArrayList<>();
        for (var e : groups.entrySet()) {
            e.getValue().sort((a, b) -> {
                int c = (int)((int)a[0] - (int)b[0]);
                if (c != 0) return c;
                c = ((String)a[1]).compareTo((String)b[1]);
                if (c != 0) return c;
                return ((String)a[2]).compareTo((String)b[2]);
            });
            out.add("sender: " + e.getKey());
            for (Object[] r : e.getValue()) out.add(r[0] + " " + r[1] + (((String)r[2]).isEmpty() ? "" : " " + r[2]));
        }
        return out.toArray(new String[0]);
    }
}

