        while (getline(ss, ln, '\n')) lines.push_back(ln);
        if (lines.empty() || lines[0].empty()) return {};
        int n = stoi(lines[0]);
        map<string, vector<tuple<int, string, string>>> groups;
        for (int i = 1; i <= n; i++) {
            stringstream ls(lines[i]); int ts; string sender, receiver, subj, tok;
            ls >> ts >> sender >> receiver;
            getline(ls, subj);
            // strip leading space
            size_t p = subj.find_first_not_of(' ');
            subj = (p == string::npos) ? "" : subj.substr(p);
            groups[sender].push_back({ts, receiver, subj});
        }
        vector<string> out;
        for (auto& [sender, items] : groups) {
            sort(items.begin(), items.end());
            out.push_back("sender: " + sender);
            for (auto& [ts, r, subj] : items) {
                string line = to_string(ts) + " " + r;
                if (!subj.empty()) line += " " + subj;
                out.push_back(line);
            }
        }
        return out;
    }
};

