def process_intents(commands: List[str]) -> List[str]:
    merchants: dict = {}
    intents: dict = {}
    for cmd in commands:
        p = cmd.split()
        if p[0] == "INIT":
            if p[1] not in merchants: merchants[p[1]] = int(p[2])
        elif p[0] == "CREATE":
            pid, mid, amt = p[1], p[2], int(p[3])
            if pid in intents or mid not in merchants or amt < 0: continue
            intents[pid] = [mid, amt, "REQUIRES_ACTION"]
        elif p[0] == "UPDATE":
            pid, new_amt = p[1], int(p[2])
            if pid in intents and intents[pid][2] == "REQUIRES_ACTION" and new_amt >= 0:
                intents[pid][1] = new_amt
        elif p[0] == "ATTEMPT":
            if p[1] in intents and intents[p[1]][2] == "REQUIRES_ACTION":
                intents[p[1]][2] = "PROCESSING"
        elif p[0] == "SUCCEED":
            if p[1] in intents and intents[p[1]][2] == "PROCESSING":
                intents[p[1]][2] = "COMPLETED"
                merchants[intents[p[1]][0]] += intents[p[1]][1]
    return [f"{m} {merchants[m]}" for m in sorted(merchants)]

