def process_intents(commands: List[str]) -> List[str]:
    merchants: dict = {}  # mid -> [balance, refund_limit (None = unlimited)]
    intents: dict = {}    # pid -> [mid, amt, state, refunded, succeed_ts]
    for cmd in commands:
        p = cmd.split()
        ts = int(p[0])
        op = p[1]
        if op == "INIT":
            mid, bal = p[2], int(p[3])
            limit = int(p[4]) if len(p) >= 5 else None
            if mid not in merchants:
                merchants[mid] = [bal, limit if (limit is None or limit >= 0) else None]
        elif op == "CREATE":
            pid, mid, amt = p[2], p[3], int(p[4])
            if pid in intents or mid not in merchants or amt < 0: continue
            intents[pid] = [mid, amt, "REQUIRES_ACTION", False, None]
        elif op == "UPDATE":
            if p[2] in intents and intents[p[2]][2] == "REQUIRES_ACTION" and int(p[3]) >= 0:
                intents[p[2]][1] = int(p[3])
        elif op == "ATTEMPT":
            if p[2] in intents and intents[p[2]][2] == "REQUIRES_ACTION":
                intents[p[2]][2] = "PROCESSING"
        elif op == "SUCCEED":
            if p[2] in intents and intents[p[2]][2] == "PROCESSING":
                intents[p[2]][2] = "COMPLETED"
                merchants[intents[p[2]][0]][0] += intents[p[2]][1]
                intents[p[2]][4] = ts
        elif op == "FAIL":
            if p[2] in intents and intents[p[2]][2] == "PROCESSING":
                intents[p[2]][2] = "REQUIRES_ACTION"
        elif op == "REFUND":
            if p[2] in intents and intents[p[2]][2] == "COMPLETED" and not intents[p[2]][3]:
                mid = intents[p[2]][0]
                limit = merchants[mid][1]
                ok = (limit is None) or (limit > 0 and ts - intents[p[2]][4] <= limit) or (limit < 0)
                if limit == 0: ok = False
                if ok:
                    merchants[mid][0] -= intents[p[2]][1]
                    intents[p[2]][3] = True
    return [f"{m} {merchants[m][0]}" for m in sorted(merchants)]

from typing import List

def process_intents(commands: List[str]) -> List[str]:
    merchants: dict = {}
    intents: dict = {}
    for cmd in commands:
        p = cmd.split()
        if p[0] == "INIT":
            mid, bal = p[1], int(p[2])
            if mid not in merchants:
                merchants[mid] = bal
        elif p[0] == "CREATE":
            pid, mid, amt = p[1], p[2], int(p[3])
            if pid in intents or mid not in merchants or amt < 0: continue
            intents[pid] = [mid, amt, "REQUIRES_ACTION"]
        elif p[0] == "ATTEMPT":
            pid = p[1]
            if pid in intents and intents[pid][2] == "REQUIRES_ACTION":
                intents[pid][2] = "PROCESSING"
        elif p[0] == "SUCCEED":
            pid = p[1]
            if pid in intents and intents[pid][2] == "PROCESSING":
                intents[pid][2] = "COMPLETED"
                merchants[intents[pid][0]] += intents[pid][1]
    return [f"{m} {merchants[m]}" for m in sorted(merchants)]

import java.util.*;

class Solution {
    public List<String> processIntents(List<String> commands) {
        Map<String, Long> merchants = new TreeMap<>();
        Map<String, Object[]> intents = new HashMap<>();
        for (String cmd : commands) {
            String[] p = cmd.split("\\s+");
            switch (p[0]) {
                case "INIT": merchants.putIfAbsent(p[1], Long.parseLong(p[2])); break;
                case "CREATE": {
                    if (intents.containsKey(p[1]) || !merchants.containsKey(p[2]) || Long.parseLong(p[3]) < 0) break;
                    intents.put(p[1], new Object[]{p[2], Long.parseLong(p[3]), "REQUIRES_ACTION"});
                    break;
                }
                case "ATTEMPT": {
                    Object[] iv = intents.get(p[1]);
                    if (iv != null && "REQUIRES_ACTION".equals(iv[2])) iv[2] = "PROCESSING";
                    break;
                }
                case "SUCCEED": {
                    Object[] iv = intents.get(p[1]);
                    if (iv != null && "PROCESSING".equals(iv[2])) { iv[2] = "COMPLETED"; merchants.merge((String) iv[0], (Long) iv[1], Long::sum); }
                    break;
                }
            }
        }
        List<String> out = new ArrayList<>();
        for (var e : merchants.entrySet()) out.add(e.getKey() + " " + e.getValue());
        return out;
    }
}

