class Solution {
    public List<Long> solution(String[] queries, int diff) {
        Map<Integer, Integer> cnt = new HashMap<>();
        long total = 0;
        List<Long> out = new ArrayList<>();
        for (String q : queries) {
            int sign = q.charAt(0) == '+' ? 1 : -1;
            int x = Integer.parseInt(q.substring(1));
            int cur = cnt.getOrDefault(x, 0);
            int delta = sign == 1 ? 1 : -cur;
            int a = cnt.getOrDefault(x - diff, 0), b = cnt.getOrDefault(x + diff, 0);
            int c2 = cnt.getOrDefault(x + 2 * diff, 0), d2 = cnt.getOrDefault(x - 2 * diff, 0);
            int base = sign == 1 ? cur : cur + delta;
            long d = (long) a * b * delta
                   + (long) base * c2 * delta
                   + (long) d2 * base * delta;
            total += d;
            cnt.put(x, cur + delta);
            out.add(total);
        }
        return out;
    }
}

vector<long long> solution(vector<string>& queries, int diff) {
 unordered_map<int, int> cnt;
