 int sign = q[0] == '+' ? 1 : -1;
 int x = stoi(q.substr(1));
 int cur = cnt[x];
 int delta = sign == 1 ? 1 : -cur;
 int base = sign == 1 ? cur : cur + delta;
 long long d = 0;
 d += (long long) cnt[x - diff] * cnt[x + diff] * delta;
 d += (long long) base * cnt[x + 2 * diff] * delta;
 d += (long long) cnt[x - 2 * diff] * base * delta;
 total += d;
 cnt[x] += delta;
 out.push_back(total);
 }
 return out;
}

