def solution(matrix):
    n = len(matrix); mid = n // 2
    def is_y(r, c):
        if r <= mid and (c == r or c == n - 1 - r): return True
        return r > mid and c == mid
    best = float('inf')
    for y in range(3):
        for b in range(3):
            if y == b: continue
            cost = 0
            for i in range(n):
                for j in range(n):
                    if is_y(i, j):
                        if matrix[i][j] != y: cost += 1
                    else:
                        if matrix[i][j] != b: cost += 1
            best = min(best, cost)
    return best

class Solution {
