        for (int y = 0; y < 3; y++) for (int b = 0; b < 3; b++) {
            if (y == b) continue;
            int cost = 0;
            for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
                boolean inY = (i <= mid && (j == i || j == n - 1 - i)) || (i > mid && j == mid);
                if (inY) { if (matrix[i][j] != y) cost++; }
                else { if (matrix[i][j] != b) cost++; }
            }
            best = Math.min(best, cost);
        }
        return best;
    }
}

