def solution(laps):
    best = {}; active = set(); order = []
    for lap in laps:
        for entry in lap:
            name, t = entry.rsplit(maxsplit=1); t = int(t)
            if name in active or name not in best:
                active.add(name)
                if name not in best or t < best[name]: best[name] = t
        if len(active) <= 1:
            order.extend(sorted(active)); active.clear(); break
        slowest = max(best[d] for d in active)
        out = sorted(d for d in active if best[d] == slowest)
        order.extend(out)
        for d in out: active.remove(d)
    order.extend(sorted(active))
    return order

