                }
            }
            if (active.size() <= 1) { order.addAll(active); active.clear(); break; }
            int slowest = Integer.MIN_VALUE;
            for (String d : active) slowest = Math.max(slowest, best.get(d));
            List<String> out = new ArrayList<>();
            for (String d : active) if (best.get(d).intValue() == slowest) out.add(d);
            Collections.sort(out);
            order.addAll(out); active.removeAll(out);
        }
        order.addAll(new TreeSet<>(active));
        return order;
    }
}

vector<string> solution(vector<vector<string>>& laps) {
 unordered_map<string, int> best;
 set<string> active;
 vector<string> order;
 for (auto& lap : laps) {
 for (auto& entry : lap) {
 auto sp = entry.rfind(' ');
 string name = entry.substr(0, sp);
 int t = stoi(entry.substr(sp + 1));
 if (active.count(name) || !best.count(name)) {
 active.insert(name);
 if (!best.count(name) || t < best[name]) best[name] = t;
 }
 }
 if (active.size() <= 1) { for (auto& d : active) order.push_back(d); active.clear(); break; }
 int slowest = INT_MIN;
 for (auto& d : active) slowest = max(slowest, best[d]);
 vector<string> out;
 for (auto& d : active) if (best[d] == slowest) out.push_back(d);
 sort(out.begin(), out.end());
 for (auto& d : out) { order.push_back(d); active.erase(d); }
 }
 vector<string> rest(active.begin(), active.end());
 sort(rest.begin(), rest.end());
 for (auto& d : rest) order.push_back(d);
 return order;
}

