class Solution {
    int adventureToCountMoves(int numRows, int numColumns, int curRow, int curColumn, int[][] laserCoordinates) {
        java.util.HashSet<Integer> dr = new java.util.HashSet<>(), dc = new java.util.HashSet<>();
        for (int[] l : laserCoordinates) { dr.add(l[0]); dc.add(l[1]); }
        int up = 0, down = 0, left = 0, right = 0;
        for (int r = curRow - 1; r >= 1; r--) { if (dr.contains(r)) break; up++; }
        for (int r = curRow + 1; r <= numRows; r++) { if (dr.contains(r)) break; down++; }
        for (int c = curColumn - 1; c >= 1; c--) { if (dc.contains(c)) break; left++; }
        for (int c = curColumn + 1; c <= numColumns; c++) { if (dc.contains(c)) break; right++; }
        return Math.max(Math.max(up, down), Math.max(left, right));
    }
}

class Solution {
public:
    int adventureToCountMoves(int numRows, int numColumns, int curRow, int curColumn, vector<vector<int>>& laserCoordinates) {
        unordered_set<int> dr, dc;
        for (auto& l : laserCoordinates) { dr.insert(l[0]); dc.insert(l[1]); }
        int up = 0, down = 0, left = 0, right = 0;
        for (int r = curRow - 1; r >= 1; r--) { if (dr.count(r)) break; up++; }
        for (int r = curRow + 1; r <= numRows; r++) { if (dr.count(r)) break; down++; }
        for (int c = curColumn - 1; c >= 1; c--) { if (dc.count(c)) break; left++; }
        for (int c = curColumn + 1; c <= numColumns; c++) { if (dc.count(c)) break; right++; }
        return max({up, down, left, right});
    }
};

from sortedcontainers import SortedList

def arrayManipulation(queries, diff):
    sl = SortedList()
    res = []
    for q in queries:
        op = q[0]
        v = int(q[1:])
        if op == '+': sl.add(v)
        else: sl.remove(v)
        cnt = 0
        for i in range(len(sl) - 1):
            if sl[i + 1] - sl[i] <= diff:
                cnt += 1
        res.append(cnt)
    return res

class Solution {
    int[] arrayManipulation(String[] queries, int diff) {
        java.util.TreeMap<Integer, Integer> ms = new java.util.TreeMap<>();
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            char op = queries[i].charAt(0);
            int v = Integer.parseInt(queries[i].substring(1));
            if (op == '+') ms.merge(v, 1, Integer::sum);
            else if (ms.merge(v, -1, Integer::sum) == 0) ms.remove(v);
            int cnt = 0;
            Integer prev = null;
            for (var e : ms.entrySet()) {
                int k = e.getKey(), c = e.getValue();
                if (c >= 2) cnt += c - 1;
                if (prev != null && k - prev <= diff) cnt++;
                prev = k;
            }
            res[i] = cnt;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> arrayManipulation(vector<string>& queries, int diff) {
        multiset<int> ms;
        vector<int> res;
        for (auto& q : queries) {
            char op = q[0];
            int v = stoi(q.substr(1));
            if (op == '+') ms.insert(v);
            else ms.erase(ms.find(v));
            int cnt = 0;
            auto it = ms.begin();
            if (it != ms.end()) {
                int prev = *it;
                ++it;
                for (; it != ms.end(); ++it) {
                    if (*it - prev <= diff) cnt++;
                    prev = *it;
                }
            }
            res.push_back(cnt);
        }
        return res;
    }
};

