from collections import defaultdict

def countTriplesWithDiff(operations):
    cnt = defaultdict(int)
    res = []
    def count():
        keys = list(cnt.keys())
        total = 0
        # d = 0：从同一个值挑 3 个
        for v in keys:
            c = cnt[v]
            total += c * (c - 1) * (c - 2) // 6
        # d > 0：枚举 (y-d, y, y+d)
        for i, y in enumerate(keys):
            for x in keys:
                if x >= y: continue
                d = y - x
                z = y + d
                if z in cnt:
                    total += cnt[x] * cnt[y] * cnt[z]
        return total
    for op in operations:
        if op[0] == '+':
            v = int(op[1:])
            cnt[v] += 1
        else:
            v = int(op[1:])
            cnt[v] -= 1
            if cnt[v] == 0: del cnt[v]
        res.append(count())
    return res

class Solution {
    long[] countTriplesWithDiff(String[] operations) {
        java.util.HashMap<Long, Long> cnt = new java.util.HashMap<>();
        long[] res = new long[operations.length];
        for (int oi = 0; oi < operations.length; oi++) {
            char op = operations[oi].charAt(0);
            long v = Long.parseLong(operations[oi].substring(1));
            if (op == '+') cnt.merge(v, 1L, Long::sum);
            else if (cnt.merge(v, -1L, Long::sum) == 0) cnt.remove(v);
            long total = 0;
            for (long c : cnt.values()) total += c * (c - 1) * (c - 2) / 6;
            Long[] keys = cnt.keySet().toArray(new Long[0]);
            for (int i = 0; i < keys.length; i++)
                for (int j = 0; j < keys.length; j++) {
                    if (keys[i] >= keys[j]) continue;
                    long d = keys[j] - keys[i];
                    long z = keys[j] + d;
                    if (cnt.containsKey(z)) total += cnt.get(keys[i]) * cnt.get(keys[j]) * cnt.get(z);
                }
            res[oi] = total;
        }
        return res;
    }
}

class Solution {
public:
    vector<long long> countTriplesWithDiff(vector<string>& operations) {
        unordered_map<long long, long long> cnt;
        vector<long long> res;
        for (auto& op : operations) {
            char o = op[0];
            long long v = stoll(op.substr(1));
            if (o == '+') cnt[v]++;
            else { if (--cnt[v] == 0) cnt.erase(v); }
            long long total = 0;
            for (auto& [k, c] : cnt) total += c * (c - 1) * (c - 2) / 6;
            vector<long long> keys;
            for (auto& [k, c] : cnt) keys.push_back(k);
            for (size_t i = 0; i < keys.size(); i++)
                for (size_t j = 0; j < keys.size(); j++) {
                    if (keys[i] >= keys[j]) continue;
                    long long d = keys[j] - keys[i];
                    long long z = keys[j] + d;
                    if (cnt.count(z)) total += cnt[keys[i]] * cnt[keys[j]] * cnt[z];
                }
            res.push_back(total);
        }
        return res;
    }
};

def cyclicPairs(arr):
