        return min(s[i:] + s[:i] for i in range(len(s)))
    from collections import Counter
    groups = Counter(canonical(str(x)) for x in arr)
    total = 0
    for c in groups.values():
        total += c * (c - 1) // 2
    return total

class Solution {
    long cyclicPairs(int[] arr) {
        java.util.HashMap<String, Long> groups = new java.util.HashMap<>();
        for (int x : arr) {
            String s = String.valueOf(x);
            String best = s;
            for (int i = 1; i < s.length(); i++) {
                String r = s.substring(i) + s.substring(0, i);
                if (r.compareTo(best) < 0) best = r;
            }
            groups.merge(best, 1L, Long::sum);
        }
        long total = 0;
        for (long c : groups.values()) total += c * (c - 1) / 2;
        return total;
    }
}

