class Solution {
    int[] fastestSFCommute(String[] grid, int[] times, int[] costs) {
        int R = grid.length, C = R > 0 ? grid[0].length() : 0;
        int sr = 0, sc = 0, dr = 0, dc = 0;
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) {
            if (grid[i].charAt(j) == 'S') { sr = i; sc = j; }
            else if (grid[i].charAt(j) == 'D') { dr = i; dc = j; }
        }
        int[] best = {-1, -1, -1};
        int bestT = Integer.MAX_VALUE;
        for (int mode = 1; mode <= 4; mode++) {
            int[][] dist = new int[R][C];
            for (int[] row : dist) java.util.Arrays.fill(row, -1);
            dist[sr][sc] = 0;
            java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
            q.add(new int[]{sr, sc});
            while (!q.isEmpty()) {
                int[] x = q.poll();
                int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
                for (int[] d : dirs) {
                    int nr = x[0] + d[0], nc = x[1] + d[1];
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || dist[nr][nc] != -1) continue;
                    char ch = grid[nr].charAt(nc);
                    if (ch == 'S' || ch == 'D' || ch - '0' == mode) {
                        dist[nr][nc] = dist[x[0]][x[1]] + 1;
                        q.add(new int[]{nr, nc});
                    }
                }
            }
            int d = dist[dr][dc];
            if (d < 0) continue;
            int t = d * times[mode - 1], cst = d * costs[mode - 1];
            if (t < bestT || (t == bestT && cst < best[2])) {
                bestT = t;
                best = new int[]{mode, t, cst};
            }
        }
        return best;
    }
}

class Solution {
public:
    vector<int> fastestSFCommute(vector<string>& grid, vector<int>& times, vector<int>& costs) {
        int R = grid.size(), C = R ? grid[0].size() : 0;
        int sr = 0, sc = 0, dr = 0, dc = 0;
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'S') { sr = i; sc = j; }
            else if (grid[i][j] == 'D') { dr = i; dc = j; }
        }
        vector<int> best = {-1, -1, -1};
        int bestT = INT_MAX;
        int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
        for (int mode = 1; mode <= 4; mode++) {
            vector<vector<int>> dist(R, vector<int>(C, -1));
            dist[sr][sc] = 0;
            queue<pair<int,int>> q;
            q.push({sr, sc});
            while (!q.empty()) {
                auto [r, c] = q.front(); q.pop();
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr < 0 || nr >= R || nc < 0 || nc >= C || dist[nr][nc] != -1) continue;
                    char ch = grid[nr][nc];
                    if (ch == 'S' || ch == 'D' || ch - '0' == mode) {
                        dist[nr][nc] = dist[r][c] + 1;
                        q.push({nr, nc});
                    }
                }
            }
            int d = dist[dr][dc];
            if (d < 0) continue;
            int t = d * times[mode - 1], cst = d * costs[mode - 1];
            if (t < bestT || (t == bestT && cst < best[2])) {
                bestT = t;
                best = {mode, t, cst};
            }
        }
        return best;
    }
};

class Solution {
    int findFirstAnagramIndex(String s, String pattern) {
        int m = pattern.length(), n = s.length();
        if (m > n) return -1;
        int[] pcnt = new int[26], wcnt = new int[26];
        for (char c : pattern.toCharArray()) pcnt[c - 'a']++;
        for (int i = 0; i < m; i++) wcnt[s.charAt(i) - 'a']++;
        for (int i = 0; i + m <= n; i++) {
            if (java.util.Arrays.equals(wcnt, pcnt)) return i;
            if (i + m < n) {
                wcnt[s.charAt(i) - 'a']--;
                wcnt[s.charAt(i + m) - 'a']++;
            }
        }
        return -1;
    }
}

class Solution {
public:
    int findFirstAnagramIndex(string s, string pattern) {
        int m = pattern.size(), n = s.size();
        if (m > n) return -1;
        int pcnt[26] = {0}, wcnt[26] = {0};
        for (char c : pattern) pcnt[c - 'a']++;
        for (int i = 0; i < m; i++) wcnt[s[i] - 'a']++;
        for (int i = 0; i + m <= n; i++) {
            bool eq = true;
            for (int j = 0; j < 26; j++) if (wcnt[j] != pcnt[j]) { eq = false; break; }
            if (eq) return i;
            if (i + m < n) {
                wcnt[s[i] - 'a']--;
                wcnt[s[i + m] - 'a']++;
            }
        }
        return -1;
    }
};

def gotoLargestBucket(commands):
    buckets = {}
    cur = None
    for cmd in commands:
        parts = cmd.split()
        if parts[0] == "goto":
            cur = parts[1]
            if cur not in buckets: buckets[cur] = set()
        elif parts[0] == "create":
            buckets[cur].add(parts[1])
    best = max(buckets, key=lambda b: len(buckets[b]))
    return best

class Solution {
    String gotoLargestBucket(String[] commands) {
        java.util.HashMap<String, java.util.HashSet<String>> buckets = new java.util.HashMap<>();
        String cur = null;
        for (String cmd : commands) {
            String[] p = cmd.split(" ");
            if (p[0].equals("goto")) {
                cur = p[1];
                buckets.putIfAbsent(cur, new java.util.HashSet<>());
            } else if (p[0].equals("create")) {
                buckets.get(cur).add(p[1]);
            }
        }
        String best = null;
        int bestSize = -1;
        for (var e : buckets.entrySet()) {
            if (e.getValue().size() > bestSize) {
                bestSize = e.getValue().size();
                best = e.getKey();
            }
        }
        return best;
    }
}

class Solution {
public:
    string gotoLargestBucket(vector<string>& commands) {
        unordered_map<string, unordered_set<string>> buckets;
        string cur;
        for (auto& cmd : commands) {
            stringstream ss(cmd);
            string op, arg;
            ss >> op >> arg;
            if (op == "goto") { cur = arg; if (!buckets.count(cur)) buckets[cur] = {}; }
            else if (op == "create") buckets[cur].insert(arg);
        }
        string best;
        int bestSize = -1;
        for (auto& [k, v] : buckets) {
            if ((int) v.size() > bestSize) { bestSize = v.size(); best = k; }
        }
        return best;
    }
};

