def longestCommonPrefix(firstArray, secondArray):
    pre = set()
    for x in secondArray:
        s = str(x)
        for i in range(1, len(s) + 1):
            pre.add(s[:i])
    best = 0
    for x in firstArray:
        s = str(x)
        for i in range(len(s), 0, -1):
            if s[:i] in pre:
                if i > best: best = i
                break
    return best

class Solution {
    int longestCommonPrefix(int[] firstArray, int[] secondArray) {
        java.util.HashSet<String> pre = new java.util.HashSet<>();
        for (int x : secondArray) {
            String s = String.valueOf(x);
            for (int i = 1; i <= s.length(); i++) pre.add(s.substring(0, i));
        }
        int best = 0;
        for (int x : firstArray) {
            String s = String.valueOf(x);
            for (int i = s.length(); i >= 1; i--) {
                if (pre.contains(s.substring(0, i))) {
                    if (i > best) best = i;
                    break;
                }
            }
        }
        return best;
    }
}

class Solution {
