        }
        int best = 0;
        for (int x : firstArray) {
            string s = to_string(x);
            for (int i = s.size(); i >= 1; i--) {
                if (pre.count(s.substr(0, i))) {
                    if (i > best) best = i;
                    break;
                }
            }
        }
        return best;
    }
};

def pushBoxes(board):
    R = len(board)
    C = len(board[0]) if R > 0 else 0
    b = [list(row) for row in board]
    # 向右推
    for r in range(R):
        write = C - 1
        for c in range(C - 1, -1, -1):
            if b[r][c] == '*':
                write = c - 1
            elif b[r][c] == '#':
                b[r][c] = '.'
                b[r][write] = '#'
                write -= 1
    # 向下推
    for c in range(C):
        write = R - 1
        for r in range(R - 1, -1, -1):
            if b[r][c] == '*':
                write = r - 1
            elif b[r][c] == '#':
                b[r][c] = '.'
                b[write][c] = '#'
                write -= 1
    return [''.join(row) for row in b]

class Solution {
    char[][] pushBoxes(char[][] board) {
        int R = board.length, C = R > 0 ? board[0].length : 0;
        char[][] b = new char[R][C];
        for (int i = 0; i < R; i++) b[i] = board[i].clone();
        for (int r = 0; r < R; r++) {
            int write = C - 1;
            for (int c = C - 1; c >= 0; c--) {
                if (b[r][c] == '*') write = c - 1;
                else if (b[r][c] == '#') {
                    b[r][c] = '.';
                    b[r][write] = '#';
                    write--;
                }
            }
        }
        for (int c = 0; c < C; c++) {
            int write = R - 1;
            for (int r = R - 1; r >= 0; r--) {
                if (b[r][c] == '*') write = r - 1;
                else if (b[r][c] == '#') {
                    b[r][c] = '.';
                    b[write][c] = '#';
                    write--;
                }
            }
        }
        return b;
    }
}

