def stringRequests(binaryString, requests):
    n = len(binaryString)
    zeros = [0] * (n + 1)
    for i in range(n):
        zeros[i + 1] = zeros[i] + (1 if binaryString[i] == '0' else 0)
    flipped = False
    res = []
    for q in requests:
        if q == "flip":
            flipped = not flipped
        else:
            k = int(q.split(":")[1])
            z = zeros[k + 1]
            if flipped:
                res.append((k + 1) - z)
            else:
                res.append(z)
    return res

class Solution {
    int[] stringRequests(String binaryString, String[] requests) {
        int n = binaryString.length();
        int[] zeros = new int[n + 1];
        for (int i = 0; i < n; i++) zeros[i + 1] = zeros[i] + (binaryString.charAt(i) == '0' ? 1 : 0);
        boolean flipped = false;
        java.util.List<Integer> res = new java.util.ArrayList<>();
        for (String q : requests) {
            if (q.equals("flip")) flipped = !flipped;
            else {
                int k = Integer.parseInt(q.split(":")[1]);
                int z = zeros[k + 1];
                res.add(flipped ? (k + 1) - z : z);
            }
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

