                int z = zeros[k + 1];
                res.push_back(flipped ? (k + 1) - z : z);
            }
        }
        return res;
    }
};

class Solution {
    int subarrayCounting(int[] numbers, int[] pattern) {
        int n = numbers.length, m = pattern.length, cnt = 0;
        for (int i = 0; i <= n - m - 1; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                int sign = Integer.compare(numbers[i + j + 1], numbers[i + j]);
                if (sign != pattern[j]) { ok = false; break; }
            }
            if (ok) cnt++;
        }
        return cnt;
    }
}

