def romanizer(numbers: List[int]) -> List[str]:
    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
             (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
             (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    def to_roman(n: int) -> str:
        out = []
        for v, s in table:
            while n >= v:
                out.append(s); n -= v
        return "".join(out)
    return [to_roman(n) for n in numbers]

