def get_maximum_distance(location: List[int], k: int) -> int:
    loc = sorted(location)
    n = len(loc)
    if k >= n:
        return 0
    def can(d: int) -> bool:
        clusters = 1
        a = loc[0]
        for x in loc:
            if x - a > 2 * d:
                clusters += 1
                a = x
                if clusters > k:
                    return False
        return True
    lo, hi = 0, (loc[-1] - loc[0] + 1) // 2 + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

import java.util.*;

class Solution {
    public int getMaximumDistance(int[] location, int k) {
        int[] loc = location.clone();
        Arrays.sort(loc);
        int n = loc.length;
        if (k >= n) return 0;
        int lo = 0, hi = (loc[n - 1] - loc[0] + 1) / 2 + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (can(loc, k, mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    boolean can(int[] loc, int k, int d) {
        int clusters = 1, a = loc[0];
        for (int x : loc) {
            if (x - a > 2L * d) {
                clusters++;
                a = x;
                if (clusters > k) return false;
            }
        }
        return true;
    }
}

