                bool midOk = (l == 0 || r == m - 1) || (prefix[l - 1] < suffix[r + 1]);
                if (leftOk && rightOk && midOk) best = min(best, r - l + 1);
            }
        return best == m ? 0 : best;
    }
};

from typing import List

def get_final_price(price: List[int], queries: List[List[int]]) -> List[int]:
    arr = list(price)
    for q in queries:
        if q[0] == 1:
            arr[q[1] - 1] = q[2]
        else:
            v = q[1]
            for i in range(len(arr)):
                if arr[i] < v:
                    arr[i] = v
    return arr

class Solution {
    int[] getFinalPrice(int[] price, int[][] queries) {
        int[] arr = price.clone();
        for (int[] q : queries) {
            if (q[0] == 1) arr[q[1] - 1] = q[2];
            else for (int i = 0; i < arr.length; i++) if (arr[i] < q[1]) arr[i] = q[1];
        }
        return arr;
    }
}

class Solution {
public:
    vector<int> getFinalPrice(vector<int>& price, vector<vector<int>>& queries) {
        vector<int> arr = price;
        for (auto& q : queries) {
            if (q[0] == 1) arr[q[1] - 1] = q[2];
            else for (int& x : arr) if (x < q[1]) x = q[1];
        }
        return arr;
    }
};

from typing import List

def get_sizes_of_friends_groups(queryType: List[str], student1: List[int],
                                  student2: List[int], n: int) -> int:
    parent = list(range(n + 1))
    size = [1] * (n + 1)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb: return
        if size[ra] < size[rb]: ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
    total = 0
    for q, s1, s2 in zip(queryType, student1, student2):
        if q == "Friend":
            union(s1, s2)
        else:
            r1, r2 = find(s1), find(s2)
            if r1 == r2:
                total += size[r1] * 2
            else:
                total += size[r1] + size[r2]
    return total

class Solution {
    int[] parent, size;
    int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    void union_(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
    int getSizesOfFriendsGroups(String[] queryType, int[] s1, int[] s2, int n) {
        parent = new int[n + 1];
        size = new int[n + 1];
        for (int i = 0; i <= n; i++) { parent[i] = i; size[i] = 1; }
        long total = 0;
        for (int i = 0; i < queryType.length; i++) {
            if (queryType[i].equals("Friend")) union_(s1[i], s2[i]);
            else {
                int r1 = find(s1[i]), r2 = find(s2[i]);
                total += (r1 == r2) ? 2L * size[r1] : (long) size[r1] + size[r2];
            }
        }
        return (int) total;
    }
}

class Solution {
public:
    vector<int> parent, sz;
    int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    }
    int getSizesOfFriendsGroups(vector<string>& queryType, vector<int>& s1, vector<int>& s2, int n) {
        parent.assign(n + 1, 0); sz.assign(n + 1, 1);
        iota(parent.begin(), parent.end(), 0);
        long long total = 0;
        for (size_t i = 0; i < queryType.size(); ++i) {
            if (queryType[i] == "Friend") unite(s1[i], s2[i]);
            else {
                int r1 = find(s1[i]), r2 = find(s2[i]);
                total += (r1 == r2) ? 2LL * sz[r1] : (long long) sz[r1] + sz[r2];
            }
        }
        return (int) total;
    }
};

import java.util.*;

class Solution {
    String[] solveMaximizeChefDishProfit(String input) {
        String[] lines = input.strip().split("\n");
        int idx = 0;
        int n = Integer.parseInt(lines[idx++].trim());
        int[] chef = Arrays.stream(lines[idx++].trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        int m = Integer.parseInt(lines[idx++].trim());
        int[] diffs = Arrays.stream(lines[idx++].trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        int[] profits = Arrays.stream(lines[idx++].trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> diffs[a] - diffs[b]);
        int[] ds = new int[m]; int[] maxP = new int[m];
        int cur = 0;
        for (int i = 0; i < m; i++) {
            ds[i] = diffs[order[i]];
            cur = Math.max(cur, profits[order[i]]);
            maxP[i] = cur;
        }
        long total = 0;
        for (int s : chef) {
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ds[mid] <= s) lo = mid + 1; else hi = mid;
            }
            if (lo > 0) total += maxP[lo - 1];
        }
        return new String[]{Long.toString(total)};
    }
}

class Solution {
public:
    vector<string> solveMaximizeChefDishProfit(string input) {
        vector<string> lines;
        string cur;
        for (char c : input + "\n") {
            if (c == '\n') { if (!cur.empty()) lines.push_back(cur); cur.clear(); }
            else cur += c;
        }
        int idx = 0;
        int n = stoi(lines[idx++]);
        vector<int> chef;
        {
            stringstream ss(lines[idx++]);
            int x;
            while (ss >> x) chef.push_back(x);
        }
        int m = stoi(lines[idx++]);
        vector<int> diffs, profits;
        {
            stringstream ss(lines[idx++]);
            int x;
            while (ss >> x) diffs.push_back(x);
        }
        {
            stringstream ss(lines[idx++]);
            int x;
            while (ss >> x) profits.push_back(x);
        }
        vector<pair<int, int>> pairs;
        for (int i = 0; i < m; i++) pairs.push_back({diffs[i], profits[i]});
        sort(pairs.begin(), pairs.end());
        vector<int> maxP(m);
        int mx = 0;
        for (int i = 0; i < m; i++) { mx = max(mx, pairs[i].second); maxP[i] = mx; }
        long long total = 0;
        for (int s : chef) {
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (pairs[mid].first <= s) lo = mid + 1; else hi = mid;
            }
            if (lo > 0) total += maxP[lo - 1];
        }
        return {to_string(total)};
    }
};

from typing import List

def get_order_priorities(orderIds: List[int]) -> List[int]:
    arr = list(orderIds)
    res = []
    while arr:
        candidates = []
        n = len(arr)
        for i in range(n):
            left = arr[i - 1] if i > 0 else float("-inf")
            right = arr[i + 1] if i + 1 < n else float("-inf")
            if arr[i] > left and arr[i] > right:
                candidates.append(i)
        if candidates:
            best = max(candidates, key=lambda i: (-arr[i], i))
        else:
            best = max(range(n), key=lambda i: (-arr[i], i))
        res.append(arr[best])
        arr.pop(best)
    return res

import java.util.*;

class Solution {
    int[] getOrderPriorities(int[] orderIds) {
        List<Integer> arr = new ArrayList<>();
        for (int x : orderIds) arr.add(x);
        List<Integer> res = new ArrayList<>();
        while (!arr.isEmpty()) {
            int best = -1, bestVal = Integer.MIN_VALUE;
            int n = arr.size();
            List<Integer> cand = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int left = i > 0 ? arr.get(i - 1) : Integer.MIN_VALUE;
                int right = i + 1 < n ? arr.get(i + 1) : Integer.MIN_VALUE;
                if (arr.get(i) > left && arr.get(i) > right) cand.add(i);
            }
            List<Integer> source = cand.isEmpty() ? null : cand;
            if (source == null) {
                source = new ArrayList<>();
                for (int i = 0; i < n; i++) source.add(i);
            }
            for (int i : source) if (arr.get(i) > bestVal) { bestVal = arr.get(i); best = i; }
            res.add(arr.get(best));
            arr.remove(best);
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> getOrderPriorities(vector<int>& orderIds) {
        vector<int> arr = orderIds, res;
        while (!arr.empty()) {
            int n = arr.size();
            vector<int> cand;
            for (int i = 0; i < n; i++) {
                int left = i > 0 ? arr[i - 1] : INT_MIN;
                int right = i + 1 < n ? arr[i + 1] : INT_MIN;
                if (arr[i] > left && arr[i] > right) cand.push_back(i);
            }
            if (cand.empty()) for (int i = 0; i < n; i++) cand.push_back(i);
            int best = cand[0];
            for (int i : cand) if (arr[i] > arr[best]) best = i;
            res.push_back(arr[best]);
            arr.erase(arr.begin() + best);
        }
        return res;
    }
};

from typing import List
from collections import deque

def team_formation(score: List[int], team_size: int, k: int) -> int:
    dq = deque(score)
    total = 0
    for _ in range(team_size):
        if not dq:
            break
        front = list(dq)[:min(k, len(dq))]
        back = list(dq)[-min(k, len(dq)):]
        best_val = -float("inf")
        best_pos = None  # 'front' or 'back', index
        for i, v in enumerate(front):
            if v > best_val:
                best_val = v
                best_pos = ('front', i)
        for i, v in enumerate(back):
            real_idx = len(dq) - len(back) + i
            if v > best_val:
                best_val = v
                best_pos = ('back', real_idx)
        if best_pos is None:
            break
        total += best_val
        if best_pos[0] == 'front':
            arr = list(dq)
            arr.pop(best_pos[1])
            dq = deque(arr)
        else:
            arr = list(dq)
            arr.pop(best_pos[1])
            dq = deque(arr)
    return total

import java.util.*;

class Solution {
    long teamFormation(int[] score, int teamSize, int k) {
        List<Integer> arr = new ArrayList<>();
        for (int x : score) arr.add(x);
        long total = 0;
        for (int t = 0; t < teamSize && !arr.isEmpty(); t++) {
            int n = arr.size();
            int kk = Math.min(k, n);
            int bestIdx = -1; int bestVal = Integer.MIN_VALUE;
            for (int i = 0; i < kk; i++) if (arr.get(i) > bestVal) { bestVal = arr.get(i); bestIdx = i; }
            for (int i = n - kk; i < n; i++) if (arr.get(i) > bestVal) { bestVal = arr.get(i); bestIdx = i; }
            total += bestVal;
            arr.remove(bestIdx);
        }
        return total;
    }
}

class Solution {
public:
    long long teamFormation(vector<int>& score, int teamSize, int k) {
        vector<int> arr = score;
        long long total = 0;
        for (int t = 0; t < teamSize && !arr.empty(); t++) {
            int n = arr.size();
            int kk = min(k, n);
            int bestIdx = -1, bestVal = INT_MIN;
            for (int i = 0; i < kk; i++) if (arr[i] > bestVal) { bestVal = arr[i]; bestIdx = i; }
            for (int i = n - kk; i < n; i++) if (arr[i] > bestVal) { bestVal = arr[i]; bestIdx = i; }
            total += bestVal;
            arr.erase(arr.begin() + bestIdx);
        }
        return total;
    }
};

class Solution {
    int[] balloonColorPairs(int length, int[][] queries) {
        int[] arr = new int[length];
        int pairs = 0;
        int[] res = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int idx = queries[q][0], color = queries[q][1];
            if (arr[idx] != 0) {
                if (idx - 1 >= 0 && arr[idx - 1] == arr[idx]) pairs--;
                if (idx + 1 < length && arr[idx + 1] == arr[idx]) pairs--;
            }
            arr[idx] = color;
            if (idx - 1 >= 0 && arr[idx - 1] == color && arr[idx - 1] != 0) pairs++;
            if (idx + 1 < length && arr[idx + 1] == color && arr[idx + 1] != 0) pairs++;
            res[q] = pairs;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> balloonColorPairs(int length, vector<vector<int>>& queries) {
        vector<int> arr(length, 0);
        int pairs = 0;
        vector<int> res;
        for (auto& q : queries) {
            int idx = q[0], color = q[1];
            if (arr[idx] != 0) {
                if (idx - 1 >= 0 && arr[idx - 1] == arr[idx]) pairs--;
                if (idx + 1 < length && arr[idx + 1] == arr[idx]) pairs--;
            }
            arr[idx] = color;
            if (idx - 1 >= 0 && arr[idx - 1] == color && arr[idx - 1] != 0) pairs++;
            if (idx + 1 < length && arr[idx + 1] == color && arr[idx + 1] != 0) pairs++;
            res.push_back(pairs);
        }
        return res;
    }
};

class Solution {
    int[] collectSticks(int[] forest, int bird) {
        List<Integer> res = new ArrayList<>();
        int total = 0, direction = 1;
        while (total < 100) {
            int i = bird + direction;
            while (i >= 0 && i < forest.length && forest[i] == 0) i += direction;
            if (i < 0 || i >= forest.length) break;
            res.add(i);
            total += forest[i];
            forest[i] = 0;
            direction = -direction;
        }
        int[] out = new int[res.size()];
        for (int k = 0; k < res.size(); k++) out[k] = res.get(k);
        return out;
    }
}

class Solution {
public:
    vector<int> collectSticks(vector<int>& forest, int bird) {
        vector<int> res;
        int total = 0, direction = 1;
        while (total < 100) {
            int i = bird + direction;
            while (i >= 0 && i < (int)forest.size() && forest[i] == 0) i += direction;
            if (i < 0 || i >= (int)forest.size()) break;
            res.push_back(i);
            total += forest[i];
            forest[i] = 0;
            direction = -direction;
        }
        return res;
    }
};

class Solution {
    int[][] popBubbles(int[][] grid, int[][] operations) {
        int m = grid.length, n = grid[0].length;
        int[][] diags = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};
        for (int[] op : operations) {
            int r = op[0], c = op[1];
            if (grid[r][c] == 0) continue;
            int color = grid[r][c];
            Deque<int[]> q = new ArrayDeque<>();
            q.add(new int[]{r, c});
            grid[r][c] = 0;
            while (!q.isEmpty()) {
                int[] p = q.poll();
                for (int[] d : diags) {
                    int ni = p[0] + d[0], nj = p[1] + d[1];
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == color) {
                        grid[ni][nj] = 0;
                        q.add(new int[]{ni, nj});
                    }
                }
            }
            for (int c2 = 0; c2 < n; c2++) {
                List<Integer> col = new ArrayList<>();
                for (int r2 = 0; r2 < m; r2++) if (grid[r2][c2] != 0) col.add(grid[r2][c2]);
                int k = m - col.size();
                for (int r2 = 0; r2 < m; r2++) grid[r2][c2] = r2 < k ? 0 : col.get(r2 - k);
            }
        }
        return grid;
    }
}

class Solution {
public:
    vector<vector<int>> popBubbles(vector<vector<int>>& grid, vector<vector<int>>& operations) {
        int m = grid.size(), n = grid[0].size();
        int diags[4][2] = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};
        for (auto& op : operations) {
            int r = op[0], c = op[1];
            if (grid[r][c] == 0) continue;
            int color = grid[r][c];
            queue<pair<int,int>> q;
            q.push({r, c});
            grid[r][c] = 0;
            while (!q.empty()) {
                auto [i, j] = q.front(); q.pop();
                for (auto& d : diags) {
                    int ni = i + d[0], nj = j + d[1];
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == color) {
                        grid[ni][nj] = 0;
                        q.push({ni, nj});
                    }
                }
            }
            for (int c2 = 0; c2 < n; c2++) {
                vector<int> col;
                for (int r2 = 0; r2 < m; r2++) if (grid[r2][c2] != 0) col.push_back(grid[r2][c2]);
                int k = m - col.size();
                for (int r2 = 0; r2 < m; r2++) grid[r2][c2] = r2 < k ? 0 : col[r2 - k];
            }
        }
        return grid;
    }
};

class Solution {
    static String solution(String source) {
        int n = source.length(), bestLen = 0, bestStart = -1;
        char bestChar = ' ';
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && source.charAt(j) == source.charAt(i)) j++;
            int curLen = j - i;
            if (curLen > bestLen || (curLen == bestLen && i > bestStart)) {
                bestLen = curLen; bestChar = source.charAt(i); bestStart = i;
            }
            i = j;
        }
        return "" + bestChar + bestLen;
    }
}

