class Solution {
    public long[][] assignPins(int[] pins, int k) {
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        for (int i = 0; i < k; i++) pq.add(new long[]{0, i});
        long[] heights = new long[k];
        long[] assigned = new long[pins.length];
        for (int j = 0; j < pins.length; j++) {
            long[] top = pq.poll();
            int idx = (int) top[1];
            assigned[j] = idx;
            heights[idx] += pins[j];
            pq.add(new long[]{heights[idx], idx});
        }
        return new long[][]{assigned, heights};
    }
}

