from collections import deque
from typing import List

def bubble_explosion(bubbles: List[List[int]]) -> List[List[int]]:
    if not bubbles or not bubbles[0]:
        return bubbles
    r, c = len(bubbles), len(bubbles[0])
    grid = [row[:] for row in bubbles]
    seen = [[False] * c for _ in range(r)]
    to_pop = [[False] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if seen[i][j] or grid[i][j] == 0:
                continue
            comp: list = []
            q = deque([(i, j)])
            seen[i][j] = True
            color = grid[i][j]
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < r and 0 <= ny < c and not seen[nx][ny] and grid[nx][ny] == color:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            if len(comp) >= 3:
                for x, y in comp:
                    to_pop[x][y] = True
    for i in range(r):
        for j in range(c):
            if to_pop[i][j]:
                grid[i][j] = 0
    # gravity per column
    for j in range(c):
        col = [grid[i][j] for i in range(r) if grid[i][j] != 0]
        for i in range(r):
            grid[i][j] = 0
        for k, v in enumerate(col):
            grid[r - len(col) + k][j] = v
    return grid

import java.util.*;

class Solution {
    public int[][] bubbleExplosion(int[][] bubbles) {
        int r = bubbles.length, c = bubbles[0].length;
        int[][] grid = new int[r][c];
        for (int i = 0; i < r; i++) grid[i] = bubbles[i].clone();
        boolean[][] seen = new boolean[r][c], pop = new boolean[r][c];
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) {
            if (seen[i][j] || grid[i][j] == 0) continue;
            List<int[]> comp = new ArrayList<>();
            Deque<int[]> q = new ArrayDeque<>();
            q.add(new int[]{i, j}); seen[i][j] = true;
            int color = grid[i][j];
            while (!q.isEmpty()) {
                int[] p = q.poll(); comp.add(p);
                for (int k = 0; k < 4; k++) {
                    int nr = p[0] + dr[k], nc = p[1] + dc[k];
                    if (nr >= 0 && nr < r && nc >= 0 && nc < c && !seen[nr][nc] && grid[nr][nc] == color) {
                        seen[nr][nc] = true; q.add(new int[]{nr, nc});
                    }
                }
            }
            if (comp.size() >= 3) for (int[] p : comp) pop[p[0]][p[1]] = true;
        }
        for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) if (pop[i][j]) grid[i][j] = 0;
        for (int j = 0; j < c; j++) {
            List<Integer> col = new ArrayList<>();
            for (int i = 0; i < r; i++) if (grid[i][j] != 0) col.add(grid[i][j]);
            for (int i = 0; i < r; i++) grid[i][j] = 0;
            for (int k = 0; k < col.size(); k++) grid[r - col.size() + k][j] = col.get(k);
        }
        return grid;
    }
}

