def minimize_expression(expression: str) -> str:
    n = len(expression)

    def safe_eval(s: str):
        try:
            return eval(s)
        except Exception:
            return None

    best_val = safe_eval(expression)
    best_str = expression
    for i in range(n):
        for j in range(i + 1, n + 1):
            # candidate: insert "(" before i, ")" after j
            cand = expression[:i] + "(" + expression[i:j] + ")" + expression[j:]
            v = safe_eval(cand)
            if v is not None and (best_val is None or v < best_val):
                best_val = v
                best_str = cand
    return best_str

