class Solution {
    public String minimizeExpression(String expression) {
        ScriptEngine engine = new ScriptEngineManager().getEngineByName("js");
        try {
            double bestVal = ((Number) engine.eval(expression)).doubleValue();
            String best = expression;
            int n = expression.length();
            for (int i = 0; i < n; i++) for (int j = i + 1; j <= n; j++) {
                String cand = expression.substring(0, i) + "(" + expression.substring(i, j) + ")" + expression.substring(j);
                try {
                    double v = ((Number) engine.eval(cand)).doubleValue();
                    if (v < bestVal) { bestVal = v; best = cand; }
                } catch (Exception ignored) {}
            }
            return best;
        } catch (Exception e) { return expression; }
    }
}

