// Simple recursive-descent evaluator for digits and '+'
class Solution {
    long long parseExpr(const string& s, size_t& i);
    long long parseTerm(const string& s, size_t& i) {
        if (i < s.size() && s[i] == '(') {
            i++;
            long long v = parseExpr(s, i);
            if (i < s.size() && s[i] == ')') i++;
            return v;
        }
        long long v = 0;
        while (i < s.size() && isdigit(s[i])) { v = v * 10 + (s[i] - '0'); i++; }
        return v;
    }
public:
    string minimizeExpression(string expression) {
        auto eval = [&](const string& s) -> long long {
            size_t i = 0; return parseExpr(s, i);
        };
        long long bestVal = eval(expression);
        string best = expression;
        int n = expression.size();
        for (int i = 0; i < n; i++) for (int j = i + 1; j <= n; j++) {
            string cand = expression.substr(0, i) + "(" + expression.substr(i, j - i) + ")" + expression.substr(j);
            try { long long v = eval(cand); if (v < bestVal) { bestVal = v; best = cand; } } catch (...) {}
        }
        return best;
    }
};

long long Solution::parseExpr(const string& s, size_t& i) {
    long long v = parseTerm(s, i);
    while (i < s.size() && s[i] == '+') { i++; v += parseTerm(s, i); }
    return v;
}

