class Solution {
    public int travelDistance(int finish, int[] scooters) {
        int[] s = Arrays.stream(scooters).filter(x -> x >= 0 && x < finish).sorted().toArray();
        int pos = 0, total = 0;
        while (pos < finish) {
            int lo = 0, hi = s.length;
            while (lo < hi) { int m = (lo + hi) / 2; if (s[m] >= pos) hi = m; else lo = m + 1; }
            if (lo >= s.length) break;
            int scoot = s[lo];
            int rideTo = Math.min(scoot + 10, finish);
            total += rideTo - scoot;
            pos = rideTo;
        }
        return total;
    }
}

