class Solution {
    int[] minimalOperations(String[] words) {
        int[] res = new int[words.length];
        for (int k = 0; k < words.length; k++) {
            String w = words[k];
            int cnt = 0, i = 0;
            while (i < w.length()) {
                int j = i;
                while (j < w.length() && w.charAt(j) == w.charAt(i)) j++;
                cnt += (j - i) / 2;
                i = j;
            }
            res[k] = cnt;
        }
        return res;
    }
}

