class Solution {
    int minimizePathValue(int N, int[][] edges, int source, int destination) {
        List<int[]>[] adj = new List[N + 1];
        for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) { adj[e[0]].add(new int[]{e[1], e[2]}); adj[e[1]].add(new int[]{e[0], e[2]}); }
        int[] dist = new int[N + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.add(new int[]{0, source});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > dist[u]) continue;
            if (u == destination) return d;
            for (int[] e : adj[u]) {
                int nd = Math.max(d, e[1]);
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    pq.add(new int[]{nd, e[0]});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int minimizePathValue(int N, vector<vector<int>>& edges, int source, int destination) {
        vector<vector<pair<int,int>>> adj(N + 1);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        vector<int> dist(N + 1, INT_MAX);
        dist[source] = 0;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
        pq.push({0, source});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            if (u == destination) return d;
            for (auto& [v, w] : adj[u]) {
                int nd = max(d, w);
                if (nd < dist[v]) { dist[v] = nd; pq.push({nd, v}); }
            }
        }
        return -1;
    }
};

def longestSegmentsAfterQueries(N: int, queries: list[int]) -> list[list[int]]:
    available = set(range(N))
    results = []
    for q in queries:
        available.discard(q)
        best_len, best_start = 0, -1
        cur_len, cur_start = 0, -1
        for p in sorted(available):
            if cur_start != -1 and p == cur_start + cur_len:
                cur_len += 1
            else:
                cur_len, cur_start = 1, p
            if cur_len > best_len:
                best_len, best_start = cur_len, cur_start
        results.append(list(range(best_start, best_start + best_len)) if best_len > 0 else [])
    return results

import java.util.*;

class Solution {
    static List<List<Integer>> longestSegmentsAfterQueries(int N, int[] queries) {
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < N; i++) available.add(i);
        List<List<Integer>> results = new ArrayList<>();
        for (int q : queries) {
            available.remove(q);
            int bestLen = 0, bestStart = -1, curLen = 0, curStart = -1;
            Integer prev = null;
            for (int p : available) {
                if (prev != null && p == prev + 1) curLen++;
                else { curLen = 1; curStart = p; }
                if (curLen > bestLen) { bestLen = curLen; bestStart = curStart; }
                prev = p;
            }
            List<Integer> seg = new ArrayList<>();
            for (int i = 0; i < bestLen; i++) seg.add(bestStart + i);
            results.add(seg);
        }
        return results;
    }
}

