 if (abs(cr - i) + abs(cc - j) < radius) s += matrix[i][j];
 if (!found || s > best) { best = s; found = true; }
 }
 return best;
}

def formatParagraphs(paragraphs):
    TAG = {'bold': 'b', 'italic': 'i', 'underline': 'u', 'p': None}
    def render(chunk):
        kind, content = chunk[0], chunk[1]
        if isinstance(content, list):
            inner = ''.join(render(c) for c in content)
        else:
            inner = content
        tag = TAG.get(kind)
        return f'<{tag}>{inner}</{tag}>' if tag else inner
    return [f'<p>{"".join(render(c) for c in para)}</p>' for para in paragraphs]

import java.util.*;

class Solution {
    static Map<String, String> TAG = Map.of("bold", "b", "italic", "i", "underline", "u");

    static String render(Object chunk) {
        List<?> c = (List<?>) chunk;
        String kind = (String) c.get(0);
        Object content = c.get(1);
        String inner;
        if (content instanceof List<?> list) {
            StringBuilder sb = new StringBuilder();
            for (Object x : list) sb.append(render(x));
            inner = sb.toString();
        } else {
            inner = (String) content;
        }
        String tag = TAG.get(kind);
        return tag == null ? inner : "<" + tag + ">" + inner + "</" + tag + ">";
    }

    static List<String> formatParagraphs(List<List<List<Object>>> paragraphs) {
        List<String> out = new ArrayList<>();
        for (var para : paragraphs) {
            StringBuilder sb = new StringBuilder("<p>");
            for (Object c : para) sb.append(render(c));
            sb.append("</p>");
            out.add(sb.toString());
        }
        return out;
    }
}

