from sortedcontainers import SortedList

def segmentsAfterDestruction(houses, queries):
    houses_sorted = sorted(houses)
    alive = SortedList(houses_sorted)
    segments = 1
    for i in range(1, len(houses_sorted)):
        if houses_sorted[i] != houses_sorted[i - 1] + 1:
            segments += 1
    if not houses_sorted:
        segments = 0
    out = []
    for q in queries:
        idx = alive.index(q)
        has_left = idx > 0 and alive[idx - 1] == q - 1
        has_right = idx < len(alive) - 1 and alive[idx + 1] == q + 1
        if has_left and has_right:
            segments += 1
        elif not has_left and not has_right:
            segments -= 1
        alive.remove(q)
        out.append(segments)
    return out

import java.util.*;

class Solution {
    static int[] segmentsAfterDestruction(int[] houses, int[] queries) {
        TreeSet<Integer> alive = new TreeSet<>();
        for (int h : houses) alive.add(h);
        int segments = 0;
        Integer prev = null;
        for (int h : alive) {
            if (prev == null || h != prev + 1) segments++;
            prev = h;
        }
        int[] out = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            boolean hasLeft = alive.contains(q - 1);
            boolean hasRight = alive.contains(q + 1);
            if (hasLeft && hasRight) segments++;
            else if (!hasLeft && !hasRight) segments--;
            alive.remove(q);
            out[i] = segments;
        }
        return out;
    }
}

