        if (k == 0) return 1;
        if (k == 1) return 2;
        return k % 2 == 0 ? 0 : 2;
    }
    int findLongestDiagonalSegment(int[][] matrix) {
        int n = matrix.length, m = matrix[0].length;
        int best = 0;
        int[][] dirs = {{1,1},{1,-1},{-1,1},{-1,-1}};
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            for (int[] d : dirs) {
                int len = 0, x = i, y = j;
                while (x >= 0 && x < n && y >= 0 && y < m && matrix[x][y] == expected(len)) {
                    len++;
                    x += d[0];
                    y += d[1];
                }
                best = Math.max(best, len);
            }
        }
        return best;
    }
}

