import java.util.*;

class Solution {
    String[] applyRateLimiter(int window, int limit, String[] requests) {
        Map<String, Deque<Long>> history = new HashMap<>();
        String[] out = new String[requests.length];
        for (int i = 0; i < requests.length; i++) {
            String[] p = requests[i].split(" ");
            long ts = Long.parseLong(p[0]);
            String key = p[1];
            Deque<Long> q = history.computeIfAbsent(key, k -> new ArrayDeque<>());
            while (!q.isEmpty() && q.peekFirst() <= ts - window) q.pollFirst();
            if (q.size() < limit) {
                q.offerLast(ts);
                out[i] = "ALLOW";
            } else {
                out[i] = "REJECT";
            }
        }
        return out;
    }
}

class Solution {
public:
    vector<string> applyRateLimiter(int window, int limit, vector<string>& requests) {
        unordered_map<string, deque<long long>> history;
        vector<string> out;
        for (const string& req : requests) {
            stringstream ss(req);
            long long ts; string key;
            ss >> ts >> key;
            auto& q = history[key];
            while (!q.empty() && q.front() <= ts - window) q.pop_front();
            if ((int) q.size() < limit) {
                q.push_back(ts);
                out.push_back("ALLOW");
            } else {
                out.push_back("REJECT");
            }
        }
        return out;
    }
};

