from bisect import bisect_right, bisect_left
from typing import List

def makeTowersStrictlyMonotonic(towers: List[int]) -> int:
    n = len(towers)
    # 将"严格递增"转换：要 a[i] >= a[i-1] + 1，等价于 a[i] - i 非递减
    # 最长非递减子序列长度 = 可保留的元素数
    def longest_nondec(arr):
        tails = []
        for x in arr:
            idx = bisect_right(tails, x)
            if idx == len(tails):
                tails.append(x)
            else:
                tails[idx] = x
        return len(tails)
    inc = [towers[i] - i for i in range(n)]
    dec = [towers[i] + i for i in range(n)]
    keep_inc = longest_nondec(inc)
    keep_dec = longest_nondec(dec[::-1])
    return min(n - keep_inc, n - keep_dec) * 2  # 每个未保留的改一次（粗略 cost 模型）

import java.util.*;

class Solution {
    int longestNondec(int[] arr) {
        List<Integer> tails = new ArrayList<>();
        for (int x : arr) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails.get(mid) <= x) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(x);
            else tails.set(lo, x);
        }
        return tails.size();
    }
    int makeTowersStrictlyMonotonic(int[] towers) {
        int n = towers.length;
        int[] inc = new int[n];
        int[] dec = new int[n];
        for (int i = 0; i < n; i++) {
            inc[i] = towers[i] - i;
            dec[i] = towers[i] + i;
        }
        int[] decRev = new int[n];
        for (int i = 0; i < n; i++) decRev[i] = dec[n - 1 - i];
        int keepInc = longestNondec(inc);
        int keepDec = longestNondec(decRev);
        return Math.min(n - keepInc, n - keepDec) * 2;
    }
}

class Solution {
public:
    int longestNondec(vector<int>& arr) {
        vector<int> tails;
        for (int x : arr) {
            auto it = upper_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) tails.push_back(x);
            else *it = x;
        }
        return tails.size();
    }
    int makeTowersStrictlyMonotonic(vector<int>& towers) {
        int n = towers.size();
        vector<int> inc(n), dec(n);
        for (int i = 0; i < n; i++) {
            inc[i] = towers[i] - i;
            dec[i] = towers[i] + i;
        }
        vector<int> decRev(dec.rbegin(), dec.rend());
        int keepInc = longestNondec(inc);
        int keepDec = longestNondec(decRev);
        return min(n - keepInc, n - keepDec) * 2;
    }
};

from collections import defaultdict, deque
from typing import List

def applyMultiFieldRateLimiter(fieldRules: List[str], requests: List[str]) -> List[str]:
    rules = []
    for r in fieldRules:
        name, w, lim = r.split()
        rules.append((name, int(w), int(lim)))
    # 每个 (字段 idx, 字段值) -> 时间戳队列
    history = [defaultdict(deque) for _ in rules]
    out = []
    for req in requests:
        parts = req.split()
        ts = int(parts[0])
        values = parts[1:]
        # 第一遍：逐维度检查
        ok = True
        for i, (_, w, lim) in enumerate(rules):
            q = history[i][values[i]]
            while q and q[0] <= ts - w:
                q.popleft()
            if len(q) >= lim:
                ok = False
        if ok:
            for i in range(len(rules)):
                history[i][values[i]].append(ts)
            out.append("ALLOW")
        else:
            out.append("REJECT")
    return out

import java.util.*;

class Solution {
    String[] applyMultiFieldRateLimiter(String[] fieldRules, String[] requests) {
        int F = fieldRules.length;
        int[] windows = new int[F];
        int[] limits = new int[F];
        for (int i = 0; i < F; i++) {
            String[] p = fieldRules[i].split(" ");
            windows[i] = Integer.parseInt(p[1]);
            limits[i] = Integer.parseInt(p[2]);
        }
        List<Map<String, Deque<Long>>> history = new ArrayList<>();
        for (int i = 0; i < F; i++) history.add(new HashMap<>());
        String[] out = new String[requests.length];
        for (int r = 0; r < requests.length; r++) {
            String[] p = requests[r].split(" ");
            long ts = Long.parseLong(p[0]);
            boolean ok = true;
            for (int i = 0; i < F; i++) {
                Deque<Long> q = history.get(i).computeIfAbsent(p[1 + i], k -> new ArrayDeque<>());
                while (!q.isEmpty() && q.peekFirst() <= ts - windows[i]) q.pollFirst();
                if (q.size() >= limits[i]) ok = false;
            }
            if (ok) {
                for (int i = 0; i < F; i++) history.get(i).get(p[1 + i]).offerLast(ts);
                out[r] = "ALLOW";
            } else {
                out[r] = "REJECT";
            }
        }
        return out;
    }
}

class Solution {
public:
    vector<string> applyMultiFieldRateLimiter(vector<string>& fieldRules, vector<string>& requests) {
        int F = fieldRules.size();
        vector<int> windows(F), limits(F);
        for (int i = 0; i < F; i++) {
            stringstream ss(fieldRules[i]);
            string name;
            ss >> name >> windows[i] >> limits[i];
        }
        vector<unordered_map<string, deque<long long>>> history(F);
        vector<string> out;
        for (auto& req : requests) {
            stringstream ss(req);
            long long ts; ss >> ts;
            vector<string> vals(F);
            for (int i = 0; i < F; i++) ss >> vals[i];
            bool ok = true;
            for (int i = 0; i < F; i++) {
                auto& q = history[i][vals[i]];
                while (!q.empty() && q.front() <= ts - windows[i]) q.pop_front();
                if ((int) q.size() >= limits[i]) ok = false;
            }
            if (ok) {
                for (int i = 0; i < F; i++) history[i][vals[i]].push_back(ts);
                out.push_back("ALLOW");
            } else {
                out.push_back("REJECT");
            }
        }
        return out;
    }
};

from typing import List

def scheduleMeeting(schedules: List[List[List[int]]], length: int) -> int:
    DAY = 1440
    intervals = []
    for emp in schedules:
        for s, e in emp:
            intervals.append((s, e))
    if not intervals:
        return 0 if length <= DAY else -1
    intervals.sort()
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))
    # 空隙
    prev_end = 0
    for s, e in merged:
        if s - prev_end >= length:
            return prev_end
        prev_end = max(prev_end, e)
    if DAY - prev_end >= length:
        return prev_end
    return -1

import java.util.*;

class Solution {
    int scheduleMeeting(int[][][] schedules, int length) {
        int DAY = 1440;
        List<int[]> intervals = new ArrayList<>();
        for (int[][] emp : schedules)
            for (int[] m : emp) intervals.add(m);
        if (intervals.isEmpty()) return length <= DAY ? 0 : -1;
        intervals.sort((a, b) -> a[0] - b[0]);
        List<int[]> merged = new ArrayList<>();
        for (int[] iv : intervals) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1]) {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
            } else {
                merged.add(new int[]{iv[0], iv[1]});
            }
        }
        int prevEnd = 0;
        for (int[] iv : merged) {
            if (iv[0] - prevEnd >= length) return prevEnd;
            prevEnd = Math.max(prevEnd, iv[1]);
        }
        return DAY - prevEnd >= length ? prevEnd : -1;
    }
}

class Solution {
public:
    int scheduleMeeting(vector<vector<vector<int>>>& schedules, int length) {
        const int DAY = 1440;
        vector<pair<int,int>> intervals;
        for (auto& emp : schedules)
            for (auto& m : emp) intervals.push_back({m[0], m[1]});
        if (intervals.empty()) return length <= DAY ? 0 : -1;
        sort(intervals.begin(), intervals.end());
        vector<pair<int,int>> merged;
        for (auto& iv : intervals) {
            if (!merged.empty() && iv.first <= merged.back().second) {
                merged.back().second = max(merged.back().second, iv.second);
            } else {
                merged.push_back(iv);
            }
        }
        int prevEnd = 0;
        for (auto& iv : merged) {
            if (iv.first - prevEnd >= length) return prevEnd;
            prevEnd = max(prevEnd, iv.second);
        }
        return DAY - prevEnd >= length ? prevEnd : -1;
    }
};

