def cyclicShiftPairs(a: List[int]) -> int:
    def canonical(x: int) -> str:
        s = str(x)
        rotations = [s[i:] + s[:i] for i in range(len(s))]
        return min(rotations)
    sigs = [(len(str(x)), canonical(x)) for x in a]
    cnt = Counter(sigs)
    return sum(c * (c - 1) // 2 for c in cnt.values())

import java.util.*;

class Solution {
    String canonical(int x) {
        String s = String.valueOf(x);
        String best = s;
        for (int i = 1; i < s.length(); i++) {
            String rot = s.substring(i) + s.substring(0, i);
            if (rot.compareTo(best) < 0) best = rot;
        }
        return s.length() + "|" + best;
    }
    long cyclicShiftPairs(int[] a) {
        Map<String, Integer> cnt = new HashMap<>();
        for (int x : a) cnt.merge(canonical(x), 1, Integer::sum);
        long ans = 0;
        for (int c : cnt.values()) ans += (long) c * (c - 1) / 2;
        return ans;
    }
}

class Solution {
public:
    string canonical(int x) {
        string s = to_string(x);
        string best = s;
        for (size_t i = 1; i < s.size(); i++) {
            string rot = s.substr(i) + s.substr(0, i);
            if (rot < best) best = rot;
        }
        return to_string(s.size()) + "|" + best;
    }
    long long cyclicShiftPairs(vector<int>& a) {
        unordered_map<string, int> cnt;
        for (int x : a) cnt[canonical(x)]++;
        long long ans = 0;
        for (auto& [k, c] : cnt) ans += (long long) c * (c - 1) / 2;
        return ans;
    }
};

import java.util.*;

class Solution {
    long suffixPairs(String[] words) {
        Map<String, Integer> cnt = new HashMap<>();
        String[] rev = new String[words.length];
        for (int i = 0; i < words.length; i++) {
            rev[i] = new StringBuilder(words[i]).reverse().toString();
            cnt.merge(rev[i], 1, Integer::sum);
        }
        long ans = 0;
        for (String r : rev) {
            for (int k = 1; k <= r.length(); k++) {
                String pref = r.substring(0, k);
                ans += cnt.getOrDefault(pref, 0);
            }
            ans--;
        }
        return ans / 2;
    }
}

class Solution {
public:
    long long suffixPairs(vector<string>& words) {
        unordered_map<string, int> cnt;
        vector<string> rev;
        for (auto& w : words) {
            string r(w.rbegin(), w.rend());
            rev.push_back(r);
            cnt[r]++;
        }
        long long ans = 0;
        for (auto& r : rev) {
            for (size_t k = 1; k <= r.size(); k++) {
                string pref = r.substr(0, k);
                auto it = cnt.find(pref);
                if (it != cnt.end()) ans += it->second;
            }
            ans--;
        }
        return ans / 2;
    }
};

