def longest_stable_period(transactions: List[int], k: int) -> int:
    first = {0: -1}
    cur = 0
    ans = 0
    for i, x in enumerate(transactions):
        cur = (cur + x) % k
        if cur in first:
            ans = max(ans, i - first[cur])
        else:
            first[cur] = i
    return ans

import java.util.*;

class Solution {
    int longestStablePeriod(int[] transactions, int k) {
        Map<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);
        long cur = 0;
        int ans = 0;
        for (int i = 0; i < transactions.length; i++) {
            cur = ((cur + transactions[i]) % k + k) % k;
            if (first.containsKey(cur)) ans = Math.max(ans, i - first.get(cur));
            else first.put(cur, i);
        }
        return ans;
    }
}

class Solution {
public:
    int longestStablePeriod(vector<int>& transactions, int k) {
        unordered_map<long long, int> first;
        first[0] = -1;
        long long cur = 0;
        int ans = 0;
        for (int i = 0; i < (int) transactions.size(); i++) {
            cur = ((cur + transactions[i]) % k + k) % k;
            auto it = first.find(cur);
            if (it != first.end()) ans = max(ans, i - it->second);
            else first[cur] = i;
        }
        return ans;
    }
};

def replace_consonant(message: str, n: int) -> str:
    vowels = set("aeiouAEIOU")
    def next_consonant(c):
        is_upper = c.isupper()
        x = c.lower()
        while True:
            x = chr((ord(x) - ord('a') + 1) % 26 + ord('a'))
            if x not in "aeiou":
                break
        return x.upper() if is_upper else x
    out = []
    cnt = 0
    for c in message:
        if c.isalpha() and c not in vowels:
            cnt += 1
            if cnt % n == 0:
                out.append(next_consonant(c))
                continue
        out.append(c)
    return "".join(out)

class Solution {
    String replaceConsonant(String message, int n) {
        StringBuilder out = new StringBuilder();
        int cnt = 0;
        for (char c : message.toCharArray()) {
            if (Character.isLetter(c) && !isVowel(c)) {
                cnt++;
                if (cnt % n == 0) { out.append(nextConsonant(c)); continue; }
            }
            out.append(c);
        }
        return out.toString();
    }
    private boolean isVowel(char c) { return "aeiouAEIOU".indexOf(c) >= 0; }
    private char nextConsonant(char c) {
        boolean upper = Character.isUpperCase(c);
        char x = Character.toLowerCase(c);
        do { x = (char) ((x - 'a' + 1) % 26 + 'a'); } while (isVowel(x));
        return upper ? Character.toUpperCase(x) : x;
    }
}

class Solution {
public:
    string replaceConsonant(string message, int n) {
        string out;
        int cnt = 0;
        auto isVowel = [](char c) { return string("aeiouAEIOU").find(c) != string::npos; };
        auto nextC = [&](char c) {
            bool upper = isupper(c);
            char x = tolower(c);
            do { x = (x - 'a' + 1) % 26 + 'a'; } while (isVowel(x));
            return upper ? (char) toupper(x) : x;
        };
        for (char c : message) {
            if (isalpha((unsigned char) c) && !isVowel(c)) {
                ++cnt;
                if (cnt % n == 0) { out += nextC(c); continue; }
            }
            out += c;
        }
        return out;
    }
};

class Solution {
    int[] countGroups(int[] tags, int[][] queries) {
        int n = tags.length;
        Map<Integer, int[]> pref = new HashMap<>();
        for (int t : tags) pref.computeIfAbsent(t, k -> new int[n + 1]);
        for (int i = 0; i < n; i++) {
            for (Map.Entry<Integer, int[]> e : pref.entrySet()) {
                e.getValue()[i + 1] = e.getValue()[i];
            }
            pref.get(tags[i])[i + 1]++;
        }
        int[] res = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int l = queries[q][0], r = queries[q][1];
            int total = 0;
            for (int[] arr : pref.values()) {
                int cnt = arr[r] - arr[l - 1];
                total += cnt / 2;
            }
            res[q] = total;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> countGroups(vector<int>& tags, vector<vector<int>>& queries) {
        int n = tags.size();
        unordered_map<int, vector<int>> pref;
        for (int t : tags) if (!pref.count(t)) pref[t] = vector<int>(n + 1, 0);
        for (int i = 0; i < n; i++) {
            for (auto& [k, v] : pref) v[i + 1] = v[i];
            pref[tags[i]][i + 1]++;
        }
        vector<int> res;
        for (auto& q : queries) {
            int l = q[0], r = q[1];
            int total = 0;
            for (auto& [k, v] : pref) {
                int cnt = v[r] - v[l - 1];
                total += cnt / 2;
            }
            res.push_back(total);
        }
        return res;
    }
};

