class Solution {
    public int solve(int n) {
        final int MOD = 1_000_000_007;
        List<int[]> pats = new ArrayList<>();
        for (int a = 0; a < 3; a++) for (int b = 0; b < 3; b++) for (int c = 0; c < 3; c++)
            if (!(a == b && b == c)) pats.add(new int[]{a, b, c});
        Map<Long, Long> dp = new HashMap<>();
        for (int[] p : pats) dp.merge(key(p[0], p[1], p[2]), 1L, Long::sum);
        for (int s = 1; s < n; s++) {
            Map<Long, Long> nd = new HashMap<>();
            for (var e : dp.entrySet()) {
                int[] k = unkey(e.getKey());
                long cnt = e.getValue();
                for (int[] p : pats) {
                    int n0 = (k[0] != -1 && p[0] == k[0]) ? k[0] : -1;
                    int n1 = (k[1] != -1 && p[1] == k[1]) ? k[1] : -1;
                    int n2 = (k[2] != -1 && p[2] == k[2]) ? k[2] : -1;
                    nd.merge(key(n0, n1, n2), cnt, (x, y) -> (x + y) % MOD);
                }
            }
            dp = nd;
        }
        long ans = 0;
        for (var e : dp.entrySet()) {
            int[] k = unkey(e.getKey());
            if (k[0] == -1 && k[1] == -1 && k[2] == -1) ans = (ans + e.getValue()) % MOD;
        }
        return (int) ans;
    }
    private long key(int a, int b, int c) { return ((a + 1L) * 5 + (b + 1)) * 5 + (c + 1); }
    private int[] unkey(long k) { int c = (int)(k % 5) - 1; k /= 5; int b = (int)(k % 5) - 1; int a = (int)(k / 5) - 1; return new int[]{a, b, c}; }
}

