def solve(s):
    n = len(s)
    f = [[0] * n for _ in range(n)]
    for i in range(n): f[i][i] = 1
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            f[l][r] = f[l+1][r] + 1
            for k in range(l + 1, r + 1):
                if s[k] == s[l]:
                    mid = f[l+1][k-1] if k - 1 >= l + 1 else 0
                    f[l][r] = min(f[l][r], mid + f[k][r])
    return f[0][n-1]

class Solution {
    public int solve(String s) {
        int n = s.length();
        int[][] f = new int[n][n];
        for (int i = 0; i < n; i++) f[i][i] = 1;
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len <= n; l++) {
                int r = l + len - 1;
                f[l][r] = f[l+1][r] + 1;
                for (int k = l + 1; k <= r; k++) if (s.charAt(k) == s.charAt(l)) {
                    int mid = (k - 1 >= l + 1) ? f[l+1][k-1] : 0;
                    f[l][r] = Math.min(f[l][r], mid + f[k][r]);
                }
            }
        }
        return f[0][n-1];
    }
}

