import java.util.*;

class Solution {
    int getMinimumDifference(int K, int[] A) {
        int[] a = A.clone();
        Arrays.sort(a);
        int n = a.length;
        if (n == 1) return 0;
        int ans = a[n - 1] - a[0];
        for (int i = 1; i < n; i++) {
            int low = Math.min(a[0] + K, a[i] - K);
            int high = Math.max(a[i - 1] + K, a[n - 1] - K);
            ans = Math.min(ans, high - low);
        }
        return ans;
    }
}

