        int n = a.size();
        if (n == 1) return 0;
        int ans = a[n - 1] - a[0];
        for (int i = 1; i < n; i++) {
            int low = min(a[0] + K, a[i] - K);
            int high = max(a[i - 1] + K, a[n - 1] - K);
            ans = min(ans, high - low);
        }
        return ans;
    }
};

from collections import deque

def minimum_jumps(m: int, n: int, X: int, p: int, q: int, u: int, v: int) -> int:
    moves = []
    X2 = X * X
    for dr in range(-X, X + 1):
        for dc in range(-X, X + 1):
            if dr * dr + dc * dc == X2:
                moves.append((dr, dc))
    if not moves:
        return -1
    sr, sc = p - 1, q - 1
    er, ec = u - 1, v - 1
    if (sr, sc) == (er, ec):
        return 0
    dist = [[-1] * n for _ in range(m)]
    dist[sr][sc] = 0
    dq = deque([(sr, sc)])
    while dq:
        r, c = dq.popleft()
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                if (nr, nc) == (er, ec):
                    return dist[nr][nc]
                dq.append((nr, nc))
    return -1

import java.util.*;

class Solution {
    int minimumJumps(int m, int n, int X, int p, int q, int u, int v) {
        List<int[]> moves = new ArrayList<>();
        int X2 = X * X;
        for (int dr = -X; dr <= X; dr++)
            for (int dc = -X; dc <= X; dc++)
                if (dr * dr + dc * dc == X2) moves.add(new int[]{dr, dc});
        if (moves.isEmpty()) return -1;
        int sr = p - 1, sc = q - 1, er = u - 1, ec = v - 1;
        if (sr == er && sc == ec) return 0;
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[sr][sc] = 0;
        Deque<int[]> dq = new ArrayDeque<>();
        dq.add(new int[]{sr, sc});
        while (!dq.isEmpty()) {
            int[] cur = dq.poll();
            for (int[] mv : moves) {
                int nr = cur[0] + mv[0], nc = cur[1] + mv[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[cur[0]][cur[1]] + 1;
                    if (nr == er && nc == ec) return dist[nr][nc];
                    dq.add(new int[]{nr, nc});
                }
            }
        }
        return -1;
    }
}

class Solution {
public:
    int minimumJumps(int m, int n, int X, int p, int q, int u, int v) {
        vector<pair<int, int>> moves;
        int X2 = X * X;
        for (int dr = -X; dr <= X; dr++)
            for (int dc = -X; dc <= X; dc++)
                if (dr * dr + dc * dc == X2) moves.push_back({dr, dc});
        if (moves.empty()) return -1;
        int sr = p - 1, sc = q - 1, er = u - 1, ec = v - 1;
        if (sr == er && sc == ec) return 0;
        vector<vector<int>> dist(m, vector<int>(n, -1));
        dist[sr][sc] = 0;
        queue<pair<int, int>> dq;
        dq.push({sr, sc});
        while (!dq.empty()) {
            auto [r, c] = dq.front(); dq.pop();
            for (auto& mv : moves) {
                int nr = r + mv.first, nc = c + mv.second;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    if (nr == er && nc == ec) return dist[nr][nc];
                    dq.push({nr, nc});
                }
            }
        }
        return -1;
    }
};

