import heapq

def letter_candles(N: int, M: int, S: str) -> int:
    cnt = Counter(S)
    heap = [-c for c in cnt.values()]
    heapq.heapify(heap)
    for _ in range(M):
        if not heap: break
        c = -heapq.heappop(heap)
        c -= 1
        if c > 0: heapq.heappush(heap, -c)
    return sum(c * c for c in (-x for x in heap))

import java.util.*;

class Solution {
    long letterCandles(int N, int M, String S) {
        int[] cnt = new int[26];
        for (char c : S.toCharArray()) cnt[c - 'a']++;
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int c : cnt) if (c > 0) heap.add(c);
        for (int i = 0; i < M; i++) {
            if (heap.isEmpty()) break;
            int x = heap.poll() - 1;
            if (x > 0) heap.add(x);
        }
        long total = 0;
        for (int x : heap) total += (long) x * x;
        return total;
    }
}

