            if (heap.empty()) break;
            int x = heap.top() - 1; heap.pop();
            if (x > 0) heap.push(x);
        }
        long long total = 0;
        while (!heap.empty()) { int x = heap.top(); heap.pop(); total += (long long) x * x; }
