def longest_cipher(s: str) -> int:
    best = -1
    i = 0
    n = len(s)
    while i < n:
        if s[i].isdigit():
            i += 1; continue
        j = i
        has_upper = False
        while j < n and not s[j].isdigit():
            if s[j].isupper(): has_upper = True
            j += 1
        if has_upper:
            best = max(best, j - i)
        i = j
    return best

class Solution {
    int longestCipher(String s) {
        int best = -1, n = s.length();
        int i = 0;
        while (i < n) {
            if (Character.isDigit(s.charAt(i))) { i++; continue; }
            int j = i;
            boolean upper = false;
            while (j < n && !Character.isDigit(s.charAt(j))) {
                if (Character.isUpperCase(s.charAt(j))) upper = true;
                j++;
            }
            if (upper) best = Math.max(best, j - i);
            i = j;
        }
        return best;
    }
}

class Solution {
public:
    int longestCipher(string s) {
        int best = -1, n = s.size();
        int i = 0;
        while (i < n) {
            if (isdigit((unsigned char) s[i])) { i++; continue; }
            int j = i;
            bool upper = false;
            while (j < n && !isdigit((unsigned char) s[j])) {
                if (isupper((unsigned char) s[j])) upper = true;
                j++;
            }
            if (upper) best = max(best, j - i);
            i = j;
        }
        return best;
    }
};

