def maximum_reward(N: int, M: int, matrix: List[List[int]]) -> int:
    INF = float("inf")
    min_so_far = [[INF] * M for _ in range(N)]
    for i in range(N):
        for j in range(M):
            cur = matrix[i][j]
            from_top = min_so_far[i - 1][j] if i > 0 else INF
            from_left = min_so_far[i][j - 1] if j > 0 else INF
            min_so_far[i][j] = min(cur, from_top, from_left)
    best = -INF
    for i in range(N):
        for j in range(M):
            from_top = min_so_far[i - 1][j] if i > 0 else INF
            from_left = min_so_far[i][j - 1] if j > 0 else INF
            prev_min = min(from_top, from_left)
            if prev_min != INF:
                best = max(best, matrix[i][j] - prev_min)
    return best

