            long cur = matrix[i][j];
            long ft = i > 0 ? minSoFar[i - 1][j] : INF;
            long fl = j > 0 ? minSoFar[i][j - 1] : INF;
            minSoFar[i][j] = Math.min(cur, Math.min(ft, fl));
        }
        long best = Long.MIN_VALUE;
        for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) {
            long ft = i > 0 ? minSoFar[i - 1][j] : INF;
            long fl = j > 0 ? minSoFar[i][j - 1] : INF;
            long prev = Math.min(ft, fl);
            if (prev != INF) best = Math.max(best, matrix[i][j] - prev);
        }
        return (int) best;
    }
}

