def optimize_watering_cost(N: int, ranges: List[int], cost: List[int]) -> int:
    INF = float("inf")
    intervals = []
    for i, r in enumerate(ranges):
        intervals.append((max(0, i - r), min(N, i + r), cost[i]))
    dp = [INF] * (N + 2)
    dp[0] = 0
    for x in range(1, N + 2):
        for l, r, c in intervals:
            if l <= x - 1 <= r:
                # this sprinkler can cover from l to r; dp[r+1] = min(dp[r+1], dp[l] + c)
                # using x as target right boundary +1
                if x - 1 == r:
                    if dp[l] != INF and dp[l] + c < dp[x]:
                        dp[x] = dp[l] + c
        # alt: for any sprinkler whose r >= x-1, can extend coverage
        for l, r, c in intervals:
            if l <= x - 1 and r >= x - 1:
                # can replace coverage up to r+1
                if dp[l] != INF and dp[l] + c < dp[min(N + 1, r + 1)]:
                    dp[min(N + 1, r + 1)] = dp[l] + c
    return dp[N + 1] if dp[N + 1] != INF else -1

import java.util.*;

class Solution {
    int optimizeWateringCost(int N, int[] ranges, int[] cost) {
        long INF = Long.MAX_VALUE / 4;
        int len = ranges.length;
        long[] dp = new long[N + 2];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int x = 1; x <= N + 1; x++) {
            for (int i = 0; i < len; i++) {
                int l = Math.max(0, i - ranges[i]);
                int r = Math.min(N, i + ranges[i]);
                if (l <= x - 1 && r >= x - 1) {
                    if (dp[l] + cost[i] < dp[Math.min(N + 1, r + 1)]) {
                        dp[Math.min(N + 1, r + 1)] = dp[l] + cost[i];
                    }
                }
            }
        }
        return dp[N + 1] == INF ? -1 : (int) dp[N + 1];
    }
}

class Solution {
public:
    int optimizeWateringCost(int N, vector<int>& ranges, vector<int>& cost) {
        const long long INF = 1e18;
        int len = ranges.size();
        vector<long long> dp(N + 2, INF);
        dp[0] = 0;
        for (int x = 1; x <= N + 1; x++) {
            for (int i = 0; i < len; i++) {
                int l = max(0, i - ranges[i]);
                int r = min(N, i + ranges[i]);
                if (l <= x - 1 && r >= x - 1) {
                    int target = min(N + 1, r + 1);
                    if (dp[l] + cost[i] < dp[target]) dp[target] = dp[l] + cost[i];
                }
            }
        }
        return dp[N + 1] == INF ? -1 : (int) dp[N + 1];
    }
};

from collections import Counter

def rearrange_string(s: str) -> str:
    n = len(s)
    cnt = Counter(s)
    if max(cnt.values()) > (n + 1) // 2:
        return "impossible"
    chars = sorted(s)
    res = [''] * n
    i, j = 0, n - 1
    k = 0
    for ch in chars:
        if k % 2 == 0:
            res[i] = ch; i += 1
        else:
            res[j] = ch; j -= 1
        k += 1
    for x in range(n // 2):
        if res[x] == res[n - 1 - x]:
            for y in range(n):
                if res[y] != res[x] and res[n - 1 - y] != res[x] and res[y] != res[n - 1 - x]:
                    res[x], res[y] = res[y], res[x]
                    break
    for x in range(n // 2):
        if res[x] == res[n - 1 - x]:
            return "impossible"
    return "".join(res)

import java.util.*;

class Solution {
    String rearrangeString(String s) {
        int n = s.length();
        int[] cnt = new int[256];
        for (char c : s.toCharArray()) cnt[c]++;
        int max = 0;
        for (int c : cnt) max = Math.max(max, c);
        if (max > (n + 1) / 2) return "impossible";
        char[] chars = s.toCharArray();
        Arrays.sort(chars);
        char[] res = new char[n];
        int i = 0, j = n - 1, k = 0;
        for (char c : chars) {
            if (k % 2 == 0) res[i++] = c;
            else res[j--] = c;
            k++;
        }
        return new String(res);
    }
}

