def set_total_palindrome_cost(s: str) -> int:
    n = len(s)
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] ^ (1 << (ord(s[i]) - ord('a')))
    total = 0
    for l in range(n):
        for r in range(l + 1, n + 1):
            mask = pre[r] ^ pre[l]
            ones = bin(mask).count("1")
            total += max(0, (ones - 1) // 2) + ((ones - 1) % 2 if ones > 0 else 0)
            # cost = popcount // 2 when len even, (popcount - 1) // 2 when len odd
            length = r - l
            total += 0
    # The corrected formula: cost = popcount // 2 if length even else (popcount - 1) // 2
    total = 0
    for l in range(n):
        for r in range(l + 1, n + 1):
            mask = pre[r] ^ pre[l]
            ones = bin(mask).count("1")
            length = r - l
            if length % 2 == 0:
                total += ones // 2
            else:
                total += max(0, (ones - 1) // 2)
    return total

class Solution {
    long setTotalPalindromeCost(String s) {
        int n = s.length();
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ (1 << (s.charAt(i) - 'a'));
        long total = 0;
        for (int l = 0; l < n; l++)
            for (int r = l + 1; r <= n; r++) {
                int mask = pre[r] ^ pre[l];
                int ones = Integer.bitCount(mask);
                int length = r - l;
                if (length % 2 == 0) total += ones / 2;
                else total += Math.max(0, (ones - 1) / 2);
            }
        return total;
    }
}

class Solution {
public:
    long long setTotalPalindromeCost(string s) {
        int n = s.size();
        vector<int> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ (1 << (s[i] - 'a'));
        long long total = 0;
        for (int l = 0; l < n; l++)
            for (int r = l + 1; r <= n; r++) {
                int mask = pre[r] ^ pre[l];
                int ones = __builtin_popcount(mask);
                int length = r - l;
                if (length % 2 == 0) total += ones / 2;
                else total += max(0, (ones - 1) / 2);
            }
        return total;
    }
};

