def spreading_fire(N: int, M: int, K: int, firePoints: List[List[int]], R: int, T: int) -> int:
    radius = R * T
    rad2 = radius * radius
    count = 0
    for x in range(N + 1):
        for y in range(M + 1):
            safe = True
            for fx, fy in firePoints:
                if (x - fx) ** 2 + (y - fy) ** 2 <= rad2:
                    safe = False
                    break
            if safe:
                count += 1
    return count

class Solution {
    int spreadingFire(int N, int M, int K, int[][] firePoints, int R, int T) {
        long radius = (long) R * T;
        long rad2 = radius * radius;
        int count = 0;
        for (int x = 0; x <= N; x++)
            for (int y = 0; y <= M; y++) {
                boolean safe = true;
                for (int[] f : firePoints) {
                    long dx = x - f[0], dy = y - f[1];
                    if (dx * dx + dy * dy <= rad2) { safe = false; break; }
                }
                if (safe) count++;
            }
        return count;
    }
}

