def minimum_time_to_infect(N: int, M: int, grid: List[List[int]]) -> int:
    q = deque()
    fresh = 0
    for i in range(N):
        for j in range(M):
            if grid[i][j] == 2:
                q.append((i, j, 0))
            elif grid[i][j] == 1:
                fresh += 1
    time_ = 0
    while q:
        r, c, t = q.popleft()
        time_ = max(time_, t)
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < M and grid[nr][nc] == 1:
                grid[nr][nc] = 2
                fresh -= 1
                q.append((nr, nc, t + 1))
    return -1 if fresh > 0 else time_

import java.util.*;

class Solution {
    int minimumTimeToInfect(int N, int M, int[][] grid) {
        Deque<int[]> q = new ArrayDeque<>();
        int fresh = 0;
        for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) {
            if (grid[i][j] == 2) q.add(new int[]{i, j, 0});
            else if (grid[i][j] == 1) fresh++;
        }
        int time = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            time = Math.max(time, cur[2]);
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nr < N && nc >= 0 && nc < M && grid[nr][nc] == 1) {
                    grid[nr][nc] = 2; fresh--;
                    q.add(new int[]{nr, nc, cur[2] + 1});
                }
            }
        }
        return fresh > 0 ? -1 : time;
    }
}

