def modifyArray(arr: List[int]) -> int:
    def cost(nums):
        vals = sorted(set(nums))
        n = len(nums); k = len(vals)
        dp = [abs(nums[0] - v) for v in vals]
        for i in range(1, n):
            new_dp = [0] * k
            cur_min = dp[0]
            new_dp[0] = abs(nums[i] - vals[0]) + cur_min
            for j in range(1, k):
                cur_min = min(cur_min, dp[j])
                new_dp[j] = abs(nums[i] - vals[j]) + cur_min
            dp = new_dp
        return min(dp)
    return min(cost(arr), cost(list(reversed(arr))))

class Solution {
    int modifyArray(int[] arr) {
        return (int) Math.min(cost(arr), costReversed(arr));
    }

    private long cost(int[] nums) {
        TreeSet<Integer> uniq = new TreeSet<>();
        for (int x : nums) uniq.add(x);
        Integer[] vals = uniq.toArray(new Integer[0]);
        int n = nums.length, k = vals.length;
        long[] dp = new long[k];
        for (int j = 0; j < k; j++) dp[j] = Math.abs(nums[0] - vals[j]);
        for (int i = 1; i < n; i++) {
            long[] nd = new long[k];
            long cur = dp[0];
            nd[0] = Math.abs(nums[i] - vals[0]) + cur;
            for (int j = 1; j < k; j++) {
                cur = Math.min(cur, dp[j]);
                nd[j] = Math.abs(nums[i] - vals[j]) + cur;
            }
            dp = nd;
        }
        long m = Long.MAX_VALUE;
        for (long v : dp) m = Math.min(m, v);
        return m;
    }

    private long costReversed(int[] nums) {
        int[] rev = new int[nums.length];
        for (int i = 0; i < nums.length; i++) rev[i] = nums[nums.length - 1 - i];
        return cost(rev);
    }
}

class Solution {
public:
    int modifyArray(vector<int>& arr) {
        long long c1 = cost(arr);
        vector<int> rev(arr.rbegin(), arr.rend());
        return (int) min(c1, cost(rev));
    }

private:
    long long cost(vector<int>& nums) {
        set<int> uniq(nums.begin(), nums.end());
        vector<int> vals(uniq.begin(), uniq.end());
        int n = nums.size(), k = vals.size();
        vector<long long> dp(k);
        for (int j = 0; j < k; j++) dp[j] = abs(nums[0] - vals[j]);
        for (int i = 1; i < n; i++) {
            vector<long long> nd(k);
            long long cur = dp[0];
            nd[0] = abs(nums[i] - vals[0]) + cur;
            for (int j = 1; j < k; j++) {
                cur = min(cur, dp[j]);
                nd[j] = abs(nums[i] - vals[j]) + cur;
            }
            dp = nd;
        }
        return *min_element(dp.begin(), dp.end());
    }
};

