class Solution {
    static int[] countLamps(int[][] lamps, int[] points) {
        int m = lamps.length;
        int[] starts = new int[m], ends = new int[m];
        for (int i = 0; i < m; i++) { starts[i] = lamps[i][0]; ends[i] = lamps[i][1]; }
        Arrays.sort(starts); Arrays.sort(ends);
        int[] out = new int[points.length];
        for (int i = 0; i < points.length; i++) {
            int p = points[i];
            int started = upperBound(starts, p);
            int ended = lowerBound(ends, p);
            out[i] = started - ended;
        }
        return out;
    }
    static int upperBound(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= v) lo = mid + 1; else hi = mid; }
        return lo;
    }
    static int lowerBound(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < v) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

