class Solution {
    static String smallestReverse(String word) {
        int n = word.length();
        String best = word;
        for (int k = 1; k <= n; k++) {
            String pre = new StringBuilder(word.substring(0, k)).reverse().toString() + word.substring(k);
            String suf = word.substring(0, n - k) + new StringBuilder(word.substring(n - k)).reverse().toString();
            if (pre.compareTo(best) < 0) best = pre;
            if (suf.compareTo(best) < 0) best = suf;
        }
        return best;
    }
}

