}

def restore_squares(m: list[list[int]]) -> list[list[int]]:
    N = len(m)
    n = N // 4
    miss_pos, miss_val = [], []
    for bi in range(n):
        for bj in range(n):
            s, mr, mc = 0, -1, -1
            for i in range(4):
                for j in range(4):
                    v = m[bi * 4 + i][bj * 4 + j]
                    if v == -1: mr, mc = bi * 4 + i, bj * 4 + j
                    else: s += v
            miss_pos.append((mr, mc))
            miss_val.append(136 - s)
    miss_val.sort()
    for (r, c), v in zip(miss_pos, miss_val):
        m[r][c] = v
    return m

