class Solution {
    static int[][] restoreSquares(int[][] m) {
        int N = m.length, n = N / 4;
        int[][] missPos = new int[n * n][2];
        int[] missVal = new int[n * n];
        int k = 0;
        for (int bi = 0; bi < n; bi++)
            for (int bj = 0; bj < n; bj++) {
                int sum = 0, mr = -1, mc = -1;
                for (int i = 0; i < 4; i++)
                    for (int j = 0; j < 4; j++) {
                        int v = m[bi * 4 + i][bj * 4 + j];
                        if (v == -1) { mr = bi * 4 + i; mc = bj * 4 + j; }
                        else sum += v;
                    }
                missPos[k][0] = mr; missPos[k][1] = mc;
                missVal[k] = 136 - sum;
                k++;
            }
        int[] sorted = missVal.clone();
        Arrays.sort(sorted);
        for (int i = 0; i < missPos.length; i++)
            m[missPos[i][0]][missPos[i][1]] = sorted[i];
        return m;
    }
}

