import java.util.*;

class Solution {
    static long prefixPairs(String[] titles) {
        Map<Integer, int[]> children = new HashMap<>();
        Map<Integer, Integer> end = new HashMap<>();
        int next = 1;
        children.put(0, new int[26]);
        long ans = 0;
        for (String t : titles) {
            int cur = 0;
            long fromMe = 0;
            for (char c : t.toCharArray()) {
                int[] node = children.get(cur);
                int idx = c - 'a';
                if (node[idx] == 0) {
                    node[idx] = next;
                    children.put(next, new int[26]);
                    next++;
                }
                cur = node[idx];
                fromMe += end.getOrDefault(cur, 0);
            }
            ans += fromMe;
            end.merge(cur, 1, Integer::sum);
        }
        long pairs = 0;
        for (String t : titles) {
            int cur = 0;
            boolean ok = true;
            for (char c : t.toCharArray()) {
                int[] node = children.get(cur);
                int nxt = node == null ? 0 : node[c - 'a'];
                if (nxt == 0) { ok = false; break; }
                cur = nxt;
            }
            if (ok) pairs += end.getOrDefault(cur, 0) - 1;
        }
        return ans + pairs;
    }
}

