    }

    Long deposit(long ts, String id, long amt) {
        id = resolve(id);
        if (id == null || !acc.containsKey(id)) return null;
        Account a = acc.get(id);
        a.bal += amt;
        a.hist.add(new long[]{ts, a.bal});
        return a.bal;
    }

    Long pay(long ts, String id, long amt) {
        id = resolve(id);
        if (id == null || !acc.containsKey(id) || acc.get(id).bal < amt) return null;
        Account a = acc.get(id);
        a.bal -= amt;
        a.out += amt;
        a.hist.add(new long[]{ts, a.bal});
        return a.bal;
    }

    List<String> topActivity(long ts, int n) {
        List<Map.Entry<String, Account>> list = new ArrayList<>(acc.entrySet());
        list.sort((x, y) -> {
            if (x.getValue().out != y.getValue().out)
                return Long.compare(y.getValue().out, x.getValue().out);
            return x.getKey().compareTo(y.getKey());
        });
        List<String> out = new ArrayList<>();
        for (int i = 0; i < Math.min(n, list.size()); i++) {
            out.add(list.get(i).getKey() + "(" + list.get(i).getValue().out + ")");
        }
        return out;
    }

    String transfer(long ts, String src, String dst, long amt) {
        src = resolve(src); dst = resolve(dst);
        if (src == null || dst == null || !acc.containsKey(src) || !acc.containsKey(dst) || src.equals(dst))
            return null;
        if (acc.get(src).bal < amt) return null;
        acc.get(src).bal -= amt;
        acc.get(src).hist.add(new long[]{ts, acc.get(src).bal});
        tidSeq++;
        String tid = "transfer" + tidSeq;
        pending.put(tid, new long[]{amt, ts});
        pendingMeta.put(tid, new String[]{src, dst});
        return tid;
    }

    boolean acceptTransfer(long ts, String id, String tid) {
        id = resolve(id);
        if (!pending.containsKey(tid)) return false;
        String[] meta = pendingMeta.get(tid);
        long[] info = pending.get(tid);
        long amt = info[0], t0 = info[1];
        if (!id.equals(meta[1]) || ts - t0 > 86_400_000L) return false;
        acc.get(meta[0]).out += amt;
        acc.get(meta[1]).bal += amt;
        acc.get(meta[1]).hist.add(new long[]{ts, acc.get(meta[1]).bal});
        pending.remove(tid);
        pendingMeta.remove(tid);
        return true;
    }

    boolean mergeAccounts(long ts, String a1, String a2) {
        a1 = resolve(a1); a2 = resolve(a2);
        if (a1 == null || a2 == null || a1.equals(a2) || !acc.containsKey(a1) || !acc.containsKey(a2))
            return false;
        acc.get(a1).bal += acc.get(a2).bal;
        acc.get(a1).out += acc.get(a2).out;
        acc.get(a1).hist.add(new long[]{ts, acc.get(a1).bal});
        acc.get(a2).mergedInto = a1;
        return true;
    }

    Long getBalance(long ts, String id, long timeAt) {
        id = resolve(id);
        if (id == null || !acc.containsKey(id)) return null;
        List<long[]> hist = acc.get(id).hist;
        int lo = 0, hi = hist.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (hist.get(mid)[0] <= timeAt) lo = mid + 1;
            else hi = mid;
        }
        if (lo == 0) return null;
        return hist.get(lo - 1)[1];
    }
}

