struct Account {
    long long bal = 0, out_ = 0;
    string mergedInto;
    vector<pair<long long, long long>> hist; // ts, bal
};

class BankingSystem {
public:
    unordered_map<string, Account> acc;
    unordered_map<string, pair<long long, long long>> pending; // tid -> {amt, t0}
    unordered_map<string, pair<string, string>> pendingMeta;
    long long tidSeq = 0;

    string resolve(const string& id_in) {
        string id = id_in;
        while (!id.empty() && acc.count(id) && !acc[id].mergedInto.empty())
            id = acc[id].mergedInto;
        return id;
    }

    bool createAccount(long long ts, const string& id) {
        if (acc.count(id)) return false;
        Account a;
        a.hist.push_back({ts, 0});
        acc[id] = a;
        return true;
    }

    long long deposit(long long ts, string id, long long amt) {
        id = resolve(id);
        if (id.empty() || !acc.count(id)) return -1;
        acc[id].bal += amt;
        acc[id].hist.push_back({ts, acc[id].bal});
        return acc[id].bal;
    }

    long long pay(long long ts, string id, long long amt) {
        id = resolve(id);
        if (id.empty() || !acc.count(id) || acc[id].bal < amt) return -1;
        acc[id].bal -= amt;
        acc[id].out_ += amt;
        acc[id].hist.push_back({ts, acc[id].bal});
        return acc[id].bal;
    }

    vector<string> topActivity(long long ts, int n) {
        vector<pair<string, long long>> v;
        for (auto& [k, a] : acc) v.push_back({k, a.out_});
        sort(v.begin(), v.end(), [](auto& x, auto& y) {
            if (x.second != y.second) return x.second > y.second;
            return x.first < y.first;
        });
        vector<string> out;
        for (int i = 0; i < (int) min((size_t) n, v.size()); i++)
            out.push_back(v[i].first + "(" + to_string(v[i].second) + ")");
        return out;
    }

    string transfer(long long ts, string src, string dst, long long amt) {
        src = resolve(src); dst = resolve(dst);
        if (src.empty() || dst.empty() || !acc.count(src) || !acc.count(dst) || src == dst) return "";
        if (acc[src].bal < amt) return "";
        acc[src].bal -= amt;
        acc[src].hist.push_back({ts, acc[src].bal});
        tidSeq++;
        string tid = "transfer" + to_string(tidSeq);
        pending[tid] = {amt, ts};
        pendingMeta[tid] = {src, dst};
        return tid;
    }

    bool acceptTransfer(long long ts, string id, const string& tid) {
        id = resolve(id);
        if (!pending.count(tid)) return false;
        auto [amt, t0] = pending[tid];
        auto [src, dst] = pendingMeta[tid];
        if (id != dst || ts - t0 > 86400000LL) return false;
        acc[src].out_ += amt;
        acc[dst].bal += amt;
        acc[dst].hist.push_back({ts, acc[dst].bal});
        pending.erase(tid);
        pendingMeta.erase(tid);
        return true;
    }

    bool mergeAccounts(long long ts, string a1, string a2) {
        a1 = resolve(a1); a2 = resolve(a2);
        if (a1.empty() || a2.empty() || a1 == a2 || !acc.count(a1) || !acc.count(a2)) return false;
        acc[a1].bal += acc[a2].bal;
        acc[a1].out_ += acc[a2].out_;
        acc[a1].hist.push_back({ts, acc[a1].bal});
        acc[a2].mergedInto = a1;
        return true;
    }

    long long getBalance(long long ts, string id, long long timeAt) {
        id = resolve(id);
        if (id.empty() || !acc.count(id)) return -1;
        auto& hist = acc[id].hist;
        int lo = 0, hi = hist.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (hist[mid].first <= timeAt) lo = mid + 1;
            else hi = mid;
        }
        if (lo == 0) return -1;
        return hist[lo - 1].second;
    }
};

def get_max_sum(arr: list[int], k: int) -> int:
    n = len(arr)
    NEG = float('-inf')
    f = [[NEG] * n for _ in range(k + 1)]
    f[0][n - 1] = arr[n - 1]
    for i in range(n - 2, -1, -1):
        f[0][i] = f[0][i + 1] + arr[i]
    for j in range(1, k + 1):
        f[j][n - 1] = arr[n - 1]
        for i in range(n - 2, -1, -1):
            f[j][i] = f[j - 1][i + 1] + arr[i]
            combined = arr[i] * arr[i + 1]
            if i + 2 < n:
                f[j][i] = max(f[j][i], f[j - 1][i + 2] + combined)
            else:
                f[j][i] = max(f[j][i], combined)
    return max(f[j][0] for j in range(k + 1))

import java.util.Arrays;

class Solution {
    static long getMaxSum(int[] arr, int k) {
        int n = arr.length;
        long NEG = Long.MIN_VALUE / 2;
        long[][] f = new long[k + 1][n];
        for (long[] row : f) Arrays.fill(row, NEG);
        f[0][n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) f[0][i] = f[0][i + 1] + arr[i];
        for (int j = 1; j <= k; j++) {
            f[j][n - 1] = arr[n - 1];
            for (int i = n - 2; i >= 0; i--) {
                f[j][i] = f[j - 1][i + 1] + arr[i];
                long combined = (long) arr[i] * arr[i + 1];
                if (i + 2 < n) f[j][i] = Math.max(f[j][i], f[j - 1][i + 2] + combined);
                else            f[j][i] = Math.max(f[j][i], combined);
            }
        }
        long best = Long.MIN_VALUE;
        for (int j = 0; j <= k; j++) best = Math.max(best, f[j][0]);
        return best;
    }
}

