def count_triplets(d: list[int], t: int) -> int:
    a = sorted(d)
    n = len(a)
    cnt = 0
    for c in range(2, n):
        l, r = 0, c - 1
        while l < r:
            if a[l] + a[r] + a[c] <= t:
                cnt += r - l
                l += 1
            else:
                r -= 1
    return cnt

import java.util.Arrays;

class Solution {
    static long countTriplets(int[] d, int t) {
        int[] a = d.clone();
        Arrays.sort(a);
        int n = a.length;
        long cnt = 0;
        for (int c = 2; c < n; c++) {
            int l = 0, r = c - 1;
            while (l < r) {
                if (a[l] + a[r] + a[c] <= t) { cnt += r - l; l++; }
                else r--;
            }
        }
        return cnt;
    }
}

