def get_max_sum_sign_flip(arr):
    total_abs = sum(abs(x) for x in arr)
    negatives = sum(1 for x in arr if x < 0)
    if negatives % 2 == 0:
        return total_abs
    return total_abs - 2 * min(abs(x) for x in arr)

class Solution {
    long getMaxSumSignFlip(int[] arr) {
        long totalAbs = 0;
        int negatives = 0, minAbs = Integer.MAX_VALUE;
        for (int x : arr) {
            int a = Math.abs(x);
            totalAbs += a;
            if (x < 0) negatives++;
            if (a < minAbs) minAbs = a;
        }
        if (negatives % 2 == 0) return totalAbs;
        return totalAbs - 2L * minAbs;
    }
}

