def arrange_squares(mat):
    rows = len(mat)
    cols = len(mat[0])
    n = cols // 4
    blocks = []
    for b in range(n):
        s = 0
        missing_pos = None
        for i in range(4):
            for j in range(4):
                v = mat[i][b * 4 + j]
                if v == -1:
                    missing_pos = (i, j)
                else:
                    s += v
        missing_val = 136 - s
        # copy the block as a flat list, replacing -1 with the missing value
        block = [[mat[i][b * 4 + j] if mat[i][b * 4 + j] != -1 else missing_val for j in range(4)] for i in range(4)]
        blocks.append((missing_val, block))
    blocks.sort(key=lambda x: x[0])
    out = [[0] * cols for _ in range(4)]
    for bi, (_, block) in enumerate(blocks):
        for i in range(4):
            for j in range(4):
                out[i][bi * 4 + j] = block[i][j]
    return out

import java.util.*;

class Solution {
    int[][] arrangeSquares(int[][] mat) {
        int cols = mat[0].length;
        int n = cols / 4;
        List<int[][]> blocks = new ArrayList<>();
        int[] missing = new int[n];
        for (int b = 0; b < n; b++) {
            int s = 0;
            int[][] block = new int[4][4];
            int mi = -1, mj = -1;
            for (int i = 0; i < 4; i++)
                for (int j = 0; j < 4; j++) {
                    int v = mat[i][b * 4 + j];
                    block[i][j] = v;
                    if (v == -1) { mi = i; mj = j; }
                    else s += v;
                }
            missing[b] = 136 - s;
            block[mi][mj] = missing[b];
            blocks.add(block);
        }
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, c) -> missing[a] - missing[c]);
        int[][] out = new int[4][cols];
        for (int bi = 0; bi < n; bi++) {
            int[][] block = blocks.get(order[bi]);
            for (int i = 0; i < 4; i++)
                for (int j = 0; j < 4; j++)
                    out[i][bi * 4 + j] = block[i][j];
        }
        return out;
    }
}

