from collections import deque
from typing import List

def largest_square_area(cityline: List[int]) -> int:
    n = len(cityline)
    def can(s: int) -> bool:
        if s > n: return False
        dq: deque = deque()
        for i in range(n):
            while dq and dq[0] <= i - s:
                dq.popleft()
            while dq and cityline[dq[-1]] >= cityline[i]:
                dq.pop()
            dq.append(i)
            if i >= s - 1 and cityline[dq[0]] >= s:
                return True
        return False
    lo, hi = 0, min(n, max(cityline) if cityline else 0)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo * lo

import java.util.*;

class Solution {
    public int largestSquareArea(int[] cityline) {
        int n = cityline.length, maxH = 0;
        for (int x : cityline) maxH = Math.max(maxH, x);
        int lo = 0, hi = Math.min(n, maxH);
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (can(cityline, mid)) lo = mid; else hi = mid - 1;
        }
        return lo * lo;
    }
    boolean can(int[] a, int s) {
        if (s > a.length) return false;
        Deque<Integer> dq = new ArrayDeque<>();
        for (int i = 0; i < a.length; i++) {
            while (!dq.isEmpty() && dq.peek() <= i - s) dq.poll();
            while (!dq.isEmpty() && a[dq.peekLast()] >= a[i]) dq.pollLast();
            dq.offerLast(i);
            if (i >= s - 1 && a[dq.peek()] >= s) return true;
        }
        return false;
    }
}

