            while (!dq.empty() && dq.front() <= i - s) dq.pop_front();
            while (!dq.empty() && a[dq.back()] >= a[i]) dq.pop_back();
            dq.push_back(i);
            if (i >= s - 1 && a[dq.front()] >= s) return true;
        }
