def longest_selectable_non_decreasing(A: List[int], B: List[int]) -> int:
    n = len(A)
    if n == 0:
        return 0
    la = 1; lb = 1; best = 1
    for i in range(1, n):
        nla = 1
        if A[i - 1] <= A[i]: nla = max(nla, la + 1)
        if B[i - 1] <= A[i]: nla = max(nla, lb + 1)
        nlb = 1
        if A[i - 1] <= B[i]: nlb = max(nlb, la + 1)
        if B[i - 1] <= B[i]: nlb = max(nlb, lb + 1)
        la, lb = nla, nlb
        best = max(best, la, lb)
    return best

class Solution {
    public int longestSelectableNonDecreasingSubarray(int[] A, int[] B) {
        int n = A.length;
        if (n == 0) return 0;
        int la = 1, lb = 1, best = 1;
        for (int i = 1; i < n; i++) {
            int nla = 1, nlb = 1;
            if (A[i - 1] <= A[i]) nla = Math.max(nla, la + 1);
            if (B[i - 1] <= A[i]) nla = Math.max(nla, lb + 1);
            if (A[i - 1] <= B[i]) nlb = Math.max(nlb, la + 1);
            if (B[i - 1] <= B[i]) nlb = Math.max(nlb, lb + 1);
            la = nla; lb = nlb;
            best = Math.max(best, Math.max(la, lb));
        }
        return best;
    }
}

