from typing import List

def maximize_capped_contribution_sum(a: List[int], b: List[int], k: int) -> int:
    base = sum(min(x, y) for x, y in zip(a, b))
    gains = sorted((min(x, 2 * y) - min(x, y) for x, y in zip(a, b)), reverse=True)
    return base + sum(gains[:k])

import java.util.*;

class Solution {
    public long maximizeCappedContributionSum(int[] a, int[] b, int k) {
        long base = 0;
        Integer[] gains = new Integer[a.length];
        for (int i = 0; i < a.length; i++) {
            base += Math.min(a[i], b[i]);
            gains[i] = Math.min(a[i], 2 * b[i]) - Math.min(a[i], b[i]);
        }
        Arrays.sort(gains, Collections.reverseOrder());
        for (int i = 0; i < k && i < gains.length; i++) base += gains[i];
        return base;
    }
}

