        vector<long long> gains(a.size());
        for (int i = 0; i < (int)a.size(); i++) {
            base += min(a[i], b[i]);
            gains[i] = (long long) min(a[i], 2 * b[i]) - min(a[i], b[i]);
        }
        sort(gains.begin(), gains.end(), greater<long long>());
        for (int i = 0; i < k && i < (int)gains.size(); i++) base += gains[i];
        return base;
    }
};

from typing import List

def minimum_cost_for_skill_quotas(costs: List[int], skill1: List[int], skill2: List[int]) -> List[int]:
    n = len(costs)
    both, a1, a2, none = [], [], [], []
    for i in range(n):
        if skill1[i] and skill2[i]: both.append(costs[i])
        elif skill1[i]: a1.append(costs[i])
        elif skill2[i]: a2.append(costs[i])
        else: none.append(costs[i])
    both.sort(); a1.sort(); a2.sort()
    def pre(arr):
        p = [0]
        for x in arr: p.append(p[-1] + x)
        return p
    pb, p1, p2 = pre(both), pre(a1), pre(a2)
    out = []
    for K in range(1, n + 1):
        best = float('inf')
        for b in range(min(len(both), K) + 1):
            need = K - b
            if need < 0: continue
            if need > len(a1) or need > len(a2): continue
            cost = pb[b] + p1[need] + p2[need]
            if cost < best: best = cost
        out.append(best if best != float('inf') else -1)
    return out

import java.util.*;

class Solution {
    public long[] minimumCostForSkillQuotas(int[] costs, int[] skill1, int[] skill2) {
        List<Integer> both = new ArrayList<>(), a1 = new ArrayList<>(), a2 = new ArrayList<>();
        for (int i = 0; i < costs.length; i++) {
            if (skill1[i] == 1 && skill2[i] == 1) both.add(costs[i]);
            else if (skill1[i] == 1) a1.add(costs[i]);
            else if (skill2[i] == 1) a2.add(costs[i]);
        }
        Collections.sort(both); Collections.sort(a1); Collections.sort(a2);
        long[] pb = pre(both), p1 = pre(a1), p2 = pre(a2);
        long[] out = new long[costs.length];
        for (int K = 1; K <= costs.length; K++) {
            long best = Long.MAX_VALUE;
            for (int b = 0; b <= Math.min(both.size(), K); b++) {
                int need = K - b;
                if (need < 0 || need > a1.size() || need > a2.size()) continue;
                long c = pb[b] + p1[need] + p2[need];
                if (c < best) best = c;
            }
            out[K - 1] = best == Long.MAX_VALUE ? -1 : best;
        }
        return out;
    }
    long[] pre(List<Integer> arr) {
        long[] p = new long[arr.size() + 1];
        for (int i = 0; i < arr.size(); i++) p[i + 1] = p[i] + arr.get(i);
        return p;
    }
}

