class Solution {
    static long maxProfit(int[] rates, int[] strategy, int k) {
        int n = rates.length;
        long P0 = 0;
        for (int i = 0; i < n; i++) P0 += (long) -strategy[i] * rates[i];
        long winGain = 0;
        for (int i = 0; i < k; i++)
            winGain += Math.abs(rates[i]) + (long) strategy[i] * rates[i];
        long best = winGain;
        for (int i = k; i < n; i++) {
            winGain += Math.abs(rates[i]) + (long) strategy[i] * rates[i];
            winGain -= Math.abs(rates[i - k]) + (long) strategy[i - k] * rates[i - k];
            if (winGain > best) best = winGain;
        }
        return P0 + best;
    }
}

