def max_expression(puzzle):
    h, w = len(puzzle), len(puzzle[0])

    def scan(i, j, di, dj):
        total, sign, last_digit = 0, 1, False
        while 0 <= i < h and 0 <= j < w:
            c = puzzle[i][j]
            if c.isdigit():
                if last_digit:
                    break
                total += sign * int(c)
                last_digit = True
            else:
                if not last_digit:
                    break
                sign = 1 if c == '+' else -1
                last_digit = False
            i += di; j += dj
        return total

    ans = float('-inf')
    for i in range(h):
        for j in range(w):
            if puzzle[i][j].isdigit():
                ans = max(ans, scan(i, j, 0, 1), scan(i, j, 1, 0))
    return ans

class Solution {
    static long maxExpression(char[][] g) {
        int h = g.length, w = g[0].length;
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
                if (Character.isDigit(g[i][j])) {
                    ans = Math.max(ans, scan(g, i, j, 0, 1));
                    ans = Math.max(ans, scan(g, i, j, 1, 0));
                }
        return ans;
    }
    static long scan(char[][] g, int i, int j, int di, int dj) {
        int h = g.length, w = g[0].length;
        long total = 0;
        int sign = 1;
        boolean lastDigit = false;
        while (i < h && j < w) {
            char c = g[i][j];
            if (Character.isDigit(c)) {
                if (lastDigit) break;
                total += sign * (c - '0');
                lastDigit = true;
            } else {
                if (!lastDigit) break;
                sign = (c == '+') ? 1 : -1;
                lastDigit = false;
            }
            i += di; j += dj;
        }
        return total;
    }
}

