import java.util.*;

class Solution {
    static int[] houseDensity(int[] queries) {
        int n = queries.length;
        Map<Integer, Integer> left = new HashMap<>(), right = new HashMap<>();
        TreeMap<Integer, Integer> lenCnt = new TreeMap<>();
        int[] out = new int[n];
        int best = 0;
        for (int i = 0; i < n; i++) {
            int q = queries[i];
            int l = q, r = q;
            if (right.containsKey(q - 1)) {
                int l2 = right.get(q - 1);
                int len = q - 1 - l2 + 1;
                lenCnt.merge(len, -1, Integer::sum);
                if (lenCnt.get(len) == 0) lenCnt.remove(len);
                l = l2;
                right.remove(q - 1);
            }
            if (left.containsKey(q + 1)) {
                int r2 = left.get(q + 1);
                int len = r2 - (q + 1) + 1;
                lenCnt.merge(len, -1, Integer::sum);
                if (lenCnt.get(len) == 0) lenCnt.remove(len);
                r = r2;
                left.remove(q + 1);
            }
            left.put(l, r);
            right.put(r, l);
            int newLen = r - l + 1;
            lenCnt.merge(newLen, 1, Integer::sum);
            best = Math.max(best, lenCnt.lastKey());
            out[i] = best;
        }
        return out;
    }
}

