 vector<int> out(n);
 int best = 0;
 for (int i = 0; i < n; i++) {
 int q = queries[i];
 int l = q, r = q;
 if (right_.count(q - 1)) {
 int l2 = right_[q - 1];
 int len = q - 1 - l2 + 1;
 if (--lenCnt[len] == 0) lenCnt.erase(len);
 l = l2;
 right_.erase(q - 1);
 }
 if (left_.count(q + 1)) {
 int r2 = left_[q + 1];
 int len = r2 - (q + 1) + 1;
 if (--lenCnt[len] == 0) lenCnt.erase(len);
 r = r2;
 left_.erase(q + 1);
 }
 left_[l] = r;
 right_[r] = l;
 lenCnt[r - l + 1]++;
 best = max(best, lenCnt.rbegin()->first);
 out[i] = best;
 }
 return out;
}

from collections import Counter

def get_string(input_str: str) -> str:
    remain = Counter(input_str)
    in_stk = set()
    stk = []
    for c in input_str:
        if c in in_stk:
            remain[c] -= 1
            continue
        while stk and stk[-1] < c and remain[stk[-1]] > 1:
            top = stk.pop()
            in_stk.remove(top)
            remain[top] -= 1
        stk.append(c)
        in_stk.add(c)
    return "".join(stk)

class Solution {
    String getString(String inputStr) {
        int[] remain = new int[26];
        for (char c : inputStr.toCharArray()) remain[c - 'a']++;
        boolean[] inStk = new boolean[26];
        StringBuilder stk = new StringBuilder();
        for (char c : inputStr.toCharArray()) {
            if (inStk[c - 'a']) { remain[c - 'a']--; continue; }
            while (stk.length() > 0 && stk.charAt(stk.length() - 1) < c
                   && remain[stk.charAt(stk.length() - 1) - 'a'] > 1) {
                char top = stk.charAt(stk.length() - 1);
                stk.deleteCharAt(stk.length() - 1);
                inStk[top - 'a'] = false;
                remain[top - 'a']--;
            }
            stk.append(c);
            inStk[c - 'a'] = true;
        }
        return stk.toString();
    }
}

class Solution {
