        for (char c : inputStr) remain[c - 'a']++;
        bool inStk[26] = {false};
        string stk;
        for (char c : inputStr) {
            if (inStk[c - 'a']) { remain[c - 'a']--; continue; }
            while (!stk.empty() && stk.back() < c && remain[stk.back() - 'a'] > 1) {
                char top = stk.back();
                stk.pop_back();
                inStk[top - 'a'] = false;
                remain[top - 'a']--;
            }
