def find_length_of_longest_good_subsequence(s: str) -> int:
    n = len(s)
    pre = [[0] * 128 for _ in range(n + 1)]
    suf = [[0] * 128 for _ in range(n + 1)]
    for i in range(n):
        for c in range(128):
            pre[i + 1][c] = pre[i][c]
        pre[i + 1][ord(s[i])] += 1
    for i in range(n - 1, -1, -1):
        for c in range(128):
            suf[i][c] = suf[i + 1][c]
        suf[i][ord(s[i])] += 1
    best = 0
    for i in range(n + 1):
        for a in range(128):
            for b in range(128):
                m = min(pre[i][a], suf[i][b])
                if 2 * m > best:
                    best = 2 * m
    return best

class Solution {
    int findLengthOfLongestGoodSubsequence(String s) {
        int n = s.length();
        int[][] pre = new int[n + 1][128];
        int[][] suf = new int[n + 1][128];
        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 128; c++) pre[i + 1][c] = pre[i][c];
            pre[i + 1][s.charAt(i)]++;
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 128; c++) suf[i][c] = suf[i + 1][c];
            suf[i][s.charAt(i)]++;
        }
        int best = 0;
        for (int i = 0; i <= n; i++)
            for (int a = 0; a < 128; a++)
                for (int b = 0; b < 128; b++) {
                    int m = Math.min(pre[i][a], suf[i][b]);
                    if (2 * m > best) best = 2 * m;
                }
        return best;
    }
}

