        for (auto& [x, y] : targets) {
            if ((x + y) % 3 == 0 && ((x - y) % 3 + 3) % 3 == 0) {
                long long steps = max(x, y);
                if (steps < best) best = steps;
            }
        }
        return best == LLONG_MAX ? -1 : (int) best;
    }
};

