def can_reach(sx, sy, tx, ty):
    while tx >= sx and ty >= sy:
        if tx == sx and ty == sy:
            return "Yes"
        if tx > ty:
            if ty == sy:
                return "Yes" if (tx - sx) % ty == 0 else "No"
            tx %= ty
        else:
            if tx == sx:
                return "Yes" if (ty - sy) % tx == 0 else "No"
            ty %= tx
    return "No"

