class Solution {
    long calculateTheSum(int n, int[][] operations) {
        int maxR = 0;
        for (int[] op : operations) maxR = Math.max(maxR, op[1]);
        int[] diff = new int[maxR + 2];
        for (int[] op : operations) { diff[op[0]] ^= 1; diff[op[1] + 1] ^= 1; }
        int cur = 0;
        long total = 0;
        for (int i = 1; i <= maxR; i++) {
            cur ^= diff[i];
            if (cur == 1) total += i;
        }
        return total;
    }
}

