def getMaxEfficiency(arrivalTime: List[int]) -> int:
    a = sorted(arrivalTime)
    n = len(a)
    best = -float('inf')
    min_iai = 0 - a[0]
    for j in range(1, n):
        cur = (j - a[j]) - min_iai + 1
        if cur > best: best = cur
        if (j - a[j]) < min_iai:
            min_iai = j - a[j]
    return int(best)

