class Solution {
    long getMaximumSumOfStrengths(int[] arr) {
        int n = arr.length;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1] + (long) arr[i - 1] * i;
            if (i >= 2) {
                long cand = dp[i - 2] + (long) arr[i - 2] * i + (long) arr[i - 1] * (i - 1);
                if (cand > dp[i]) dp[i] = cand;
            }
        }
        return dp[n];
    }
}

