 while (i < words.size()) {
 string w = words[i];
 int need = w.size() + (cur.empty() ? 0 : 1);
 if (curLen + need <= L) {
 cur.push_back(w);
 curLen += need;
 i++;
 continue;
 }
 if (w.find('-') != string::npos) {
 vector<string> parts;
 size_t l = 0;
 while (l <= w.size()) {
 size_t r = w.find('-', l);
 parts.push_back(w.substr(l, r == string::npos ? string::npos : r - l));
 if (r == string::npos) break;
 l = r + 1;
 }
 string bestPrefix;
 int bestK = -1;
 string acc;
 for (size_t k = 0; k + 1 < parts.size(); k++) {
 if (k > 0) acc += '-';
 acc += parts[k];
 string cand = acc + "-";
 int ext = cand.size() + (cur.empty() ? 0 : 1);
 if (curLen + ext <= L) { bestPrefix = cand; bestK = k; }
 }
 if (!bestPrefix.empty()) {
 cur.push_back(bestPrefix);
 string rem;
 for (size_t k = bestK + 1; k < parts.size(); k++) {
 if (k > (size_t)bestK + 1) rem += '-';
 rem += parts[k];
 }
 words[i] = rem;
 }
 }
 lines.push_back(cur);
 cur.clear();
 curLen = 0;
 }
 if (!cur.empty()) lines.push_back(cur);

 vector<string> out;
 for (auto& line : lines) {
 int wordLen = 0;
 for (auto& w : line) wordLen += w.size();
 int pad = L - wordLen;
 string s;
 if (line.size() == 1) {
 int left = pad / 2;
 s += string(left, '_') + line[0] + string(pad - left, '_');
 } else {
 int gaps = line.size() - 1;
 int base = pad / gaps, extra = pad % gaps;
 for (size_t j = 0; j < line.size(); j++) {
 s += line[j];
 if ((int)j < gaps) {
 int sp = base + ((int)j < extra ? 1 : 0);
 s += string(sp, '_');
 }
 }
 }
 out.push_back(s);
 }
 return out;
}

