        dp[0] = 0;
        for (int mask = 0; mask < (1 << k); mask++) {
            if (dp[mask] >= 1e17) continue;
            for (auto& [s, price] : options) {
                int nm = mask | s;
                if (dp[mask] + price < dp[nm]) dp[nm] = dp[mask] + price;
            }
        }
        return (int) dp[FULL];
    }
