    vector<string> tailNLines(vector<string>& lines, int n) {
        if (n <= 0) return {};
        if (n >= (int) lines.size()) return lines;
        return vector<string>(lines.end() - n, lines.end());
    }
};

class Solution {
    static int regionOf(String ip) {
        String[] parts = ip.split("\\.");
        if (parts.length != 4) return -1;
        int first = 0;
        for (int idx = 0; idx < 4; idx++) {
            String p = parts[idx];
            if (p.isEmpty() || (p.length() > 1 && p.charAt(0) == '0')) return -1;
            for (char c : p.toCharArray()) if (!Character.isDigit(c)) return -1;
            int v;
            try { v = Integer.parseInt(p); } catch (Exception e) { return -1; }
            if (v < 0 || v > 255) return -1;
            if (idx == 0) first = v;
        }
        if (first <= 127) return 1;
        if (first <= 191) return 2;
        if (first <= 223) return 3;
        if (first <= 239) return 4;
        return 5;
    }
    static int[] getRegions(String[] ips) {
        int[] out = new int[ips.length];
        for (int i = 0; i < ips.length; i++) out[i] = regionOf(ips[i]);
        return out;
    }
}

int regionOf(const string& ip) {
 vector<string> parts;
 string cur;
 for (char c : ip) {
 if (c == '.') { parts.push_back(cur); cur.clear(); }
 else cur += c;
 }
 parts.push_back(cur);
 if (parts.size() != 4) return -1;
 int first = 0;
 for (int idx = 0; idx < 4; ++idx) {
 auto& p = parts[idx];
 if (p.empty() || (p.size() > 1 && p[0] == '0')) return -1;
 for (char c : p) if (!isdigit(c)) return -1;
 int v = stoi(p);
 if (v < 0 || v > 255) return -1;
 if (idx == 0) first = v;
 }
 if (first <= 127) return 1;
 if (first <= 191) return 2;
 if (first <= 223) return 3;
 if (first <= 239) return 4;
 return 5;
}

vector<int> getRegions(vector<string>& ips) {
 vector<int> out;
 for (auto& ip : ips) out.push_back(regionOf(ip));
 return out;
}

class Solution {
    static long beaconSignal(long x1, long y1, long x2, long y2, long xl, long yl, long R) {
        long xLo = Math.max(x1, xl - R);
        long xHi = Math.min(x2, xl + R);
        long total = 0;
        long R2 = R * R;
        for (long x = xLo; x <= xHi; x++) {
            long dx2 = (x - xl) * (x - xl);
            if (dx2 > R2) continue;
            long h = (long) Math.sqrt((double) (R2 - dx2));
            while ((h + 1) * (h + 1) <= R2 - dx2) h++;
            while (h * h > R2 - dx2) h--;
            long yLo = Math.max(y1, yl - h);
            long yHi = Math.min(y2, yl + h);
            if (yLo <= yHi) total += yHi - yLo + 1;
        }
        return total;
    }
}

