def find_minimum_time(processSize: List[int], capacity: List[int]) -> int:
    if max(processSize) > max(capacity):
        return -1
    processSize_sorted = sorted(processSize, reverse=True)
    cap_sorted = sorted(capacity, reverse=True)

    def can_finish(T: int) -> bool:
        slots = (T + 1) // 2
        cap_slot_used = [0] * len(cap_sorted)
        for sz in processSize_sorted:
            placed = False
            for i, c in enumerate(cap_sorted):
                if c >= sz and cap_slot_used[i] < slots:
                    cap_slot_used[i] += 1
                    placed = True
                    break
            if not placed:
                return False
        return True

    lo, hi = 1, 2 * len(processSize) + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if can_finish(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

import java.util.*;

class Solution {
    int findMinimumTime(int[] processSize, int[] capacity) {
        int maxP = 0, maxC = 0;
        for (int x : processSize) maxP = Math.max(maxP, x);
        for (int x : capacity) maxC = Math.max(maxC, x);
        if (maxP > maxC) return -1;
        Integer[] ps = Arrays.stream(processSize).boxed().toArray(Integer[]::new);
        Arrays.sort(ps, Comparator.reverseOrder());
        Integer[] cs = Arrays.stream(capacity).boxed().toArray(Integer[]::new);
        Arrays.sort(cs, Comparator.reverseOrder());
        int lo = 1, hi = 2 * processSize.length + 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (canFinish(ps, cs, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean canFinish(Integer[] ps, Integer[] cs, int T) {
        int slots = (T + 1) / 2;
        int[] used = new int[cs.length];
        for (int sz : ps) {
            boolean placed = false;
            for (int i = 0; i < cs.length; i++) {
                if (cs[i] >= sz && used[i] < slots) { used[i]++; placed = true; break; }
            }
            if (!placed) return false;
        }
        return true;
    }
}

class Solution {
public:
    int findMinimumTime(vector<int>& processSize, vector<int>& capacity) {
        int maxP = *max_element(processSize.begin(), processSize.end());
        int maxC = *max_element(capacity.begin(), capacity.end());
        if (maxP > maxC) return -1;
        vector<int> ps = processSize, cs = capacity;
        sort(ps.begin(), ps.end(), greater<int>());
        sort(cs.begin(), cs.end(), greater<int>());
        int lo = 1, hi = 2 * (int) ps.size() + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int slots = (mid + 1) / 2;
            vector<int> used(cs.size(), 0);
            bool ok = true;
            for (int sz : ps) {
                bool placed = false;
                for (size_t i = 0; i < cs.size(); ++i) {
                    if (cs[i] >= sz && used[i] < slots) { used[i]++; placed = true; break; }
                }
                if (!placed) { ok = false; break; }
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

