from collections import deque

def maximum_time_required(g_nodes: int, g_from: List[int], g_to: List[int]) -> int:
    adj = [[] for _ in range(g_nodes + 1)]
    for u, v in zip(g_from, g_to):
        adj[u].append(v); adj[v].append(u)

    def bfs(src):
        dist = [-1] * (g_nodes + 1)
        dist[src] = 0
        q = deque([src])
        far, far_d = src, 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    if dist[v] > far_d:
                        far_d = dist[v]; far = v
                    q.append(v)
        return far, far_d

    u, _ = bfs(1)
    _, d = bfs(u)
    return d

import java.util.*;

class Solution {
    int maximumTimeRequiredToTransferData(int g_nodes, int[] g_from, int[] g_to) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= g_nodes; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < g_from.length; i++) {
            adj.get(g_from[i]).add(g_to[i]);
            adj.get(g_to[i]).add(g_from[i]);
        }
        int[] u = bfs(1, g_nodes, adj);
        int[] d = bfs(u[0], g_nodes, adj);
        return d[1];
    }

    private int[] bfs(int src, int n, List<List<Integer>> adj) {
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        dist[src] = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(src);
        int far = src, farD = 0;
        while (!q.isEmpty()) {
            int x = q.poll();
            for (int y : adj.get(x)) if (dist[y] == -1) {
                dist[y] = dist[x] + 1;
                if (dist[y] > farD) { farD = dist[y]; far = y; }
                q.add(y);
            }
        }
        return new int[]{far, farD};
    }
}

class Solution {
public:
    int maximumTimeRequiredToTransferData(int g_nodes, vector<int>& g_from, vector<int>& g_to) {
        vector<vector<int>> adj(g_nodes + 1);
        for (size_t i = 0; i < g_from.size(); ++i) {
            adj[g_from[i]].push_back(g_to[i]);
            adj[g_to[i]].push_back(g_from[i]);
        }
        auto bfs = [&](int src) {
            vector<int> dist(g_nodes + 1, -1);
            dist[src] = 0;
            queue<int> q; q.push(src);
            int far = src, farD = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    if (dist[v] > farD) { farD = dist[v]; far = v; }
                    q.push(v);
                }
            }
            return make_pair(far, farD);
        };
        auto p1 = bfs(1);
        auto p2 = bfs(p1.first);
        return p2.second;
    }
};

from math import comb

def get_triplet_count(a, d):
    cnt = [0] * d
    for x in a:
        cnt[x % d] += 1
    ans = 0
    for r1 in range(d):
        for r2 in range(r1, d):
            r3 = (d - (r1 + r2) % d) % d
            if r3 < r2:
                continue
            if r1 == r2 == r3:
                ans += comb(cnt[r1], 3)
            elif r1 == r2:
                ans += comb(cnt[r1], 2) * cnt[r3]
            elif r2 == r3:
                ans += cnt[r1] * comb(cnt[r2], 2)
            else:
                ans += cnt[r1] * cnt[r2] * cnt[r3]
    return ans

class Solution {
    static long getTripletCount(int[] a, int d) {
        long[] cnt = new long[d];
        for (int x : a) cnt[((x % d) + d) % d]++;
        long ans = 0;
        for (int r1 = 0; r1 < d; r1++)
            for (int r2 = r1; r2 < d; r2++) {
                int r3 = ((d - (r1 + r2) % d) % d);
                if (r3 < r2) continue;
                if (r1 == r2 && r2 == r3) ans += cnt[r1] * (cnt[r1] - 1) * (cnt[r1] - 2) / 6;
                else if (r1 == r2) ans += cnt[r1] * (cnt[r1] - 1) / 2 * cnt[r3];
                else if (r2 == r3) ans += cnt[r1] * cnt[r2] * (cnt[r2] - 1) / 2;
                else ans += cnt[r1] * cnt[r2] * cnt[r3];
            }
        return ans;
    }
}

