def coprime_count(A):
    def phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result
    return [phi(x) for x in A]

class Solution {
    static int phi(int n) {
        int res = n;
        for (int p = 2; (long) p * p <= n; p++) {
            if (n % p == 0) {
                while (n % p == 0) n /= p;
                res -= res / p;
            }
        }
        if (n > 1) res -= res / n;
        return res;
    }
    static int[] coprimeCount(int[] A) {
        int[] out = new int[A.length];
        for (int i = 0; i < A.length; i++) out[i] = phi(A[i]);
        return out;
    }
}

