from typing import List

def cars_left(n: int, direction: List[int], strength: List[int]) -> List[int]:
    stack: list = []  # indices of cars going right
    survivors: list = []
    for i in range(n):
        if direction[i] == 1:
            stack.append(i)
        else:
            # left-going car collides with right-going stack top
            alive = True
            while stack and alive:
                top = stack[-1]
                if strength[top] > strength[i]:
                    alive = False
                elif strength[top] < strength[i]:
                    stack.pop()
                else:
                    stack.pop(); alive = False
            if alive:
                survivors.append(i)
    survivors.extend(stack)
    survivors.sort()
    return survivors

import java.util.*;

class Solution {
    public int[] carsLeft(int n, int[] direction, int[] strength) {
        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> survivors = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (direction[i] == 1) stack.push(i);
            else {
                boolean alive = true;
                while (!stack.isEmpty() && alive) {
                    int top = stack.peek();
                    if (strength[top] > strength[i]) alive = false;
                    else if (strength[top] < strength[i]) stack.pop();
                    else { stack.pop(); alive = false; }
                }
                if (alive) survivors.add(i);
            }
        }
        survivors.addAll(stack);
        Collections.sort(survivors);
        return survivors.stream().mapToInt(Integer::intValue).toArray();
    }
}

