class Solution {
public:
    vector<int> carsLeft(int n, vector<int>& direction, vector<int>& strength) {
        vector<int> stack, survivors;
        for (int i = 0; i < n; i++) {
            if (direction[i] == 1) stack.push_back(i);
            else {
                bool alive = true;
                while (!stack.empty() && alive) {
                    int top = stack.back();
                    if (strength[top] > strength[i]) alive = false;
                    else if (strength[top] < strength[i]) stack.pop_back();
                    else { stack.pop_back(); alive = false; }
                }
                if (alive) survivors.push_back(i);
            }
        }
        for (int x : stack) survivors.push_back(x);
        sort(survivors.begin(), survivors.end());
        return survivors;
    }
};

class Solution {
    public long countInvestablePeriods(int[] price, int maxPrice, int minPrice) {
        long total = 0;
        int segStart = 0, lastMax = -1, lastMin = -1;
        for (int r = 0; r < price.length; r++) {
            int p = price[r];
            if (p < minPrice || p > maxPrice) {
                segStart = r + 1; lastMax = lastMin = -1; continue;
            }
            if (p == maxPrice) lastMax = r;
            if (p == minPrice) lastMin = r;
            if (lastMax >= segStart && lastMin >= segStart) {
                total += Math.min(lastMax, lastMin) - segStart + 1;
            }
        }
        return total;
    }
}

