class Solution {
    static final long MOD = 1_000_000_007L;
    public int countValidPasswords(int n, int k) {
        long[] dp = new long[k];
        dp[1] = 26;
        for (int i = 2; i <= n; i++) {
            long[] nxt = new long[k];
            long total = 0;
            for (long v : dp) total = (total + v) % MOD;
            nxt[1] = total * 25 % MOD;
            for (int j = 2; j < k; j++) nxt[j] = dp[j - 1];
            dp = nxt;
        }
        long s = 0;
        for (long v : dp) s = (s + v) % MOD;
        return (int) s;
    }
}

