def find_minimum_possible_size(arr: List[int]) -> int:
    arr.sort()
    n = len(arr)
    i = 0; j = n // 2
    removed = 0
    while i < n // 2 and j < n:
        if 2 * arr[i] <= arr[j]:
            removed += 1
            i += 1; j += 1
        else:
            j += 1
    return n - removed

