def find_odd(series: List[str]) -> str:
    def diffs(s: str):
        return tuple(ord(s[i + 1]) - ord(s[i]) for i in range(len(s) - 1))
    seq = [diffs(s) for s in series]
    from collections import Counter
    c = Counter(seq)
    for s, d in zip(series, seq):
        if c[d] == 1:
            return s
    return series[-1]

import java.util.*;

class Solution {
    public String findOdd(String[] series) {
        Map<String, Integer> cnt = new HashMap<>();
        String[] keys = new String[series.length];
        for (int i = 0; i < series.length; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 1; j < series[i].length(); j++) sb.append(series[i].charAt(j) - series[i].charAt(j - 1)).append(",");
            keys[i] = sb.toString();
            cnt.merge(keys[i], 1, Integer::sum);
        }
        for (int i = 0; i < series.length; i++) if (cnt.get(keys[i]) == 1) return series[i];
        return series[series.length - 1];
    }
}

