class Solution {
    static final long MOD = 1_000_000_007L;
    public int goodStrings(int n, int d) {
        long[] dp = new long[26];
        Arrays.fill(dp, 1);
        for (int i = 1; i < n; i++) {
            long[] pre = new long[27];
            for (int j = 0; j < 26; j++) pre[j + 1] = (pre[j] + dp[j]) % MOD;
            long[] nxt = new long[26];
            for (int c = 0; c < 26; c++) {
                int lo = Math.max(0, c - d), hi = Math.min(25, c + d);
                nxt[c] = (pre[hi + 1] - pre[lo] + MOD) % MOD;
            }
            dp = nxt;
        }
        long s = 0;
        for (long v : dp) s = (s + v) % MOD;
        return (int) s;
    }
}

