class Solution {
    public int[] hasVowels(String[] strArr, String[] queries) {
        Set<Character> vow = Set.of('a','e','i','o','u');
        int[] pre = new int[strArr.length + 1];
        for (int i = 0; i < strArr.length; i++) {
            String s = strArr[i];
            boolean ok = !s.isEmpty() && vow.contains(s.charAt(0)) && vow.contains(s.charAt(s.length() - 1));
            pre[i + 1] = pre[i] + (ok ? 1 : 0);
        }
        int[] out = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            String[] p = queries[q].split("-");
            int i = Integer.parseInt(p[0]), r = Integer.parseInt(p[1]);
            out[q] = pre[r] - pre[i - 1];
        }
        return out;
    }
}

