def load_balancing(n: int, burst_time: List[int]) -> int:
    def can(limit: int) -> bool:
        segs = 1; cur = 0
        for t in burst_time:
            if t > limit: return False
            if cur + t > limit:
                segs += 1; cur = t
                if segs > n: return False
            else:
                cur += t
        return segs <= n
    lo, hi = max(burst_time), sum(burst_time)
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid): hi = mid
        else: lo = mid + 1
    return lo

class Solution {
    public long loadBalancing(int n, int[] burstTime) {
        long lo = 0, hi = 0;
        for (int t : burstTime) { lo = Math.max(lo, t); hi += t; }
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            int segs = 1; long cur = 0;
            boolean ok = true;
            for (int t : burstTime) {
                if (t > mid) { ok = false; break; }
                if (cur + t > mid) { segs++; cur = t; if (segs > n) { ok = false; break; } }
                else cur += t;
            }
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

