def maximize_beauty(arr: List[int]) -> int:
    n = len(arr)
    # dp[i] = max beauty considering up to index i, last kept is at position k = arr[i] in final
    # i.e. # picks so that picked elements' values equal 1, 2, ...
    # equivalent LIS where arr[i] - (#picks so far) ≥ 0
    # Standard approach: dp[k] = min original index needed to achieve "k beautiful kept so far"
    INF = float('inf')
    best = [INF] * (n + 1)
    best[0] = -1
    for i in range(n):
        # for each k where best[k] < i and arr[i] >= k + 1 and (i - best[k] - 1) >= arr[i] - 1 - k, can extend to k+1
        for k in range(n, 0, -1):
            if best[k - 1] != INF and best[k - 1] < i:
                # need arr[i] to be exactly the position in final array
                # final position of i-th kept element = k; we need arr[i] == k
                if arr[i] == k:
                    best[k] = min(best[k], i)
    for k in range(n, -1, -1):
        if best[k] != INF:
            return k
    return 0

class Solution {
    public int maximizeBeauty(int[] arr) {
        int n = arr.length;
        int[] best = new int[n + 1];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[0] = -1;
        for (int i = 0; i < n; i++) {
            for (int k = n; k >= 1; k--) {
                if (best[k - 1] != Integer.MAX_VALUE && best[k - 1] < i && arr[i] == k) {
                    best[k] = Math.min(best[k], i);
                }
            }
        }
        for (int k = n; k >= 0; k--) if (best[k] != Integer.MAX_VALUE) return k;
        return 0;
    }
}

