class Solution {
    public long maxEvenSum(int[] arr) {
        long s = 0;
        for (int x : arr) if (x > 0) s += x;
        if (s % 2 == 0) return s;
        long bestPos = Long.MAX_VALUE, bestNeg = Long.MIN_VALUE;
        for (int x : arr) {
            if (x > 0 && x % 2 != 0) bestPos = Math.min(bestPos, x);
            if (x < 0 && x % 2 != 0) bestNeg = Math.max(bestNeg, x);
        }
        long best = Long.MIN_VALUE;
        if (bestPos != Long.MAX_VALUE) best = Math.max(best, s - bestPos);
        if (bestNeg != Long.MIN_VALUE) best = Math.max(best, s + bestNeg);
        return best == Long.MIN_VALUE ? 0 : best;
    }
}

