def get_minimum_operations(execution_time: List[int], x: int, y: int) -> int:
    def feasible(m: int) -> bool:
        need = 0
        for t in execution_time:
            rem = t - m * y
            if rem > 0:
                need += (rem + (x - y) - 1) // (x - y)
                if need > m: return False
        return need <= m
    lo, hi = 1, max(execution_time)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid): hi = mid
        else: lo = mid + 1
    return lo

