        for (int t : executionTime) hi = Math.max(hi, t);
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            long need = 0; boolean feas = true;
            for (int t : executionTime) {
                long rem = t - mid * y;
                if (rem > 0) { need += (rem + (x - y) - 1) / (x - y); if (need > mid) { feas = false; break; } }
            }
            if (feas) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

