def largest_sub_grid(grid: List[List[int]], max_sum: int) -> int:
    n = len(grid)
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            pre[i + 1][j + 1] = grid[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j]

    def can(s: int) -> bool:
        for i in range(n - s + 1):
            for j in range(n - s + 1):
                total = pre[i + s][j + s] - pre[i][j + s] - pre[i + s][j] + pre[i][j]
                if total <= max_sum: return True
        return False

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid): lo = mid
        else: hi = mid - 1
    return lo

class Solution {
    public int largestSubGrid(int[][] grid, long maxSum) {
        int n = grid.length;
        long[][] pre = new long[n + 1][n + 1];
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
            pre[i + 1][j + 1] = grid[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j];
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            boolean ok = false;
            for (int i = 0; i + mid <= n && !ok; i++)
                for (int j = 0; j + mid <= n; j++) {
                    long total = pre[i + mid][j + mid] - pre[i][j + mid] - pre[i + mid][j] + pre[i][j];
                    if (total <= maxSum) { ok = true; break; }
                }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

