class Solution {
public:
    long long sumOfSubarrayRegions(vector<int>& heights) {
        int n = heights.size();
        vector<int> left(n, -1), right(n, n);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && heights[st.back()] < heights[i]) { right[st.back()] = i; st.pop_back(); }
            left[i] = st.empty() ? -1 : st.back();
            st.push_back(i);
        }
        long long total = 0;
        for (int i = 0; i < n; i++) total += (long long)(right[i] - left[i] - 1);
        return total;
    }
};

from typing import List

def dfsSubsequences(s: str) -> List[str]:
    res = []
    def dfs(i, cur):
        if i == len(s):
            if cur: res.append(cur)
            return
        dfs(i + 1, cur + s[i])
        dfs(i + 1, cur)
    dfs(0, "")
    return sorted(res)

class Solution {
    String[] dfsSubsequences(String s) {
        List<String> res = new ArrayList<>();
        dfs(s, 0, new StringBuilder(), res);
        Collections.sort(res);
        return res.toArray(new String[0]);
    }

    private void dfs(String s, int i, StringBuilder cur, List<String> res) {
        if (i == s.length()) {
            if (cur.length() > 0) res.add(cur.toString());
            return;
        }
        cur.append(s.charAt(i));
        dfs(s, i + 1, cur, res);
        cur.deleteCharAt(cur.length() - 1);
        dfs(s, i + 1, cur, res);
    }
}

class Solution {
public:
    vector<string> dfsSubsequences(string s) {
        vector<string> res;
        string cur;
        dfs(s, 0, cur, res);
        sort(res.begin(), res.end());
        return res;
    }

private:
    void dfs(string& s, int i, string& cur, vector<string>& res) {
        if (i == (int)s.size()) {
            if (!cur.empty()) res.push_back(cur);
            return;
        }
        cur += s[i];
        dfs(s, i + 1, cur, res);
        cur.pop_back();
        dfs(s, i + 1, cur, res);
    }
};

def numberOfDivisibleSubstrings(word: str) -> int:
    # mapping (a,b,c)->1, (d,e,f)->2, ... phone keypad style
    mp = {}
    for i, group in enumerate(["abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"], start=1):
        for c in group:
            mp[c] = i
    n = len(word)
    cnt = 0
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += mp[word[j]]
            if s % (j - i + 1) == 0:
                cnt += 1
    return cnt

class Solution {
    int numberOfDivisibleSubstrings(String word) {
        int[] mp = new int[26];
        String[] groups = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        for (int g = 0; g < groups.length; g++) for (char c : groups[g].toCharArray()) mp[c - 'a'] = g + 1;
        int n = word.length(), cnt = 0;
        for (int i = 0; i < n; i++) {
            long s = 0;
            for (int j = i; j < n; j++) {
                s += mp[word.charAt(j) - 'a'];
                if (s % (j - i + 1) == 0) cnt++;
            }
        }
        return cnt;
    }
}

