class Solution {
public:
    vector<long long> shortestPathsToTargets(int n, vector<vector<int>>& edges, int source, vector<int>& targets) {
        vector<vector<pair<int, long long>>> g(n + 1);
        for (auto& e : edges) g[e[0]].push_back({e[1], e[2]});
        vector<long long> dist(n + 1, LLONG_MAX);
        dist[source] = 0;
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
        pq.push({0, source});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : g[u]) {
                long long nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; pq.push({nd, v}); }
            }
        }
        vector<long long> out;
        for (int t : targets) out.push_back(dist[t] == LLONG_MAX ? -1 : dist[t]);
        return out;
    }
};

import java.util.*;

class Solution {
    static final long MOD = 1_000_000_007L;
    public long countGoodSubsequences(int[] arr) {
        Map<Integer, Long> cnt = new HashMap<>();
        int maxV = 0;
        for (int x : arr) { cnt.merge(x, 1L, Long::sum); maxV = Math.max(maxV, x); }
        long total = 0;
        int v = 1;
        while (v <= maxV) {
            if (cnt.getOrDefault(v, 0L) == 0) { v++; continue; }
            int e = v;
            while (e + 1 <= maxV && cnt.getOrDefault(e + 1, 0L) > 0) e++;
            long chain = 0;
            for (int u = e; u >= v; u--) {
                chain = cnt.get(u) * (1 + chain) % MOD;
                total = (total + chain) % MOD;
            }
            v = e + 1;
        }
        return total;
    }
}

