class Solution {
    public long getMaximumEdges(int employeeNodes, int[] employeeFrom, int[] employeeTo,
                                int[] specialEmployees, int maxConnections) {
        int n = employeeNodes, k = specialEmployees.length;
        long total = (long) n * (n - 1) / 2;
        long existing = employeeFrom.length;
        long forbiddenSpecials = (long) k * (k - 1) / 2;
        int nonSpecial = n - k;
        long forbiddenNon = (long) nonSpecial * Math.max(0, k - maxConnections);
        return total - existing - forbiddenSpecials - forbiddenNon;
    }
}

