import java.util.*;

class Solution {
    public int getMinimumTime(int[] players, int[] points) {
        Arrays.sort(players); Arrays.sort(points);
        int n = players.length, m = points.length;
        if (m == 0) return 0;
        int lo = 0, hi = Math.max(Math.abs(points[m-1] - players[0]), Math.abs(points[0] - players[n-1])) + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (can(players, points, mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    boolean can(int[] players, int[] points, int t) {
        int i = 0, m = points.length;
        for (int p : players) {
            if (i == m) return true;
            if (points[i] > p + t) continue;
            if (points[i] < p - t) return false;
            long leftmost = points[i];
            long leftCost = Math.max(0, p - leftmost);
            long reach = (leftmost >= p) ? (long)p + t : (long)p + Math.max(0, t - 2 * leftCost);
            while (i < m && points[i] <= reach) i++;
        }
        return i == m;
    }
}

