from collections import deque
from typing import List

def get_node_to_remove(g_nodes: int, g_from: List[int], g_to: List[int], malware: List[int]) -> int:
    n = g_nodes
    adj = [[] for _ in range(n + 1)]
    for u, v in zip(g_from, g_to):
        adj[u].append(v); adj[v].append(u)
    infected_init = [i + 1 for i, v in enumerate(malware) if v == 1]

    def infect_count(excluded: int) -> int:
        seen = {excluded}
        q = deque()
        for s in infected_init:
            if s != excluded:
                if s not in seen:
                    seen.add(s); q.append(s)
        cnt = len(seen) - 1  # exclude the excluded
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v); q.append(v); cnt += 1
        return cnt

    best_r = -1; best_cnt = float('inf')
    for r in sorted(infected_init):
        c = infect_count(r)
        if c < best_cnt:
            best_cnt = c; best_r = r
    return best_r if best_r != -1 else (infected_init[0] if infected_init else -1)

import java.util.*;

class Solution {
    public int getNodeToRemove(int gNodes, int[] gFrom, int[] gTo, int[] malware) {
        int n = gNodes;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < gFrom.length; i++) { adj.get(gFrom[i]).add(gTo[i]); adj.get(gTo[i]).add(gFrom[i]); }
        List<Integer> initInfected = new ArrayList<>();
        for (int i = 0; i < malware.length; i++) if (malware[i] == 1) initInfected.add(i + 1);
        Collections.sort(initInfected);
        int bestR = initInfected.isEmpty() ? -1 : initInfected.get(0);
        int bestCnt = Integer.MAX_VALUE;
        for (int r : initInfected) {
            Set<Integer> seen = new HashSet<>(); seen.add(r);
            Deque<Integer> q = new ArrayDeque<>();
            for (int s : initInfected) if (s != r && seen.add(s)) q.add(s);
            int cnt = seen.size() - 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u)) if (seen.add(v)) { q.add(v); cnt++; }
            }
            if (cnt < bestCnt) { bestCnt = cnt; bestR = r; }
        }
        return bestR;
    }
}

