def max_energy(mat: List[List[int]]) -> int:
    INF = float('inf')
    dp = [list(row) for row in mat]
    for i in range(1, 4):
        for j in range(4):
            best = INF
            for dj in (-1, 0, 1):
                pj = j + dj
                if 0 <= pj < 4:
                    best = min(best, dp[i - 1][pj])
            dp[i][j] = mat[i][j] + best
    return 100 - min(dp[3])

class Solution {
    public int maxEnergy(int[][] mat) {
        int[][] dp = new int[4][4];
        for (int j = 0; j < 4; j++) dp[0][j] = mat[0][j];
        for (int i = 1; i < 4; i++) for (int j = 0; j < 4; j++) {
            int best = Integer.MAX_VALUE;
            for (int dj = -1; dj <= 1; dj++) {
                int pj = j + dj;
                if (pj >= 0 && pj < 4) best = Math.min(best, dp[i - 1][pj]);
            }
            dp[i][j] = mat[i][j] + best;
        }
        int mn = Integer.MAX_VALUE;
        for (int j = 0; j < 4; j++) mn = Math.min(mn, dp[3][j]);
        return 100 - mn;
    }
}

