from typing import List

def throw_the_ball(receiver: List[int], seconds: int) -> int:
    pos = 1
    visited = {pos: 0}
    path = [pos]
    for step in range(1, seconds + 1):
        pos = receiver[pos - 1]
        if pos in visited:
            cycle_len = step - visited[pos]
            rem = (seconds - step) % cycle_len
            for _ in range(rem):
                pos = receiver[pos - 1]
            return pos
        visited[pos] = step
        path.append(pos)
    return pos

import java.util.*;

class Solution {
    public int throwTheBall(int[] receiver, long seconds) {
        int pos = 1;
        Map<Integer, Long> visited = new HashMap<>();
        visited.put(pos, 0L);
        for (long step = 1; step <= seconds; step++) {
            pos = receiver[pos - 1];
            if (visited.containsKey(pos)) {
                long cycleLen = step - visited.get(pos);
                long rem = (seconds - step) % cycleLen;
                for (long t = 0; t < rem; t++) pos = receiver[pos - 1];
                return pos;
            }
            visited.put(pos, step);
        }
        return pos;
    }
}

