import java.util.*;

class Solution {
    public long tdeskFlights(int[] c2d, int[] d2c, int journies) {
        Arrays.sort(c2d); Arrays.sort(d2c);
        long t = 0;
        for (int k = 0; k < journies; k++) {
            int i = lowerBound(c2d, (int) t);
            if (i >= c2d.length) return -1;
            t = c2d[i] + 100;
            int j = lowerBound(d2c, (int) t);
            if (j >= d2c.length) return -1;
            t = d2c[j] + 100;
        }
        return t;
    }
    int lowerBound(int[] a, int v) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) / 2; if (a[m] < v) lo = m + 1; else hi = m; }
        return lo;
    }
}

