class Solution {
    public long friendGroups(int[] friendList, int minimumPairs) {
        int n = friendList.length;
        long count = 0;
        for (int l = 0; l < n; l++) {
            Map<Integer, Integer> cnt = new HashMap<>();
            long pairs = 0;
            for (int r = l; r < n; r++) {
                pairs += cnt.getOrDefault(friendList[r], 0);
                cnt.merge(friendList[r], 1, Integer::sum);
                if (pairs >= minimumPairs) { count += n - r; break; }
            }
        }
        return count;
    }
}

