def transform_string(S: str) -> str:
    pairs = {("A", "B"), ("B", "A"), ("C", "D"), ("D", "C")}
    stack: list = []
    for c in S:
        if stack and (stack[-1], c) in pairs:
            stack.pop()
        else:
            stack.append(c)
    return "".join(stack)

class Solution {
