        StringBuilder st = new StringBuilder();
        for (char c : S.toCharArray()) {
            int n = st.length();
            if (n > 0) {
                char t = st.charAt(n - 1);
                if ((t == 'A' && c == 'B') || (t == 'B' && c == 'A')
                    || (t == 'C' && c == 'D') || (t == 'D' && c == 'C')) {
                    st.deleteCharAt(n - 1);
                    continue;
                }
            }
            st.append(c);
        }
        return st.toString();
    }
}

