            signs[i - 1] = d == 0 ? 0 : (d > 0 ? 1 : -1);
        }
        vector<int> res(n);
        int pos = 0;
        auto matches = [&](int start, vector<int>& pat) {
            for (size_t j = 0; j < pat.size(); j++) if (signs[start + j] != pat[j]) return false;
            return true;
        };
        for (int i = 0; i < n; i++) {
