class Solution {
    long increasingPaths(int[][] grid) {
        int rows = grid.length;
        int cols = 0;
        for (int[] r : grid) cols = Math.max(cols, r.length);
        List<int[]> cells = new ArrayList<>();
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < grid[i].length; j++)
                cells.add(new int[]{grid[i][j], i, j});
        cells.sort((a, b) -> a[0] - b[0]);
        long[][] f = new long[rows][cols];
        long total = 0;
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        int cellCount = 0;
        for (int i = 0; i < rows; i++) cellCount += grid[i].length;
        for (int[] c : cells) {
            int v = c[0], i = c[1], j = c[2];
            f[i][j] = 1;
            for (int[] d : dirs) {
                int ni = i + d[0], nj = j + d[1];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < grid[ni].length && grid[ni][nj] < v) {
                    f[i][j] += f[ni][nj];
                }
            }
            total += f[i][j];
        }
        return total - cellCount;
    }
}

