def calculate_max_profit(stockPrices: List[str]) -> int:
    by_stock = defaultdict(list)
    for s in stockPrices:
        parts = s.split(",") if "," in s else s.split()
        stock, date, price = parts[0], parts[1], float(parts[2])
        by_stock[stock].append((date, price))
    best_cash = 1000.0
    for stock, lst in by_stock.items():
        lst.sort()
        cash = 1000.0
        for i in range(1, len(lst)):
            if lst[i][1] > lst[i - 1][1]:
                cash *= lst[i][1] / lst[i - 1][1]
        if cash > best_cash:
            best_cash = cash
    return round(best_cash - 1000)

