def chainOfCommand(n, parent, queries):
    from collections import defaultdict
    children = defaultdict(list)
    root = 0
    for i, p in enumerate(parent):
        if p == -1:
            root = i
        else:
            children[p].append(i)
    for p in children:
        children[p].sort()

    enter, leave = [0] * n, [0] * n
    tour = []

    def dfs(u):
        enter[u] = len(tour)
        tour.append(u)
        for c in children[u]:
            dfs(c)
        leave[u] = len(tour) - 1

    dfs(root)

    out = []
    for p, k in queries:
        idx = enter[p] + k - 1
        if idx > leave[p]:
            out.append(-1)
        else:
            out.append(tour[idx])
    return out

import java.util.*;

class Solution {
    int[] enter, leave;
    List<Integer> tour;
    List<List<Integer>> children;

    void dfs(int u) {
        enter[u] = tour.size();
        tour.add(u);
        for (int c : children.get(u)) dfs(c);
        leave[u] = tour.size() - 1;
    }

    int[] chainOfCommand(int n, int[] parent, int[][] queries) {
        children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        int root = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == -1) root = i;
            else children.get(parent[i]).add(i);
        }
        for (List<Integer> l : children) Collections.sort(l);
        enter = new int[n];
        leave = new int[n];
        tour = new ArrayList<>();
        dfs(root);
        int[] out = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int p = queries[q][0], k = queries[q][1];
            int idx = enter[p] + k - 1;
            out[q] = (idx > leave[p]) ? -1 : tour.get(idx);
        }
        return out;
    }
}

