def asteroid_game(size: List[int], direction: List[int]) -> List[int]:
    stk = []
    for s, d in zip(size, direction):
        alive = True
        while alive and d == 0 and stk and stk[-1][1] == 1:
            top_s, _ = stk[-1]
            if top_s < s:
                stk.pop()
            elif top_s == s:
                stk.pop()
                alive = False
            else:
                alive = False
        if alive:
            stk.append((s, d))
    return [s for s, _ in stk]

import java.util.*;

class Solution {
    int[] asteroidGame(int[] size, int[] direction) {
        Deque<int[]> stk = new ArrayDeque<>();
        for (int i = 0; i < size.length; i++) {
            int s = size[i], d = direction[i];
            boolean alive = true;
            while (alive && d == 0 && !stk.isEmpty() && stk.peek()[1] == 1) {
                int[] top = stk.peek();
                if (top[0] < s) stk.pop();
                else if (top[0] == s) { stk.pop(); alive = false; }
                else alive = false;
            }
            if (alive) stk.push(new int[]{s, d});
        }
        int[] res = new int[stk.size()];
        int idx = res.length - 1;
        for (int[] a : stk) res[idx--] = a[0];
        return res;
    }
}

class Solution {
public:
    vector<int> asteroidGame(vector<int>& size, vector<int>& direction) {
        vector<pair<int, int>> stk;
        for (size_t i = 0; i < size.size(); ++i) {
            int s = size[i], d = direction[i];
            bool alive = true;
            while (alive && d == 0 && !stk.empty() && stk.back().second == 1) {
                if (stk.back().first < s) stk.pop_back();
                else if (stk.back().first == s) { stk.pop_back(); alive = false; }
                else alive = false;
            }
            if (alive) stk.push_back({s, d});
        }
        vector<int> res;
        for (auto& p : stk) res.push_back(p.first);
        return res;
    }
};

import java.util.*;

class Solution {
    int findBestPath(int n, int m, int startRow, int startColumn, int endRow, int endColumn,
                     int[] obstacleRow, int[] obstacleColumn) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        Deque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < obstacleRow.length; i++) {
            dist[obstacleRow[i]][obstacleColumn[i]] = 0;
            q.add(new int[]{obstacleRow[i], obstacleColumn[i]});
        }
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && dist[nr][nc] > dist[cur[0]][cur[1]] + 1) {
                    dist[nr][nc] = dist[cur[0]][cur[1]] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        int[][] best = new int[n][m];
        for (int[] row : best) Arrays.fill(row, -1);
        best[startRow][startColumn] = dist[startRow][startColumn];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        pq.add(new int[]{best[startRow][startColumn], startRow, startColumn});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int v = cur[0], r = cur[1], c = cur[2];
            if (r == endRow && c == endColumn) return v;
            if (v < best[r][c]) continue;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nv = Math.min(v, dist[nr][nc]);
                    if (nv > best[nr][nc]) { best[nr][nc] = nv; pq.add(new int[]{nv, nr, nc}); }
                }
            }
        }
        return best[endRow][endColumn];
    }
}

class Solution {
public:
    int findBestPath(int n, int m, int startRow, int startColumn, int endRow, int endColumn,
                      vector<int>& obstacleRow, vector<int>& obstacleColumn) {
        vector<vector<int>> dist(n, vector<int>(m, INT_MAX));
        queue<pair<int, int>> q;
        for (size_t i = 0; i < obstacleRow.size(); ++i) {
            dist[obstacleRow[i]][obstacleColumn[i]] = 0;
            q.push({obstacleRow[i], obstacleColumn[i]});
        }
        int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && dist[nr][nc] > dist[r][c] + 1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }
        vector<vector<int>> best(n, vector<int>(m, -1));
        best[startRow][startColumn] = dist[startRow][startColumn];
        priority_queue<tuple<int, int, int>> pq;
        pq.push({best[startRow][startColumn], startRow, startColumn});
        while (!pq.empty()) {
            auto [v, r, c] = pq.top(); pq.pop();
            if (r == endRow && c == endColumn) return v;
            if (v < best[r][c]) continue;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nv = min(v, dist[nr][nc]);
                    if (nv > best[nr][nc]) { best[nr][nc] = nv; pq.push({nv, nr, nc}); }
                }
            }
        }
        return best[endRow][endColumn];
    }
};

from typing import List

def max_sub_square_under_k(matrix: List[List[int]], k: int) -> int:
    n = len(matrix)
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            pre[i + 1][j + 1] = matrix[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j]

    def submat_sum(r1, c1, r2, c2):
        return pre[r2 + 1][c2 + 1] - pre[r1][c2 + 1] - pre[r2 + 1][c1] + pre[r1][c1]

    ans = 0
    for L in range(1, n + 1):
        ok = True
        for i in range(n - L + 1):
            for j in range(n - L + 1):
                if submat_sum(i, j, i + L - 1, j + L - 1) >= k:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            ans = L
        else:
            break
    return ans

class Solution {
    int maxSubSquareUnderK(int[][] matrix, int k) {
        int n = matrix.length;
        long[][] pre = new long[n + 1][n + 1];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                pre[i + 1][j + 1] = matrix[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j];
        int ans = 0;
        for (int L = 1; L <= n; L++) {
            boolean ok = true;
            for (int i = 0; i + L <= n && ok; i++)
                for (int j = 0; j + L <= n && ok; j++) {
                    long s = pre[i + L][j + L] - pre[i][j + L] - pre[i + L][j] + pre[i][j];
                    if (s >= k) ok = false;
                }
            if (ok) ans = L; else break;
        }
        return ans;
    }
}

