        Map<String, Integer> freq = new HashMap<>();
        String[] strs = new String[fragments.length];
        for (int i = 0; i < fragments.length; i++) {
            strs[i] = String.valueOf(fragments[i]);
            freq.merge(strs[i], 1, Integer::sum);
