def solution(memory, queries):
    mem = memory[:]
    n = len(mem)
    id_to_range = {}  # id -> (start, length)
    counter = 0
    out = []
    for op, x in queries:
        if op == 0:
            sz = x
            placed = -1
            for s in range(0, n, 8):
                if s + sz > n: break
                if all(mem[s + k] == 0 for k in range(sz)):
                    for k in range(sz):
                        mem[s + k] = 1
                    counter += 1
                    id_to_range[counter] = (s, sz)
                    placed = s
                    break
            out.append(placed)
        else:
            aid = x
            if aid in id_to_range:
                s, sz = id_to_range.pop(aid)
                for k in range(sz):
                    mem[s + k] = 0
                out.append(sz)
            else:
                out.append(-1)
    return out

class Solution {
    public int[] solution(int[] memory, int[][] queries) {
        int n = memory.length;
        int[] mem = memory.clone();
        Map<Integer, int[]> idRange = new HashMap<>();
        int counter = 0;
        int[] out = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int op = queries[q][0], x = queries[q][1];
            if (op == 0) {
                int sz = x, placed = -1;
                for (int s = 0; s + sz <= n; s += 8) {
                    boolean free = true;
                    for (int k = 0; k < sz; k++) if (mem[s + k] != 0) { free = false; break; }
                    if (free) {
                        for (int k = 0; k < sz; k++) mem[s + k] = 1;
                        counter++;
                        idRange.put(counter, new int[]{s, sz});
                        placed = s;
                        break;
                    }
                }
                out[q] = placed;
            } else {
                int aid = x;
                int[] r = idRange.remove(aid);
                if (r == null) out[q] = -1;
                else {
                    for (int k = 0; k < r[1]; k++) mem[r[0] + k] = 0;
                    out[q] = r[1];
                }
            }
        }
        return out;
    }
}

