class Solution {
    String[] solution(String[][] paragraphs, String[] aligns, int width) {
        List<String> out = new ArrayList<>();
        StringBuilder bsb = new StringBuilder();
        for (int i = 0; i < width + 2; i++) bsb.append('*');
        String border = bsb.toString();
        out.add(border);
        for (int p = 0; p < paragraphs.length; p++) {
            String[] para = paragraphs[p];
            String align = aligns[p];
            int i = 0;
            while (i < para.length) {
                int j = i, cur = para[j].length();
                j++;
                while (j < para.length && cur + 1 + para[j].length() <= width) {
                    cur += 1 + para[j].length();
                    j++;
                }
                StringBuilder line = new StringBuilder();
                for (int k = i; k < j; k++) {
                    if (k > i) line.append(' ');
                    line.append(para[k]);
                }
                int pad = width - line.length();
                StringBuilder spaces = new StringBuilder();
                for (int s = 0; s < pad; s++) spaces.append(' ');
                String padded = align.equals("LEFT") ? line.toString() + spaces
                                                    : spaces.toString() + line.toString();
                out.add("*" + padded + "*");
                i = j;
            }
        }
        out.add(border);
        return out.toArray(new String[0]);
    }
}

