from typing import List

def calculateTotalRegion(heights: List[int]) -> int:
    n = len(heights)
    left = [0] * n   # 最远左下标 (>= 0)
    right = [n - 1] * n
    stack = []
    for i in range(n):
        # 严格大才弹出，相等的也归入同一组（避免重复，使用 ≥ / >）
        while stack and heights[stack[-1]] < heights[i]:
            stack.pop()
        left[i] = stack[-1] + 1 if stack else 0
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        right[i] = stack[-1] - 1 if stack else n - 1
        stack.append(i)
    return sum(right[i] - left[i] + 1 for i in range(n))

import java.util.*;

class Solution {
    long calculateTotalRegion(int[] heights) {
        int n = heights.length;
        int[] left = new int[n], right = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && heights[st.peek()] < heights[i]) st.pop();
            left[i] = st.isEmpty() ? 0 : st.peek() + 1;
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && heights[st.peek()] <= heights[i]) st.pop();
            right[i] = st.isEmpty() ? n - 1 : st.peek() - 1;
            st.push(i);
        }
        long ans = 0;
        for (int i = 0; i < n; i++) ans += right[i] - left[i] + 1;
        return ans;
    }
}

class Solution {
public:
    long long calculateTotalRegion(vector<int>& heights) {
        int n = heights.size();
        vector<int> left(n), right(n);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && heights[st.top()] < heights[i]) st.pop();
            left[i] = st.empty() ? 0 : st.top() + 1;
            st.push(i);
        }
        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && heights[st.top()] <= heights[i]) st.pop();
            right[i] = st.empty() ? n - 1 : st.top() - 1;
            st.push(i);
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += right[i] - left[i] + 1;
        return ans;
    }
};

