def incremovableSubarrayCount(nums: List[int]) -> int:
    n = len(nums)
    L = 1
    while L < n and nums[L] > nums[L - 1]:
        L += 1
    if L == n:
        return n * (n + 1) // 2
    # 最长严格递增后缀
    R = 1
    while R < n and nums[n - R - 1] < nums[n - R]:
        R += 1
    ans = R + 1  # i = 0 时，j ∈ [0..R]
    # 双指针
    j_ptr = R
    for i in range(1, L + 1):
        while j_ptr > 0 and nums[n - j_ptr] <= nums[i - 1]:
            j_ptr -= 1
        max_j = j_ptr
        upper = min(max_j, n - i - 1)  # 移除非空
        if upper >= 0:
            ans += upper + 1
    return ans

