class Solution {
    int findMaximumBeauty(int[] arr) {
        int n = arr.length;
        Set<Integer> achievable = new HashSet<>();
        achievable.add(0);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int k = arr[i];
            if (achievable.contains(k - 1) && k <= i + 1) {
