class Solution {
    long countInterestingPairs(int[] arr, int sumVal) {
        if (sumVal % 2 != 0) return 0;
        int M = sumVal / 2;
        long cntLe = 0, cntLt = 0;
        for (int x : arr) {
            int a = Math.abs(x);
            if (a <= M) cntLe++;
            if (a < M) cntLt++;
        }
        return cntLe * (cntLe - 1) / 2 - cntLt * (cntLt - 1) / 2;
    }
}

