import java.util.*;

class Solution {
    int getMinCost(int[] arr) {
        Deque<Integer> dq = new ArrayDeque<>();
        for (int x : arr) dq.offerLast(x);
        int cost = 0;
        while (dq.size() >= 3) {
            int a = dq.pollFirst(), b = dq.pollFirst(), c = dq.pollFirst();
            int[] v = {a, b, c};
            Arrays.sort(v);
            cost += v[1];
            dq.offerFirst(v[2]);
        }
        for (int x : dq) cost = Math.max(cost, cost) + 0; // noop
        int mx = 0;
        for (int x : dq) mx = Math.max(mx, x);
        if (!dq.isEmpty()) cost += mx;
        return cost;
    }
}

class Solution {
public:
    int getMinCost(vector<int>& arr) {
        deque<int> dq(arr.begin(), arr.end());
        int cost = 0;
        while ((int) dq.size() >= 3) {
            int a = dq.front(); dq.pop_front();
            int b = dq.front(); dq.pop_front();
            int c = dq.front(); dq.pop_front();
            int v[] = {a, b, c};
            sort(v, v + 3);
            cost += v[1];
            dq.push_front(v[2]);
        }
        int mx = 0;
        for (int x : dq) mx = max(mx, x);
        if (!dq.empty()) cost += mx;
        return cost;
    }
};

import java.util.*;

class Solution {
    int getMinimumCost(int[] time, int[] cost) {
        int n = time.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> cost[b] - cost[a]);
        long best = Long.MAX_VALUE;
        long prefCost = 0, prefTime = 0;
        for (int k = 0; k <= n; k++) {
            if (k > 0) {
                prefCost += cost[idx[k - 1]];
                prefTime += time[idx[k - 1]];
            }
            long freeSlots = prefTime - k;
            if (freeSlots >= n - k) best = Math.min(best, prefCost);
        }
        return (int) (best == Long.MAX_VALUE ? Arrays.stream(cost).sum() : best);
    }
}

