        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) { return cost[a] > cost[b]; });
        long long best = LLONG_MAX;
        long long prefCost = 0, prefTime = 0;
        for (int k = 0; k <= n; k++) {
            if (k > 0) {
                prefCost += cost[idx[k - 1]];
                prefTime += time[idx[k - 1]];
            }
            long long freeSlots = prefTime - k;
            if (freeSlots >= n - k) best = min(best, prefCost);
        }
        if (best == LLONG_MAX) {
            long long s = 0;
            for (int c : cost) s += c;
            return (int) s;
        }
        return (int) best;
    }
};

from typing import List

def maximumSizeSubarraySum(a: List[int]) -> int:
    n = len(a)
    pl = [-1] * n   # 左边第一个 > a[i]
    pr = [n] * n    # 右边第一个 ≥ a[i]
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] <= a[i]:
            stack.pop()
        pl[i] = stack[-1] if stack else -1
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        pr[i] = stack[-1] if stack else n
        stack.append(i)
    return sum(pr[i] - pl[i] - 1 for i in range(n))

import java.util.*;

class Solution {
    long maximumSizeSubarraySum(int[] a) {
        int n = a.length;
        int[] pl = new int[n], pr = new int[n];
        Arrays.fill(pl, -1);
        Arrays.fill(pr, n);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && a[st.peek()] <= a[i]) st.pop();
            pl[i] = st.isEmpty() ? -1 : st.peek();
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && a[st.peek()] < a[i]) st.pop();
            pr[i] = st.isEmpty() ? n : st.peek();
            st.push(i);
        }
        long ans = 0;
        for (int i = 0; i < n; i++) ans += pr[i] - pl[i] - 1;
        return ans;
    }
}

class Solution {
public:
