        int n = a.size();
        vector<int> pl(n, -1), pr(n, n);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && a[st.top()] <= a[i]) st.pop();
            pl[i] = st.empty() ? -1 : st.top();
            st.push(i);
        }
        while (!st.empty()) st.pop();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && a[st.top()] < a[i]) st.pop();
            pr[i] = st.empty() ? n : st.top();
            st.push(i);
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans += pr[i] - pl[i] - 1;
        return ans;
    }
};

import java.util.*;

class Solution {
    long minAcquireCost(int[] police_station, int capacity) {
        Set<Integer> occupied = new HashSet<>();
        for (int p : police_station) occupied.add(p);
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        for (int p : police_station) {
            pq.offer(new long[]{1, p - 1});
            pq.offer(new long[]{1, p + 1});
        }
        long total = 0;
        int bought = 0;
        while (bought < capacity) {
            long[] cur = pq.poll();
            int pos = (int) cur[1];
            if (occupied.contains(pos)) continue;
            occupied.add(pos);
            total += cur[0];
            bought++;
            pq.offer(new long[]{cur[0] + 1, pos - 1});
            pq.offer(new long[]{cur[0] + 1, pos + 1});
        }
        return total;
    }
}

class Solution {
public:
    long long minAcquireCost(vector<int>& police_station, int capacity) {
        unordered_set<int> occupied(police_station.begin(), police_station.end());
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
        for (int p : police_station) {
            pq.push({1, p - 1});
            pq.push({1, p + 1});
        }
        long long total = 0;
        int bought = 0;
        while (bought < capacity) {
            auto [d, pos] = pq.top(); pq.pop();
            if (occupied.count(pos)) continue;
            occupied.insert(pos);
            total += d;
            bought++;
            pq.push({d + 1, pos - 1});
            pq.push({d + 1, pos + 1});
        }
        return total;
    }
};

class Solution {
    int minOperations(int[] source, int[] target) {
        int n = source.length;
        long pre = 0, total = 0;
        for (int i = 0; i < n; i++) {
            pre += target[i] - source[i];
            total += Math.abs(pre);
        }
        if (pre != 0) return -1;
        return (int) (total / 2);
    }
}

