class Solution {
    int perfectBreak(int[] arr) {
        final int MOD = 1_000_000_007;
        int n = arr.length;
        int V = 0;
        for (int x : arr) V = Math.max(V, x);
        V++;
        long[] dp = new long[V];
        for (int v = 0; v <= arr[0]; v++) dp[v] = 1;
        for (int i = 1; i < n; i++) {
            long[] pref = new long[V + 1];
            for (int v = 0; v < V; v++) pref[v + 1] = (pref[v] + dp[v]) % MOD;
            long[] nd = new long[V];
            int gap = Math.max(0, arr[i] - arr[i - 1]);
            for (int v = 0; v <= arr[i]; v++) {
                int upper = Math.min(v - gap, arr[i - 1]);
                if (upper < 0) continue;
                nd[v] = pref[upper + 1];
            }
            dp = nd;
        }
        long sum = 0;
        for (long x : dp) sum = (sum + x) % MOD;
        return (int) sum;
    }
}

