                nd[v] = pref[upper + 1];
            }
            dp = nd;
        }
        long long sum = 0;
        for (long long x : dp) sum = (sum + x) % MOD;
        return (int) sum;
    }
};

import sys
from typing import List

def treePoints(g_nodes: int, g_from: List[int], g_to: List[int], A: List[int], K: int) -> int:
    sys.setrecursionlimit(200000)
    adj = [[] for _ in range(g_nodes)]
    for u, v in zip(g_from, g_to):
        adj[u].append(v)
        adj[v].append(u)

    def dfs(u: int, parent: int, shift: int) -> int:
        cur_val = A[u] >> shift
        # 方式 1：cur_val - K
        s1 = cur_val - K
        for v in adj[u]:
            if v != parent:
                s1 += dfs(v, u, shift)
        # 方式 2：⌊cur_val/2⌋，子树 shift + 1
        s2 = cur_val >> 1
        for v in adj[u]:
            if v != parent:
                s2 += dfs(v, u, shift + 1)
        return max(s1, s2)
    return dfs(0, -1, 0)

import java.util.*;

class Solution {
    List<List<Integer>> adj;
    int[] A;
    int K;
    long treePoints(int g_nodes, int[] g_from, int[] g_to, int[] A, int K) {
        this.A = A;
        this.K = K;
        adj = new ArrayList<>();
        for (int i = 0; i < g_nodes; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < g_from.length; i++) {
            adj.get(g_from[i]).add(g_to[i]);
            adj.get(g_to[i]).add(g_from[i]);
        }
        return dfs(0, -1, 0);
    }
    long dfs(int u, int parent, int shift) {
        long cur = A[u] >> shift;
        long s1 = cur - K;
        for (int v : adj.get(u)) if (v != parent) s1 += dfs(v, u, shift);
        long s2 = cur >> 1;
        for (int v : adj.get(u)) if (v != parent) s2 += dfs(v, u, shift + 1);
        return Math.max(s1, s2);
    }
}

