        long long s1 = cur - K;
        for (int v : adj[u]) if (v != parent) s1 += dfs(v, u, shift);
        long long s2 = cur >> 1;
        for (int v : adj[u]) if (v != parent) s2 += dfs(v, u, shift + 1);
