def solve(n, edges, values, k):
    from collections import defaultdict
    g = defaultdict(list)
    for u, v in edges: g[u].append(v); g[v].append(u)
    best = float('-inf')
    for u in range(n):
        nb = sorted((values[v] for v in g[u] if values[v] > 0), reverse=True)[:k]
        best = max(best, values[u] + sum(nb))
    return best

class Solution {
    public int solve(int n, int[][] edges, int[] values, int k) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int best = Integer.MIN_VALUE;
        for (int u = 0; u < n; u++) {
            List<Integer> nb = new ArrayList<>();
            for (int v : g.get(u)) if (values[v] > 0) nb.add(values[v]);
            nb.sort(Comparator.reverseOrder());
            int s = values[u];
            for (int i = 0; i < Math.min(nb.size(), k); i++) s += nb.get(i);
            best = Math.max(best, s);
        }
        return best;
    }
}

