class DisplayBook:
    def __init__(self, lot_size, mm_bid, mm_bid_qty, mm_ask, mm_ask_qty):
        self.lot = lot_size
        self.mm = (mm_bid, mm_bid_qty, mm_ask, mm_ask_qty)
        self.bids = SortedDict(); self.asks = SortedDict()
        self.orders = {}
    def _displayable(self, side, price, qty):
        mb, mbq, ma, maq = self.mm
        if qty % self.lot != 0: return False
        if side == 'bid':
            if price > mb: return True
            if price == mb and qty > maq * 0.05: return True
        else:
            if price < ma: return True
            if price == ma and qty > maq * 0.05: return True
        return False
    def add(self, oid, ts, is_bid, price, qty):
        self.orders[oid] = (ts, is_bid, price, qty)
        book = self.bids if is_bid else self.asks
        book[price] = book.get(price, 0) + qty
        return self.best()
    def cancel(self, oid, ts):
        ts0, is_bid, price, qty = self.orders.pop(oid)
        book = self.bids if is_bid else self.asks
        book[price] -= qty
        if book[price] == 0: del book[price]
        return self.best()
    def best(self):
        mb, mbq, ma, maq = self.mm
        best_bid = max((p for p in self.bids if self._displayable('bid', p, self.bids[p])), default=mb)
        best_ask = min((p for p in self.asks if self._displayable('ask', p, self.asks[p])), default=ma)
        return (max(best_bid, mb), min(best_ask, ma))

class DisplayBook {
    int lot;
    double mmBid, mmAsk;
    long mmBidQty, mmAskQty;
    TreeMap<Double, Long> bids = new TreeMap<>(), asks = new TreeMap<>();
    Map<Integer, double[]> orders = new HashMap<>();

    DisplayBook(int lot, double mb, long mbq, double ma, long maq) {
        this.lot = lot; this.mmBid = mb; this.mmBidQty = mbq; this.mmAsk = ma; this.mmAskQty = maq;
    }
    private boolean displayable(boolean isBid, double price, long qty) {
        if (qty % lot != 0) return false;
        long ref = isBid ? mmAskQty : mmAskQty;
        if (isBid) {
            if (price > mmBid) return true;
            return price == mmBid && qty > ref * 0.05;
        } else {
            if (price < mmAsk) return true;
            return price == mmAsk && qty > ref * 0.05;
        }
    }
    double[] add(int oid, long ts, boolean isBid, double price, long qty) {
        orders.put(oid, new double[]{isBid ? 1 : 0, price, qty});
        TreeMap<Double, Long> book = isBid ? bids : asks;
        book.merge(price, qty, Long::sum);
        return best();
    }
    double[] cancel(int oid, long ts) {
        double[] o = orders.remove(oid);
        boolean isBid = o[0] == 1; double price = o[1]; long qty = (long) o[2];
        TreeMap<Double, Long> book = isBid ? bids : asks;
        long v = book.get(price) - qty;
        if (v == 0) book.remove(price); else book.put(price, v);
        return best();
    }
    double[] best() {
        double bb = mmBid, ba = mmAsk;
        for (var e : bids.descendingMap().entrySet())
            if (displayable(true, e.getKey(), e.getValue())) { bb = Math.max(bb, e.getKey()); break; }
        for (var e : asks.entrySet())
            if (displayable(false, e.getKey(), e.getValue())) { ba = Math.min(ba, e.getKey()); break; }
        return new double[]{bb, ba};
    }
}

struct DisplayBook {
 int lot;
