 unordered_map<int, tuple<bool, double, long long>> orders;

 DisplayBook(int l, double mb, long long mbq, double ma, long long maq)
 : lot(l), mmBid(mb), mmAsk(ma), mmBidQty(mbq), mmAskQty(maq) {}

 bool displayable(bool isBid, double price, long long qty) {
 if (qty % lot != 0) return false;
 long long ref = mmAskQty;
 if (isBid) {
 if (price > mmBid) return true;
 return price == mmBid && qty > ref * 0.05;
 }
 if (price < mmAsk) return true;
 return price == mmAsk && qty > ref * 0.05;
 }
 pair<double, double> add(int oid, long ts, bool isBid, double price, long long qty) {
 orders[oid] = {isBid, price, qty};
 auto& book = isBid ? bids : asks;
 book[price] += qty;
 return best();
 }
 pair<double, double> cancel(int oid, long ts) {
 auto [isBid, price, qty] = orders[oid];
