from collections import deque

def solve(logs, window, budget):
    dq = deque(); total = 0; out = []
    for i, (bytes_, ts) in enumerate(logs):
        while dq and dq[0][0] + window <= ts:
            total -= dq.popleft()[1]
        if total + bytes_ <= budget:
            total += bytes_; dq.append((ts, bytes_)); out.append(i)
    return out

class Solution {
    public List<Integer> solve(int[][] logs, int window, int budget) {
        Deque<long[]> dq = new ArrayDeque<>();
        long sum = 0;
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < logs.length; i++) {
            long ts = logs[i][1], bytes = logs[i][0];
            while (!dq.isEmpty() && dq.peekFirst()[0] + window <= ts) sum -= dq.pollFirst()[1];
            if (sum + bytes <= budget) { sum += bytes; dq.addLast(new long[]{ts, bytes}); out.add(i); }
        }
        return out;
    }
}

