 for (int i = 0; i < (int)logs.size(); ++i) {
 unsigned long ts = logs[i].timestamp;
 unsigned int bytes = logs[i].size;
 while (!dq.empty() && dq.front().first + window <= ts) { sum -= dq.front().second; dq.pop_front(); }
 if (sum + bytes <= budget) { sum += bytes; dq.push_back({ts, bytes}); out.push_back(i); }
 }
 return out;
}

