def delivery_management(city_nodes: int, city_from: List[int], city_to: List[int], company: int) -> List[int]:
    g = defaultdict(list)
    for u, v in zip(city_from, city_to):
        g[u].append(v); g[v].append(u)
    dist = {company: 0}
    q = deque([company])
    while q:
        u = q.popleft()
        for v in g[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return [c for d, c in sorted((d, c) for c, d in dist.items() if c != company)]

import java.util.*;

class Solution {
    public int[] deliveryManagement(int cityNodes, int[] cityFrom, int[] cityTo, int company) {
        Map<Integer, List<Integer>> g = new HashMap<>();
        for (int i = 0; i < cityFrom.length; i++) {
            g.computeIfAbsent(cityFrom[i], k -> new ArrayList<>()).add(cityTo[i]);
            g.computeIfAbsent(cityTo[i], k -> new ArrayList<>()).add(cityFrom[i]);
        }
        Map<Integer, Integer> dist = new HashMap<>();
        dist.put(company, 0);
        Deque<Integer> q = new ArrayDeque<>(); q.add(company);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.getOrDefault(u, Collections.emptyList())) {
                if (!dist.containsKey(v)) { dist.put(v, dist.get(u) + 1); q.add(v); }
            }
        }
        List<int[]> pairs = new ArrayList<>();
        for (var e : dist.entrySet()) if (e.getKey() != company) pairs.add(new int[]{e.getValue(), e.getKey()});
        pairs.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int[] out = new int[pairs.size()];
        for (int i = 0; i < pairs.size(); i++) out[i] = pairs.get(i)[1];
        return out;
    }
}

