class Solution {
    public int differenceCalculator(int n, int[] arr) {
        int ind1 = 0;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && arr[j] == arr[i]) j++;
            if (j - i == arr[i]) ind1++;
            i = j;
        }
        int ind2 = 0;
        for (int k = 1; k <= n; k++) {
            int v = arr[k - 1];
            if (v != k) continue;
            if (k - 1 + v > n) continue;
            boolean ok = true;
            for (int t = 0; t < v; t++) if (arr[k - 1 + t] != v) { ok = false; break; }
            if (ok) ind2++;
        }
        return Math.abs(ind1 - ind2);
    }
}

