import bisect

def find_nearest_cities(num_of_cities: int, cities: List[str], x_coords: List[int], y_coords: List[int],
                       num_of_queries: int, queries: List[str]) -> List[str]:
    pos = {cities[i]: (x_coords[i], y_coords[i]) for i in range(num_of_cities)}
    by_x = defaultdict(list)  # x -> sorted [(y, name)]
    by_y = defaultdict(list)  # y -> sorted [(x, name)]
    for i in range(num_of_cities):
        x, y, name = x_coords[i], y_coords[i], cities[i]
        by_x[x].append((y, name))
        by_y[y].append((x, name))
    for v in by_x.values(): v.sort()
    for v in by_y.values(): v.sort()

    out: List[str] = []
    for q in queries:
        x, y = pos[q]
        best_name = None; best_dist = float('inf')
        # in same x
        col = by_x[x]
        i = bisect.bisect_left(col, (y, q))
        for j in (i - 1, i + 1, i):
            if 0 <= j < len(col) and col[j][1] != q:
                d = abs(col[j][0] - y)
                if d < best_dist or (d == best_dist and (best_name is None or col[j][1] < best_name)):
                    best_dist = d; best_name = col[j][1]
        # in same y
        row = by_y[y]
        i = bisect.bisect_left(row, (x, q))
        for j in (i - 1, i + 1, i):
            if 0 <= j < len(row) and row[j][1] != q:
                d = abs(row[j][0] - x)
                if d < best_dist or (d == best_dist and (best_name is None or row[j][1] < best_name)):
                    best_dist = d; best_name = row[j][1]
        out.append(best_name if best_name else "NONE")
    return out

import java.util.*;

class Solution {
    public String[] findNearestCities(int numOfCities, String[] cities, int[] x, int[] y,
                                      int numOfQueries, String[] queries) {
        Map<String, int[]> pos = new HashMap<>();
        Map<Integer, TreeMap<Integer, String>> byX = new HashMap<>(), byY = new HashMap<>();
        for (int i = 0; i < numOfCities; i++) {
            pos.put(cities[i], new int[]{x[i], y[i]});
            byX.computeIfAbsent(x[i], k -> new TreeMap<>()).put(y[i], cities[i]);
            byY.computeIfAbsent(y[i], k -> new TreeMap<>()).put(x[i], cities[i]);
        }
        String[] out = new String[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int[] p = pos.get(queries[q]);
            String bestName = null; long bestDist = Long.MAX_VALUE;
            var col = byX.get(p[0]);
            if (col != null) {
                var lower = col.lowerEntry(p[1]); var higher = col.higherEntry(p[1]);
                if (lower != null) { long d = p[1] - lower.getKey(); if (d < bestDist) { bestDist = d; bestName = lower.getValue(); } }
                if (higher != null) { long d = higher.getKey() - p[1]; if (d < bestDist || (d == bestDist && (bestName == null || higher.getValue().compareTo(bestName) < 0))) { bestDist = d; bestName = higher.getValue(); } }
            }
            var row = byY.get(p[1]);
            if (row != null) {
                var lower = row.lowerEntry(p[0]); var higher = row.higherEntry(p[0]);
                if (lower != null) { long d = p[0] - lower.getKey(); if (d < bestDist || (d == bestDist && (bestName == null || lower.getValue().compareTo(bestName) < 0))) { bestDist = d; bestName = lower.getValue(); } }
                if (higher != null) { long d = higher.getKey() - p[0]; if (d < bestDist || (d == bestDist && (bestName == null || higher.getValue().compareTo(bestName) < 0))) { bestDist = d; bestName = higher.getValue(); } }
            }
            out[q] = bestName != null ? bestName : "NONE";
        }
        return out;
    }
}

