class Solution {
public:
    vector<string> findNearestCities(int n, vector<string>& cities, vector<int>& x, vector<int>& y,
                                     int numOfQueries, vector<string>& queries) {
        unordered_map<string, pair<int, int>> pos;
        map<int, map<int, string>> byX, byY;
        for (int i = 0; i < n; i++) {
            pos[cities[i]] = {x[i], y[i]};
            byX[x[i]][y[i]] = cities[i];
            byY[y[i]][x[i]] = cities[i];
        }
        vector<string> out;
        for (auto& q : queries) {
            auto [px, py] = pos[q];
            string bestName; long long bestDist = LLONG_MAX;
            auto checkAndUpdate = [&](long long d, const string& name) {
                if (d < bestDist || (d == bestDist && (bestName.empty() || name < bestName))) { bestDist = d; bestName = name; }
            };
            if (byX.count(px)) {
                auto& col = byX[px];
                auto it = col.lower_bound(py);
                if (it != col.begin()) { auto p = prev(it); checkAndUpdate(py - p->first, p->second); }
                if (it != col.end() && it->first != py) checkAndUpdate(it->first - py, it->second);
                if (it != col.end() && it->first == py && next(it) != col.end()) checkAndUpdate(next(it)->first - py, next(it)->second);
            }
            if (byY.count(py)) {
                auto& row = byY[py];
                auto it = row.lower_bound(px);
                if (it != row.begin()) { auto p = prev(it); checkAndUpdate(px - p->first, p->second); }
                if (it != row.end() && it->first != px) checkAndUpdate(it->first - px, it->second);
                if (it != row.end() && it->first == px && next(it) != row.end()) checkAndUpdate(next(it)->first - px, next(it)->second);
            }
            out.push_back(bestName.empty() ? "NONE" : bestName);
        }
        return out;
    }
};

from functools import lru_cache
from typing import List

def get_probability(scores: List[List[int]], prob: List[List[int]], n: int, x: int) -> float:
    # scores[i], prob[i] in percent for mix i
    mixes = []
    for i in range(len(scores)):
        # convert to (score, p) including p_fail = 1 - sum
        psum = sum(prob[i]) / 100.0
        m = [(s, p / 100.0) for s, p in zip(scores[i], prob[i])]
        m.append((0, max(0.0, 1 - psum)))  # failure
        mixes.append(m)

    @lru_cache(maxsize=None)
    def f(k, s):
        if s == 0: return 1.0
        if s < 0 or k == 0: return 0.0
        best = 0.0
        for mix in mixes:
            ev = 0.0
            for sc, p in mix:
                ev += p * f(k - 1, s - sc)
            if ev > best: best = ev
        return best

    return round(f(n, x), 3)

import java.util.*;

class Solution {
    double[][] memo;
    int n, x;
    List<List<double[]>> mixes;
    public double getProbability(int[][] scores, int[][] prob, int n, int x) {
        this.n = n; this.x = x;
        mixes = new ArrayList<>();
        for (int i = 0; i < scores.length; i++) {
            List<double[]> m = new ArrayList<>();
            double psum = 0;
            for (int j = 0; j < scores[i].length; j++) { m.add(new double[]{scores[i][j], prob[i][j] / 100.0}); psum += prob[i][j] / 100.0; }
            m.add(new double[]{0, Math.max(0, 1 - psum)});
            mixes.add(m);
        }
        memo = new double[n + 1][x + 1];
        for (double[] row : memo) Arrays.fill(row, -1);
        return Math.round(f(n, x) * 1000) / 1000.0;
    }
    double f(int k, int s) {
        if (s == 0) return 1.0;
        if (s < 0 || k == 0) return 0.0;
        if (memo[k][s] >= 0) return memo[k][s];
        double best = 0;
        for (var mix : mixes) {
            double ev = 0;
            for (double[] sp : mix) ev += sp[1] * f(k - 1, (int) (s - sp[0]));
            best = Math.max(best, ev);
        }
        return memo[k][s] = best;
    }
}

