def get_substring(input_str: str, k: int) -> str:
    n = len(input_str)
    # find positions of '1'
    ones = [i for i, c in enumerate(input_str) if c == '1']
    if len(ones) < k:
        return ""
    best = None
    for i in range(len(ones) - k + 1):
        # window [ones[i]..ones[i+k-1]]
        cand = input_str[ones[i]:ones[i + k - 1] + 1]
        if best is None or len(cand) < len(best) or (len(cand) == len(best) and cand < best):
            best = cand
    return best

import java.util.*;

class Solution {
    public String getSubstring(String s, int k) {
        List<Integer> ones = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) if (s.charAt(i) == '1') ones.add(i);
        if (ones.size() < k) return "";
        String best = null;
        for (int i = 0; i + k - 1 < ones.size(); i++) {
            String c = s.substring(ones.get(i), ones.get(i + k - 1) + 1);
            if (best == null || c.length() < best.length() || (c.length() == best.length() && c.compareTo(best) < 0)) best = c;
        }
        return best;
    }
}

