class Solution {
    public int maxMeetings(int[] effectiveness) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        long cur = 0;
        int cnt = 0;
        for (int e : effectiveness) {
            cur += e; cnt++;
            pq.add((long) e);
            while (cur <= 0 && !pq.isEmpty()) {
                cur -= pq.poll();
                cnt--;
            }
        }
        return cnt;
    }
}

