def maximize_ratings(ratings: List[int]) -> int:
    n = len(ratings)
    if n == 0: return 0
    if n == 1: return ratings[0]
    if n == 2: return max(ratings)
    dp = [0] * n
    dp[0] = ratings[0]
    dp[1] = ratings[1]
    for i in range(2, n):
        dp[i] = ratings[i] + max(dp[i - 1], dp[i - 2])
    return max(dp[n - 1], dp[n - 2])

