        dp[0] = ratings[0]; dp[1] = ratings[1];
        for (int i = 2; i < n; i++) dp[i] = ratings[i] + Math.max(dp[i - 1], dp[i - 2]);
        return Math.max(dp[n - 1], dp[n - 2]);
    }
}

