def minimum_chunks_required(total_packets: int, uploaded_chunks: List[List[int]]) -> int:
    intervals = sorted(uploaded_chunks)
    merged: list = []
    for s, e in intervals:
        if merged and s <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    gaps: list = []
    prev_end = 0
    for s, e in merged:
        if s > prev_end + 1:
            gaps.append((prev_end + 1, s - 1))
        prev_end = max(prev_end, e)
    if prev_end < total_packets:
        gaps.append((prev_end + 1, total_packets))
    chunks = 0
    for a, b in gaps:
        L = b - a + 1
        cur = a
        while cur <= b:
            # max power of 2 dividing cur AND ≤ remaining
            rem = b - cur + 1
            k = 0
            while (1 << (k + 1)) <= rem and cur % (1 << (k + 1)) == 0:
                k += 1
            chunks += 1
            cur += 1 << k
    return chunks

