class Solution {
    public int minimumChunksRequired(long totalPackets, long[][] uploadedChunks) {
        long[][] arr = uploadedChunks.clone();
        Arrays.sort(arr, (a, b) -> Long.compare(a[0], b[0]));
        List<long[]> merged = new ArrayList<>();
        for (long[] iv : arr) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1] + 1) {
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
            } else merged.add(new long[]{iv[0], iv[1]});
        }
        List<long[]> gaps = new ArrayList<>();
        long prevEnd = 0;
        for (long[] iv : merged) {
            if (iv[0] > prevEnd + 1) gaps.add(new long[]{prevEnd + 1, iv[0] - 1});
            prevEnd = Math.max(prevEnd, iv[1]);
        }
        if (prevEnd < totalPackets) gaps.add(new long[]{prevEnd + 1, totalPackets});
        int chunks = 0;
        for (long[] g : gaps) {
            long cur = g[0];
            while (cur <= g[1]) {
                long rem = g[1] - cur + 1;
                int k = 0;
                while ((1L << (k + 1)) <= rem && cur % (1L << (k + 1)) == 0) k++;
                chunks++;
                cur += 1L << k;
            }
        }
        return chunks;
    }
}

