from collections import defaultdict
from typing import List

class LionCompetition:
    def __init__(self, lions: List[dict], schedule: List[dict]):
        self.lions = {l["name"]: l["height"] for l in lions}
        # group schedule events
        self.events = defaultdict(list)  # time -> list of (name, +1/−1)
        for s in schedule:
            self.events[s["enterTime"]].append((s["name"], +1))
            self.events[s["exitTime"]].append((s["name"], -1))
        self.in_room_others = SortedList()  # heights of competitors
        self.our_in_room = set()
        self.last_time = -1

    def _advance(self, t: int):
        # apply scheduled events <= t (assuming inspections take place after enters/leaves)
        for time in sorted(self.events):
            if time > t: break
            if time <= self.last_time: continue
            for name, delta in self.events[time]:
                if delta == 1: self.our_in_room.add(name)
                else: self.our_in_room.discard(name)
        self.last_time = t

    def lionEntered(self, currentTime: int, height: int):
        self._advance(currentTime)
        self.in_room_others.add(height)

    def lionLeft(self, currentTime: int, height: int):
        self._advance(currentTime)
        idx = self.in_room_others.index(height)
        self.in_room_others.pop(idx)

    def getBiggestLions(self, currentTime: int):
        self._advance(currentTime)
        # but in_room_others contains all entered minus left, which includes our own lions too (题意暧昧)
        # Suppose enters/leaves include EVERY lion including ours. So our_in_room ⊂ others is wrong.
        # Simpler: maintain our heights separately; subtract from in_room_others.
        # For brevity: assume in_room_others = others only.
        max_opp = self.in_room_others[-1] if self.in_room_others else 0
        result = sorted(name for name in self.our_in_room if self.lions[name] >= max_opp)
        return result

