class Solution {
    int[] matchCol; List<List<Integer>> adj;
    boolean tryKuhn(int u, boolean[] vis) {
        for (int v : adj.get(u)) {
            if (vis[v]) continue;
            vis[v] = true;
            if (matchCol[v] == -1 || tryKuhn(matchCol[v], vis)) { matchCol[v] = u; return true; }
        }
        return false;
    }
