def server_clusters(serverProp):
    n = len(serverProp)
    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        a, b = find(a), find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    prime_first = {}
    for i, v in enumerate(serverProp):
        x = v
        p = 2
        while p * p <= x:
            if x % p == 0:
                if p in prime_first:
                    union(i, prime_first[p])
                else:
                    prime_first[p] = i
                while x % p == 0:
                    x //= p
            p += 1
        if x > 1:
            if x in prime_first:
                union(i, prime_first[x])
            else:
                prime_first[x] = i
    return [size[find(i)] for i in range(n)]

import java.util.*;

class Solution {
    int[] parent, size;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void union_(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) { int t = a; a = b; b = t; }
        parent[b] = a;
        size[a] += size[b];
    }

    int[] serverClusters(int[] serverProp) {
        int n = serverProp.length;
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        Map<Integer, Integer> primeFirst = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int x = serverProp[i];
            for (int p = 2; (long) p * p <= x; p++) {
                if (x % p == 0) {
                    if (primeFirst.containsKey(p)) union_(i, primeFirst.get(p));
                    else primeFirst.put(p, i);
                    while (x % p == 0) x /= p;
                }
            }
            if (x > 1) {
                if (primeFirst.containsKey(x)) union_(i, primeFirst.get(x));
                else primeFirst.put(x, i);
            }
        }
        int[] out = new int[n];
        for (int i = 0; i < n; i++) out[i] = size[find(i)];
        return out;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
    vector<int> parent, sz;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }

public:
    vector<int> serverClusters(vector<int>& serverProp) {
        int n = serverProp.size();
        parent.resize(n); sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
        unordered_map<int, int> primeFirst;
        for (int i = 0; i < n; i++) {
            int x = serverProp[i];
            for (int p = 2; (long long) p * p <= x; p++) {
                if (x % p == 0) {
                    auto it = primeFirst.find(p);
                    if (it != primeFirst.end()) unite(i, it->second);
                    else primeFirst[p] = i;
                    while (x % p == 0) x /= p;
                }
            }
            if (x > 1) {
                auto it = primeFirst.find(x);
                if (it != primeFirst.end()) unite(i, it->second);
                else primeFirst[x] = i;
            }
        }
        vector<int> out(n);
        for (int i = 0; i < n; i++) out[i] = sz[find(i)];
        return out;
    }
};

