from typing import List

def get_min_time(cache_size: int, cache_time: int, server_time: int, urls: List[str]) -> List[int]:
    cache = OrderedDict()
    res = []
    for url in urls:
        if url in cache:
            cache.move_to_end(url)
            res.append(cache_time)
        else:
            cache[url] = True
            if len(cache) > cache_size:
                cache.popitem(last=False)
            res.append(server_time)
    return res

import java.util.*;

class Solution {
    int[] getMinTime(int cacheSize, int cacheTime, int serverTime, String[] urls) {
        LinkedHashMap<String, Boolean> cache = new LinkedHashMap<>(16, 0.75f, true);
        int[] res = new int[urls.length];
        for (int i = 0; i < urls.length; i++) {
            String u = urls[i];
            if (cache.containsKey(u)) {
                cache.get(u);
                res[i] = cacheTime;
            } else {
                cache.put(u, true);
                if (cache.size() > cacheSize) {
                    Iterator<String> it = cache.keySet().iterator();
                    it.next();
                    it.remove();
                }
                res[i] = serverTime;
            }
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getMinTime(int cacheSize, int cacheTime, int serverTime, vector<string>& urls) {
        list<string> order;
        unordered_map<string, list<string>::iterator> pos;
        vector<int> res;
        res.reserve(urls.size());
        for (auto& u : urls) {
            auto it = pos.find(u);
            if (it != pos.end()) {
                order.erase(it->second);
                order.push_back(u);
                pos[u] = prev(order.end());
                res.push_back(cacheTime);
            } else {
                order.push_back(u);
                pos[u] = prev(order.end());
                if ((int) order.size() > cacheSize) {
                    pos.erase(order.front());
                    order.pop_front();
                }
                res.push_back(serverTime);
            }
        }
        return res;
    }
};

class Solution {
    int countOperations(int[] p) {
        final int MOD = 1_000_000_007;
        int n = p.length;
        boolean[] seen = new boolean[n];
        long ans = 1;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            int j = i, length = 0;
            while (!seen[j]) { seen[j] = true; j = p[j] - 1; length++; }
            ans = ans / gcd(ans, length) * length % MOD;
        }
        return (int) ans;
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

