        string st;
        for (char c : s) {
            if (c == '#') { if (!st.empty()) st.pop_back(); }
            else st += c;
        }
        return st;
    }
    int compareStrings(string s1, string s2) {
        return proc(s1) == proc(s2) ? 1 : 0;
    }
};

from collections import OrderedDict

def computeParameterValue(sources):
    od = OrderedDict()
    for src in sources:
        for item in src:
            k, v = item.split(":")
            if k not in od:
                od[k] = v
            else:
                od[k] = v  # 后到覆盖
    return list(od.values())

class Solution {
    String[] computeParameterValue(String[][] sources) {
        java.util.LinkedHashMap<String, String> od = new java.util.LinkedHashMap<>();
        for (String[] src : sources) {
            for (String item : src) {
                String[] kv = item.split(":");
                od.put(kv[0], kv[1]);
            }
        }
        return od.values().toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> computeParameterValue(vector<vector<string>>& sources) {
        vector<pair<string, string>> order;
        unordered_map<string, int> idx;
        for (auto& src : sources) {
            for (auto& item : src) {
                int p = item.find(':');
                string k = item.substr(0, p), v = item.substr(p + 1);
                auto it = idx.find(k);
                if (it == idx.end()) {
                    idx[k] = order.size();
                    order.push_back({k, v});
                } else order[it->second].second = v;
            }
        }
        vector<string> res;
        for (auto& p : order) res.push_back(p.second);
        return res;
    }
};

def countPalindromes(s):
    n = len(s)
    cnt = 0
    for c in range(n):
        for L, R in [(c, c), (c, c + 1)]:
            while L >= 0 and R < n and s[L] == s[R]:
                cnt += 1
                L -= 1; R += 1
    return cnt

class Solution {
    int countPalindromes(String s) {
        int n = s.length(), cnt = 0;
        for (int c = 0; c < n; c++) {
            int[][] starts = {{c, c}, {c, c + 1}};
            for (int[] LR : starts) {
                int L = LR[0], R = LR[1];
                while (L >= 0 && R < n && s.charAt(L) == s.charAt(R)) {
                    cnt++; L--; R++;
                }
            }
        }
        return cnt;
    }
}

class Solution {
public:
    int countPalindromes(string s) {
        int n = s.size(), cnt = 0;
        for (int c = 0; c < n; c++) {
            for (auto [L, R] : vector<pair<int,int>>{{c, c}, {c, c + 1}}) {
                while (L >= 0 && R < n && s[L] == s[R]) { cnt++; L--; R++; }
            }
        }
        return cnt;
    }
};

class Solution {
    int maxProfit(int costPerCut, int salePrice, int[] lengths) {
        int M = 0;
        for (int x : lengths) M = Math.max(M, x);
        long best = 0;
        for (int L = 1; L <= M; L++) {
            long rods = 0, cuts = 0;
            for (int ln : lengths) {
                int r = ln / L;
                if (r == 0) continue;
                rods += r;
                if (ln % L == 0) cuts += r - 1;
                else cuts += r;
            }
            long profit = rods * L * salePrice - cuts * costPerCut;
            best = Math.max(best, profit);
        }
        return (int) best;
    }
}

