        int M = *max_element(lengths.begin(), lengths.end());
        long long best = 0;
        for (int L = 1; L <= M; L++) {
            long long rods = 0, cuts = 0;
            for (int ln : lengths) {
                int r = ln / L;
                if (r == 0) continue;
                rods += r;
                if (ln % L == 0) cuts += r - 1;
                else cuts += r;
            }
            long long profit = rods * L * salePrice - cuts * costPerCut;
            best = max(best, profit);
        }
        return (int) best;
    }
};

def decode(encode):
    s = encode[::-1]
    out = []
    i = 0
    while i < len(s):
        # 优先尝试 2 位
        if i + 2 <= len(s):
            v = int(s[i:i+2])
            if v == 32 or (65 <= v <= 90):
                out.append(chr(v)); i += 2; continue
        if i + 3 <= len(s):
            v = int(s[i:i+3])
            if 97 <= v <= 122:
                out.append(chr(v)); i += 3; continue
        # fallback
        i += 1
    return "".join(out)

class Solution {
    String decode(String encode) {
        String s = new StringBuilder(encode).reverse().toString();
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (i + 2 <= s.length()) {
                int v = Integer.parseInt(s.substring(i, i + 2));
                if (v == 32 || (v >= 65 && v <= 90)) { out.append((char) v); i += 2; continue; }
            }
            if (i + 3 <= s.length()) {
                int v = Integer.parseInt(s.substring(i, i + 3));
                if (v >= 97 && v <= 122) { out.append((char) v); i += 3; continue; }
            }
            i++;
        }
        return out.toString();
    }
}

class Solution {
public:
    string decode(string encode) {
        string s = encode;
        reverse(s.begin(), s.end());
        string out;
        int i = 0;
        while (i < (int)s.size()) {
            if (i + 2 <= (int)s.size()) {
                int v = stoi(s.substr(i, 2));
                if (v == 32 || (v >= 65 && v <= 90)) { out += (char) v; i += 2; continue; }
            }
            if (i + 3 <= (int)s.size()) {
                int v = stoi(s.substr(i, 3));
                if (v >= 97 && v <= 122) { out += (char) v; i += 3; continue; }
