def encryptionValidity(instructionCount, validityPeriod, keys):
    best_deg = 0
    n = len(keys)
    for m in keys:
        deg = 0
        for k in keys:
            if k > 1 and m % k == 0:
                deg += 1
        best_deg = max(best_deg, deg)
    strength = best_deg * 100000
    capable = instructionCount * validityPeriod
    cracked = 1 if capable >= strength else 0
    return [cracked, strength]

class Solution {
    int[] encryptionValidity(long instructionCount, long validityPeriod, int[] keys) {
        int bestDeg = 0;
        for (int m : keys) {
            int deg = 0;
            for (int k : keys) if (k > 1 && m % k == 0) deg++;
            bestDeg = Math.max(bestDeg, deg);
        }
        long strength = (long) bestDeg * 100000L;
        long capable = instructionCount * validityPeriod;
        return new int[]{capable >= strength ? 1 : 0, (int) strength};
    }
}

