def alphanumericCombinations(S):
    n = len(S)
    if n == 0: return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if S[i-1] != '0':
            dp[i] += dp[i-1]
        if i >= 2:
            two = int(S[i-2:i])
            if 10 <= two <= 26:
                dp[i] += dp[i-2]
    return dp[n]

