class Solution {
    int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    int decryptCodeLock(int[] codeSequence, int maxValue) {
        int n = codeSequence.length;
        long best = Long.MIN_VALUE;
        for (int j = 0; j < n; j++) {
            boolean ok = true;
            for (int k = 0; k < n; k++) if (k != j && gcd(codeSequence[j], codeSequence[k]) != 1) { ok = false; break; }
            if (ok) best = Math.max(best, codeSequence[j]);
            for (int v = maxValue; v >= 1; v--) {
                boolean okv = true;
                for (int k = 0; k < n; k++) if (k != j && gcd(v, codeSequence[k]) != 1) { okv = false; break; }
                if (okv) {
                    int cost = (v == codeSequence[j]) ? 0 : 1;
                    best = Math.max(best, (long)v - cost);
                    break;
                }
            }
        }
        return (int) best;
    }
}

