def encodeOrDecode(operation, message, key):
    digits = str(key)
    if operation == 1:
        out = []
        for i, c in enumerate(message):
            out.append(c * int(digits[i % len(digits)]))
        return "".join(out)
    else:
        out = []
        i = 0
        idx = 0
        while i < len(message):
            d = int(digits[idx % len(digits)])
            if d == 0: return "-1"
            for k in range(d):
                if i + k >= len(message) or message[i + k] != message[i]:
                    return "-1"
            out.append(message[i])
            i += d
            idx += 1
        return "".join(out)

class Solution {
