        String digits = String.valueOf(key);
        if (operation == 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < message.length(); i++) {
                int d = digits.charAt(i % digits.length()) - '0';
                for (int k = 0; k < d; k++) sb.append(message.charAt(i));
            }
            return sb.toString();
        } else {
            StringBuilder sb = new StringBuilder();
            int i = 0, idx = 0;
            while (i < message.length()) {
                int d = digits.charAt(idx % digits.length()) - '0';
                if (d == 0) return "-1";
                for (int k = 0; k < d; k++) {
                    if (i + k >= message.length() || message.charAt(i + k) != message.charAt(i)) return "-1";
                }
                sb.append(message.charAt(i));
                i += d; idx++;
            }
            return sb.toString();
        }
    }
}

