class Solution {
    long findNiceness(int[] ramu, int[] sonu) {
        int n = ramu.length;
        int[] pat = new int[n - 1];
        for (int i = 0; i < n - 1; i++) pat[i] = ramu[i + 1] > ramu[i] ? 1 : -1;
        int[] role = new int[n];
        for (int i = 0; i < n; i++) {
            Integer L = i > 0 ? pat[i - 1] : null;
            Integer R = i < n - 1 ? pat[i] : null;
            if (L != null && L == 1 && R != null && R == -1) role[i] = 1;
            else if (L != null && L == -1 && R != null && R == 1) role[i] = -1;
            else if (L != null && L == 1) role[i] = 1;
            else if (L != null && L == -1) role[i] = -1;
            else if (R != null && R == -1) role[i] = 1;
            else if (R != null && R == 1) role[i] = -1;
        }
        int[] a = sonu.clone();
        java.util.Arrays.sort(a);
        int[] arr = new int[n];
        java.util.List<Integer> peaks = new java.util.ArrayList<>(), valleys = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (role[i] == 1) peaks.add(i);
            else if (role[i] == -1) valleys.add(i);
        }
        for (int i = 0; i < valleys.size(); i++) arr[valleys.get(i)] = a[i];
        for (int i = 0; i < peaks.size(); i++) arr[peaks.get(i)] = a[a.length - 1 - i];
        long total = 0;
        for (int i = 0; i < n - 1; i++) total += Math.abs(arr[i + 1] - arr[i]);
        return total;
    }
}

