from collections import deque

def getMinimumMoves(maze, k):
    n = len(maze)
    m = len(maze[0]) if n > 0 else 0
    if maze[0][0] == 1 or maze[n-1][m-1] == 1: return -1
    dist = [[-1] * m for _ in range(n)]
    dist[0][0] = 0
    q = deque([(0, 0)])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        i, j = q.popleft()
        if i == n - 1 and j == m - 1: return dist[i][j]
        for dr, dc in dirs:
            for step in range(1, k + 1):
                ni, nj = i + dr * step, j + dc * step
                if 0 <= ni < n and 0 <= nj < m and maze[ni][nj] == 0:
                    if dist[ni][nj] == -1:
                        dist[ni][nj] = dist[i][j] + 1
                        q.append((ni, nj))
                else:
                    break
    return -1

class Solution {
    int getMinimumMoves(int[][] maze, int k) {
        int n = maze.length, m = n > 0 ? maze[0].length : 0;
        if (maze[0][0] == 1 || maze[n-1][m-1] == 1) return -1;
        int[][] dist = new int[n][m];
        for (int[] row : dist) java.util.Arrays.fill(row, -1);
        dist[0][0] = 0;
        java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
        q.add(new int[]{0, 0});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] x = q.poll();
            if (x[0] == n - 1 && x[1] == m - 1) return dist[n-1][m-1];
            for (int[] d : dirs) {
                for (int step = 1; step <= k; step++) {
                    int ni = x[0] + d[0] * step, nj = x[1] + d[1] * step;
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m || maze[ni][nj] == 1) break;
                    if (dist[ni][nj] == -1) {
                        dist[ni][nj] = dist[x[0]][x[1]] + 1;
                        q.add(new int[]{ni, nj});
                    }
                }
            }
        }
        return -1;
    }
}

