class Solution {
    long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    long getMinimumValue(int[] data, long maxOperations) {
        java.util.TreeMap<Long, Integer> ms = new java.util.TreeMap<>();
        for (int x : data) ms.merge((long) x, 1, Integer::sum);
        long g = data[0];
        for (int x : data) g = gcd(g, x);
        for (long op = 0; op < maxOperations; op++) {
            if (ms.size() < 2 && ms.firstEntry().getValue() < 2) break;
            long a = ms.firstKey();
            // 拿第二小
            if (ms.get(a) >= 2) {
                long diff = 0;
                ms.merge(diff, 1, Integer::sum);
                if (ms.firstKey() == 0) break;
            } else {
                long b = ms.higherKey(a);
                long diff = b - a;
                ms.merge(diff, 1, Integer::sum);
            }
            if (ms.firstKey() == g) break;
        }
        return ms.firstKey();
    }
}

class Solution {
public:
    long long gcd(long long a, long long b) { return b == 0 ? a : gcd(b, a % b); }
    long long getMinimumValue(vector<int>& data, long long maxOperations) {
        multiset<long long> ms(data.begin(), data.end());
        long long g = data[0];
        for (int x : data) g = gcd(g, (long long) x);
        for (long long op = 0; op < maxOperations; op++) {
            if (ms.size() < 2) break;
            auto it = ms.begin();
            long long a = *it; ++it;
            long long b = *it;
            long long diff = b - a;
            ms.insert(diff);
            if (*ms.begin() == g) break;
        }
        return *ms.begin();
    }
};

class Solution {
    int getNumberTransmittedLogs(int[] logTimestamp, String[] logTag, int bufferCapacity, int transmissionWindow) {
        java.util.LinkedList<int[]> buf = new java.util.LinkedList<>();
        java.util.LinkedList<String> bufTag = new java.util.LinkedList<>();
        int transmitted = 0;
        for (int i = 0; i < logTimestamp.length; i++) {
            int ts = logTimestamp[i]; String tag = logTag[i];
            java.util.Iterator<int[]> it1 = buf.iterator();
            java.util.Iterator<String> it2 = bufTag.iterator();
            while (it1.hasNext()) {
                int[] entry = it1.next(); String g = it2.next();
                if (g.equals(tag) && ts - entry[0] <= transmissionWindow) {
                    transmitted++; it1.remove(); it2.remove();
                }
            }
            if (buf.size() >= bufferCapacity) { buf.removeFirst(); bufTag.removeFirst(); }
            buf.add(new int[]{ts});
            bufTag.add(tag);
            transmitted++;
        }
        return transmitted;
    }
}

class Solution {
public:
    int getNumberTransmittedLogs(vector<int>& logTimestamp, vector<string>& logTag, int bufferCapacity, int transmissionWindow) {
        list<pair<int, string>> buf;
        int transmitted = 0;
        for (size_t i = 0; i < logTimestamp.size(); i++) {
            int ts = logTimestamp[i]; string tag = logTag[i];
            for (auto it = buf.begin(); it != buf.end();) {
                if (it->second == tag && ts - it->first <= transmissionWindow) {
                    transmitted++;
                    it = buf.erase(it);
                } else ++it;
            }
            if ((int) buf.size() >= bufferCapacity) buf.pop_front();
            buf.push_back({ts, tag});
            transmitted++;
        }
        return transmitted;
    }
};

