class Solution {
    int maxMeetings(int[] effectiveness) {
        Integer[] a = new Integer[effectiveness.length];
        for (int i = 0; i < a.length; i++) a[i] = effectiveness[i];
        java.util.Arrays.sort(a, java.util.Collections.reverseOrder());
        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
        long s = 0;
        int cnt = 0;
        for (int v : a) {
            if (s + v > 0) {
                s += v; heap.add(v); cnt++;
            } else if (!heap.isEmpty() && heap.peek() < v) {
                int old = heap.poll();
                s = s - old + v;
                heap.add(v);
            }
        }
        return cnt;
    }
}

