        sort(a.rbegin(), a.rend());
        priority_queue<int, vector<int>, greater<>> heap;
        long long s = 0;
        int cnt = 0;
        for (int v : a) {
            if (s + v > 0) { s += v; heap.push(v); cnt++; }
            else if (!heap.empty() && heap.top() < v) {
                int old = heap.top(); heap.pop();
                s = s - old + v;
                heap.push(v);
            }
        }
        return cnt;
    }
};

def maxSubsequenceLength(n, arr, k):
    dp = {}
    best = 1
    for v in arr:
        dp[v] = max(dp.get(v, 0), dp.get(v ^ k, 0) + 1)
        if dp[v] > best: best = dp[v]
    return best

class Solution {
    int maxSubsequenceLength(int n, int[] arr, int k) {
        java.util.HashMap<Integer, Integer> dp = new java.util.HashMap<>();
        int best = 1;
        for (int v : arr) {
            int prev = dp.getOrDefault(v ^ k, 0);
            int cur = Math.max(dp.getOrDefault(v, 0), prev + 1);
            dp.put(v, cur);
            if (cur > best) best = cur;
        }
        return best;
    }
}

class Solution {
public:
    int maxSubsequenceLength(int n, vector<int>& arr, int k) {
        unordered_map<int, int> dp;
        int best = 1;
        for (int v : arr) {
            int prev = dp.count(v ^ k) ? dp[v ^ k] : 0;
            int cur = max(dp.count(v) ? dp[v] : 0, prev + 1);
            dp[v] = cur;
            if (cur > best) best = cur;
        }
        return best;
    }
};

