def isPossible(a, b, c, d):
    while c >= a and d >= b:
        if c == a and d == b: return "Yes"
        if c > d:
            if d == b:
                if (c - a) % b == 0: return "Yes"
                return "No"
            c %= d
        else:
            if c == a:
                if (d - b) % a == 0: return "Yes"
                return "No"
            d %= c
    return "No"

