from sortedcontainers import SortedList

def maxMin(operations, x):
    sl = SortedList()
    res = []
    for op, v in zip(operations, x):
        if op == "push":
            sl.add(v)
        else:
            sl.remove(v)
        if sl:
            res.append(sl[0] * sl[-1])
        else:
            res.append(0)
    return res

class Solution {
    long[] maxMin(String[] operations, int[] x) {
        java.util.TreeMap<Integer, Integer> ms = new java.util.TreeMap<>();
        long[] res = new long[operations.length];
        for (int i = 0; i < operations.length; i++) {
            if (operations[i].equals("push")) ms.merge(x[i], 1, Integer::sum);
            else {
                if (ms.merge(x[i], -1, Integer::sum) == 0) ms.remove(x[i]);
            }
            if (ms.isEmpty()) res[i] = 0;
            else res[i] = (long) ms.firstKey() * ms.lastKey();
        }
        return res;
    }
}

class Solution {
public:
    vector<long long> maxMin(vector<string>& operations, vector<int>& x) {
        multiset<int> ms;
        vector<long long> res;
        for (size_t i = 0; i < operations.size(); i++) {
            if (operations[i] == "push") ms.insert(x[i]);
            else ms.erase(ms.find(x[i]));
            if (ms.empty()) res.push_back(0);
            else res.push_back((long long) *ms.begin() * *ms.rbegin());
        }
        return res;
    }
};

class Solution {
    String plusMultArray(int[] A) {
        long re = compute(A, 0), ro = compute(A, 1);
        if (ro > re) return "ODD";
        if (re > ro) return "EVEN";
        return "NEUTRAL";
    }
    long compute(int[] A, int start) {
        java.util.List<Integer> idx = new java.util.ArrayList<>();
        for (int i = start; i < A.length; i += 2) idx.add(i);
        if (idx.isEmpty()) return 0;
        long r = A[idx.get(0)];
        for (int k = 1; k < idx.size(); k++) {
            if ((k - 1) % 2 == 0) r = r * A[idx.get(k)];
            else r = r + A[idx.get(k)];
        }
        return r % 2;
    }
}

class Solution {
public:
    long long compute(vector<int>& A, int start) {
        vector<int> idx;
        for (int i = start; i < (int)A.size(); i += 2) idx.push_back(i);
        if (idx.empty()) return 0;
        long long r = A[idx[0]];
        for (size_t k = 1; k < idx.size(); k++) {
            if ((k - 1) % 2 == 0) r = r * A[idx[k]];
            else r = r + A[idx[k]];
        }
        return r % 2;
    }
    string plusMultArray(vector<int>& A) {
        long long re = compute(A, 0), ro = compute(A, 1);
        if (ro > re) return "ODD";
        if (re > ro) return "EVEN";
        return "NEUTRAL";
    }
};

def pointsBelong(x1, y1, x2, y2, x3, y3, xp, yp, xq, yq):
    def dist2(ax, ay, bx, by):
        return (ax - bx) ** 2 + (ay - by) ** 2
    def is_valid_triangle():
        # 用面积判：3 点不共线
        return (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1) != 0
    if not is_valid_triangle(): return 0
    def sign(a, b, c, x, y):
        return (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0])
    def in_tri(x, y):
        a = (x1, y1); b = (x2, y2); c = (x3, y3)
        d1 = sign(a, b, c, x, y)
        d2 = sign(b, c, a, x, y)
        d3 = sign(c, a, b, x, y)
        has_neg = d1 < 0 or d2 < 0 or d3 < 0
        has_pos = d1 > 0 or d2 > 0 or d3 > 0
        return not (has_neg and has_pos)
    p_in = in_tri(xp, yp)
    q_in = in_tri(xq, yq)
    if p_in and q_in: return 3
    if p_in: return 1
    if q_in: return 2
    return 4

class Solution {
    int pointsBelong(int x1, int y1, int x2, int y2, int x3, int y3, int xp, int yp, int xq, int yq) {
        long area2 = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
        if (area2 == 0) return 0;
        boolean p = inTri(x1, y1, x2, y2, x3, y3, xp, yp);
        boolean q = inTri(x1, y1, x2, y2, x3, y3, xq, yq);
        if (p && q) return 3;
        if (p) return 1;
        if (q) return 2;
        return 4;
    }
    boolean inTri(int x1, int y1, int x2, int y2, int x3, int y3, int x, int y) {
        long d1 = (long)(x2 - x1) * (y - y1) - (long)(y2 - y1) * (x - x1);
        long d2 = (long)(x3 - x2) * (y - y2) - (long)(y3 - y2) * (x - x2);
        long d3 = (long)(x1 - x3) * (y - y3) - (long)(y1 - y3) * (x - x3);
        boolean neg = d1 < 0 || d2 < 0 || d3 < 0;
        boolean pos = d1 > 0 || d2 > 0 || d3 > 0;
        return !(neg && pos);
    }
}

