class Solution {
    String[] preprocessDate(String[] dates) {
        java.util.HashMap<String, String> months = new java.util.HashMap<>();
        String[] mNames = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
        for (int i = 0; i < 12; i++) months.put(mNames[i], String.format("%02d", i + 1));
        String[] res = new String[dates.length];
        for (int i = 0; i < dates.length; i++) {
            String[] p = dates[i].split(" ");
            int day = Integer.parseInt(p[0].substring(0, p[0].length() - 2));
            res[i] = p[2] + "-" + months.get(p[1]) + "-" + String.format("%02d", day);
        }
        return res;
    }
