class Solution {
    int numberOfAlerts(int precedingMinutes, int alertThreshold, int[] numCalls) {
        int n = numCalls.length;
        if (n < precedingMinutes) return 0;
        long s = 0;
        for (int i = 0; i < precedingMinutes; i++) s += numCalls[i];
        int alerts = 0;
        if (s > (long) alertThreshold * precedingMinutes) alerts++;
        for (int i = precedingMinutes; i < n; i++) {
            s += numCalls[i] - numCalls[i - precedingMinutes];
            if (s > (long) alertThreshold * precedingMinutes) alerts++;
        }
        return alerts;
    }
}

