class Solution {
    static long[] getFinalData(long[] data, int[][] updates) {
        int n = data.length;
        int[] flip = new int[n + 1];
        for (int[] u : updates) {
            flip[u[0] - 1] ^= 1;
            flip[u[1]] ^= 1;
        }
        long[] out = new long[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur ^= flip[i];
            out[i] = cur == 1 ? -data[i] : data[i];
        }
        return out;
    }
}

