class Solution {
    long[] calculateNetProfit(String[] events) {
        java.util.HashMap<String, Long> position = new java.util.HashMap<>();
        java.util.HashMap<String, Long> price = new java.util.HashMap<>();
        long cash = 0;
        java.util.List<Long> res = new java.util.ArrayList<>();
        for (String e : events) {
            String[] p = e.split(" ");
            if (p[0].equals("BUY")) {
                long pr = price.getOrDefault(p[1], 0L);
                long qty = Long.parseLong(p[2]);
                cash -= pr * qty;
                position.merge(p[1], qty, Long::sum);
            } else if (p[0].equals("SELL")) {
                long pr = price.getOrDefault(p[1], 0L);
                long qty = Long.parseLong(p[2]);
                cash += pr * qty;
                position.merge(p[1], -qty, Long::sum);
            } else if (p[0].equals("CHANGE")) {
                price.merge(p[1], Long.parseLong(p[2]), Long::sum);
            } else {
                long unreal = 0;
                for (var en : position.entrySet()) unreal += en.getValue() * price.getOrDefault(en.getKey(), 0L);
                res.add(cash + unreal);
            }
        }
        long[] arr = new long[res.size()];
        for (int i = 0; i < res.size(); i++) arr[i] = res.get(i);
        return arr;
    }
}

class Solution {
public:
    vector<long long> calculateNetProfit(vector<string>& events) {
        unordered_map<string, long long> position, price;
        long long cash = 0;
        vector<long long> res;
        for (auto& e : events) {
            stringstream ss(e);
            string cmd; ss >> cmd;
            if (cmd == "BUY") {
                string s; long long q; ss >> s >> q;
                cash -= price[s] * q;
                position[s] += q;
            } else if (cmd == "SELL") {
                string s; long long q; ss >> s >> q;
                cash += price[s] * q;
                position[s] -= q;
            } else if (cmd == "CHANGE") {
                string s; long long d; ss >> s >> d;
                price[s] += d;
            } else {
                long long unreal = 0;
                for (auto& [s, q] : position) unreal += q * price[s];
                res.push_back(cash + unreal);
            }
        }
        return res;
    }
};

