class Solution {
    int[] countNumbers(int[][] arr) {
        int[] res = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            int n = arr[i][0], m = arr[i][1], cnt = 0;
            for (int x = n; x <= m; x++) {
                int mask = 0; boolean dup = false;
                int v = x;
                while (v > 0) {
                    int d = v % 10;
                    if ((mask & (1 << d)) != 0) { dup = true; break; }
