def countSignals(frequencies, filterRanges):
    lo = max(f[0] for f in filterRanges)
    hi = min(f[1] for f in filterRanges)
    if lo > hi: return 0
    return sum(1 for x in frequencies if lo <= x <= hi)

class Solution {
    int countSignals(int[] frequencies, int[][] filterRanges) {
        int lo = Integer.MIN_VALUE, hi = Integer.MAX_VALUE;
        for (int[] f : filterRanges) { lo = Math.max(lo, f[0]); hi = Math.min(hi, f[1]); }
        if (lo > hi) return 0;
        int cnt = 0;
        for (int x : frequencies) if (x >= lo && x <= hi) cnt++;
        return cnt;
    }
}

class Solution {
public:
    int countSignals(vector<int>& frequencies, vector<vector<int>>& filterRanges) {
        int lo = INT_MIN, hi = INT_MAX;
        for (auto& f : filterRanges) { lo = max(lo, f[0]); hi = min(hi, f[1]); }
        if (lo > hi) return 0;
        int cnt = 0;
        for (int x : frequencies) if (x >= lo && x <= hi) cnt++;
        return cnt;
    }
};

def countTeams(teamSize_1, teamSize_2, p):
    best = float('inf')
    for a in range(p // teamSize_1 + 1):
        rem = p - a * teamSize_1
        if rem >= 0 and rem % teamSize_2 == 0:
            best = min(best, a + rem // teamSize_2)
    return -1 if best == float('inf') else best

class Solution {
    int countTeams(int teamSize_1, int teamSize_2, int p) {
        int best = Integer.MAX_VALUE;
        for (int a = 0; a <= p / teamSize_1; a++) {
            int rem = p - a * teamSize_1;
            if (rem >= 0 && rem % teamSize_2 == 0) best = Math.min(best, a + rem / teamSize_2);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

class Solution {
public:
    int countTeams(int teamSize_1, int teamSize_2, int p) {
        int best = INT_MAX;
        for (int a = 0; a <= p / teamSize_1; a++) {
            int rem = p - a * teamSize_1;
            if (rem >= 0 && rem % teamSize_2 == 0) best = min(best, a + rem / teamSize_2);
        }
        return best == INT_MAX ? -1 : best;
    }
};

def findMinimumCost(arr):
