def findNumOfPairs(a, b):
    a = sorted(a)
    b = sorted(b)
    i = j = pairs = 0
    while i < len(a) and j < len(b):
        if a[i] > b[j]:
            pairs += 1
            i += 1
            j += 1
        else:
            i += 1
    return pairs

class Solution {
    int findNumOfPairs(int[] a, int[] b) {
        int[] aa = a.clone(), bb = b.clone();
        java.util.Arrays.sort(aa); java.util.Arrays.sort(bb);
        int i = 0, j = 0, pairs = 0;
        while (i < aa.length && j < bb.length) {
            if (aa[i] > bb[j]) { pairs++; i++; j++; }
            else i++;
        }
        return pairs;
    }
}

class Solution {
public:
    int findNumOfPairs(vector<int>& a, vector<int>& b) {
        vector<int> aa = a, bb = b;
        sort(aa.begin(), aa.end()); sort(bb.begin(), bb.end());
        int i = 0, j = 0, pairs = 0;
        while (i < (int)aa.size() && j < (int)bb.size()) {
            if (aa[i] > bb[j]) { pairs++; i++; j++; }
            else i++;
        }
        return pairs;
    }
};

class Solution {
    java.util.List<Integer> findSumWeight(int[] cans) {
        java.util.List<Integer> arr = new java.util.ArrayList<>();
        for (int x : cans) arr.add(x);
        java.util.List<Integer> res = new java.util.ArrayList<>();
        while (arr.size() >= 3) {
            int mn = Integer.MAX_VALUE;
            for (int x : arr) mn = Math.min(mn, x);
            int found = -1;
            for (int i = 0; i + 2 < arr.size(); i++) {
                if (arr.get(i) == mn && arr.get(i + 1) == mn && arr.get(i + 2) == mn) { found = i; break; }
            }
            if (found < 0) break;
            res.add(arr.get(found) + arr.get(found + 1) + arr.get(found + 2));
            arr.subList(found, found + 3).clear();
        }
        return res;
    }
}

class Solution {
public:
    vector<int> findSumWeight(vector<int>& cans) {
        vector<int> arr = cans, res;
        while (arr.size() >= 3) {
            int mn = *min_element(arr.begin(), arr.end());
            int found = -1;
            for (int i = 0; i + 2 < (int)arr.size(); i++) {
                if (arr[i] == mn && arr[i + 1] == mn && arr[i + 2] == mn) { found = i; break; }
            }
            if (found < 0) break;
            res.push_back(arr[found] + arr[found + 1] + arr[found + 2]);
            arr.erase(arr.begin() + found, arr.begin() + found + 3);
        }
        return res;
    }
};

class Solution {
    long findTotalCost(int[] arr) {
        java.util.TreeMap<Long, Integer> ms = new java.util.TreeMap<>();
        for (int x : arr) ms.merge((long) x, 1, Integer::sum);
        long total = 0;
        while (ms.values().stream().mapToInt(Integer::intValue).sum() > 1) {
            long mn = ms.firstKey();
            if (ms.merge(mn, -1, Integer::sum) == 0) ms.remove(mn);
            long mx = ms.lastKey();
            if (ms.merge(mx, -1, Integer::sum) == 0) ms.remove(mx);
            long cost = (mn + mx + (mx - mn + 1) - 1) / (mx - mn + 1);
            total += cost;
            ms.merge(mn + mx, 1, Integer::sum);
        }
        return total;
    }
}

class Solution {
public:
    long long findTotalCost(vector<int>& arr) {
        multiset<long long> ms(arr.begin(), arr.end());
        long long total = 0;
        while (ms.size() > 1) {
            long long mn = *ms.begin();
            ms.erase(ms.begin());
            long long mx = *ms.rbegin();
            ms.erase(prev(ms.end()));
            long long cost = (mn + mx + (mx - mn + 1) - 1) / (mx - mn + 1);
            total += cost;
            ms.insert(mn + mx);
        }
        return total;
    }
};

class Solution {
    long findTotalWeight(int[] cans) {
        java.util.LinkedList<Integer> arr = new java.util.LinkedList<>();
        for (int x : cans) arr.add(x);
        long total = 0;
        while (!arr.isEmpty()) {
            int mn = Integer.MAX_VALUE, idx = -1;
            for (int i = 0; i < arr.size(); i++) if (arr.get(i) < mn) { mn = arr.get(i); idx = i; }
            total += mn;
            int lo = Math.max(0, idx - 1), hi = Math.min(arr.size(), idx + 2);
            for (int i = hi - 1; i >= lo; i--) arr.remove(i);
        }
        return total;
    }
}

class Solution {
public:
    long long findTotalWeight(vector<int>& cans) {
        vector<int> arr = cans;
        long long total = 0;
        while (!arr.empty()) {
            int mn = INT_MAX, idx = -1;
            for (size_t i = 0; i < arr.size(); i++) if (arr[i] < mn) { mn = arr[i]; idx = i; }
            total += mn;
            int lo = max(0, idx - 1), hi = min((int)arr.size(), idx + 2);
            arr.erase(arr.begin() + lo, arr.begin() + hi);
        }
        return total;
    }
};

def generateTableOfContents(text):
    res = []
    chapter = 0
    section = 0
    for line in text:
        if line.startswith("## "):
            section += 1
            res.append(f"{chapter}.{section}. " + line[3:])
        elif line.startswith("# "):
            chapter += 1
            section = 0
            res.append(f"{chapter}. " + line[2:])
    return res

class Solution {
    String[] generateTableOfContents(String[] text) {
        java.util.List<String> res = new java.util.ArrayList<>();
        int chapter = 0, section = 0;
        for (String line : text) {
            if (line.startsWith("## ")) {
                section++;
                res.add(chapter + "." + section + ". " + line.substring(3));
            } else if (line.startsWith("# ")) {
                chapter++; section = 0;
                res.add(chapter + ". " + line.substring(2));
            }
        }
        return res.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> generateTableOfContents(vector<string>& text) {
        vector<string> res;
        int chapter = 0, section = 0;
        for (auto& line : text) {
            if (line.rfind("## ", 0) == 0) {
                section++;
                res.push_back(to_string(chapter) + "." + to_string(section) + ". " + line.substr(3));
            } else if (line.rfind("# ", 0) == 0) {
                chapter++; section = 0;
                res.push_back(to_string(chapter) + ". " + line.substr(2));
            }
        }
        return res;
    }
};

def getFinalString(s):
    st = []
    for c in s:
        st.append(c)
        if len(st) >= 3 and st[-3] == 'A' and st[-2] == 'W' and st[-1] == 'S':
            st.pop(); st.pop(); st.pop()
    return "".join(st) if st else "-1"

class Solution {
    String getFinalString(String s) {
        StringBuilder st = new StringBuilder();
        for (char c : s.toCharArray()) {
            st.append(c);
            int n = st.length();
            if (n >= 3 && st.charAt(n - 3) == 'A' && st.charAt(n - 2) == 'W' && st.charAt(n - 1) == 'S') {
                st.setLength(n - 3);
            }
        }
        return st.length() == 0 ? "-1" : st.toString();
    }
}

class Solution {
public:
    string getFinalString(string s) {
        string st;
        for (char c : s) {
            st += c;
            int n = st.size();
            if (n >= 3 && st[n - 3] == 'A' && st[n - 2] == 'W' && st[n - 1] == 'S') st.resize(n - 3);
        }
        return st.empty() ? "-1" : st;
    }
};

def getLargestNumber(num):
    odds = sorted([c for c in num if int(c) % 2 == 1], reverse=True)
    evens = sorted([c for c in num if int(c) % 2 == 0], reverse=True)
    res = []
    oi = ei = 0
    for c in num:
        if int(c) % 2 == 1:
            res.append(odds[oi]); oi += 1
        else:
            res.append(evens[ei]); ei += 1
    return "".join(res)

class Solution {
    String getLargestNumber(String num) {
        java.util.List<Character> odds = new java.util.ArrayList<>();
        java.util.List<Character> evens = new java.util.ArrayList<>();
        for (char c : num.toCharArray()) {
            if ((c - '0') % 2 == 1) odds.add(c);
            else evens.add(c);
        }
        odds.sort(java.util.Collections.reverseOrder());
        evens.sort(java.util.Collections.reverseOrder());
        StringBuilder sb = new StringBuilder();
        int oi = 0, ei = 0;
        for (char c : num.toCharArray()) {
            if ((c - '0') % 2 == 1) sb.append(odds.get(oi++));
            else sb.append(evens.get(ei++));
        }
        return sb.toString();
    }
}

class Solution {
public:
    string getLargestNumber(string num) {
        vector<char> odds, evens;
        for (char c : num) {
            if ((c - '0') % 2 == 1) odds.push_back(c);
            else evens.push_back(c);
        }
        sort(odds.rbegin(), odds.rend());
        sort(evens.rbegin(), evens.rend());
        string res;
        int oi = 0, ei = 0;
        for (char c : num) {
            if ((c - '0') % 2 == 1) res += odds[oi++];
            else res += evens[ei++];
        }
        return res;
    }
};

def getMaxDeletions(S):
    cnt = {'U': 0, 'D': 0, 'L': 0, 'R': 0}
    for c in S: cnt[c] += 1
    return 2 * (min(cnt['U'], cnt['D']) + min(cnt['L'], cnt['R']))

class Solution {
    int getMaxDeletions(String S) {
        int U = 0, D = 0, L = 0, R = 0;
        for (char c : S.toCharArray()) {
            if (c == 'U') U++;
            else if (c == 'D') D++;
            else if (c == 'L') L++;
            else if (c == 'R') R++;
        }
        return 2 * (Math.min(U, D) + Math.min(L, R));
    }
}

class Solution {
public:
    int getMaxDeletions(string S) {
        int U = 0, D = 0, L = 0, R = 0;
        for (char c : S) {
            if (c == 'U') U++;
            else if (c == 'D') D++;
            else if (c == 'L') L++;
            else if (c == 'R') R++;
        }
        return 2 * (min(U, D) + min(L, R));
    }
};

def getMergedIntervals(intervals):
    if not intervals: return []
    a = sorted(intervals)
    res = [a[0][:]]
    for s, e in a[1:]:
        if s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

class Solution {
    int[][] getMergedIntervals(int[][] intervals) {
        if (intervals.length == 0) return new int[0][];
        int[][] a = intervals.clone();
        java.util.Arrays.sort(a, (x, y) -> Integer.compare(x[0], y[0]));
        java.util.List<int[]> res = new java.util.ArrayList<>();
        res.add(a[0].clone());
        for (int i = 1; i < a.length; i++) {
            int[] last = res.get(res.size() - 1);
            if (a[i][0] <= last[1]) last[1] = Math.max(last[1], a[i][1]);
            else res.add(a[i].clone());
        }
        return res.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> getMergedIntervals(vector<vector<int>>& intervals) {
        if (intervals.empty()) return {};
        vector<vector<int>> a = intervals;
        sort(a.begin(), a.end());
        vector<vector<int>> res = {a[0]};
        for (size_t i = 1; i < a.size(); i++) {
            if (a[i][0] <= res.back()[1]) res.back()[1] = max(res.back()[1], a[i][1]);
            else res.push_back(a[i]);
        }
        return res;
    }
};

def getMinLength(seq):
    st = []
    for c in seq:
        if c == 'B' and st and (st[-1] == 'A' or st[-1] == 'B'):
            st.pop()
        else:
            st.append(c)
    return len(st)

class Solution {
    int getMinLength(String seq) {
        java.util.ArrayDeque<Character> st = new java.util.ArrayDeque<>();
        for (char c : seq.toCharArray()) {
            if (c == 'B' && !st.isEmpty() && (st.peek() == 'A' || st.peek() == 'B')) st.pop();
            else st.push(c);
        }
        return st.size();
    }
}

class Solution {
public:
    int getMinLength(string seq) {
        string st;
        for (char c : seq) {
            if (c == 'B' && !st.empty() && (st.back() == 'A' || st.back() == 'B')) st.pop_back();
            else st += c;
        }
        return st.size();
    }
};

class Solution {
    int getMinMachines(int[] start, int[] end) {
        int n = start.length;
        int[][] ev = new int[2 * n][2];
        for (int i = 0; i < n; i++) { ev[2*i] = new int[]{start[i], 1}; ev[2*i+1] = new int[]{end[i] + 1, -1}; }
        java.util.Arrays.sort(ev, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int cur = 0, best = 0;
        for (int[] e : ev) { cur += e[1]; if (cur > best) best = cur; }
        return best;
    }
}

class Solution {
public:
    int getMinMachines(vector<int>& start, vector<int>& end) {
        vector<pair<int,int>> ev;
        for (size_t i = 0; i < start.size(); i++) { ev.push_back({start[i], 1}); ev.push_back({end[i] + 1, -1}); }
        sort(ev.begin(), ev.end());
        int cur = 0, best = 0;
        for (auto& e : ev) { cur += e.second; best = max(best, cur); }
        return best;
    }
};

def getMinOperations(kValues):
    res = []
    for k in kValues:
        if k == 0:
            res.append(0); continue
        ops = 0
        while k > 0:
            if k & 1:
                k -= 1
            else:
                k >>= 1
            ops += 1
        res.append(ops)
    return res

class Solution {
    int[] getMinOperations(long[] kValues) {
        int[] res = new int[kValues.length];
        for (int i = 0; i < kValues.length; i++) {
            long k = kValues[i]; int ops = 0;
            while (k > 0) {
                if ((k & 1) == 1) k--; else k >>= 1;
                ops++;
            }
            res[i] = ops;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getMinOperations(vector<long long>& kValues) {
        vector<int> res(kValues.size());
        for (size_t i = 0; i < kValues.size(); i++) {
            long long k = kValues[i]; int ops = 0;
            while (k > 0) {
                if (k & 1) k--; else k >>= 1;
                ops++;
            }
            res[i] = ops;
        }
        return res;
    }
};

def getMinimumOperations(items):
    n = len(items)
    arr = items[:]
    total = 0
    def cost_to_flip(v, target_parity):
        c = 0
        while v % 2 != target_parity and v > 0:
            v //= 2
            c += 1
            if v == 0: break
        # 若 v 变 0 后还不达预期 parity（0 是偶）
        return c if (v % 2 == target_parity) else float('inf')
    # 简化版：对每相邻对，若同奇偶就把右边 /2 直到不同
    for i in range(n - 1):
        while arr[i] % 2 == arr[i + 1] % 2:
            # 优先 / 2 右边
            if arr[i + 1] > 0:
                arr[i + 1] //= 2
                total += 1
            else:
                arr[i] //= 2
                total += 1
                if arr[i] == 0 and arr[i + 1] == 0: break
    return total

class Solution {
    int getMinimumOperations(int[] items) {
        int[] arr = items.clone();
        int total = 0;
        for (int i = 0; i + 1 < arr.length; i++) {
            int safety = 60;
            while (arr[i] % 2 == arr[i + 1] % 2 && safety-- > 0) {
                if (arr[i + 1] > 0) { arr[i + 1] /= 2; total++; }
                else if (arr[i] > 0) { arr[i] /= 2; total++; }
                else break;
            }
        }
        return total;
    }
}

class Solution {
public:
    int getMinimumOperations(vector<int>& items) {
        vector<int> arr = items;
        int total = 0;
        for (size_t i = 0; i + 1 < arr.size(); i++) {
            int safety = 60;
            while (arr[i] % 2 == arr[i + 1] % 2 && safety-- > 0) {
                if (arr[i + 1] > 0) { arr[i + 1] /= 2; total++; }
                else if (arr[i] > 0) { arr[i] /= 2; total++; }
                else break;
            }
        }
        return total;
    }
};

from collections import deque

def getPotentialOfWinner(potential, k):
    if k >= len(potential) - 1:
        return max(potential)
    dq = deque(potential)
    a = dq.popleft()
    streak = 0
    while True:
        b = dq.popleft()
        if a > b:
            streak += 1
            dq.append(b)
        else:
            dq.append(a)
            a = b
            streak = 1
        if streak >= k:
            return a

class Solution {
    int getPotentialOfWinner(int[] potential, long k) {
        if (k >= potential.length - 1) {
            int mx = Integer.MIN_VALUE;
            for (int x : potential) mx = Math.max(mx, x);
            return mx;
        }
        java.util.ArrayDeque<Integer> dq = new java.util.ArrayDeque<>();
        for (int x : potential) dq.add(x);
        int a = dq.poll();
        long streak = 0;
        while (true) {
            int b = dq.poll();
            if (a > b) { streak++; dq.add(b); }
            else { dq.add(a); a = b; streak = 1; }
            if (streak >= k) return a;
        }
    }
}

class Solution {
public:
    int getPotentialOfWinner(vector<int>& potential, long long k) {
        if (k >= (long long) potential.size() - 1) return *max_element(potential.begin(), potential.end());
        deque<int> dq(potential.begin(), potential.end());
        int a = dq.front(); dq.pop_front();
        long long streak = 0;
        while (true) {
            int b = dq.front(); dq.pop_front();
            if (a > b) { streak++; dq.push_back(b); }
            else { dq.push_back(a); a = b; streak = 1; }
            if (streak >= k) return a;
        }
    }
};

def getSearchResults(words, queries):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    for g in groups.values():
        g.sort()
    res = []
    for q in queries:
        key = "".join(sorted(q))
        res.append(groups.get(key, []))
    return res

class Solution {
    String[][] getSearchResults(String[] words, String[] queries) {
        java.util.HashMap<String, java.util.List<String>> groups = new java.util.HashMap<>();
        for (String w : words) {
            char[] ca = w.toCharArray();
            java.util.Arrays.sort(ca);
            groups.computeIfAbsent(new String(ca), k -> new java.util.ArrayList<>()).add(w);
        }
        for (var g : groups.values()) java.util.Collections.sort(g);
        String[][] res = new String[queries.length][];
        for (int i = 0; i < queries.length; i++) {
            char[] ca = queries[i].toCharArray();
            java.util.Arrays.sort(ca);
            java.util.List<String> g = groups.get(new String(ca));
            res[i] = g == null ? new String[0] : g.toArray(new String[0]);
        }
        return res;
    }
}

class Solution {
public:
    vector<vector<string>> getSearchResults(vector<string>& words, vector<string>& queries) {
        unordered_map<string, vector<string>> groups;
        for (auto& w : words) {
            string k = w;
            sort(k.begin(), k.end());
            groups[k].push_back(w);
        }
        for (auto& [k, v] : groups) sort(v.begin(), v.end());
        vector<vector<string>> res;
        for (auto& q : queries) {
            string k = q;
            sort(k.begin(), k.end());
            auto it = groups.find(k);
            res.push_back(it == groups.end() ? vector<string>() : it->second);
        }
        return res;
    }
};

def getUniqueCharacter(s):
    cnt = [0] * 26
    for c in s: cnt[ord(c) - ord('a')] += 1
    for i, c in enumerate(s):
        if cnt[ord(c) - ord('a')] == 1: return i + 1
    return -1

class Solution {
    int getUniqueCharacter(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
