class Solution {
    long maximumAmount(int[] quantity, int m) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int q : quantity) pq.add(q);
        long total = 0;
        for (int i = 0; i < m; i++) {
            if (pq.isEmpty() || pq.peek() == 0) break;
            int top = pq.poll();
            total += top - 1;
            if (top - 1 > 0) pq.add(top - 1);
        }
        return total;
    }
}

