def maximumInformation(security_val, k):
    n = len(security_val)
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        nxt = dp[i + k] if i + k < n else 0
        dp[i] = security_val[i] + max(0, nxt)
    return max(dp)

class Solution {
    long maximumInformation(int[] security_val, int k) {
        int n = security_val.length;
        long[] dp = new long[n];
        long best = Long.MIN_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            long nxt = i + k < n ? dp[i + k] : 0;
            dp[i] = security_val[i] + Math.max(0L, nxt);
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

