class Solution {
    int minimumSwaps(int[] popularity) {
        int[] a = popularity.clone();
        Integer[] sortedDesc = new Integer[a.length];
        for (int i = 0; i < a.length; i++) sortedDesc[i] = a[i];
        java.util.Arrays.sort(sortedDesc, java.util.Collections.reverseOrder());
        java.util.HashMap<Integer, Integer> pos = new java.util.HashMap<>();
        for (int i = 0; i < a.length; i++) pos.put(a[i], i);
        int swaps = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] != sortedDesc[i]) {
                int target = sortedDesc[i];
                int j = pos.get(target);
                int tmp = a[i]; a[i] = a[j]; a[j] = tmp;
                pos.put(a[j], j);
                pos.put(a[i], i);
                swaps++;
            }
        }
        return swaps;
    }
}

