        for (int i = 0; i < (int)a.size(); i++) {
            if (a[i] != sortedDesc[i]) {
                int target = sortedDesc[i], j = pos[target];
                swap(a[i], a[j]);
                pos[a[j]] = j;
                pos[a[i]] = i;
                swaps++;
            }
        }
        return swaps;
    }
};

class Solution {
    int oneSubstringCount(String s) {
        java.util.List<Integer> runs = new java.util.ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            int j = i;
            while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
            runs.add(j - i);
            i = j;
        }
        int total = 0;
        for (int k = 0; k + 1 < runs.size(); k++) total += Math.min(runs.get(k), runs.get(k + 1));
        return total;
    }
}

