class Solution {
    int printNumberOfElementsWithoutRepeatingDigits(int start, int end) {
        int cnt = 0;
        for (int x = start; x <= end; x++) {
            int mask = 0; boolean dup = false; int v = x;
            while (v > 0) {
                int d = v % 10;
                if ((mask & (1 << d)) != 0) { dup = true; break; }
                mask |= 1 << d;
                v /= 10;
            }
            if (!dup) cnt++;
        }
        return cnt;
    }
}

