def solution(paragraphs, aligns, width):
    lines = []
    for words, align in zip(paragraphs, aligns):
        cur = []
        cur_len = 0
        for w in words:
            extra = 1 if cur else 0
            if cur_len + extra + len(w) <= width:
                cur.append(w); cur_len += extra + len(w)
            else:
                lines.append((cur, align))
                cur = [w]; cur_len = len(w)
        if cur: lines.append((cur, align))
    out = []
    border = '*' * (width + 2)
    out.append(border)
    for words, align in lines:
        line = ' '.join(words)
        pad = width - len(line)
        if align == "LEFT":
            line = line + ' ' * pad
        else:
            line = ' ' * pad + line
        out.append('*' + line + '*')
    out.append(border)
    return out

class Solution {
    public List<String> newspaperLayout(String[][] paras, String[] aligns, int W) {
        List<Object[]> lines = new ArrayList<>();
        for (int p = 0; p < paras.length; p++) {
            List<String> cur = new ArrayList<>(); int len = 0;
            for (String w : paras[p]) {
                int add = (cur.isEmpty() ? 0 : 1) + w.length();
                if (len + add <= W) { cur.add(w); len += add; }
                else { lines.add(new Object[]{cur, aligns[p]}); cur = new ArrayList<>(); cur.add(w); len = w.length(); }
            }
            if (!cur.isEmpty()) lines.add(new Object[]{cur, aligns[p]});
        }
        List<String> out = new ArrayList<>();
        String border = "*".repeat(W + 2);
        out.add(border);
        for (Object[] ln : lines) {
            String s = String.join(" ", (List<String>) ln[0]);
            int pad = W - s.length();
            s = ln[1].equals("LEFT") ? s + " ".repeat(pad) : " ".repeat(pad) + s;
            out.add("*" + s + "*");
        }
        out.add(border);
        return out;
    }
}

vector<string> newspaperLayout(vector<vector<string>>& paras, vector<string>& aligns, int W) {
 vector<pair<vector<string>, string>> lines;
 for (int p = 0; p < (int)paras.size(); ++p) {
 vector<string> cur; int len = 0;
 for (auto& w : paras[p]) {
 int add = (cur.empty() ? 0 : 1) + (int)w.size();
 if (len + add <= W) { cur.push_back(w); len += add; }
 else { lines.push_back({cur, aligns[p]}); cur = {w}; len = w.size(); }
 }
 if (!cur.empty()) lines.push_back({cur, aligns[p]});
 }
 vector<string> out;
 string border(W + 2, '*');
 out.push_back(border);
 for (auto& [ws, al] : lines) {
 string s;
 for (int i = 0; i < (int)ws.size(); ++i) { if (i) s += ' '; s += ws[i]; }
 int pad = W - s.size();
 s = (al == "LEFT") ? s + string(pad, ' ') : string(pad, ' ') + s;
 out.push_back("*" + s + "*");
 }
 out.push_back(border);
 return out;
}

class Solution {
    public String lunarPhase(String season, int dayCount, String initialPhase) {
        String[] phases = {"NewMoon","Crescent","Quarter","Gibbous","Full","Waning","Eclipse","Twilight"};
        String[] months = {"January","February","March","April","May","June","July","August","September","October","November","December"};
        int[] days = {31,28,31,30,31,30,31,31,30,31,30,31};
        int total = 0;
        for (int i = 0; i < months.length; i++) { if (months[i].equals(season)) break; total += days[i]; }
        total += dayCount - 1;
        int start = 0; for (int i = 0; i < 8; i++) if (phases[i].equals(initialPhase)) { start = i; break; }
        return phases[(start + total) % 8];
    }
}

string lunarPhase(string season, int dayCount, string initialPhase) {
 vector<string> phases = {"NewMoon","Crescent","Quarter","Gibbous","Full","Waning","Eclipse","Twilight"};
 vector<pair<string,int>> months = {{"January",31},{"February",28},{"March",31},{"April",30},{"May",31},{"June",30},
 {"July",31},{"August",31},{"September",30},{"October",31},{"November",30},{"December",31}};
 int total = 0;
 for (auto& [m, d] : months) { if (m == season) break; total += d; }
 total += dayCount - 1;
 int start = find(phases.begin(), phases.end(), initialPhase) - phases.begin();
 return phases[(start + total) % 8];
}

def robot_matrix(mat, cmds):
    M = [row[:] for row in mat]
    for cmd in cmds:
        parts = cmd.split()
        op = parts[0]
        if op == 'swapRows':
            r1, r2 = int(parts[1]), int(parts[2]); M[r1], M[r2] = M[r2], M[r1]
        elif op == 'swapColumns':
            c1, c2 = int(parts[1]), int(parts[2])
            for row in M: row[c1], row[c2] = row[c2], row[c1]
        elif op == 'reverseRow':
            r = int(parts[1]); M[r].reverse()
        elif op == 'reverseColumn':
            c = int(parts[1])
            col = [M[i][c] for i in range(len(M))][::-1]
            for i in range(len(M)): M[i][c] = col[i]
        else:
            nr, nc = len(M), len(M[0])
            M = [[M[nr - 1 - i][j] for i in range(nr)] for j in range(nc)]
    return M

class Solution {
    public int[][] robotMatrix(int[][] mat, String[] cmds) {
        int[][] M = mat;
        for (String cmd : cmds) {
            String[] parts = cmd.split(" ");
            switch (parts[0]) {
                case "swapRows": { int r1 = Integer.parseInt(parts[1]), r2 = Integer.parseInt(parts[2]); int[] t = M[r1]; M[r1] = M[r2]; M[r2] = t; break; }
                case "swapColumns": { int c1 = Integer.parseInt(parts[1]), c2 = Integer.parseInt(parts[2]); for (int[] row : M) { int t = row[c1]; row[c1] = row[c2]; row[c2] = t; } break; }
                case "reverseRow": { int r = Integer.parseInt(parts[1]); for (int i = 0, j = M[r].length - 1; i < j; i++, j--) { int t = M[r][i]; M[r][i] = M[r][j]; M[r][j] = t; } break; }
                case "reverseColumn": { int c = Integer.parseInt(parts[1]); for (int i = 0, j = M.length - 1; i < j; i++, j--) { int t = M[i][c]; M[i][c] = M[j][c]; M[j][c] = t; } break; }
                case "rotate90Clockwise": {
                    int nr = M.length, nc = M[0].length;
                    int[][] nw = new int[nc][nr];
                    for (int j = 0; j < nc; j++) for (int i = 0; i < nr; i++) nw[j][i] = M[nr - 1 - i][j];
                    M = nw; break;
                }
            }
        }
        return M;
    }
}

vector<vector<int>> robotMatrix(vector<vector<int>>& mat, vector<string>& cmds) {
 auto M = mat;
 for (auto& cmd : cmds) {
 stringstream ss(cmd); string op; ss >> op;
 if (op == "swapRows") { int r1, r2; ss >> r1 >> r2; swap(M[r1], M[r2]); }
 else if (op == "swapColumns") { int c1, c2; ss >> c1 >> c2; for (auto& row : M) swap(row[c1], row[c2]); }
 else if (op == "reverseRow") { int r; ss >> r; reverse(M[r].begin(), M[r].end()); }
 else if (op == "reverseColumn") { int c; ss >> c; int n = M.size(); for (int i = 0; i < n / 2; ++i) swap(M[i][c], M[n-1-i][c]); }
 else {
 int nr = M.size(), nc = M[0].size();
 vector<vector<int>> nw(nc, vector<int>(nr));
 for (int j = 0; j < nc; ++j) for (int i = 0; i < nr; ++i) nw[j][i] = M[nr-1-i][j];
 M = nw;
 }
 }
 return M;
}

class Solution {
    public List<Integer> reconstructJourney(int[][] photos) {
        Map<Integer, Set<Integer>> g = new HashMap<>();
        for (int[] p : photos) {
            g.computeIfAbsent(p[0], k -> new HashSet<>()).add(p[1]);
            g.computeIfAbsent(p[1], k -> new HashSet<>()).add(p[0]);
        }
        int start = -1;
        for (Map.Entry<Integer, Set<Integer>> e : g.entrySet()) if (e.getValue().size() == 1) { start = e.getKey(); break; }
        if (start == -1) start = g.keySet().iterator().next();
        List<Integer> path = new ArrayList<>(); path.add(start);
        int prev = -1, cur = start;
        while (true) {
            int nxt = -1;
            for (int v : g.get(cur)) if (v != prev) { nxt = v; break; }
            if (nxt == -1) break;
            path.add(nxt); prev = cur; cur = nxt;
        }
        return path;
    }
}

vector<int> reconstructJourney(vector<vector<int>>& photos) {
 unordered_map<int, set<int>> g;
 for (auto& p : photos) { g[p[0]].insert(p[1]); g[p[1]].insert(p[0]); }
 int start = -1;
 for (auto& [k, s] : g) if (s.size() == 1) { start = k; break; }
 if (start == -1) start = g.begin()->first;
 vector<int> path = {start};
 int prev = -1, cur = start;
 while (true) {
 int nxt = -1;
 for (int v : g[cur]) if (v != prev) { nxt = v; break; }
 if (nxt == -1) break;
 path.push_back(nxt); prev = cur; cur = nxt;
 }
 return path;
}

def solution(memory, queries):
    n = len(memory)
    ids = [0] * n
    counter = 1
    out = []
    for q in queries:
        if q[0] == 0:
            x = q[1]
            found = -1
            for start in range(0, n - x + 1, 8):
                if all(memory[start + k] == 0 for k in range(x)):
                    found = start; break
            if found == -1:
                out.append(-1)
            else:
                for k in range(x):
                    memory[found + k] = 1
                    ids[found + k] = counter
                out.append(found)
                counter += 1
        else:
            tid = q[1]
            freed = 0
            for i in range(n):
                if ids[i] == tid:
                    ids[i] = 0
                    memory[i] = 0
                    freed += 1
            out.append(freed if freed else -1)
    return out

class Solution {
    public int[] memAlloc(int[] mem, int[][] queries) {
        int n = mem.length;
        int[] ids = new int[n];
        int counter = 1;
        int[] out = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int[] q = queries[qi];
            if (q[0] == 0) {
                int x = q[1], found = -1;
                for (int s = 0; s <= n - x; s += 8) {
                    boolean ok = true;
                    for (int k = 0; k < x; k++) if (mem[s + k] != 0) { ok = false; break; }
                    if (ok) { found = s; break; }
                }
                if (found == -1) out[qi] = -1;
                else { for (int k = 0; k < x; k++) { mem[found+k] = 1; ids[found+k] = counter; } out[qi] = found; counter++; }
            } else {
                int tid = q[1], freed = 0;
                for (int i = 0; i < n; i++) if (ids[i] == tid) { ids[i] = 0; mem[i] = 0; freed++; }
                out[qi] = freed > 0 ? freed : -1;
            }
        }
        return out;
    }
}

vector<int> memAlloc(vector<int>& mem, vector<vector<int>>& queries) {
 int n = mem.size();
 vector<int> ids(n, 0);
 int counter = 1;
 vector<int> out;
 for (auto& q : queries) {
 if (q[0] == 0) {
 int x = q[1], found = -1;
 for (int s = 0; s <= n - x; s += 8) {
 bool ok = true;
 for (int k = 0; k < x; ++k) if (mem[s + k] != 0) { ok = false; break; }
 if (ok) { found = s; break; }
 }
 if (found == -1) out.push_back(-1);
 else { for (int k = 0; k < x; ++k) { mem[found+k] = 1; ids[found+k] = counter; } out.push_back(found); ++counter; }
 } else {
 int tid = q[1], freed = 0;
 for (int i = 0; i < n; ++i) if (ids[i] == tid) { ids[i] = 0; mem[i] = 0; ++freed; }
 out.push_back(freed ? freed : -1);
 }
 }
 return out;
}

class Solution {
    public List<Long> pairSumQueries(int[] a, int[] b, int[][] queries) {
        Map<Integer, Integer> cntA = new HashMap<>(), cntB = new HashMap<>();
        for (int x : a) cntA.merge(x, 1, Integer::sum);
        for (int x : b) cntB.merge(x, 1, Integer::sum);
        List<Long> out = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 0) { cntA.merge(a[q[1]], -1, Integer::sum); a[q[1]] += q[2]; cntA.merge(a[q[1]], 1, Integer::sum); }
            else {
                long t = 0;
                for (Map.Entry<Integer, Integer> e : cntA.entrySet()) t += (long) e.getValue() * cntB.getOrDefault(q[1] - e.getKey(), 0);
                out.add(t);
            }
        }
        return out;
    }
}

vector<long long> pairSumQueries(vector<int>& a, vector<int>& b, vector<vector<int>>& queries) {
 unordered_map<int,int> cntA, cntB;
 for (int x : a) cntA[x]++;
 for (int x : b) cntB[x]++;
 vector<long long> out;
 for (auto& q : queries) {
 if (q[0] == 0) { cntA[a[q[1]]]--; a[q[1]] += q[2]; cntA[a[q[1]]]++; }
 else {
 long long t = 0;
 for (auto& [v, c] : cntA) { auto it = cntB.find(q[1] - v); if (it != cntB.end()) t += (long long)c * it->second; }
 out.push_back(t);
 }
 }
 return out;
}

def solution(cityLine):
    n = len(cityLine)
    def can(s):
        run = 0
        for h in cityLine:
            if h >= s:
                run += 1
                if run >= s: return True
            else:
                run = 0
        return False
    lo, hi = 0, min(n, max(cityLine))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid): lo = mid
        else: hi = mid - 1
    return lo * lo

class Solution {
    public int largestSquareCity(int[] cityLine) {
        int n = cityLine.length, mx = 0;
        for (int h : cityLine) mx = Math.max(mx, h);
        int lo = 0, hi = Math.min(n, mx);
        while (lo < hi) { int mid = (lo + hi + 1) / 2; if (can(cityLine, mid)) lo = mid; else hi = mid - 1; }
        return lo * lo;
    }
    private boolean can(int[] a, int s) {
        int run = 0;
        for (int h : a) { if (h >= s) { if (++run >= s) return true; } else run = 0; }
        return false;
    }
}

int largestSquareCity(vector<int>& cityLine) {
 int n = cityLine.size(), mx = 0;
 for (int h : cityLine) mx = max(mx, h);
 auto can = [&](int s) {
 int run = 0;
 for (int h : cityLine) { if (h >= s) { if (++run >= s) return true; } else run = 0; }
 return false;
 };
 int lo = 0, hi = min(n, mx);
 while (lo < hi) { int mid = (lo + hi + 1) / 2; if (can(mid)) lo = mid; else hi = mid - 1; }
 return lo * lo;
}

def solution(segments, bytes_seq):
    n_seg = len(segments)
    covers = [set() for _ in range(n_seg)]
    complete = 0
    out = []
    for b in bytes_seq:
        for i in range(n_seg):
            s, l = segments[i]
            if s <= b < s + l and b not in covers[i]:
                covers[i].add(b)
                if len(covers[i]) == l:
                    complete += 1
        out.append(complete)
    return out

class Solution {
    public int[] fileTransfer(int[][] segments, int[] bytesSeq) {
        int n = segments.length;
        Set<Integer>[] covers = new HashSet[n];
        for (int i = 0; i < n; i++) covers[i] = new HashSet<>();
        int complete = 0;
        int[] out = new int[bytesSeq.length];
        for (int bi = 0; bi < bytesSeq.length; bi++) {
            int b = bytesSeq[bi];
            for (int i = 0; i < n; i++) {
                int s = segments[i][0], l = segments[i][1];
                if (s <= b && b < s + l && covers[i].add(b))
                    if (covers[i].size() == l) complete++;
            }
            out[bi] = complete;
        }
        return out;
    }
}

vector<int> fileTransfer(vector<vector<int>>& segments, vector<int>& bytesSeq) {
 int n = segments.size();
 vector<set<int>> covers(n);
 int complete = 0;
 vector<int> out;
 for (int b : bytesSeq) {
 for (int i = 0; i < n; ++i) {
 int s = segments[i][0], l = segments[i][1];
 if (s <= b && b < s + l && !covers[i].count(b)) {
 covers[i].insert(b);
 if ((int)covers[i].size() == l) ++complete;
 }
 }
 out.push_back(complete);
 }
 return out;
}

def solution(titles):
    n = len(titles)
    cnt = 0
    for i in range(n):
        for j in range(n):
            if i != j and titles[j].startswith(titles[i]):
                cnt += 1
    return cnt

class Solution {
    public int bookPrefixPairs(String[] titles) {
        int n = titles.length, cnt = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
            if (i != j && titles[j].startsWith(titles[i])) cnt++;
        return cnt;
    }
}

int bookPrefixPairs(vector<string>& titles) {
 int n = titles.size(), cnt = 0;
 for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
 if (i == j) continue;
 if (titles[j].size() >= titles[i].size() && titles[j].compare(0, titles[i].size(), titles[i]) == 0) ++cnt;
 }
 return cnt;
}

class Solution {
    public long stockTradeAlgo(int[] prices, int[] algo, int k) {
        int n = prices.length;
        long base = 0;
        for (int i = 0; i < n; i++) base += algo[i] == 1 ? prices[i] : -prices[i];
        int[] gain = new int[n];
        for (int i = 0; i < n; i++) gain[i] = prices[i] * (1 - algo[i]) * 2;
        long window = 0;
        for (int i = 0; i < k; i++) window += gain[i];
        long best = window;
        for (int i = k; i < n; i++) { window += gain[i] - gain[i - k]; best = Math.max(best, window); }
        return base + best;
    }
}

long long stockTradeAlgo(vector<int>& prices, vector<int>& algo, int k) {
 int n = prices.size();
 long long base = 0;
 for (int i = 0; i < n; ++i) base += algo[i] == 1 ? prices[i] : -prices[i];
 vector<int> gain(n);
 for (int i = 0; i < n; ++i) gain[i] = prices[i] * (1 - algo[i]) * 2;
 long long window = 0;
 for (int i = 0; i < k; ++i) window += gain[i];
 long long best = window;
 for (int i = k; i < n; ++i) { window += gain[i] - gain[i - k]; best = max(best, window); }
 return base + best;
}

class Solution {
    public int labyrinthRD(int n, int m, int[][] obstacles, int[][][] teleports) {
        Set<Long> obs = new HashSet<>();
        for (int[] o : obstacles) obs.add((long) o[0] * 100000 + o[1]);
        Map<Long, long[]> tele = new HashMap<>();
        for (int[][] tp : teleports) tele.put((long) tp[0][0] * 100000 + tp[0][1], new long[]{tp[1][0], tp[1][1]});
        Set<Long> visited = new HashSet<>();
        long cur = 0;
        int cnt = 0;
        long goal = (long)(n - 1) * 100000 + (m - 1);
        while (true) {
            if (!visited.add(cur)) return -2;
            cnt++;
            if (tele.containsKey(cur)) {
                long[] e = tele.get(cur);
                cur = e[0] * 100000 + e[1];
                if (!visited.add(cur)) return -2;
                cnt++;
            }
            if (cur == goal) return cnt;
            int r = (int)(cur / 100000), c = (int)(cur % 100000);
            if (c + 1 < m && !obs.contains((long) r * 100000 + (c + 1))) cur = (long) r * 100000 + (c + 1);
            else if (r + 1 < n && !obs.contains((long)(r + 1) * 100000 + c)) cur = (long)(r + 1) * 100000 + c;
            else return -1;
        }
    }
}

int labyrinthRD(int n, int m, vector<vector<int>>& obstacles, vector<vector<vector<int>>>& teleports) {
 set<pair<int,int>> obs;
 for (auto& o : obstacles) obs.insert({o[0], o[1]});
 map<pair<int,int>, pair<int,int>> tele;
 for (auto& tp : teleports) tele[{tp[0][0], tp[0][1]}] = {tp[1][0], tp[1][1]};
 pair<int,int> goal = {n - 1, m - 1};
 set<pair<int,int>> visited;
 pair<int,int> cur = {0, 0};
 int cnt = 0;
 while (true) {
 if (visited.count(cur)) return -2;
 visited.insert(cur); ++cnt;
 if (tele.count(cur)) {
 cur = tele[cur];
 if (visited.count(cur)) return -2;
 visited.insert(cur); ++cnt;
 }
 if (cur == goal) return cnt;
 auto [r, c] = cur;
 if (c + 1 < m && !obs.count({r, c + 1})) cur = {r, c + 1};
 else if (r + 1 < n && !obs.count({r + 1, c})) cur = {r + 1, c};
 else return -1;
 }
}

def solution(ingredients, recipes):
    ing_set = set(ingredients)
    max_len = max(len(s) for s in ingredients)
    out = []
    for r in recipes:
        n = len(r)
        f = [False] * (n + 1)
        f[0] = True
        for i in range(1, n + 1):
            for j in range(max(0, i - max_len), i):
                if f[j] and r[j:i] in ing_set:
                    f[i] = True; break
        out.append(f[n])
    return out

class Solution {
    public boolean[] recipePrep(String[] ingredients, String[] recipes) {
        Set<String> ing = new HashSet<>(Arrays.asList(ingredients));
        int maxLen = 0; for (String s : ingredients) maxLen = Math.max(maxLen, s.length());
        boolean[] out = new boolean[recipes.length];
        for (int ri = 0; ri < recipes.length; ri++) {
            String r = recipes[ri]; int n = r.length();
            boolean[] f = new boolean[n + 1];
            f[0] = true;
            for (int i = 1; i <= n; i++)
                for (int j = Math.max(0, i - maxLen); j < i; j++)
                    if (f[j] && ing.contains(r.substring(j, i))) { f[i] = true; break; }
            out[ri] = f[n];
        }
        return out;
    }
}

vector<bool> recipePrep(vector<string>& ingredients, vector<string>& recipes) {
 unordered_set<string> ing(ingredients.begin(), ingredients.end());
 int maxLen = 0; for (auto& s : ingredients) maxLen = max(maxLen, (int)s.size());
 vector<bool> out;
 for (auto& r : recipes) {
 int n = r.size();
 vector<bool> f(n + 1, false);
 f[0] = true;
 for (int i = 1; i <= n; ++i)
 for (int j = max(0, i - maxLen); j < i; ++j)
 if (f[j] && ing.count(r.substr(j, i - j))) { f[i] = true; break; }
 out.push_back(f[n]);
 }
 return out;
}

from typing import List

def solveOneCountEvenDigitNumbers(input: str) -> List[str]:
    nums = input.split()
    cnt = 0
    for s in nums:
        # 处理负号
        if s.startswith('-'):
            s = s[1:]
        if len(s) % 2 == 0:
            cnt += 1
    return [str(cnt)]

class Solution {
    String[] solveOneCountEvenDigitNumbers(String input) {
        String[] tokens = input.trim().split("\\s+");
        int cnt = 0;
        for (String s : tokens) {
            if (s.startsWith("-")) s = s.substring(1);
            if (s.length() % 2 == 0) cnt++;
        }
