def solveOneCyclicShiftStrictlyDescending(input: str) -> str:
    lines = input.strip().split('\n')
    n = int(lines[0])
    nums = list(map(int, lines[1].split()))
    t = int(lines[2])
    rotated = [nums[(i - t) % n] for i in range(n)]
    for i in range(n - 1):
        if not (rotated[i] > rotated[i + 1]):
            return "false"
    return "true"

class Solution {
