def solveOneDynamicWallRangeQuery(input: str) -> List[str]:
    lines = input.strip().split('\n')
    n = int(lines[0])
    walls = SortedList()
    out = []
    # lines[1] 可能是操作数量；为兼容多种格式，跳过它若是单个整数
    start = 1
    if lines[1].strip().isdigit():
        start = 2
    for i in range(start, len(lines)):
        parts = lines[i].split()
        if not parts:
            continue
        if parts[0] == 'build':
            idx = int(parts[1])
            if idx not in walls:
                walls.add(idx)
        elif parts[0] == 'query':
            l, r = int(parts[1]), int(parts[2])
            pos = walls.bisect_left(l)
            if pos < len(walls) and walls[pos] <= r:
                out.append('1')
            else:
                out.append('0')
    return out

import java.util.*;

class Solution {
    String[] solveOneDynamicWallRangeQuery(String input) {
        String[] lines = input.trim().split("\n");
        TreeSet<Integer> walls = new TreeSet<>();
        List<String> out = new ArrayList<>();
        int start = 1;
        if (lines.length > 1 && lines[1].trim().matches("\\d+")) start = 2;
        for (int i = start; i < lines.length; i++) {
            String[] p = lines[i].trim().split("\\s+");
            if (p.length == 0 || p[0].isEmpty()) continue;
            if (p[0].equals("build")) {
                walls.add(Integer.parseInt(p[1]));
            } else if (p[0].equals("query")) {
                int l = Integer.parseInt(p[1]), r = Integer.parseInt(p[2]);
                Integer c = walls.ceiling(l);
                out.add(c != null && c <= r ? "1" : "0");
            }
        }
        return out.toArray(new String[0]);
    }
}

class Solution {
public:
    vector<string> solveOneDynamicWallRangeQuery(string input) {
        vector<string> lines;
        stringstream ss(input);
        string ln;
        while (getline(ss, ln)) lines.push_back(ln);
        set<int> walls;
        vector<string> out;
        int start = 1;
        if (lines.size() > 1) {
            bool isNum = !lines[1].empty();
            for (char c : lines[1]) if (!isdigit(c) && !isspace(c)) { isNum = false; break; }
            if (isNum) start = 2;
        }
        for (size_t i = start; i < lines.size(); i++) {
            stringstream ls(lines[i]);
            string op;
            if (!(ls >> op)) continue;
            if (op == "build") {
                int idx; ls >> idx;
                walls.insert(idx);
            } else if (op == "query") {
                int l, r; ls >> l >> r;
                auto it = walls.lower_bound(l);
                out.push_back((it != walls.end() && *it <= r) ? "1" : "0");
            }
        }
        return out;
    }
};

