import java.util.*;

class Solution {
    int[] getFunctionExecutionTime(int n, String[] logs) {
        int[] res = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        int prev = 0;
        for (String log : logs) {
            String[] p = log.split(":");
            int fid = Integer.parseInt(p[0]);
            int ts = Integer.parseInt(p[2]);
            if (p[1].equals("start")) {
                if (!stack.isEmpty()) res[stack.peek()] += ts - prev;
                stack.push(fid);
                prev = ts;
            } else {
                res[stack.pop()] += ts - prev + 1;
                prev = ts + 1;
            }
        }
        return res;
    }
}

class Solution {
public:
    vector<int> getFunctionExecutionTime(int n, vector<string>& logs) {
        vector<int> res(n, 0);
        stack<int> st;
        int prev = 0;
        for (auto& log : logs) {
            size_t c1 = log.find(':'), c2 = log.find(':', c1 + 1);
            int fid = stoi(log.substr(0, c1));
            string typ = log.substr(c1 + 1, c2 - c1 - 1);
            int ts = stoi(log.substr(c2 + 1));
            if (typ == "start") {
                if (!st.empty()) res[st.top()] += ts - prev;
                st.push(fid);
                prev = ts;
            } else {
                res[st.top()] += ts - prev + 1;
                st.pop();
                prev = ts + 1;
            }
        }
        return res;
    }
};

class Solution {
    int[][] rotateOverDiagonals(int[][] matrix, int turns) {
        int n = matrix.length;
        turns %= 4;
        for (int k = 0; k < turns; k++) {
            int[][] nm = new int[n][n];
            for (int i = 0; i < n; i++) nm[i] = matrix[i].clone();
            for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
                if (i == j || i + j == n - 1) continue;
                boolean upper = i < j && i + j < n - 1;
                boolean right = i < j && i + j > n - 1;
                boolean lower = i > j && i + j > n - 1;
                int si, sj;
                if (upper) { si = n - 1 - j; sj = i; }
                else if (right) { si = j; sj = n - 1 - i; }
                else if (lower) { si = n - 1 - j; sj = n - 1 - i; }
                else { si = j; sj = n - 1 - i; }
                nm[i][j] = matrix[si][sj];
            }
            matrix = nm;
        }
        return matrix;
    }
}

