from collections import Counter
from typing import List

def sumDigitsUntilOne(numbers: List[str]) -> int:
    def root(s: str) -> int:
        n = int(s)
        if n == 0:
            return 0
        return 1 + (n - 1) % 9
    roots = [root(s) for s in numbers]
    cnt = Counter(roots)
    # 取频次最高，多个同频取最大
    max_freq = max(cnt.values())
    return max(k for k, v in cnt.items() if v == max_freq)

import java.util.*;

class Solution {
    int sumDigitsUntilOne(List<String> numbers) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (String s : numbers) {
            long n = Long.parseLong(s);
            int r = (n == 0) ? 0 : (int) (1 + (n - 1) % 9);
            cnt.merge(r, 1, Integer::sum);
        }
        int maxFreq = Collections.max(cnt.values());
        int best = Integer.MIN_VALUE;
        for (var e : cnt.entrySet()) {
            if (e.getValue() == maxFreq) best = Math.max(best, e.getKey());
        }
        return best;
    }
}

class Solution {
public:
    int sumDigitsUntilOne(vector<string>& numbers) {
        unordered_map<int, int> cnt;
        for (auto& s : numbers) {
            long long n = stoll(s);
            int r = (n == 0) ? 0 : (int) (1 + (n - 1) % 9);
            cnt[r]++;
        }
        int maxFreq = 0;
        for (auto& [k, v] : cnt) maxFreq = max(maxFreq, v);
        int best = INT_MIN;
        for (auto& [k, v] : cnt) if (v == maxFreq) best = max(best, k);
        return best;
    }
};

import java.math.BigInteger;

class Solution {
    int countOperations(int[] p) {
        int MOD = 1_000_000_007;
        int n = p.length;
        boolean[] visited = new boolean[n];
        BigInteger lcm = BigInteger.ONE;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int len = 0, j = i;
                while (!visited[j]) {
                    visited[j] = true;
                    j = p[j] - 1;
                    len++;
                }
                BigInteger L = BigInteger.valueOf(len);
                lcm = lcm.divide(lcm.gcd(L)).multiply(L);
            }
        }
        return lcm.mod(BigInteger.valueOf(MOD)).intValue();
    }
}

#include <numeric>

class Solution {
public:
    int countOperations(vector<int>& p) {
        const int MOD = 1'000'000'007;
        int n = p.size();
        vector<bool> visited(n, false);
        // 收集各循环长度并去重
        vector<int> cycles;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int len = 0, j = i;
                while (!visited[j]) {
                    visited[j] = true;
                    j = p[j] - 1;
                    len++;
                }
                cycles.push_back(len);
            }
        }
        // 用质因数分解求 LCM 模 MOD：对每个 cycle 分解质因数取每个素数最大幂
        unordered_map<int, int> primePow;
        for (int L : cycles) {
            int x = L;
            for (int d = 2; (long long) d * d <= x; d++) {
                if (x % d == 0) {
                    int cnt = 0;
                    while (x % d == 0) { x /= d; cnt++; }
                    primePow[d] = max(primePow[d], cnt);
                }
            }
            if (x > 1) primePow[x] = max(primePow[x], 1);
        }
        long long ans = 1;
        for (auto& [pr, e] : primePow) {
            for (int k = 0; k < e; k++) ans = ans * pr % MOD;
        }
        return (int) ans;
    }
};

from typing import List

def allocateWells(A: List[int], N: int) -> List[int]:
    n = len(A)
    lo, hi = max(A), sum(A)
    def feasible(limit: int):
        groups, cur = 1, 0
        for x in A:
            if cur + x > limit:
                groups += 1
                cur = x
                if groups > N:
                    return None
            else:
                cur += x
        return True
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    # 用 lo 重新构造分段
    limit = lo
    res = []
    cur = 0
    for x in A:
        if cur + x > limit:
            res.append(cur)
            cur = x
        else:
            cur += x
    res.append(cur)
    while len(res) < N:
        res.append(0)
    return res

import java.util.*;

class Solution {
    int[] allocateWells(int[] A, int N) {
        int n = A.length;
        int lo = 0, hi = 0;
        for (int x : A) { lo = Math.max(lo, x); hi += x; }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (feasible(A, N, mid)) hi = mid;
            else lo = mid + 1;
        }
        List<Integer> res = new ArrayList<>();
        int cur = 0;
        for (int x : A) {
            if (cur + x > lo) { res.add(cur); cur = x; }
            else cur += x;
        }
        res.add(cur);
        while (res.size() < N) res.add(0);
        int[] out = new int[res.size()];
        for (int i = 0; i < res.size(); i++) out[i] = res.get(i);
        return out;
    }
    boolean feasible(int[] A, int N, int limit) {
        int groups = 1, cur = 0;
        for (int x : A) {
            if (cur + x > limit) { groups++; cur = x; if (groups > N) return false; }
            else cur += x;
        }
        return true;
    }
}

