                int nx = x + dr[0], ny = y + dr[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    int nd = min(d, dist[nx][ny]);
                    if (nd > best[nx][ny]) {
                        best[nx][ny] = nd;
                        pq.push({nd, nx, ny});
                    }
                }
            }
        }
        return best[ex][ey];
    }
};

from typing import List

def getMinLength(a: List[int], k: int) -> int:
    n = len(a)
    if n == 0:
        return 0
    res = 0
    cur = a[0]
    for i in range(1, n):
        # 尝试把 a[i] 合并进 cur
        if cur * a[i] <= k:
            cur *= a[i]
        else:
            res += 1       # cur 成为一个最终段
            cur = a[i]     # 开新段
    res += 1               # 最后那段也要算
    return res

class Solution {
    int getMinLength(int[] a, int k) {
        int n = a.length;
        if (n == 0) return 0;
        int res = 0;
        long cur = a[0];
        for (int i = 1; i < n; i++) {
            if (cur * a[i] <= k) {
                cur *= a[i];
            } else {
                res++;
                cur = a[i];
            }
        }
        return res + 1;
    }
}

