def getSubstring(input_str: str, k: int) -> str:
    n = len(input_str)
    # Step 1: 最短窗口长度
    # 滑动窗口找含 k 个 1 的最短子串
    left = 0
    ones = 0
    min_len = n + 1
    for right in range(n):
        if input_str[right] == '1':
            ones += 1
        while ones > k:
            if input_str[left] == '1':
                ones -= 1
            left += 1
        if ones == k:
            # 收缩前导 0
            while left <= right and input_str[left] == '0' and ones == k and (left + 1 <= right and input_str[left] != '1' or True):
                # 实际上我们要收缩，不影响 ones（去掉的是 0）
                if input_str[left] == '0':
                    left += 1
                else:
                    break
            min_len = min(min_len, right - left + 1)
    # Step 2: 在所有恰好 k 个 1 且长度为 min_len 的子串里取字典序最小
    best = None
    for i in range(n - min_len + 1):
        sub = input_str[i:i + min_len]
        if sub.count('1') == k:
            if best is None or sub < best:
                best = sub
    return best

class Solution {
    String getSubstring(String input_str, int k) {
        int n = input_str.length();
        int left = 0, ones = 0, minLen = n + 1;
        for (int right = 0; right < n; right++) {
            if (input_str.charAt(right) == '1') ones++;
            while (ones > k) {
                if (input_str.charAt(left) == '1') ones--;
                left++;
            }
            if (ones == k) {
                int l = left;
                while (l < right && input_str.charAt(l) == '0') l++;
                minLen = Math.min(minLen, right - l + 1);
            }
        }
        String best = null;
        for (int i = 0; i + minLen <= n; i++) {
            String sub = input_str.substring(i, i + minLen);
            int cnt = 0;
            for (int j = 0; j < sub.length(); j++) if (sub.charAt(j) == '1') cnt++;
            if (cnt == k && (best == null || sub.compareTo(best) < 0)) {
                best = sub;
            }
        }
        return best;
    }
}

