class Solution {
    int sumOfCompressedNumbers(int[] a) {
        final int MOD = 1_000_000_007;
        int n = a.length;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long prod = 1;
            int curLen = 1;
            for (int j = i; j < n; j++) {
                if (j > i && a[j] == a[j - 1]) {
                    prod = prod * (curLen + 1) / curLen;
                    curLen++;
                } else {
                    curLen = 1;
                }
                ans = (ans + (prod - 1 + MOD) % MOD) % MOD;
            }
        }
        return (int) ans;
    }
}

