class Solution {
    public int[] arrangeFlowerSticks(int[] flowerStick, int K) {
        int[] a = Arrays.copyOfRange(flowerStick, 0, K);
        int[] b = Arrays.copyOfRange(flowerStick, K, flowerStick.length);
