def find_largest_house_area(grid: List[List[int]]) -> int:
    if not grid:
        return 0
    n, m = len(grid), len(grid[0])
    seen = [[False] * m for _ in range(n)]
    best = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not seen[i][j]:
                size = 0
                q = deque([(i, j)])
                seen[i][j] = True
                while q:
                    r, c = q.popleft()
                    size += 1
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 1 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            q.append((nr, nc))
                best = max(best, size)
    return best

import java.util.*;

class Solution {
    public int findLargestHouseArea(int[][] grid) {
        int n = grid.length, m = grid[0].length;
        boolean[][] seen = new boolean[n][m];
        int best = 0;
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            if (grid[i][j] == 1 && !seen[i][j]) {
                int size = 0;
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[]{i, j}); seen[i][j] = true;
                while (!q.isEmpty()) {
                    int[] cur = q.poll(); size++;
                    for (int k = 0; k < 4; k++) {
                        int nr = cur[0] + dr[k], nc = cur[1] + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 1 && !seen[nr][nc]) {
                            seen[nr][nc] = true; q.add(new int[]{nr, nc});
                        }
                    }
                }
                best = Math.max(best, size);
            }
        }
        return best;
    }
}

