from collections import Counter
from typing import List

def most_frequent_products(tag: List[List[int]], K: int) -> List[int]:
    cnt: Counter = Counter()
    for row in tag:
        for pid in set(row):
            cnt[pid] += 1
    eligible = {pid: c for pid, c in cnt.items() if c >= K}
    if not eligible:
        return []
    best = max(eligible.values())
    return sorted([pid for pid, c in eligible.items() if c == best])

import java.util.*;

class Solution {
    public int[] mostFrequentProducts(int[][] tag, int K) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int[] row : tag) {
            Set<Integer> distinct = new HashSet<>();
            for (int p : row) distinct.add(p);
            for (int p : distinct) cnt.merge(p, 1, Integer::sum);
        }
        int best = 0;
        for (var e : cnt.entrySet()) if (e.getValue() >= K) best = Math.max(best, e.getValue());
        if (best == 0) return new int[0];
        List<Integer> out = new ArrayList<>();
        for (var e : cnt.entrySet()) if (e.getValue() == best) out.add(e.getKey());
        Collections.sort(out);
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

