public:
    vector<int> mostFrequentProducts(vector<vector<int>>& tag, int K) {
        unordered_map<int, int> cnt;
        for (auto& row : tag) {
            unordered_set<int> distinct(row.begin(), row.end());
            for (int p : distinct) cnt[p]++;
        }
        int best = 0;
        for (auto& [k, v] : cnt) if (v >= K) best = max(best, v);
        if (best == 0) return {};
        vector<int> out;
        for (auto& [k, v] : cnt) if (v == best) out.push_back(k);
        sort(out.begin(), out.end());
        return out;
    }
};

class Solution {
