class Solution {
public:
    int n, m;
    unordered_set<long long> blocked;
    unordered_map<long long, long long> tele;
    long long goalKey;
    bool hasLoop;
    int best;

    long long key(int r, int c) { return (long long) r * m + c; }

    bool resolve(long long pos, unordered_set<long long>& visited, long long& out) {
        unordered_set<long long> local;
        long long cur = pos;
        while (tele.count(cur)) {
            if (local.count(cur)) { hasLoop = true; return false; }
            local.insert(cur);
            visited.insert(cur);
            cur = tele[cur];
        }
        visited.insert(cur);
        out = cur;
        return true;
    }

    void dfs(long long pos, unordered_set<long long> visited) {
        if (pos == goalKey) {
            best = max(best, (int) visited.size());
            return;
        }
        int r = (int)(pos / m), c = (int)(pos % m);
        int dirs[2][2] = {{1, 0}, {0, 1}};
        for (auto& d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
            long long nk = key(nr, nc);
            if (blocked.count(nk)) continue;
            auto nv = visited;
            long long out;
            if (!resolve(nk, nv, out)) continue;
            dfs(out, nv);
        }
    }

    int solution(int n_, int m_, vector<vector<int>>& obstacles, vector<vector<int>>& teleports) {
        n = n_; m = m_;
        for (auto& o : obstacles) blocked.insert(key(o[0], o[1]));
        for (auto& t : teleports) tele[key(t[0], t[1])] = key(t[2], t[3]);
        goalKey = key(n - 1, m - 1);
        hasLoop = false; best = -1;
        unordered_set<long long> init;
        long long start;
        if (resolve(key(0, 0), init, start)) dfs(start, init);
        if (best == -1) return hasLoop ? -2 : -1;
        return best;
    }
};

def solution(cityLine: list[int]) -> int:
    n = len(cityLine)
    def can(s: int) -> bool:
        run = 0
        for h in cityLine:
            if h >= s:
                run += 1
                if run >= s: return True
            else:
                run = 0
        return False
    lo, hi = 0, min(n, max(cityLine))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid): lo = mid
        else: hi = mid - 1
    return lo * lo

class Solution {
    static long solution(int[] cityLine) {
        int n = cityLine.length, mx = 0;
        for (int h : cityLine) mx = Math.max(mx, h);
        int lo = 0, hi = Math.min(n, mx);
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            int run = 0;
            boolean ok = false;
            for (int h : cityLine) {
                if (h >= mid) { run++; if (run >= mid) { ok = true; break; } }
                else run = 0;
            }
            if (ok) lo = mid; else hi = mid - 1;
        }
        return (long) lo * lo;
    }
}

