import heapq

def solution(balances, requests):
    n_acc = len(balances)
    bal = list(balances)
    cashback = []

    def flush(ts):
        while cashback and cashback[0][0] <= ts:
            rt, idx, amt = heapq.heappop(cashback)
            bal[idx] += amt

    for i, req in enumerate(requests, 1):
        parts = req.split()
        op, ts, hid, amt = parts[0], int(parts[1]), int(parts[2]), int(parts[3])
        flush(ts)
        if hid < 1 or hid > n_acc:
            return [-i]
        idx = hid - 1
        if op == "deposit":
            bal[idx] += amt
        elif op == "withdraw":
            if bal[idx] < amt: return [-i]
            bal[idx] -= amt
            cashback_amt = (amt * 2) // 100
            heapq.heappush(cashback, (ts + 86400, idx, cashback_amt))
        else:
            return [-i]
    return bal

import heapq

class Bank2:
    def __init__(self):
        self.accounts = {}
        self.scheduled = {}
        self.pay_counter = 0
        self.queue = []
        self.merged = {}

    def _resolve(self, aid):
        while aid in self.merged: aid = self.merged[aid]
        return aid

    def _flush_scheduled(self, ts):
        while self.queue and self.queue[0][0] <= ts:
            et, pid = heapq.heappop(self.queue)
            p = self.scheduled[pid]
            if p["status"] != "SCHEDULED": continue
            aid = self._resolve(p["account"])
            if aid not in self.accounts:
                p["status"] = "CANCELLED"; continue
            acc = self.accounts[aid]
            if acc["balance"] < p["amount"]:
                p["status"] = "FAILED"; continue
            acc["balance"] -= p["amount"]
            acc["outgoing"] += p["amount"]
            acc["history"].append((et, acc["balance"]))
            p["status"] = "EXECUTED"

    def schedulePayment(self, ts, aid, amt, delay):
        self._flush_scheduled(ts)
        aid = self._resolve(aid)
        if aid not in self.accounts: return None
        self.pay_counter += 1
        pid = f"payment{self.pay_counter}"
        exec_ts = ts + delay
        self.scheduled[pid] = {"account": aid, "amount": amt, "exec_ts": exec_ts, "status": "SCHEDULED"}
        heapq.heappush(self.queue, (exec_ts, pid))
        return pid

    def cancelScheduledPayment(self, ts, pid):
        self._flush_scheduled(ts)
        if pid not in self.scheduled: return False
        if self.scheduled[pid]["status"] != "SCHEDULED": return False
        self.scheduled[pid]["status"] = "CANCELLED"
        return True

import java.util.*;

class Solution {
    int[] acceptOrDeclineQueries(String[] timestamps, String[] ipAddresses, int limit, int timeWindow) {
        Map<String, TreeMap<Long, Integer>> accepted = new HashMap<>();
        int[] res = new int[timestamps.length];
        for (int i = 0; i < timestamps.length; i++) {
            long ts = Long.parseLong(timestamps[i]);
            String ip = ipAddresses[i];
            TreeMap<Long, Integer> tm = accepted.computeIfAbsent(ip, k -> new TreeMap<>());
            long lo = ts - timeWindow;
            int count = 0;
            for (Long t : tm.tailMap(lo).keySet()) count += tm.get(t);
            if (count < limit) {
                tm.merge(ts, 1, Integer::sum);
                res[i] = 1;
            } else res[i] = 0;
        }
        return res;
    }
}

class Solution {
public:
    vector<int> acceptOrDeclineQueries(vector<string>& timestamps, vector<string>& ipAddresses,
                                        int limit, int timeWindow) {
        unordered_map<string, vector<long long>> accepted;
        vector<int> res(timestamps.size());
        for (size_t i = 0; i < timestamps.size(); ++i) {
            long long ts = stoll(timestamps[i]);
            auto& lst = accepted[ipAddresses[i]];
            long long lo = ts - timeWindow;
            auto it = lower_bound(lst.begin(), lst.end(), lo);
            int count = lst.end() - it;
            if (count < limit) {
                lst.insert(upper_bound(lst.begin(), lst.end(), ts), ts);
                res[i] = 1;
            } else res[i] = 0;
        }
        return res;
    }
};

def getMaximumJobs(n: int, m: int, k: int) -> int:
    # left side has (k-1) processors with values x-1, x-2, ..., bottomed at 1
    # right side has (n-k) processors similarly
    def need(x: int) -> int:
        def side(cnt: int, peak: int) -> int:
            # cnt processors, values peak-1, peak-2, ..., flattened at 1
            if cnt == 0:
                return 0
            full = min(cnt, peak - 1)
            # sum of (peak-1) + (peak-2) + ... down to (peak-full)
            s = (peak - 1 + peak - full) * full // 2
            s += max(0, cnt - full)
            return s
        return x + side(k - 1, x) + side(n - k, x)

    lo, hi, ans = 1, m, 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if need(mid) <= m:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

class Solution {
    int getMaximumJobs(int n, int m, int k) {
        long lo = 1, hi = m, ans = 1;
        while (lo <= hi) {
            long mid = (lo + hi) >>> 1;
            if (need(mid, n, k) <= m) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return (int) ans;
    }
    private long need(long x, int n, int k) {
        return x + side(k - 1, x) + side(n - k, x);
    }
    private long side(int cnt, long peak) {
        if (cnt == 0) return 0;
        long full = Math.min(cnt, peak - 1);
        long s = (peak - 1 + peak - full) * full / 2;
        s += Math.max(0, cnt - full);
        return s;
    }
}

