def filterOddsAndReverseEvens(nums: List[int]) -> List[int]:
    return [x for x in nums if x % 2 == 0][::-1]

class Solution {
    int[] filterOddsAndReverseEvens(int[] nums) {
        List<Integer> even = new ArrayList<>();
        for (int x : nums) if (x % 2 == 0) even.add(x);
