def findWrongDigitIndex(num1: int, num2: int, givenSum: int) -> int:
    correct = num1 + num2
    idx = 0
    while correct > 0 or givenSum > 0:
        if correct % 10 != givenSum % 10:
            return idx
        correct //= 10; givenSum //= 10; idx += 1
    return -1

class Solution {
    int findWrongDigitIndex(long num1, long num2, long givenSum) {
        long correct = num1 + num2;
        int idx = 0;
        while (correct > 0 || givenSum > 0) {
            if (correct % 10 != givenSum % 10) return idx;
            correct /= 10; givenSum /= 10; idx++;
        }
        return -1;
    }
}

class Solution {
public:
    int findWrongDigitIndex(long long num1, long long num2, long long givenSum) {
        long long correct = num1 + num2;
        int idx = 0;
        while (correct > 0 || givenSum > 0) {
            if (correct % 10 != givenSum % 10) return idx;
            correct /= 10; givenSum /= 10; idx++;
        }
        return -1;
    }
};

def countGoodSubsequences(word: str) -> int:
    MOD = 10**9 + 7
    n = len(word)
    cnt = [0] * 26
    for ch in word:
        cnt[ord(ch) - 97] += 1
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD
    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD
    ans = 0
    max_cnt = max(cnt)
    for k in range(1, max_cnt + 1):
        prod = 1
        for c in cnt:
            if c >= k:
                prod = prod * (comb(c, k) + 1) % MOD
        # prod 包含"每种字符可选 k 个或不选"，减去全不选的 1 种
        ans = (ans + prod - 1) % MOD
    return ans

class Solution {
    static final int MOD = 1_000_000_007;
    long[] fact, invFact;
    int countGoodSubsequences(String word) {
        int n = word.length();
        int[] cnt = new int[26];
        for (char ch : word.toCharArray()) cnt[ch - 'a']++;
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        int maxCnt = 0;
        for (int c : cnt) maxCnt = Math.max(maxCnt, c);
        long ans = 0;
        for (int k = 1; k <= maxCnt; k++) {
            long prod = 1;
            for (int c : cnt) {
                if (c >= k) prod = prod * (comb(c, k) + 1) % MOD;
            }
            ans = (ans + prod - 1 + MOD) % MOD;
        }
        return (int) ans;
    }
    long comb(int a, int b) {
        if (b < 0 || b > a) return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    }
    long modPow(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
}

class Solution {
public:
    static const int MOD = 1'000'000'007;
    vector<long long> fact, invFact;
    long long modPow(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    long long comb(int a, int b) {
        if (b < 0 || b > a) return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    }
    int countGoodSubsequences(string word) {
        int n = word.size();
        vector<int> cnt(26, 0);
        for (char ch : word) cnt[ch - 'a']++;
        fact.assign(n + 1, 1);
        invFact.assign(n + 1, 1);
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        int maxCnt = *max_element(cnt.begin(), cnt.end());
        long long ans = 0;
        for (int k = 1; k <= maxCnt; k++) {
            long long prod = 1;
            for (int c : cnt) if (c >= k) prod = prod * (comb(c, k) + 1) % MOD;
            ans = (ans + prod - 1 + MOD) % MOD;
        }
        return (int) ans;
    }
};

import java.util.*;

class Solution {
    List<String> res;
    char[] chars;
    int[] qIdx;
    int dayHours;
    List<String> findSchedules(int work_hours, int day_hours, String pattern) {
        chars = pattern.toCharArray();
        dayHours = day_hours;
        List<Integer> qs = new ArrayList<>();
        int fixed = 0;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '?') qs.add(i);
            else fixed += chars[i] - '0';
        }
        qIdx = qs.stream().mapToInt(Integer::intValue).toArray();
        res = new ArrayList<>();
        dfs(0, work_hours - fixed);
        return res;
    }
    void dfs(int i, int remain) {
        if (i == qIdx.length) {
            if (remain == 0) res.add(new String(chars));
            return;
        }
        int left = qIdx.length - i;
        if (remain < 0 || remain > (long) left * dayHours) return;
        for (int d = 0; d <= dayHours; d++) {
            chars[qIdx[i]] = (char) ('0' + d);
            dfs(i + 1, remain - d);
        }
        chars[qIdx[i]] = '?';
    }
}

class Solution {
public:
    vector<string> res;
    string chars;
    vector<int> qIdx;
    int dayHours;
    vector<string> findSchedules(int work_hours, int day_hours, string pattern) {
        chars = pattern;
        dayHours = day_hours;
        int fixed = 0;
        for (int i = 0; i < (int) chars.size(); i++) {
            if (chars[i] == '?') qIdx.push_back(i);
            else fixed += chars[i] - '0';
        }
        dfs(0, work_hours - fixed);
        return res;
    }
    void dfs(int i, int remain) {
        if (i == (int) qIdx.size()) {
            if (remain == 0) res.push_back(chars);
            return;
        }
        int left = (int) qIdx.size() - i;
        if (remain < 0 || remain > left * dayHours) return;
        for (int d = 0; d <= dayHours; d++) {
            chars[qIdx[i]] = (char) ('0' + d);
            dfs(i + 1, remain - d);
        }
        chars[qIdx[i]] = '?';
    }
};

