def minCostConnectPoints(points: List[List[int]]) -> int:
    n = len(points)
    if n <= 1:
        return 0
    INF = float('inf')
    min_dist = [INF] * n
    min_dist[0] = 0
    in_mst = [False] * n
    total = 0
    for _ in range(n):
        u = -1
        best = INF
        for v in range(n):
            if not in_mst[v] and min_dist[v] < best:
                best = min_dist[v]
                u = v
        in_mst[u] = True
        total += best
        xu, yu = points[u]
        for v in range(n):
            if not in_mst[v]:
                d = abs(xu - points[v][0]) + abs(yu - points[v][1])
                if d < min_dist[v]:
                    min_dist[v] = d
    return total

class Solution {
    int minCostConnectPoints(int[][] points) {
        int n = points.length;
        if (n <= 1) return 0;
        int[] minDist = new int[n];
        Arrays.fill(minDist, Integer.MAX_VALUE);
        minDist[0] = 0;
        boolean[] inMst = new boolean[n];
        int total = 0;
        for (int k = 0; k < n; k++) {
            int u = -1, best = Integer.MAX_VALUE;
            for (int v = 0; v < n; v++) {
                if (!inMst[v] && minDist[v] < best) {
                    best = minDist[v];
                    u = v;
                }
            }
            inMst[u] = true;
            total += best;
            for (int v = 0; v < n; v++) {
                if (!inMst[v]) {
                    int d = Math.abs(points[u][0] - points[v][0]) + Math.abs(points[u][1] - points[v][1]);
                    if (d < minDist[v]) minDist[v] = d;
                }
            }
        }
        return total;
    }
}

