class Solution {
    int minimumOperationsToConvertArray(int[] arr) {
        int n = arr.length;
        int best = Integer.MAX_VALUE;
        for (int k = 0; k < n; k++) {
            boolean[] visited = new boolean[n];
            int cycles = 0;
            for (int i = 0; i < n; i++) {
                if (!visited[i]) {
                    cycles++;
                    int j = i;
                    while (!visited[j]) {
                        visited[j] = true;
                        int val = arr[(j + k) % n];
                        j = val - 1;
                    }
                }
            }
            best = Math.min(best, k + (n - cycles));
        }
        return best;
    }
}

