class Solution {
    String canRearrangeString(String s) {
        int n = s.length();
        int[] cnt = new int[128];
        for (char c : s.toCharArray()) cnt[c]++;
        int maxFreq = 0;
        for (int c : cnt) maxFreq = Math.max(maxFreq, c);
        boolean alreadyOk = true;
        for (int i = 0; i + 1 < n; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) { alreadyOk = false; break; }
        }
        if (alreadyOk) return "POSSIBLE";
        return maxFreq <= (n + 1) / 2 ? "POSSIBLE" : "NOT POSSIBLE";
    }
}

