        for (char c : s) cnt[c]++;
        int maxFreq = *max_element(cnt.begin(), cnt.end());
        bool alreadyOk = true;
        for (int i = 0; i + 1 < n; i++) {
            if (s[i] == s[i + 1]) { alreadyOk = false; break; }
        }
        if (alreadyOk) return "POSSIBLE";
        return maxFreq <= (n + 1) / 2 ? "POSSIBLE" : "NOT POSSIBLE";
    }
