def numPlayers(k: int, scores: List[int]) -> int:
    n = len(scores)
    sorted_scores = sorted(scores, reverse=True)
    ans = 0
    rank = 1
    for i in range(n):
        if i > 0 and sorted_scores[i] != sorted_scores[i - 1]:
            rank = i + 1
        if rank <= k and sorted_scores[i] > 0:
            ans += 1
    return ans

import java.util.*;

class Solution {
    int numPlayers(int k, int[] scores) {
        Integer[] s = new Integer[scores.length];
        for (int i = 0; i < scores.length; i++) s[i] = scores[i];
        Arrays.sort(s, Collections.reverseOrder());
        int ans = 0, rank = 1;
        for (int i = 0; i < s.length; i++) {
            if (i > 0 && !s[i].equals(s[i - 1])) rank = i + 1;
            if (rank <= k && s[i] > 0) ans++;
        }
        return ans;
    }
}

class Solution {
public:
    int numPlayers(int k, vector<int>& scores) {
        vector<int> s = scores;
        sort(s.begin(), s.end(), greater<int>());
        int ans = 0, rank = 1;
        for (int i = 0; i < (int) s.size(); i++) {
            if (i > 0 && s[i] != s[i - 1]) rank = i + 1;
            if (rank <= k && s[i] > 0) ans++;
        }
        return ans;
    }
};

def getSubstringCount(s: str) -> int:
    groups = []
    cnt = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]: cnt += 1
        else: groups.append(cnt); cnt = 1
    groups.append(cnt)
    return sum(min(groups[i], groups[i + 1]) for i in range(len(groups) - 1))

class Solution {
    static long getSubstringCount(String s) {
        long ans = 0, prev = 0, cur = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) cur++;
            else { ans += Math.min(prev, cur); prev = cur; cur = 1; }
        }
        return ans + Math.min(prev, cur);
    }
}

