def compressWord(word: str, k: int) -> str:
    stack = []
    for c in word:
        if stack and stack[-1][0] == c:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([c, 1])
    return ''.join(c * cnt for c, cnt in stack)

import java.util.*;

class Solution {
    static String compressWord(String word, int k) {
        Deque<int[]> stack = new ArrayDeque<>();
        for (char c : word.toCharArray()) {
            if (!stack.isEmpty() && stack.peek()[0] == c) {
                stack.peek()[1]++;
                if (stack.peek()[1] == k) stack.pop();
            } else {
                stack.push(new int[]{c, 1});
            }
        }
        StringBuilder sb = new StringBuilder();
        Iterator<int[]> it = stack.descendingIterator();
        while (it.hasNext()) {
            int[] p = it.next();
            for (int i = 0; i < p[1]; i++) sb.append((char) p[0]);
        }
        return sb.toString();
    }
}

