def longestSubsequence(x: str, y: str) -> int:
    n, m = len(x), len(y)
    best = 0
    for s in range(m):
        i = k = 0
        while i < n and s + k < m:
            if x[i] == y[s + k]:
                k += 1
            i += 1
        best = max(best, k)
    return best

class Solution {
    static int longestSubsequence(String x, String y) {
        int n = x.length(), m = y.length(), best = 0;
        for (int s = 0; s < m; s++) {
            int i = 0, k = 0;
            while (i < n && s + k < m) {
                if (x.charAt(i) == y.charAt(s + k)) k++;
                i++;
            }
            best = Math.max(best, k);
        }
        return best;
    }
}

