class Solution {
    int antiAgingSerum(String sample, int[] tol) {
        int m = sample.length();
        int[] cnt = new int[26];
        int l = 0, best = 0;
        for (int r = 0; r < m; r++) {
            cnt[sample.charAt(r) - 'a']++;
            while (true) {
                int length = r - l + 1;
                int minTol = Integer.MAX_VALUE;
                for (int c = 0; c < 26; c++) {
                    if (cnt[c] > 0) minTol = Math.min(minTol, tol[c]);
                }
                if (length <= minTol) break;
                cnt[sample.charAt(l) - 'a']--;
                l++;
            }
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

class Solution {
public:
    int antiAgingSerum(string sample, vector<int>& tol) {
        int m = sample.size();
        vector<int> cnt(26, 0);
        int l = 0, best = 0;
        for (int r = 0; r < m; r++) {
            cnt[sample[r] - 'a']++;
            while (true) {
                int length = r - l + 1;
                int minTol = INT_MAX;
                for (int c = 0; c < 26; c++) {
                    if (cnt[c] > 0) minTol = min(minTol, tol[c]);
                }
                if (length <= minTol) break;
                cnt[sample[l] - 'a']--;
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};

from typing import List

def battleWithUpperMoon6(K: List[List[int]]) -> List[List[int]]:
    n, m = len(K), len(K[0])
    out = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            # 寻找祖先（包括自己）里 K 值最大的格子
            max_k = K[i][j]
            max_is_self = True
            # 祖先：(i', j') 使得 i' < i 且 |j - j'| ≤ i - i'，逐级向上
            for di in range(1, i + 1):
                ii = i - di
                for jj in range(max(0, j - di), min(m - 1, j + di) + 1):
                    if K[ii][jj] > max_k:
                        max_k = K[ii][jj]
                        max_is_self = False
            out[i][j] = 0 if max_is_self else 1
    return out

class Solution {
    int[][] battleWithUpperMoon6(int[][] K) {
        int n = K.length, m = K[0].length;
        int[][] out = new int[n][m];
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
            int maxK = K[i][j];
            boolean maxIsSelf = true;
            for (int di = 1; di <= i; di++) {
                int ii = i - di;
                for (int jj = Math.max(0, j - di); jj <= Math.min(m - 1, j + di); jj++) {
                    if (K[ii][jj] > maxK) {
                        maxK = K[ii][jj];
                        maxIsSelf = false;
                    }
                }
            }
            out[i][j] = maxIsSelf ? 0 : 1;
        }
        return out;
    }
}

