    }
};

from typing import List

def bitonicPartitioning(arr: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(arr)
    # prefix_sum
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + arr[i]
    # inc[i] = 把 arr[0..i-1] 划分成严格递增平均值序列的方案数
    # dec[i] = 从 arr[i..n-1] 划分成严格递减平均值序列的方案数
    # 总数 = Σ_k inc_with_last_avg(k) · dec_with_first_avg_lower_than_k(k)
    # 严格简化：考虑 inc[i][prev] = 用 arr[0..i-1] 结束，最后段平均值 = prev 的方案数
    # n ≤ 5000，state 太多。用 O(n²)：
    inc = [[0] * n for _ in range(n + 1)]  # inc[i][j] = 前 i 个划分，最后一段是 arr[j..i-1]
    dec = [[0] * n for _ in range(n + 1)]
    # inc[i][j]: 1 if 段 arr[j..i-1] 是新加段，且其平均值 > 前一段平均值（或首段）
    for i in range(1, n + 1):
        for j in range(i):
            avg_last = (P[i] - P[j]) / max(1, i - j)
            if j == 0:
                inc[i][j] = 1
            else:
                # 前面段必须以 arr[?..j-1] 结尾，平均值 < avg_last
                total = 0
                for k in range(j):
                    avg_prev = (P[j] - P[k]) / max(1, j - k)
                    if avg_prev < avg_last:
                        total = (total + inc[j][k]) % MOD
                inc[i][j] = total
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            avg_first = (P[j] - P[i]) / max(1, j - i)
            if j == n:
                dec[i][j] = 1
            else:
                total = 0
                for k in range(j + 1, n + 1):
                    avg_next = (P[k] - P[j]) / max(1, k - j)
                    if avg_next < avg_first:
                        total = (total + dec[j][k]) % MOD
                dec[i][j] = total
    # 总数：枚举峰段 arr[p..q-1] (p < q ≤ n)，要求其平均最大
    ans = 0
    for p in range(n):
        for q in range(p + 1, n + 1):
            avg_peak = (P[q] - P[p]) / max(1, q - p)
            # 左段 inc[p+1][...]：以 arr[?..p-1] 结尾 avg < avg_peak
            left_cnt = 1 if p == 0 else 0
            for k in range(p):
                avg_prev = (P[p] - P[k]) / max(1, p - k)
                if avg_prev < avg_peak:
                    left_cnt = (left_cnt + inc[p][k]) % MOD
            right_cnt = 1 if q == n else 0
            for k in range(q + 1, n + 1):
                avg_next = (P[k] - P[q]) / max(1, k - q)
                if avg_next < avg_peak:
                    right_cnt = (right_cnt + dec[q][k]) % MOD
            ans = (ans + left_cnt * right_cnt) % MOD
    return ans

class Solution {
    int bitonicPartitioning(int[] arr) {
        final int MOD = 1_000_000_007;
        int n = arr.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + arr[i];
        long[][] inc = new long[n + 1][n];
        long[][] dec = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                double avgLast = (double)(P[i] - P[j]) / Math.max(1, i - j);
                if (j == 0) inc[i][j] = 1;
                else {
                    long total = 0;
                    for (int k = 0; k < j; k++) {
                        double avgPrev = (double)(P[j] - P[k]) / Math.max(1, j - k);
                        if (avgPrev < avgLast) total = (total + inc[j][k]) % MOD;
                    }
                    inc[i][j] = total;
                }
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i + 1; j <= n; j++) {
                double avgFirst = (double)(P[j] - P[i]) / Math.max(1, j - i);
                if (j == n) dec[i][j] = 1;
                else {
                    long total = 0;
                    for (int k = j + 1; k <= n; k++) {
                        double avgNext = (double)(P[k] - P[j]) / Math.max(1, k - j);
                        if (avgNext < avgFirst) total = (total + dec[j][k]) % MOD;
                    }
                    dec[i][j] = total;
                }
            }
        }
        long ans = 0;
        for (int p = 0; p < n; p++) {
            for (int q = p + 1; q <= n; q++) {
                double avgPeak = (double)(P[q] - P[p]) / Math.max(1, q - p);
                long L = (p == 0) ? 1 : 0;
                for (int k = 0; k < p; k++) {
                    double a = (double)(P[p] - P[k]) / Math.max(1, p - k);
                    if (a < avgPeak) L = (L + inc[p][k]) % MOD;
                }
                long R = (q == n) ? 1 : 0;
                for (int k = q + 1; k <= n; k++) {
                    double a = (double)(P[k] - P[q]) / Math.max(1, k - q);
                    if (a < avgPeak) R = (R + dec[q][k]) % MOD;
                }
                ans = (ans + L * R) % MOD;
            }
        }
        return (int) ans;
    }
}

