class Solution {
    int[] chainMerge(int[][] retentionTimes) {
        int n = retentionTimes.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> retentionTimes[b][0] - retentionTimes[a][0]);
        int[] out = new int[n];
        for (int i = 0; i < n; i++) out[i] = idx[i] + 1;
        return out;
    }
