class Solution {
public:
    vector<int> chainMerge(vector<vector<int>>& retentionTimes) {
        int n = retentionTimes.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            return retentionTimes[a][0] > retentionTimes[b][0];
        });
        vector<int> out(n);
        for (int i = 0; i < n; i++) out[i] = idx[i] + 1;
        return out;
    }
};

def doingSmartWork(a: str) -> str:
    odds = [c for c in a if int(c) % 2 == 1]
    evens = [c for c in a if int(c) % 2 == 0]
    i = j = 0
    out = []
    while i < len(odds) and j < len(evens):
        if odds[i] <= evens[j]:
            out.append(odds[i]); i += 1
        else:
            out.append(evens[j]); j += 1
    out.extend(odds[i:])
    out.extend(evens[j:])
    return ''.join(out)

class Solution {
    String doingSmartWork(String a) {
        StringBuilder odds = new StringBuilder(), evens = new StringBuilder();
        for (char c : a.toCharArray()) {
            if ((c - '0') % 2 == 1) odds.append(c);
            else evens.append(c);
        }
        StringBuilder out = new StringBuilder();
        int i = 0, j = 0;
        while (i < odds.length() && j < evens.length()) {
            if (odds.charAt(i) <= evens.charAt(j)) out.append(odds.charAt(i++));
            else out.append(evens.charAt(j++));
        }
        out.append(odds.substring(i));
        out.append(evens.substring(j));
        return out.toString();
    }
}

class Solution {
public:
    string doingSmartWork(string a) {
        string odds, evens;
        for (char c : a) {
            if ((c - '0') % 2 == 1) odds += c;
            else evens += c;
        }
        string out;
        size_t i = 0, j = 0;
        while (i < odds.size() && j < evens.size()) {
            if (odds[i] <= evens[j]) out += odds[i++];
            else out += evens[j++];
        }
        out += odds.substr(i);
        out += evens.substr(j);
        return out;
    }
};

class Solution {
    long enhanceLuminescence(int[] arr, int z) {
        long f0 = 0, f1 = Long.MIN_VALUE / 4, f2 = Long.MIN_VALUE / 4;
        long best = 0;
        for (int x : arr) {
            long nf0 = Math.max(0, f0 + x);
            long nf1 = Math.max(nf0 + (long) x * z, f1 + (long) x * z);
            long nf2 = Math.max(f2 + x, f1 + x);
            f0 = nf0; f1 = nf1; f2 = nf2;
            best = Math.max(best, Math.max(f0, Math.max(f1, f2)));
        }
        return best;
    }
}

