from typing import List

def findPodCount(pods: List[int], logs: List[List[int]]) -> List[int]:
    n = len(pods)
    last_val = list(pods)        # 最近一次显式赋值（含初始）
    last_time = [0] * n          # 时间戳
    floor = 0
    floor_time = 0
    for t, log in enumerate(logs, start=1):
        if log[0] == 1:
            p = log[1] - 1
            last_val[p] = log[2]
            last_time[p] = t
        else:
            floor = max(floor, log[2])
            floor_time = t
    out = []
    for i in range(n):
        if last_time[i] >= floor_time:
            out.append(last_val[i])
        else:
            out.append(max(last_val[i], floor))
    return out

class Solution {
    int[] findPodCount(int[] pods, int[][] logs) {
        int n = pods.length;
        int[] lastVal = pods.clone();
        int[] lastTime = new int[n];
        int floor = 0, floorTime = 0;
        for (int t = 1; t <= logs.length; t++) {
            int[] log = logs[t - 1];
            if (log[0] == 1) {
                int p = log[1] - 1;
                lastVal[p] = log[2];
                lastTime[p] = t;
            } else {
                floor = Math.max(floor, log[2]);
                floorTime = t;
            }
        }
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            if (lastTime[i] >= floorTime) out[i] = lastVal[i];
            else out[i] = Math.max(lastVal[i], floor);
        }
        return out;
    }
}

