        vector<int> lastVal = pods, lastTime(n, 0);
        int floorV = 0, floorTime = 0;
        for (int t = 1; t <= (int) logs.size(); t++) {
            auto& log = logs[t - 1];
            if (log[0] == 1) {
                int p = log[1] - 1;
                lastVal[p] = log[2];
                lastTime[p] = t;
            } else {
                floorV = max(floorV, log[2]);
                floorTime = t;
            }
        }
        vector<int> out(n);
        for (int i = 0; i < n; i++) {
            if (lastTime[i] >= floorTime) out[i] = lastVal[i];
            else out[i] = max(lastVal[i], floorV);
        }
        return out;
    }
};

import java.util.*;

class Solution {
    String friendshipString(String s) {
        int floor = -1;
        List<Integer> kept = new ArrayList<>(), plus = new ArrayList<>();
        for (char c : s.toCharArray()) {
            int d = c - '0';
            if (d >= floor) { kept.add(d); floor = d; }
            else plus.add(Math.min(d + 1, 9));
        }
        List<Integer> all = new ArrayList<>(kept);
        all.addAll(plus);
        Collections.sort(all);
        StringBuilder sb = new StringBuilder();
        for (int x : all) sb.append((char) ('0' + x));
        return sb.toString();
    }
}

class Solution {
public:
    string friendshipString(string s) {
        int floorV = -1;
        vector<int> all;
        for (char c : s) {
            int d = c - '0';
            if (d >= floorV) { all.push_back(d); floorV = d; }
            else all.push_back(min(d + 1, 9));
        }
        sort(all.begin(), all.end());
        string out;
        for (int x : all) out += (char) ('0' + x);
        return out;
    }
};

from typing import List

def getMinOperations(change: List[int], arr: List[int]) -> int:
    m = len(arr)
    nulled = [False] * (m + 1)
    arr_local = list(arr)
    ops = 0
    null_count = 0
    for i, c in enumerate(change):
        if null_count == m:
            return ops
        ops += 1
        if c > 0 and 1 <= c <= m and not nulled[c] and arr_local[c - 1] == 0:
            nulled[c] = True
            null_count += 1
        else:
            # 选最大未 null 的减 1
            best_idx = -1
            best_val = -1
            for j in range(m):
                if not nulled[j + 1] and arr_local[j] > best_val:
                    best_val = arr_local[j]
                    best_idx = j
            if best_idx == -1:
                return ops  # 全 null
            arr_local[best_idx] = max(0, arr_local[best_idx] - 1)
    return ops if null_count == m else -1

class Solution {
    int getMinOperations(int[] change, int[] arr) {
        int m = arr.length;
        boolean[] nulled = new boolean[m + 1];
        int[] a = arr.clone();
        int ops = 0, cnt = 0;
        for (int i = 0; i < change.length; i++) {
            if (cnt == m) return ops;
            ops++;
            int c = change[i];
            if (c > 0 && c <= m && !nulled[c] && a[c - 1] == 0) {
                nulled[c] = true;
                cnt++;
            } else {
                int best = -1, bv = -1;
                for (int j = 0; j < m; j++) {
                    if (!nulled[j + 1] && a[j] > bv) { bv = a[j]; best = j; }
                }
                if (best == -1) return ops;
                a[best] = Math.max(0, a[best] - 1);
            }
        }
        return cnt == m ? ops : -1;
    }
}

