def getTripletCount(arr: List[int], d: int) -> int:
    n = len(arr)
    ans = 0
    for i in range(n):
        for j in range(i + 1, n):
            need = (-arr[i] - arr[j]) % d
            for k in range(j + 1, n):
                if arr[k] % d == need:
                    ans += 1
    return ans

class Solution {
    long getTripletCount(int[] arr, int d) {
        int n = arr.length;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int need = (int) (((-(long) arr[i] - arr[j]) % d + d) % d);
                for (int k = j + 1; k < n; k++) {
                    if (arr[k] % d == need) ans++;
                }
            }
        }
        return ans;
    }
}

class Solution {
public:
    long long getTripletCount(vector<int>& arr, int d) {
        int n = arr.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long long s = ((long long) -arr[i] - arr[j]) % d;
                int need = (int) ((s + d) % d);
                for (int k = j + 1; k < n; k++) {
                    if (arr[k] % d == need) ans++;
                }
            }
        }
        return ans;
    }
};

from typing import List

def keySumManagement(operations: List[List[str]], n: int, q: int) -> int:
    # 解析：先 n 行 ["child", "parent"] 建初始树；剩 q 行 [op, ...]
    parent = {}
    level = {}
    # 初始 n 个边定义。如果某节点 1 没出现则它是根。
    # 我们解析所有初始关系
    children_count = {}
    for i in range(n):
        c, p = int(operations[i][0]), int(operations[i][1])
        parent[c] = p
        # level 暂未定
    # 找根：未出现在 child 的节点 → 但本题保证 "key 1 root"
    # 用 DFS 计算 level：root = 1
    nodes = set(parent.keys()) | set(parent.values())
    if 1 not in nodes:
        nodes.add(1)
    parent[1] = 0  # 虚根
    level[1] = 0
    # BFS
    children = {v: [] for v in nodes}
    for c, p in parent.items():
        if c != 1:
            children[p].append(c)
    from collections import deque
    dq = deque([1])
    while dq:
        u = dq.popleft()
        for c in children[u]:
            if c != 1:
                level[c] = level[u] + 1
                dq.append(c)
    # 现在处理 q 个操作
    value = {v: 0 for v in level}
    layer_add = {}  # 当前各层累计加法
    # 为简化，重新做：维护 level_count 与 layer_add
    for k in range(n, len(operations)):
        op = operations[k]
        if op[0] == 'Ro':
            p, v = int(op[1]), int(op[2])
            parent[v] = p
            level[v] = level[p] + 1
            # 新节点的 value = 0（不继承累积加法，因为它"刚创建"）
            value[v] = 0
            # 但题目"Re I z 影响该层及所有子层" → 之后的 Re 才生效
            # 旧的 Re 不影响它（因为创建在 Re 之后）
        elif op[0] == 'Re':
            I, z = int(op[1]), int(op[2])
            # 给所有 level >= I 的节点 +z（包括尚未创建的？不，只对当前存在的）
            for u in list(value.keys()):
                if level[u] >= I:
                    value[u] += z
    return sum(value.values())

import java.util.*;

class Solution {
    long keySumManagement(String[][] operations, int n, int q) {
        Map<Integer, Integer> level = new HashMap<>();
        Map<Integer, Long> value = new HashMap<>();
        Map<Integer, List<Integer>> children = new HashMap<>();
        Map<Integer, Integer> parent = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int c = Integer.parseInt(operations[i][0]);
            int p = Integer.parseInt(operations[i][1]);
            parent.put(c, p);
            children.computeIfAbsent(p, k -> new ArrayList<>()).add(c);
        }
        level.put(1, 0);
        value.put(1, 0L);
        Deque<Integer> dq = new ArrayDeque<>();
        dq.offer(1);
        while (!dq.isEmpty()) {
            int u = dq.poll();
            for (int c : children.getOrDefault(u, Collections.emptyList())) {
                if (!level.containsKey(c)) {
                    level.put(c, level.get(u) + 1);
                    value.put(c, 0L);
                    dq.offer(c);
                }
            }
        }
        for (int k = n; k < operations.length; k++) {
            String[] op = operations[k];
            if (op[0].equals("Ro")) {
                int p = Integer.parseInt(op[1]), v = Integer.parseInt(op[2]);
                level.put(v, level.get(p) + 1);
                value.put(v, 0L);
            } else {
                int I = Integer.parseInt(op[1]), z = Integer.parseInt(op[2]);
                for (int u : new HashSet<>(value.keySet())) {
                    if (level.get(u) >= I) value.merge(u, (long) z, Long::sum);
                }
            }
        }
        long sum = 0;
        for (long v : value.values()) sum += v;
        return sum;
    }
}

class Solution {
public:
    long long keySumManagement(vector<vector<string>>& operations, int n, int q) {
        unordered_map<int, int> level;
        unordered_map<int, long long> value;
        unordered_map<int, vector<int>> children;
        for (int i = 0; i < n; i++) {
            int c = stoi(operations[i][0]);
            int p = stoi(operations[i][1]);
            children[p].push_back(c);
        }
        level[1] = 0;
        value[1] = 0;
        queue<int> dq;
        dq.push(1);
        while (!dq.empty()) {
            int u = dq.front(); dq.pop();
            for (int c : children[u]) {
                if (!level.count(c)) {
                    level[c] = level[u] + 1;
                    value[c] = 0;
                    dq.push(c);
                }
            }
        }
        for (int k = n; k < (int) operations.size(); k++) {
            auto& op = operations[k];
            if (op[0] == "Ro") {
                int p = stoi(op[1]), v = stoi(op[2]);
                level[v] = level[p] + 1;
                value[v] = 0;
            } else {
                int I = stoi(op[1]), z = stoi(op[2]);
                for (auto& [u, _] : value) {
                    if (level[u] >= I) value[u] += z;
                }
            }
        }
        long long sum = 0;
        for (auto& [k, v] : value) sum += v;
        return sum;
    }
};

