class Solution {
    int maximizeHappiness(int[][] employeeData, int budget) {
        int n = employeeData.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i <= n; i++) children.add(new ArrayList<>());
        for (int i = 1; i <= n; i++) children.get(employeeData[i - 1][0]).add(i);
        long best = 0;
        for (int u = 1; u <= n; u++) {
            List<Integer> costs = new ArrayList<>();
            Deque<Integer> st = new ArrayDeque<>();
            st.push(u);
            while (!st.isEmpty()) {
                int v = st.pop();
                costs.add(employeeData[v - 1][1]);
                for (int c : children.get(v)) st.push(c);
            }
            Collections.sort(costs);
            long total = 0;
            int cnt = 0;
            for (int c : costs) {
                if (total + c <= budget) { total += c; cnt++; }
                else break;
            }
            best = Math.max(best, (long) employeeData[u - 1][2] * cnt);
        }
        return (int) best;
    }
}

