from collections import defaultdict, deque

def maximizeStellarGradient(n: int, edges: List[List[int]]) -> int:
    # edges[i] = [u, v, dir]，dir 0=无向，1=表示 u→v 即 e_v = e_u + 1
    adj = defaultdict(list)
    for u, v, d in edges:
        if d == 1:
            adj[u].append((v, 1))    # e_v - e_u = 1
            adj[v].append((u, -1))
        else:
            adj[u].append((v, None))
            adj[v].append((u, None))
    e = [None] * (n + 1)
    best_diff = 0
    for start in range(1, n + 1):
        if e[start] is not None:
            continue
        e[start] = 0
        comp_min = comp_max = 0
        q = deque([start])
        ok = True
        while q and ok:
            u = q.popleft()
            for v, delta in adj[u]:
                if delta is None:
                    # 无向：选 e_v = e_u + 1（贪心使范围更大）
                    if e[v] is None:
                        e[v] = e[u] + 1
                        comp_max = max(comp_max, e[v])
                        comp_min = min(comp_min, e[v])
                        q.append(v)
                    # 若已赋值且差不是 ±1 → 不一致
                    elif abs(e[v] - e[u]) != 1:
                        ok = False
                else:
                    if e[v] is None:
                        e[v] = e[u] + delta
                        comp_max = max(comp_max, e[v])
                        comp_min = min(comp_min, e[v])
                        q.append(v)
                    elif e[v] != e[u] + delta:
                        ok = False
        if not ok:
            return -1
        best_diff = max(best_diff, comp_max - comp_min)
    return best_diff

import java.util.*;

class Solution {
    int maximizeStellarGradient(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            int u = e[0], v = e[1], d = e[2];
            if (d == 1) {
                adj.get(u).add(new int[]{v, 1});
                adj.get(v).add(new int[]{u, -1});
            } else {
                adj.get(u).add(new int[]{v, 0});
                adj.get(v).add(new int[]{u, 0});
            }
        }
        Integer[] val = new Integer[n + 1];
        int bestDiff = 0;
        for (int start = 1; start <= n; start++) {
            if (val[start] != null) continue;
            val[start] = 0;
            int mn = 0, mx = 0;
            Deque<Integer> q = new ArrayDeque<>();
            q.offer(start);
            boolean ok = true;
            while (!q.isEmpty() && ok) {
                int u = q.poll();
                for (int[] p : adj.get(u)) {
                    int v = p[0], delta = p[1];
                    if (delta == 0) {
                        if (val[v] == null) {
                            val[v] = val[u] + 1;
                            mx = Math.max(mx, val[v]);
                            mn = Math.min(mn, val[v]);
                            q.offer(v);
                        } else if (Math.abs(val[v] - val[u]) != 1) {
                            ok = false;
                        }
                    } else {
                        if (val[v] == null) {
                            val[v] = val[u] + delta;
                            mx = Math.max(mx, val[v]);
                            mn = Math.min(mn, val[v]);
                            q.offer(v);
                        } else if (val[v] != val[u] + delta) {
                            ok = false;
                        }
                    }
                }
            }
            if (!ok) return -1;
            bestDiff = Math.max(bestDiff, mx - mn);
        }
        return bestDiff;
    }
}

