def mikeAndGems(a: List[int]) -> int:
    heap = []
    s = 0
    for x in a:
        heapq.heappush(heap, x)
        s += x
        while s < 0:
            top = heapq.heappop(heap)
            s -= top
    return len(heap)

import java.util.*;

class Solution {
    int mikeAndGems(int[] a) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        long s = 0;
        for (int x : a) {
            heap.offer(x);
            s += x;
            while (s < 0 && !heap.isEmpty()) {
                int top = heap.poll();
                s -= top;
            }
        }
        return heap.size();
    }
}

