        priority_queue<int, vector<int>, greater<int>> heap;
        long long s = 0;
        for (int x : a) {
            heap.push(x);
            s += x;
            while (s < 0 && !heap.empty()) {
                s -= heap.top();
                heap.pop();
            }
        }
        return heap.size();
    }
};

class Solution {
    long redistributeMegaseeds(int[] seeds) {
        long S = 0;
        for (int x : seeds) S += x;
        if (S < 2) return -1;
        List<Long> divisors = new ArrayList<>();
        for (long d = 2; d * d <= S; d++) {
            if (S % d == 0) {
                divisors.add(d);
                if (S / d != d) divisors.add(S / d);
            }
        }
        divisors.add(S);
        long best = Long.MAX_VALUE;
        for (long d : divisors) {
            long ops = 0, pref = 0;
            for (int i = 0; i < seeds.length - 1; i++) {
                pref += seeds[i];
                long r = pref % d;
                ops += Math.min(r, d - r);
            }
            best = Math.min(best, ops);
        }
        return best == Long.MAX_VALUE ? -1 : best;
    }
}

