        if (S < 2) return -1;
        vector<long long> divisors;
        for (long long d = 2; d * d <= S; d++) {
            if (S % d == 0) {
                divisors.push_back(d);
                if (S / d != d) divisors.push_back(S / d);
            }
        }
        divisors.push_back(S);
        long long best = LLONG_MAX;
        for (long long d : divisors) {
            long long ops = 0, pref = 0;
            for (int i = 0; i + 1 < (int) seeds.size(); i++) {
                pref += seeds[i];
                long long r = pref % d;
                ops += min(r, d - r);
            }
            best = min(best, ops);
        }
        return best == LLONG_MAX ? -1 : best;
    }
};

