def salvageHumankind(n: int, masses: List[int], ops: int, queries: List[List[int]]) -> List[int]:
    # 简化暴力实现：直接维护数组
    a = list(masses)
    out = []
    for q in queries:
        if q[0] == 1:
            s, e = q[1] - 1, q[2] - 1
            out.append(sum(a[s:e + 1]))
        else:
            s, e, z = q[1] - 1, q[2] - 1, q[3]
            for i in range(s, e + 1):
                a[i] ^= z
    return out

