def saveTheUniverse(n: int, m: int, k: int, e: List[int], p: List[int]) -> int:
    children = [[] for _ in range(n + 1)]
    for i, par in enumerate(p, start=2):
        children[par].append(i)
    ops = 0
    sub_sum = [0] * (n + 1)
    # post-order
    order = []
    stack = [1]
    while stack:
        u = stack.pop()
        order.append(u)
        for c in children[u]:
            stack.append(c)
    for u in reversed(order):
        s = e[u - 1]
        for c in children[u]:
            s += sub_sum[c]
        if s > k:
            # 需要把这个子树切掉，开枪计数
            ops += 1
            s = e[u - 1]   # 切完后该节点单独
            for c in children[u]:
                if sub_sum[c] > 0:
                    s += sub_sum[c]
        sub_sum[u] = s
    return ops

import java.util.*;

class Solution {
    int saveTheUniverse(int n, int m, long k, long[] e, int[] p) {
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i <= n; i++) children.add(new ArrayList<>());
        for (int i = 2; i <= n; i++) children.get(p[i - 2]).add(i);
        long[] sub = new long[n + 1];
        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> st = new ArrayDeque<>();
        st.push(1);
        while (!st.isEmpty()) {
            int u = st.pop();
            order[idx++] = u;
            for (int c : children.get(u)) st.push(c);
        }
        int ops = 0;
        for (int t = n - 1; t >= 0; t--) {
            int u = order[t];
            long s = e[u - 1];
            for (int c : children.get(u)) s += sub[c];
            if (s > k) { ops++; s = e[u - 1]; }
            sub[u] = s;
        }
        return ops;
    }
}

