from typing import List

def theOracles(n: int, q: int, operations: List[List[int]], queries: List[int]) -> List[int]:
    sizes = [0]   # 累积长度
    for op_type, x in operations:
        prev = sizes[-1]
        if op_type == 1:
            sizes.append(prev + 1)
        else:
            sizes.append(prev * x)
    out = []
    for qi in queries:
        idx = qi
        for k in range(len(operations), 0, -1):
            op_type, x = operations[k - 1]
            prev = sizes[k - 1]
            if op_type == 1:
                # append x：第 prev+1 位 = x
                if idx == prev + 1:
                    out.append(x)
                    break
                # 否则 idx <= prev，继续
            else:
                # repeat x：当前 size = prev * x；idx in [1, prev*x]
                idx = (idx - 1) % prev + 1
        else:
            out.append(-1)
    return out

import java.util.*;

class Solution {
    int[] theOracles(int n, int q, int[][] operations, long[] queries) {
        long[] sizes = new long[n + 1];
        for (int i = 0; i < n; i++) {
            long prev = sizes[i];
            if (operations[i][0] == 1) sizes[i + 1] = prev + 1;
            else sizes[i + 1] = prev * operations[i][1];
        }
        int[] out = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            long idx = queries[qi];
            int ans = -1;
            for (int k = n; k > 0; k--) {
                int t = operations[k - 1][0], x = operations[k - 1][1];
                long prev = sizes[k - 1];
                if (t == 1) {
                    if (idx == prev + 1) { ans = x; break; }
                } else {
                    idx = (idx - 1) % prev + 1;
                }
            }
            out[qi] = ans;
        }
        return out;
    }
}

