        for (int i = 0; i < n; i++) {
            long long prev = sizes[i];
            if (operations[i][0] == 1) sizes[i + 1] = prev + 1;
            else sizes[i + 1] = prev * operations[i][1];
        }
        vector<int> out;
        for (long long qi : queries) {
            long long idx = qi;
            int ans = -1;
            for (int k = n; k > 0; k--) {
