from typing import List

def unalignedDedupe(strings: List[str], m: int, k: int) -> List[int]:
    best_l, best_saved = k, 0
    for l in range(k, m + 1):
        seen = set()
        saved = 0
        for s in strings:
            # 当前串里 aligned 切分
            blocks = [s[i:i + l] for i in range(0, len(s), l) if len(s[i:i + l]) == l]
            for b in blocks:
                if b in seen:
                    saved += l
            # 加入"该串里所有 l 长 substr"供后续串使用
            for i in range(len(s) - l + 1):
                seen.add(s[i:i + l])
        if saved > best_saved:
            best_saved = saved
            best_l = l
    return [best_l, best_saved]

import java.util.*;

class Solution {
    int[] unalignedDedupe(String[] strings, int m, int k) {
        int bestL = k, bestSaved = 0;
        for (int l = k; l <= m; l++) {
            Set<String> seen = new HashSet<>();
            int saved = 0;
            for (String s : strings) {
                for (int i = 0; i + l <= s.length(); i += l) {
                    String b = s.substring(i, i + l);
                    if (seen.contains(b)) saved += l;
                }
                for (int i = 0; i + l <= s.length(); i++) {
                    seen.add(s.substring(i, i + l));
                }
            }
            if (saved > bestSaved) { bestSaved = saved; bestL = l; }
        }
        return new int[]{bestL, bestSaved};
    }
}

class Solution {
public:
    vector<int> unalignedDedupe(vector<string>& strings, int m, int k) {
        int bestL = k, bestSaved = 0;
        for (int l = k; l <= m; l++) {
            unordered_set<string> seen;
            int saved = 0;
            for (auto& s : strings) {
                for (int i = 0; i + l <= (int) s.size(); i += l) {
                    string b = s.substr(i, l);
                    if (seen.count(b)) saved += l;
                }
                for (int i = 0; i + l <= (int) s.size(); i++) {
                    seen.insert(s.substr(i, l));
                }
            }
            if (saved > bestSaved) { bestSaved = saved; bestL = l; }
        }
        return {bestL, bestSaved};
    }
};

def max_historical_income(A):
    profit = sum(max(0, A[i] - A[i-1]) for i in range(1, len(A)))
    return profit % 10**9

class Solution {
    static long maxHistoricalIncome(int[] A) {
        long MOD = 1_000_000_000L;
        long profit = 0;
        for (int i = 1; i < A.length; i++)
            if (A[i] > A[i - 1]) profit += A[i] - A[i - 1];
        return profit % MOD;
    }
}

