class Solution {
    static long numberScore(long n) {
        String s = String.valueOf(n);
        long score = 0;
        for (char c : s.toCharArray()) {
            if (c == '5') score += 2;
            if ((c - '0') % 2 == 1) score++;
        }
        int i = 0;
        while (i < s.length()) {
            int j = i;
            while (j + 1 < s.length() && s.charAt(j + 1) == '3' && s.charAt(j) == '3') j++;
            if (j > i) score += 4L * (j - i);
            i = j + 1;
        }
        i = 0;
        while (i < s.length()) {
            int j = i;
            while (j + 1 < s.length() && s.charAt(j + 1) - s.charAt(j) == 1) j++;
            int len = j - i + 1;
            score += (long) len * len;
            i = j + 1;
        }
        if (n % 5 == 0) score += 6;
        return score;
    }
}

