def lock_checker(events):
    stack, held = [], set()
    for i, ev in enumerate(events):
        parts = ev.split()
        if parts[0] == "ACQUIRE":
            if parts[1] in held: return i + 1
            stack.append(parts[1])
            held.add(parts[1])
        else:
            if not stack or stack[-1] != parts[1]: return i + 1
            stack.pop()
            held.remove(parts[1])
    return 0 if not stack else len(events) + 1

class Solution {
    static int lockChecker(String[] events) {
        Deque<String> stack = new ArrayDeque<>();
        Set<String> held = new HashSet<>();
        for (int i = 0; i < events.length; i++) {
            String[] p = events[i].split(" ");
            if (p[0].equals("ACQUIRE")) {
                if (held.contains(p[1])) return i + 1;
                stack.push(p[1]);
                held.add(p[1]);
            } else {
                if (stack.isEmpty() || !stack.peek().equals(p[1])) return i + 1;
                stack.pop();
                held.remove(p[1]);
            }
        }
        return stack.isEmpty() ? 0 : events.length + 1;
    }
}

int lockChecker(vector<string>& events) {
 vector<string> stk;
 unordered_set<string> held;
 for (int i = 0; i < (int)events.size(); ++i) {
 auto& ev = events[i];
 auto sp = ev.find(' ');
 string op = ev.substr(0, sp), name = ev.substr(sp + 1);
 if (op == "ACQUIRE") {
 if (held.count(name)) return i + 1;
 stk.push_back(name);
 held.insert(name);
 } else {
 if (stk.empty() || stk.back() != name) return i + 1;
 stk.pop_back();
 held.erase(name);
 }
 }
 return stk.empty() ? 0 : (int)events.size() + 1;
}

def count_palindromic_substrings(s):
    cnt = 0
    n = len(s)
    for c in range(n):
        l, r = c, c
        while l >= 0 and r < n and s[l] == s[r]:
            cnt += 1; l -= 1; r += 1
        l, r = c, c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            cnt += 1; l -= 1; r += 1
    return cnt

class Solution {
    static long countPalindromicSubstrings(String s) {
        long cnt = 0;
        for (int c = 0; c < s.length(); c++) {
            int l = c, r = c;
            while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { cnt++; l--; r++; }
            l = c; r = c + 1;
            while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) { cnt++; l--; r++; }
        }
        return cnt;
    }
}

