 l = c; r = c + 1;
 while (l >= 0 && r < n && s[l] == s[r]) { ++cnt; --l; ++r; }
 }
 return cnt;
}

items.statement:
Bob wrote the binary search below and claims it returns the index of `target` in a sorted array, or `-1` if not present. Either prove it correct or produce a counterexample sorted array + target where it returns the wrong answer.

```c
int sorted_search(int* elements, int size, int target) {
 if (size <= 0 || !elements) return -1;
 int left = 0, right = size - 1;
 while (left < right) {
 int middle = (left + right + 1) / 2;
 if (elements[middle] > target) right = middle - 1;
 else left = middle + 1;
 }
 if (elements[right] == target) return right;
 return -1;
}
```

solutions.code:
def check_bobs_binary_search():
    def bob(elements, target):
        if not elements: return -1
        left, right = 0, len(elements) - 1
        while left < right:
            middle = (left + right + 1) // 2
            if elements[middle] > target: right = middle - 1
            else: left = middle + 1
        return right if elements[right] == target else -1

    # brute search small inputs for a counterexample
    from itertools import combinations_with_replacement
    for n in range(1, 6):
        for arr in combinations_with_replacement(range(1, n + 2), n):
            arr = list(arr)
            for t in range(0, n + 3):
                expected = arr.index(t) if t in arr else -1  # any index works
                got = bob(arr, t)
                # bob returns -1 when t in arr but unreachable
                if t in arr and got == -1:
                    return arr, t
                if t not in arr and got != -1:
                    return arr, t
    return None

class Solution {
    static int bob(int[] a, int t) {
        if (a.length == 0) return -1;
        int left = 0, right = a.length - 1;
        while (left < right) {
            int middle = (left + right + 1) / 2;
            if (a[middle] > t) right = middle - 1;
            else               left  = middle + 1;
        }
        return a[right] == t ? right : -1;
    }
}

int bob(vector<int>& a, int t) {
 if (a.empty()) return -1;
 int left = 0, right = (int)a.size() - 1;
 while (left < right) {
 int middle = (left + right + 1) / 2;
 if (a[middle] > t) right = middle - 1;
 else left = middle + 1;
 }
 return a[right] == t ? right : -1;
}

