def count_different_palindrome_substrings(s: str) -> int:
    found = set()
    n = len(s)
    for c in range(n):
        l, r = c, c
        while l >= 0 and r < n and s[l] == s[r]:
            found.add(s[l:r + 1]); l -= 1; r += 1
        l, r = c, c + 1
        while l >= 0 and r < n and s[l] == s[r]:
            found.add(s[l:r + 1]); l -= 1; r += 1
    return len(found)

import java.util.*;

class Solution {
    int countDifferentPalindromeSubstrings(String s) {
        Set<String> found = new HashSet<>();
        int n = s.length();
        for (int c = 0; c < n; c++) {
            int l = c, r = c;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                found.add(s.substring(l, r + 1)); l--; r++;
            }
            l = c; r = c + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                found.add(s.substring(l, r + 1)); l--; r++;
            }
        }
        return found.size();
    }
}

class Solution {
public:
    int countDifferentPalindromeSubstrings(string s) {
        unordered_set<string> found;
        int n = s.size();
        for (int c = 0; c < n; c++) {
            int l = c, r = c;
            while (l >= 0 && r < n && s[l] == s[r]) { found.insert(s.substr(l, r - l + 1)); --l; ++r; }
            l = c; r = c + 1;
            while (l >= 0 && r < n && s[l] == s[r]) { found.insert(s.substr(l, r - l + 1)); --l; ++r; }
        }
        return (int) found.size();
    }
};

