class Solution {
    int[] findDoubles(int[] numbers) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : numbers) cnt.merge(x, 1, Integer::sum);
        List<Integer> res = new ArrayList<>();
        for (int v : numbers) if (cnt.getOrDefault(2 * v, 0) == 1) res.add(v);
