def find_repetitions(short_s: str, long_s: str) -> int:
    if not short_s or not long_s:
        return 0
    s = len(short_s)
    best = cur = 0
    i = 0
    while i + s <= len(long_s):
        if long_s[i:i + s] == short_s:
            cur += 1
            best = max(best, cur)
            i += s
        else:
            cur = 0
            i += 1
    return best

class Solution {
    int findRepetitions(String shortS, String longS) {
        if (shortS.isEmpty() || longS.isEmpty()) return 0;
        int s = shortS.length(), best = 0, cur = 0;
        int i = 0;
        while (i + s <= longS.length()) {
            if (longS.regionMatches(i, shortS, 0, s)) {
                cur++;
                best = Math.max(best, cur);
                i += s;
            } else { cur = 0; i++; }
        }
        return best;
    }
}

class Solution {
public:
    int findRepetitions(string shortS, string longS) {
        if (shortS.empty() || longS.empty()) return 0;
        int s = shortS.size(), best = 0, cur = 0;
        int i = 0;
        while (i + s <= (int) longS.size()) {
            if (longS.compare(i, s, shortS) == 0) {
                ++cur;
                best = max(best, cur);
                i += s;
            } else { cur = 0; ++i; }
        }
        return best;
    }
};

from typing import List
from collections import defaultdict

def find_winner(results: List[List[int]]) -> List[int]:
    pts = [10, 6, 4, 3, 2, 1]
    score = defaultdict(int)
    for race, racer, pos in results:
        if 1 <= pos <= 6:
            score[racer] += pts[pos - 1]
    best_racer, best_score = -1, -1
    for racer in sorted(score):
        if score[racer] > best_score:
            best_racer, best_score = racer, score[racer]
    return [best_racer, best_score]

import java.util.*;

class Solution {
    int[] findWinner(int[][] results) {
        int[] pts = {10, 6, 4, 3, 2, 1};
        TreeMap<Integer, Integer> score = new TreeMap<>();
        for (int[] r : results) {
            int racer = r[1], pos = r[2];
            if (pos >= 1 && pos <= 6) score.merge(racer, pts[pos - 1], Integer::sum);
        }
        int best = -1, bestS = -1;
        for (var e : score.entrySet()) {
            if (e.getValue() > bestS) { best = e.getKey(); bestS = e.getValue(); }
        }
        return new int[]{best, bestS};
    }
}

class Solution {
public:
    vector<int> findWinner(vector<vector<int>>& results) {
        int pts[6] = {10, 6, 4, 3, 2, 1};
        map<int, int> score;
        for (auto& r : results) {
            int racer = r[1], pos = r[2];
            if (pos >= 1 && pos <= 6) score[racer] += pts[pos - 1];
        }
        int best = -1, bestS = -1;
        for (auto& [racer, s] : score) {
            if (s > bestS) { best = racer; bestS = s; }
        }
        return {best, bestS};
    }
};

