def generateMatrixB(A: List[List[int]]) -> List[List[int]]:
    m, n = len(A), len(A[0])
    B = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            B[i][j] = A[i][j]
            if i > 0:
                B[i][j] += B[i - 1][j]
            if j > 0:
                B[i][j] += B[i][j - 1]
            if i > 0 and j > 0:
                B[i][j] -= B[i - 1][j - 1]
    return B

class Solution {
    int[][] generateMatrixB(int[][] A) {
        int m = A.length, n = A[0].length;
        int[][] B = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                B[i][j] = A[i][j];
                if (i > 0) B[i][j] += B[i - 1][j];
                if (j > 0) B[i][j] += B[i][j - 1];
                if (i > 0 && j > 0) B[i][j] -= B[i - 1][j - 1];
            }
        }
        return B;
    }
}

