class Solution {
    public int[] getRequiredSweeps(int[] ping) {
        int n = ping.length;
        TreeSet<Integer> set = new TreeSet<>();
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            set.add(ping[i]);
            int cnt = set.size(), j = 0, best = 0;
            for (int p : set) {
                int target = n - cnt + j + 1;
                int sweeps = Math.max(0, target - p - j);
                if (sweeps > best) best = sweeps;
                j++;
            }
            out[i] = best;
        }
        return out;
    }
}

