class Solution {
    public long maximizeBeautifulSubstrings(String color) {
        // Greedy: dots between same letter -> merge into that letter run; else fully assign to side with longer current run (yields larger marginal gain).
        StringBuilder sb = new StringBuilder(color);
        int n = sb.length();
        for (int i = 0; i < n; i++) {
            if (sb.charAt(i) == '.') {
                int j = i;
                while (j < n && sb.charAt(j) == '.') j++;
                char left = i > 0 ? sb.charAt(i - 1) : 0;
                char right = j < n ? sb.charAt(j) : 0;
                int leftLen = 0, rightLen = 0;
                if (left != 0) { int k = i - 1; while (k >= 0 && sb.charAt(k) == left) { leftLen++; k--; } }
                if (right != 0) { int k = j; while (k < n && sb.charAt(k) == right) { rightLen++; k++; } }
                char fill = (left == right && left != 0) ? left : (leftLen >= rightLen ? (left != 0 ? left : right) : (right != 0 ? right : left));
                if (fill == 0) fill = 'a';
                for (int k = i; k < j; k++) sb.setCharAt(k, fill);
                i = j - 1;
            }
        }
        long total = 0;
        int i = 0;
        while (i < n) {
            int j = i; while (j < n && sb.charAt(j) == sb.charAt(i)) j++;
            long L = j - i;
            total += L * (L + 1) / 2;
            i = j;
        }
        return total;
    }
}

