class Solution {
public:
    int minBoysNextToGirls(std::string s) {
        int n = s.size(), boys = 0, i = 0;
        while (i < n) {
            if (s[i] == 'G') {
                int j = i;
                while (j < n && s[j] == 'G') j++;
                bool leftEmpty = i > 0 && s[i - 1] == '-';
                bool rightEmpty = j < n && s[j] == '-';
                int len = j - i;
                if (len == 1) {
                    if (leftEmpty) { s[i - 1] = 'B'; boys++; }
                    else if (rightEmpty) { s[j] = 'B'; boys++; }
                    else return -1;
                } else if (len == 2) {
                    if (leftEmpty && rightEmpty) { s[i - 1] = 'B'; s[j] = 'B'; boys += 2; }
                    else return -1;
                } else return -1;
                i = j;
            } else i++;
        }
        return boys;
    }
};

from typing import List

def printAllPalindromes(s: str) -> List[str]:
    result: List[str] = []
    n = len(s)
    def expand(left: int, right: int) -> None:
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 >= 3:
                result.append(s[left:right + 1])
            left -= 1
            right += 1
    for i in range(n):
        expand(i, i)
        expand(i, i + 1)
    return result

import java.util.*;

class Solution {
    List<String> printAllPalindromes(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            expand(s, i, i, result);
            expand(s, i, i + 1, result);
        }
        return result;
    }
    private void expand(String s, int l, int r, List<String> result) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
            if (r - l + 1 >= 3) result.add(s.substring(l, r + 1));
            l--; r++;
        }
    }
}

