        std::vector<std::string> result;
        int n = s.size();
        auto expand = [&](int l, int r) {
            while (l >= 0 && r < n && s[l] == s[r]) {
                if (r - l + 1 >= 3) result.push_back(s.substr(l, r - l + 1));
                l--; r++;
            }
        };
        for (int i = 0; i < n; i++) {
            expand(i, i);
            expand(i, i + 1);
        }
        return result;
    }
};

