 vector<long long> res(n, 0);
 for (auto& [v, idxs] : groups) {
 int m = idxs.size();
 if (m <= 1) continue;
 vector<long long> pre(m + 1, 0);
 for (int i = 0; i < m; ++i) pre[i + 1] = pre[i] + idxs[i];
 long long total = pre[m];
 for (int k = 0; k < m; ++k) {
 long long x = idxs[k];
 long long left = (long long)k * x - pre[k];
 long long right = (total - pre[k + 1]) - (long long)(m - 1 - k) * x;
 res[x] = left + right;
 }
 }
 return res;
}

class Solution {
    public int minMoves(int[][] maze, int x, int y) {
        int n = maze.length, m = maze[0].length;
        Map<Long, Integer> coinIdx = new HashMap<>();
        int k = 0;
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++)
            if (maze[i][j] == 2) coinIdx.put((long) i * m + j, k++);
        int full = (1 << k) - 1;
        if (maze[0][0] == 1) return -1;
        Deque<int[]> dq = new ArrayDeque<>();
        Set<Long> seen = new HashSet<>();
        dq.add(new int[]{0, 0, 0, 0});
        seen.add(0L);
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        while (!dq.isEmpty()) {
            int[] s = dq.poll();
            if (s[0] == x && s[1] == y && s[2] == full) return s[3];
            for (int i = 0; i < 4; i++) {
                int nr = s[0] + dr[i], nc = s[1] + dc[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m || maze[nr][nc] == 1) continue;
                int nm = s[2];
                Long key = (long) nr * m + nc;
                if (coinIdx.containsKey(key)) nm |= (1 << coinIdx.get(key));
                long st = ((long) nr * m + nc) * 128 + nm;
                if (seen.add(st)) dq.add(new int[]{nr, nc, nm, s[3] + 1});
            }
        }
        return -1;
    }
}

int minMoves(vector<vector<int>>& maze, int x, int y) {
 int n = maze.size(), m = maze[0].size();
 map<pair<int,int>, int> coinIdx;
 int k = 0;
 for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j)
 if (maze[i][j] == 2) coinIdx[{i, j}] = k++;
 int full = (1 << k) - 1;
 if (maze[0][0] == 1) return -1;
 queue<tuple<int,int,int,int>> dq;
 set<tuple<int,int,int>> seen;
 dq.push({0, 0, 0, 0}); seen.insert({0, 0, 0});
 int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1};
 while (!dq.empty()) {
 auto [r, c, mask, d] = dq.front(); dq.pop();
 if (r == x && c == y && mask == full) return d;
 for (int i = 0; i < 4; ++i) {
 int nr = r + dr[i], nc = c + dc[i];
 if (nr < 0 || nr >= n || nc < 0 || nc >= m || maze[nr][nc] == 1) continue;
 int nm = mask;
 if (coinIdx.count({nr, nc})) nm |= (1 << coinIdx[{nr, nc}]);
 if (seen.insert({nr, nc, nm}).second) dq.push({nr, nc, nm, d + 1});
 }
 }
 return -1;
}

def getRecommendedFriends(n, friendships):
    f = [set() for _ in range(n)]
    for a, b in friendships: f[a].add(b); f[b].add(a)
    res = []
    for u in range(n):
        cand = set()
        for v in f[u]: cand |= f[v]
        cand.discard(u); cand -= f[u]
        best_idx, best_cnt = -1, 0
        for c in cand:
            cnt = len(f[u] & f[c])
            if cnt > best_cnt or (cnt == best_cnt and (best_idx == -1 or c < best_idx)):
                best_cnt = cnt; best_idx = c
        res.append(best_idx)
    return res

class Solution {
    public int[] getRecommendedFriends(int n, int[][] friendships) {
        List<Set<Integer>> f = new ArrayList<>();
        for (int i = 0; i < n; i++) f.add(new HashSet<>());
        for (int[] e : friendships) { f.get(e[0]).add(e[1]); f.get(e[1]).add(e[0]); }
        int[] res = new int[n];
        for (int u = 0; u < n; u++) {
            Set<Integer> cand = new HashSet<>();
            for (int v : f.get(u)) cand.addAll(f.get(v));
            cand.remove(u);
            cand.removeAll(f.get(u));
            int bestIdx = -1, bestCnt = 0;
            for (int c : cand) {
                int cnt = 0;
                for (int x : f.get(u)) if (f.get(c).contains(x)) cnt++;
                if (cnt > bestCnt || (cnt == bestCnt && (bestIdx == -1 || c < bestIdx))) { bestCnt = cnt; bestIdx = c; }
            }
            res[u] = bestIdx;
        }
        return res;
    }
}

