def canReach(x1, y1, x2, y2):
    while x2 > 0 and y2 > 0:
        if x2 == x1 and y2 == y1: return "Yes"
        if x2 > y2:
            if y2 == y1 and x2 > x1 and (x2 - x1) % y2 == 0: return "Yes"
            x2 %= y2
        else:
            if x2 == x1 and y2 > y1 and (y2 - y1) % x2 == 0: return "Yes"
            y2 %= x2
    return "No"

