from collections import defaultdict

def numNicePairs(n, frm, to, w):
    g = defaultdict(list)
    for u, v, ww in zip(frm, to, w):
        b = 1 << (ww - 1); g[u].append((v, b)); g[v].append((u, b))
    cnt = defaultdict(int)
    stk = [(1, 0, -1)]
    while stk:
        u, m, p = stk.pop(); cnt[m] += 1
        for v, b in g[u]:
            if v != p: stk.append((v, m ^ b, u))
    res = 0
    for m, c in cnt.items():
        res += c * (c - 1) // 2
        for i in range(26):
            o = m ^ (1 << i)
            if o > m and o in cnt: res += c * cnt[o]
    return res

class Solution {
    public long numNicePairs(int n, int[] from, int[] to, int[] w) {
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int i = 0; i < from.length; i++) {
            int b = 1 << (w[i] - 1);
            g.get(from[i]).add(new int[]{to[i], b});
            g.get(to[i]).add(new int[]{from[i], b});
        }
        Map<Integer, Integer> cnt = new HashMap<>();
        Deque<int[]> stk = new ArrayDeque<>();
        stk.push(new int[]{1, 0, -1});
        while (!stk.isEmpty()) {
            int[] s = stk.pop();
            cnt.merge(s[1], 1, Integer::sum);
            for (int[] e : g.get(s[0])) if (e[0] != s[2]) stk.push(new int[]{e[0], s[1] ^ e[1], s[0]});
        }
        long res = 0;
        for (var e : cnt.entrySet()) {
            int m = e.getKey(), c = e.getValue();
            res += (long) c * (c - 1) / 2;
            for (int i = 0; i < 26; i++) {
                int other = m ^ (1 << i);
                if (other > m && cnt.containsKey(other)) res += (long) c * cnt.get(other);
            }
        }
        return res;
    }
}

