class Solution {
    public String[] classifyEdges(int gNodes, int[] gFrom, int[] gTo, int[] gWeight) {
        int n = gNodes;
        List<long[]>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < gFrom.length; i++) {
            adj[gFrom[i]].add(new long[]{gTo[i], gWeight[i]});
            adj[gTo[i]].add(new long[]{gFrom[i], gWeight[i]});
        }
        long[] d1 = dijkstra(adj, n, 1);
        long[] dn = dijkstra(adj, n, n);
        long D = d1[n];
        String[] out = new String[gFrom.length];
        for (int i = 0; i < gFrom.length; i++) {
            int u = gFrom[i], v = gTo[i], w = gWeight[i];
            out[i] = (d1[u] + w + dn[v] == D || d1[v] + w + dn[u] == D) ? "YES" : "NO";
        }
        return out;
    }
    long[] dijkstra(List<long[]>[] adj, int n, int src) {
        long[] dist = new long[n + 1]; Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            if (cur[0] > dist[(int) cur[1]]) continue;
            for (long[] e : adj[(int) cur[1]]) {
                long nd = cur[0] + e[1];
                if (nd < dist[(int) e[0]]) { dist[(int) e[0]] = nd; pq.add(new long[]{nd, (int) e[0]}); }
            }
        }
        return dist;
    }
}

