            adj[gFrom[i]].push_back({gTo[i], gWeight[i]});
            adj[gTo[i]].push_back({gFrom[i], gWeight[i]});
        }
        auto d1 = dijkstra(adj, n, 1);
        auto dn = dijkstra(adj, n, n);
        long long D = d1[n];
        vector<string> out;
        for (int i = 0; i < (int)gFrom.size(); i++) {
            int u = gFrom[i], v = gTo[i], w = gWeight[i];
            out.push_back((d1[u] + w + dn[v] == D || d1[v] + w + dn[u] == D) ? "YES" : "NO");
