        return out;
    }
};

import java.util.*;

class Solution {
    public int maxNetworkingTime(int[] start, int[] finish, int k) {
        int n = start.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> start[a] - start[b]);
        int[] dur = new int[n];
        int T = 0;
        for (int i = 0; i < n; i++) { dur[i] = finish[order[i]] - start[order[i]]; T = Math.max(T, finish[i]); }
        int keep = n - k;
        if (keep <= 0) return T;
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + dur[i];
        int minSum = Integer.MAX_VALUE;
        for (int i = 0; i + keep <= n; i++) minSum = Math.min(minSum, pre[i + keep] - pre[i]);
        return T - minSum;
    }
}

