class Solution {
    public int maxMeetings(int[] firstDay, int[] lastDay) {
        int n = firstDay.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> lastDay[a] - lastDay[b]);
        int cnt = 0, prev = 0;
        for (int i : order) {
            int d = Math.max(prev + 1, firstDay[i]);
            if (d <= lastDay[i]) { cnt++; prev = d; }
        }
        return cnt;
    }
}

