            vector<long long> nxt(26, 0);
            for (int c = 0; c < 26; c++)
                for (int cp = max(0, c - d); cp <= min(25, c + d); cp++)
                    nxt[c] = (nxt[c] + dp[cp]) % MOD;
            dp = nxt;
        }
        long long s = 0;
        for (long long v : dp) s = (s + v) % MOD;
        return (int) s;
    }
};

