from bisect import bisect_left, bisect_right

def sum_of_cubes_of_beautiful_numbers(queries: List[List[int]]) -> List[int]:
    MOD = 998244353
    beautiful = []
    max_bits = 62
    for L in range(2, max_bits):
        for z in range(1, 4):
            if z > L - 1:
                continue
            for combo in combinations(range(L - 1), z):
                val = (1 << (L - 1))
                zeros = set(combo)
                for j in range(L - 1):
                    if j in zeros:
                        pass
                    else:
                        val |= 1 << (L - 2 - j)
                beautiful.append(val)
    beautiful = sorted(set(beautiful))
    prefix = [0]
    for v in beautiful:
        prefix.append((prefix[-1] + pow(v, 3, MOD)) % MOD)
    res = []
    for L, R in queries:
        lo = bisect_left(beautiful, L)
        hi = bisect_right(beautiful, R)
        res.append((prefix[hi] - prefix[lo]) % MOD)
    return res

import java.util.*;

class Solution {
    long[] sumOfCubesOfBeautifulNumbers(long[][] queries) {
        final long MOD = 998244353L;
        List<Long> beautiful = new ArrayList<>();
        for (int L = 2; L < 62; L++) {
            int[] positions = new int[L - 1];
            for (int z = 1; z <= 3 && z <= L - 1; z++) {
                int[] idx = new int[z];
                for (int i = 0; i < z; i++) idx[i] = i;
                while (true) {
                    long val = 1L << (L - 1);
                    Set<Integer> zeros = new HashSet<>();
                    for (int x : idx) zeros.add(x);
                    for (int j = 0; j < L - 1; j++)
                        if (!zeros.contains(j)) val |= 1L << (L - 2 - j);
                    beautiful.add(val);
                    int t = z - 1;
                    while (t >= 0 && idx[t] == (L - 1) - (z - t)) t--;
                    if (t < 0) break;
                    idx[t]++;
                    for (int k = t + 1; k < z; k++) idx[k] = idx[k - 1] + 1;
                }
            }
        }
        TreeSet<Long> uniq = new TreeSet<>(beautiful);
        long[] arr = uniq.stream().mapToLong(Long::longValue).toArray();
        long[] prefix = new long[arr.length + 1];
        for (int i = 0; i < arr.length; i++)
            prefix[i + 1] = (prefix[i] + modPow(arr[i], 3, MOD)) % MOD;
        long[] res = new long[queries.length];
        for (int q = 0; q < queries.length; q++) {
            int lo = lowerBound(arr, queries[q][0]);
            int hi = upperBound(arr, queries[q][1]);
            res[q] = (prefix[hi] - prefix[lo] + MOD) % MOD;
        }
        return res;
    }
    long modPow(long b, long e, long m) { long r = 1; b %= m; while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; } return r; }
    int lowerBound(long[] a, long v) { int lo = 0, hi = a.length; while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < v) lo = mid + 1; else hi = mid; } return lo; }
    int upperBound(long[] a, long v) { int lo = 0, hi = a.length; while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= v) lo = mid + 1; else hi = mid; } return lo; }
}

class Solution {
public:
    vector<long long> sumOfCubesOfBeautifulNumbers(vector<vector<long long>>& queries) {
        const long long MOD = 998244353LL;
        set<long long> uniq;
        for (int L = 2; L < 62; L++) {
            for (int z = 1; z <= 3 && z <= L - 1; z++) {
                vector<int> idx(z);
                iota(idx.begin(), idx.end(), 0);
                while (true) {
                    long long val = 1LL << (L - 1);
                    set<int> zeros(idx.begin(), idx.end());
                    for (int j = 0; j < L - 1; j++)
                        if (!zeros.count(j)) val |= 1LL << (L - 2 - j);
                    uniq.insert(val);
                    int t = z - 1;
                    while (t >= 0 && idx[t] == (L - 1) - (z - t)) t--;
                    if (t < 0) break;
                    idx[t]++;
                    for (int k = t + 1; k < z; k++) idx[k] = idx[k - 1] + 1;
                }
            }
        }
        vector<long long> arr(uniq.begin(), uniq.end());
        vector<long long> prefix(arr.size() + 1, 0);
        auto pw = [&](long long b, long long e) {
            long long r = 1; b %= MOD;
            while (e > 0) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
            return r;
        };
        for (size_t i = 0; i < arr.size(); ++i) prefix[i + 1] = (prefix[i] + pw(arr[i], 3)) % MOD;
        vector<long long> res;
        for (auto& q : queries) {
            int lo = lower_bound(arr.begin(), arr.end(), q[0]) - arr.begin();
            int hi = upper_bound(arr.begin(), arr.end(), q[1]) - arr.begin();
            res.push_back((prefix[hi] - prefix[lo] + MOD) % MOD);
        }
        return res;
    }
};

