class Solution {
    std::unordered_map<std::string, std::string> defs;
    std::unordered_map<std::string, int> cache;
    std::unordered_set<std::string> visiting;
    bool hasCycle = false;

    int evaluate(const std::string& expr) {
        std::vector<std::string> tokens;
        std::regex re("\\d+|[A-Za-z_][A-Za-z_0-9]*|[+\\-*/()]");
        for (auto it = std::sregex_iterator(expr.begin(), expr.end(), re); it != std::sregex_iterator(); ++it)
            tokens.push_back(it->str());
        std::unordered_map<std::string, int> prec{{"+", 1}, {"-", 1}, {"*", 2}, {"/", 2}};
        std::vector<std::string> out;
        std::stack<std::string> ops;
        for (auto& t : tokens) {
            if (isdigit(t[0]) || isalpha(t[0]) || t[0] == '_') out.push_back(t);
            else if (prec.count(t)) {
                while (!ops.empty() && prec.count(ops.top()) && prec[ops.top()] >= prec[t]) { out.push_back(ops.top()); ops.pop(); }
                ops.push(t);
            }
        }
        while (!ops.empty()) { out.push_back(ops.top()); ops.pop(); }
        std::stack<int> st;
        for (auto& t : out) {
            if (prec.count(t)) {
                int b = st.top(); st.pop();
                int a = st.top(); st.pop();
                if (t == "+") st.push(a + b);
                else if (t == "-") st.push(a - b);
                else if (t == "*") st.push(a * b);
                else st.push(a / b);
            } else if (isdigit(t[0])) st.push(std::stoi(t));
            else { st.push(resolve(t)); if (hasCycle) return 0; }
        }
        return st.top();
    }

    int resolve(const std::string& name) {
        if (hasCycle) return 0;
        auto it = cache.find(name);
        if (it != cache.end()) return it->second;
        if (visiting.count(name)) { hasCycle = true; return 0; }
        visiting.insert(name);
        int v = evaluate(defs[name]);
        visiting.erase(name);
        cache[name] = v;
        return v;
    }

public:
    std::vector<std::string> evaluateExpressionMap(std::vector<std::string>& definitions) {
        std::vector<std::string> order;
        for (auto& d : definitions) {
            auto eq = d.find('=');
            std::string name = d.substr(0, eq);
            defs[name] = d.substr(eq + 1);
            order.push_back(name);
        }
        std::vector<std::string> results;
        for (auto& name : order) {
            int v = resolve(name);
            if (hasCycle) return {"CYCLE"};
            results.push_back(name + "=" + std::to_string(v));
        }
        return results;
    }
};

from typing import List

def solveSpreadsheetFormulaEvaluator(input: str) -> List[str]:
    formulas: dict[str, list[str]] = {}  # label -> tokens
    out: List[str] = []

    def parse(expr: str) -> list[str]:
        return [t.strip() for t in expr.split("+") if t.strip()]

    def has_cycle(start: str, candidate: list[str]) -> bool:
        # DFS from start using candidate for start, existing formulas otherwise
        WHITE, GRAY, BLACK = 0, 1, 2
        color: dict[str, int] = {}

        def dfs(node: str) -> bool:
            if color.get(node, WHITE) == GRAY:
                return True
            if color.get(node, WHITE) == BLACK:
                return False
            color[node] = GRAY
            tokens = candidate if node == start else formulas.get(node, [])
            for tk in tokens:
                if not tk.isdigit():
                    if dfs(tk):
                        return True
            color[node] = BLACK
            return False

        return dfs(start)

    def evaluate(label: str) -> int | None:
        if label not in formulas:
            return None
        cache: dict[str, int | None] = {}

        def rec(node: str) -> int | None:
            if node in cache:
                return cache[node]
            if node not in formulas:
                cache[node] = None
                return None
            total = 0
            for tk in formulas[node]:
                if tk.isdigit():
                    total += int(tk)
                else:
                    v = rec(tk)
                    if v is None:
                        cache[node] = None
                        return None
                    total += v
            cache[node] = total
            return total

        return rec(label)

    for line in input.strip().split("\n"):
        parts = line.split(maxsplit=2)
        if parts[0] == "SET":
            label = parts[1]
            tokens = parse(parts[2])
            if has_cycle(label, tokens):
                out.append("ERROR")
            else:
                formulas[label] = tokens
                out.append("OK")
        else:
            v = evaluate(parts[1])
            out.append("ERROR" if v is None else str(v))
    return out

import java.util.*;

class Solution {
    private Map<String, List<String>> formulas = new HashMap<>();

    String[] solveSpreadsheetFormulaEvaluator(String input) {
        List<String> out = new ArrayList<>();
        for (String line : input.strip().split("\n")) {
            String[] parts = line.split(" ", 3);
            if (parts[0].equals("SET")) {
                String label = parts[1];
                List<String> tokens = parse(parts[2]);
                if (hasCycle(label, tokens)) out.add("ERROR");
                else { formulas.put(label, tokens); out.add("OK"); }
            } else {
                Integer v = evaluate(parts[1], new HashMap<>());
                out.add(v == null ? "ERROR" : String.valueOf(v));
            }
        }
        return out.toArray(new String[0]);
    }

    private List<String> parse(String expr) {
        List<String> res = new ArrayList<>();
        for (String t : expr.split("\\+")) {
            String s = t.trim();
            if (!s.isEmpty()) res.add(s);
        }
        return res;
    }

    private boolean hasCycle(String start, List<String> candidate) {
        Map<String, Integer> color = new HashMap<>();
        return dfsCycle(start, start, candidate, color);
    }

    private boolean dfsCycle(String node, String start, List<String> candidate, Map<String, Integer> color) {
        Integer c = color.getOrDefault(node, 0);
        if (c == 1) return true;
        if (c == 2) return false;
        color.put(node, 1);
        List<String> tokens = node.equals(start) ? candidate : formulas.getOrDefault(node, Collections.emptyList());
        for (String tk : tokens) {
            if (!tk.matches("\\d+")) {
                if (dfsCycle(tk, start, candidate, color)) return true;
            }
        }
        color.put(node, 2);
        return false;
    }

    private Integer evaluate(String label, Map<String, Integer> cache) {
        if (cache.containsKey(label)) return cache.get(label);
        if (!formulas.containsKey(label)) { cache.put(label, null); return null; }
        int total = 0;
        for (String tk : formulas.get(label)) {
            if (tk.matches("\\d+")) total += Integer.parseInt(tk);
            else {
                Integer v = evaluate(tk, cache);
                if (v == null) { cache.put(label, null); return null; }
                total += v;
            }
        }
        cache.put(label, total);
        return total;
    }
}

#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>
#include <optional>

class Solution {
    std::unordered_map<std::string, std::vector<std::string>> formulas;

    std::vector<std::string> parse(const std::string& expr) {
        std::vector<std::string> res;
        std::string cur;
        for (char c : expr) {
            if (c == '+') {
                if (!cur.empty()) { res.push_back(cur); cur.clear(); }
            } else if (!isspace((unsigned char) c)) cur.push_back(c);
        }
        if (!cur.empty()) res.push_back(cur);
        return res;
    }

    bool isNum(const std::string& s) {
        for (char c : s) if (!isdigit((unsigned char) c)) return false;
        return !s.empty();
    }

    bool dfsCycle(const std::string& node, const std::string& start, const std::vector<std::string>& cand, std::unordered_map<std::string, int>& color) {
        auto it = color.find(node);
        if (it != color.end()) { if (it->second == 1) return true; if (it->second == 2) return false; }
        color[node] = 1;
        const std::vector<std::string>& tokens = (node == start) ? cand : (formulas.count(node) ? formulas[node] : std::vector<std::string>{});
        for (auto& tk : tokens) {
            if (!isNum(tk)) {
                if (dfsCycle(tk, start, cand, color)) return true;
            }
        }
        color[node] = 2;
        return false;
    }

    bool hasCycle(const std::string& start, const std::vector<std::string>& cand) {
        std::unordered_map<std::string, int> color;
        return dfsCycle(start, start, cand, color);
    }

    std::optional<int> evaluate(const std::string& label, std::unordered_map<std::string, std::optional<int>>& cache) {
        auto it = cache.find(label);
        if (it != cache.end()) return it->second;
        auto fit = formulas.find(label);
        if (fit == formulas.end()) { cache[label] = std::nullopt; return std::nullopt; }
        int total = 0;
        for (auto& tk : fit->second) {
            if (isNum(tk)) total += std::stoi(tk);
            else {
                auto v = evaluate(tk, cache);
                if (!v) { cache[label] = std::nullopt; return std::nullopt; }
                total += *v;
            }
        }
        cache[label] = total;
        return total;
    }

public:
    std::vector<std::string> solveSpreadsheetFormulaEvaluator(std::string input) {
        std::vector<std::string> out;
        std::stringstream ss(input);
        std::string line;
        while (std::getline(ss, line)) {
            if (line.empty()) continue;
            std::stringstream ls(line);
            std::string cmd, label;
            ls >> cmd >> label;
            if (cmd == "SET") {
                std::string rest;
                std::getline(ls, rest);
                auto tokens = parse(rest);
                if (hasCycle(label, tokens)) out.push_back("ERROR");
                else { formulas[label] = tokens; out.push_back("OK"); }
            } else {
                std::unordered_map<std::string, std::optional<int>> cache;
                auto v = evaluate(label, cache);
                out.push_back(v ? std::to_string(*v) : "ERROR");
            }
        }
        return out;
    }
};

from typing import List

def markdown_header_chunks(markdown: str, max_chunk_size: int) -> List[str]:
    lines = markdown.split("\n") if markdown else []
    chunks: List[str] = []
    # active_headers: list of (level, line_text)
    active: list = []
    cur: list = []

    def flush():
        if cur:
            chunks.append(" | ".join(cur))

    def header_lines():
        return [h[1] for h in active]

    def start_new_chunk():
        nonlocal cur
        cur = list(header_lines())

    for line in lines:
        s = line.lstrip()
        is_header = s.startswith("#")
        if is_header:
            level = len(s) - len(s.lstrip("#"))
            while active and active[-1][0] >= level:
                active.pop()
            active.append((level, line))
            # if cur already had content and adding this header pushes past limit, start new chunk
            tentative = " | ".join(cur + [line])
            if cur and len(tentative) > max_chunk_size and any(c not in header_lines()[:-0] for c in cur):
                flush()
                start_new_chunk()
                cur.append(line) if line not in cur else None
            else:
                cur.append(line)
        else:
            tentative = " | ".join(cur + [line])
            if cur and len(tentative) > max_chunk_size:
                # decide if cur has any non-header content
                has_content = len(cur) > len(header_lines())
                if has_content:
                    flush()
                    start_new_chunk()
                cur.append(line)
            else:
                cur.append(line)
    flush()
    return chunks

import java.util.*;

class Solution {
    public List<String> markdownHeaderChunks(String markdown, int maxChunkSize) {
        List<String> out = new ArrayList<>();
        if (markdown == null || markdown.isEmpty()) return out;
        String[] lines = markdown.split("\n", -1);
        List<int[]> activeLevels = new ArrayList<>();
        List<String> activeText = new ArrayList<>();
        List<String> cur = new ArrayList<>();
        for (String line : lines) {
            String trimmed = line.replaceAll("^\\s+", "");
            boolean isHeader = trimmed.startsWith("#");
            if (isHeader) {
                int level = 0;
                while (level < trimmed.length() && trimmed.charAt(level) == '#') level++;
                while (!activeLevels.isEmpty() && activeLevels.get(activeLevels.size() - 1)[0] >= level) {
                    activeLevels.remove(activeLevels.size() - 1);
                    activeText.remove(activeText.size() - 1);
                }
                activeLevels.add(new int[]{level});
                activeText.add(line);
            }
            String tentative = String.join(" | ", cur) + (cur.isEmpty() ? "" : " | ") + line;
            boolean hasContent = cur.size() > activeText.size() - (isHeader ? 1 : 0);
            if (!cur.isEmpty() && tentative.length() > maxChunkSize && hasContent) {
                out.add(String.join(" | ", cur));
                cur = new ArrayList<>(activeText.subList(0, isHeader ? activeText.size() - 1 : activeText.size()));
            }
            cur.add(line);
        }
        if (!cur.isEmpty()) out.add(String.join(" | ", cur));
        return out;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<string> markdownHeaderChunks(string markdown, int maxChunkSize) {
        vector<string> out;
        if (markdown.empty()) return out;
        vector<string> lines;
        stringstream ss(markdown); string ln;
        while (getline(ss, ln, '\n')) lines.push_back(ln);
        vector<int> activeLevels;
        vector<string> activeText;
        vector<string> cur;
        auto join = [](const vector<string>& v) {
            string s; for (size_t i = 0; i < v.size(); i++) { if (i) s += " | "; s += v[i]; } return s;
        };
        for (auto& line : lines) {
            size_t p = 0; while (p < line.size() && isspace((unsigned char)line[p])) p++;
            bool isHeader = p < line.size() && line[p] == '#';
            if (isHeader) {
                int lvl = 0; while (p + lvl < line.size() && line[p + lvl] == '#') lvl++;
                while (!activeLevels.empty() && activeLevels.back() >= lvl) { activeLevels.pop_back(); activeText.pop_back(); }
                activeLevels.push_back(lvl); activeText.push_back(line);
            }
            string tent = cur.empty() ? line : join(cur) + " | " + line;
            int curContent = (int)cur.size() - ((int)activeText.size() - (isHeader ? 1 : 0));
            if (!cur.empty() && (int)tent.size() > maxChunkSize && curContent > 0) {
                out.push_back(join(cur));
                cur.assign(activeText.begin(), activeText.end() - (isHeader ? 1 : 0));
            }
            cur.push_back(line);
        }
        if (!cur.empty()) out.push_back(join(cur));
        return out;
    }
};

