class Solution {
    public int minProblemsToSolve(int[] points, int threshold) {
        int n = points.length;
        int i = 0, count = 1, mn = points[0], mx = points[0];
        while (mx - mn < threshold) {
            int nxt = (i + 2 < n) ? i + 2 : i + 1;
            if (nxt >= n) return n;
            i = nxt;
            mn = Math.min(mn, points[i]);
            mx = Math.max(mx, points[i]);
            count++;
        }
        return count;
    }
}

