from typing import List
from bisect import bisect_left

def chooseFlask(requirements: List[int], markings: List[List[int]]) -> int:
    flasks = {}
    for f, m in markings:
        flasks.setdefault(f, []).append(m)
    best_idx, best_waste = -1, float('inf')
    for idx in sorted(flasks.keys()):
        marks = flasks[idx]
        waste = 0
        ok = True
        for r in requirements:
            i = bisect_left(marks, r)
            if i == len(marks):
                ok = False
                break
            waste += marks[i] - r
        if ok and waste < best_waste:
            best_waste = waste
            best_idx = idx
    return best_idx

class Solution {
    int chooseFlask(int[] requirements, int[][] markings) {
        TreeMap<Integer, List<Integer>> flasks = new TreeMap<>();
        for (int[] m : markings) flasks.computeIfAbsent(m[0], k -> new ArrayList<>()).add(m[1]);
        int bestIdx = -1;
        long bestWaste = Long.MAX_VALUE;
        for (Map.Entry<Integer, List<Integer>> e : flasks.entrySet()) {
            List<Integer> marks = e.getValue();
            long waste = 0;
            boolean ok = true;
            for (int r : requirements) {
                int lo = 0, hi = marks.size();
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (marks.get(mid) < r) lo = mid + 1; else hi = mid;
                }
                if (lo == marks.size()) { ok = false; break; }
                waste += marks.get(lo) - r;
            }
            if (ok && waste < bestWaste) { bestWaste = waste; bestIdx = e.getKey(); }
        }
        return bestIdx;
    }
}

class Solution {
public:
    int chooseFlask(vector<int>& requirements, vector<vector<int>>& markings) {
        map<int, vector<int>> flasks;
        for (auto& m : markings) flasks[m[0]].push_back(m[1]);
        int bestIdx = -1;
        long long bestWaste = LLONG_MAX;
        for (auto& [idx, marks] : flasks) {
            long long waste = 0;
            bool ok = true;
            for (int r : requirements) {
                auto it = lower_bound(marks.begin(), marks.end(), r);
                if (it == marks.end()) { ok = false; break; }
                waste += *it - r;
            }
            if (ok && waste < bestWaste) { bestWaste = waste; bestIdx = idx; }
        }
        return bestIdx;
    }
};

def getFinalImage(image, rotation, vertical_flip, horizontal_flip):
    n = len(image)
    M = [row[:] for row in image]

    def rotate90(mat):
        return [[mat[n - 1 - j][i] for j in range(n)] for i in range(n)]

    for _ in range(rotation // 90):
        M = rotate90(M)
    if vertical_flip:
        M = M[::-1]
    if horizontal_flip:
        M = [row[::-1] for row in M]
    return M

class Solution {
    static int[][] getFinalImage(int[][] image, int rotation, int vFlip, int hFlip) {
        int n = image.length;
        int[][] M = new int[n][n];
        for (int i = 0; i < n; i++) M[i] = image[i].clone();
        for (int r = 0; r < rotation / 90; r++) {
            int[][] nx = new int[n][n];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) nx[i][j] = M[n - 1 - j][i];
            M = nx;
        }
        if (vFlip == 1) {
            for (int i = 0; i < n / 2; i++) {
                int[] t = M[i]; M[i] = M[n - 1 - i]; M[n - 1 - i] = t;
            }
        }
        if (hFlip == 1) {
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n / 2; j++) {
                    int t = M[i][j]; M[i][j] = M[i][n - 1 - j]; M[i][n - 1 - j] = t;
                }
        }
        return M;
    }
}

