            else if (c == '<') { cc = b - 1; while (cc >= 0 && black[a][cc]) cc--; if (cc < 0) { out.push_back({-1, -1}); continue; } }
            else if (c == 'v') { rr = a + 1; while (rr < h && black[rr][b]) rr++; if (rr == h) { out.push_back({-1, -1}); continue; } }
