class Solution {
    public int palindromicArrayTransformation(String[] arr) {
        int n = arr.length;
        if (n <= 1) return 1;
        for (int i = 0; i < n / 2; i++) {
            String a = arr[i], b = arr[n - 1 - i];
            if (a.length() != b.length()) return 0;
            StringBuilder rev = new StringBuilder(b).reverse();
            if (!a.contentEquals(rev)) return 0;
        }
        if (n % 2 == 1) {
            String m = arr[n / 2];
            if (!m.contentEquals(new StringBuilder(m).reverse())) return 0;
        }
        return 1;
    }
}

