    int palindromicArrayTransformation(vector<string>& arr) {
        int n = arr.size();
        if (n <= 1) return 1;
        for (int i = 0; i < n / 2; i++) {
            string& a = arr[i]; string b = arr[n - 1 - i];
            reverse(b.begin(), b.end());
            if (a != b) return 0;
        }
        if (n % 2 == 1) {
            string m = arr[n / 2];
            string r = m; reverse(r.begin(), r.end());
            if (m != r) return 0;
        }
        return 1;
    }
};

def sum_consecutive(digits: str) -> str:
    stack: list = []
    for c in digits:
        push = [c]
        while push:
            x = push.pop(0)
            if stack and stack[-1] == x:
                d = int(x)
                stack.pop()
                s = str(d + d)
                push = list(s) + push
            else:
                stack.append(x)
    return "".join(stack)

import java.util.*;

class Solution {
    public String sumConsecutiveIdenticalDigits(String digits) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : digits.toCharArray()) {
            Deque<Character> push = new ArrayDeque<>();
            push.add(c);
            while (!push.isEmpty()) {
                char x = push.poll();
                if (!stack.isEmpty() && stack.peek() == x) {
                    int d = x - '0';
                    stack.pop();
                    String s = String.valueOf(d + d);
                    Deque<Character> tmp = new ArrayDeque<>();
                    for (char ch : s.toCharArray()) tmp.add(ch);
                    while (!push.isEmpty()) tmp.add(push.poll());
                    push = tmp;
                } else {
                    stack.push(x);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = stack.descendingIterator();
        while (it.hasNext()) sb.append(it.next());
        return sb.toString();
    }
}

