import java.util.*;

class Solution {
    int meetingRoom(int N, int[] people, int[] starting, int[] ending) {
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (x, y) -> ending[x] - ending[y]);
        int[] s = new int[N], e = new int[N], p = new int[N];
        for (int i = 0; i < N; i++) {
            s[i] = starting[idx[i]];
            e[i] = ending[idx[i]];
            p[i] = people[idx[i]];
        }
        int[] dp = new int[N + 1];
        int total = 0;
        for (int v : people) total += v;
        for (int i = 1; i <= N; i++) {
            int lo = 0, hi = i - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (e[mid - 1] < s[i - 1]) lo = mid;
                else hi = mid - 1;
            }
            dp[i] = Math.max(dp[i - 1], dp[lo] + p[i - 1]);
        }
        return total - dp[N];
    }
}

