        sort(fish.begin(), fish.end(), greater<int>());
        sort(baits.begin(), baits.end(), greater<int>());
        int count = 0, i = 0;
        for (int b : baits) {
            int used = 0;
            while (i < (int) fish.size() && used < 3 && fish[i] > b) { i++; used++; count++; }
        }
        return count;
    }
};

