def coder_writing(records: List[str]) -> str:
    totals = {}
    for r in records:
        name, grade = r.split(":")
        name = name.strip(); g = int(grade.strip())
        s, c = totals.get(name, (0, 0))
        totals[name] = (s + g, c + 1)
    best_name = ""
    best_avg = -float("inf")
