from collections import Counter

def count_triple(sentence: str) -> int:
    cnt = 0
    for w in sentence.split():
        c = Counter(w.lower())
        if any(v >= 3 for v in c.values()):
            cnt += 1
    return cnt

class Solution {
    int countTriple(String sentence) {
        int cnt = 0;
        for (String w : sentence.split("\\s+")) {
            int[] c = new int[26];
            for (char ch : w.toLowerCase().toCharArray())
                if (ch >= 'a' && ch <= 'z') c[ch - 'a']++;
            for (int x : c) if (x >= 3) { cnt++; break; }
        }
        return cnt;
    }
}

class Solution {
public:
    int countTriple(string sentence) {
        int cnt = 0;
        string cur;
        for (char c : sentence + ' ') {
            if (c == ' ' || c == '\t' || c == '\n') {
                if (!cur.empty()) {
                    int f[26] = {0};
                    for (char x : cur) if (isalpha((unsigned char) x)) f[tolower(x) - 'a']++;
                    for (int v : f) if (v >= 3) { cnt++; break; }
                    cur.clear();
                }
            } else cur += c;
        }
        return cnt;
    }
};

