def cycle_shift(a: List[int]) -> int:
    def canonical(n):
        s = str(n)
        L = len(s)
        return min(s[i:] + s[:i] for i in range(L))
    cnt = Counter(canonical(x) for x in a)
    return sum(c * (c - 1) // 2 for c in cnt.values())

import java.util.*;

class Solution {
    long cycleShift(int[] a) {
        Map<String, Integer> cnt = new HashMap<>();
        for (int x : a) {
            String s = Integer.toString(x);
            String best = s;
            for (int i = 1; i < s.length(); i++) {
                String t = s.substring(i) + s.substring(0, i);
                if (t.compareTo(best) < 0) best = t;
            }
            cnt.merge(best, 1, Integer::sum);
        }
        long total = 0;
        for (int c : cnt.values()) total += (long) c * (c - 1) / 2;
        return total;
    }
}

