            string best = s;
            for (size_t i = 1; i < s.size(); i++) {
                string t = s.substr(i) + s.substr(0, i);
                if (t < best) best = t;
            }
            cnt[best]++;
        }
        long long total = 0;
        for (auto& [k, c] : cnt) total += (long long) c * (c - 1) / 2;
