from typing import List

def distribute_integers(numbers: List[int]) -> List[int]:
    first = [numbers[0]]
    second = [numbers[1]] if len(numbers) > 1 else []
    for i in range(2, len(numbers)):
        x = numbers[i]
        gt1 = sum(1 for v in first if v > x)
        gt2 = sum(1 for v in second if v > x)
        if gt1 > gt2:
            first.append(x)
        elif gt2 > gt1:
            second.append(x)
        elif len(first) < len(second):
            first.append(x)
        elif len(second) < len(first):
            second.append(x)
        else:
            first.append(x)
    return first + second

import java.util.*;

class Solution {
    int[] distributeIntegers(int[] numbers) {
        List<Integer> first = new ArrayList<>(), second = new ArrayList<>();
        first.add(numbers[0]);
        if (numbers.length > 1) second.add(numbers[1]);
        for (int i = 2; i < numbers.length; i++) {
            int x = numbers[i];
            int gt1 = 0, gt2 = 0;
            for (int v : first) if (v > x) gt1++;
            for (int v : second) if (v > x) gt2++;
            if (gt1 > gt2) first.add(x);
            else if (gt2 > gt1) second.add(x);
            else if (first.size() < second.size()) first.add(x);
            else if (second.size() < first.size()) second.add(x);
            else first.add(x);
        }
        int[] res = new int[first.size() + second.size()];
        int k = 0;
        for (int v : first) res[k++] = v;
        for (int v : second) res[k++] = v;
        return res;
    }
}

class Solution {
public:
    vector<int> distributeIntegers(vector<int>& numbers) {
        vector<int> first, second;
        first.push_back(numbers[0]);
        if (numbers.size() > 1) second.push_back(numbers[1]);
        for (size_t i = 2; i < numbers.size(); i++) {
            int x = numbers[i];
            int gt1 = 0, gt2 = 0;
            for (int v : first) if (v > x) gt1++;
            for (int v : second) if (v > x) gt2++;
            if (gt1 > gt2) first.push_back(x);
            else if (gt2 > gt1) second.push_back(x);
            else if (first.size() < second.size()) first.push_back(x);
            else if (second.size() < first.size()) second.push_back(x);
            else first.push_back(x);
        }
        vector<int> res = first;
        res.insert(res.end(), second.begin(), second.end());
        return res;
    }
};

