class Solution {
    int[] eventTime(int[] times) {
        int[] res = new int[times.length];
        Deque<Long> queueEnds = new ArrayDeque<>();
        long endTime = -1;
        for (int i = 0; i < times.length; i++) {
            long t = times[i];
            while (!queueEnds.isEmpty() && queueEnds.peekFirst() <= t) queueEnds.pollFirst();
            boolean inService = endTime > t;
            int qs = queueEnds.size();
            if (!inService && qs == 0) {
                endTime = t + 300;
                res[i] = (int) endTime;
            } else {
                if (qs > 10) res[i] = (int) t;
                else {
                    long start = Math.max(endTime, t);
                    long ne = start + 300;
                    queueEnds.addLast(ne);
                    endTime = ne;
                    res[i] = (int) ne;
                }
            }
        }
        return res;
    }
}

