def fantasy_card_duel(playerDeckA: List[int], playerDeckB: List[int]) -> int:
    a = sorted(playerDeckA, reverse=True)
    b = sorted(playerDeckB)
    rounds = min(len(a), len(b))
    score = 0
    for i in range(rounds):
        if a[i] > b[i]:
            score += a[i] + b[i]
    return score

