        cans = cansConsumed;
        children.assign(n, {});
        for (int i = 0; i < n; i++) if (manager[i] != -1) children[manager[i]].push_back(i);
        for (int i = 0; i < n; i++) if (manager[i] == -1) dfs(i);
        return best;
    }

private:
    pair<long long, int> dfs(int u) {
