        for (int c : children[u]) {
            auto [s, k] = dfs(c);
            sum += s; cnt += k;
        }
        long long teamSum = sum - cans[u];
        int teamCnt = cnt - 1;
        if (teamCnt >= 2) {
            double avg = (double) teamSum / teamCnt;
            if (avg > best) best = avg;
        }
