def min_turn_back(U, weight):
    turnbacks = 0
    prev = None
    for w in weight:
        if w > U:
            turnbacks += 1
            continue
        if prev is None:
            prev = w
        elif prev + w <= U:
            prev = w
        else:
            turnbacks += 1
            if w < prev:
                prev = w
    return turnbacks

class Solution {
