        int turnbacks = 0;
        long prev = -1;
        for (int w : weight) {
            if (w > U) { turnbacks++; continue; }
            if (prev < 0) { prev = w; }
            else if (prev + w <= U) { prev = w; }
            else {
                turnbacks++;
                if (w < prev) prev = w;
            }
        }
        return turnbacks;
    }
}

