def count_divisible_permutations(n: int) -> int:
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        i = bin(mask).count('1') + 1  # next position 1-indexed
        if i > n:
            continue
        for v in range(1, n + 1):
            if mask & (1 << (v - 1)):
                continue
            if i % v == 0 or v % i == 0:
                dp[mask | (1 << (v - 1))] += dp[mask]
    return dp[(1 << n) - 1]

class Solution {
    public long countDivisiblePermutations(int n) {
        long[] dp = new long[1 << n];
        dp[0] = 1;
        for (int mask = 0; mask < (1 << n); mask++) {
            int i = Integer.bitCount(mask) + 1;
            if (i > n) continue;
            for (int v = 1; v <= n; v++) {
                if ((mask & (1 << (v - 1))) != 0) continue;
                if (i % v == 0 || v % i == 0) dp[mask | (1 << (v - 1))] += dp[mask];
            }
        }
        return dp[(1 << n) - 1];
    }
}

