class Solution {
    public long robHouses(int n, int y, int x, int[] a) {
        long[][] dp = new long[y + 1][x];
        dp[0][0] = 1;
        for (int d : a) {
            for (int j = Math.min(y, a.length); j >= 1; j--) {
                for (int r = 0; r < x; r++) {
                    int pr = ((r - d) % x + x) % x;
                    dp[j][r] += dp[j - 1][pr];
                }
            }
        }
        long base = dp[y][0];
        return y >= 1 ? base * 2 : base;
    }
}

