def extract_cards(cards: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(cards)
    pos = [0] * (n + 1)
    for i, x in enumerate(cards):
        pos[x] = i
    best_k = 1
    cur = 1
    for v in range(2, n + 1):
        if pos[v] > pos[v - 1]:
            cur += 1
        else:
            break
    best_k = cur
    extra = 1
    for v in range(2, n + 1):
        if pos[v] > pos[v - 1]:
            extra += 1
        else:
            break
    total = n * (n + 1) // 2
    free = best_k * (best_k + 1) // 2
    return (total - free) % MOD

class Solution {
    int extractCards(int[] cards) {
        final int MOD = 1_000_000_007;
        int n = cards.length;
        int[] pos = new int[n + 1];
        for (int i = 0; i < n; i++) pos[cards[i]] = i;
        int bestK = 1, cur = 1;
        for (int v = 2; v <= n; v++) {
            if (pos[v] > pos[v - 1]) cur++;
            else break;
        }
        bestK = cur;
        long total = (long) n * (n + 1) / 2;
        long free_ = (long) bestK * (bestK + 1) / 2;
        return (int) ((total - free_) % MOD);
    }
}

