        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> arr[a] - arr[b]);
        int[] target = new int[n];
        for (int k = 0; k < n / 2; k++) {
            target[2 * k] = arr[idx[k]];
            target[2 * k + 1] = arr[idx[n - 1 - k]];
