        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || arr[i] == target[i]) { visited[i] = true; continue; }
            int j = i, cycleLen = 0;
            while (!visited[j]) { visited[j] = true; j = pos.get(arr[j]); cycleLen++; }
            swaps += cycleLen - 1;
        }
        return swaps;
    }
}

class Solution {
public:
    int minimumSwapsForMaximumScore(vector<int>& arr) {
        int n = arr.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) { return arr[a] < arr[b]; });
        vector<int> target(n);
        for (int k = 0; k < n / 2; k++) {
            target[2 * k] = arr[idx[k]];
            target[2 * k + 1] = arr[idx[n - 1 - k]];
        }
        unordered_map<int, int> pos;
        for (int i = 0; i < n; i++) pos[target[i]] = i;
        vector<bool> visited(n, false);
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || arr[i] == target[i]) { visited[i] = true; continue; }
            int j = i, cycleLen = 0;
            while (!visited[j]) { visited[j] = true; j = pos[arr[j]]; cycleLen++; }
            swaps += cycleLen - 1;
        }
        return swaps;
    }
};

