                if (height[l] >= lmax) lmax = height[l]; else ans += lmax - height[l];
                l++;
            } else {
                if (height[r] >= rmax) rmax = height[r]; else ans += rmax - height[r];
                r--;
            }
        }
        return ans;
    }
}

