def prison(n: int, m: int, h: List[int], v: List[int]) -> int:
    def longest_run(arr):
        arr = sorted(arr)
        cur = best = 1
        for i in range(1, len(arr)):
            if arr[i] - arr[i - 1] == 1:
                cur += 1
                if cur > best: best = cur
            else:
                cur = 1
        return best
    mh = longest_run(h)
    mv = longest_run(v)
    return (mh + 1) * (mv + 1)

class Solution {
    int prison(int n, int m, int[] h, int[] v) {
        return (longestRun(h) + 1) * (longestRun(v) + 1);
    }

    private int longestRun(int[] arr) {
        int[] a = arr.clone();
        Arrays.sort(a);
        int cur = 1, best = 1;
        for (int i = 1; i < a.length; i++) {
            if (a[i] - a[i - 1] == 1) { cur++; best = Math.max(best, cur); }
            else cur = 1;
        }
        return best;
    }
}

