        sort(arr.begin(), arr.end());
        int cur = 1, best = 1;
        for (size_t i = 1; i < arr.size(); i++) {
            if (arr[i] - arr[i - 1] == 1) { cur++; best = max(best, cur); }
            else cur = 1;
        }
        return best;
    }
};

