    static int[] solution(int[] forest, int bird) {
        int[] f = forest.clone();
        int n = f.length, dir = 1, nest = 0;
        List<Integer> out = new ArrayList<>();
        while (nest < 100) {
            int i = bird + dir;
            while (i >= 0 && i < n && f[i] == 0) i += dir;
            if (i < 0 || i >= n) break;
            out.add(i);
            nest += f[i];
            f[i] = 0;
            dir = -dir;
        }
        int[] arr = new int[out.size()];
        for (int k = 0; k < arr.length; k++) arr[k] = out.get(k);
        return arr;
    }
}

