def solution(matrix):
    n = len(matrix)
    center = n // 2
    Y = set()
    for i in range(n):
        for j in range(n):
            if (i <= center and (j == i or j == n - 1 - i)) or (i > center and j == center):
                Y.add((i, j))
    bg = {(i, j) for i in range(n) for j in range(n)} - Y
    best = float('inf')
    for ys in range(3):
        for bs in range(3):
            if ys == bs:
                continue
            cost = sum(1 for (i, j) in Y if matrix[i][j] != ys) \
                 + sum(1 for (i, j) in bg if matrix[i][j] != bs)
            best = min(best, cost)
    return best

class Solution {
    static int solution(int[][] m) {
        int n = m.length, center = n / 2;
        boolean[][] isY = new boolean[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if ((i <= center && (j == i || j == n - 1 - i)) || (i > center && j == center))
                    isY[i][j] = true;
        int best = Integer.MAX_VALUE;
        for (int y = 0; y < 3; y++) {
            for (int bg = 0; bg < 3; bg++) {
                if (y == bg) continue;
                int cost = 0;
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        if (isY[i][j] ? m[i][j] != y : m[i][j] != bg) cost++;
                best = Math.min(best, cost);
            }
        }
        return best;
    }
}

