def countIntegerSequences(N: int, M: int, X: int) -> int:
    # bit length needed
    L = max(M, X).bit_length()
    sz = 1 << L
    dp = [0] * sz
    dp[0] = 1
    for _ in range(N - 1):
        ndp = [0] * sz
        for x in range(sz):
            if dp[x] == 0:
                continue
            for v in range(M + 1):
                ndp[x ^ v] = (ndp[x ^ v] + dp[x]) % MOD
        dp = ndp
    ans = 0
    for x in range(sz):
        last = X ^ x
        if 0 <= last <= M:
            ans = (ans + dp[x]) % MOD
    return ans if N >= 1 else (1 if X == 0 else 0)

class Solution {
    static final int MOD = 998244353;

    int countIntegerSequences(int N, int M, int X) {
        int L = Math.max(32 - Integer.numberOfLeadingZeros(Math.max(M, X)), 1);
        int sz = 1 << L;
        long[] dp = new long[sz];
        dp[0] = 1;
        for (int step = 0; step < N - 1; step++) {
            long[] ndp = new long[sz];
            for (int x = 0; x < sz; x++) {
                if (dp[x] == 0) continue;
                for (int v = 0; v <= M; v++) {
                    ndp[x ^ v] = (ndp[x ^ v] + dp[x]) % MOD;
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int x = 0; x < sz; x++) {
            int last = X ^ x;
            if (last >= 0 && last <= M) ans = (ans + dp[x]) % MOD;
        }
        return (int) ans;
    }
}

