def makeNumbersEqual(A: int, B: int) -> int:
    cost = 0
    while A and B:
        if A < B:
            A, B = B, A
        cost += A // B
        A %= B
        if A == 0:
            cost -= 1
            break
    return cost

class Solution {
    long makeNumbersEqual(long A, long B) {
        long cost = 0;
        while (A > 0 && B > 0) {
            if (A < B) { long t = A; A = B; B = t; }
            cost += A / B;
            A %= B;
            if (A == 0) { cost--; break; }
        }
        return cost;
    }
}

class Solution {
public:
    long long makeNumbersEqual(long long A, long long B) {
        long long cost = 0;
        while (A > 0 && B > 0) {
            if (A < B) swap(A, B);
            cost += A / B;
            A %= B;
            if (A == 0) { cost--; break; }
        }
        return cost;
    }
};

