class Solution {
    int[] arrangeCoins(int[] coins) {
        int[] res = new int[coins.length];
        for (int i = 0; i < coins.length; i++) {
            long n = coins[i];
            long k = (long) ((Math.sqrt(8.0 * n + 1) - 1) / 2);
            while ((k + 1) * (k + 2) / 2 <= n) k++;
