def daysSinceLastLogin(lastLoginDate: str) -> str:
    if lastLoginDate is None or lastLoginDate.strip() == "":
        return "E8430"
    if not re.fullmatch(r"\d{2}/\d{2}/\d{4}", lastLoginDate):
        return "E9021"
    try:
