def get_string_to_remove(S: str, X: str) -> str:
    n, m = len(S), len(X)
    if m > n:
        return "-1"
    for i in range(m, -1, -1):
        if S[:i] == X[:i] and S[n - (m - i):] == X[i:]:
            removed = S[i: n - (m - i)]
            if removed:
                return removed
    return "-1"

class Solution {
    String getStringToRemove(String S, String X) {
        int n = S.length(), m = X.length();
        if (m > n) return "-1";
        for (int i = m; i >= 0; i--) {
            if (S.substring(0, i).equals(X.substring(0, i))
                && S.substring(n - (m - i)).equals(X.substring(i))) {
                String removed = S.substring(i, n - (m - i));
                if (!removed.isEmpty()) return removed;
            }
        }
        return "-1";
    }
}

class Solution {
public:
    string getStringToRemove(string S, string X) {
        int n = S.size(), m = X.size();
        if (m > n) return "-1";
        for (int i = m; i >= 0; --i) {
            if (S.substr(0, i) == X.substr(0, i)
                && S.substr(n - (m - i)) == X.substr(i)) {
                string removed = S.substr(i, n - (m - i) - i);
                if (!removed.empty()) return removed;
            }
        }
        return "-1";
    }
};

import java.util.*;

class Solution {
    static final long MOD = 1_000_000_007L;
    public int buildMonuments(int monumentTypes, int totalCities, int[] routeStart, int[] routeEnd) {
        Map<Integer, List<Integer>> g = new HashMap<>();
        for (int i = 0; i < routeStart.length; i++) {
            g.computeIfAbsent(routeStart[i], k -> new ArrayList<>()).add(routeEnd[i]);
            g.computeIfAbsent(routeEnd[i], k -> new ArrayList<>()).add(routeStart[i]);
        }
        long ans = monumentTypes;
        Set<Integer> visited = new HashSet<>(); visited.add(1);
        Map<Integer, Integer> parent = new HashMap<>(), grand = new HashMap<>();
        Map<Integer, Integer> sibDone = new HashMap<>();
        parent.put(1, 0);
        Deque<Integer> q = new ArrayDeque<>(); q.add(1);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.getOrDefault(u, Collections.emptyList())) {
                if (visited.add(v)) {
                    parent.put(v, u);
                    grand.put(v, parent.get(u));
                    int forbid = 1 + (grand.get(v) != 0 ? 1 : 0) + sibDone.getOrDefault(u, 0);
                    int choices = Math.max(0, monumentTypes - forbid);
                    ans = ans * choices % MOD;
                    sibDone.merge(u, 1, Integer::sum);
                    q.add(v);
                }
            }
        }
        return (int) ans;
    }
}

