import java.util.*;

class Solution {
    public int[] exclusiveTime(int n, List<String> logs) {
        int[] out = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        int prev = 0;
        for (String log : logs) {
            String[] p = log.split(":");
            int fid = Integer.parseInt(p[0]), t = Integer.parseInt(p[2]);
            if ("start".equals(p[1])) {
                if (!stack.isEmpty()) out[stack.peek()] += t - prev;
                stack.push(fid);
                prev = t;
            } else {
                out[stack.pop()] += t - prev + 1;
                prev = t + 1;
            }
        }
        return out;
    }
}

