class Solution {
public:
    vector<int> exclusiveTime(int n, vector<string>& logs) {
        vector<int> out(n, 0);
        vector<int> stack;
        int prev = 0;
        for (auto& log : logs) {
            int p1 = log.find(':'), p2 = log.find(':', p1 + 1);
            int fid = stoi(log.substr(0, p1));
            string ev = log.substr(p1 + 1, p2 - p1 - 1);
            int t = stoi(log.substr(p2 + 1));
            if (ev == "start") {
                if (!stack.empty()) out[stack.back()] += t - prev;
                stack.push_back(fid);
                prev = t;
            } else {
                out[stack.back()] += t - prev + 1;
                stack.pop_back();
                prev = t + 1;
            }
        }
        return out;
    }
};

