        String[] arr = messages.clone();
        Arrays.sort(arr, (a, b) -> {
            String[] pa = a.split(":"), pb = b.split(":");
            int dp = Integer.parseInt(pa[1]) - Integer.parseInt(pb[1]);
            return dp != 0 ? dp : Integer.parseInt(pa[0]) - Integer.parseInt(pb[0]);
        });
        return arr;
    }
