def minimum_extra_chocolates(A: int, B: int) -> int:
    best = float('inf')
    for k in range(1, 2 * (max(A, B) // min(A, B) + 2) + 5):
        if k * A >= B:
            cost = k * A - B
        else:
            need = B - k * A
            X = (need + k - 1) // k
            Y = k * (A + X) - B
            cost = X + Y
        best = min(best, cost)
    return best

class Solution {
    public long minimumExtraChocolates(int A, int B) {
        long best = Long.MAX_VALUE;
        for (long k = 1; k <= (long)(B / A + 4) * 2; k++) {
            long cost;
            if (k * A >= B) cost = k * A - B;
            else {
                long need = B - k * A;
                long X = (need + k - 1) / k;
                long Y = k * (A + X) - B;
                cost = X + Y;
            }
            best = Math.min(best, cost);
        }
        return best;
    }
}

