def most_unique_part2(group: List[str], use_jaccard: bool) -> str:
    if use_jaccard:
        avgs = []
        for i, s in enumerate(group):
            other = [group[j] for j in range(len(group)) if j != i]
            if other:
                avgs.append(sum(jaccard(s, o) for o in other) / len(other))
            else:
                avgs.append(0)
        best = min(avgs)
        chosen_idx = [i for i, v in enumerate(avgs) if v == best]
    else:
        props = []
        for s in group:
            c = Counter(s)
            mx = max(c.values()) if c else 0
            props.append(mx / len(s) if s else 1)
        best = min(props)
        chosen_idx = [i for i, v in enumerate(props) if v == best]
    chosen_chars = Counter()
    other_chars = set()
    for i, s in enumerate(group):
        if i in chosen_idx:
            for c in s: chosen_chars[c] += 1
        else:
            other_chars.update(s)
    out = []
    for i in chosen_idx:
        for c in group[i]:
            if c not in other_chars:
                out.append(c)
    return "".join(out)

import java.util.*;

class Solution {
    public double jaccard(String s1, String s2) {
        Map<Character, Integer> a = new HashMap<>(), b = new HashMap<>();
        for (char c : s1.toCharArray()) a.merge(c, 1, Integer::sum);
        for (char c : s2.toCharArray()) b.merge(c, 1, Integer::sum);
        int inter = 0, union = 0;
        Set<Character> keys = new HashSet<>(a.keySet());
        keys.addAll(b.keySet());
        for (char k : keys) {
            int va = a.getOrDefault(k, 0), vb = b.getOrDefault(k, 0);
            inter += Math.min(va, vb);
            union += Math.max(va, vb);
        }
        return union > 0 ? (double) inter / union : 0;
    }
}

