    public String mostUniqueElements(String[] group) {
        double[] props = new double[group.length];
        for (int i = 0; i < group.length; i++) {
            Map<Character, Integer> c = new HashMap<>();
            for (char ch : group[i].toCharArray()) c.merge(ch, 1, Integer::sum);
            int mx = 0;
            for (int v : c.values()) mx = Math.max(mx, v);
            props[i] = group[i].isEmpty() ? 1 : (double) mx / group[i].length();
        }
        double best = Double.MAX_VALUE;
        for (double p : props) best = Math.min(best, p);
        Set<Integer> chosen = new HashSet<>();
        for (int i = 0; i < props.length; i++) if (props[i] == best) chosen.add(i);
        Set<Character> otherChars = new HashSet<>();
        for (int i = 0; i < group.length; i++) if (!chosen.contains(i)) for (char c : group[i].toCharArray()) otherChars.add(c);
        StringBuilder sb = new StringBuilder();
        for (int i : chosen) for (char c : group[i].toCharArray()) if (!otherChars.contains(c)) sb.append(c);
        return sb.toString();
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string mostUniqueElements(vector<string>& group) {
        vector<double> props(group.size());
        for (int i = 0; i < (int)group.size(); i++) {
            map<char, int> c;
            for (char ch : group[i]) c[ch]++;
            int mx = 0;
            for (auto& [k, v] : c) mx = max(mx, v);
            props[i] = group[i].empty() ? 1.0 : (double) mx / group[i].size();
        }
        double best = *min_element(props.begin(), props.end());
        set<int> chosen;
        for (int i = 0; i < (int)props.size(); i++) if (props[i] == best) chosen.insert(i);
        set<char> otherChars;
        for (int i = 0; i < (int)group.size(); i++) if (!chosen.count(i)) for (char c : group[i]) otherChars.insert(c);
        string out;
        for (int i : chosen) for (char c : group[i]) if (!otherChars.count(c)) out += c;
        return out;
    }
};
